// Fahrschul Assistent - Fragenkatalog Klasse B (Stand 01.04.2025, Quelle: fuehrerschein-bestehen.de)
// Generiert mit tools/build-from-fsb.mjs aus data/_source/fsb-current.jsonl
window.FS_QUESTIONS = [{"n":"1.1.01-001","t":"Was versteht man unter defensivem Fahren?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Vorsorglich an jeder Kreuzung anhalten","Nicht auf dem eigenen Recht bestehen","Mit Fehlern anderer rechnen"],"co":[1,2],"ex":["An jeder Kreuzung anzuhalten, behindert den fließenden Verkehr und führt eventuell auch zu riskanten Überholvorgängen der nachfolgenden Fahrer. Eine Erhöhung der Verkehrssicherheit wird damit nicht erreicht.","Denn defensives Fahren bedeutet auch, bei Bedarf im Interesse der allgemeinen Verkehrssicherheit auf die eigene Vorfahrt zu verzichten.","Unsicherheiten und Fehleinschätzung anderer Verkehrsteilnehmer sind durchaus möglich. Durch vorausschauendes Fahren können Unfälle vermieden werden."],"rn":1},{"n":"1.1.01-002","t":"Was kann zu Auffahrunfällen führen?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Zu dichtes Auffahren","Unaufmerksamkeit","Unerwartet starkes Bremsen"],"co":[0,1,2],"ex":["Vorausschauend Fahren bedeutet, Abstand zu halten, da die Fahrweise des Vordermanns nicht vorhersehbar ist. Plötzliches Bremsen durch diesen kann hier schnell zu Auffahrunfällen führen, wenn der Abstand nicht eingehalten wird. Es gilt: Je höher die Geschwindigkeit, desto größer der Abstand!","Volle Konzentration, stetige Aufmerksamkeit und schnelles Reaktionsvermögen sind das wichtigste im Straßenverkehr. Wenn du einen Moment unaufmerksam bist (z.B. nebenher einen neuen Sender im Radio einstellst), wirkt sich das auf dein Reaktionsvermögen aus, da du den vorausfahrenden Verkehr kurzzeitig nicht beobachten kannst.","Du musst immer davon ausgehen, dass dein Hintermann eine verzögerte Reaktionszeit hat. Wenn du unerwartet stark bremst, kann dieser unter Umständen nicht mehr schnell genug abbremsen."],"rn":2},{"n":"1.1.01-003","t":"Welches Verhalten ist beispielhaft für „Vorausschauendes Fahren“?","p":2,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Ich reagiere möglichst frühzeitig auf wahrscheinliche Veränderungen der Verkehrssituation","Ich versuche, die Absichten anderer Verkehrsteilnehmer möglichst frühzeitig zu erkennen","Ich beschränke die Verkehrsbeobachtung möglichst auf das direkt vor mir fahrende Fahrzeug"],"co":[0,1],"ex":["So verminderst du das Risiko für Staus und Unfälle.","Hierdurch verminderst du das Risiko für gefährliche Verkehrssituationen.","Du solltest deine Verkehrsbeobachtung möglichst auf den gesamten Verkehr um dich herum ausweiten, um so frühzeitig reagieren und risikohaftes Fahrverhalten vermeiden zu können."],"rn":3},{"n":"1.1.01-004","t":"Sie sollen ein Ihnen unbekanntes Kraftfahrzeug fahren. Warum müssen Sie dabei zunächst besonders vorsichtig sein?","p":3,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["- in der Anordnung und der Funktion der Bedienelemente","- im Lenkverhalten","- im Bremsverhalten"],"co":[0,1,2],"ex":["Möglicherweise gibt es bestimmte Besonderheiten der Bedienelemente, die sich von denen der Fahrzeuge, die du davor bereits gefahren bist, unterscheiden. Ein Beispiel hierfür wäre der Umstieg von Schaltung auf Automatik. Nehme dir ausreichend Zeit, dich mit diesen Neuerungen auseinanderzusetzen, bevor du losfährst.","Die Lenkräder unterschiedlicher Kraftfahrzeuge können sehr unterschiedlich sensibel in ihrer Lenkreaktion sein.","Bremsen können von Fahrzeug zu Fahrzeug sehr unterschiedlich sein. Bei manchen musst du das Bremspedal nur leicht berühren und es bremst bereits sehr stark ab, bei anderen musst du das Bremspedal sehr weit durchdrücken, bis du eine erste Bremsreaktion spürst. Um hierfür ein Gefühl zu bekommen, solltest du -in einer verkehrsarmen Straße oder einer Grundstückseinfahrt- anfangs mehrmals anfahren und abbremsen. Das hilft zusätzlich, ein besseres Gespür für den Schleifpunkt zu bekommen."],"rn":4},{"n":"1.1.01-101","t":"Sie fahren innerorts hinter einem Fahrzeug mit ortsfremdem Kennzeichen. Was könnte geschehen?","p":3,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["- betätigt den Blinker vor dem Abbiegen zu spät","- bremst unerwartet","- hält unerwartet an, um nach dem Weg zu fragen"],"co":[0,1,2],"ex":["Auch dies ist ein mögliches Szenario, das sich darauf zurückführen lässt, dass der Fahrer sich nicht auskennt.","Der Fahrer ist möglicherweise nicht ortskundig und fährt den Weg vielleicht mit Navigationssystem oder nach einer Beschreibung. So kann beim späten Erkennen einer Straße plötzliches Abbremsen erfolgen. Daher soll ausreichend Abstand gehalten werden.","Daher vorausschauend Fahren und ausreichend Abstand halten."],"rn":5},{"n":"1.1.01-102","t":"Was sind vermeidbare Behinderungen im fließenden Verkehr?","p":3,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Langsamfahren ohne triftigen Grund","Liegenbleiben wegen Kraftstoffmangels","Abwürgen des Motors"],"co":[0,1,2],"ex":["Dies stört den Verkehrsfluss, hält andere Verkehrsteilnehmer auf und ist eine vermeidbare Behinderung. Natürlich sind auch langsam fahrende Traktoren oder LKWs u.U. eine Behinderung. Diese sind jedoch nicht in der Lage, schneller zu fahren.","Der Kraftstoffvorrat ist an der Tankuhr abzulesen. Leuchtet die Reservetankleuchte auf, dann gilt die Daumenregel: Du kannst noch circa 50 Kilometer mit dieser Tankfüllung fahren. Allerdings sollte dies nie bis auf ein Maximum ausgereizt werden, da sonst Schäden am Motor entstehen können. Also: rechtzeitig tanken und Motor und Nerven schonen.","Dies kann bei aufmerksamem Fahren und ausreichender Übung ohne Weiteres vermieden werden."],"rn":6},{"n":"1.1.01-103","t":"Warum darf man nicht unnötig langsam fahren?","p":3,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Weil Nachfolgende zu gefährlichem Überholen verleitet werden","Weil der Verkehrsfluss behindert wird","Weil die Gefahr von Auffahrunfällen erhöht wird"],"co":[0,1,2],"ex":["Besonders auf einspurigen Fahrbahnen wie Landstraßen ist zu langsames Fahren ein gefährdender Faktor für den Verkehrsfluss. Andere Fahrer fühlen sich, um die vorgegebene Geschwindigkeit einzuhalten, möglicherweise zum Überholen motiviert und tun dies eventuell auch an unübersichtlichen und kurvigen Stellen und gefährden somit deine als auch die Sicherheit anderer Personen im Straßenverkehr.","So kann stockender Verkehr entstehen und du kannst zur Verkehrsbehinderung für andere Autofahrer werden.","Fährt der Hintermann nach Richtgeschwindigkeit und erkennt zu spät, dass diese vom vorausfahrenden Fahrzeug nicht eingehalten wird, dann ist er möglicherweise nicht mehr in der Lage, rechtzeitig abzubremsen."],"rn":7},{"n":"1.1.01-107","t":"Welche Anzeichen warnen während der Fahrt vor aufkommender Müdigkeit?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Häufiges Gähnen","Schwere Augenlider","Verkürzte Reaktionszeit"],"co":[0,1],"ex":["Häufiges Gähnen ist ein Anzeichen, dass man müde ist. Daher sollte eine längere Pause eingelegt oder ein Fahrerwechsel durchgeführt werden.","Werden deine Augenlider schwer, dann musst du unbedingt eine Pause einlegen oder jemand anderen weiterfahren lassen. Hier sollte man frühzeitig reagieren, um die Gefahr für Sekundenschlaf zu vermeiden.","Eine verkürzte Reaktionszeit steht für hohe Aufmerksamkeit und Wachsamkeit, also das Gegenteil von Müdigkeit."],"rn":8},{"n":"1.1.01-108","t":"Welche Folgen kann die Missachtung von Müdigkeitsanzeichen nach sich ziehen?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Konzentrationsmangel","Fahrfehler","Sekundenschlaf"],"co":[0,1,2],"ex":["Je müder man ist, desto schlechter kann man sich konzentrieren. Hohe Konzentration ist im Straßenverkehr notwendig, um sicher zu fahren.","Ist man müde, dann können leichter Fahrfehler passieren, als wenn man ausgeschlafen und konzentriert ist. Um so etwas zu vermeiden, sollte eine Pause eingelegt werden.","Sekundenschlaf bezeichnet ungewolltes Einschlafen, das ein paar Sekunden andauern kann. Passiert Sekundenschlaf während der Fahrt, dann kann das lebensgefährlich sein."],"rn":9},{"n":"1.1.01-109","t":"Was ist zu tun, wenn Sie während der Fahrt Anzeichen von Müdigkeit spüren?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Anregende Musik hören","Unverzüglich eine Pause einlegen","Sich an frischer Luft bewegen"],"co":[1,2],"ex":["Anregende Musik ist eine zusätzliche Belastung für den Körper, wenn er ohnehin bereits müde ist. Du solltest lieber an eine Pause einplanen und dir die Beine vertreten.","Um wieder aufmerksam und wachsam im Straßenverkehr zu sein, sollte man bei Anzeichen von Müdigkeit eine Pause einlegen.","Bewegung und Sauerstoff wirken Müdigkeit entgegen."],"rn":10},{"n":"1.1.01-110","t":"Wie wirkt sich Müdigkeit beim Fahren aus?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Verzögerte Reaktionen","Eingeschränkte Wahrnehmung","Nachlassende Aufmerksamkeit"],"co":[0,1,2],"ex":["Wenn man müde bist, verlängert sich die Reaktionszeit. Das kann zu Risikosituationen im Straßenverkehr führen.","Müdigkeit schränkt die Aufnahme, Weiterleitung und Verarbeitung der Sinnesreize ein. Somit ist auch die Wahrnehmung vermindert.","Müdigkeit wirkt sich negativ auf die Aufmerksamkeit eines Menschen aus. Das kann eine verlängerte Reaktionszeit mit sich bringen. Daher sollte beim Autofahren unbedingt eine Pause eingelegt werden, sobald Müdigkeit festgestellt wird."],"rn":11},{"n":"1.1.01-112","t":"Was kann zum Abkommen von der Fahrbahn führen?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Ablenkung","Müdigkeit","Unaufmerksamkeit"],"co":[0,1,2],"ex":["Ein Fahrer sollte unter keinen Umständen von einer konzentrierten, vorausschauenden und aufmerksamen Fahrweise abgelenkt werden.","Bei Müdigkeit sollte unbedingt eine Pause eingelegt, oder, falls möglich, ein Fahrerwechsel getätigt werden.","Unaufmerksames Verhalten verzögert die Reaktionszeit. Das kann im schlimmsten Fall dazu führen, dass man von der Fahrbahn abkommt. Vor allem ein Handy verleitet zu unaufmerksamem Verhalten bei der Fahrt. Daher dieses am besten lautlos stellen und verräumen, damit es dich nicht stören kann."],"rn":12},{"n":"1.1.01-113","t":"Was führt häufig zu schweren Unfällen?","p":4,"c":"1.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Ein Fahren mit zu geringem Abstand","Eine mangelhafte Beobachtung des Verkehrs","Eine unangepasste Geschwindigkeit"],"co":[0,1,2],"ex":["Ausreichender Abstand ist notwendig, um bei plötzlichem Abbremsen des Vordermanns einen ausreichenden Reaktions- und Bremsweg zu haben und somit Auffahrunfälle zu vermeiden.","Du solltest den Verkehr möglichst umfassend beobachten, um Veränderungen im Verkehrsgeschehen frühzeitig erkennen und darauf reagieren zu können.","Die Geschwindigkeit sollte immer an das Verkehrsaufkommen und den Verkehrsfluss angepasst sein. So können Risikosituationen vermieden werden."],"rn":13},{"n":"1.1.02-005","t":"Mit welchem Verhalten von Kindern müssen Sie an Zebrastreifen rechnen?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Sie kehren ohne erkennbaren Grund auf dem Zebrastreifen um und laufen zurück","Sie schätzen Geschwindigkeit und Entfernung herannahender Fahrzeuge immer richtig ein und warten am Fahrbahnrand","Sie laufen auf den Zebrastreifen, ohne auf den Verkehr zu achten"],"co":[0,2],"ex":["Das Verhalten von Kindern kann schwer vorhergesagt werden. Zudem haben sie eine andere Gefahrenwahrnehmung als Erwachsene.","Hiervon kann man nicht einmal bei erwachsenen Personen ausgehen, die Erfahrung im Straßenverkehr besitzen. Daher kann dieser Verhalten auch nicht von Kindern erwartet werden, deren Wahrnehmungsfokus sich auf andere Dinge konzentriert, als das angepasste und aufmerksame Verhalten im Straßenverkehr.","Ist ein Zebrastreifen in Sicht, sollte generell erhöhte Aufmerksamkeit auf Fußgänger gelegt werden, vor allem, wenn Kinder in der Nähe sind. Von Kindern kann kein vorausschauendes Verhalten im Straßenverkehr erwartet werden."],"rn":14},{"n":"1.1.02-022","t":"Womit ist zu rechnen, wenn Kinder an einer Ampel warten?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["- auch bei Rot loslaufen, weil es ihnen zu lange dauert","- schon losrennen, wenn die Ampel in meiner Fahrtrichtung von Grün auf Gelb umschaltet","- sich gegenseitig auf die Fahrbahn schubsen"],"co":[0,1,2],"ex":["Kinder können oft die Gefahr Ihres Handelns und die Situation nicht richtig einschätzen. Daher musst du als Autofahrer damit rechnen, dass Kinder die Straße überqueren, obwohl die Ampel für sie noch auf Rot geschaltet ist, da sie möglicherweise zu ungeduldig sind, zu warten.","Kinder lernen erst nach und nach sich im Verkehr richtig zu verhalten. Sie nehmen Ihre Umgebung anders wahr, als Erwachsene und können Gefahrensituationen noch nicht so gut einschätzen.","Erst im Alter von 8 Jahren sind Kinder in der Lage, Gefahrensituationen wahrzunehmen und einzuschätzen. Allerdings kann man in jedem Kindesalter davon ausgehen, dass bei einer Spielerei einer der Beteiligten auf die Straße geschubst wird. Daher gilt: Aufmerksames und vorausschauendes Fahren."],"rn":15},{"n":"1.1.02-027","t":"Womit müssen Sie rechnen, wenn ältere Personen mit Gehhilfe die Fahrbahn überqueren?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Dass sie auf der Fahrbahn stehen bleiben","Dass sie die Fahrbahn langsam überqueren","Dass sie auf der Fahrbahn umkehren"],"co":[0,1,2],"ex":["Wenn ältere Leute eine Gehhilfe besitzen, hat dies den Grund, dass ihnen das Gehen schwer fällt. Daher ist es möglich, dass sie auf der Fahrbahn stehenbleiben, um eine kurze Pause einzulegen.","Es ist sogar sehr wahrscheinlich, dass ältere Menschen, die zusätzlich eine Gehhilfe benötigen, die Fahrbahn langsam überqueren und dabei mehr Zeit benötigen, als andere Fußgänger.","Fußgänger können generell aus den unterschiedlichsten Gründen dazu motiviert sein, plötzlich Kehrt zu machen, während sie eine Fahrbahn überqueren. Darauf sollte man immer gefasst sein."],"rn":16},{"n":"1.1.02-028","t":"Trotz vorhandenen Gehweges auf der rechten Straßenseite fährt eine Person im Rollstuhl auf der Straße. Wie verhalten Sie sich?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Ich überhole mit großem Seitenabstand, weil ich mit Ausweichbewegungen rechnen muss","Ich fahre so lange hinterher, bis ich überholen kann","Ich mache die Person durch Hupen darauf aufmerksam, dass sie sich falsch verhält"],"co":[0,1],"ex":["Ist ein sicheres Überholen möglich, dann darf mit ausreichendem seitlichen Abstand zum Rollstuhlfahrer überholt werden.","§3 (2a) der StVO besagt, dass Fahrer sich gegenüber Hilfsbedürftigen, Kindern und älteren Menschen besonders vorsichtig verhalten müssen. Folglich solltest du so lange hinter dem Rollstuhlfahrer herfahren, bis ein sicheres Überholen möglich ist.","Zwar wäre es sinnvoller, wenn der Rollstuhlfahrer auf dem Gehweg fahren würde, das gestattet es dir allerdings nicht, zu hupen. Möglicherweise hatte der Rollstuhlfahrer keine Möglichkeit, eigenständig auf den Gehweg zu gelangen. Das Hupen wäre in diesem Fall rechtswidrig."],"rn":17},{"n":"1.1.02-029","t":"Eine Person im Rollstuhl schafft es nach dem Überqueren der Straße nicht, mit dem Rollstuhl den Bordstein zu überwinden, um den Gehweg zu erreichen. Wie verhalten Sie sich?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Ich steige aus und helfe der Person im Rollstuhl","Ich hupe und fahre um die Person herum","Ich halte und schalte die Warnblinkanlage ein"],"co":[0,2],"ex":["Laut §3 (2a) StVO musst du dich \"(...) gegenüber Kindern, Hilfsbedürftigen und älteren Menschen, insbesondere durch Verminderung der Fahrgeschwindigkeit und durch Bremsbereitschaft, so verhalten, dass eine Gefährdung dieser Verkehrsteilnehmer ausgeschlossen ist.\" Der Rollstuhlfahrer, der ohne Hilfe nicht auf den Gehweg gelangt, ist ein Hilfsbedürftiger, der deine Hilfe benötigt.","Hupen und Vorbeifahren bringt den Rollstuhlfahrer nicht aus der Gefahrensituation und ist ihm keinerlei Hilfe.","Durch das Einschalten des Warnblinklichtes signalisierst du anderen Verkehrsteilnehmern, dass hier erhöhte Wachsamkeit geboten ist. Dann hilfst du dem Rollstuhlfahrer, das Hindernis zu überwinden."],"rn":18},{"n":"1.1.02-032","t":"Bei welcher Person müssen Sie mit einer schweren Sehbehinderung rechnen?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Dem Mann","Dem Kind","Der Frau"],"co":[0],"ex":["Der Mann führt einen weißen Stock bei sich und trägt eine gelbe Armbinde mit drei schwarzen Punkten darauf. Dieser weist daraufhin, dass der Mann sehbehindert oder blind ist.","Das Kind zeigt keine sichtbaren Kennzeichen für eine Sehbehinderung mit sich.","Die Frau führt weder einen weißen Stock, einen Führhund, noch eine gelbe Armbinde mit drei schwarzen Punkten mit sich. Sie hat somit keine von außen ersichtlichen Kennzeichen für eine Sehbehinderung."],"i":["https://video4.kalaiwa.de/assets/1102032.webp"],"rn":19},{"n":"1.1.02-052","t":"Warum müssen Sie damit rechnen, dass Kinder sich im Straßenverkehr unvorhersehbar verhalten?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["- die Verkehrssituation häufig nur unvollständig überblicken können","- leicht ablenkbar sind","- oft nicht zuordnen können, aus welcher Richtung ein Geräusch kommt"],"co":[0,1,2],"ex":["Für erwachsene Personen ist in vielen Situationen klar, was als Nächstes im Straßenverkehr passieren wird. Kinder hingegen haben oft weniger Erfahrung und handeln deshalb anders, als du es von Erwachsenen erwartest. Die geringere Körpergröße von Kindern schränkt ihren Überblick zusätzlich ein.","Kinder sind oft neugierig und haben einen ausgeprägten Spieltrieb. Sie können von ihrer Umgebung abgelenkt werden und plötzlich auf die Straße laufen, um etwas zu erkunden oder einem Spielzeug hinterherzulaufen, ohne auf den Verkehr zu achten. Darauf musst du gefasst sein.","Akustische Reize wie Fahrzeuggeräusche und Hupen dienen dazu, Gefahren zu signalisieren und den Verkehrsfluss zu regeln. Kinder lernen möglicherweise noch, diese Reize zu interpretieren und angemessen darauf zu reagieren."],"rn":20},{"n":"1.1.02-116","t":"Die Straßenbahn ist an der Haltestelle gerade zum Stehen gekommen. Welches Verhalten ist richtig?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["- dürfen nicht gefährdet werden","- dürfen nicht behindert werden","- dürfen mit der Hupe gewarnt werden"],"co":[0,1],"ex":["Du musst dich so verhalten, dass ein- und aussteigende Fahrgäste nicht gefährdet werden. Das heißt, Geschwindigkeit vermindern und bremsbereit sein.","Die ein- und aussteigenden Fahrgäste haben Vorrang. Du musst gegebenenfalls abbremsen oder anhalten, um diese ungehindert passieren zu lassen.","Es ist verboten, die Fahrgäste mit der Hupe zu warnen. Du darfst sie nicht behindern."],"i":["https://video2.kalaiwa.de/assets/1102116.webp"],"rn":21},{"n":"1.1.02-119","t":"Wie sollten Sie sich verhalten?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Bremsbereit bleiben","Unverändert weiterfahren","Auf Schrittgeschwindigkeit abbremsen"],"co":[0,2],"ex":["Es kann passieren, dass das Kind auf dem Bobbycar die Straße überqueren will. Für diesen Fall musst du in Schrittgeschwindigkeit fahren und bremsbereit sein.","Du darfst unter keinen Umständen die Sicherheit des Kindes gefährden.","Um das Kind auf dem Bobbycar nicht zu gefährden, musst du auf Schrittgeschwindigkeit abbremsen und bremsbereit sein."],"i":["https://video2.kalaiwa.de/assets/1102119.webp"],"rn":22},{"n":"1.1.02-122","t":"Mit welchem Verhalten müssen Sie an solchen Haltestellen rechnen?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Fußgänger verlassen die Haltestelleninsel unachtsam","Fußgänger rennen über die Fahrbahn zur Haltestelleninsel","Fußgänger warten, bis die Fahrbahn frei ist"],"co":[0,1],"ex":["Hier musst du Schrittgeschwindigkeit fahren und bremsbereit sein, um keine Fußgänger zu gefährden.","Fußgänger könnten ungeachtet des Verkehrs über die Fahrbahn rennen, um die Straßenbahn noch zu erreichen. Halte dich für diesen Fall bremsbereit und reduziere auf Schrittgeschwindigkeit.","Das wäre ein wünschenswertes Verhalten, wovon du aber nicht ausgehen kannst."],"i":["https://video2.kalaiwa.de/assets/1102122.webp"],"rn":23},{"n":"1.1.02-126","t":"Warum sind ältere Fußgänger im Verkehr mehr gefährdet als jüngere?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Sie schätzen die Geschwindigkeit von Fahrzeugen oft falsch ein","Sie sehen und hören oft schlechter","Sie reagieren oft langsamer und sind weniger beweglich"],"co":[0,1,2],"ex":["Werden Fahrzeuge langsamer eingeschätzt, als sie sind, so kann das zu gefährlichen Situationen, vor allem für ältere Verkehrsteilnehmer, führen.","Dadurch sind ihre Reaktionen verzögerter. Deshalb müssen andere Verkehrsteilnehmer besonders auf sie Acht geben.","So können hier in unübersichtlichen Verkehrslagen eher gefährliche Situationen entstehen, als für jüngere Verkehrsteilnehmer."],"rn":24},{"n":"1.1.02-128","t":"Mit welchem Verhalten muss bei Personen am Fußgängerüberweg gerechnet werden?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Sie blicken weder nach links noch nach rechts","Sie betreten unerwartet die Fahrbahn","Sie kehren manchmal auf halbem Wege um"],"co":[0,1,2],"ex":["Da Personen an Fußgängerüberwegen Vorrang haben, kann es sein, dass sie deshalb nicht auf den Verkehr achten und einfach die Straße überqueren.","Deswegen solltest du langsam und aufmerksam fahren und dich bremsbereit halten.","Deswegen solltest du erst wieder anfahren, sobald der Fußgänger die Straße vollständig überquert hat."],"rn":25},{"n":"1.1.02-129","t":"Ein Fußgänger mit einem weißen Stock möchte vor Ihnen die Fahrbahn überqueren. Wie müssen Sie sich verhalten?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["- die Geschwindigkeit vermindern und nötigenfalls anhalten","- mit gleichbleibender Geschwindigkeit weiterfahren","- Warnzeichen geben"],"co":[0],"ex":["Ein weißer Stock ist, neben einem Blindenhund und einer gelben Armbinde mit drei schwarzen Punkten, ein Anzeichen dafür, dass die Person sehbehindert oder blind ist. Du musst hier die Geschwindigkeit reduzieren und bei Bedarf halten, um diesen Fußgänger nicht zu gefährden.","So riskierst du, den sehbehinderten oder blinden Fußgänger zu gefährden. Reduziere deine Geschwindigkeit und halte bei Bedarf an, damit er sicher die Fahrbahn überqueren kann.","Zum einen darfst du keine Warnzeichen geben, zum anderen wäre das sehr unangebracht, da der Fußgänger wahrscheinlich sehbehindert oder blind ist."],"rn":26},{"n":"1.1.02-131","t":"Womit müssen Sie rechnen?","p":3,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Dass Fahrzeugtüren geöffnet werden","Dass Fahrzeuge anfahren","Dass Fußgänger plötzlich auf die Fahrbahn treten"],"co":[0,1,2],"ex":["Auf beiden Seiten der Straße parken einige Fahrzeuge. Aus diesen könnten Personen aussteigen.","Wie im Falle des Fahrzeugs vor den beiden Radfahrern ist es wahrscheinlich, dass Fahrzeuge aus Parklücken herausfahren.","Vor dem links haltenden Fahrzeug steht ein Fußgänger. Es ist möglich, dass er die Fahrbahn überqueren möchte."],"i":["https://video4.kalaiwa.de/assets/1102131.webp"],"rn":27},{"n":"1.1.02-132","t":"Wie schätzen Sie die Situation ein?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Ich kann unvermindert weiterfahren","Die Fußgängerin kann unachtsam die Fahrbahn betreten","Der Fußgänger mit dem Mofa kann plötzlich die Richtung ändern"],"co":[1,2],"ex":["Dann würdest du die anderen Verkehrsteilnehmer gefährden.","Um auf diesen Situation vorbereitet zu sein, solltest du Schrittgeschwindigkeit fahren und bremsbereit sein.","In diesem Fall müsstest du die Geschwindigkeit reduzieren und bei Bedarf anhalten."],"i":["https://video2.kalaiwa.de/assets/1102132.webp"],"rn":28},{"n":"1.1.02-133","t":"Eine Person am Straßenrand trägt eine gelbe Armbinde mit drei schwarzen Punkten. Worauf weist diese Armbinde hin?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Auf die Zugehörigkeit zu einer Berufsgruppe","Auf eine besondere Verhaltenspflicht gegenüber dieser Person","Auf eine behinderte Person"],"co":[1,2],"ex":["Die gelbe Armbinde mit drei schwarzen Punkten ist kein Hinweis auf die Zugehörigkeit zu einer Berufsgruppe. Sie weist darauf hin, dass die Person eine Behinderung hat.","Da diese Person behindert ist, kann es sein, dass sie in bestimmten Verkehrssituationen Hilfe von anderen Personen braucht oder mehr Zeit benötigt, als andere Verkehrsteilnehmer. Verhalte dich aufmerksam, hilfsbereit und vorausschauend, um behinderten Personen die Teilnahme am Straßenverkehr zu erleichtern.","Die gelbe Armbinde mit drei schwarzen Punkten signalisiert den anderen Verkehrsteilnehmern, dass diese Person behindert ist."],"rn":29},{"n":"1.1.02-135","t":"Womit müssen Sie rechnen, wenn Fußgänger die Fahrbahn überqueren?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["- unachtsam sein","- auf halbem Wege umkehren","- plötzlich stehen bleiben"],"co":[0,1,2],"ex":["Deswegen musst du langsam und bremsbereit fahren, um sie nicht zu gefährden.","Für diesen Fall musst du vorbereitet sein. Das wird durch vorausschauendes Fahren ermöglicht.","Für diesen Fall musst du in Bremsbereitschaft sein."],"rn":30},{"n":"1.1.02-039-M","t":"Wie verhalten Sie sich?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Kinder beobachten","Mit unveränderter Geschwindigkeit weiterfahren","Bremsbereit sein"],"co":[0,2],"ex":["Die Kinder befinden sich nah am Straßenrand. Deswegen solltest du die Geschwindigkeit reduzieren, um rechtzeitig bremsen zu können, falls sie auf die Straße laufen.","Mit unveränderter Geschwindigkeit weiterzufahren, würde ein großes Risiko für die Kinder bedeuten, falls sie plötzlich auf die Straße laufen.","Es kann passieren, dass die Kinder in jedem Moment auf die Straße laufen. Deswegen solltest du dich in Bremsbereitschaft halten."],"i":["https://video4.kalaiwa.de/assets/1102039m.webp"],"rn":31},{"n":"1.1.02-041-M","t":"Mit welchen Gefahren müssen Sie rechnen?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Einzelne Kinder kehren wieder um","Alle Kinder warten auf dem Gehweg","Die Kinder verlassen die Fahrbahn nicht rechtzeitig"],"co":[0,2],"ex":["Kinder können Gefahrensituationen nicht so gut einschätzen, wie Erwachsene. Daher ist es möglich, dass eines der Kinder plötzlich umkehrt und wieder auf die Straße rennt.","Am Gehweg zu warten wäre verkehrsgerechtes Verhalten. Davon kann man bei Kindern allerdings nicht ausgehen. Daher solltest du hier sehr langsam fahren und bremsbereit sein.","Es sieht zwar so aus, als ob die Kinder dabei sind, die Fahrbahn zu verlassen. Es könnte allerdings eine unvorhergesehene Situation entstehen, die dazu führt, dass du bremsen musst. So könnte zum Beispiel der Ball auf die Straße rollen. Fahre mit reduzierter Geschwindigkeit weiter und halte dich bremsbereit."],"i":["https://video2.kalaiwa.de/assets/1102041m.webp"],"rn":32},{"n":"1.1.02-042-M","t":"Wie sollten Sie sich verhalten?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Unvermindert weiterfahren","Auf Schrittgeschwindigkeit abbremsen","Bremsbereit bleiben"],"co":[1,2],"ex":["Du musst dich so verhalten, dass du die Kinder durch deine Fahrweise nicht gefährdest.","Reduziere deine Fahrgeschwindigkeit auf Schritttempo, um die Sicherheit der Kinder nicht zu gefährden.","Die Kinder könnten auf die Straße laufen. Für diesen Fall musst du bremsbereit sein."],"i":["https://video4.kalaiwa.de/assets/1102042m.webp"],"rn":33},{"n":"1.1.02-043-M","t":"Wie müssen Sie sich verhalten?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Mit unverminderter Geschwindigkeit vorbeifahren","Bremsbereit bleiben","Sofort auf Schrittgeschwindigkeit abbremsen"],"co":[1,2],"ex":["Du musst dich im Straßenverkehr so verhalten, dass du niemanden gefährdest. In diesem Fall bedeutet das: Bremsbereit und in Schritttempo fahren, da Kinder auf die Straße laufen könnten.","Laut StVO musst du dich gegenüber Kindern vor allem durch Verminderung der Fahrgeschwindigkeit und durch Bremsbereitschaft, so verhalten, dass du sie nicht gefährdest.","Auf der Straße liegt ein Ball. Das deutet auf spielende Kinder in der Nähe hin. Daher musst du hier auf Schrittgeschwindigkeit abbremsen, um die Kinder nicht zu gefährden."],"i":["https://video2.kalaiwa.de/assets/1102043m.webp"],"rn":34},{"n":"1.1.02-048-M","t":"Wie sollten Sie sich jetzt verhalten?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Ich überhole den Radfahrer","Ich bremse auf Schrittgeschwindigkeit ab","Ich bleibe bremsbereit"],"co":[1,2],"ex":["Ein Überholmanöver könnte den Radfahrer sowie die Fußgänger in Gefahr bringen. Vermutlich wird der Radfahrer in wenigen Sekunden nach links ausscheren, um an dem grünen Pkw vorbeizufahren. Das Weiterfahren mit unverminderter Geschwindigkeit könnte zudem die Fußgänger gefährden, die die Straße überqueren wollen.","Fahr langsam an die Situation heran, da der Radfahrer vor dir ausscheren könnte, um den grünen Pkw zu überholen. Es könnten auch die Fußgänger auf der rechten und auf der linken Seite auf die Fahrbahn laufen, ohne auf den Verkehr zu achten.","Sowohl der Radfahrer als auch die Fußgänger könnten sich innerhalb von wenigen Sekunden vor dir auf der Fahrbahn befinden. Darum muss du bremsbereit bleiben."],"i":["https://video2.kalaiwa.de/assets/1102048m.webp"],"rn":35},{"n":"1.1.02-050-M","t":"Warum müssen Sie hier langsam und bremsbereit fahren?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Weil die Verkehrssituation unübersichtlich ist","Weil sich ein Kind auf der Fahrbahn befindet","Weil der weiße Transporter anfährt"],"co":[0,1],"ex":["Links und rechts vor dir stehen Fahrzeuge, die die Sicht auf mögliche Fußgänger einschränken. Von der Tankstelle staut sich der Verkehr auf die Straße zurück und es befinden sich Kinder in deiner unmittelbaren Umgebung. Deswegen musst du hier langsam und bremsbereit fahren.","Hinter dem links parkenden Transporter ist ein Kind dabei, die Straße zu überqueren. Daher musst du langsam und bremsbereit fahren, um es nicht zu gefährden.","Der weiße Transporter fährt nicht an. Die Gründe, weshalb langsames und bremsbereites Fahren notwendig ist, sind die unübersichtliche Verkehrssituation und das Kind, das sich auf der Fahrbahn befindet."],"v":["https://video4.kalaiwa.de/assets/1102050mv1440.mp4"],"rn":36},{"n":"1.1.02-051-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Ich halte an und lasse die Person die Straße überqueren","Ich signalisiere der Person durch Betätigung der Lichthupe, dass ich warte","Ich fahre mit ausreichendem Abstand links an der Person vorbei"],"co":[0],"ex":["Da die blinde Person das heranfahrende Auto nicht sehen kann, solltest du anhalten und sie vorbei gehen lassen. Du kannst dich auch nicht darauf verlassen, dass der Blinde dich hört oder dass der Blindenhund richtig handelt und stehen bleibt.","Die Betätigung der Lichthupe ist in diesem Fall nicht sinnvoll, da die blinde Person das Signal nicht wahrnehmen kann. Zu warten, ist aber die richtige Entscheidung.","Es genügt nicht, mit ausreichendem Abstand an der blinden Person vorbeizufahren, denn sie ist kurz davor, die Straße zu betreten und wird weiterlaufen. In dem Fall kannst du keinen ausreichenden Abstand zur Person einhalten und würdest sie zusätzlich sehr verunsichern."],"i":["https://video4.kalaiwa.de/assets/1102051m.webp"],"rn":37},{"n":"1.1.02-108-B","t":"Was müssen Sie in dieser Situation beachten?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["- in keinem Fall vorbeifahren","- nur mit Schrittgeschwindigkeit vorbeifahren","- nur vorbeifahren, wenn eine Gefährdung von Fahrgästen ausgeschlossen ist"],"co":[1,2],"ex":["Ein normales Vorbeifahren ist in diesem Fall verboten. Du solltest abbremsen, mit Schrittgeschwindigkeit am Bus vorbeifahren und bremsbereit bleiben, bis du den Bus passiert hast.","Fahrgäste dürfen weder gefährdet, noch behindert werden. Sie könnten spontan die Straße überqueren und auf deine Fahrbahn laufen. Daher musst du mit Schrittgeschwindigkeit vorbei fahren, auch wenn du dich auf der anderen Fahrbahnseite befindest.","Die Gefährdung von Fahrgästen muss immer ausgeschlossen sein. Daher solltest du die Schrittgeschwindigkeit einhalten und bremsbereit sein, falls ein Fahrgast spontan auf die Straße läuft. Dann musst du warten und den Fahrgast vorbeilassen."],"i":["https://video2.kalaiwa.de/assets/1102108b.webp"],"rn":38},{"n":"1.1.02-121-M","t":"Wie müssen Sie sich verhalten?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Weiterfahren, weil sich Personen nur am linken Fahrbahnrand befinden","Weiterfahren, weil ausreichend Zeit ist, bis die Personen meine Fahrbahnseite erreicht haben","Anhalten, um den Personen das Überqueren der Fahrbahn zu ermöglichen"],"co":[2],"ex":["Du musst vor dem Zebrastreifen anhalten und die Fußgänger diesen passieren lassen. Es ist egal, auf welcher Seite der Fahrbahn sie sich befinden.","Sobald Fußgänger an einem Zebrastreifen stehen, musst du anhalten und sie diesen überqueren lassen.","Am Zebrastreifen musst du halten, wenn dort Fußgänger stehen."],"i":["https://video4.kalaiwa.de/assets/1102121m.webp"],"rn":39},{"n":"1.1.02-123-M","t":"Sie wollen rechts abbiegen. Worauf müssen Sie sich einstellen?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Der Lkw wird anhalten","Nach dem Abbiegen des Lkws könnten Fußgänger von der gegenüberliegenden Straßenseite kommen","Der Fußgänger könnte den Lkw vorbeilassen und dann vor mir die Fahrbahn überqueren"],"co":[0,1,2],"ex":["Der LKW blinkt nach rechts. Da sich am Straßenrand ein Fußgänger befindet, ist es wahrscheinlich, dass der LKW anhält, um diesen die Straße überqueren zu lassen.","In diesem Fall musst du anhalten und sie die Straße überqueren lassen.","Das ist ebenfalls ein mögliches Szenario, auf das du dich einstellen solltest."],"i":["https://video2.kalaiwa.de/assets/1102123m.webp"],"rn":40},{"n":"1.1.02-124-M","t":"Worauf müssen Sie sich einstellen?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Auf Sichtbehinderungen","Auf querende Personen","Auf sich öffnende Fahrzeugtüren"],"co":[0,1,2],"ex":["Aufgrund der beidseitig parkenden Autos ist die Sicht eingeschränkt. Fahre daher besonders aufmerksam und vorsichtig.","Links von dir setzt eine Frau zum überqueren der Straße an. Generell sind viele Fußgänger auf den Gehwegen und auf der Straße unterwegs. Reduziere hier auf Schrittgeschwindigkeit und halte dich bremsbereit.","Da in der Straße viele Autos parken, ist es wahrscheinlich, dass Personen Fahrzeugtüren öffnen, um aus diesen auszusteigen."],"i":["https://video4.kalaiwa.de/assets/1102124m.webp"],"rn":41},{"n":"1.1.02-125-M","t":"Womit sollten Sie rechnen?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Dass Kinder zwischen den Fahrzeugen auftauchen können","Dass starkes Bremsen erforderlich werden kann","Dass Erwachsene auf die Fahrbahn treten können"],"co":[0,1,2],"ex":["Am rechten Straßenrand ist ein Verkehrszeichen aufgestellt, welches „Achtung, Kinder!“ bedeutet. In dieser Straße ist es sehr wahrscheinlich, dass sich hier Kinder auf der Straße befinden oder darüber laufen können. Daher musst du auf Schrittgeschwindigkeit reduzieren und in Bremsbereitschaft sein.","Es können jederzeit Fußgänger oder spielende Kinder auf die Fahrbahn treten. Daher musst du bremsbereit sein.","Aufgrund der beidseitig parkenden Autos ist die Sicht auf Fußgänger eingeschränkt. Fahre deswegen vorsichtig und langsam."],"i":["https://video4.kalaiwa.de/assets/1102125m.webp"],"rn":42},{"n":"1.1.02-130-M","t":"Womit müssen Sie rechnen?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Dass Kinder plötzlich zwischen den Fahrzeugen auftauchen","Dass vor mir Fußgänger auf die Fahrbahn treten","Dass Fußgänger warten werden, bis ich vorbeigefahren bin"],"co":[0,1],"ex":["Das Verkehrszeichen am rechten Fahrbahnrand signalisiert \"Vorsicht Kinder!\". Es ist wahrscheinlich, dass hier Kinder auf die Straße laufen. Daher musst du hier sehr langsam fahren und in Bremsbereitschaft sein.","Aufgrund der beidseitig parkenden Autos ist die Sicht auf Fußgänger, die vom Gehweg auf die Straße treten könnten, eingeschränkt. Fahre hier deswegen besonders aufmerksam und vorsichtig.","Das wäre wünschenswert, davon kann aber nicht ausgegangen werden."],"i":["https://video2.kalaiwa.de/assets/1102130m.webp"],"rn":43},{"n":"1.1.02-136-M","t":"Warum müssen Sie jetzt langsam und bremsbereit fahren?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Weil der Bus anfährt","Wegen des Fußgängers","Wegen der Radfahrerin"],"co":[1],"ex":["Der Bus hält noch, damit die Fahrgäste ein- und aussteigen können. Außerdem fährt er nicht an, da direkt vor ihm ein Fußgänger steht, der die Straße überqueren möchte.","Du solltest jetzt langsam und bremsbereit fahren, da vor dem angehaltenen Bus gerade ein Fußgänger die Straße überquert.","Außer dem Fußgänger, der die Straße überqueren will, gibt es keine weiteren Verkehrsteilnehmer, auf die du gerade besondere Rücksicht nehmen musst."],"v":["https://video2.kalaiwa.de/assets/1102136mv1440.mp4"],"rn":44},{"n":"1.1.02-137-M","t":"Warum müssen Sie hier bremsen?","p":5,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["- Radfahrers","- grünen Fahrzeugs","- Kindes"],"co":[2],"ex":["Wegen des Radfahrers musst du nicht bremsen, da er noch weit entfernt ist und auf der anderen Fahrspur fährt.","Wegen des grünen Fahrzeugs musst du nicht bremsen, da es auf der anderen Fahrspur fährt.","Du musst hier bremsen, da ein Kind vermutlich gleich von rechts über die Straße rennen wird. Das Kind ist durch den parkenden Kastenwagen nur schwer zu erkennen. Du kannst nicht davon ausgehen, dass das Kind selbst auf den Verkehr achten wird."],"v":["https://video2.kalaiwa.de/assets/1102137mv1440.mp4"],"rn":45},{"n":"1.1.02-138-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Ich fahre gleichmäßig weiter","Ich reduziere meine Geschwindigkeit","Ich stelle mich auf eine Gefahrbremsung ein"],"co":[1,2],"ex":["Da der Hund und der Hundehalter auf die Fahrbahn laufen, darfst du nicht einfach weiterfahren. Eine angemessene Reaktion ist, deine Geschwindigkeit zu reduzieren, um gegebenenfalls eine Gefahrenbremsung durchführen zu können.","Es scheint, als würden der Hund und der Hundehalter auf die Straße rennen. Um eine Kollision vermeiden zu können, solltest du deine Geschwindigkeit reduzieren.","In der angezeigten Situation ist möglich, dass als Nächstes der Hund samt Hundehalter auf deine Fahrbahn läuft. Sei bereit, eine Gefahrenbremsung machen zu müssen."],"v":["https://video4.kalaiwa.de/assets/1102138mv1440.mp4"],"rn":46},{"n":"1.1.03-001","t":"Wo müssen Sie besonders mit starker Fahrbahnverschmutzung und Rutschgefahr rechnen?","p":3,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["An Baustellen","An Einmündungen von Feldwegen","An innerstädtischen Kreuzungen"],"co":[0,1],"ex":["Da hier viel Baumaterial transportiert wird, kann es schnell zu Verschmutzung auf der Fahrbahn kommen. Besonders witterungsbedingt durch Regen und Wind kann das Baumaterial auf der Straße verteilt und somit zu einem rutschigen Risiko für den Autofahrer werden.","Feldwege sind häufig nicht betoniert, sondern bestehen aus Kies oder Schotter. Dies kann durch Fahrzeugreifen auf die Fahrbahn an der Ein- und Ausfahrt des Feldwegs transportiert werden und somit ebenfalls durch witterungsbedingte Einflüsse eine potenzielle Rutschgefahr darstellen.","Da diese betoniert und meist viel befahren sind, kann hier im Regelfall von einer unrutschigen und sauberen Fahrbahn ausgegangen werden."],"rn":47},{"n":"1.1.03-003","t":"Wo müssen Sie besonders mit Fahrbahnvereisung rechnen?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Auf Strecken, die durch Wald führen","Auf Brücken","Auf stark befahrenen Strecken"],"co":[0,1],"ex":["Im Wald wird die Sonneneinstrahlung durch die Bäume eingeschränkt. Dadurch kann die Straße nicht in dem Maß durch Sonnenwärme erhitzt werden und Eis schmelzen, wie es auf freiliegenden Straßen der Fall ist. Zudem sind Waldstraßen häufig weniger befahren als beispielsweise Autobahnen.","Es fehlt unter den Brücken der Erdboden als Wärmespeicher. Außerdem führt Wind zu weiterer und schnellerer Abkühlung der durch die Befahrung aufgeheizten Fahrbahn.","Auf vielbefahrenen Straßen wird durch den hohen Abgasausstoß mehr Wärme auf die Straßen abgegeben. Somit kann Eis weniger leicht entstehen oder bestehen bleiben. Allerdings sollte auch auf stark befahrenen Straßen morgens erhöhte Vorsicht geboten werden, da hier nachts weniger Befahrung herrscht und sich der Boden abkühlt."],"rn":48},{"n":"1.1.03-005","t":"Auf der Fahrbahn befindet sich Öl. Wie sollten Sie sich jetzt verhalten?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich weiche auf die linke Fahrbahnhälfte aus","Ich informiere die Feuerwehr","Ich vermeide starkes Bremsen und ruckartiges Lenken"],"co":[1,2],"ex":["Auf der linken Fahrbahnhälfte befindet sich ein Fahrzeug. Du kannst hier nicht ausweichen. Vermindere vorsichtig deine Geschwindigkeit und vermeide Lenkbewegungen, während du über die Ölspur fährst, um nicht ins Schleudern zu geraten.","Ist eine Ölspur auf der Fahrbahn, dann muss das der Feuerwehr gemeldet werden, damit diese sie beseitigen kann.","Das Öl trägt zusätzlich zum Regen zu einer rutschigen Fahrbahn bei, auf der die Reifen weniger Haftung haben. Durch starkes Bremsen oder ruckartiges Lenken würdest du Risiko laufen, ins Rutschen oder Schleudern zu geraten."],"i":["https://video4.kalaiwa.de/assets/1103005.webp"],"rn":49},{"n":"1.1.03-104","t":"Die Straße ist auf einem kurzen Stück vereist. Was sollen Sie hier möglichst vermeiden?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Beschleunigen","Lenkbewegungen","Bremsen"],"co":[0,1,2],"ex":["Auf einer vereisten Fläche sollte versucht werden, die Schleudergefahr so gering wie möglich zu halten. Daher sollte bei vereisten Straßen besonders langsam mit erhöhter Vorsicht gefahren werden.","Auch die kleinste unkontrollierte Lenkbewegung kann auf einer vereisten Straße zu einem Unfall führen. Daher solltest du bei Glätte besonders bedacht fahren und plötzliche oder hektische Lenkradbewegungen vermeiden.","Bremse möglichst nicht, da du sonst leicht ins Schleudern geraden kannst. Lass das Auto stattdessen lieber langsam ausrollen."],"rn":50},{"n":"1.1.03-105","t":"Wie können Sie beim Fahren gefahrlos feststellen, ob die Fahrbahn vereist ist?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Lenkung ruckartig hin- und herbewegen","Bei ganz langsamer Fahrt bremsen","Kräftig Gas geben"],"co":[1],"ex":["Bei bestimmten Fahrbahnzuständen (z.B. bei Eis, Rollsplitt) sollte auf hektische Lenkbewegungen verzichtet werden, da sonst die Gefahr besteht, ins Schleudern zu geraten.","Ein Bremstest bei ganz langsamer Fahrt ist wichtig, um die Fahrbahnverhältnisse bei Glätte einzuschätzen. Dann ist der Bremsweg relativ kurz und die Schleudergefahr am geringsten. Entsprechend ist ein solcher Test empfehlenswert, um sein eigenes Fahrverhalten im Anschluss besser steuern zu können. So kann auch einer Gefährdung anderer Verkehrsteilnehmer vorgebeugt werden.","Kräftiges Gas geben begünstigt die Schleudergefahr bei vereisten Fahrbahnflächen, da die Reifen so schnell Halt verlieren können. Daher sollte bei vereister Fahrbahn langsam gefahren werden."],"rn":51},{"n":"1.1.03-109","t":"Wo müssen Sie besonders mit plötzlich auftretendem Nebel rechnen?","p":3,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["An Flussläufen","In Moorgebieten","An Seen"],"co":[0,1,2],"ex":["Nebel entsteht wenn mit Wasserdampf gesättigte Luft abkühlt. Folglich ist an Flussläufen mit Nebelschwaden zu rechnen.","Feuchte Moore begünstigen durch ihren erhöhten Feuchtigkeitsgehalt die Bildung von Nebel.","Gewässer begünstigen im Allgemeinen die Bildung von Nebel. Daher bildet sich dieser auch bei Seen und kann die Sicht auf die Fahrbahn behindern."],"rn":52},{"n":"1.1.03-110","t":"Was müssen Sie tun, wenn vor Ihnen ein Nebelfeld die Sicht stark behindert?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Geschwindigkeit rechtzeitig den Sichtverhältnissen anpassen","Dicht aufschließen, um sich an den Schlussleuchten des vorausfahrenden Fahrzeugs zu orientieren","Abstand zum vorausfahrenden Fahrzeug vergrößern"],"co":[0,2],"ex":["In der StVO § 3 Abs. 1 ist definiert, dass der Fahrzeugführer nur so schnell fahren darf, dass er sein Fahrzeug ständig beherrscht. Er hat seine Geschwindigkeit insbesondere den Sicht- und Wetterverhältnissen anzupassen. Da durch Nebel die Sicht beeinträchtigt wird, darf nur so schnell gefahren werden, dass jederzeit gefahrlos angehalten werden kann.","Dichtes Auffahren begünstigt Auffahrunfälle. Insbesondere in Kombination mit einer feuchten Fahrbahn kann dies zum Verhängnis werden. Daher ist der Sicherheitsabstand bei Nebel noch zu vergrößern, damit bei abruptem Anhalten des Vordermanns gefahrlos langsam abgebremst werden kann.","Bei Nebel ist die Fahrbahn feucht. Dadurch verlängert sich der Bremsweg des Fahrzeugs und zudem ist die Sicht auf den Vordermann eingeschränkt. Entsprechend muss der Abstand zum vorausfahrenden Fahrzeug vergrößert werden, um die Gefahr eines Auffahrunfalls zu minimieren."],"rn":53},{"n":"1.1.03-116","t":"Warum kann hier das Rechtsabbiegen gefährlich werden?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Weil ich möglicherweise nicht rechtzeitig anhalten kann, wenn Fußgänger die Seitenstraße überqueren","Weil mein Fahrzeug bei zu schnellem Abbiegen ins Schleudern geraten kann","Weil Fahrzeuge, die aus der Seitenstraße kommen, beim Abbremsen ins Schleudern geraten können"],"co":[0,1,2],"ex":["Die Straße sieht sehr eisig und rutschig aus. Fahre daher sehr langsam und vorsichtig um die Kurve. Befinden sich Fußgänger am Straßenrand, dann halte an und warte mit dem Abbiegen, bis sie die Straße vollständig überquert haben, um niemanden zu gefährden.","Die eisige Fahrbahn gibt ohnehin wenig Haftung für die Reifen. Hier kann zu schnelles Abbiegen dazu führen, dass das Fahrzeug ins Schleudern gerät.","Aufgrund der vereisten Fahrbahnoberfläche haben die Reifen kaum Haftung. So kann es passieren, dass ein Auto beim Abbremsen ins Schleudern gerät."],"i":["https://video4.kalaiwa.de/assets/1103116.webp"],"rn":54},{"n":"1.1.03-120","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":3,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich bremse in der Kurve stark ab","Ich vermeide ruckartige Lenkbewegungen","Ich verringere die Geschwindigkeit"],"co":[1,2],"ex":["Starkes Bremsen in der Kurve ist generell gefährlich. Wenn du zu schnell in eine Kurve fährst, kannst du die Kontrolle über dein Fahrzeug verlieren. In dieser Situation kommt die Schnee- und Eisglätte noch hinzu. Du würdest vermutlich ins Rutschen geraten.","Schnee oder Eis auf der Fahrbahn führt zu Glätte. Ruckartiges Bremsen oder Lenken sind zu vermeiden, da eine große Rutschgefahr besteht.","Offensichtlich fährst du einen Berg nach oben. Das Verkehrsschild deutet auf Schnee- oder Eisglätte hin und in der Kurve vor dir ist bereits Schnee oder Schneematsch auf der Straße erkennbar. Auch der entgegenkommende Räumdienst mit eingeschaltetem Warnlicht lässt vermuten, dass hier erhöhte Vorsicht geboten ist. Du musst bremsen, um nicht ins Rutschen zu geraten."],"i":["https://video2.kalaiwa.de/assets/1103120.webp"],"rn":55},{"n":"1.1.03-121","t":"Während der Fahrt regnet es plötzlich stark. Wie sollten Sie sich verhalten?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich verringere meine Geschwindigkeit","Ich vermeide starkes Beschleunigen","Ich verringere den Sicherheitsabstand zum Vorausfahrenden"],"co":[0,1],"ex":["Bei Regen verschlechtert sich deine Sicht. Um trotzdem auf alle möglichen Einflüsse gefasst zu sein, solltest du langsam und vorausschauend fahren. Außerdem kann es zu Aquaplaning kommen. Hierbei verlieren deine Reifen die Haftung zur Straße und du hast keine Kontrolle mehr. Es gilt: nicht Lenken, nicht Bremsen, nur die Kupplung treten und somit langsamer werden.","Auf einer nassen Fahrbahn kann starkes Beschleunigen zum Durchdrehen der Räder führen, somit kannst du die Kontrolle über dein Fahrzeug verlieren.","Auf einer nassen Fahrbahn verlängert sich dein Bremsweg. Du solltest deinen Sicherheitsabstand zum Vorausfahrenden vergrößern, um einen Auffahrunfall zu vermeiden."],"rn":56},{"n":"1.1.03-006-M","t":"Worauf müssen Sie sich hier einstellen?","p":3,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Auf eine verengte Fahrbahn","Auf einen verlängerten Bremsweg","Auf ein von rechts kommendes Fahrzeug"],"co":[0,1,2],"ex":["Das Verkehrszeichen zeigt eine einseitig verengte Fahrbahn rechts an. Du müsstest den entgegenkommenden Lkw heraus fahren lassen, bevor du in die Straße geradeaus fahren kannst.","Durch Nässe und Laub ist der Bremsweg auf dieser Fahrbahn deutlich länger. Zusätzlich besteht Rutschgefahr.","An dieser Kreuzung gilt die Regelung rechts vor links, da sich keine vorfahrtregelnden Verkehrszeichen, Ampeln oder Polizeibeamten an den Einmündungen befinden. Erschwert wird die Situation, weil nahende Fahrzeuge von rechts durch die Hecke nicht erkennbar sind. Es könnte sich bereits ein Fahrzeug kurz vor der Kreuzung befinden. Sicherheitshalber solltest Du deine Aufmerksamkeit zunächst auf diese Einmündung richten, bevor Du Dich auf die enger werdende Straße geradeaus konzentrierst."],"i":["https://video2.kalaiwa.de/assets/1103006m.webp"],"rn":57},{"n":"1.1.03-007-M","t":"Sie fahren nach Starkregen. Was sollten Sie in dieser Situation beachten?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich sollte einen großen Sicherheitsabstand zum vorausfahrenden Fahrzeug halten","Ich kann Unebenheiten auf der Fahrbahn schlecht erkennen","Spritzwasser kann meine Sicht beeinträchtigen"],"co":[0,1,2],"ex":["Nach einem Starkregen hat sich viel Wasser auf der Straße gesammelt, das erst noch ablaufen muss. Gegebenenfalls haben sich Pfützen gebildet, die das Risiko für Aquaplaning erhöhen. Aquaplaning führt dazu, dass du die Kontrolle über das Fahrzeug verlierst. Auch deshalb solltest du nach Starkregen immer einen großen Sicherheitsabstand zum vorausfahrenden Fahrzeug halten.","Durch den starken Regen bilden sich oft Pfützen, in denen man Unebenheiten der Fahrbahn oder Schlaglöcher nicht erkennen kann. Außerdem kann die nasse Fahrbahn spiegeln, was die Sicht zusätzlich erschwert.","Nach Starkregen kann durch das vorausfahrende Fahrzeug oder den Gegenverkehr plötzlich viel Spritzwasser aus Pfützen auf der Windschutzscheibe landen. Darauf solltest du gefasst sein. Möglicherweise sind auch Bremslichter und andere Signale der anderen Fahrzeuge bei Nässe schlechter zu erkennen, als bei trockener Fahrbahn."],"i":["https://video4.kalaiwa.de/assets/1103007m.webp"],"rn":58},{"n":"1.1.03-102-B","t":"Warum müssen Sie auf dieser Straße besonders aufmerksam fahren?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Weil das Fahren auf den Schienen gefährlich ist","Weil eine Straßenbahn entgegenkommen könnte","Weil die Fahrbahnoberfläche uneben und unterschiedlich griffig ist"],"co":[0,1,2],"ex":["Es könnte von hinten oder vorne eine Straßenbahn auf dich zukommen. Für diesen Fall musst du eine Ausweichmöglichkeit im Auge haben, bei der kein Verkehrsteilnehmer gefährdet wird. Das ist nur durch vorausschauendes Fahren möglich. Zudem können Schienen rutschig sein und die Haftung der Reifen am Boden einschränken.","Wenn dieser Fall eintritt, dann solltest du mit einer Geschwindigkeit fahren, bei der du den Abstand zur Straßenbahn ausreichend abschätzen kannst.","So haben die Reifen weniger Haftung und der Bremsweg ist länger."],"i":["https://video2.kalaiwa.de/assets/1103102b.webp"],"rn":59},{"n":"1.1.03-108-B","t":"Warum müssen Sie hier besonders vorsichtig fahren?","p":3,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Weil die Fahrbahn durch den falsch parkenden Pkw verengt ist","Weil die Sicht durch die Kurve behindert ist","Weil die Fahrbahn glatt ist"],"co":[0,1,2],"ex":["Parken in Kurven ist untersagt. Der PKW behindert so deinen ohnehin schon eingeschränkten Blick auf die Kurve und möglichen Gegenverkehr. Daher solltest du dich äußerst vorsichtig und langsam an die Kurve herantasten, um im Falle von Gegenverkehr schnell und sicher reagieren zu können.","Aufgrund der Kurve ist nicht ersichtlich, wie die Fahrbahn weiter verläuft. Das in Kombination mit den Witterungsbedingungen und dem parkenden Fahrzeug sollte dich dazu veranlassen, sehr langsam und vorsichtig zu fahren.","Aufgrund von Schnee und Eisglätte sollte hier unbedingt langsam und vorsichtig gefahren werden."],"i":["https://video4.kalaiwa.de/assets/1103108b.webp"],"rn":60},{"n":"1.1.03-112-M","t":"Wie verhalten Sie sich hier richtig?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich ermögliche der Fußgängerin auf der rechten Seite das Überqueren der Fahrbahn","Ich fahre vorsichtig weiter, da keine Markierung auf der Fahrbahn zu erkennen ist","Ich bremse vorsichtig"],"co":[0,2],"ex":["Die Fußgängerin steht am Fußgängerüberweg. Sie hat Vorrang vor dir.","Durch den Schnee auf der Fahrbahn ist keine Markierung zu erkennen. Allerdings weisen Verkehrsschilder auf einen Fußgängerüberweg hin.","Vor dir befindet sich ein Fußgängerüberweg. Du solltest deine Geschwindigkeit vorsichtig reduzieren. Durch den Schnee auf der Fahrbahn könntest du durch zu starkes Bremsen ins Rutschen geraten."],"i":["https://video4.kalaiwa.de/assets/1103112m.webp"],"rn":61},{"n":"1.1.03-114-M","t":"Warum müssen Sie hier besonders aufmerksam sein?","p":4,"c":"1.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Weil der Gegenverkehr die Kurve schneiden könnte","Weil die Fahrbahnoberfläche ungleichmäßig ist","Weil der Straßenverlauf unübersichtlich ist"],"co":[0,1,2],"ex":["Der Gegenverkehr ist hier nicht ersichtlich und es ist möglich, dass er die Kurve schneidet. Deswegen solltest du hier besonders aufmerksam sein.","Durch die unebene Fahrbahn haben die Reifen weniger Haftung. Das musst du bei deiner Fahrweise berücksichtigen.","Das Kurvenende und der Gegenverkehr sind hier nicht ersichtlich. Daher solltest du dich langsam und vorsichtig an die Kurve herantasten."],"i":["https://video2.kalaiwa.de/assets/1103114m.webp"],"rn":62},{"n":"1.1.04-107","t":"Womit müssen Sie hier rechnen?","p":4,"c":"1.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Dass sich Ampeln von den bunten Lichtreklamen kaum abheben","Dass Sie entgegenkommende Fahrzeuge erst spät erkennen","Dass Ihr Fahrzeug von anderen nicht rechtzeitig gesehen wird"],"co":[0,1,2],"ex":["Die Lichter der Ampeln ähneln denen der bunten Umgebung. Sie unterscheiden sich nicht so stark vom Umfeld und können somit möglicherweise erst spät erkannt werden.","Dir fällt es aufgrund der vielen bunten Leuchtreklame schwerer, andere Fahrzeuge von der Umgebung zu unterscheiden. So kann es passieren, dass du entgegenkommende Fahrzeuge erst spät als solche wahrnimmst.","Das Umfeld ist sehr stark in bunten Lichtern beleuchtet. So können andere Fahrer dich aufgrund des hellen Lichtlevels nicht mehr so stark von der sonst dunklen Umgebung unterscheiden und dich möglicherweise nicht rechtzeitig erkennen."],"i":["https://video4.kalaiwa.de/assets/1104107.webp"],"rn":63},{"n":"1.1.04-108","t":"Warum kann das Befahren dieser Straße gefährlich werden?","p":4,"c":"1.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Weil Personen auf der Fahrbahn leicht übersehen werden","Weil schlecht beleuchtete Fahrzeuge schwer zu erkennen sind","Weil entgegenkommende Kraftfahrzeuge erst spät erkannt werden"],"co":[0,1],"ex":["Die Straße ist nur schwach beleuchtet. Deswegen könnten Personen, die sich außerhalb des Lichtkegels deines Abblendlichts befinden, erst spät von dir gesehen werden. Daher fahre hier angemessen, damit du im Bedarfsfall rechtzeitig bremsen kannst.","Deswegen musst du hier sehr langsam und aufmerksam fahren.","Entgegenkommende Fahrzeuge werden nicht zu spät erkannt, da sie bei Dunkelheit das Abblendlicht eingeschaltet haben."],"i":["https://video2.kalaiwa.de/assets/1104108.webp"],"rn":64},{"n":"1.1.04-110","t":"Worauf müssen Sie achten, wenn Sie in eine Tiefgarage fahren?","p":4,"c":"1.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Fußgänger laufen oft auf Fahrwegen","Meine Augen müssen sich erst an die veränderten Lichtverhältnisse gewöhnen","Meine Reifen können an engen Aus- und Einfahrten beschädigt werden"],"co":[0,1,2],"ex":["Überall, wo Fußgänger in der Nähe sein könnten, musst du besonders aufmerksam fahren und bremsbereit sein.","Du musst langsam in die Tiefgarage einfahren, um deine Augen an die Lichtverhältnisse zu gewöhnen.","Um zu vermeiden, dass Reifen beschädigt werden, solltest du hier langsam und vorsichtig fahren."],"rn":65},{"n":"1.1.04-111","t":"Wie sollten Sie sich bei diesen Sichtverhältnissen verhalten?","p":3,"c":"1.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Ich orientiere mich am rechten Fahrbahnrand","Ich schalte das Fernlicht ein","Ich reduziere meine Geschwindigkeit"],"co":[0,2],"ex":["Vermeide unbedingt den direkten Blick in Richtung der Blendung und orientiere dich am rechten Fahrbahnrand.","Das würde den Traktor blenden und dir keinerlei Hilfe sein.","Hinter dem Traktor geht die Sonne auf. Die dadurch verursachte Blendung wird beim Weiterfahren noch stärker. Vermindere daher deine Geschwindigkeit."],"i":["https://video2.kalaiwa.de/assets/1104111.webp"],"rn":66},{"n":"1.1.04-103-B","t":"Was müssen Sie hier tun, wenn Sie geblendet werden?","p":4,"c":"1.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Zum rechten Fahrbahnrand schauen","Beschleunigen, um schneller aus dem Lichtkegel herauszukommen","Geschwindigkeit notfalls vermindern"],"co":[0,2],"ex":["Blendet dich das Licht des Gegenverkehrs, dann ist es hilfreich, an den rechten Fahrbahnrand zu schauen. So hast du nämlich immernoch Sicht auf den vorausfahrenden Verkehr und wirst weniger durch die Scheinwerfer des Gegenverkehrs irritiert.","Das wäre sehr riskant, da dein Sichtfeld ohnehin schon durch die blendenden Scheinwerfer eingeschränkt ist.","Wenn die Blendung dich in deiner sicheren Fahrweise einschränkt, dann solltest du langsamer fahren und zum rechten Fahrbahnrand schauen."],"i":["https://video4.kalaiwa.de/assets/1104103b.webp"],"rn":67},{"n":"1.1.05-001","t":"Wo führt schnelles Fahren häufig zu Unfällen?","p":4,"c":"1.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["An Fußgängerüberwegen","An Straßenkreuzungen und -einmündungen","In Kurven"],"co":[0,1,2],"ex":["Plötzlich auf die Fahrbahn laufende Fußgänger erlauben nur eine sehr kurze Reaktionszeit und einen extrem kurzen Bremsweg. Bei zu schnellem Fahren wird der Reaktionsweg länger und der Bremsweg zum Anhalten zu lang, um eine sichere Überquerung der Fußgänger zu gewährleisten. Daher sollte, sobald ein Fußgängerüberweg in Sicht ist, das Fahrtempo an eine mögliche Überquerung angepasst werden.","An Kreuzungen und Einmündungen hat der Fahrer eine eingeschränkte Einsicht in das Verkehrsgeschehen. Eventuell herannahende Fahrzeuge können erst spät erkannt werden. Durch schnelles Fahren wird der Reaktionsweg länger und der Bremsweg zum Anhalten zu lang. Dadurch können Unfälle entstehen.","Durch die Fliehkraft wird das Fahrzeug in einer Kurve an den Kurvenrand gedrängt. Bei erhöhter Geschwindigkeit des Fahrzeugs verstärkt sich die Fliehkraft \"nach außen\" und kann dazu führen, dass man \"aus der Kurve fliegt\"."],"rn":68},{"n":"1.1.05-002","t":"Wo ist zu schnelles Fahren besonders gefährlich?","p":4,"c":"1.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["An Fahrbahnverengungen","An Bahnübergängen","In unübersichtlichen Kurven"],"co":[0,1,2],"ex":["Ist die Fahrbahn zu schmal, dann kann es an Engstellen problematisch sein, am Gegenverkehr vorbei zu kommen. Entsprechen sollte langsam gefahren werden, um im Bedarfsfall zu bremsen oder ein Stück nach rechts ausweichen zu können, ohne einen Unfall zu riskieren.","Um den Bahnübergang gefahrlos überqueren zu können, ist vorausschauendes und langsames Fahren notwendig. Nur so kannst du abschätzen, wie weit ein herannahendes Schienenfahrzeug entfernt ist und auf Verkehrszeichen achten.","Hier kann nur ein kleiner Teil der Fahrstrecke wahrgenommen werden. Dadurch ist vorausschauendes Fahren nicht möglich und Hindernisse nach der Kurve können nicht eingesehen werden. Auch der Gegenverkehr kann aufgrund einer Kurve oft nicht oder nicht ausreichend eingeschätzt werden. Zudem kann das Fahrzeug bei zu schnellem Fahren \"aus der Kurve fliegen\". Daher muss das Fahrtempo an die Einsicht der Fahrbahn angepasst werden."],"rn":69},{"n":"1.1.05-003","t":"Wie durchfahren Sie enge Kurven?","p":4,"c":"1.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["Erst im Scheitelpunkt der Kurve Geschwindigkeit vermindern","Vor der Kurve Geschwindigkeit vermindern","Erst beim Übergang in die Gerade wieder beschleunigen"],"co":[1,2],"ex":["Der Scheitelpunkt der Kurve ist des gefährlichste Moment, da hier das Risiko ins Schleudern zu geraten am höchsten ist. Daher sollte langsam und mit Bedacht in die Kurve eingefahren werden.","Durch die Fliehkraft wird das Fahrzeug in einer Kurve an den Fahrbahnrand gedrückt. Dieser Effekt wird durch eine hohe Geschwindigkeit noch verstärkt. Entsprechend ist langsames Einfahren in Kurven geboten um ein \"aus der Kurve fliegen\" und das Gelangen auf die Gegenfahrbahn zu vermeiden.","Beschleunigen in der Kurve kann die Schleudergefahr erhöhen. Entsprechend sollte erst wieder Gas gegeben werden, wenn das Fahrzeug am Ende der Kurve angelangt ist."],"rn":70},{"n":"1.1.05-107-M","t":"Womit müssen Sie hier rechnen?","p":4,"c":"1.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["Dass zu schnell gefahren wird","Dass Einmündungen übersehen werden","Dass Kinder auf die Straße laufen"],"co":[0,1,2],"ex":["Weil diese Straße sehr breit und wenig befahren ist, könnte das andere Verkehrsteilnehmer zum schnellen Fahren verleiten.","Die Häuser sind sehr nah am Gehweg gebaut und schränken somit die Sicht auf Einmündungen ein.","Dies ist eine Wohngegend, somit kann man davon ausgehen, dass Kinder auf die Straße laufen können."],"i":["https://video4.kalaiwa.de/assets/1105107m.webp"],"rn":71},{"n":"1.1.06-002","t":"Ist es leichtsinnig, noch kurz vor einer Kreuzung einen Lastzug zu überholen?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Nein, weil Lastzüge meist langsam fahren","Ja, weil der Lastzug die Sicht auf wichtige Verkehrszeichen verdecken kann","Ja, weil der Lastzug die Sicht auf den Querverkehr verdeckt"],"co":[1,2],"ex":["Generell kann nicht davon ausgegangen werden, dass LKWs langsam fahren. Auch andere Fahrzeuge sollten nicht vor Kreuzungen überholt werden, da dies leichtsinnig ist und die Sicherheit des Straßenverkehrs gefährdet.","Aufgrund der Höhe des Lastfahrzeugs (LKW) ist die Sicht auf die Kreuzung eingeschränkt. Im Vergleich zum LKW relativ kleine Verkehrszeichen können durch ein Überholen des LKWs leicht übersehen werden. Dementsprechend ist von einem Überholmanöver abzusehen.","Ein LKW kann auch die Sicht auf den Verkehr in einer Kreuzung verdecken. Querverkehr, der möglicherweise auf Ihre Straße abbiegen möchte, kann somit nicht gesehen werden und es kann zu Zusammenstößen kommen."],"rn":72},{"n":"1.1.06-104","t":"Wann wird ein Überholender gefährdet?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- seine Geschwindigkeit stark verringert","- plötzlich beschleunigt","- zum Überholen ausschert"],"co":[1,2],"ex":["Wenn der zu Überholende seine Geschwindigkeit stark verringert, dann wird der Überholweg deutlich kürzer. Der Überholende kann sich eher wieder im rechten Fahrstreifen einordnen und befindet sich nicht so lange auf der Gegenfahrbahn. Dadurch wird niemand gefährdet.","Dann wird der Überholweg nämlich länger. Der Überholende kann eine solche Verhaltensweise nicht vorhersehen, aber es kann daraus eine gefährliche Situation (z.B. aufgrund von Gegenverkehr) entstehen. Laut StVO ist beschleunigen, wenn man überholt wird, verboten.","So kann es sein, dass sich der Überholende im toten Winkel des vorderen Fahrzeugs befindet und dieser ausschert, ohne den Heranfahrenden zu sehen."],"rn":73},{"n":"1.1.06-105","t":"In welchen Fällen muss das Überholen abgebrochen werden?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Wenn der Eingeholte seine Geschwindigkeit stark verringert","Wenn durch unerwarteten Gegenverkehr Gefahr entsteht","Wenn der Eingeholte plötzlich beschleunigt"],"co":[1,2],"ex":["Verringert der Eingeholte seine Geschwindigkeit, so beschleunigt das den Überholvorgang. Der Überholende kann schneller wieder vor dem überholten Fahrzeug einscheren. Dadurch wird ein sicheres Überholen erleichtert.","Ein plötzlich auftauchendes Fahrzeug kann die eingeplante Zeit für den Überholvorgang bedeutend verkürzen. Die zur Verfügung stehende Wegstrecke wird ebenfalls kürzer. Es ist daher besser, den Überholvorgang abzubrechen und bei Bedarf zu gegebener Zeit nochmals neu zum Überholen anzusetzen.","Dann dauert der Überholvorgang nämlich bedeutend länger. Die benötigte Wegstrecke verlängert sich. Daher ist es besser den Überholvorgang abzubrechen."],"rn":74},{"n":"1.1.06-106","t":"Wann ist das Überholen verboten?","p":4,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Wenn Sie nicht wesentlich schneller fahren können als der zu Überholende","Wenn Sie nicht die gesamte Überholstrecke überblicken","Wenn die Verkehrslage unklar ist"],"co":[0,1,2],"ex":["Wird die Motorleistung des eigenen Fahrzeugs überschätzt, kann dies bei einem Überholvorgang sehr gefährliche Konsequenzen haben. So kann der Überholvorgang länger dauern als anfangs geschätzt und die benötigte Strecke kann folglich nicht in der geplanten Zeit abgefahren werden. Dadurch wird der Überholvorgang sehr gefährlich. Es könnte ein Fahrzeug auf der Gegenfahrbahn erscheinen und die Gefahr eines Zusammenstoßes auftreten.","Wenn nicht die gesamte Strecke eingesehen werden kann, ist nicht abzuschätzen, was sich auf der Gegenfahrbahn befindet (oder ob auf der eigenen Fahrbahn ein Hindernis steht). Daher ist es gefährlich in dieser Situation zu überholen und man sollte warten, bis ausreichend Einsicht in die Straße gegeben ist, um zu überholen.","Somit ist eine Abschätzung des Fahrverhaltens anderer Fahrzeugführer nicht möglich. Laut StVO muss die Verkehrslage klar sein, um ein Überholmanöver zu beginnen."],"rn":75},{"n":"1.1.06-111","t":"Warum kann Überholen auch auf übersichtlichen und geraden Fahrbahnen gefährlich sein?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- Gegenverkehr langsamer fährt als angenommen","- Überholweg länger ist als angenommen","- Gegenverkehr schneller fährt als angenommen"],"co":[1,2],"ex":["Dadurch wird das Überholen erleichtert.","Um das zu vermeiden, solltest du nur Überholen, wenn die Verkehrslage weit einsichtig ist.","Dadurch steht dir weniger Zeit und Weg zur Verfügung, als angenommen."],"rn":76},{"n":"1.1.06-114","t":"Wie verhalten Sie sich?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich führe den Überholvorgang zügig durch","Ich breche den Überholvorgang ab","Ich führe den Überholvorgang vorsichtig durch"],"co":[1],"ex":["So würdest du den Radfahrer, das ausparkende Fahrzeug und dich gefährden.","Weil rechts ein Fahrzeug aus der Parklücke herausfährt, musst du den Überholvorgang abbrechen.","Du musst den Überholvorgang abbrechen, um niemanden zu gefährden."],"v":["https://video4.kalaiwa.de/assets/1106114v1440.mp4"],"rn":77},{"n":"1.1.06-122","t":"Womit müssen Sie rechnen, wenn Sie überholen wollen?","p":4,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Mit Rutschgefahr","Mit unsicherer Fahrweise des Radfahrers","Mit verlängertem Anhalteweg"],"co":[0,1,2],"ex":["Bei verschneiter, eisiger Fahrbahn haben die Reifen weniger Haftung und können ins Rutschen geraten. Du solltest plötzliches Bremsen durch langsames, vorausschauendes Fahren vermeiden, um nicht ins Schleudern zu geraten.","Aufgrund der Witterungsbedingungen kann die Fahrsicherheit des Radfahrers beeinträchtigt sein.","Die Fahrbahn ist verschneit und möglicherweise vereist. Dadurch haben die Autoreifen weniger Haftung und der Anhalteweg verlängert sich."],"i":["https://video4.kalaiwa.de/assets/1106122.webp"],"rn":78},{"n":"1.1.06-124","t":"Sie möchten in einer schmalen Straße Radfahrer überholen. Wegen der Straßenbreite ist ein Seitenabstand zu ihnen von höchstens 50 cm möglich. Wie verhalten Sie sich?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich überhole nicht","Ich gebe vor dem Überholen ein kurzes Warnzeichen","Ich überhole mit mäßiger Geschwindigkeit"],"co":[0],"ex":["50 cm Seitenabstand reichen nicht aus, um ein sicheres Überholen zu gewährleisten.","Du darfst in diesem Fall nicht überholen, weil der Seitenabstand zu gering ist.","Du darfst nicht überholen. 50 cm Seitenabstand reichen nicht aus, damit sicheres Überholen möglich ist."],"rn":79},{"n":"1.1.06-128","t":"In welcher Situation ist das Überholen unzulässig?","p":4,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- nötigen Seitenabstand nicht einhalten kann","- Überholvorgang nicht vor dem Beginn eines Überholverbots beenden kann","- Überholvorgang nicht vor einer Kuppe beenden kann"],"co":[0,1,2],"ex":["Beim Überholen muss der Seitenabstand zu anderen Verkehrsteilnehmern unbedingt eingehalten werden. Dieser beträgt im Ort mindestens 1,5 m und außerhalb von Ortschaften mindestens 2 m.","Im Überholverbot darfst du nicht überholen. Auch nicht, wenn du deinen Überholvorgang schon vor dem Überholverbot begonnen hast.","Vor unübersichtlichen Stellen wie Kuppen sollte generell nicht überholt werden. Es könnte jederzeit ein Fahrzeug auf der Gegenfahrbahn kommen."],"rn":80},{"n":"1.1.06-130","t":"Weshalb kann Überholen auch auf übersichtlichen und geraden Fahrbahnen gefährlich sein?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- die Entfernung eines entgegenkommenden Fahrzeugs als zu groß einschätze","- die Geschwindigkeit eines entgegenkommenden Fahrzeugs als zu gering einschätze","- meinen Überholweg kürzer einschätze, als er ist"],"co":[0,1,2],"ex":["Möglicherweise könntest du die Entfernung des entgegenkommenden Fahrzeugs als zu groß einschätzen und somit könnte die Zeitspanne, die du für den Überholvorgang benötigst, nicht ausreichen.","Wenn du die Geschwindigkeit des entgegenkommenden Fahrzeugs unterschätzt, kann dein Überholvorgang zu lange dauern und somit für dich und andere Verkehrsteilnehmer gefährlich werden.","Schätzt du deinen Überholweg zu kurz ein, überholst du möglicherweise zu knapp und könntest andere Verkehrsteilnehmer somit behindern und gefährden!"],"rn":81},{"n":"1.1.06-005-M","t":"Warum dürfen Sie jetzt nicht überholen?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil die Radfahrerin nach links abbiegen könnte","Weil der Straßenbelag auf der linken Fahrbahnhälfte sehr schlecht ist","Weil ich möglichen Gegenverkehr nicht rechtzeitig sehen kann"],"co":[0,2],"ex":["Du befindest dich kurz vor einer linksabzweigenden Straße. Die Radfahrerin vor dir könnte jederzeit links abbiegen und dem anderen Radfahrer folgen. Du darfst jetzt nicht überholen, um eine mögliche Kollision mit der Radfahrerin zu vermeiden.","Der Zustand des Straßenbelags hat in dieser Situation keinen Einfluss auf dein Fahren. Der schlechte Straßenbelag ist demnach kein relevanter Grund dafür, nicht zu überholen.","Die andere Fahrbahnhälfte ist durch die am rechten Straßenrand parkenden Autos schlecht einsehbar. Von deiner Position aus kannst du möglichen Gegenverkehr nicht rechtzeitig sehen. Deswegen darfst du an dieser Stelle nicht überholen, da du einen Unfall mit entgegenkommenden Verkehrsteilnehmern riskieren würdest."],"i":["https://video4.kalaiwa.de/assets/1106005m.webp"],"rn":82},{"n":"1.1.06-127-M","t":"Wie verhalten Sie sich richtig?","p":4,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- vor Erreichen des Lkws","- zwischen Lkw und Kurve","- nach der Kurve"],"co":[2],"ex":["Es ist nicht möglich, den Radfahrer noch vor Erreichen des LKWs zu überholen.","Zwischen LKW und Kurve ist keine ausreichende Verkehrseinsicht möglich, um den Radfahrer sicher überholen zu können.","Der LKW hält an einer sehr ungünstigen Stelle und behindert somit die Einsicht in die Kurve. Du musst warten, bis der Radfahrer am LKW vorbeigefahren ist, um in die Kurve hineinzufahren und darfst den Radfahrer erst nach der Kurve überholen, wenn eine bessere Verkehrseinsicht gewährleistet ist."],"v":["https://video2.kalaiwa.de/assets/1106127mv1440.mp4"],"rn":83},{"n":"1.1.06-131-M","t":"Wie verhalten Sie sich jetzt richtig?","p":5,"c":"1.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich verringere die Geschwindigkeit","Ich behalte die Geschwindigkeit bei","Ich fahre nach rechts auf den Parkstreifen"],"co":[0],"ex":["Das dich überholende Fahrzeug hat seinen Überholweg zu kurz eingeschätzt. Du solltest deine Geschwindigkeit verringern, dass der Überholende früher wieder einscheren kann und dass die Gefahr eines Unfalls verringert wird.","Du solltest deine Geschwindigkeit verringern, um die Situation zu deeskalieren.","Nach rechts auf den Parkstreifen auszuweichen, ist wegen der parkenden Fahrzeuge nicht möglich."],"v":["https://video2.kalaiwa.de/assets/1106131mv1440.mp4"],"rn":84},{"n":"1.1.07-001","t":"Womit müssen Sie rechnen, wenn vor Ihnen ein Lastzug in eine enge Straße nach rechts abbiegen will?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- sich besonders weit rechts einordnen","- seine Geschwindigkeit stark vermindern","- vor dem Abbiegen nach links ausscheren"],"co":[1,2],"ex":["Würde sich der LKW weit rechts einordnen, so würde er die Kurve schneiden. Aufgrund der Länge des LKWs ist es notwendig, nach links auszuscheren, um rechts abbiegen zu können.","Besonders dann, wenn ein LKW in eine enge Straße einbiegen will, wird er seine Geschwindigkeit stark vermindern, da er einen größeren Wendekreis als ein PKW besitzt. Entsprechend muss er sehr vorsichtig um die Kurve fahren.","Da der LKW einen größeren Wendekreis als ein PKW besitzt, ist es für dessen Fahrer vor allem bei sehr engen Kurven notwendig, auszuscheren, um diese nehmen zu können."],"rn":85},{"n":"1.1.07-002","t":"Worauf müssen Sie innerorts an Kreuzungen und Einmündungen besonders achten?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["An allen Kreuzungen und Einmündungen gilt ausnahmslos die Regel „rechts vor links“","Die breitere Straße ist immer bevorrechtigt","Kreuzende oder einmündende Straßen können bevorrechtigt sein, obwohl sie schmal und weniger gut ausgebaut sind"],"co":[2],"ex":["\"rechts vor links\" gilt nur dann, wenn keine Verkehrszeichen vorhanden und keine Ampeln oder Polizisten da sind, die den Verkehr regeln.","Die Breite der Straße gibt keine Auskunft über Verkehrsregeln. Im Verkehr müssen Vorfahrtsregelungen in folgender Reihenfolge befolgt werden: 1. einem Polizeibeamten (falls Unfälle oder Ampelausfälle geschehen sind), 2. Ampeln, 3. anderen Verkehrszeichen, 4. Grundregel \"rechts vor links\"","Der Verkehr wird entweder durch einen Polizeibeamten, eine Ampel, Verkehrszeichen oder die Grundregel \"rechts vor links\" geregelt. Wie die Straße ausgebaut ist, ist dabei nicht wichtig. Es besteht durchaus die Möglichkeit, dass eine breite, gut ausgebaute Straße durch Verkehrszeichen zu einer untergeordneten Straße wird."],"rn":86},{"n":"1.1.07-009","t":"Sie nähern sich einer Schule. Kinder verlassen das Schulgelände. Womit müssen Sie rechnen?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- ausgelassen auf die Fahrbahn stürmen","- mit ihren Fahrrädern unvorsichtig auf die Fahrbahn fahren","- sich immer verkehrsgerecht verhalten"],"co":[0,1],"ex":["Kinder sind im Straßenverkehr besonders gefährdet. Sie sind oft ungeduldig und vergessen beim Toben ihr Umfeld. Nach einem anstrengenden Schultag ist es möglich, dass die Kinder unausgelassen und bewegungsbedürftig sind und den Straßenverkehr nicht im Fokus haben.","Kinder können Gefahrensituationen häufig noch nicht angemessen einschätzen. Zudem sind sie auf dem Fahrrad in der Regel nicht so sicher unterwegs wie Erwachsene. Hier ist höchste Vorsicht und Wachsamkeit geboten.","Kinder verhalten sich nicht immer verkehrsgerecht. Oft vergessen sie die Umwelt um sich herum oder können Gefahren nicht richtig einschätzen."],"rn":87},{"n":"1.1.07-010","t":"Worauf kann Warnblinklicht hinweisen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf liegen gebliebene Fahrzeuge","Auf einen Stau","Auf Schulbusse, bei denen Kinder ein- oder aussteigen"],"co":[0,1,2],"ex":["So kann der nachfolgende Verkehr darauf aufmerksam gemacht werden und langsam vorsichtig die Pannenstelle passieren, ohne jemanden zu gefährden.","Um die nachfolgenden Fahrzeuge auf das Stauende aufmerksam zu machen ist es ratsam das Warnblinklicht einzuschalten. So kann die Geschwindigkeit frühzeitig reduziert und Auffahrunfälle vermieden werden.","Hier sollte besondere Aufmerksamkeit geboten sein, da z.B. Kinder ohne zu schauen auf die Straße laufen könnten."],"rn":88},{"n":"1.1.07-011","t":"Vor Ihnen will ein großer Mähdrescher nach rechts abbiegen. Was ist richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- wird vor dem Abbiegen sehr langsam werden","- wird beim Abbiegen weit nach links ausschwenken","- kann wegen der Hinterradlenkung nicht ausschwenken"],"co":[0,1],"ex":["Ein Mähdrescher hat einen sehr hohen Schwerpunkt. Dadurch neigt er in Kurven bei hoher Geschwindigkeit sehr schnell zum Kippen. Der Fahrer muss daher die Geschwindigkeit vor Kurven stark reduzieren.","Ein Mähdrescher wird durch die hintere Achse gelenkt. An der Vorderseite ist er sehr breit. Daher ist es notwendig, nach links auszuschwenken, um beim Abbiegen nichts rechtsseitig Liegendes zu streifen.","Gerade wegen der Hinterradlenkung schwenkt der hintere Teil besonders stark aus."],"rn":89},{"n":"1.1.07-013","t":"Sie fahren hinter einem landwirtschaftlichen Fahrzeug mit hoch beladenem Anhänger. Womit müssen Sie rechnen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Der Zug hat wegen der Beladung einen besonders kurzen Bremsweg","Vor allem beim Bremsen oder beim Abbiegen können Teile der Ladung herunterfallen","Die Blinker können verdeckt sein, so dass schlecht zu erkennen ist, wenn der Zug abbiegen will"],"co":[1,2],"ex":["Das Gegenteil ist der Fall. Durch die schwere Beladung muss mehr Gewicht gebremst werden und der Bremsweg verlängert sich.","Laut § 23 der StVO muss ein Kraftfahrzeugführer seine Ladung so sichern, dass diese ihn und andere Verkehrsteilnehmer nicht gefährdet. Hiervon kann jedoch nicht automatisch ausgegangen werden, da sich die Befestigung der Ladung beispielsweise während der Fahrt ungeplant lösen kann. Vor allem lockere Ladung wie z.B. Stroh kann nicht umfassend gesichert werden und so können vereinzelte Strohhalme von der Ladefläche fliegen.","Daher sollte mit ausreichend Abstand gefahren werden, um so plötzlich starkes Abbremsen oder Auffahrunfälle zu vermeiden."],"rn":90},{"n":"1.1.07-017","t":"Worauf stellen Sie sich in dieser Situation ein?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- abbremsen und die Straßenmitte nicht überfahren","- ausscheren und die Straßenmitte überfahren","- überholen, ohne die Straßenmitte zu überfahren"],"co":[1],"ex":["Das wäre die angebrachte Reaktion in diesem Moment. Hiervon kannst du jedoch nicht ausgehen.","Der entgegenkommende PKW hat den Blinker angesetzt, was signalisiert, dass er die Fahrradfahrerin überholen möchte. Deswegen solltest du langsamer fahren, dich möglichst rechts halten und bremsbereit sein.","Dann würde er die Radfahrerin stark schneiden. Um diese beim Überholvorgang nicht zu gefährden, muss der PKW die Straßenmitte überfahren."],"v":["https://video4.kalaiwa.de/assets/1107017v1440.mp4"],"rn":91},{"n":"1.1.07-023","t":"Was sollten Sie bei Elektrofahrrädern (E-Bikes) im Straßenverkehr beachten?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- im Aussehen schwer von herkömmlichen Fahrrädern unterschieden werden","- in der Geschwindigkeit leicht unterschätzt werden","- leicht am Motorgeräusch erkannt werden"],"co":[0,1],"ex":["Der Motor von E-Bikes ist häufig so ins Radgestell eingebaut, dass er von außen kaum ersichtlich ist. So kann man sie nur bei genauer Betrachtung von herkömmlichen Fahrrädern unterscheiden.","Da sie normalen Fahrrädern sehr ähneln, man hiermit jedoch weitaus schneller fahren kann, werden E-Bikes leicht in ihrer Geschwindigkeit unterschätzt.","Der Elektromotor macht keine Geräusche. Am Motorgeräusch können Elektrofahrräder also nicht erkannt werden."],"rn":92},{"n":"1.1.07-101","t":"Sie wollen eine landwirtschaftliche Zugmaschine mit nach hinten herausragendem Anbaugerät überholen. Was ist zu beachten?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Die hintere Beleuchtung kann stark verschmutzt oder verdeckt sein, so dass eingeschaltete Blinkleuchten schlecht oder gar nicht zu sehen sind","Beim Abbiegen kann das Anbaugerät ausschwenken","Zugmaschinen können wegen ihrer niedrigen Geschwindigkeit immer gefahrlos überholt werden"],"co":[0,1],"ex":["Die Blinkleuchten sind im Verhältnis zu der Größe der Anbaugeräte meist sehr klein. Sie können noch zusätzlich durch aufgewirbelten Staub oder Dreck bei der Arbeit verschmutzt sein. Daher müssen Sie als Fahrer direkt hinter einem landwirtschaftlichen Fahrzeug immer darauf vorbereitet sein, dass es \"plötzlich\" abbiegt.","Je nach Art des Anbaugeräts ragt es über die hintere Achse des Traktors (landwirtschaftliche Zugmaschine) hinaus. Dadurch schwenkt es beim Abbiegen aus. Darauf muss geachtet werden.","Die Gefahr besteht bei landwirtschaftlichen Fahrzeugen nicht in der Geschwindigkeit, sondern darin, dass sie beim Abbiegen ausschwenken können oder durch Verschmutzung die Beleuchtung und Blinkeinrichtung nicht deutlich zu erkennen ist."],"rn":93},{"n":"1.1.07-113","t":"Sie fahren auf einer neu angelegten Straße durch bewaldetes Gebiet. Womit müssen Sie rechnen?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Mit einem Hindernis durch einen Wildunfall","Wild überquert unerwartet die Fahrbahn","Auf neu angelegten Straßen sind Wildunfälle nicht zu erwarten"],"co":[0,1],"ex":["Ein Fahrzeug oder ein verletztes oder totes Tier aus einem Wildunfall könnte auf der Straße liegen.","Die neue Straße könnte einen seit Jahrzehnten oder Jahrhunderten von Wildtieren genutzten Weg kreuzen. Die Tiere haben sich auf die neue Situation noch nicht eingestellt und können daher unverhofft plötzlich über die Fahrbahn laufen.","Wenn die neu angelegte Straße durch Wälder oder offenes unbewohntes Gebiet gebaut wird, ist mit Wildwechsel zu rechnen."],"rn":94},{"n":"1.1.07-117","t":"Zu welcher Tageszeit ist mit verstärktem Wildwechsel zu rechnen?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Während der Abenddämmerung","Im Morgengrauen","In der Mittagszeit"],"co":[0,1],"ex":["Wildtiere befinden sich je nach Rasse in der Abenddämmerung auf dem Weg zu ihrer Ruhestätte oder auf Futtersuche. Daher ist damit zu rechnen, dass Wildwechsel zu dieser Tageszeit die Fahrbahn quert.","Auch früh morgens befinden sich Wildtiere oft auf Futtersuche. Daher ist damit zu rechnen, dass Wild die Fahrbahn quert. Der Fahrbahnrand sollte daher zur Morgendämmerung gut beobachtet werden.","Morgens und Abends ist das Wildaufkommen am höchsten. Mittags ist daher vergleichsweise mit wenig Wildwechsel zu rechnen. Allerdings kann es auch zu dieser Tageszeit vorkommen, dass Wildtiere die Fahrbahn kreuzen. Daher ist zu jeder Tag- und Nachtzeit ein aufmerksames Fahrverhalten beim Durchqueren von Waldgebieten angebracht."],"rn":95},{"n":"1.1.07-118","t":"Mit welchen Gefahren müssen Sie vor allem in ländlichen Gebieten rechnen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Mit Fahrbahnverschmutzungen","Mit überbreiten landwirtschaftlichen Fahrzeugen","Mit langsamen landwirtschaftlichen Fahrzeugen"],"co":[0,1,2],"ex":["In ländlichen Gebieten sind viele Traktoren mit ihren Maschinen für die Feldarbeit auf den Straßen unterwegs. Oft wird Schmutz von den Feldern auf die Straße geschleppt, ohne dass dies der Fahrer bemerkt. Daher müssen musst du hier mit Fahrbahnverschmutzungen rechnen.","Die landwirtschaftlichen Fahrzeuge werden für die Feldarbeit verwendet. Viele Arbeitsgeräte haben Überbreite, um eine möglichst große Fläche auf einmal zu bearbeiten. Daher musst du in diesen Gebieten mit überbreiten landwirtschaftlichen Fahrzeugen rechnen.","Die landwirtschaftlichen Fahrzeuge werden für die Feldarbeit verwendet. Viele davon haben nur eine geringe Höchstgeschwindigkeit (25 - 40 km/h). Daher musst du in ländlichen Gebieten mit langsam fahrenden landwirtschaftlichen Fahrzeugen rechnen."],"rn":96},{"n":"1.1.07-119","t":"In der Dämmerung kommt Ihnen eine landwirtschaftliche Zugmaschine mit eingeschalteter Beleuchtung entgegen. Womit müssen Sie rechnen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Die Breite der Zugmaschine ist trotz der eingeschalteten Beleuchtung nicht immer erkennbar","Die Zugmaschine kann ein breiteres, schlecht erkennbares Arbeitsgerät mitführen","Die Zugmaschine kann 2 breitere Anhänger mitführen"],"co":[0,1,2],"ex":["Die meisten Traktoren (landwirtschaftliche Zugmaschinen) haben eine sehr breite Hinterachse. Durch eine verschmutzte Beleuchtung ist diese Breite bei Dämmerung nicht immer erkennbar.","Oft haben landwirtschaftliche Zugmaschinen (Traktoren) ein Arbeitsgerät zur Bearbeitung der Felder angehängt. Diese Arbeitsgeräte sind oft sehr breit und nicht gut ausgeleuchtet. Zudem kann die Beleuchtung durch Schmutz und Staub vom Feld schlecht zu erkennen sein.","Traktoren (landwirtschaftliche Zugmaschinen) dürfen 2 Anhänger ziehen. Diese sind meist breiter und größer als der Traktor selbst. In der Dämmerung sind sie manchmal schlecht erkennbar."],"rn":97},{"n":"1.1.07-120","t":"Was müssen Sie beachten, bevor Sie in einen Tunnel einfahren?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Sonnenbrille abnehmen","Nebelscheinwerfer einschalten","Auch am Tage in gut beleuchteten Tunneln mit Abblendlicht fahren"],"co":[0,2],"ex":["Trotz Beleuchtung sind Tunnel nie so hell, dass man eine Sonnenbrille brauchen würde. Um im Tunnel gut sehen zu können, solltest du deine Sonnenbrille abnehmen.","Im Tunnel entsteht kein Nebel, daher dürfen hier die Nebelscheinwerfer nicht eingeschaltet werden.","In einem Tunnel erfordern es die Sichtverhältnisse, das Abblendlicht einzuschalten."],"rn":98},{"n":"1.1.07-121","t":"Wie müssen Sie sich bei einem Stau im Tunnel verhalten?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Fahrzeug sichern und umgehend verlassen","Warnblinklicht einschalten","Bei Stillstand mit ca. 5 m Sicherheitsabstand zum Vordermann anhalten"],"co":[1,2],"ex":["Der Stau kann sich jeden Moment wieder auflösen. Fahrzeug sichern und umgehend verlassen wäre ein Verhalten in Notfallsituationen.","So können Fahrzeuge, die sich hinter dir befinden, rechtzeitig gewarnt werden. Man kann die Geschwindigkeit frühzeitig reduzieren und somit Auffahrunfälle, die häufig an Stauenden auftreten, vermeiden.","Um im Notfall noch eine Reaktionsmöglichkeit zu haben, solltest du 5 m Platz zwischen dir und deinem Vordermann lassen."],"rn":99},{"n":"1.1.07-122","t":"Wodurch kann die Aufmerksamkeit bei einer Tunneldurchfahrt beeinträchtigt werden?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Gute Fahrbahnmarkierung","Tunnellänge","Beleuchtungsreflexionen durch den Gegenverkehr"],"co":[1,2],"ex":["Eine gute Fahrbahnmarkierung ist hilfreich für den Autofahrer.","Ist der Tunnel sehr lang, dann kann sich das negativ auf die Aufmerksamkeit auswirken, weil sich die Wahrnehmung an den Anblick gewöhnt und man sich weniger aktiv konzentrieren muss.","Die Beleuchtung des Gegenverkehrs kann dich blenden oder sich im Fahrzeuglack anderer Autos spiegeln."],"rn":100},{"n":"1.1.07-125","t":"Welche grundlegenden Verhaltensregeln müssen Sie im Tunnel beachten?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Nicht wenden","Auch am Tage im gut beleuchteten Tunnel mit Abblendlicht fahren","Anweisungen und Informationen des Tunnelpersonals Folge leisten"],"co":[0,1,2],"ex":["Im Tunnel sollten jegliche Risiken, die Unfälle verursachen könnten, vermieden werden. Hierzu gehört auch das Wenden.","Entsprechend der StVO § 17 Abs. 1 müssen wir die vorgeschriebene Beleuchtung einschalten, wenn es die Sichtverhältnisse erfordern. Im Tunnel ist es, trotz teilweise guter Beleuchtung, immer erforderlich, das Abblendlicht einzuschalten.","Das Tunnelpersonal schreitet im Sonder- oder Notfall ein. Deshalb sollte seinen Aussagen Folge geleistet werden, um niemanden in eine Risikosituation zu bringen."],"rn":101},{"n":"1.1.07-136","t":"Wie verhalten Sie sich jetzt?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Verzögern und bremsbereit sein","Nach links ausweichen","Gleichmäßig weiterfahren"],"co":[0],"ex":["Es könnte passieren, dass der blaue PKW rückwärts rausfährt und dich aufgrund seines eingeschränkten Sichtfelds nicht rechtzeitig sieht. Reduziere daher deine Geschwindigkeit und halte dich bremsbereit.","Nach links ausweichen ist keine Option, da du sonst den heranfahrenden Motorradfahrer gefährden würdest.","Wenn der blaue PKW nun rückwärts rausfährt, dann könntest du möglicherweise nicht mehr rechtzeitig reagieren, wenn du gleichmäßig weiterfährst. Daher solltest du unbedingt deine Geschwindigkeit reduzieren und bremsbereit sein."],"v":["https://video4.kalaiwa.de/assets/1107136v1440.mp4"],"rn":102},{"n":"1.1.07-137","t":"Sie wollen nach rechts abbiegen. Wie sollten Sie sich verhalten?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["„Schulterblick“ durchführen","Den Radfahrer durchfahren lassen","Vor dem Radfahrer abbiegen"],"co":[0,1],"ex":["So gehst du sicher, dass sich kein weiterer Radfahrer in deinem toten Winkel befindet.","Du darfst den Radfahrer nicht gefährden. Daher musst du mit dem Rechtsabbiegen warten, bis er durchgefahren ist.","So würdest du ihn gefährden."],"i":["https://video2.kalaiwa.de/assets/1107137.webp"],"rn":103},{"n":"1.1.07-138","t":"Womit müssen Sie rechnen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Die Person neben dem Transporter könnte weiter auf die Fahrbahn treten","Fußgänger könnten vor dem Transporter die Fahrbahn überqueren","Das Motorrad könnte nach links ausscheren"],"co":[0,1,2],"ex":["Vielleicht muss die Person etwas aus dem Transporter ausladen und somit weiter auf die Fahrbahn treten. Fahre hier langsam und halte dich bremsbereit.","Der Transporter könnte die Sicht auf Fußgänger verdecken. Fahre hier sehr langsam, vorsichtig und in Bremsbereitschaft, um niemanden zu gefährden.","Es könnte passieren, dass der Motorradfahrer nach links ausschert, um die Radfahrerin zu überholen."],"i":["https://video4.kalaiwa.de/assets/1107138.webp"],"rn":104},{"n":"1.1.07-139","t":"Vor dem Motorrad möchte ein Pkw auf die Fahrbahn zurücksetzen. Womit müssen Sie rechnen?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Dass mein Bremsweg länger als normal wird","Dass der Pkw weiter zurücksetzt","Dass das Motorrad plötzlich abgebremst wird"],"co":[0,1,2],"ex":["Die Straße ist verschneit und eisig. So haben die Reifen weniger Haftung auf der Fahrbahn und der Bremsweg ist länger. Fahre hier langsam und vorausschauend.","Das ist bereits erkennbar. Du kannst davon ausgehen, dass der Motorradfahrer darauf reagiert. Fahre daher sehr langsam und bremsbereit.","Um den PKW ungehindert ausparken lassen zu können, muss der Motorradfahrer abbremsen. Darauf musst du vorbereitet sein."],"i":["https://video4.kalaiwa.de/assets/1107139.webp"],"rn":105},{"n":"1.1.07-141","t":"Warum sind Sie besonders gefährdet, wenn Sie ein Zweirad fahren?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Weil ich leicht zu übersehen bin","Weil meine Geschwindigkeit unterschätzt werden kann","Weil ich bei Unfällen ein höheres Verletzungsrisiko habe"],"co":[0,1,2],"ex":["Kraftfahrzeuge sind aufgrund ihrer Größe auffälliger als Zweiradfahrer. Deswegen sollten Zweiradfahrer besonders aufmerksam und vorsichtig fahren und einen Helm tragen. Auch auffällige Kleidung ist hier hilfreich.","Wird generell die Geschwindigkeit eines Verkehrsteilnehmers unterschätzt, kann dies gefährlich werden.","Zweiradfahrer sind aufgrund der Beschaffung des Gefährtes weniger geschützt, als Personen, die sich in Kraftfahrzeugen befinden."],"rn":106},{"n":"1.1.07-142","t":"Auf einer stark befahrenen Straße mit mehreren Fahrstreifen haben Sie sich zum Linksabbiegen eingeordnet. Sie möchten nun stattdessen nach rechts abbiegen. Wie verhalten Sie sich?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich biege nach links ab","Ich biege im großen Bogen nach rechts ab","Ich fahre mit eingeschaltetem Warnblinklicht rückwärts"],"co":[0],"ex":["Die Straße ist stark befahren und du hast dich bereits eingeordnet. Daher musst du nach links abbiegen und bei Gelegenheit wenden. Sich jetzt rechts einzuordnen, würde den Verkehrsfluss behindern und wäre riskant.","So würdest du dich und andere Verkehrsteilnehmer gefährden.","Dieses Verhalten ist in keiner Verkehrssituation angebracht."],"rn":107},{"n":"1.1.07-143","t":"Auf meiner Fahrtroute befindet sich ein Tunnel. Was sollte ich wissen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich sollte wissen, wie Fluchtwege in Tunneln ausgewiesen sind","Ich sollte wissen, wie ich mein Fahrzeug abstelle und verlasse, wenn ich nicht mehr weiterfahren kann","Ich kann darauf vertrauen, dass im Notfall immer rechtzeitig Hilfskräfte zur Stelle sind"],"co":[0,1],"ex":["Fluchtwege in Tunneln sind mit Schildern ausgewiesen, die die Richtung zum nächstgelegenen Fluchtweg zeigen.","Wenn du im Tunnel in die Situation gerätst, dein Fahrzeug verlassen zu müssen, dann schalte den Motor ab, lass den Zündschlüssel stecken -für den Fall, dass Einsatzkräfte dein Fahrzeug wegfahren müssen- , schließe alle Fenster und Türen und verlasse auf schnellstem Weg zu Fuß den Tunnel.","Davon kannst du nicht ausgehen. Du musst für den Notfall vorbereitet sein."],"rn":108},{"n":"1.1.07-145","t":"Während der Fahrt in einem Tunnel haben Sie Ihr Fahrzeug wegen eines Feuers noch im Tunnel abstellen müssen. Wie verhalten Sie sich jetzt?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich schließe mein Fahrzeug ab","Ich löse Feueralarm an der Notrufstation aus","Ich lösche das Feuer soweit möglich"],"co":[1,2],"ex":["Du darfst dein Fahrzeug nicht abschließen.","Dadurch werden die Einsatzkräfte informiert.","Du solltest das Feuer aber nur im Anfangsstadium versuchen, selbst zu löschen. Ist es bereits fortgeschritten, dann musst du dich vom Feuer entfernen und den Tunnel schnellstmöglich über den nächstgelegenen Notausgang verlassen."],"rn":109},{"n":"1.1.07-146","t":"Womit müssen Sie rechnen?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- im rechten Fahrstreifen bleibt","- plötzlich stehen bleibt","- weiter ausschwenkt"],"co":[1,2],"ex":["Der LKW blinkt nach rechts und schert nach links aus. Daher kannst du davon ausgehen, dass er nach rechts abbiegen wird.","Eine Fußgängerin überquert die Straße, in die der LKW-Fahrer einbiegen will. Daher ist es wahrscheinlich, dass er vor dem Abbiegen anhalten muss, um diese nicht zu behindern.","Der LKW muss weiter nach links ausscheren, um nach rechts abbiegen zu können."],"v":["https://video2.kalaiwa.de/assets/1107146v1440.mp4"],"rn":110},{"n":"1.1.07-147","t":"Worauf müssen Sie jetzt achten?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf den vorausfahrenden Pkw","Auf das Fahrrad","Auf das Motorrad"],"co":[0,1],"ex":["Dieser möchte ebenfalls rechts abbiegen und wird zuvor wahrscheinlich am Fußgängerüberweg anhalten, damit der Passant diesen überqueren kann.","Im rechten Rückspiegel siehst du, das hinter dir ein Radfahrer angefahren kommt. Diesen musst du vorbeilassen, bevor du nach rechts abbiegen darfst.","Das Motorrad ist bereits vor dir geradeaus gefahren. Darauf musst du also nicht achten."],"v":["https://video2.kalaiwa.de/assets/1107147v1440.mp4"],"rn":111},{"n":"1.1.07-148","t":"Weshalb müssen Sie hier warten?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Wegen der Radfahrerin","Wegen des Fußgängers","Wegen des grünen Pkws"],"co":[0],"ex":["Das grüne Auto will geradeaus fahren und hält vorschriftsgemäß, um die Kreuzung nicht zu verstopfen. Die Radfahrerin fährt noch und es ist noch unklar, in welcher Richtung sie weiterfahren möchte. Unabhängig davon hat sie Vorfahrt vor dir. Deshalb musst du sie die Kreuzung durchfahren lassen, bis du selbst fahren darfst.","Der Fußgänger befindet sich auf der anderen Seite der Kreuzung. Du kommst in dieser Verkehrssituation nicht mit ihm in Berührung.","Der grüne PKW hält vor der Kreuzung, um diese nicht zu verstopfen. Eigentlich müsstest du ihm laut Verkehrszeichen Vorfahrt gewähren. In diesem Fall kannst du jedoch vor ihm fahren."],"v":["https://video4.kalaiwa.de/assets/1107148v1440.mp4"],"rn":112},{"n":"1.1.07-149","t":"Weshalb müssen Sie hier warten?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Wegen der Radfahrerin","Wegen des roten Pkws","Wegen des Fußgängers"],"co":[1],"ex":["Die Radfahrerin fährt mittig hinter dir. Sie ist gut sichtbar im Rückspiegel und kein Grund für dich zu warten.","Der rote PKW möchte links abbiegen und hat Vorfahrt vor dir.","Der Fußgänger ist weit entfernt auf der anderen Straßenseite. Wegen ihm musst du nicht warten."],"v":["https://video2.kalaiwa.de/assets/1107149v1440.mp4"],"rn":113},{"n":"1.1.07-154","t":"Wie verhalten Sie sich bei einer Tunneldurchfahrt richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["In einem Tunnel mit Gegenverkehr orientiere ich mich am rechten Fahrbahnrand","Ich fahre mit verringertem Abstand, damit ich mich an den Schlussleuchten des vorausfahrenden Fahrzeugs orientieren kann","Ich präge mir Sicherheitseinrichtungen wie Notausgänge und Notruftelefone ein"],"co":[0,2],"ex":["Hierdurch werden deine Augen nicht so stark vom Gegenverkehr geblendet.","Du musst immer einen ausreichenden Abstand zum vorausfahrenden Fahrzeug einhalten.","Das ist wichtig, um in Notfallsituationen schnell reagieren zu können."],"rn":114},{"n":"1.1.07-158","t":"Mit welchem Verhalten von Radfahrern müssen Sie rechnen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- keine Beleuchtung bei Dunkelheit","- Radwege auf der falschen Seite","- Einbahnstraßen in beide Richtungen"],"co":[0,1,2],"ex":["Natürlich kann es passieren, dass Radfahrer keine (funktionierende) Beleuchtung an ihrem Fahrrad haben und dennoch bei Dunkelheit fahren.","Es muss immer damit gerechnet werden, dass Radfahrer auf Radwegen entgegen der Fahrtrichtung unterwegs sind.","Obwohl Radfahrer nicht entgegengesetzt in Einbahnstraßen hinein fahren dürfen, musst du damit rechnen, dass sie in beiden Richtungen unterwegs sind."],"rn":115},{"n":"1.1.07-163","t":"Warum ist das Vorbeifahren an dieser Unfallsituation gefährlich?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Weil die Verkehrslage unklar ist","Weil Folgeunfälle möglich sind","Weil Fußgänger übersehen werden können"],"co":[0,1,2],"ex":["Die Verkehrslage wurde von Feuerwehr oder Polizei noch nicht klar geregelt und gesichert. Dadurch ist sie unklar und unübersichtlich. Ungeregeltes Vorbeifahren könnte zu Unfällen führen.","Durch die schlechte Sicht und die unübersichtliche Verkehrslage kann es schnell zu Folgeunfällen kommen. Hier solltest du abwarten, bis die Verkehrslage klarer wird.","Bei einem Unfall befinden sich vermehrt Personen, z. B. Rettungsdienst, Ersthelfer oder Passanten, auf der Fahrbahn. Diese können leicht übersehen werden."],"i":["https://video4.kalaiwa.de/assets/1107163.webp"],"rn":116},{"n":"1.1.07-167","t":"Sie fahren durch einen Tunnel. Welche Besonderheit besteht dabei?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- sind Sicherheitseinrichtungen wie Notausgänge und Notruftelefone ausgeschildert","- kann ich durch starke Fahrgeräusche abgelenkt werden","- kann ich durch Lichteffekte abgelenkt werden"],"co":[0,1,2],"ex":["In einem Tunnel sind die Notausgänge und SOS-Notruftelefone gut sichtbar ausgeschildert und ausgeleuchtet. In einem Notfall solltest du die Einrichtungen nutzen.","Nirgends im Straßenverkehr wird mehr Schall auf die Verkehrsteilnehmer reflektiert als in einem Tunnel. Die Geräusche sind deshalb lauter als sonst und können dich ablenken.","Die starke und unterschiedliche Beleuchtung sowie die Lichter der anderen Verkehrsteilnehmer könnten dich im dunklen Tunnel irritieren."],"rn":117},{"n":"1.1.07-170","t":"Sie befahren einen Straßenabschnitt, für den ein Stau gemeldet wurde. Wie verhalten Sie sich richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich nutze den Notbremsassistenten zum sicheren Anhalten vor dem Stauende","Ich fahre in Kurven und vor Kuppen besonders aufmerksam","Ich verfolge weiterhin die Verkehrsmeldungen"],"co":[1,2],"ex":["Es ist nicht ratsam, sich zum Halten vor einem Stauende ausschließlich auf den Notbremsassistenten zu verlassen. Das sehr abrupte Stoppen deines Fahrzeuges kann außerdem dazu führen, dass Personen hinter dir nicht rechtzeitig bremsen können und auffahren.","Du weißt bereits, dass sich auf deiner Strecke ein Stau befindet, den du jederzeit erreichen kannst. Daher solltet du vor allem in Kurven und vor Kuppen besonders aufmerksam fahren. Ein mögliches Stauende ist an diesen Stellen erst später einsehbar, sodass du schneller reagieren musst.","Die Verkehrsmeldungen informieren dich über alle Änderungen und Neuigkeiten, die den Stau betreffen. Du solltest sie deswegen weiterhin hören. So erfährst du auch, wann du ungefähr auf das Stauende treffen wirst und kannst dich besser darauf einstellen."],"rn":118},{"n":"1.1.07-171","t":"Warum müssen Sie jetzt anhalten?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Wegen der Radfahrerin","Wegen der Fußgänger","Wegen des Lkws"],"co":[0],"ex":["Von links kommt eine Radfahrerin angefahren, die in Kürze die Straße vor dir auf dem Radweg überqueren wird. Das \"Vorfahrt gewähren\" Zeichen in Kombination mit dem Fahrrad Zusatzzeichen zeigt dir, dass du auf mögliche Radfahrer achten und ihnen Vorfahrt gewähren musst. Daher musst du jetzt anhalten und die Radfahrerin vorbeifahren lassen.","Die zwei Fußgänger unterhalten sich und machen keine Anstalten, die Straße zu überqueren. Daher musst du auch nicht wegen ihnen anhalten.","Der LKW fährt auf einer zweispurigen Straße auf der linken Spur. Du kannst problemlos auf die rechte Spur der Fahrbahn auffahren, nachdem die Radfahrerin vorbeigefahren ist. Der LKW ist somit kein Grund für dich anzuhalten."],"v":["https://video4.kalaiwa.de/assets/1107171v1440.mp4"],"rn":119},{"n":"1.1.07-173","t":"Während der Fahrt überquert vor Ihrem Fahrzeug ein Reh die Fahrbahn. Was sollten Sie beachten?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Das Reh kann mitten auf der Fahrbahn stehen bleiben","Dem Reh können weitere Tiere folgen","Das Reh kann durch Einschalten des Fernlichts verscheucht werden"],"co":[0,1],"ex":["Rehe können beim Überqueren von Straßen mitten auf der Fahrbahn stehen bleiben. Damit solltest du rechnen und bereit sein, bei Wildwechsel bis zum Stillstand abzubremsen.","Kreuzt ein Reh deine Fahrbahn, solltest du sehr aufmerksam sein und damit rechnen, dass ihm weitere Rehe folgen. Reduziere deine Geschwindigkeit, damit du eine Kollision mit folgenden Tieren vermeiden kannst. Mithilfe der Warnblinkanlage kannst du anderen Verkehrsteilnehmern die Gefahr signalisieren.","Wildtiere und insbesondere Rehe neigen dazu, gebannt ins Scheinwerferlicht zu starren. Sie bewegen sich dann vor Schreck nicht mehr und du kannst nicht damit rechnen, sie durch Fernlicht von der Fahrbahn zu verscheuchen."],"rn":120},{"n":"1.1.07-006-B","t":"Warum müssen Sie hier besonders vorsichtig sein?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Weil ein Fahrzeug von rechts kommen könnte","Weil das von links kommende Auto Vorfahrt hat","Weil beim Bremsen erhöhte Rutschgefahr besteht"],"co":[0,2],"ex":["Dass rechts von dir eine Straße liegt, siehst du am Straßenschild. Allerdings ist diese komplett mit Laub bedeckt, wodurch sie schwerer zu erkennen ist. Es besteht die Möglichkeit, dass von hier ein Auto kommt und du diesem laut Grundregel \"rechts vor links\" Vorfahrt gewähren musst. Da wegen des Laubs für euch beide Rutschgefahr besteht, solltest du dich mit besonderer Vorsicht ans Verkehrsgeschehen herantasten.","Hier gilt die Grundregel \"rechts vor links\". Du bist rechts von diesem Auto und hast somit Vorfahrt.","Aufgrund des Laubs am Straßenrand besteht die Gefahr, dass die Reifen, vor allem beim Bremsen, nicht mehr so gut am Boden haften. Das Fahrzeug könnte ins Rutschen geraten. Daher solltest du hier besonders aufmerksam und langsam fahren."],"i":["https://video2.kalaiwa.de/assets/1107006b.webp"],"rn":121},{"n":"1.1.07-014-M","t":"Womit müssen Sie rechnen?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Dass ich vor der Kreuzung halten muss","Mit einem Fahrzeug, das am Bus vorbeifährt","Mit Personen, die die Fahrbahn überqueren"],"co":[0,1,2],"ex":["Weil du keine Einsicht in die Straße hast, in die du einbiegen willst, musst du hier sehr aufmerksam fahren. Es kann sein, dass du halten musst, weil Fußgänger die Straße queren oder um den Bus aus der Straße herausfahren zu lassen.","Aufgrund der Hecke kannst du nicht in die Straße einsehen. Fahre deshalb vorsichtig und langsam heran und taste dich in die Kurve hinein.","In der Straße, in die du einbiegen möchtest, steht ein Bus. Es ist möglich, dass hier Personen die Fahrbahn überqueren, um ein- oder auszusteigen."],"i":["https://video4.kalaiwa.de/assets/1107014m.webp"],"rn":122},{"n":"1.1.07-015-M","t":"Wie verhalten Sie sich in dieser Situation?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Geschwindigkeit vermindern","Bremsbereit sein","Unverändert weiterfahren"],"co":[0,1],"ex":["Der Traktor fährt mit eingeschränkter Sicht auf die Straße aus der Einfahrt heraus. Deshalb: Runter vom Gas und bremsbereit sein.","Der Traktorfahrer sieht nicht in die Straße ein und kann dich deshalb beim Herausfahren nicht beachten. Daher musst du bremsbereit sein.","Der Traktorfahrer sieht dich vermutlich erst spät, da seine Sicht eingeschränkt ist. Ein unverändertes Weiterfahren könnte ihn am Herausfahren hindern oder schlimmstenfalls zu einem Zusammenstoß führen."],"i":["https://video4.kalaiwa.de/assets/1107015m.webp"],"rn":123},{"n":"1.1.07-019-M","t":"Sie möchten an der Kreuzung nach rechts abbiegen. Was ist richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich darf den Schutzstreifen für Radfahrer nur mit Schrittgeschwindigkeit überqueren","Ich wechsle den Fahrstreifen möglichst frühzeitig","Ich darf Radfahrer auf dem Schutzstreifen nicht behindern"],"co":[1,2],"ex":["Wenn du den Schutzstreifen nur mit Schrittgeschwindigkeit überquerst, behinderst du Radfahrer, die selbst schneller als Schrittgeschwindigkeit fahren.","Du solltest beim Spurwechsel nicht auf dem Schutzstreifen zum Stehen kommen. Deshalb solltest du möglichst früh deinen Spurwechsel vollzogen haben.","Du darfst den Schutzstreifen nur zum Abbiegen, Spurwechseln oder zum Ausweichen befahren. Wenn du ihn befährst, darfst du keine Radfahrer behindern."],"i":["https://video2.kalaiwa.de/assets/1107019m.webp"],"rn":124},{"n":"1.1.07-020-M","t":"Wann kann es hier zu einer gefährlichen Situation kommen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Wenn der Radfahrer am Ende des Radweges anhält","Wenn der Radfahrer auf meine Fahrbahn wechselt","Wenn ich unvermindert weiterfahre"],"co":[1,2],"ex":["Dann kannst du ungehindert weiterfahren und eine gefährliche Situation wird vermieden.","Deswegen musst du abbremsen, um ausreichend Abstand zu ihm halten zu können.","Der Radweg endet, weswegen der Fahrradfahrer wahrscheinlich auf die Straße wechseln wird. Fährst du unvermindert weiter, dann behinderst du ihn dabei oder gefährdest ihn sogar."],"i":["https://video2.kalaiwa.de/assets/1107020m.webp"],"rn":125},{"n":"1.1.07-025-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich weiche auf die linke Fahrbahnhälfte aus","Ich bin bremsbereit","Ich beobachte den Radfahrer aufmerksam"],"co":[1,2],"ex":["Du solltest nicht auf die linke Fahrbahnhälfte ausweichen, da sich dort ein entgegenkommendes Auto nähert. Es würde wahrscheinlich zu einer Kollision mit dem Gegenverkehr kommen.","Der Radfahrer hat sein Fahrrad in Richtung der Fahrbahn ausgerichtet und sieht so aus, als wenn er jeden Moment losfahren wird. Du solltest daher bremsbereit sein, um in diesem Fall schnell reagieren und rechtzeitig bremsen zu können.","Du musst den Radfahrer aufmerksam beobachten, da er kurz davor ist, loszufahren und den Kopf von der Fahrbahn abgewandt hat. Er sieht dich deswegen vermutlich nicht. Du kannst nicht damit rechnen, dass er selbst aufmerksam ist und abwartet, bis du vorbei gefahren bist."],"i":["https://video4.kalaiwa.de/assets/1107025m.webp"],"rn":126},{"n":"1.1.07-103-M","t":"Womit müssen Sie hinter dieser Straßenkuppe rechnen?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf meinem Fahrstreifen kann sich ein langsam fahrendes Fahrzeug befinden","Dort kann ein Fahrzeug liegen geblieben sein","Es kann ein Fahrzeug entgegenkommen, das meinen Fahrstreifen mitbenutzt"],"co":[0,1,2],"ex":["Es kann sein, dass sich hinter der Kuppe auf deiner Fahrbahn ein langsam fahrendes Fahrzeug befindet.","Es ist möglich, dass sich hinter der Kuppe ein Fahrzeug befindet, das eine Panne hat.","Der Gegenverkehr könnte deinen Fahrstreifen mitbenutzen."],"i":["https://video4.kalaiwa.de/assets/1107103m.webp"],"rn":127},{"n":"1.1.07-107-B","t":"Worauf müssen Sie sich einstellen?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf Arbeiter und Baugeräte auf der Fahrbahn","Auf eine unebene und verschmutzte Fahrbahn","Auf einen durch Polizei geregelten Verkehrsablauf"],"co":[0,1],"ex":["Es ist sehr wahrscheinlich, dass sich an der Baustelle Arbeiter und Baugeräte befinden. Deswegen solltest du hier besonders langsam und aufmerksam fahren, um niemanden zu gefährden.","Du befindest dich vor einer Baustelle. Es ist möglich, dass Baumaterialien auf die Straße gelangt sind und diese nun verschmutzt und rutschig ist. Die Straße kann zudem uneben sein, weil diese bearbeitet oder erneuert wird.","Weil die Baustelle keine Ausnahmesituation wie einen Unfall oder einen Ampelausfall darstellt, kann man nicht davon ausgehen, dass die Polizei den Verkehr regelt. Halte dich hier an die vorhandenen Verkehrsschilder."],"i":["https://video2.kalaiwa.de/assets/1107107b.webp"],"rn":128},{"n":"1.1.07-152-M","t":"Worauf müssen Sie beim Umschalten der Ampel auf „Grün“ achten?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf den Gegenverkehr","Auf das Motorrad","Auf den Fußgänger"],"co":[1,2],"ex":["Der Gegenverkehr spielt in dieser Verkehrssituation keine Rolle.","Dieses hat sich links neben dir eingeordnet. Es kann sein, dass es beim Umschalten der Ampel auf \"Grün\" beschleunigt. Stelle dich darauf ein, es vorbeifahren zu lassen, bevor du selbst anfährst.","Du darfst erst fahren, wenn der Fußgänger die Straße vollständig überquert hat."],"v":["https://video4.kalaiwa.de/assets/1107152mv1440.mp4"],"rn":129},{"n":"1.1.07-153-M","t":"Worauf müssen Sie sich in dieser Situation einstellen?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Dass Gegenverkehr auftaucht","Dass der Lkw-Fahrer auf die Fahrbahn springt","Dass Verkehrszeichen durch den Lkw verdeckt sind"],"co":[0,1,2],"ex":["Dieser könnte aufgrund des orangefarbenen LKWs erst spät erkannt werden. Fahre daher mit verminderter Geschwindigkeit heran und fahre erst langsam und vorsichtig vorbei, wenn du die Verkehrssituation einschätzen kannst.","Der LKW-Fahrer steht auf dem Trittbrett. Es ist möglich, dass er von diesem herunter auf die Fahrbahn springt.","Aufgrund der Höhe und Positionierung des LKWs ist es möglich, dass er Verkehrszeichen verdeckt."],"i":["https://video4.kalaiwa.de/assets/1107153m.webp"],"rn":130},{"n":"1.1.07-155-M","t":"Worauf müssen Sie jetzt achten?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf die Radfahrerin rechts","Auf den Radfahrer links","Auf den grünen Pkw"],"co":[0,1],"ex":["Die Radfahrerin rechts von dir war zuvor auf dem rechten Radweg. Möglicherweise ist sie auf den Parkstreifen abgefahren, um nach links in die Straße einzubiegen. Warte, bis sie vorausgefahren ist, bevor du nach links abbiegst.","Noch ist unklar, ob der Radfahrer nach links abbiegen oder geradeaus weiterfahren möchte. In jedem Fall musst du mit dem Abbiegen warten, bis er durchgefahren ist.","Auf den grünen PKW musst du nicht achten. Er parkt weit vor dir und hat keinen Einfluss auf deine Verkehrssituation."],"v":["https://video2.kalaiwa.de/assets/1107155mv1440.mp4"],"rn":131},{"n":"1.1.07-156-M","t":"Wie sollten Sie sich jetzt verhalten?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich halte das Lenkrad gerade und fest","Ich weiche nach links aus","Ich führe eine Gefahrbremsung durch"],"co":[0,2],"ex":["Nach rechts oder links auszuweichen wäre riskant und kann Menschenleben in Gefahr bringen. Wenn kontrollierte Ausweichmanöver nicht gefahrlos möglich sind, sollte das Lenkrad stets gerade und fest gehalten werden.","Beim Ausweichen nach links würdest Du vermutlich mit dem entgegenkommenden Lkw kollidieren.","Bei größeren Tieren wie Hunden oder Wildtieren auf der Fahrbahn ist eine Gefahrenbremsung zwingend notwendig. Ein Zusammenstoß gefährdet nicht nur das Tier, sondern auch Fahrer und Mitfahrer."],"v":["https://video2.kalaiwa.de/assets/1107156mv1440.mp4"],"rn":132},{"n":"1.1.07-157-M","t":"Worauf sollten Sie sich in dieser Situation einstellen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Das Quad fährt plötzlich an","Der Bus schwenkt beim Anfahren kurz auf meinen Fahrstreifen aus","Personen betreten hinter dem Bus die Fahrbahn"],"co":[1,2],"ex":["Davon ist nicht auszugehen, da sich vor dem Quad eine Person aufhält.","Um aus der Haltestellenbucht herausfahren zu können, muss der Bus einen Bogen fahren und ein Stück weit auf die Gegenfahrbahn ausscheren.","Da die Fußgänger dich wegen dem Bus noch nicht sehen, laufen sie eventuell schon über die Straße."],"v":["https://video2.kalaiwa.de/assets/1107157mv1440.mp4"],"rn":133},{"n":"1.1.07-159-M","t":"Worauf müssen Sie sich hier einstellen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Personen betreten die Fahrbahn","Entgegenkommende Fahrzeuge biegen nach links ab","Fahrzeuge biegen auf die Fahrbahn ein"],"co":[0,1,2],"ex":["Vor dir befindet sich ein Wanderparkplatz. Du musst mit Personen auf der Straße rechnen. Zwei sind sogar erkennbar.","Auf dem Wanderparkplatz befinden sich Fahrzeuge. Du musst damit rechnen, dass entgegenkommende Fahrzeuge deine Fahrbahn überqueren könnten.","Auf dem Wanderparkplatz vor dir auf der rechten Seite befinden sich einige Pkws. Du musst damit rechnen, dass diese losfahren und in deine Fahrbahn einfahren."],"i":["https://video4.kalaiwa.de/assets/1107159m.webp"],"rn":134},{"n":"1.1.07-160-M","t":"Warum müssen Sie jetzt anhalten?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Wegen des Radfahrers","Wegen des gelben Lkws","Weil die Verkehrssituation unübersichtlich ist"],"co":[0,2],"ex":["Der Radfahrer kommt von der rechten Seite und wird deine Fahrbahn auf dem Radweg kreuzen. Er hat Vorrang. Die Beschilderung zeigt an, dass der Querverkehr Vorfahrt hat. Zudem zeigt das Zusatzschild an, dass Radfahrer von rechts und links kreuzen.","Du möchtest rechts abbiegen. Der gelbe Lkw fährt in die Gegenrichtung. Damit stellt der Lkw keine Gefahr dar.","Der graue Pkw am rechten Fahrbahnrand verdeckt den Radweg und einen Teil der Fahrbahn, auf die du abbiegen möchtest. Um beim rechts Abbiegen keine Verkehrsteilnehmer zu gefährden, solltest du zuerst anhalten und dir einen Überblick verschaffen."],"v":["https://video4.kalaiwa.de/assets/1107160mv1440.mp4"],"rn":135},{"n":"1.1.07-161-M","t":"Sie möchten geradeaus weiterfahren. Wie verhalten Sie sich in dieser Situation richtig?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich lasse den Elektroroller die Fahrbahn überqueren","Ich lasse das rote Fahrzeug abbiegen","Ich überquere die Kreuzung als Erster"],"co":[0,1],"ex":["Hier gilt es \"defensiv\" zu fahren. Das bedeutet umsichtig, nicht unbedingt auf sein Recht bestehend zu fahren und mit Fehlern anderer zu rechnen. Der Elektroroller hat keine Vorfahrt, um einen Unfall zu vermeiden, solltest du ihn trotzdem überqueren lassen.","Da keine anderen Verkehrszeichen zu sehen sind, gilt rechts vor links. Das rote Fahrzeug steht rechts von dir und hat deshalb Vorfahrt.","Du befindest dich zuerst auf einer Vorfahrtstraße. Durch dein Abbiegen verlässt du diese und somit gilt dann an der Kreuzung rechts vor links. Das rote Fahrzeug hat Vorfahrt und den Elektroroller solltest du aus Sicherheitsgründen überqueren lassen."],"v":["https://video4.kalaiwa.de/assets/1107161mv1440.mp4"],"rn":136},{"n":"1.1.07-162-M","t":"Sie möchten ausparken. Wie beurteilen Sie die Situation richtig?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- Fahrzeuge sehe ich erst spät","- Fahrzeugführer lassen mir beim Ausparken meinen Vorrang","- Fahrzeugführer sehen mich erst spät"],"co":[0,2],"ex":["Der hinter dir parkende Lkw versperrt dir die Sicht auf den von hinten anfahrenden Verkehr. Vorbeifahrende Fahrzeuge können dadurch erst spät entdeckt und somit übersehen werden.","Dadurch, dass vorbeifahrende Fahrzeugführer eine eingeschränkte Sicht auf dich haben, können sie dich erst spät erkennen. Deshalb ist es unwahrscheinlich, dass sie dir den Vorrang lassen. Du solltest lieber sicher gehen, dass der Weg frei ist.","Durch den hinter dir parkenden Lkw ist die Sicht auf dein parkendes Auto eingeschränkt. Fahrzeugführer, die von hinten angefahren kommen, haben eine schlechte Sicht auf dich und könnten dich möglicherweise zu spät sehen."],"i":["https://video4.kalaiwa.de/assets/1107162m.webp"],"rn":137},{"n":"1.1.07-164-M","t":"Worauf müssen Sie hier beim Rechtsabbiegen achten?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf das Motorrad","Auf den Gegenverkehr","Auf den Radfahrer"],"co":[2],"ex":["Das Motorrad steht parkend am Straßenrand und beeinträchtigt dich beim Rechtsabbiegen nicht.","Das entgegenkommende Fahrzeug fährt geradeaus und beeinflusst dich deshalb hier beim Rechtsabbiegen nicht.","Der Radfahrer hat Vorfahrt. Beim Rechtsabbiegen musst du immer darauf achten, ob sich Fußgänger oder Radfahrer nähern. Sie dürfen vor dir die Straße überqueren. Schaue hierfür in den Spiegel und nutze außerdem den Schulterblick, um auch den toten Winkel einsehen zu können."],"v":["https://video2.kalaiwa.de/assets/1107164mv1440.mp4"],"rn":138},{"n":"1.1.07-165-M","t":"Wie verhalten Sie sich jetzt richtig?","p":5,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich führe eine Gefahrbremsung durch","Ich überquere die Kreuzung zügig","Ich bremse leicht ab"],"co":[0],"ex":["Der Roller scheint dich nicht kommen zu sehen und nimmt dir die Vorfahrt. Um einen Unfall zu vermeiden, musst du sofort eine Gefahrenbremsung durchführen.","Würdest du die Kreuzung überqueren, würde es zu einem Unfall mit dem Roller kommen.","Bei deiner Geschwindigkeit reicht eine leichte Bremsung nicht aus, um eine Kollision zu verhindern."],"v":["https://video2.kalaiwa.de/assets/1107165mv1440.mp4"],"rn":139},{"n":"1.1.07-166-M","t":"Womit müssen Sie in dieser Situation rechnen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Der Radfahrer schert nach links aus","Der Radfahrer steigt ab, um mich vorbeizulassen","Mit Gegenverkehr"],"co":[0,2],"ex":["Der Radfahrer wird das parkende Auto überholen wollen und schert deshalb nach links aus.","Dass der Radfahrer absteigt, um dich vorbeizulassen, ist unwahrscheinlich.","Es ist mit Gegenverkehr zu rechnen. Da das Hindernis auf deiner Seite ist, musst du in diesem Fall warten."],"i":["https://video2.kalaiwa.de/assets/1107166m.webp"],"rn":140},{"n":"1.1.07-168-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich weiche nach links aus","Ich beschleunige aufgrund meines Vorrangs","Ich bremse ab"],"co":[2],"ex":["Links kommt dir ein Motorrad entgegen. Du kannst nicht ausweichen.","Du solltest nicht immer auf deinen Vorrang bestehen. Bremse ab und lasse das Auto einscheren, um keinen Unfall zu provozieren.","Das noch parkende blaue Fahrzeug möchte auf die Straße einfahren und hat dich offensichtlich übersehen. Du solltest abbremsen, um einen Unfall zu vermeiden."],"v":["https://video4.kalaiwa.de/assets/1107168mv1440.mp4"],"rn":141},{"n":"1.1.07-169-M","t":"Womit müssen Sie jetzt rechnen?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Der Radfahrer schert nach links aus","Der Fahrer des gelben Fahrzeugs öffnet die Fahrertür","Der blaue Lkw schert nach links aus"],"co":[0,1,2],"ex":["Das gelbe Fahrzeug blockiert den Weg für den Radfahrer. Daher musst du damit rechnen, dass der Radfahrer nach links ausscheren wird, um das gelbe Fahrzeug zu überholen und seinen Weg fortsetzen zu können.","Du kannst bereits am gesetzten rechten Blinker und dem Aufleuchten der roten Bremslichter erkennen, dass der Fahrer des gelben Fahrzeugs am rechten Fahrbahnrand anhalten möchte. Das Fahrzeug kommt jetzt zum Stehen und du musst damit rechnen, dass der Fahrer als Nächstes die Fahrertür öffnen wird, um auszusteigen.","Der blaue LKW, der zuvor am rechten Fahrbahnrand gehalten hat, fährt jetzt an. Er wird vermutlich nach links ausscheren, um seine Fahrt zu beginnen."],"v":["https://video2.kalaiwa.de/assets/1107169mv1440.mp4"],"rn":142},{"n":"1.1.07-172-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich führe eine Gefahrbremsung durch","Ich beschleunige","Ich fahre bremsbereit weiter"],"co":[0],"ex":["Von links fährt ein Radfahrer über die Straße, der gerade vom weißen Fahrzeug verdeckt wird. Auch wenn die Ampel für dich grün zeigt, musst du sofort eine Gefahrbremsung durchführen, um rechtzeitig zum Stehen zu kommen und eine Kollision zu vermeiden.","Du darfst nicht beschleunigen, da dies zu seiner Kollision mit dem von links kommenden Radfahrer führen würde.","Es reicht in dieser Situation nicht aus, bremsbereit weiter zu fahren. Du musst sofort bremsen, da sich der Radfahrer bereits auf der Straße befindet. Der Abstand zum Radfahrer ist so zu gering, um erst später zu bremsen."],"v":["https://video2.kalaiwa.de/assets/1107172mv1440.mp4"],"rn":143},{"n":"1.1.07-174-M","t":"Wie verhalten Sie sich richtig?","p":3,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich bleibe zunächst auf meinem Fahrstreifen","Ich lenke jetzt nach links","Ich bremse weiter ab"],"co":[0,2],"ex":["Ein Fahrstreifenwechsel ist erst möglich, wenn der Fahrstreifen links von dir frei ist. Bleibe zunächst auf deinem Fahrstreifen und bremse weiter ab.","Ein Pkw fährt links von dir. Um eine Kollision zu vermeiden, darfst du nicht nach links lenken.","Der Lkw fährt rückwärts in die Einfahrt zur Baustelle ein. Bremse ab, um eine Kollision mit dem Lkw zu vermeiden."],"v":["https://video2.kalaiwa.de/assets/1107174mv1440.mp4"],"rn":144},{"n":"1.1.07-175-M","t":"Worauf stellen Sie sich in dieser Situation ein?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Die Fußgängerin überquert die Straße","Der gelbe Pkw biegt nach links ab","Ich muss auf meine Vorfahrt verzichten"],"co":[1,2],"ex":["Die Fußgängerin möchte nicht die Straße überqueren.","Der gelbe Pkw blinkt und wird nach links abbiegen. Obwohl er keine Vorfahrt hat, wird er bei seiner hohen Geschwindigkeit nicht mehr anhalten können, ohne auf deine Spur zu kommen.","Der gelbe Pkw scheint trotz deiner Vorfahrt zum Abbiegen anzusetzen. Bremse ab und verzichte auf deine Vorfahrt, um eine Kollision zu vermeiden. Die Verpflichtung zur Unfallvermeidung steht über allen Vorfahrtsregeln."],"v":["https://video2.kalaiwa.de/assets/1107175mv1440.mp4"],"rn":145},{"n":"1.1.07-176-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich fahre gleichmäßig weiter","Ich weiche nach links aus","Ich bremse ab"],"co":[2],"ex":["Der Radfahrer wird höchstwahrscheinlich auf die Straße wechseln. Wenn du mit gleichmäßiger Geschwindigkeit weiterfahren würdest, wirst du mit ihm kollidieren.","Nach links kannst du nicht ausweichen, da links von dir ein Pkw überholt, mit dem du kollidieren würdest.","Du musst in dieser Situation abbremsen, um eine Kollision mit dem überholenden Pkw und dem Fahrradfahrer zu vermeiden."],"v":["https://video2.kalaiwa.de/assets/1107176mv1440.mp4"],"rn":146},{"n":"1.1.09-004","t":"Wodurch kann die Fahrtüchtigkeit herabgesetzt werden?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Durch Alkohol und andere berauschende Mittel","Durch bestimmte Medikamente","Durch Übermüdung"],"co":[0,1,2],"ex":["Alkohol und andere berauschende Mittel führen zu einer eingeschränkten Reaktionsfähigkeit und Fehleinschätzungen von Situationen. Entsprechend beeinträchtigen sie die Fahrtüchtigkeit und sollten somit nicht vor Antritt einer Fahrt konsumiert werden.","Bestimmte Medikamente verweisen in der Packungsbeilage daraufhin, dass die Fahrtüchtigkeit beeinträchtigt werden kann. Daher sollten Sie lieber aufs Fahren verzichten, wenn Sie ein solches Medikament konsumiert haben.","Müdigkeit hinterm Steuer kann zu einer Beeinträchtigung in der sicheren Führung des Fahrzeugs führen, da in diesem Zustand Aufmerksamkeit und Konzentrationsfähigkeit nachlassen. Somit sollte man ein Fahrzeug immer in ausgeruhtem Zustand führen."],"rn":147},{"n":"1.1.09-006","t":"Wie lange dauert es im Allgemeinen, bis 1,0 Promille Alkohol im Blut abgebaut ist?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["1 Stunde","5 Stunden","10 Stunden"],"co":[2],"ex":["Nach einer Stunde ist die Alkoholkonzentration im Blut noch so hoch, dass das Fahrverhalten erheblich beeinträchtigt werden kann. In diesem Falle hast du wahrscheinlich noch circa 0,9 Promille Alkohol im Blut.","Nach fünf Stunden befindet sich noch eine Menge Restalkohol im Blut. Da dies die Fahrtüchtigkeit in erheblichem Maße einschränken kann, sollte man sich nach 5 Stunden noch nicht wieder hinters Steuer setzen.","Pro Stunde sinkt der Promillegehalt um circa 0,1 Promille. Bis eine Blutalkoholkonzentration von 1,0 Promille abgebaut ist, dauert es daher in etwa 10 Stunden."],"rn":148},{"n":"1.1.09-008","t":"Wozu können bereits geringe Mengen Alkohol führen?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Zu verzögerter Reaktion","Zu einem Nachlassen der Hör- und Sehleistung","Zu riskanter Fahrweise"],"co":[0,1,2],"ex":["Schon geringe Mengen Alkohol schränken die Reaktionsfähigkeit stark ein, obwohl man sich selbst fit fühlt. Bereits eine niedrige Alkoholkonzentration im Blut führt zu steigenden Reaktionszeiten. Reaktionen werden ungenau. Alkoholisierte Fahrer sind Überraschungssituationen nicht mehr gewachsen.","Schon bei geringen Mengen Alkohol ist die Sehleistung vielseitig beeinträchtigt. Über den Sehapparat nimmt ein Verkehrsteilnehmer 90% der für den Verkehr wichtigen Informationen auf. Störungen des Sehapparates wirken sich demzufolge besonders nachteilig aus. Typische alkoholbedingte Ausfallerscheinungen des Sehvermögens sind das Doppeltsehen (Einbußen der räumlichen Wahrnehmung), Tunnelblick (Einschränkung des Blickfeldes), sowie eine verzögerte Hell-Dunkel-Anpassung.","Gerade geringe Mengen Alkohol bewirken eine gesteigerte motorische Aktivität, bei gleichzeitiger Minderung der hemmenden und kontrollierenden Funktionen."],"rn":149},{"n":"1.1.09-015","t":"Wie wird der berauschende Wirkstoff von Haschisch im Körper abgebaut?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Gleichmäßig, 0,1 Promille je Stunde","Ungleichmäßig, zeitlich nicht abschätzbar","Gleichmäßig, 0,1 Gramm je Stunde"],"co":[1],"ex":["Der Promillewert ermöglicht lediglich eine Aussage über den Alkoholgehalt im Blut. Den THC-Gehalt im Körper misst dieser Wert nicht.","Der berauschende Wirkstoff von Haschisch (THC) wird ungleichmäßig und zeitlich nicht abschätzbar im Körper abgebaut, da sich dieser im Fettgewebe einlagert.","Der THC-Gehalt misst sich in Nanogramm und nicht in Gramm."],"rn":150},{"n":"1.1.09-017","t":"Welche Folgen kann es haben, wenn man unter Einwirkung von Drogen (wie z. B. Haschisch, Heroin, Kokain) ein Kraftfahrzeug führt?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Anordnung einer medizinisch-psychologischen Untersuchung","Entzug der Fahrerlaubnis oder Fahrverbot","Geld- und/oder Freiheitsstrafe"],"co":[0,1,2],"ex":["Eine häufige Folge, wenn ein Autofahrer unter Drogeneinfluss am Steuer erwischt wird ist die MPU (medizinisch-psychologische Untersuchung). In dem Fall kann die Fahrerlaubnisbehörde anordnen, ein Gutachten oder Zeugnis eines Facharztes oder Amtsarztes, ein Gutachten einer amtlich anerkannten Begutachtungsstelle für Fahreignung oder eines amtlich anerkannten Sachverständigen oder Prüfers für den Kraftfahrzeugverkehr innerhalb einer angemessenen Frist zu erstellen.","Gesetzlich ist geregelt, dass ein Gericht dem/der Betroffenen für ein bis drei Monate verbieten kann, im Straßenverkehr Kraftfahrzeuge zu führen (vgl. §25 Abs. 1 StVG). Zudem kann die Fahrerlaubnis entzogen werden, wenn jemand einer rechtswidrige Tat nach §69 StGB begeht. Hierunter fällt auch das Fahren eines Fahrzeugs unter Einfluss berauschender Mittel.","§ 24a des StVG schreibt vor, dass das Führen von Kraftfahrzeugen unter Wirkung berauschender Mittel eine Ordnungswidrigkeit darstellt, welche mit einer Geldbuße bis zu dreitausend Euro geahndet werden kann. Das StGB geht an dieser Stelle sogar noch weiter. Hier regelt §315c Abs. 1, dass wer im Straßenverkehr ein Fahrzeug führt, obwohl er in Folge des Genusses alkoholischer Getränke oder anderer berauschender Mittel nicht in der Lage ist, das Fahrzeug sicher zu führen und dadurch Leib oder Leben eines anderen Menschen oder fremde Sachen von bedeutendem Wert gefährdet, wird mit Freiheitsstrafe bis zu fünf Jahren oder Geldstrafe bestraft."],"rn":151},{"n":"1.1.09-018","t":"Was kann Haschischkonsum bewirken?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Verbesserte Zeiteinschätzung","Rausch mit Verwirrtheitszuständen und Depressionen","Rausch mit gefährlichen Sinnestäuschungen und Herabsetzung des Reaktionsvermögens"],"co":[1,2],"ex":["Um die Zeit genau einschätzen zu können, ist eine ungetrügte und klare Wahrnehmung notwendig. Gerade diese wird aber im Haschisch-Rausch verzerrt.","Haschisch hat im akuten Rauschzustand oft eine bewusstseinsverändernde Wirkung. Diese kann positiv aber auch negativ sein. Tendenzen zu Ängstlichkeit oder Depressivität können durch Haschischkonsum verstärkt werden. Auch Orientierungslosigkeit und Momente von Verwirrtheit können eine Konsequenz sein.","Im akuten Rauschzustand treten häufig Denkstörungen auf. Die Konzentrationsfähigkeit und die Aufmerksamkeit können vermindert sein, ebenso die Leistung des Kurzzeitgedächtnisses. Der Konsument ist leichter ablenkbar und konzentriert sich auf Nebenreize. Illusionen und Wahrnehmungstäuschungen können resultieren."],"rn":152},{"n":"1.1.09-019","t":"Welche Auswirkungen kann Haschischkonsum haben?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Das Gefahrenbewusstsein kann abnehmen","Fehler bei der Verarbeitung von Informationen können zunehmen","Fehleinschätzungen von Geschwindigkeit und Entfernung können eintreten"],"co":[0,1,2],"ex":["Haschisch verändert das Bewusstsein. Sehr oft wird eine erheiternde und entspannende Wirkung beobachtet. So können potenzielle Gefahrensituationen als weniger gefährlich eingeschätzt werden, was weitreichende risikohafte Konsequenzen mit sich bringen kann.","Eine Auswirkung von Haschischkonsum können sprunghafte Gedanken und Gedächtnislücken sein. Dadurch ist die Verarbeitung von Informationen und Sinneseindrücken eingeschränkt.","Durch die verändernde Sinneswahrnehmung beim Konsum von Haschisch, kann die Einschätzung von Distanzen und Tempo verzerrt werden. Dies kann vor allem im Straßenverkehr weitreichende gefährliche Konsequenzen haben."],"rn":153},{"n":"1.1.09-021","t":"Für wen besteht ein Alkoholverbot beim Führen von Kraftfahrzeugen?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Für alle Kraftfahrer in der Probezeit","Für alle Kraftfahrer unter 21 Jahren","Für alle Kraftfahrer"],"co":[0,1],"ex":["Alle Kraftfahrer, die sich in der Probezeit befinden, stehen unter absolutem Alkoholverbot. Das bedeutet 0,0 Promille bei Fahrtantritt.","Jeder Kraftfahrer unter 21 Jahren muss 0,0 Promille haben. Hier herrscht absolutes Alkoholverbot.","Nicht für alle Fahrzeugführer gilt ein absolutes Alkoholverbot. Für Autofahrer über 21, die nicht in der Probezeit sind, gilt die 0,5-Promille-Grenze."],"rn":154},{"n":"1.1.09-022","t":"Dürfen Kraftfahrer beim Führen von Kraftfahrzeugen während der Probezeit unter der Wirkung alkoholischer Getränke stehen?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Ja, bis 0,5 Promille ohne alkoholbedingte Fahrauffälligkeit","Ja, bis 0,3 Promille ohne alkoholbedingte Fahrauffälligkeit","Nein, in keinem Fall"],"co":[2],"ex":["Die 0,5 Promillegrenze gilt erst nach der Probezeit.","Bis zur Beendigung der Probezeit darf ein Kraftfahrer während des Fahrens keinerlei Alkohol im Blut haben. Danach gilt die 0,5 Promillegrenze.","Während der Probezeit gibt es keine 0,5 Promillegrenze. Ein Autofahrer darf in dieser Zeit während des Fahrens keinerlei Alkohol im Blut haben."],"rn":155},{"n":"1.1.09-024","t":"Warum kann die Fahrtüchtigkeit bereits durch geringe Mengen Alkohol beeinträchtigt werden?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Weil sich die Reaktionszeit verkürzt","Weil sich das räumliche Sehen verschlechtert","Weil sich das Sichtfeld der Augen verkleinert"],"co":[1,2],"ex":["Die Reaktionszeit verlängert sich durch den Konsum von Alkohol.","Bereits geringe Mengen Alkohol beeinträchtigen das räumliche Sehvermögen.","Der Konsum von Alkohol schränkt nicht nur das Sichtfeld ein, er verschlechtert zudem das Kontrastsehen und die Blendempfindlichkeit."],"rn":156},{"n":"1.1.09-026","t":"Warum ist bereits der einmalige Konsum von Drogen für die Teilnahme am Straßenverkehr gefährlich?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["- zur Fahruntüchtigkeit führen kann","- Wahrnehmungsstörungen verursachen kann","- einen mehrstündigen Rausch verursachen kann"],"co":[0,1,2],"ex":["Drogenkonsum verändert die Wahrnehmung und beeinträchtigt die Fahrsicherheit. Bereits einmaliger Konsum kann zu Fahruntüchtigkeit führen.","Dies kann im Straßenverkehr sehr gefährlich werden und andere Verkehrsteilnehmer, so wie einen selbst gefährden.","Hierdurch ist die Wahrnehmung verändert und Verkehrssituationen können nicht mehr realistisch eingeschätzt werden."],"rn":157},{"n":"1.1.09-027","t":"Wie lange sind Cannabis und dessen Abbauprodukte im Urin nachweisbar?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Höchstens mehrere Tage","Noch nach Wochen","Nur mehrere Stunden"],"co":[1],"ex":["Cannabis und dessen Abbauprodukte können bis zu mehrere Wochen nach dem Konsum noch im Urin nachgewiesen werden.","Bei einmaligem Konsum ist THC 3-5 Tage im Urin nachweisbar, bei regelmäßigem Konsum 4-6 Wochen.","Bei einmaligem Konsum ist es mehrere Tage, bei regelmäßigem Konsum mehrere Wochen im Urin nachweisbar."],"rn":158},{"n":"1.1.09-028","t":"Warum ist man nach dem Konsum der Droge „Crystal Meth“ fahruntauglich?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Weil die eigene Leistungsfähigkeit überschätzt werden kann","Weil plötzliche Erschöpfung eintreten kann","Weil Wahnvorstellungen auftreten können"],"co":[0,1,2],"ex":["So können Verkehrssituationen nicht mehr realistisch eingeschätzt werden.","Sobald die Wirkung der Droge nachlässt, können starke Erschöpfungszustände auftreten. Das ist einer von zahlreichen Gründen, warum der Konsum fahruntauglich macht.","Der Konsum von \"Crystal Meth\" kann Wahnzustände hervorrufen, die sehr lange andauern können."],"rn":159},{"n":"1.1.09-029","t":"Wodurch lässt sich die Fahrtüchtigkeit nach übermäßigem Alkoholkonsum kurzfristig wiederherstellen?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Durch 15 Minuten Sport","Durch gar nichts","Durch das Trinken von 2 Tassen Kaffee"],"co":[1],"ex":["Sport beschleunigt den Abbau des Alkohols nicht.","Der Abbau von Alkohol im Körper kann nicht beschleunigt werden.","Kaffee kann den Alkoholabbau nicht beschleunigen."],"rn":160},{"n":"1.1.09-030","t":"Was kann die Fahrtüchtigkeit ähnlich beeinträchtigen wie Alkohol?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Erfrischungsgetränke","Drogen","Medikamente"],"co":[1,2],"ex":["Alkoholfreie Erfrischungsgetränke haben keinen Einfluss auf die Fahrtüchtigkeit.","Drogen können bereits in geringen Mengen die Fahrtüchtigkeit herabsetzen. Fahren unter Drogeneinfluss ist strafbar.","Einige Medikamente können Einfluss auf die Fahrtüchtigkeit haben. Sie können z. B. Sehstörungen und Schwindel hervorrufen oder schläfrig machen. Der Arzt gibt Auskunft über eine eventuelle Fahruntüchtigkeit. Hinweise finden sich auch auf der Packungsbeilage."],"rn":161},{"n":"1.1.09-031","t":"Welche Auswirkung kann der Konsum von Cannabisprodukten auf den Fahrer haben?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Die Aufmerksamkeit für das Verkehrsgeschehen nimmt ab","Die Konzentration auf das Fahren nimmt ab","Die Blendempfindlichkeit nimmt ab"],"co":[0,1],"ex":["Cannabis beeinflusst die Aufmerksamkeit, aber auch die Wahrnehmung und das Reaktionsvermögen. Wer unter Einfluss von Cannabis steht, ist eine Gefahr für sich und andere Verkehrsteilnehmer.","Der Konsum von Cannabis beeinträchtigt das Konzentrationsvermögen. Die Konzentration sinkt. Die Teilnahme am Straßenverkehr erfordert jedoch die volle Konzentration. Schließlich können schon kurze Unaufmerksamkeiten zu schweren Unfällen führen.","Die Blendempfindlichkeit nimmt durch den Konsum von Cannabisprodukten zu."],"rn":162},{"n":"1.1.09-032","t":"Was kann der Konsum von Drogen bewirken?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Eine Beeinträchtigung der Konzentration","Eine Fehleinschätzung von Geschwindigkeiten","Eine Erhöhung der Risikobereitschaft"],"co":[0,1,2],"ex":["Der Konsum von Drogen kann die Konzentration und die Reaktionsfähigkeit beeinträchtigen.","Drogen können die Wahrnehmung von Raum und Zeit beim Konsumenten verändern. Dadurch werden Geschwindigkeiten unter Umständen falsch eingeschätzt.","Häufig führt der Konsum von Drogen zu Selbstüberschätzung und zu erhöhter Risikobereitschaft."],"rn":163},{"n":"1.1.09-033","t":"Bei welcher Substanz kann der Konsum vor oder während der Fahrt zu Fahruntüchtigkeit führen?","p":4,"c":"1.1.09","ch":"Alkohol Drogen Medikamente","th":"Gefahrenlehre","o":["Alkohol","Kokain","Haschisch"],"co":[0,1,2],"ex":["Der Konsum von Alkohol kann zu Fahruntüchtigkeit führen, weil er sowohl die kognitiven, als auch die motorischen Fähigkeiten einschränkt.","Der Konsum von Kokain führt neben eingeschränkten kognitiven und motorischen Fähigkeiten oft zu Selbstüberschätzung und erhöhter Risikobereitschaft. Vor oder während einer Fahrt kann der Konsum deshalb zu Fahruntüchtigkeit führen.","Der Konsum von Haschisch kann neben Koordination und Konzentration das Urteilsvermögen und die Aufmerksamkeit beeinträchtigen und kann so zu Fahruntüchtigkeit führen."],"rn":164},{"n":"1.1.10-001","t":"Bei hohen Außentemperaturen lässt die Konzentration bei langen Fahrten nach und die Unfallzahlen steigen. Welche Maßnahme ist empfehlenswert, damit Sie auch im Hochsommer aufmerksam und sicher fahren?","p":3,"c":"1.1.10","ch":"Gesundheitsrisiken","th":"Gefahrenlehre","o":["Ich plane regelmäßige Pausen ein","Ich lege meine Fahrten bevorzugt in die Mittagszeit","Ich nehme ausreichend Flüssigkeit zu mir"],"co":[0,2],"ex":["Vor allem bei hohen Temperaturen sind regelmäßige Pausen wichtig, damit du dich ausruhen und anschließend konzentriert weiterfahren kannst.","Es ist nicht sinnvoll, deine Fahrten in die Mittagszeit zu verlegen, da es dann besonders warm ist. Die hohen Temperaturen sind anstrengender für deinen Körper und können unsicheres Fahren bedingen.","An heißen Tagen ist es besonders wichtig, viel zu trinken. Ein Mangel an Wasser würde dein Fahrvermögen und deine Aufmerksamkeit stark beeinträchtigen. Du musst also darauf achten, ausreichend Flüssigkeit mitzunehmen."],"rn":165},{"n":"1.1.10-002","t":"Bei welchem körperlichen Anzeichen sollten Sie kein Kraftfahrzeug führen?","p":3,"c":"1.1.10","ch":"Gesundheitsrisiken","th":"Gefahrenlehre","o":["Bei Schwindel","Bei Übelkeit","Bei Fieber"],"co":[0,1,2],"ex":["Schwindel beeinträchtigt deine Fahrtüchtigkeit. Um dich und andere Verkehrsteilnehmer nicht zu gefährden, führe kein Kraftfahrzeug, solange dir schwindelig ist.","Übelkeit kann dich ablenken und das Unfallrisiko erhöhen. Warte, bis es dir besser geht, oder lasse jemand anderen fahren.","Fieber beeinträchtigt deine Konzentration und Reaktionsfähigkeit. Wegen des erhöhten Unfallrisikos solltest du mit Fieber nur im Notfall fahren."],"rn":166},{"n":"1.2.01-003","t":"Gegenüber welchen Verkehrsteilnehmern müssen Sie sich besonders vorsichtig verhalten?","p":4,"c":"1.2.01","ch":"Grundregeln Ueber Das Verhalten Im Strassenverkehr","th":"Verhalten Im Strassenverkehr","o":["Gegenüber Personen mit erkennbaren Behinderungen","Gegenüber Taxifahrern","Gegenüber Kindern"],"co":[0,2],"ex":["Du musst dich im Straßenverkehr so verhalten, dass du hilfsbedürftige Personen und somit auch Personen mit erkennbaren Behinderungen nicht gefährdest.","Bei Taxifahrern muss keine besondere Vorsicht gegeben werden.","Du musst gewährleisten, dass Kinder durch dein Teilhaben am Straßenverkehr nicht gefährdet werden."],"rn":167},{"n":"1.2.02-106","t":"Welche Kraftfahrzeuge müssen auf einer Landstraße möglichst den befestigten Seitenstreifen benutzen?","p":3,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["Mofas","Kleinkrafträder","Langsam fahrende landwirtschaftliche Zug- und Arbeitsmaschinen"],"co":[0,2],"ex":["Die zulässige Höchstgeschwindigkeit von Mofas beträgt 25 km/h. Um den übrigen Verkehr aufgrund der geringen Geschwindigkeit nicht zu behindern, müssen Mofafahrer möglichst auf dem Seitenstreifen fahren.","Kleinkrafträder müssen nicht auf dem Seitenstreifen fahren.","So behindern sie den restlichen Verkehr nicht."],"rn":168},{"n":"1.2.02-107","t":"Wie sollten Sie sich in dieser Situation verhalten?","p":3,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["- zurück, denn der Entgegenkommende darf fahren","- in die Lücke, um den Entgegenkommenden vorbeizulassen","- weiter, weil der Entgegenkommende zurückfahren muss"],"co":[1],"ex":["Ihr habt beide das Recht zu fahren. Jedoch kannst nur du ausweichen. Zurückfahren wäre notwendig, wenn es keine Ausweichmöglichkeit gäbe.","Das entgegenkommende Fahrzeug hat nämlich keine Möglichkeit, auszuweichen. Fahre daher in die Lücke und lass ihn vorbeifahren.","Ihr habt gleichermaßen ein Fahrtrecht. Allerdings hat der Gegenverkehr keine Möglichkeit, auszuweichen. Daher musst du ihm Platz machen, indem du in die Lücke einfährst."],"v":["https://video4.kalaiwa.de/assets/1202107v1440.mp4"],"rn":169},{"n":"1.2.02-108","t":"Ihnen kommt eine Pferdekutsche entgegen. Wie sollten Sie sich verhalten?","p":3,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["- Standlicht einschalten","- möglichst weit rechts fahren","- Lärm vermeiden"],"co":[1,2],"ex":["Es ist in diesem Fall nicht sinnvoll oder zielführend, das Standlicht einzuschalten.","So kann die Kutsche die Stelle möglichst ungehindert passieren und du hast ausreichend Sicherheitsabstand zu den Pferden.","Damit du die Pferde nicht erschreckst, solltest du Lärm vermeiden."],"rn":170},{"n":"1.2.02-109","t":"Was ist in dieser Situation richtig?","p":2,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["- gilt die Vorfahrtregel „rechts vor links“","- habe ich Vorfahrt","- endet ein verkehrsberuhigter Bereich"],"co":[0],"ex":["Das besagt das Verkehrszeichen.","Du musst Vorfahrt gewähren.","Das Verkehrszeichen, das einen verkehrsberuhigten Bereich kennzeichnet, zeigt ein Spielszenario in weißer Farbe mit blauem Untergrund und rotem Querstrich darüber."],"i":["https://video4.kalaiwa.de/assets/1202109.webp"],"rn":171},{"n":"1.2.02-110","t":"Was müssen Sie beim Überqueren einer Vorfahrtstraße beachten?","p":2,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["- die Breite der Vorfahrtstraße","- die Witterungsverhältnisse","- die Geschwindigkeit und Entfernung des Querverkehrs"],"co":[0,1,2],"ex":["Je breiter die Vorfahrtsstraße, desto mehr Zeit benötigst du, um sie zu überqueren.","Die Fahrweise muss an die Witterungsverhältnisse angepasst werden. Ist die Fahrbahn aufgrund von Laub, Eis oder Regen rutschig, dann solltest du mehr Zeit für das Überqueren einplanen, da du langsamer Fahren musst.","Erst wenn du den Abstand zum Querverkehr realistisch einschätzen kannst und dieser ausreichend vorhanden ist, darfst du die Vorfahrtsstraße überqueren."],"rn":172},{"n":"1.2.02-111","t":"Sie möchten eine Autobahn benutzen. Welche bauartbedingte Höchstgeschwindigkeit muss hierfür in der Zulassungsbescheinigung Teil I oder in der Betriebserlaubnis eingetragen sein?","p":3,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","na":"Antwort: Mehr als 60 km/h","e":"Laut Straßenverkehrsordnung (StVO) dürfen Autobahnen nur von Kraftfahrzeugen benutzt werden, deren bauartbedingte Höchstgeschwindigkeit mehr als 60 km/h beträgt.","rn":173},{"n":"1.2.02-101-B","t":"Wozu darf der rechte Seitenstreifen benutzt werden?","p":3,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["Zum Überholen","Zum Halten und Parken","Zum Befahren mit langsamen Fahrzeugen"],"co":[1,2],"ex":["Rechts darf nicht überholt werden. Zudem ist hier eine durchgezogene Linie abgebildet, die zusätzlich generelles Überholen untersagt.","Laut §12 Absatz 4 der StVO darf auf dem ausgebauten Seitenstreifen einer Landstraße gehalten und geparkt werden.","Langsame Fahrzeuge, wie Traktoren, können auf der Landstraße diesen Seitenstreifen zum Fahren nutzen, um so den übrigen Verkehr nicht zu behindern."],"i":["https://video2.kalaiwa.de/assets/1202101b.webp"],"rn":174},{"n":"1.2.02-104-M","t":"Sie haben sich irrtümlich links eingeordnet, möchten aber nach rechts abbiegen. Wie verhalten Sie sich richtig?","p":4,"c":"1.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["Ich fahre geradeaus weiter oder biege links ab","Ich fahre geradeaus weiter und biege im Kreuzungsbereich rechts ab","Ich wechsle vorsichtig in den rechten Fahrstreifen"],"co":[0],"ex":["Ein Spurwechsel ist hier nicht mehr möglich, weil die Spurlinie durchgezogen ist. Daher musst du nun geradeaus fahren oder links abbiegen.","Du musst geradeaus fahren, oder rechts abbiegen. Im Kreuzungsbereich kurzfristig die Fahrtrichtung zu ändern, könnte andere Verkehrsteilnehmer behindern oder gefährden.","Du darfst nicht mehr auf den rechten Fahrstreifen wechseln."],"i":["https://video4.kalaiwa.de/assets/1202104m.webp"],"rn":175},{"n":"1.2.03-001","t":"Was verlängert den Bremsweg?","p":4,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["Mitführen eines ungebremsten Anhängers","Fahren auf Gefällstrecken","Nasse oder glatte Fahrbahnen"],"co":[0,1,2],"ex":["Ein ungebremster Anhänger kann nur durch das Bremsen des Zugfahrzeugs mit abgebremst werden. Das bedeutet, dass das Zugfahrzeug mehr Masse abbremsen muss, als nur das Eigengewicht und somit mehr Strecke benötigt, um dies zu tun.","Fährt man eine Steigung hinauf, verkürzt sich der Bremsweg, weil das Fahrzeug entgegen der Steigung arbeiten muss. Beim Gefälle ist das genau umgekehrt und bei gleicher Bremskraft erhöht sich der Bremsweg.","Nasse oder glatte Fahrbahnen verringern den Reibungswiderstand und erhöhen somit den Bremsweg. Dies wird bei Glätte besonders deutlich."],"rn":176},{"n":"1.2.03-002","t":"Wovon ist der Bremsweg abhängig?","p":3,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["- Bremsanlage","- Bereifung","- Fahrbahnoberfläche"],"co":[0,1,2],"ex":["Es gibt verschiedene Arten von Bremsanlagen. Je nachdem Qualität einer Bremsanlage verkürzt oder verlängert sich der Bremsweg.","Der Bremsweg ist abhängig von der Beschaffenheit der Reifen. Die Qualität eines Reifen ist abhängig von seinem Alter, den Abmessungen, dem Profil und dem Reifendruck. Sind einer oder mehrere Faktoren mangelhaft, so wird der Bremsweg länger.","Je nach Beschaffenheit der Oberfläche der Fahrbahn ist die Haftung der Autoreifen größer oder geringer. Zum Beispiel verringert Glatteis die Haftung eines Reifens auf der Fahrbahn und verlängert daher auch den Bremsweg."],"rn":177},{"n":"1.2.03-101","t":"Welche zulässige Höchstgeschwindigkeit gilt allgemein innerhalb geschlossener Ortschaften?","p":3,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"50 km/h","e":"Die zulässige Höchstgeschwindigkeit innerhalb geschlossener Ortschaften ist gesetzlich auf 50 km/h festgelegt","rn":178},{"n":"1.2.03-102","t":"Sie verdoppeln Ihre Geschwindigkeit. Wie verändert sich der Bremsweg?","p":4,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"Antwort: Er wird 4 mal so lang","e":"Da die Geschwindigkeit in die Formel des Bremswegs quadratisch, also zweimal, eingeht, ergibt sich bei doppelter Geschwindigkeit ein 4-facher Bremsweg, da 2² = 4","rn":179},{"n":"1.2.03-103","t":"Was müssen Sie bei der Wahl Ihrer Geschwindigkeit berücksichtigen?","p":4,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["Sicht- und Wetterverhältnisse","Persönliche Fähigkeiten","Fahrbahnzustand und Verkehrsverhältnisse"],"co":[0,1,2],"ex":["Die Geschwindigkeit muss an die Sicht- und Wetterverhältnisse angepasst werden. Nebel, starker Regen und Schneefall zum Beispiel können die Sicht so stark beeinträchtigen, dass weitaus langsamer als vorgeschrieben gefahren werden sollte, um sich selbst und andere Verkehrsteilnehmer nicht zu gefährden.","Vor allem Fahranfänger können Gefahrensituationen nicht in dem Maße abschätzen, in dem dies geschulte Fahrzeugführer tun. Es ist jahrelange Fahrerfahrung vonnöten, um unterschiedliche Verkehrssituationen einschätzen und dementsprechend reagieren zu können. Vor allem bei unbegrenzter Geschwindigkeit oder unübersichtlichen Überholmanövern sollte Vorsicht vor Risiko walten.","Beispiele für schlechten Fahrbahnzustand sind Schlaglöcher, Kiesbetten (Rutschgefahr), Glätte und Verschmutzung. Hier sollte also langsamer und mit ausreichend Abstand gefahren werden. Zudem sollte die Geschwindigkeit an die Verkehrsverhältnisse angepasst werden. Bei erhöhtem Verkehrsaufkommen ist das Risiko für stockenden Verkehr oder Staubildung erhöht. Hier muss die Geschwindigkeit dem Verkehrsaufkommen angepasst werden."],"rn":180},{"n":"1.2.03-104","t":"Nach welcher Faustformel kann man aus der Geschwindigkeit den Weg in Metern ermitteln, den ein Fahrzeug in einer Sekunde zurücklegt?","p":2,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["Geschwindigkeit in km/h 10 x 5","Geschwindigkeit in km/h 10 x 3","Geschwindigkeit in km/h 10 x Geschwindigkeit in km/h 10"],"co":[1],"ex":["Dies ist keine Faustregel.","Dies ist die Faustformel für die Umrechnung von Kilometer pro Stunde auf Meter pro Sekunde. Dies ist die Faustregel zur Berechnung des Reaktionswegs.","Dies ist die Faustformel zur Berechnung des Bremswegs bei normaler Bremsung."],"rn":181},{"n":"1.2.03-105","t":"Nach welcher Faustformel kann man aus der Geschwindigkeit den Bremsweg in Metern bei einer normalen Bremsung berechnen?","p":2,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["Geschwindigkeit in km/h 10 x 5","Geschwindigkeit in km/h 10 x 3","Geschwindigkeit in km/h 10 x Geschwindigkeit in km/h 10"],"co":[2],"ex":["Diese Faustregel gibt es nicht.","Diese Faustformel gibt Auskunft über die Berechnung des Reaktionswegs.","Dies ist die Faustregel zur Berechnung des normalen Bremswegs. Zur Berechnung des Bremswegs bei Gefahrenbremsung muss das Ergebnis zusätzlich durch 2 geteilt werden."],"rn":182},{"n":"1.2.03-106","t":"Sie fahren mit 30 km/h. Dabei beträgt der Bremsweg bei einer normalen Bremsung 9 Meter nach der Faustformel. Wie lang ist der Bremsweg unter gleichen Bedingungen bei 60 km/h?","p":4,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["18 m","36 m","27 m"],"co":[1],"ex":["Dies wäre der Bremsweg bei Gefahrenbremsung.","Dies lässt sich mit der Faustformel für normale Bremsung wie folgt berechnen: (Geschwindigkeit in km/h : 10) x (Geschwindigkeit in km/h : 10) Bei 30 km/h beträgt der Bremsweg somit: (30 km/h : 10) x (30 km/h : 10) = 9 m Bei 60 km/h beträgt der Bremsweg somit: (60 km/h : 10) x (60 km/h : 10) = 36 m Hier sieht man: Der Bremsweg vervierfacht sich bei doppelter Geschwindigkeit!","Diese Antwort stimmt nicht."],"rn":183},{"n":"1.2.03-107","t":"Sie fahren auf einer gut ausgebauten Straße, auf der Gegenverkehr ungehindert an Ihnen vorbeifahren kann. Innerhalb welcher Strecke müssen Sie in jedem Fall anhalten können?","p":4,"c":"1.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["- doppelten von mir übersehbaren Strecke","- halben von mir übersehbaren Strecke","- von mir übersehbaren Strecke"],"co":[2],"ex":["Du musst innerhalb deiner Sichtweite anhalten können.","Du musst innerhalb der von dir übersehbaren Strecke anhalten können.","Du darfst nur so schnell fahren, dass du innerhalb deiner Sichtweite anhalten kannst."],"rn":184},{"n":"1.2.04-101","t":"Wovon hängt der einzuhaltende Abstand zum vorausfahrenden Fahrzeug ab?","p":5,"c":"1.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["Von den Sichtverhältnissen","Von der Geschwindigkeit","Von der Fahrbahnbeschaffenheit"],"co":[0,1,2],"ex":["Bei schlechter Sicht muss der Sicherheitsabstand vergrößert werden, da nun nicht mehr erkennbar ist, was vor dem Vorausfahrenden geschieht.","Mit zunehmender Geschwindigkeit vergrößern sich auch Reaktions-, Brems- und Anhalteweg. Um dies ausgleichen zu können, muss folglich auch der Abstand vergrößert werden.","Je schlechter die Fahrbahnbeschaffenheit - also der Zustand der Fahrbahn - desto länger werden Brems- und Anhalteweg. Somit sollte auch hier der Sicherheitsabstand vergrößert werden."],"rn":185},{"n":"1.2.04-102","t":"Wie verhalten Sie sich richtig?","p":5,"c":"1.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["Ich bremse ab","Ich behalte meine Geschwindigkeit bei","Ich vergrößere den Abstand zum Einscherenden"],"co":[0,2],"ex":["Dadurch, dass der Überholende sich zwischen dich und deinen Vordermann gedrängt hat, ist der Sicherheitsabstand nicht mehr ausreichend. Bremse ab und vergrößere diesen wieder. Auch kann es nicht Schaden, aufgrund des Fahrstils des Überholenden etwas mehr Abstand zu halten.","Du solltest unbedingt abbremsen, um ausreichend Sicherheitsabstand zu haben.","Bremse ab und vergrößere den Abstand zum Überholenden."],"v":["https://video4.kalaiwa.de/assets/1204102v1440.mp4"],"rn":186},{"n":"1.2.04-104","t":"Wozu kann ein ausreichender Abstand zum vorausfahrenden Fahrzeug beitragen?","p":3,"c":"1.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["Zur Verringerung des Unfallrisikos","Zur Einschränkung der Sicht","Zum vorausschauenden Fahren"],"co":[0,2],"ex":["Durch ausreichenden Sicherheitsabstand wird das Risiko für Auffahrunfälle vermindert. Zudem hast du so mehr Zeit, um auf unvorhersehbare Verkehrssituationen zu reagieren.","Ausreichender Abstand fördert die Sichtweite. Fährt man zu dicht auf, ist die Sicht auf den vorausgehenden Verkehr durch das vordere Fahrzeug eingeschränkt.","So kannst du rechtzeitig auf das Verkehrsgeschehen vor dir reagieren."],"rn":187},{"n":"1.2.05-003","t":"Sie möchten außerorts Radfahrer oder Fußgänger überholen. Welchen seitlichen Mindestabstand müssen Sie dabei einhalten?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","na":"2 m","e":"Beim Überholen musst du genügend Seitenabstand einhalten, um die anderen Verkehrsteilnehmer nicht zu gefährden. Außerorts beträgt der einzuhaltende Mindestabstand bei Fußgängern, Radfahrern und Elektrokleinstfahrzeugen 2 Meter.","rn":188},{"n":"1.2.05-004","t":"Sie möchten innerorts einen Radfahrer überholen. Welchen seitlichen Mindestabstand müssen Sie dabei einhalten?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","na":"1,5 m","e":"Beim Überholen musst du genügend Seitenabstand einhalten, um die Verkehrsteilnehmer nicht zu gefährden. Innerorts beträgt der einzuhaltende Mindestabstand bei Fußgängern, Radfahrern und Elektrokleinstfahrzeugen 1,5 Meter.","rn":189},{"n":"1.2.05-005","t":"Sie möchten innerorts einen Elektroroller überholen. Welchen seitlichen Mindestabstand müssen Sie dabei einhalten?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","na":"1,5 m","e":"Beim Überholen musst du genügend Seitenabstand einhalten, um die anderen Verkehrsteilnehmer nicht zu gefährden. Innerorts beträgt der einzuhaltende Mindestabstand bei Fußgängern, Radfahrern und Elektrokleinstfahrzeugen 1,5 Meter.","rn":190},{"n":"1.2.05-101","t":"Wo ist das Überholen verboten?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Wo die Verkehrslage unklar ist","In allen Einbahnstraßen","Wo der Gegenverkehr behindert werden könnte"],"co":[0,2],"ex":["Generell gilt: Falls nötig, nur dann Überholen, wenn die Verkehrssituation umfassend überblickt und eingeschätzt werden kann. In unklaren Verkehrslagen ist kein sicheres Überholen gewährleistet.","Einbahnstraßen können auch zweispurig sein. Generell ist hier das Überholen nicht verboten, dennoch sollte erhöhte Wachsamkeit geboten sein.","Ein Überholvorgang muss so durchgeführt werden, dass weder der Gegenverkehr noch der Überholte zum Bremsen genötigt werden. Folglich ist die Geschwindigkeit des Vordermanns, die Geschwindigkeit des Gegenverkehrs und die Entfernung zum Gegenverkehr in das Überholmanöver einzukalkulieren."],"rn":191},{"n":"1.2.05-103","t":"Was ist Voraussetzung für das Ausscheren zum Überholen?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Dass der Gegenverkehr nicht gefährdet wird","Dass der Vorausfahrende rechts blinkt","Dass eine Gefährdung des nachfolgenden Verkehrs ausgeschlossen ist"],"co":[0,2],"ex":["Der Gegenverkehr darf beim Überholen nicht behindert werden. Kann die Distanz zu diesem beispielsweise aufgrund unübersichtlicher Verkehrsverhältnisse nicht eingeschätzt werden, dann ist ein Überholen in diesem Fall zu unterlassen.","Blinkt der Vorausfahrende rechts, dann bedeutet dies, dass er rechts abbiegen will, oder dem Hintermann signalisieren möchte, dass die Bahn zum Überholen frei ist. Das ist jedoch keine Voraussetzung, um zum Überholen auszuscheren.","Ist dies nicht gewährleistet, dann darf nicht überholt werden."],"rn":192},{"n":"1.2.05-104","t":"Wie müssen Sie einen Überholvorgang beenden?","p":3,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Dicht vor dem Überholten wieder auf die rechte Fahrbahnseite wechseln","Ohne den Überholten zu behindern, so bald wie möglich wieder nach rechts einordnen","Das Wiedereinordnen rechtzeitig und deutlich anzeigen"],"co":[1,2],"ex":["Vor, während und nach des Überholvorgangs ist der Sicherheitsabstand einzuhalten. Daher ist auch beim Einscheren darauf zu achten, dass immer ausreichend Platz nach hinten zu dem Fahrzeug, dass überholt wird besteht.","Beim Überholen ist dafür Sorge zu tragen, dass eine Gefährdung des Überholten ausgeschlossen ist. Zudem muss der Überholende sich nach dem Überholvorgang sobald wie möglich wieder nach rechts einordnen.","Gemäß der Straßenverkehrsordnung muss der Überholvorgang rechtzeitig und deutlich vorher mittels Fahrtrichtungsanzeige angezeigt werden, damit sich andere Verkehrsteilnehmer darauf einstellen können."],"rn":193},{"n":"1.2.05-105","t":"Was ist über die Geschwindigkeit beim Überholvorgang vorgeschrieben?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Wer überholt wird, darf seine Geschwindigkeit nicht erhöhen","Die zulässige Höchstgeschwindigkeit darf nicht überschritten werden","Die Geschwindigkeit des Überholenden muss wesentlich höher sein"],"co":[0,1,2],"ex":["Wenn der Überholte seine Geschwindigkeit während des Überholvorgangs erhöht, entsteht für den Überholenden ein unkalkulierbares Risiko, da er länger auf der Gegenfahrbahn bleiben muss als geplant und die freie Sichtweite unter Umständen nicht mehr für einen sicheres Überholen ausreicht.","Die zulässige Höchstgeschwindigkeit darf in keinem Fall, also auch nicht beim Überholen, überschritten werden.","Die Geschwindigkeit des Überholenden muss wesentlich höher sein, da andernfalls der Überholvorgang lange dauern würde und so gefährliche Situationen auf der Fahrbahn des Gegenverkehrs oder beim Einscheren entstehen können."],"rn":194},{"n":"1.2.05-106","t":"Wie müssen Sie sich verhalten, wenn Sie überholt werden?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Möglichst weit rechts fahren","Geschwindigkeit nicht erhöhen","Geschwindigkeit erhöhen"],"co":[0,1],"ex":["Wenn du überholt wirst, solltest du alles tun, um den Überholvorgang nicht zu gefährden. Dazu gehört als überholtes Fahrzeug so weit wie möglich rechts zu fahren.","Wenn du überholt wirst, solltest du alles tun, um den Überholvorgang nicht zu gefährden. Entsprechend sollte die Geschwindigkeit nicht erhöht werden, da der Überholende sonst Schwierigkeiten auf der Gegenfahrbahn oder beim Einscheren zurück auf die eigene Fahrbahn bekommen kann.","Erhöhst du die Geschwindigkeit, benötigt der Überholende für diesen Vorgang länger. Seine Einschätzung für die benötigte Strecke stimmt dann nicht mehr. Eine unübersichtliche Kurve oder ein auftauchendes Fahrzeug auf der Gegenfahrbahn können den Überholenden dann in eine gefährliche Situation bringen."],"rn":195},{"n":"1.2.05-107","t":"Auf welcher Seite ist eine Straßenbahn zu überholen, die in der Mitte der Fahrbahn fährt (keine Einbahnstraße)?","p":3,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Rechts","Links nur dann, wenn rechts andere Fahrzeuge die Fahrbahn versperren","Links"],"co":[0],"ex":["Eine Straßenbahn in der Mitte einer Fahrbahn ist immer rechts zu überholen. Links überholen bedeutet, dass du die Gegenfahrbahn befahren musst. Durch die Länge der Straßenbahn ist dies viel zu gefährlich.","Auch wenn Fahrzeuge rechts die Fahrbahn versperren darf eine Straßenbahn nicht links überholt werden. Dann gilt es sich in Geduld zu üben, bis sich der Verkehr aufgelöst hat.","Du würdest auf der Gegenfahrbahn überholen. Dies ist viel zu gefährlich, da die Straßenbahn sehr lang ist."],"rn":196},{"n":"1.2.05-108","t":"In welchen Fällen dürfen Sie eine Straßenbahn links überholen?","p":3,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Wenn die Schienen zu weit rechts liegen","In Einbahnstraßen","Wenn die Fahrbahn (keine Einbahnstraße) rechts neben der Straßenbahn durch andere Fahrzeuge versperrt ist"],"co":[0,1],"ex":["Liegen die Schienen auf der Fahrbahn zu weit rechts, ist oft kein Überholvorgang möglich. Dann darf ausnahmsweise links überholt werden.","Einbahnstraßen bestehen lediglich aus einer Fahrbahn für eine Richtung. In diesem Falle dürfen Straßenbahnen auch links überholt werden.","Wenn die Schienen zu weit rechts liegen, dann darf ich die Straßenbahn links überholen. Wenn am rechten Fahrbahnrand Fahrzeuge halten oder parken, dann liegen die Schienen nicht zu weit rechts, es stören eben nur die Fahrzeuge. Die Ausnahme links Überholen zu dürfen gilt in diesem Falle nicht."],"rn":197},{"n":"1.2.05-109","t":"Welche Fahrzeuge dürfen nur mit besonders großem Seitenabstand überholt werden?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Motorräder","Straßenbahnen","Fahrräder"],"co":[0,2],"ex":["Motorräder sind zwar nicht so agil wie Fahrräder, können jedoch auch einmal unerwartet einscheren. Daher ist beim Überholen von Motorrädern ebenfalls ein sehr großzügiger Seitenabstand einzuhalten.","Straßenbahnen fahren auf Schienen, die ein plötzliches Ausweichen oder \"Schlenker\" nicht möglich machen. Sie müssen also keinen besonders großen Abstand halten, da Sie nicht mit unerwarteten Manövern zu rechnen haben.","Bei Fahrrädern müssen Sie immer mit \"Schlenkern\" oder unerwarteten Ausweichmanövern rechnen. Darum sollten Sie an diesen Verkehrsteilnehmern stets besonders vorsichtig und mit besonders großem Seitenabstand (mind. 1,5-2 Meter) vorbeifahren."],"rn":198},{"n":"1.2.05-110","t":"In welchen Fällen müssen Sie blinken?","p":3,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Beim Verlassen einer abknickenden Vorfahrtstraße in gerader Richtung","Vor dem Ausscheren zum Überholen oder zum Vorbeifahren","Vor dem Wiedereinordnen nach dem Überholen"],"co":[1,2],"ex":["Mit dem Blinkzeichen teilen Sie anderen Verkehrsteilnehmern ihre Absicht mit in eine andere Richtung als geradeaus zu fahren. Daher sollten Sie beim Geradeausfahren nicht blinken. Dies kann andere Verkehrsteilnehmer verwirren.","Mit dem Blinken zeigen Sie anderen Verkehrsteilnehmern an, dass Sie entweder nach rechts oder nach links fahren möchten. Entsprechend ist auch beim Ausscheren zum Überholen oder zum Vorbeifahren in eine Richtung der Blinker zu setzen.","Vor dem Wiedereinordnen nach dem Überholen ist der Blinker ebenfalls zu setzen, da Sie wieder auf die ursprüngliche Fahrbahn wechseln."],"rn":199},{"n":"1.2.05-116","t":"Sie fahren ein langsameres Fahrzeug auf einer Landstraße. Wie können Sie schnelleren Fahrzeugen das Überholen ermöglichen?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- in eine Haltebucht","- auf den Seitenstreifen","- auf den Parkstreifen"],"co":[0,1,2],"ex":["Um schneller fahrenden Fahrzeugen ein einfaches Überholen zu ermöglichen, kannst du in eine Haltebucht ausweichen.","Wenn du auf den Seitenstreifen ausweichst, behinderst du den übrigen Verkehrsfluss nicht.","Du kannst auf den Parkstreifen ausweichen und es den anderen Fahrzeugen so ermöglichen, schneller zu fahren."],"rn":200},{"n":"1.2.05-119","t":"Woran können Sie erkennen, dass eine Pferdekutsche die Fahrtrichtung ändern möchte?","p":3,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Am Ausstrecken des Armes des Kutschers","Am eingeschalteten Blinker","An der ausgestellten Winkerkelle"],"co":[0,1,2],"ex":["Dies ist ein Hinweis, dass die Pferdekutsche die Fahrtrichtung ändert.","Ein eingeschalteter Blinker ist, wenn bei der Pferdekutsche vorhanden, genauso wie bei allen anderen Teilnehmern im Straßenverkehr ein Hinweis auf Fahrtrichtungsänderung.","Die ausgestellte Winkerkelle ist ein Zeichen für Richtungsänderung einer Pferdekutsche."],"rn":201},{"n":"1.2.05-120","t":"Sie möchten eine Pferdekutsche auf einer Landstraße überholen. Wie verhalten Sie sich?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- großem Seitenabstand","- wenig Lärm","- hoher Motordrehzahl"],"co":[0,1],"ex":["Für den Fall, dass sich die Pferde unvorhersehbar verhalten, hast du so ausreichend Abstand, um nicht gefährdet zu werden.","So verschreckst du die Pferde nicht.","Du solltest eher langsam, möglichst leise und mit ausreichendem Seitenabstand eine Pferdekutsche überholen."],"rn":202},{"n":"1.2.05-123","t":"Sie möchten eine Pferdekutsche auf einer Landstraße überholen. Wie verhalten Sie sich richtig?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Ich halte einen möglichst geringen Seitenabstand ein","Ich halte einen ausreichenden Abstand beim Wiedereinscheren ein","Ich achte auf Handzeichen zum Abbiegen des Kutschers"],"co":[1,2],"ex":["Der Sicherheitsabstand sollte möglichst groß sein. Nur so ist deine und die Sicherheit der Kutsche gewährleistet. Auch die Pferde dürfen nicht aufgeschreckt werden.","Dein Überholvorgang darf die Kutsche keinesfalls beeinträchtigen. Um die Pferde vor der Kutsche nicht zu erschrecken, musst du beim Überholen und beim Einscheren ausreichend Abstand halten.","Eine Kutsche kann durch einen Blinker, eine Winkerkelle oder den ausgestreckten Arm des Kutschers signalisieren, dass sie abbiegen möchte. Wenn die Kutsche zum Abbiegen signalisiert, darfst du nicht überholen, da sie deine Überholspur kreuzen wird."],"rn":203},{"n":"1.2.05-124","t":"Welchen Seitenabstand müssen Sie beim Überholen von Fußgängern und Radfahrern einhalten?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- innerorts mindestens 1,5 m Seitenabstand einhalten","- außerorts mindestens 2,0 m Seitenabstand einhalten","- innerorts mindestens 1,0 m Seitenabstand einhalten"],"co":[0,1],"ex":["In Ortschaften muss beim Überholen mindestens 1,5 m Sicherheitsabstand seitlich eingehalten werden.","Außerhalb von Ortschaften vergrößert sich der Seitenabstand auf mindestens 2 m.","Innerorts liegt der Seitenabstand bei mindestens 1,5 m."],"rn":204},{"n":"1.2.05-125-M","t":"Was müssen Sie in dieser Situation beim Überholen der Radfahrer beachten?","p":4,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Aufgrund der Steigung pendeln die Radfahrer","Ich muss mit mindestens 1,0 m Seitenabstand überholen","Ich muss mit mindestens 1,5 m Seitenabstand überholen"],"co":[0,2],"ex":["Durch die Steigung sind die Radfahrer angestrengt und pendeln womöglich während des Fahrens hin und her. Dies solltest du bei deinem Überholvorgang beachten.","Ein Abstand von 1,0 m ist nicht ausreichend. Kannst du die vorgeschriebenen 1,5 m innerorts, nicht einhalten, gilt somit automatisch ein Überholverbot an dieser Stelle.","Du befindest dich innerorts. Hier gilt beim Überholen von Radfahrern ein Seitenabstand von mindestens 1,5 m, um diese bei ihrer Fahrt nicht zu behindern. Falls die Fahrweise der Radfahrer jedoch einen höheren Seitenabstand erfordert, musst du ihnen diesen gewähren."],"i":["https://video2.kalaiwa.de/assets/1205125m.webp"],"rn":205},{"n":"1.2.05-126-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":5,"c":"1.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Ich überhole den Radfahrer mit ausreichendem Seitenabstand","Ich bleibe hinter dem Radfahrer","Ich muss den Fußgänger die Fahrbahn überqueren lassen"],"co":[1],"ex":["Du darfst den Radfahrer nicht überholen, da eine durchgezogenen Linie die Fahrbahn des Gegenverkehrs abtrennt. Diese darfst du nicht zum Überholen überqueren.","Du musst hinter dem Radfahrer bleiben, auch wenn kein Gegenverkehr zu sehen ist. Beim Überholen würdest du eine durchgezogene Mittellinie überqueren, dies ist immer verboten.","Der wartende Fußgänger steht weder an einem Zebrastreifen noch an einer Ampel. Du musst ihn also nicht vor dir überqueren lassen."],"v":["https://video2.kalaiwa.de/assets/1205126mv1440.mp4"],"rn":206},{"n":"1.2.06-001","t":"Welches Fahrzeug muss warten, wenn eine Baustelle die halbe Fahrbahn blockiert?","p":3,"c":"1.2.06","ch":"Vorbeifahren","th":"Verhalten Im Strassenverkehr","o":["Immer das kleinere Fahrzeug","Das Fahrzeug, auf dessen Seite die Baustelle ist","Das Fahrzeug auf der freien Fahrbahnhälfte"],"co":[1],"ex":["Die Größenverhältnisse von Fahrzeugen spielen keine Rolle. Im Straßenverkehr geht es nicht darum zu zeigen, wer der Stärkere ist. Auch wenn ein 12 Tonnen LKW hinter einer Baustelle steht, hat er zuerst einen entgegenkommenden Kleinwagen vorbei zu lassen, bevor er selbst die Baustelle überholen darf.","Es muss immer derjenige halten und den Gegenverkehr vorbei lassen, der die Hindernisse auf seiner Seite hat. Dieser Grundsatz gilt auch bei Baustellen.","Das Fahrzeug auf der freien Fahrbahnhälfte muss nicht halten. Es darf vorbei fahren, weil sich das Hindernis auf der Gegenfahrbahn befindet."],"rn":207},{"n":"1.2.06-006","t":"Wie sollten Sie sich jetzt verhalten?","p":5,"c":"1.2.06","ch":"Vorbeifahren","th":"Verhalten Im Strassenverkehr","o":["- um möglichen Gegenverkehr nicht aufzuhalten","- da möglicher Gegenverkehr bereits warten muss","- wenn zu erkennen ist, dass kein Gegenverkehr kommt"],"co":[2],"ex":["Weil das Hindernis auf deiner Fahrbahnseite ist, hat der Gegenverkehr Vorrang. Du darfst also erst weiterfahren, wenn zu erkennen ist, dass kein Gegenverkehr kommt.","Der Gegenverkehr sollte nicht unnötig warten müssen. Das Hindernis ist auf deiner Seite, der Gegenverkehr hat hier Vorrang.","Du solltest erst weiterfahren, wenn der Transporter die Baustelle vollständig überholt hat und du sehen kannst, dass kein Gegenverkehr kommt."],"v":["https://video4.kalaiwa.de/assets/1206006v1440.mp4"],"rn":208},{"n":"1.2.06-101-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":5,"c":"1.2.06","ch":"Vorbeifahren","th":"Verhalten Im Strassenverkehr","o":["Ich fahre vor dem Entgegenkommenden","Ich warte, bis der Entgegenkommende vorbeigefahren ist","Ich verständige mich mit dem Entgegenkommenden, wer zuerst fährt"],"co":[1],"ex":["Da der Gegenverkehr Vorrang hat, darf er vor dir fahren.","Du musst entgegenkommende Fahrzeuge vorbeifahren lassen, da der parkende Transporter auf deiner Fahrbahn steht. Erst wenn der Entgegenkommende vorbeigefahren bist, darfst du am Transporter vorbeifahren.","Wenn du beim Vorbeifahren des parkenden Transporters die Gegenfahrbahn benutzen musst, hat der Gegenverkehr immer Vorrang. Es kommt auch nicht darauf an, wer die Engstelle zuerst erreicht."],"i":["https://video2.kalaiwa.de/assets/1206101m.webp"],"rn":209},{"n":"1.2.07-001","t":"Was müssen Sie tun, wenn Sie den Fahrstreifen wechseln wollen?","p":4,"c":"1.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Vor dem Fahrstreifenwechsel immer stark abbremsen","Auf den nachfolgenden Verkehr achten","Fahrstreifenwechsel rechtzeitig ankündigen"],"co":[1,2],"ex":["Durch starkes Abbremsen behindern und gefährdest du den nachfolgenden Verkehr.","Du musst immer auch den nachfolgenden Verkehr beachten, um kein Fahrzeug zu behindern oder eine Kollision zu verursachen. Hierbei ist auch zu berücksichtigen, dass der Nachfolgende womöglich noch nicht bemerkt hat, dass du den Fahrstreifen wechseln willst.","Um die anderen Verkehrsteilnehmer rechtzeitig über Ihr Vorhaben zu informieren, musst du rechtzeitig den Fahrstreifenwechsel ankündigen (Blinken). Dadurch können sich die anderen Verkehrsteilnehmer darauf einstellen."],"rn":210},{"n":"1.2.07-113","t":"Auf einer Fahrbahn mit mehreren Fahrstreifen für eine Richtung endet ein Fahrstreifen. Wie haben Sie sich auf dem durchgehenden Fahrstreifen zu verhalten?","p":3,"c":"1.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["- an den am Weiterfahren gehinderten Fahrzeugen vorbeifahren","- Blickkontakt aufnehmen und dann je nach Situation entscheiden","- den am Weiterfahren gehinderten Fahrzeugen den Übergang nach dem Reißverschlussverfahren ermöglichen"],"co":[2],"ex":["Dann können diese nicht Weiterfahren. Dies würde den Verkehrsfluss behindern und eine Staugefahr begünstigen.","Hier wird nicht nach Blickkontakt oder situationsabhängig entschieden. Endet ein Fahrstreifen, gilt das Reißverschlussverfahren.","So wird das Risiko, dass ein Stau entsteht, reduziert."],"rn":211},{"n":"1.2.07-116","t":"Sie möchten an der Kreuzung nach rechts abbiegen. Wie verhalten Sie sich richtig?","p":4,"c":"1.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich verzichte auf das Rechtsabbiegen und bleibe in meinem Fahrstreifen","Ich lenke deutlich nach rechts und schaffe dadurch eine Lücke im rechten Fahrstreifen","Ich warte, bis alle Fahrzeuge vorbeigefahren sind, und wechsle dann in den rechten Fahrstreifen"],"co":[0],"ex":["Da du bereits links eingeordnet bist und auf dem rechten Fahrstreifen sehr viel Verkehr ist, musst du auf das Rechtsabbiegen verzichten und auf deinem Fahrstreifen bleiben.","Das würde dich und andere Verkehrsteilnehmer gefährden. Bleibe auf deiner Spur und verzichte aufs Rechtsabbiegen.","So würdest du den nachfolgenden Verkehr behindern."],"v":["https://video2.kalaiwa.de/assets/1207116v1440.mp4"],"rn":212},{"n":"1.2.07-105-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"1.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich wechsle in etwa 200 m auf den rechten Fahrstreifen","Ich wechsle jetzt auf den rechten Fahrstreifen","Ich darf die auf dem rechten Fahrstreifen fahrenden Fahrzeuge überholen"],"co":[0,2],"ex":["Es ist richtig, erst in 200 Metern zwischen den rechts fahrenden Autos einzufädeln. Du dürftest zwar bereits jetzt auf den rechten Streifen wechseln, allerdings soll der zur Verfügung stehende Platz genutzt werden. So kann ein möglicher Rückstau vermieden werden.","Du darfst jetzt nicht auf den rechten Fahrstreifen wechseln, da du mit dem rechts fahrenden, grünen Pkw kollidieren würdest.","Du darfst die auf dem rechten Fahrstreifen fahrenden Fahrzeuge überholen und dann in etwa 200 Metern vor ihnen auf die rechte Fahrspur wechseln."],"v":["https://video2.kalaiwa.de/assets/1207105mv1440.mp4"],"rn":213},{"n":"1.2.09-016","t":"Sie möchten nach links abbiegen. Wann müssen Sie auf den nachfolgenden Verkehr achten?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Nach dem Abbiegen","Vor dem Einordnen","Vor dem Abbiegen"],"co":[1,2],"ex":["Nach dem Abbiegen musst du den nachfolgenden Verkehr nicht mehr beobachten, da davon keine Gefahr mehr ausgeht.","Zum Einordnen muss in der Regel die Spur gewechselt werden. Dabei darfst du niemand behindern oder gefährden.","Du könntest von einem Verkehrsteilnehmer im Augenblick des Abbiegens überholt werden."],"rn":214},{"n":"1.2.09-017","t":"Zwei Fahrzeuge kommen sich auf einer Kreuzung entgegen. Beide Fahrzeuge möchten jeweils nach links abbiegen. In welchem Ausnahmefall müssen sie hintereinander abbiegen?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Wenn eine gleichrangige Kreuzung befahren wird","Wenn die Gestaltung der Kreuzung es erfordert","Wenn die Verkehrslage es erfordert"],"co":[1,2],"ex":["Bei einer gleichrangigen Kreuzung biegt man ganz normal voreinander ab. Das ist keine Ausnahme.","Eine Ausnahme ist, wenn die Kreuzungsgestaltung das voreinander Abbiegen nicht ermöglicht.","Wenn es die Verkehrslage nicht anders zulässt, biegt man nacheinander ab."],"rn":215},{"n":"1.2.09-018","t":"Zwei Fahrzeuge kommen sich auf einer Kreuzung entgegen. Beide Fahrzeuge möchten jeweils nach links abbiegen. Wie müssen sich die beiden Fahrer im Regelfall verhalten?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- voreinander abbiegen","- hintereinander abbiegen","- sich über die Art des Abbiegens verständigen"],"co":[0],"ex":["Kommen sich zwei Linksabbieger entgegen, biegen sie laut StVO voreinander (tangential) ab.","Nur wenn es die Verkehrssituation oder die Gestaltung der Kreuzung erfordern, biegen die beiden Fahrzeuge hintereinander ab.","Nur in Grenzfällen ohne eindeutige Kennzeichnung und in denen es unvermeidlich ist, verständigst du dich mit dem entgegenkommenden Linksabbieger."],"rn":216},{"n":"1.2.09-101","t":"Was kann bei mehrspurigem Abbiegen zu besonders gefährlichen Situationen führen?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Genaues Einhalten des Fahrstreifens","Fahrstreifenwechsel während des Abbiegens","Zu schnelles Fahren"],"co":[1,2],"ex":["Das genaue Einhalten des Fahrstreifens führt dazu, dass keine anderen Spuren beim Abbiegevorgang gekreuzt werden. Somit ist das eigene Handeln ungefährlich. Trotzdem ist es wichtig vorausschauend zu fahren und den Verkehrsfluss kontinuierlich zu beobachten.","Der Fahrstreifen ist bereits einige Zeit vor dem eigentlichen Abbiegevorgang zu wechseln. Ein Wechselns des Fahrstreifens während des Abbiegevorgangs ist nicht erlaubt, da nicht gleichzeitig auf nachfolgenden Verkehr des Fahrstreifenwechsels als auch auf sonstige Verkehrsteilnehmer beim Abbiegen zu achten wäre. So würden schnell Fehler und somit Unfälle entstehen. Daher macht es Sinn erst den Fahrstreifen zu wechseln und dann abzubiegen.","Zu schnelles Fahren kann dazu führen, dass ich während des Abbiegevorgangs ins Schleudern gerate und somit Gefahr laufe auf eine andere Spur zu kommen. Somit stelle ich eine Gefährdung für andere Verkehrsteilnehmer dar. Daher sollte der Abbiegevorgang stets langsam und unter Beobachtung des restlichen Verkehrs vorgenommen werden."],"rn":217},{"n":"1.2.09-109","t":"Sie befinden sich im Kreisverkehr. Was ist zu beachten?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Eine Mittelinsel darf nur überfahren werden, wenn dies aufgrund der Fahrzeuggröße unvermeidbar ist","Das Verlassen des Kreises muss durch Blinken angezeigt werden","Im Kreisverkehr ist das Halten auf der Fahrbahn verboten"],"co":[0,1,2],"ex":["Wie oben beschrieben, darf laut StVO § 9a Abs. 2 die Mittelinsel nur überfahren werden, wenn es aufgrund der Fahrzeuggröße nicht anders geht.","Das Ausfahren aus dem Kreisverkehr entspricht im Sinne der StVO einem Rechtsabbiegen. Demnach sind alle Regeln für das Abbiegen zu beachten. Wie oben beschrieben, sind dabei laut StVO § 9 Abs. 1 die Fahrtrichtungsanzeiger (Blinker) zu benutzen.","Wie oben beschrieben, ist laut StVO § 9a Abs. 1 das Halten auf der Fahrbahn verboten, wenn es sich um einen Kreisverkehr handelt."],"rn":218},{"n":"1.2.09-111","t":"In welcher Situation ist Wenden besonders gefährlich?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Vor Kurven","Bei Nebel","Vor Kuppen"],"co":[0,1,2],"ex":["Kurven können uneinsichtig sein.","Nebel blockiert die Sicht.","Kuppen können diese Sicht behindern."],"rn":219},{"n":"1.2.09-117","t":"In welchen Fällen müssen Sie eine Änderung der Fahrtrichtung anzeigen?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Wenn ich dem Verlauf einer abknickenden Vorfahrtstraße folgen will","Wenn ich eine abknickende Vorfahrtstraße in gerader Richtung verlassen will","Vor dem Abbiegen in eine Einmündung oder in ein Grundstück"],"co":[0,2],"ex":["Auch wenn du dich auf einer Vorfahrtsstraße befindest, musst du eine Änderung der Fahrtrichtung anzeigen, wenn diese abknickt.","Wenn du geradeaus fährst, änderst du die Fahrtrichtung nicht und musst dies somit auch nicht anzeigen.","Möchtest du in eine Einmündung oder in ein Grundstück abbiegen, dann musst du das durch Blinken anzeigen."],"rn":220},{"n":"1.2.09-119","t":"Warum müssen Sie jetzt warten?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- roten Fahrzeugs","- grünen Fahrzeugs","- Radfahrers"],"co":[1,2],"ex":["Du hast Vorrang vor dem roten Fahrzeug, weil du dich auf der Vorfahrtsstraße befindest.","Schließlich möchtest du von der Vorfahrtsstraße abfahren. Deswegen musst du warten, bis der grüne Transporter vorbeigefahren ist, um links in die Straße einzubiegen.","Du darfst erst zum Abbiegen ansetzen, wenn der Radfahrer auf der gegenüberliegenden Fahrbahnseite vorbeigefahren ist."],"v":["https://video4.kalaiwa.de/assets/1209119v1440.mp4"],"rn":221},{"n":"1.2.09-120","t":"Sie möchten links abbiegen. In welcher Reihenfolge bereiten Sie das Abbiegen vor?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Nachfolgenden Verkehr beobachten, Fahrtrichtung anzeigen, einordnen","Fahrtrichtung anzeigen, einordnen, nachfolgenden Verkehr beobachten","Einordnen, Fahrtrichtung anzeigen, nachfolgenden Verkehr beobachten"],"co":[0],"ex":["Das ist die richtige Reihenfolge, um ein sicheres Abbiegen zu ermöglichen.","Du musst zuerst den nachfolgenden Verkehr beobachten.","Das wäre sehr gefährlich. Am wichtigsten ist es, zuerst den nachfolgenden Verkehr zu beobachten. Ermöglicht dieser ein Abbiegen, darfst du die Fahrtrichtung anzeigen und dich einordnen."],"rn":222},{"n":"1.2.09-121","t":"Welches Verhalten ist richtig?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich muss an der Haltlinie anhalten","Ich darf vor dem Radfahrer abbiegen","Ich muss den Radfahrer durchfahren lassen"],"co":[0,2],"ex":["Bevor du auf die Kreuzung fahren darfst, musst du an der Haltlinie vor dem \"Stopp\"-Schild halten.","Weil du Abbiegen willst, musst du warten. Derjenige, der geradeaus fährt, hat Vorfahrt. Das ist in diesem Fall der Radfahrer.","Bevor du abbiegst, musst du den Radfahrer durchfahren lassen."],"i":["https://video2.kalaiwa.de/assets/1209121.webp"],"rn":223},{"n":"1.2.09-123","t":"Sie möchten nach links abbiegen. Wem müssen Sie Vorrang gewähren?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Entgegenkommenden Kraftfahrzeugen","Fußgängern, welche die Straße überqueren wollen, in die ich einbiege","Entgegenkommenden Radfahrern"],"co":[0,1,2],"ex":["Du musst den entgegenkommenden Fahrzeugen Vorrang gewähren, bevor du links abbiegen kannst.","Du darfst erst nach links abbiegen, wenn gewährleistet ist, dass du dadurch niemanden behinderst oder gefährdest. Erst, wenn die Fußgänger die Straße vollständig überquert haben, darfst du zum Abbiegen ansetzen.","Die entgegenkommenden Radfahrer haben Vorrang."],"rn":224},{"n":"1.2.09-124","t":"Sie wollen links abbiegen. Welche Schwierigkeiten können dabei auftreten?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Linksabbieger können sich gefährlich nahekommen","Sichteinschränkungen durch Entgegenkommende","Missverständnisse mit entgegenkommenden Linksabbiegern"],"co":[0,1,2],"ex":["Wenn zwei entgegenkommende Fahrzeuge zum Linksabbiegen ansetzen, kann die Distanz zum anderen Fahrzeug schwer eingeschätzt werden. Bremse frühzeitig ab, um mit genügend Abstand vor ihm abbiegen zu können.","Ist die Sicht durch entgegenkommende Fahrzeuge eingeschränkt, musst du mit dem Abbiegen warten, bis der Gegenverkehr übersichtlicher ist.","Man soll voreinander abbiegen. Wenn der Gegenverkehr dies nicht tut, kann das zu einem Missverständnis führen. Dann biegt man nacheinander ab."],"rn":225},{"n":"1.2.09-125","t":"Warum müssen Sie jetzt anhalten?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Wegen des weißen Pkws","Wegen des Radfahrers","Wegen der Straßenbahn"],"co":[2],"ex":["Du hast Vorfahrt vor dem weißen PKW, weil du dich auf einer Vorfahrtsstraße befindest.","Da der Radfahrer geradeaus weiterfährt und du links abbiegen willst, stellt er keinen Grund dar anzuhalten.","Du darfst erst abbiegen, wenn die Straßenbahn vorbeigefahren ist."],"v":["https://video4.kalaiwa.de/assets/1209125v1440.mp4"],"rn":226},{"n":"1.2.09-126","t":"Wie verhalten Sie sich hier richtig?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- nicht vor dem Bahnübergang überholen","- jetzt mit ausreichendem Seitenabstand überholen","- vor dem Bahnübergang überholen, sobald der Radfahrer weg ist"],"co":[0],"ex":["Du musst hiermit warten, bis du den Bahnübergang überquert hast.","Du darfst so kurz vor dem Bahnübergang nicht mehr überholen.","Das Überholen vor Bahnübergängen ist untersagt."],"v":["https://video4.kalaiwa.de/assets/1209126v1440.mp4"],"rn":227},{"n":"1.2.09-127","t":"Warum müssen Sie jetzt bremsen?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Wegen des Motorrads","Wegen der Radfahrerin","Wegen des Transporters"],"co":[0],"ex":["Der Motorradfahrer wird vom Transporter verdeckt. Allerdings fährt er, obwohl er keine Vorfahrt hat, mit hoher Geschwindigkeit in deine Straße ein. Bremse ab, um ihn nicht zu gefährden.","Die Radfahrerin befindet sich auf dem Radweg und ist somit kein Risiko, das ein Bremsen notwendig machen würde.","Der Transporter stellt für dich keinen Grund zu bremsen dar."],"v":["https://video4.kalaiwa.de/assets/1209127v1440.mp4"],"rn":228},{"n":"1.2.09-129","t":"Was müssen Sie hier beachten?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- dem Pkw die Vorfahrt gewähren","- bei Einfahrt in den Kreisverkehr blinken","- weiter abbremsen"],"co":[0,2],"ex":["Du darfst erst in den Kreisverkehr einfahren, nachdem du dem blauen PKW die Vorfahrt gewährt hast.","Bei Einfahrt in den Kreisverkehr zu blinken kann gefährlich werden, weil andere Verkehrsteilnehmer davon ausgehen, dass du an der nächsten Ausfahrt herausfährst. Du musst immer beim Ausfahren aus dem Kreisverkehr blinken.","Du musst demjenigen, der sich bereits im Kreisverkehr befindet, die Vorfahrt gewähren. Hierfür musst du weiter abbremsen."],"v":["https://video4.kalaiwa.de/assets/1209129v1440.mp4"],"rn":229},{"n":"1.2.09-019-M","t":"Sie möchten nach links abbiegen. Welche Fahrlinie müssen Sie einhalten?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Die rechte Fahrlinie","Beide Fahrlinien sind möglich","Die linke Fahrlinie"],"co":[0],"ex":["Du bleibst auch beim Abbiegen auf deiner Fahrlinie und wechselst dabei keinesfalls den Fahrstreifen.","Das Befahren der Gegenfahrbahn ist verboten. Du bleibst auf deiner Fahrlinie, sonst wird's gefährlich.","Autos könnten dir entgegenkommen. Einen an dir vorbeigefahrenen Pkw siehst du noch in deinem linken Seitenspiegel."],"i":["https://video2.kalaiwa.de/assets/1209019m.webp"],"rn":230},{"n":"1.2.09-020-M","t":"Welchem Verkehrsteilnehmer müssen Sie hier Vorrang gewähren?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Dem Radfahrer","Der Fußgängerin","Dem Bus"],"co":[0,1],"ex":["Beim Abbiegen musst du dem Gegenverkehr – hier dem Radfahrer – Vorrang gewähren.","Obwohl deine Ampel Grün zeigt, musst du warten, bis die Fußgängerin die Straße überquert hat. Fußgänger haben Vorrang vor abbiegenden Fahrzeugen.","Du hast Vorfahrt vor dem Bus, weil seine Ampel Rot zeigt."],"v":["https://video4.kalaiwa.de/assets/1209020mv1440.mp4"],"rn":231},{"n":"1.2.09-021-M","t":"Sie möchten den Kreisverkehr an dieser Ausfahrt verlassen. Was ist richtig?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich muss den Radfahrer die Fahrbahn überqueren lassen","Ich habe Vorrang vor den die Fahrbahn überquerenden Verkehrsteilnehmern","Ich muss die Fußgängerin die Fahrbahn überqueren lassen"],"co":[0,2],"ex":["Querende Radfahrer auf einem Radweg haben Vorrang vor Fahrzeugen, die den Kreisverkehr verlassen. Lasse den Radfahrer die Fahrbahn überqueren.","Bei der Ausfahrt aus dem Kreisverkehr haben querende Fußgänger und Radfahrer Vorrang.","Querende Fußgänger haben Vorrang vor Fahrzeugen, die den Kreisverkehr verlassen. Lasse die Fußgängerin die Fahrbahn überqueren."],"i":["https://video2.kalaiwa.de/assets/1209021m.webp"],"rn":232},{"n":"1.2.09-022-M","t":"Sie möchten hier nach rechts abbiegen. Was ist richtig?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich habe Vorrang vor beiden Fußgängern","Ich muss beide Fußgänger die Fahrbahn überqueren lassen","Ich muss nur den entgegenkommenden Fußgänger die Fahrbahn überqueren lassen"],"co":[1],"ex":["Du musst beiden Fußgängern Vorrang gewähren.","Du musst beide Fußgänger die Fahrbahn überqueren lassen. Sie ändern ihre Bewegungsrichtung nicht und haben deshalb Vorrang vor dir.","Du musst auch den in deine Richtung laufenden Fußgänger die Fahrbahn überqueren lassen."],"i":["https://video4.kalaiwa.de/assets/1209022m.webp"],"rn":233},{"n":"1.2.09-103-B","t":"Alle drei Fahrzeuge wollen links abbiegen. Wer hat sich richtig eingeordnet?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Der gelbe Pkw","Der grüne Pkw","Der Lkw"],"co":[0],"ex":["Der gelbe PKW ist wie vorgeschrieben rechts am Hindernis vorbeigefahren, um anschließend links abzubiegen.","Der grüne PKW steht auf den Schienen und hat sich nicht an das Verkehrszeichen gehalten, dass signalisiert, dass rechts am Hindernis vorbeigefahren werden soll.","Der LKW hat sich auf der rechten Fahrspur eingeordnet. Er hätte sich links einordnen müssen, um nach links abbiegen zu können."],"i":["https://video2.kalaiwa.de/assets/1209103b.webp"],"rn":234},{"n":"1.2.09-104-B","t":"Nach dem Linksabbiegen wollen Sie sofort rechts abbiegen. Wie ordnen Sie sich ein?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- grüne Pkw","- rote Pkw","- blaue Pkw"],"co":[1],"ex":["Würdest du dich hinter dem grünen PKW einordnen, dann müsstest du vor dem Rechtsabbiegen noch einmal die Spur wechseln, was auf so kurzer Strecke mit Verkehr riskant sein kann.","Der rote PKW befindet sich auf der rechten linken Spur. So ist nach dem Linksabbiegen ein Rechtsabbiegen ohne Spurwechsel möglich.","Der blaue PKW steht zwischen beiden Fahrstreifen. Das ist nicht erlaubt und irritiert andere Verkehrsteilnehmer."],"i":["https://video4.kalaiwa.de/assets/1209104b.webp"],"rn":235},{"n":"1.2.09-107-B","t":"Wer muss die Fahrtrichtungsänderung anzeigen?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Keiner","Ich selbst","Das Motorrad"],"co":[2],"ex":["Du musst keine Fahrtrichtungsänderung anzeigen, da du geradeaus fährst. Der Motorradfahrer muss allerdings den Blinker betätigen und signalisieren, dass er links abbiegt.","Du änderst deine Fahrtrichtung ja nicht.","Jede Richtungsänderung muss durch Blinken angezeigt werden, auch wenn man die Vorfahrtstraße nicht verlässt."],"i":["https://video2.kalaiwa.de/assets/1209107b.webp"],"rn":236},{"n":"1.2.09-112-M","t":"Wer muss blinken?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Der rote Pkw","Ich selbst","Der blaue Lkw"],"co":[1,2],"ex":["Der rote PKW möchte geradeaus weiterfahren. Nur Fahrtrichtungsänderungen können durch Blinken angezeigt werden.","Das Verkehrsschild bedeutet \"abknickende Vorfahrtsstraße\". Du hast also Vorfahrt vor Verkehrsteilnehmern, die sich nicht auf der Vorfahrtsstraße befinden. Die Änderung der Fahrrichtung musst du trotzdem anzeigen.","Der blaue LKW muss blinken, weil er seine Fahrtrichtung ändert."],"i":["https://video2.kalaiwa.de/assets/1209112m.webp"],"rn":237},{"n":"1.2.09-113-M","t":"Wer muss hier die Fahrtrichtungsänderung anzeigen?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Das Motorrad","Der rote Pkw","Ich selbst"],"co":[0,1,2],"ex":["Der Motorradfahrer muss, bevor er nach rechts abbiegt, den Blinker setzen.","Der rote PKW muss nach links blinken, bevor er abbiegt.","Weil du nach links abbiegst, musst du die Änderung deiner Fahrtrichtung anzeigen."],"i":["https://video4.kalaiwa.de/assets/1209113m.webp"],"rn":238},{"n":"1.2.09-128-M","t":"Warum müssen Sie vor dem Rechtsabbiegen warten?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Wegen der Radfahrerin","Wegen der Fußgängerin","Wegen des schwarzen Pkws"],"co":[0,1],"ex":["Du musst der Radfahrerin das Durchfahren gewähren, bevor du nach rechts abbiegen darfst.","Du darfst erst abbiegen, wenn die Fußgängerin die Straße vollständig überquert hat.","Der schwarze PKW ist kein Grund für dich, mit dem Rechtsabbiegen zu warten. Du hast Vorfahrt."],"v":["https://video2.kalaiwa.de/assets/1209128mv1440.mp4"],"rn":239},{"n":"1.2.09-131-M","t":"Der Radfahrer möchte geradeaus fahren. Wie verhalten Sie sich hier richtig?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich überhole den Radfahrer","Ich bleibe hinter dem Radfahrer"],"co":[1],"ex":["So würdest du den Radfahrer behindern oder sogar gefährden.","Du darfst erst abbiegen, wenn der Radfahrer geradeaus durchgefahren ist."],"i":["https://video4.kalaiwa.de/assets/1209131m.webp"],"rn":240},{"n":"1.2.09-132-M","t":"Warum müssen Sie in dieser Situation mit dem Abbiegen warten?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Wegen des Motorrads","Wegen des Lkws","Wegen der Fußgängerin"],"co":[0,1],"ex":["Das Motorrad, welches hinter dem Lkw auf entgegenkommender Fahrbahn fährt, hat Vorfahrt. Du darfst erst abbiegen, wenn du sicher sein kannst, den Gegenverkehr nicht zu behindern.","Der Lkw behindert die Sicht auf die Straße, in die du einbiegen willst. Du musst warten, bis der Lkw weiter gefahren ist. Dann musst du dich vergewissern, dass kein anderer Verkehrsteilnehmer Vorfahrt hat bzw. die Fahrbahn blockiert.","Die Fußgängerin befindet sich auf dem Fußweg und stellt kein Hindernis beim Linksabbiegen dar."],"v":["https://video4.kalaiwa.de/assets/1209132mv1440.mp4"],"rn":241},{"n":"1.2.09-133-M","t":"Wer muss in dieser Situation blinken?","p":3,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich selbst","Der rote Pkw","Der blaue Pkw"],"co":[0,2],"ex":["Das gelb-weiße Zeichen zeigt dir, dass du dich auf der Vorfahrtsstraße befindest und im gesamten Verlauf der Straße Vorfahrt hast. Das Zusatzzeichen darunter zeigt dir den Verlauf der abknickenden Vorfahrtsstraße an. Du musst immer rechtzeitig blinken, wenn du ihr folgst.","Der rote Pkw fährt von der Nebenstraße geradeaus weiter auf die Vorfahrtsstraße ein. Er biegt nicht ab, also muss er nicht blinken.","Der blaue Pkw muss blinken, weil er abbiegt. Bei einem Abbiegevorgang muss immer geblinkt werden."],"i":["https://video2.kalaiwa.de/assets/1209133m.webp"],"rn":242},{"n":"1.2.09-134-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich bleibe zunächst auf dem rechten Fahrstreifen","Ich bremse ab","Ich wechsle umgehend auf den linken Fahrstreifen"],"co":[0,1],"ex":["Das Motorrad hinter dir hat bereits auf den linken Fahrstreifen gewechselt und wird dich links überholen. Um einen Unfall zu vermeiden, musst du vorerst auf dem rechten Fahrstreifen bleiben.","Du willst nach links abbiegen. Das Motorrad wird links an dir vorbeifahren. Um noch rechtzeitig auf die Linksabbiegerspur einfädeln zu können, musst du abbremsen.","Das Motorrad befindet sich links von dir im toten Winkel. Würdest du umgehend auf den linken Fahrstreifen wechseln, würde es zu einer Kollision kommen."],"v":["https://video4.kalaiwa.de/assets/1209134mv1440.mp4"],"rn":243},{"n":"1.2.09-135-M","t":"Warum dürfen Sie jetzt nicht abbiegen?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- roten Fahrzeugs","- grünen Pkws","- gelben Pkws"],"co":[2],"ex":["Das rote Fahrzeug will ebenfalls links abbiegen. Hier gilt das voreinander Linksabbiegen. Ihr biegt also beide so voreinander ab, dass sich eure beiden Fahrspuren nicht kreuzen.","Der grüne Pkw fährt geradeaus und beeinträchtigt deinen Abbiegevorgang deshalb nicht.","Auf einer Kreuzung haben Geradeausfahrer Vorfahrt. Du musst mit dem Abbiegen also warten, bis der gelbe Pkw die Kreuzung überquert hat."],"v":["https://video2.kalaiwa.de/assets/1209135mv1440.mp4"],"rn":244},{"n":"1.2.09-136-M","t":"Womit müssen Sie in dieser Situation rechnen?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Der Fußgänger wird warten","Der blaue Pkw fährt geradeaus","Der rote Bus fährt sofort an"],"co":[1],"ex":["Du musst damit rechnen, dass der Fußgänger die Straße ohne zu warten überquert.","Der blaue Pkw fährt an dem haltenden Bus vorbei und will eventuell gerade aus weiterfahren, obwohl er auf der Abbiegespur ist. Da du links abbiegst, hat er Vorfahrt.","Der Bus hält, um Personen einsteigen zu lassen. Er wird nicht sofort anfahren."],"v":["https://video2.kalaiwa.de/assets/1209136mv1440.mp4"],"rn":245},{"n":"1.2.09-137-M","t":"Warum müssen Sie jetzt anhalten?","p":5,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Wegen der Straßenbahn","Wegen der Fußgänger","Wegen des Elektrorollers"],"co":[2],"ex":["Die Straßenbahn beeinflusst dein Abbiegen nicht.","Die Fußgänger sind weit genug weg. Wenn du abbiegen würdest, würdest du keine Fußgänger gefährden.","Der Elektroroller befindet sich in deinem toten Winkel. Du musst anhalten, um ihn nicht zu gefährden."],"v":["https://video2.kalaiwa.de/assets/1209137mv1440.mp4"],"rn":246},{"n":"1.2.09-138-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich lasse den Radfahrer durchfahren","Ich führe den Schulterblick nach rechts durch","Ich biege vor dem Elektroroller ab"],"co":[0,1],"ex":["Du musst den Radfahrer durchfahren lassen, bevor du rechts abbiegst. Als abbiegender Autofahrer hast du die Pflicht, zu warten und den Radfahrer die Straße zuerst überqueren zu lassen.","Bevor du abbiegst, musst du immer einen Schulterblick durchführen, um mögliche von hinten kommende Passanten zu sehen. In dieser Situation musst du nachts rechts über deine Schulter schauen und kannst so die Entfernung zum Radfahrer einschätzen, anhalten und ihn vorlassen.","Du musst auch den Elektroroller aus der entgegengesetzten Richtung vorlassen. Für dich als abbiegenden Autofahrer gilt hier ebenfalls die Wartepflicht. Somit hat der Elektroroller Vorrang. Außerdem würdest du mit dem Radfahrer kollidieren, wenn du jetzt abbiegst."],"v":["https://video2.kalaiwa.de/assets/1209138mv1440.mp4"],"rn":247},{"n":"1.2.10-005","t":"Sie kommen aus einer Straße mit abgesenktem Bordstein und wollen in eine andere Straße einbiegen. Von links kommt ein Pkw. Was gilt hier?","p":4,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Wer über einen abgesenkten Bordstein in eine Straße einfährt, ist wartepflichtig","Die Regel „rechts vor links“","Der abgesenkte Bordstein ist für die Wartepflicht ohne Bedeutung"],"co":[0],"ex":["Hier gelten die selben Regeln wie beim Verlassen einer Ausfahrt. Entsprechend muss allen anderen Verkehrsteilnehmern der Vorrang eingeräumt werden.","Auch ein von links kommender PKW hat Vorfahrt, da hier die Regel \"rechts vor links\" nicht greift. Allen anderen Verkehrsteilnehmern ist Vorfahrt zu gewähren.","Das Gegenteil ist der Fall. Der abgesenkte Bordstein signalisiert eine Wartepflicht. Entsprechend dürfen alle anderen Verkehrsteilnehmer vor einem selbst fahren."],"rn":248},{"n":"1.2.10-101","t":"Wie verhalten Sie sich beim Anfahren vom Fahrbahnrand?","p":4,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Rückwärtigen Verkehr beobachten","Blinken","Blick in den Rückspiegel genügt"],"co":[0,1],"ex":["Wie oben beschrieben, darf beim Anfahren vom Fahrbahnrand niemand gefährdet werden. Um dies zu gewährleisten müssen die anderen Verkehrsteilnehmer und die Verkehrssituation genau beobachtet werden. Hierzu sollten Innen- und Außenspiegel des Fahrzeugs genutzt werden.","Damit andere Verkehrsteilnehmer die eigene Absicht erkennen auf die Straße einzufahren, sollte der Blinker (Fahrtrichtungsanzeige) eingesetzt werden.","Wie oben beschrieben muss zum Anfahren die Fahrtrichtungsanzeige (Blinklicht) verwendet werden. Die Beobachtung der anderern Verkehrsteilnehmer allein genügt also nicht."],"rn":249},{"n":"1.2.10-104","t":"Sie möchten aus einem verkehrsberuhigten Bereich in eine Straße einfahren. Wie müssen Sie sich verhalten?","p":4,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["- vor dem Abbiegen die Fahrtrichtung anzeigen","- die Regel „rechts vor links“ beachten","- Fußgänger auf dem Gehweg vorbeigehen lassen"],"co":[0,2],"ex":["Jede Fahrtrichtungsänderung muss durch Blinken angezeigt werden.","Wenn du einen verkehrsberuhigten Bereich verlässt, dann bist du allen anderen Fahrzeugen gegenüber in der Wartepflicht. Die Grundregel \"rechts vor links\" gilt in diesem Fall nicht.","Fußgänger haben Vorrang vor Fahrzeugen."],"rn":250},{"n":"1.2.10-105","t":"Sie wollen aus einem verkehrsberuhigten Bereich in eine Straße einfahren. Von links kommen Radfahrer. Wer muss warten?","p":4,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Alle müssen anhalten und sich dann verständigen","Ich muss warten","Die Radfahrer müssen warten"],"co":[1],"ex":["Die anderen Verkehrsteilnehmer haben Vorrang. Weil du aus einem verkehrsberuhigten Bereich herausfährst, bist du wartepflichtig.","Fährt man aus einem verkehrsberuhigten Bereich heraus, ist man wartepflichtig. Die Grundregel \"rechts vor links\" gilt in diesem Fall nicht.","Die Radfahrer haben Vorrang und du musst warten."],"rn":251},{"n":"1.2.10-106","t":"Sie wollen aus einem Grundstück nach rechts in eine Straße einbiegen. Von links kommen Radfahrer. Wer muss warten?","p":4,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Alle müssen anhalten und sich dann verständigen","Die Radfahrer müssen warten","Ich muss warten"],"co":[2],"ex":["Du bist in der Wartepflicht, die Radfahrer haben Vorfahrt.","Die Radfahrer haben Vorfahrt und müssen nicht warten. Du musst ihnen Vorrang gewähren.","Du darfst erst aus dem Grundstück auf die Straße fahren, wenn du gewährleisten kannst, dass dadurch kein Verkehrsteilnehmer behindert wird. Du musst Vorrang gewähren und somit die von links kommenden Radfahrer vorbeifahren lassen, bevor du in die Straße einbiegst."],"rn":252},{"n":"1.2.10-107","t":"Sie wollen aus einem Grundstück über den Gehweg auf die Fahrbahn einbiegen. Worauf müssen Sie achten?","p":4,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Verkehrsteilnehmer auf dem Gehweg dürfen nicht gefährdet werden","Gegebenenfalls ist ein Einweisen erforderlich","Immer zuerst auf den fließenden Verkehr auf der Fahrbahn achten"],"co":[0,1],"ex":["Du darfst den Gehweg erst passieren, wenn du dir sicher bist, dass dadurch keine Verkehrsteilnehmer gefährdet werden.","Ermöglicht die Ausfahrt keine klare Sicht auf den Gehweg, dann ist kein sicheres Abbiegen auf die Fahrbahn gewährleistet und du solltest Hilfe einfordern.","In erster Linie musst du auf den Gehweg achten und sichergehen, dass durch das Ausfahren vom Grundstück auf die Straße keine Fußgänger behindert werden."],"rn":253},{"n":"1.2.10-108","t":"Sie möchten aus dem Grundstück ausfahren. Was ist richtig?","p":4,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Ich muss warten, bis die Fußgänger die Ausfahrt überquert haben","Ich hupe kurz, damit mich die Fußgänger ausfahren lassen","Ich darf fahren, falls die Fußgänger auf ihren Vorrang verzichten"],"co":[0,2],"ex":["Die Fußgänger haben Vorrang vor dir. Du darfst dich erst aus der Ausfahrt heraustasten, wenn sie diese vollständig überquert haben.","Die Hupe darf nur getätigt werden, wenn man eine Gefährdung für sich selbst oder andere Verkehrsteilnehmer sieht, oder außerorts als Warnsignal. In diesem Fall ist das Hupen nicht gestattet.","Du musst die Fußgänger vorbeigehen lassen, bevor du aus der Ausfahrt herausfahren darfst."],"i":["https://video2.kalaiwa.de/assets/1210108.webp"],"rn":254},{"n":"1.2.10-109","t":"Sie möchten mit Ihrem Fahrzeug aus einer Parklücke in den fließenden Verkehr einfahren. Wie müssen Sie sich verhalten?","p":2,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Ich muss vor dem Anfahren blinken","Ich darf den fließenden Verkehr nicht gefährden","Ich muss den rückwärtigen Verkehr beobachten"],"co":[0,1,2],"ex":["So zeigst du anderen Verkehrsteilnehmern, dass du aus der Parklücke ausfahren willst.","Du musst warten, bis eine ausreichende Lücke im fließenden Verkehr ist, um herausfahren zu dürfen.","Du darfst nur aus der Parklücke herausfahren, wenn du hierbei den rückwärtigen Verkehr nicht behinderst."],"rn":255},{"n":"1.2.10-006-M","t":"Sie möchten aus der Tankstelle ausfahren. Was ist richtig?","p":3,"c":"1.2.10","ch":"Einfahren Und Anfahren","th":"Verhalten Im Strassenverkehr","o":["Ich muss querenden Fußgängern Vorrang gewähren","Ich habe Vorfahrt vor von links kommenden Fahrzeugen","Ich darf in beide Richtungen ausfahren"],"co":[0],"ex":["Du musst dem querenden Fußgänger den Vortritt lassen.","Wenn du von einem Privatgelände auf eine Straße einbiegen möchtest, musst du anderen Fahrzeugen Vorfahrt gewähren.","Das blaue Verkehrsschild mit dem weißen Pfeil bedeutet „vorgeschriebene Fahrtrichtung rechts“. Hier darfst du somit nur nach rechts abbiegen."],"v":["https://video4.kalaiwa.de/assets/1210006mv1440.mp4"],"rn":256},{"n":"1.2.11-003","t":"Bei stockendem Verkehr müssen bestimmte Bereiche freigehalten werden. Welche sind dies?","p":4,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Grundstückseinfahrten","Bahnübergänge","Kreuzungen"],"co":[1,2],"ex":["Es gibt keine generelle Verpflichtung bei stockendem Verkehr Grundstückseinfahrten freizuhalten. Dennoch ist es sinnvoll eine Grundstückseinfahrt freizuhalten, wenn du siehst, dass jemand das Grundstück befahren bzw. verlassen möchte.","Da du bei stockendem Verkehr nicht mit Sicherheit sagen kannst, wann sich die vor dir fahrenden Fahrzeuge wieder in Bewegung setzen und den Bahnübergang wieder räumen, begibst du dich in höchste Gefahr, wenn du im Gleisraum zum Stehen kommst. Sollten sich die Schranken schließen, so hast du keinerlei Möglichkeit mehr mit deinem Fahrzeug die Schienen zu verlassen. Eine Kollision mit dem herannahenden Zug wäre unvermeidbar.","Kreuzungen müssen bei stockendem Verkehr generell freigehalten werden, da andernfalls zusätzlich noch der Querverkehr blockiert und der Verkehrsfluss somit unnötig behindert werden würde."],"rn":257},{"n":"1.2.11-006","t":"Welche Bereiche im Straßenverkehrsraum müssen bei stockendem Verkehr frei gehalten werden?","p":4,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Fußgängerüberwege","Einmündungen","Bushaltestellen"],"co":[0,1],"ex":["Fußgängerüberwege müssen freigehalten werden, damit Fußgänger hier gefahrlos queren können.","Bei stockendem Verkehr müssen Einmündungen freigehalten werden, um Fahrzeuge, die in andere Richtungen fahren, nicht zu blockieren.","Bushaltestellen müssen nicht freigehalten werden."],"rn":258},{"n":"1.2.11-104","t":"Wie verhalten Sie sich?","p":5,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Zunächst im Bereich der Mittelinsel warten, wo der andere Pkw steht","Vor dem Linksabbiegen warten und den Bereich der Mittelinsel frei halten","Flüssig abbiegen, um die Nachfolgenden nicht zu behindern"],"co":[1],"ex":["So würdest du ein Hindernis für die Straßenbahn darstellen. Du musst warten, bis die Mittelinsel frei ist und dann erst darauf fahren, um links abzubiegen.","Im Rückspiegel siehst du die herannahende Straßenbahn. Der weiße PKW steht auf den Schienen. Damit er diese ungehindert für die Straßenbahn räumen kann, musst du warten. Fahre erst auf die Mittelinsel, wenn die Straßenbahn diese passiert hat und der Weg frei ist.","Der weiße PKW muss die Mittelinsel schnellstmöglich verlassen, damit die Straßenbahn weiterfahren kann. Du musst mit dem Linksabbiegen warten und ihm dies gewähren."],"v":["https://video4.kalaiwa.de/assets/1211104v1440.mp4"],"rn":259},{"n":"1.2.11-105","t":"Welches Verhalten ist richtig?","p":5,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Nach links ausscheren","Beschleunigen","Verzögern"],"co":[2],"ex":["Du darfst hier nicht nach links ausscheren, weil der Gegenverkehr bereits zu nah ist. Du kannst den Radfahrer nicht sicher überholen. Lass ihn die Unterführung durchfahren und warte im Bedarfsfall, bis auch der Gegenverkehr diese passiert hat, bis du an der Reihe bist.","Du darfst hier nicht beschleunigen. Du musst verzögern, damit der Radfahrer die Unterführung ungehindert passieren kann.","Der Radfahrer wird nach links ausscheren, um durch die Unterführung fahren zu können. Du musst verzögern, damit du ihn nicht dabei behinderst."],"v":["https://video2.kalaiwa.de/assets/1211105v1440.mp4"],"rn":260},{"n":"1.2.11-108","t":"In welchen Fällen dürfen Sie nicht in eine Kreuzung einfahren, obwohl die Ampel „Grün“ zeigt?","p":4,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Wenn ein Polizeibeamter „Halt“ gebietet","Wenn ich auf der Kreuzung warten muss, weil der Verkehr stockt","Wenn an der Kreuzung das Verkehrszeichen „Halt. Vorfahrt gewähren.“ steht"],"co":[0,1],"ex":["Polizeibeamte stehen an erster Stelle der Verkehrsregelung, gefolgt von Ampeln, Verkehrszeichen und der Grundregel \"rechts vor links\".","In diesem Fall musst du vor der grünen Ampel mit dem Weiterfahren warten, bis die Kreuzung wieder frei ist.","Das Verkehrszeichen gilt nur, wenn die Ampel nicht eingeschaltet ist."],"rn":261},{"n":"1.2.11-111","t":"Warum müssen Sie weiterhin bremsen?","p":4,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["- Radfahrers","- blauen Lkws","- Müllfahrzeugs"],"co":[1,2],"ex":["Die Radfahrerin befindet sich auf der anderen Straßenseite auf dem Radweg und stellt somit keinen Grund für dich abzubremsen dar.","Der blaue LKW wird aufgrund des Zusatzanhängers sehr lange brauchen, um die Kurve zu fahren. Stell dich darauf ein, hier abzubremsen und zu warten.","Aus deiner Perspektive kannst du nicht sehen, ob das Müllfahrzeug nach links oder rechts abbiegen will. So oder so musst du abbremsen, um es nicht dabei zu behindern. Der Fahrer des Müllfahrzeugs sieht dich aufgrund des LKWs ebenso wenig, wie du ihn."],"v":["https://video4.kalaiwa.de/assets/1211111v1440.mp4"],"rn":262},{"n":"1.2.11-112","t":"Sie möchten geradeaus fahren. Wie sollten Sie sich verhalten?","p":4,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["- an der Haltlinie","- zwischen dem gelben und dem blauen Fahrzeug","- unmittelbar hinter dem gelben Fahrzeug"],"co":[0],"ex":["Du solltest nur bei grün über die Kreuzung fahren, wenn du sie dadurch nicht verstopfst. In diesem Fall solltest du an der Haltlinie warten, bis der vorausgehende Verkehr weitergefahren ist.","Du musst dich für eine Spur entscheiden. Du solltest jedoch erst fahren, wenn du dadurch die Kreuzung nicht verstopfst.","Dann würdest du auf der Kreuzung stehen und den Querverkehr beim Durchfahren behindern."],"v":["https://video2.kalaiwa.de/assets/1211112v1440.mp4"],"rn":263},{"n":"1.2.11-007-M","t":"Sie möchten geradeaus weiterfahren. Was ist in dieser Situation richtig?","p":4,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Ich warte an der Haltlinie","Ich überquere die Kreuzung","Ich lasse den geschlossenen Verband durchfahren"],"co":[0,2],"ex":["Wenn dir wie im Bild ein geschlossener Verband begegnet, der durch farbige Flaggen gekennzeichnet ist, musst du trotz Vorfahrt an der Haltlinie warten, bis das letzte Fahrzeug die Kreuzung passiert hat.","Du bist zwar auf der Vorfahrtsstraße, aber trotzdem darfst du die Kreuzung erst dann überqueren, wenn das letzte Fahrzeug des geschlossenen Verbands durchgefahren ist.","Hier musst du den geschlossenen Verband durchfahren lassen, bevor du weiterfährst."],"i":["https://video2.kalaiwa.de/assets/1211007m.webp"],"rn":264},{"n":"1.2.11-103-M","t":"Sie möchten geradeaus weiterfahren. Wie verhalten Sie sich richtig?","p":4,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Ich wechsle bei einer ausreichenden Verkehrslücke nach rechts","Ich überhole das neben mir fahrende Fahrzeug und wechsle den Fahrstreifen","Ich bleibe zunächst in meinem Fahrstreifen"],"co":[0,2],"ex":["Sobald das Fahrzeug neben dir vorbeigefahren und rechts eine ausreichend große Lücke frei ist, kannst du auf die rechte Spur wechseln.","Das wäre zu riskant, weil der Abstand zum vorderen Fahrzeug zu gering wäre.","Rechts neben dir ist ein Fahrzeug. Daher kannst du jetzt noch nicht auf die rechte Spur wechseln."],"i":["https://video4.kalaiwa.de/assets/1211103m.webp"],"rn":265},{"n":"1.2.11-110-M","t":"Warum müssen Sie hier verzögern und bremsbereit sein?","p":5,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["- Fußgängers","- Radfahrers","- grünen Fahrzeugs"],"co":[1],"ex":["Der Fußgänger befindet sich in ausreichendem Abstand zu dir auf dem Gehweg und stellt somit keinen Grund dar, bremsbereit zu sein und zu verzögern.","Der Radweg endet kurz vor der Unterführung, weshalb der Radfahrer auf die Fahrbahn wechseln muss. Vermindere deshalb die Geschwindigkeit und lass ihn bei Bedarf vor dir in die Unterführung einfahren.","Das grüne Auto parkt auf der Gegenfahrbahn und stellt für dich keine Risikosituation dar."],"v":["https://video2.kalaiwa.de/assets/1211110mv1440.mp4"],"rn":266},{"n":"1.2.11-114-M","t":"Wann dürfen Sie abbiegen?","p":3,"c":"1.2.11","ch":"Besondere Verkehrslagen","th":"Verhalten Im Strassenverkehr","o":["Nur, wenn ich den Querverkehr nicht gefährde oder nicht wesentlich behindere","Erst, wenn der Lkw-Fahrer mit Handzeichen eindeutig auf seine Vorfahrt verzichtet hat","Sofort, da der Lkw-Fahrer mich dazu auffordert"],"co":[0,1],"ex":["Auf deiner Strecke ist ein \"Vorfahrt gewähren\"-Schild. Der Querverkehr hat also Vorfahrt. Somit darfst du erst fahren, wenn die Querstraße frei ist, oder der Abstand zu möglichen anderen Fahrzeugen groß genug ist, um diese nicht zu behindern.","Der Lkw-Fahrer deutet mit Lichthupe an, dass er dir die Vorfahrt gewährt. Um ganz sicher zu gehen, darfst du allerdings erst fahren, wenn er eindeutig mit Handzeichen auf seine Vorfahrt verzichtet.","Auch wenn der Lkw-Fahrer dich per Lichthupe dazu auffordert abzubiegen, solltest du auf ein eindeutiges Handzeichen des Fahrers warten und gleichzeitig zuvor sicher gehen, das du keinem anderen Verkehrsteilnehmer die Vorfahrt nimmst."],"v":["https://video2.kalaiwa.de/assets/1211114mv1440.mp4"],"rn":267},{"n":"1.2.12-001","t":"Wo ist das Halten verboten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Unmittelbar hinter Fußgängerüberwegen","Auf Bahnübergängen","An engen und an unübersichtlichen Straßenstellen"],"co":[1,2],"ex":["Unmittelbar hinter Fußgängerüberwegen wird die Sicht auf den Fußgängerüberweg nicht beeinträchtigt. Daher darf man hier auch halten.","Ein Halten auf Bahnübergängen behindert den Schienenverkehr und ist sehr gefährlich.","Enge und unübersichtliche Straßenstellen sind potentielle Gefahrenstellen für Unfälle. Um die Unfallgefahr nicht noch mehr zu erhöhen, ist das Halten an diesen Stellen verboten."],"rn":268},{"n":"1.2.12-002","t":"Wo ist das Parken verboten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Auf Vorfahrtstraßen innerhalb geschlossener Ortschaften","Auf Vorfahrtstraßen außerhalb geschlossener Ortschaften","Am Fahrbahnrand, wenn hierdurch die Benutzung gekennzeichneter Parkflächen verhindert wird"],"co":[1,2],"ex":["Das Parken auf Vorfahrtsstraßen innerhalb geschlossener Ortschaften ist erlaubt. Hier ist die Höchstgeschwindigkeit der Fahrzeuge auf 50 km/h begrenzt. Um den begrenzten Raum in einer Ortschaft besser nutzen zu können, darf hier am Fahrbahnrand geparkt werden, sofern die Parkfläche nicht durch ein Parken verboten Schild gekennzeichnet ist.","Es ist verboten, Fahrzeuge auf Vorfahrtsstraßen außerhalb geschlossener Ortschaften zu parken (§12, Abs. 3 Satz 8a StVO). Außerhalb geschlossener Ortschaften wird meistens schneller als 50 km/h gefahren. Ein stehendes Fahrzeug auf einer Vorfahrtsstraße stellt hier ein Hindernis dar und würde die Gefahr eines Unfalls erhöhen.","Es ist nicht erlaubt, parkende Fahrzeuge so abzustellen, dass dadurch die Benutzung gekennzeichneter Parkflächen verhindert wird ( §12, Abs. 3 Satz 2 StVO)."],"rn":269},{"n":"1.2.12-103","t":"Wo ist das Halten verboten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["An Taxenständen","Auf der Fahrbahn, wenn rechts ein geeigneter Seitenstreifen vorhanden ist","Auf markierten Fahrstreifen mit Richtungspfeilen"],"co":[0,1,2],"ex":["Das Halten an Taxenständen ist aus mehreren Gründen verboten: Erstens dienen Taxenstände dazu, Taxifahrern einen zentralen Ort zur Verfügung zu stellen, an dem sie auf Fahrgäste warten können. Hier soll der vorhandene Platz unter allen Umständen freigehalten werden, damit die Fahrgäste jederzeit gefahrlos und ohne Behinderungen einsteigen können und der Fahrer nicht gezwungen ist den Verkehr durch Parken in zweiter Reihe zu behindern. Zweitens sind Taxenstände oft an gut sichtbaren Stellen in der Nähe von Verkehrsknotenpunkten platziert, um den Fahrgästen die Möglichkeit zu bieten, schnell ein Taxi zu finden. Würden andere Fahrzeuge an diesen Stellen halten, könnte der Verkehrsfluss behindert und potenziell gefährliche Situationen geschaffen werden.","Auf Fahrbahnen mit geeignetem Seitenstreifen ist das Halten verboten, weil sonst der nachfolgende Verkehr unnötig behindert wird. Nachfolgende Fahrer könnten durch das Halten auf der Fahrbahn überrascht werden und gezwungen sein, abrupt zu bremsen oder gar die Spur zu wechseln, um einen Zusammenstoß zu vermeiden. Dies kann zu einer gefährlichen Verkehrssituationen führen, bspw. wenn Gegenverkehr kommt. Seitenstreifen sind so konzipiert, dass Fahrzeuge dort sicher halten können, ohne den Verkehrsfluss auf der Fahrbahn zu beeinträchtigen. Wenn also ein Seitenstreifen vorhanden ist und ausreichend Platz bietet, muss man dort halten und keinesfalls auf der Fahrbahn selbst.","Auf Fahrstreifen, die mit Richtungspfeilen markiert sind, darf nicht gehalten werden, da sonst die rechtzeitige Aufteilung und Kanalisierung des Verkehrs nicht mehr möglich wäre. Zudem würde man die ordentliche Nutzung und bspw. das Abbiegen auf einer Rechtsabbiegespur für den nachfolgenden Verkehr unmöglich machen. Das Halten ist daher auf markierten Fahrstreifen mit Richtungspfeilen verboten. Nur so kann die Verkehrssicherheit und ein ordentlicher Verkehrsfluss gemäß der Verkehrszeichen und Markierungen aufrechterhalten werden. Im Übrigen ist auch das Parken auf so markierten Fahrstreifen verboten."],"rn":270},{"n":"1.2.12-104","t":"Wo ist das Halten verboten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Über Schachtdeckeln","Unmittelbar hinter Fußgängerüberwegen","Auf Fußgängerüberwegen sowie bis zu 5 m davor"],"co":[2],"ex":["Über Schachtdeckeln ist das Parken verboten, um einen freien Zugang zu gewährleisten. Die kurze Fahrtunterbrechung durch das Halten ist hier jedoch nicht verboten.","Hinter dem Zebrastreifen muss kein Sichtfeld freigehalten werden, darum ist hier das Halten nicht verboten.","Dadurch soll gewährleistet werden, dass zum einen der für die Überquerung der Straße vorgesehene Weg ständig freigehalten wird und zum anderen Fußgänger am Überweg für den heranfahrenden Fahrzeugführer rechtzeitig zu erkennen sind."],"rn":271},{"n":"1.2.12-105","t":"Wo ist das Parken verboten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Am Fahrbahnrand, wenn hierdurch die Benutzung gekennzeichneter Parkflächen verhindert wird","Vor Bordsteinabsenkungen","Unmittelbar hinter Fußgängerüberwegen"],"co":[0,1],"ex":["Schließlich dienen die gekennzeichneten Parkflächen der Nutzung. Zum einen werden darauf befindliche Fahrzeuge am ausparken gehindert und Fahrzeugführer, die dort Parken wollen, werden am hereinfahren gehindert.","Vor Bordsteinabsenkungen ist das Parken verboten, da diese in der Regel eine Ein- und Ausfahrt kennzeichnet.","Unmittelbar hinter Fußgängerüberwegen ist das Parken erlaubt. Vor Fußgängerüberwegen muss jedoch einen Abstand von mindestens 5 m eingehalten werden."],"rn":272},{"n":"1.2.12-106","t":"Wo dürfen Sie in Fahrtrichtung links parken?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["In Einbahnstraßen","Wo rechts das Parken verboten ist","Wo Schienen auf der rechten Seite verlegt sind"],"co":[0,2],"ex":["In Einbahnstraßen ist das Parken in Fahrtrichtung links gestattet, da hier kein Gegenverkehr zu erwarten ist, dessen Verkehrsraum so behindert würde.","Dies gibt keine Berechtigung, in Fahrtrichtung links zu parken.","Wenn auf der rechten Seite Schienen befindlich sind, ist es nicht möglich, hier zu parken. Daher darf in diesem Falle links geparkt werden."],"rn":273},{"n":"1.2.12-107","t":"Wer parkt?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Wer sein Fahrzeug verlässt","Wer länger als drei Minuten hält","Wer vor einer geschlossenen Bahnschranke länger als drei Minuten wartet"],"co":[0,1],"ex":["Dann wird davon ausgegangen, dass der Fahrzeughalter parken möchte.","Bei weniger als drei Minuten würde man vom \"Halten\" sprechen.","Der Fahrer wird durch die geschlossene Bahnschranke zum Stehenbleiben gezwungen."],"rn":274},{"n":"1.2.12-108","t":"Welcher Mindestabstand muss vor einem Fußgängerüberweg beim Halten oder Parken eingehalten werden?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"5 m","e":"Würde man direkt vor dem Fußgängerüberweg parken, könnte der fließende Verkehr nicht oder nur schwer erkennen, ob ein Fußgänger die Straße überqueren möchte, der durch das parkende Fahrzeug gegebenenfalls verdeckt wird und andersherum. Bei einem Abstand von 5 Metern können sowohl Fußgänger, als auch der fließende Verkehr den Überweg rechtzeitig einsehen.","rn":275},{"n":"1.2.12-110","t":"Wie weit muss man beim Parken außerorts vom Andreaskreuz mindestens entfernt bleiben?","p":2,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"50 m","e":"An einem mit Andreaskreuz beschilderten Bahnübergang hat das Schienenfahrzeug Vorrang. Aus diesem Grund darf die Sicht auf den Bahnübergang nicht durch parkende Fahrzeuge behindert sein. Ebenso ist für den Fall, dass die Schranken geschlossen sind, ausreichend Raum für den Rückstau der wartenden Fahrzeuge nötig. Dies kann nur gewährleistet werden, wenn sich im Bereich vor dem Bahnübergang keine parkenden Fahrzeuge befinden.","rn":276},{"n":"1.2.12-111","t":"Sie wollen innerorts vor einem Andreaskreuz parken. Welche Entfernung müssen Sie mindestens einhalten?","p":2,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"5 m","e":"Schienenfahrzeuge haben an einem mit Andreaskreuz beschilderten Bahnübergang Vorrang. Um die Sicht auf den Bahnübergang und die Bahnstrecke nicht durch parkende Fahrzeuge zu verdecken, darf hier nicht geparkt werden. Außerorts beträgt dieser Abstand 50 Meter.","rn":277},{"n":"1.2.12-112","t":"Wie weit vor und hinter einem Haltestellenschild dürfen Sie nicht parken?","p":2,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"Antwort: Jeweils 15 m","e":"Dem Linienbus soll es möglich sein, bis an den Fahrbahnrand heranfahren zu können, damit die Fahrgäste ohne unnötige Behinderungen ein- und aussteigen können. Aufgrund seiner Fahrzeuggröße ist für das ein- und ausscheren und generelle Halten viel Platz nötig.","rn":278},{"n":"1.2.12-113","t":"An Haltestellen darf nur gehalten werden, wenn Busse nicht behindert werden. Wie lange dürfen Sie dort höchstens halten?","p":2,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"3 Minuten","e":"Ein Haltvorgang liegt vor, wenn Ihr Fahrzeug höchstens 3 Minuten unbewegt bleibt. Das Halten (bis 3 Minuten) an Bushaltestellen ist erlaubt, das Parken (länger als 3 Minuten) verboten.","rn":279},{"n":"1.2.12-122","t":"Wann dürfen Sie nicht auf dem rechten Fahrstreifen parken?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Wenn rechts von dem Fahrstreifen ein geeigneter Parkstreifen vorhanden ist","Wenn auf dem Fahrstreifen Schienen verlegt sind","Wenn rechts von dem Fahrstreifen ein ausreichend befestigter Seitenstreifen vorhanden ist"],"co":[0,1,2],"ex":["Dann musst du auf dem Parkstreifen parken.","Du darfst hier nicht parken, weil du sonst den Schienenverkehr behindern würdest.","Dann musst du auf dem Seitenstreifen parken."],"rn":280},{"n":"1.2.12-124","t":"Welche Fahrzeuge dürfen auf Fahrbahnen in zweiter Reihe halten?","p":2,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Alle Taxis, wenn Fahrgäste ein- oder aussteigen","Alle Fahrzeuge, wenn das Warnblinklicht eingeschaltet ist","Alle Fahrzeuge, wenn sie be- oder entladen werden"],"co":[0],"ex":["Taxis dürfen zum Ein- und Aussteigen von Fahrgästen kurz in zweiter Reihe auf Fahrbahnen halten.","Trotz eingeschaltetem Warnblinklicht darf nicht in zweiter Reihe gehalten werden.","Zum Be- oder Entladen darf nicht in zweiter Reihe gehalten werden."],"rn":281},{"n":"1.2.12-125","t":"Wo ist das Halten verboten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Auf markierten Fahrstreifen mit Richtungspfeilen","Auf Einfädelungs- und Ausfädelungsstreifen","Vor Ein- und Ausfahrten von Grundstücken"],"co":[0,1],"ex":["Auf markierten Fahrstreifen mit Richtungspfeilen ist das Halten verboten.","Beschleunigungs- und Verzögerungsstreifen sind dazu da, das Ein- und Ausfahren bei Autobahnen ohne Behinderungen zu ermöglichen. Das Halten ist hier verboten.","Das Halten ist bei Ein- und Ausfahrten von Grundstücken erlaubt, das Parken allerdings nicht."],"rn":282},{"n":"1.2.12-131","t":"Sie suchen nach einer Parkmöglichkeit am rechten Fahrbahnrand. Rechts neben Ihrer Fahrbahn befindet sich kein Radweg. Wie viel Meter vor und hinter einer Kreuzung dürfen Sie nicht parken?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"5 m","e":"Um die Sicht nicht einzuschränken, darfst du 5 Meter vor und hinter einer Kreuzung nicht parken.","rn":283},{"n":"1.2.12-132","t":"Wo ist das Halten verboten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["In allen Einbahnstraßen","In Parkverbotszonen","Vor Feuerwehrzufahrten"],"co":[2],"ex":["Das Halten in Einbahnstraßen ist nicht grundsätzlich verboten.","Das Halten in Parkverbotszonen ist grundsätzlich erlaubt.","Rettungswege und Feuerwehrzufahrten müssen immer freigehalten werden."],"rn":284},{"n":"1.2.12-133","t":"Sie suchen nach einer Parkmöglichkeit am rechten Fahrbahnrand. Rechts neben der Fahrbahn befindet sich ein Radweg. Wie viel Meter vor einer Kreuzung oder vor einer Einmündung dürfen Sie nicht parken?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"8 m","e":"Wenn sich rechts neben der Fahrbahn ein Radweg befindet, dann musst du beim Parken einen Mindestabstand von 8 Metern zu einer Kreuzung oder Einmündung einhalten.","rn":285},{"n":"1.2.12-121-M","t":"Wer parkt falsch?","p":2,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Keiner der beiden Pkws","Der weiße Pkw","Der dunkle Pkw"],"co":[1],"ex":["Der weiße PKW parkt falsch, der schwarze PKW parkt richtig.","Der weiße PKW steht auf der Zick-Zack-Linie und somit im Halt- und Parkverbot.","Der schwarze PKW steht außerhalb des Halt- und Parkverbots und parkt somit richtig."],"i":["https://video4.kalaiwa.de/assets/1212121m.webp"],"rn":286},{"n":"1.2.12-123-M","t":"Was ist hier zu beachten?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Links von der Fahrbahnbegrenzung darf nicht gehalten werden","Langsame Fahrzeuge müssen möglichst auf dem Seitenstreifen fahren","Die Fahrbahnbegrenzung darf in keinem Fall überfahren werden"],"co":[0,1],"ex":["Links von der Fahrbahnbegrenzung darfst du nicht halten, weil dies der Fahrstreifen ist. Auf dem Seitenstreifen darfst du hier aber halten.","Um andere Fahrzeuge möglichst nicht zu behindern, müssen langsam fahrende Fahrzeuge den Seitenstreifen befahren.","Die Fahrbahnbegrenzung darf für langsam fahrende Fahrzeuge überfahren werden, die auf den Seitenstreifen wechseln, um anderen Verkehrsteilnehmern das Weiterfahren zu erleichtern."],"i":["https://video2.kalaiwa.de/assets/1212123m.webp"],"rn":287},{"n":"1.2.12-126-M","t":"Wer hält falsch?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Der gelbe Pkw","Beide Pkws","Der rote Pkw"],"co":[2],"ex":["Unmittelbar nach Fußgängerüberwegen darf geparkt werden.","Nur der rote PKW hält falsch, der gelbe darf so parken.","Beim Parken vor Fußgängerüberwegen müssen mindestens 5 Meter Abstand eingehalten werden, damit die Fußgänger rechtzeitig vom fließenden Verkehr gesehen werden können."],"i":["https://video4.kalaiwa.de/assets/1212126m.webp"],"rn":288},{"n":"1.2.12-128-M","t":"Wo dürfen Sie hier parken?","p":3,"c":"1.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["- nur auf dem rechten Seitenstreifen","- nur auf dem linken Seitenstreifen","- auf dem linken und rechten Seitenstreifen"],"co":[2],"ex":["Du darfst auch auf dem linken Seitenstreifen parken.","Du darfst auch auf dem rechten Seitenstreifen parken.","Auf beiden Seiten sind markierte Parkstreifen, die dir das Parken erlauben."],"i":["https://video2.kalaiwa.de/assets/1212128m.webp"],"rn":289},{"n":"1.2.16-002","t":"Wie sollten Sie sich verhalten, wenn Sie ein Fahrzeug mit Warnblinklicht erkennen?","p":4,"c":"1.2.16","ch":"Warnzeichen","th":"Verhalten Im Strassenverkehr","o":["Ich stelle mich auf plötzlich auftretende Gefahren ein","Ich fahre unvermindert weiter","Ich reduziere meine Geschwindigkeit"],"co":[0,2],"ex":["Mit dem Warnblinklicht warnt ein Fahrer vor eventueller Gefahr wie Stau oder besonders langsamer Fahrgeschwindigkeit auf Autobahnen.","Gibt ein Fahrer mit seinem Fahrzeug ein Warnzeichen, nimmst du Rücksicht und bist besonders vorsichtig. Unvermindert weiterfahren ist keine gute Idee.","Der Fahrer könnte Hilfe brauchen oder auf eine Gefahr hinweisen. Es könnten sich zum Beispiel Fußgänger auf der Straße befinden. Also: Langsam heranfahren."],"rn":290},{"n":"1.2.16-101","t":"Zu welchem Zweck darf die Hupe außerorts benutzt werden?","p":2,"c":"1.2.16","ch":"Warnzeichen","th":"Verhalten Im Strassenverkehr","o":["Als Warnsignal","Als Überholsignal","Als Rufzeichen"],"co":[0,1],"ex":["Wenn es notwendig ist, darf die Hupe überall als Warnsignal genutzt werden.","Allerdings gilt dies nur außerorts, da innerhalb geschlossener Ortschaften hierdurch eine Lärmbelästigung für Anwohner und Passanten entstehen würde.","Die Hupe ist ausschließlich als Warnsignal gedacht."],"rn":291},{"n":"1.2.16-102","t":"Zu welchem Zweck darf die Hupe innerorts benutzt werden?","p":2,"c":"1.2.16","ch":"Warnzeichen","th":"Verhalten Im Strassenverkehr","o":["Als Warnsignal","Als Rufzeichen","Als Überholsignal"],"co":[0],"ex":["Mit der Hupe darf (und muss) auf eine Gefahrensituation hingewiesen werden, um andere Verkehrsteilnehmer zu warnen. Aus diesem Grund ist es auch wichtig, das Radio nicht zu laut zu stellen, da du sonst Warnzeichen Anderer sehr schnell überhören kannst.","Die Hupe ist ein Warnsignal und darf nicht als Rufzeichen angewendet werden.","Die Hupe darf nur außerorts als Überholsignal verwendet werden."],"rn":292},{"n":"1.2.16-103","t":"Wie verhalten Sie sich bei einer Panne in einem Tunnel?","p":4,"c":"1.2.16","ch":"Warnzeichen","th":"Verhalten Im Strassenverkehr","o":["Fahrzeug möglichst in einer Pannenbucht abstellen","Warnblinklicht einschalten","Motor vorsorglich laufen lassen"],"co":[0,1],"ex":["Das ist sicherer für dich und behindert du den übrigen Verkehr nicht.","In einer Pannensituation muss immer zuerst das Warnblinklicht eingeschaltet werden. Vor allem im Tunnel ist das sehr wichtig, da es hier dunkler und unübersichtlicher ist, als im Freien.","Der Motor sollte bei einer Panne schnellstmöglich abgestellt werden."],"rn":293},{"n":"1.2.16-104","t":"Beim Befahren eines Tunnels nähern Sie sich einem Stauende. Wie verhalten Sie sich?","p":4,"c":"1.2.16","ch":"Warnzeichen","th":"Verhalten Im Strassenverkehr","o":["Wenden und den Tunnel verlassen","Am Stauende Motor abstellen und das Fahrzeug verlassen","Warnblinklicht einschalten"],"co":[2],"ex":["Wenden ist im Tunnel untersagt. Das würde zudem nur für Unruhe unter den anderen Verkehrsteilnehmern sorgen.","Den Motor abstellen und das Fahrzeug verlassen sind Verhaltensregeln, die nur im Notfall anzuwenden sind.","So kann der nachfolgende Verkehr frühstmöglich gewarnt werden."],"rn":294},{"n":"1.2.17-001","t":"Worauf müssen Sie bei den Beleuchtungseinrichtungen Ihres Fahrzeugs achten?","p":3,"c":"1.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Sie müssen sauber sein","Sie müssen funktionstüchtig sein","Sie müssen vorschriftsmäßig angebracht sein"],"co":[0,1,2],"ex":["Verschmutze Beleuchtung schränkt die eigene Sicht auf die Fahrbahn und den Verkehr ein und behindert ebenfalls andere Verkehrsteilnehmer in der Wahrnehmung des Fahrzeugs. Auch kann das Blinken so gegebenenfalls nicht ausreichend erkannt werden.","Damit Beleuchtung ihren Zweck erfüllt, muss sie funktionieren. Sie ist notwendig, um im Dunkeln genügend Sicht zu haben und von anderen Verkehrsteilnehmern ausreichend wahrgenommen zu werden.","Es muss gewährleistet sein, dass Beleuchtungseinrichtungen korrekt angebracht und gut befestigt sind."],"rn":295},{"n":"1.2.17-102","t":"Wie kann verhindert werden, dass der Gegenverkehr mit dem Abblendlicht geblendet wird?","p":3,"c":"1.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Es dürfen nur für den jeweiligen Scheinwerfer zulässige Leuchtmittel verwendet werden","Die Leuchtweite ist in Abhängigkeit vom Beladungszustand des Fahrzeugs zu regulieren","Nach jeder Reparatur am Scheinwerfer sollte eine Überprüfung der Einstellung erfolgen"],"co":[0,1,2],"ex":["Das zugelassene Leuchtmittel steht im Handbuch des Fahrzeugs.","Es kann sein, dass das Abblendlicht deines Fahrzeugs aufgrund der Beladung den Gegenverkehr blendet. Das kannst du mit der Leuchtweitenregulierung einstellen.","Wenn ein Teil des Fahrzeugs repariert wurde, solltest du nach der Reparatur die Einstellungen davon prüfen."],"rn":296},{"n":"1.2.19-002","t":"Wann müssen Sie vor einem Bahnübergang warten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Wenn rotes Blinklicht aufleuchtet","Wenn sich die Schranken senken","Wenn ein Bahnbediensteter eine weiß-rot-weiße Fahne schwenkt"],"co":[0,1,2],"ex":["Wird die Wartepflicht trotz rotem Blinklicht oder gelbem bzw. rotem Lichtzeichen nicht eingehalten, dann kann eine Gefahrensituation entstehen.","Dies signalisiert, dass in Kürze ein Schienenfahrzeug die Strecke passiert.","Dies ist eine Warn- bzw. Signalflagge und zeigt den Verkehrsbeteiligten, dass sie anhalten bzw. warten müssen."],"rn":297},{"n":"1.2.19-004","t":"Ein Bahnbediensteter schwenkt an einem Bahnübergang eine rote Leuchte. Was bedeutet dies?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Sie dürfen die Gleise vorsichtig überqueren","Sie müssen vor dem Bahnübergang warten","Die rote Leuchte hat für Sie keine Bedeutung"],"co":[1],"ex":["Das signalisiert die rote Leute nicht. Man soll anhalten, bzw. warten.","Schwenkt ein Bahnbediensteter eine rote Leuchte, so muss in jedem Fall gewartet werden.","Die rote Leuchte signalisiert dem Verkehrsteilnehmer: \"Halt!\"."],"rn":298},{"n":"1.2.19-008","t":"An der Einfahrt in ein Industriegebiet steht das Andreaskreuz mit dem Zusatzzeichen „Industriegebiet, Schienenfahrzeuge haben Vorrang“. Was haben Sie zu beachten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["An Bahnübergänge nur mit mäßiger Geschwindigkeit heranfahren","Schienenfahrzeuge haben an allen Bahnübergängen Vorrang","Kraftfahrzeuge haben an Bahnübergängen ohne Andreaskreuz Vorrang"],"co":[0,1],"ex":["Die Schienenfahrzeuge haben Vorrang und daher musst du gegebenenfalls abbremsen, falls ein solches die Schienen vor dir passiert.","Unabhängig davon, ob eine Schienenkreuzung in einem Industriegebiet oder an einem anderen Ort passiert werden muss, Schienenfahrzeuge haben immer Vorrang vor anderen Verkehrsteilnehmern.","An Bahnübergängen haben Schienenfahrzeuge immer Vorrang."],"rn":299},{"n":"1.2.19-009","t":"Die Position der Bahnschranken ändert sich seit längerer Zeit nicht. Wie verhalten Sie sich richtig?","p":4,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Ich überquere den Bahnübergang nicht","Ich überquere den Bahnübergang mit besonderer Vorsicht","Ich melde die Störung der Polizei"],"co":[0,2],"ex":["Offenbar gibt es eine Störung an der Bahnschranke. Daher ist es nicht sicher, den Bahnübergang zu nutzen. Überquere auf keinen Fall den Bahnübergang.","Überquere auf keinen Fall den Bahnübergang. Falls sich ein Zug nähert, besteht akute Lebensgefahr. Außerdem besteht die Gefahr, dass du nicht unter den Schranken durchkommst und stecken bleibst.","Informiere die Polizei über die Störung an der Bahnschranke, damit das Problem behoben werden kann."],"i":["https://video2.kalaiwa.de/assets/1219009.webp"],"rn":300},{"n":"1.2.19-101","t":"Sie fahren auf einem Waldweg und nähern sich einem Bahnübergang ohne Andreaskreuz. Wie verhalten Sie sich?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Horchen, ob sich durch Pfeifen oder Läuten ein Schienenfahrzeug ankündigt","Ohne weiteres durchfahren, da Schienenfahrzeuge hier wartepflichtig sind","Mit mäßiger Geschwindigkeit heranfahren und beobachten, ob sich ein Schienenfahrzeug nähert"],"co":[0,2],"ex":["Da durch die Bäume die Sicht auf die Bahnstrecke eingeschränkt ist, sollte man einen zusätzlichen Aufmerksamkeitsfokus auf akustische Signale legen. Lokführer geben Läute-, Hup- oder Pfeifzeichen, wenn sie sich mit dem Schienenfahrzeug einem Bahnübergang nähern. Das gleiche gilt auch bei Dunkelheit, Schneefall oder starkem Regen.","Schienenfahrzeuge haben Vorfahrt vor Kraftfahrzeugen, auch in bewaldeten Regionen.","Die StVO § 19 Abs. 1 schreibt vor: \"Schienenfahrzeuge haben Vorrang (...) auf Bahnübergängen über Fuß-, Feld-, Wald- oder Radwege (...). Der Straßenverkehr darf sich solchen Bahnübergängen nur mit mäßiger Geschwindigkeit nähern.\" So kann ein sicheres Passieren der Schienen gewährleistet werden und im Bedarfsfall ist genug Zeit, um Abzubremsen, falls sich ein Schienenfahrzeug nähert."],"rn":301},{"n":"1.2.19-102","t":"Wie verhalten Sie sich an einem Bahnübergang, dessen Schranken geschlossen sind?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Verkehrsraum ausnutzen, dicht vor der Schranke warten","Vor dem Andreaskreuz warten, Straßeneinmündungen freilassen","Bei Dunkelheit möglichst auf Standlicht schalten"],"co":[1,2],"ex":["Um eventuellen Querverkehr nicht unnötig zu behindern, sollten Sie Einmündungen freihalten und nicht bis zur Schranke vorfahren.","Der Querverkehr würde unnötig behindert werden, wenn Einmündungen vor dem Bahnübergang nicht freigehalten würden.","Beim Warten vor dem geschlossenen Bahnübergang dürfen Ihre Scheinwerfer niemand blenden. Aus diesem Grund ist es sinnvoll, auf Standlicht herunterzuschalten. Auch um bei stehendem Motor die Fahrzeugbatterie zu entlasten."],"rn":302},{"n":"1.2.19-104","t":"Wann dürfen Sie einen unbeschrankten Bahnübergang mit Blinklichtanlage überqueren, nachdem ein Zug durchgefahren ist?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Wenn das rote Blinklicht erloschen ist","Sofort nach Durchfahrt des Zuges, auch wenn das rote Blinklicht noch leuchtet","Sobald der Gegenverkehr anfährt, auch wenn das rote Blinklicht noch leuchtet"],"co":[0],"ex":["Dies ist das Signal, dass auf ungefährdetes Überqueren des Bahnübergangs hinweist.","Erst wenn dieser Erloschen ist, darf der Übergang passiert werden.","Der Gegenverkehr ist kein Garant für korrektes Verhalten im Straßenverkehr. Fährt dieser zu früh los, setzt er sich einem Risiko aus, das durch angemessenes Warten zu vermeiden ist."],"rn":303},{"n":"1.2.19-105","t":"Sie nähern sich einem beschrankten Bahnübergang. Wo müssen Sie warten, wenn Sie bei stockendem Verkehr auf dem Bahnübergang zum Stehen kommen würden?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Vor dem Andreaskreuz","In Höhe der Schranke","Unmittelbar vor den Schienen"],"co":[0],"ex":["Bei stockendem Verkehr ist nicht gewährleistet, dass das Überqueren des Bahnübergangs fließend möglich ist. Um so nicht Gefahr zu laufen, aufgrund des stockenden Verkehrs auf den Schienen halten zu müssen, ist vor dem Andreaskreuz zu warten, bis die Schienen ungehindert passiert werden können.","Falls sich die Schranke senkt, könnte das Fahrzeug beschädigt werden. Ein ausreichender Sicherheitsabstand zum herannahenden Schienenfahrzeug ist nur auf Höhe des Andreaskreuzes gegeben.","Es muss so gehalten werden, dass man das Leuchtsignal am Andreaskreuz noch sehen kann und die Schranken noch herunter gehen können. Daher muss man bereits ein großes Stück vor den Schienen zum Stehen kommen."],"rn":304},{"n":"1.2.19-107","t":"An einem Bahnübergang - innerorts - ist die Schranke geschlossen. Wo müssen Sie warten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Vor der letzten Bake","Vor der ersten Bake","Vor dem Andreaskreuz"],"co":[2],"ex":["Die letzte Bake befindet sich noch vor dem Andreaskreuz. Du darfst aber bis zum Andreaskreuz vor fahren und musst erst dort warten.","Die erste Bake signalisiert dem Autofahrer, dass in 240 m das Andreaskreuz kommt.","Unabhängig davon, ob sich der Bahnübergang außerorts oder innerorts befindet - gibt es eine Schranke und ein Andreaskreuz, so ist vor dem Andreaskreuz zu warten."],"rn":305},{"n":"1.2.19-109","t":"Was bedeutet dieses Verkehrszeichen?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Es ist immer zu warten, wenn sich ein Schienenfahrzeug nähert","Der Schienenverkehr hat immer Vorrang","Hinweis auf vorhandene elektrische Oberleitungen"],"co":[0,1,2],"ex":["Das Andreaskreuz deutet auf einen Bahnübergang hin. Zügen ist immer Vorrang zu gewähren.","Zügen ist immer Vorrang zu gewähren.","Der in der Mitte des Andreaskreuzes angebrachte Blitz weist auf eine elektrische Oberleitung oberhalb der Bahnschienen hin. Dieser Hinweis ist vor allem für die Fahrer von land- oder forstwirtschaftlichen Fahrzeugen von großer Bedeutung, da sie häufig besonders hoch beladen sind."],"i":["https://video2.kalaiwa.de/assets/1219109.webp"],"rn":306},{"n":"1.2.19-110","t":"Vor einem Bahnübergang steht vor einer von rechts einmündenden Straße ein rot leuchtendes Lichtzeichen ohne Andreaskreuz. Wo müssen Sie warten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["An der Haltlinie","Wenn keine Haltlinie vorhanden ist, vor dem Lichtzeichen","Ich kann nach Beobachten des Verkehrs bis zum Bahnübergang vorfahren"],"co":[0,1],"ex":["In der StVO § 41 Abs. 3 Zeichen 294 (2 Haltlinie) heißt es: \"Ergänzend zu Halt- und Wartegeboten, die durch Zeichen 206 (Stoppschild), durch Polizeibeamte oder durch Lichtzeichen (in diesem Fall die rote Ampel) gegeben werden, ordnet sie an: \"Hier Halten!\" Dasselbe gilt vor Bahnübergängen für den, der warten muss.\" Daher muss an der Haltlinie vor dem rot leuchtenden Lichtzeichen gewartet werden, bis dieses umschaltet.","Es ist verboten, ein rot leuchtendes Lichtzeichen zu überfahren.","Dies würde von rechts kommende Fahrzeuge behindern und somit zu stockendem Verkehr führen. Zudem ist es verboten, ein rot leuchtendes Lichtzeichen zu überfahren."],"i":["https://video4.kalaiwa.de/assets/1219110.webp"],"rn":307},{"n":"1.2.19-111","t":"Wie müssen Sie sich in dieser Situation verhalten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["- vor dem Andreaskreuz halten","- rechts am Sicherungsposten vorbeifahren","- links am Sicherungsposten vorbeifahren"],"co":[0],"ex":["Die weiß-rot-weiße Signal- bzw. Warnflagge signalisiert Verkehrsteilnehmern zu warten. Der Bahnübergang darf nicht überquert werden.","Der Sicherungsposten signalisiert mit der weiß-rot-weißen Flagge, dass angehalten werden muss. Es könnte sich ein Schienenfahrzeug nähern.","Wenn Bahnbedienstete mit einer Signal- bzw. Warnflagge vor einem Bahnübergang stehen, muss angehalten werden."],"i":["https://video4.kalaiwa.de/assets/1219111.webp"],"rn":308},{"n":"1.2.19-112","t":"Wer muss an einem Andreaskreuz mit rotem Blinklicht in Form eines Pfeiles nach rechts warten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Geradeausfahrer","Rechtsabbieger","Linksabbieger"],"co":[1],"ex":["Geradeausfahrer betrifft das Blinklicht nicht.","An einem Andreaskreuz mit rot blinkendem Rechtspfeil müssen Personen warten, die nach rechts abbiegen wollen.","Das rote Blinklicht zeigt einen Pfeil nach rechts und bezieht sich somit auf Rechtsabbieger und nicht auf Linksabbieger."],"rn":309},{"n":"1.2.19-113","t":"Worauf weist diese Verkehrszeichenkombination hin?","p":4,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["- den ich mit maximal 10 km/h überqueren darf","- den Schienenfahrzeuge nur mit 10 km/h befahren dürfen","- an den ich ab hier mit maximal 10 km/h heranfahren darf"],"co":[0,2],"ex":["Das Verkehrszeichen bezieht sich auf die Geschwindigkeit, mit der du den Bahnübergang überqueren musst.","Das Verkehrszeichen bezieht sich nicht auf den Schienenverkehr.","Du darfst ab hier nicht schneller als mit 10 km/h an den Bahnübergang heranfahren."],"i":["https://video2.kalaiwa.de/assets/1219113.webp"],"rn":310},{"n":"1.2.19-114","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Ich warte an den Schienen","Ich warte vor dem Andreaskreuz","Ich überquere vorsichtig die Schienen"],"co":[1],"ex":["Dann würdest du eine Behinderung für den Schienenverkehr darstellen. Warte vor dem Andreaskreuz.","Weil sich vor dir der Verkehr staut und du sonst auf den Schienen zum Halten kommen würdest, musst du vor dem Andreaskreuz warten.","So würdest du riskieren, auf den Schienen zum Stehen zu kommen. Warte vor dem Andreaskreuz."],"v":["https://video2.kalaiwa.de/assets/1219114v1440.mp4"],"rn":311},{"n":"1.2.19-115","t":"Sie nähern sich einem Bahnübergang. Die Schranke beginnt sich zu senken. Wie müssen Sie sich verhalten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Ich schalte das Warnblinklicht ein","Ich fahre weiter, wenn kein Zug zu sehen ist","Ich warte vor dem Andreaskreuz"],"co":[2],"ex":["Das Warnblinklicht dient dazu, andere Verkehrsteilnehmer vor einer möglichen Gefahrensituation zu warnen. Dies ist hier nicht der Fall.","Dass sich die Schranke senkt, bedeutet, dass sich ein Schienenfahrzeug nähert. Warte also vor dem Andreaskreuz.","Das ist die korrekte Verhaltensweise."],"rn":312},{"n":"1.2.19-116","t":"Wo müssen Sie mit technisch ungesicherten Bahnübergängen rechnen?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Auf wenig befahrenen Straßen","In Industrie- und Hafengebieten","Auf Feld- und Waldwegen"],"co":[0,1,2],"ex":["Wenig befahrene Straßen können nicht mit technisch gesicherten Bahnübergängen ausgestattet werden.","In Industrie- und Hafengebieten wird auf eine technische Sicherung von Übergängen verzichtet.","Bahnübergänge auf Feld- und Waldwegen können nicht technisch gesichert werden."],"rn":313},{"n":"1.2.19-117","t":"Sie möchten einen Bahnübergang mit geöffneten Schranken überqueren. Was ist richtig?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["Ich muss mit mäßiger Geschwindigkeit an den Bahnübergang heranfahren","Ich darf die Schienen nur mit Schrittgeschwindigkeit überqueren","Ich rechne beim Überqueren des Bahnübergangs mit Bodenwellen"],"co":[0,2],"ex":["Du solltest den Bahnübergang nur mit gemäßigter Geschwindigkeit überqueren. So kannst du rechtzeitig reagieren, falls doch ein Zug kommen sollte.","Damit du den Bahnübergang zügig überqueren kannst, darfst du auch schneller als Schrittgeschwindigkeit fahren. So verhinderst du mögliche Gefahrensituationen mit kommenden Zügen oder sich senkenden Schranken.","Beim Überqueren des Bahnübergangs solltest du mit Bodenwellen rechnen, da die gleichmäßige Asphaltfläche durch die Zuggleise unterbrochen wird. Zudem haben Zuggleise häufig eine andere Neigung als die Fahrbahn, was ebenfalls zu Bodenwellen führen kann. Um Gefahrensituationen beim Passieren des Bahnübergangs zu vermeiden, solltest du deine Geschwindigkeit anpassen."],"rn":314},{"n":"1.2.19-118-M","t":"Wie müssen Sie sich jetzt verhalten?","p":3,"c":"1.2.19","ch":"Bahnuebergaenge","th":"Verhalten Im Strassenverkehr","o":["- den Bahnübergang zügig überqueren","- vor dem Andreaskreuz anhalten","- bei geöffneter Schranke weiterfahren"],"co":[1],"ex":["Du darfst den Bahnübergang nicht überqueren, da die Blinklichter über den rot-weißen Andreaskreuzen leuchten.","Du musst vor dem rot-weißen Andreaskreuz anhalten, da die Lichter über den Kreuzen sichtbar blinken.","Die Lichter über den rot-weißen Andreaskreuzen leuchten. Obwohl die Schranken geöffnet sind, darfst du nicht einfach weiterfahren."],"v":["https://video2.kalaiwa.de/assets/1219118mv1440.mp4"],"rn":315},{"n":"1.2.20-004","t":"Welchen Fahrzeugen müssen Sie das Abfahren von gekennzeichneten Haltestellen ermöglichen?","p":3,"c":"1.2.20","ch":"Oeffentliche Verkehrsmittel Und Schulbusse","th":"Verhalten Im Strassenverkehr","o":["Schulbussen","Taxen","Linienbussen"],"co":[0,2],"ex":["Ein Schulbus hat beim Abfahren von einer gekennzeichneten Haltestelle Vorrang vor dem fließenden Verkehr.","Taxen haben keine vorgegebenen Ankunftszeiten, daher haben sie auch keinen Vorrang vor dem fließenden Verkehr.","Ein Linienbus hat beim Abfahren von einer gekennzeichneten Haltestelle Vorrang vor dem fließenden Verkehr, da durch einen Fahrplan vorgegebene Zeiten eingehalten werden müssen. Dies wäre bei ständigen Verzögerungen durch Wartezeiten nicht mehr möglich."],"rn":316},{"n":"1.2.20-103","t":"Sie möchten an einem Linienbus vorbeifahren, der an einer Haltestelle angehalten hat. Was müssen Sie beachten?","p":4,"c":"1.2.20","ch":"Oeffentliche Verkehrsmittel Und Schulbusse","th":"Verhalten Im Strassenverkehr","o":["- mit ausreichendem Seitenabstand vorbeifahren","- vorsichtig vorbeifahren","- den Gegenverkehr beachten"],"co":[0,1,2],"ex":["Das darfst du aber nur tun, wenn gewährleistet ist, dass du damit keine ein- und aussteigenden Fahrgäste behinderst oder sogar gefährdest. Deswegen musst du hier sehr aufmerksam, vorsichtig, mit Schrittgeschwindigkeit und ausreichendem Seitenabstand vorbeifahren.","Du musst sehr vorsichtig vorbeifahren, weil ein- und aussteigende Fahrgäste die Fahrbahn überqueren könnten.","Du darfst nur nach links ausscheren, wenn du den Gegenverkehr dadurch nicht behinderst."],"rn":317},{"n":"1.2.20-107-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":3,"c":"1.2.20","ch":"Oeffentliche Verkehrsmittel Und Schulbusse","th":"Verhalten Im Strassenverkehr","o":["Ich überhole die Straßenbahn links","Ich bleibe hinter der Straßenbahn","Ich fahre rechts an der Straßenbahn vorbei"],"co":[1],"ex":["Zum einen kommt Gegenverkehr, zum anderen verdeckt die Straßenbahn die Sicht auf die andere Straßenseite. Ein Überholen links wäre hier sehr fahrlässig und gefährlich für alle Verkehrsteilnehmer.","Die Straßenbahn hält und Fahrgäste werden ein- und aussteigen. Um diese nicht zu gefährden, bleibe dahinter.","Du musst warten, weil Personen die Fahrbahn überqueren, um in die Straßenbahn einzusteigen."],"v":["https://video4.kalaiwa.de/assets/1220107mv1440.mp4"],"rn":318},{"n":"1.2.20-108-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"1.2.20","ch":"Oeffentliche Verkehrsmittel Und Schulbusse","th":"Verhalten Im Strassenverkehr","o":["Ich bremse jetzt auf Schrittgeschwindigkeit ab","Ich fahre mit erhöhter Aufmerksamkeit","Ich behalte meine Geschwindigkeit bei"],"co":[1,2],"ex":["Das Abbremsen auf Schrittgeschwindigkeit würde den Verkehrsfluss stark behindern und ist in dieser Situation nicht angebracht. Fahren in Schrittgeschwindigkeit ist auch für den Gegenverkehr nur dann erforderlich, wenn der Bus beim Stehen das Warnblinklicht an hat.","Du solltest mit erhöhter Aufmerksamkeit fahren, da durch den haltenden Bus die Wahrscheinlichkeit steigt, dass jederzeit ein- oder aussteigende Fahrgäste die Straße überqueren wollen.","Du kannst mit gleichbleibender Geschwindigkeit am Bus vorbeifahren, da der Bus ohne eingeschaltetes Warnblinklicht hält."],"i":["https://video4.kalaiwa.de/assets/1220108m.webp"],"rn":319},{"n":"1.2.20-109-M","t":"Was müssen Sie in dieser Situation beachten?","p":5,"c":"1.2.20","ch":"Oeffentliche Verkehrsmittel Und Schulbusse","th":"Verhalten Im Strassenverkehr","o":["Personen könnten die Fahrbahn überqueren","Ich darf mit Schrittgeschwindigkeit am Bus vorbeifahren","Ich darf nicht am Bus vorbeifahren"],"co":[0,1],"ex":["An der Bushaltestelle könnten aussteigende Personen die Fahrbahn überqueren. Außerdem könnte jemand über die Straße rennen, um den Bus noch zu erreichen. Werde langsamer und halte gegebenenfalls an.","Wenn der Bus an der Haltestelle steht und den Warnblinker an hat, darfst du nur in Schrittgeschwindigkeit daran vorbeifahren. Halte an, falls Personen die Fahrbahn überqueren.","Du darfst mit Schrittgeschwindigkeit am Bus vorbeifahren. Sei bereit, gegebenenfalls zu halten."],"v":["https://video4.kalaiwa.de/assets/1220109mv1440.mp4"],"rn":320},{"n":"1.2.20-110-M","t":"Was ist in dieser Situation richtig?","p":4,"c":"1.2.20","ch":"Oeffentliche Verkehrsmittel Und Schulbusse","th":"Verhalten Im Strassenverkehr","o":["Ich darf höchstens mit Schrittgeschwindigkeit an dem Bus vorbeifahren","Ich darf mit unveränderter Geschwindigkeit weiterfahren","Der blaue Pkw muss anhalten"],"co":[0],"ex":["Du darfst am Bus mit Schrittgeschwindigkeit vorbeifahren, da er an der Bushaltestelle steht und sein Warnblinklicht angeschaltet hat.","Du darfst nicht mit unveränderter Geschwindigkeit am stehenden Bus vorbeifahren, da du sonst auf mögliche Gefahrensituationen nicht rechtzeitig reagieren kannst. Das gilt auch dann, wenn du eine Fahrbahn vom Bus entfernt bist.","Der blaue Pkw muss nicht anhalten, sondern darf mit Schrittgeschwindigkeit am stehenden Bus vorbeifahren."],"v":["https://video4.kalaiwa.de/assets/1220110mv1440.mp4"],"rn":321},{"n":"1.2.20-111-M","t":"Was müssen Sie in dieser Situation beachten?","p":5,"c":"1.2.20","ch":"Oeffentliche Verkehrsmittel Und Schulbusse","th":"Verhalten Im Strassenverkehr","o":["Ich darf nur mit Schrittgeschwindigkeit am stehenden Bus vorbeifahren","Personen könnten die Fahrbahn überqueren","Ich darf nicht am stehenden Bus vorbeifahren"],"co":[0,1],"ex":["Am stehenden Bus darfst du nur mit Schritttempo vorbeifahren, da dieser das Warnblinklicht eingeschaltet hat und dadurch auf mögliche Gefahrensituationen hinweist. So kannst du auf Fußgänger reagieren, die eventuell noch den Bus erreichen wollen und plötzlich die Straße überqueren.","Du musst abbremsen, da Personen die Fahrbahn überqueren könnten.","Du darfst vorsichtig mit Schrittgeschwindigkeit am stehenden Bus vorbeifahren, falls die Gegenfahrbahn frei ist und du niemanden gefährdest."],"v":["https://video2.kalaiwa.de/assets/1220111mv1440.mp4"],"rn":322},{"n":"1.2.22-101","t":"Wie weit darf eine Ladung über die Rückstrahler nach hinten höchstens hinausragen, ohne dass eine Kennzeichnung erforderlich ist?","p":2,"c":"1.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","na":"1 m","e":"Ladung darf ohne Kennzeichnung nur bis zu 1m über die Rückstrahler hinausragen. Wenn sie weiter hinausreicht, muss sie, abhängig von Wetter-, Licht- und Sichtverhältnissen gekennzeichnet werden, damit sie von anderen Verkehrsteilnehmern rechtzeitig erkannt werden kann.","rn":323},{"n":"1.2.22-102","t":"Womit ist bei Dunkelheit eine Ladung zu kennzeichnen, die mehr als 1 m über die Rückstrahler des Fahrzeugs hinausragt?","p":3,"c":"1.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Mit roter Leuchte und rotem Rückstrahler","Durch Einschalten der Nebelschlussleuchte","Mit orangefarbener Warntafel"],"co":[0],"ex":["So kann sichergestellt werden, dass die zusätzliche Länge von anderen Verkehrsteilnehmern rechtzeitig erkannt wird und der Sicherheitsabstand dahingehend angepasst werden kann.","Dies ist kein geeignetes Mittel, um die herausragende Ladung kenntlich zu machen. Sie ist direkt am Fahrzeug angebracht ist und gibt keinen Hinweis auf die überstehende Ladung. Zusätzliche Gefahr birgt das Einschalten der Nebelschlussleuchte dadurch, dass andere Verkehrsteilnehmer erheblich geblendet werden. Dies würde das rechtzeitige Erkennen der nach hinten herausragenden Ladung noch zusätzlich erschweren.","Eine gelbe Warntafel genügt in keinem Fall den Anforderung an die Kenntlichmachung von herausragender Ladung bei Dunkelheit, da sie nicht auf ausreichende Entfernung erkannt werden kann. Außerdem dienen orangefarbene Warntafeln in aller Regel dem Hinweis auf Gefahrguttransporte."],"rn":324},{"n":"1.2.22-104","t":"Was kann schon durch eine 20 %ige Überladung eintreten?","p":4,"c":"1.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Verschlechterung des Lenkverhaltens","Schäden an tragenden Fahrzeugteilen","Überbeanspruchung der Bremsen"],"co":[0,1,2],"ex":["Die Lenkung ist ebenfalls für die zulässige Gesamtmasse ausgelegt. Ist das Fahrzeug zu schwer, dann lässt es sich auch schwerer lenken.","Ist ein Fahrzeug überladen, dann reichen bereits größere Bodenwellen oder die aufgrund der Überladung größere Fliehkraft in Kurven aus, um Schäden beispielsweise an den Reifen zu verursachen.","Die Bremsen sind für die zulässige Gesamtmasse ausgelegt. Ist das Fahrzeug zu schwer, dann kann es durch Überhitzung der Bremsen zu Schäden kommen."],"rn":325},{"n":"1.2.22-106","t":"Welche Bedeutung haben orangefarbene Warntafeln an einem Fahrzeug?","p":3,"c":"1.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["- Transport leicht verderblicher Lebensmittel","- Viehtransport","- Gefahrguttransport"],"co":[2],"ex":["Orangefarbene Warntafeln kennzeichnen Gefahrguttransporte. Werden leicht verderbliche Lebensmittel transportiert, so erfordert dies keine besondere Kennzeichnung am Transporter.","Orangefarbene Warntafeln kennzeichnen Gefahrguttransporte aber keine Viehtransporte.","Transporter, die gefährliche Güter befördern, müssen mit zwei rechteckigen, senkrecht angebrachten und orangefarbenen Tafeln hinten am Fahrzeugende gekennzeichnet werden."],"rn":326},{"n":"1.2.22-107","t":"Was haben Sie zu beachten, wenn Sie Ladung transportieren möchten?","p":3,"c":"1.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["- mich nicht behindern","- selbst bei einer Vollbremsung nicht verrutschen","- nie nach vorn über das Fahrzeug hinausragen"],"co":[0,1],"ex":["Du musst die Ladung so fixieren, dass sie dich nicht in deiner sicheren Fahrweise behindert.","Du musst die Ladung so fixieren, dass sie auch unter einer Vollbremsung nicht verrutscht.","Ladung darf ab einer Höhe von 2,5 Metern bis zu 50 cm über das Fahrzeug hinausragen."],"rn":327},{"n":"1.2.22-108","t":"Ab welcher Höhe darf Ladung bis zu 50 cm nach vorn über Ihr Kraftfahrzeug hinausragen?","p":3,"c":"1.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["2,50 m","3,00 m","2,00 m"],"co":[0],"ex":["Die Höhe, ab welcher die Ladung bis zu 50 cm nach vorn über das Fahrzeug hinausstehen darf, beträgt 2,50 m.","Ab einer Mindesthöhe von 2,50 m über dem Kraftfahrzeug darf eine Ladung nach vorne hinausragen. Somit darf sie dies auch bei einer Höhe von 3 m.","Die Höhe, ab welcher die Ladung vorne über das Fahrzeug hinausstehen darf, muss mindestens 2,50 m betragen."],"rn":328},{"n":"1.2.22-109","t":"Was müssen Sie bei der Beladung Ihres Fahrzeugs beachten?","p":3,"c":"1.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Ich muss die Ladung mit geeigneten Mitteln gegen Verrutschen sichern","Mein Fahrzeug darf die zulässigen Achslasten nicht überschreiten","Mein Fahrzeug darf die zulässige Gesamtmasse maximal um 5 % überschreiten"],"co":[0,1],"ex":["Laut StVO §22 Absatz 1 musst die Ladung so gut gesichert werden, dass sie selbst im Falle einer Vollbremsung oder plötzlichen Ausweichbewegung gesichert bleibt.","Du musst bei der Beladung deines Fahrzeugs darauf achten, dass vorne und hinten die zulässige Belastung der Achsen eingehalten wird. Die Zuladungswerte kannst du im Fahrzeugschein ablesen.","Dein Fahrzeug darf die zulässige Gesamtmasse nicht überschreiten."],"rn":329},{"n":"1.2.23-001","t":"Wer ist für den verkehrssicheren Zustand eines zugelassenen Fahrzeugs verantwortlich?","p":2,"c":"1.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Der Halter","Die Haftpflichtversicherung","Der Fahrer"],"co":[0,2],"ex":["Den Halter des Fahrzeugs trifft ebenfalls Verantwortung. Er muss sicherstellen, dass das Fahrzeug vor Übergabe an einen anderen Fahrer verkehrstüchtig und sicher im Straßenverkehr nutzbar ist.","Die Haftpflichtversicherung ist erst verantwortlich, wenn Schäden mit dem Fahrzeug verursacht werden. Sie ist nicht für den verkehrssicheren Zustand des Fahrzeugs verantwortlich.","Der Fahrzeugführer muss vor Fahrbeginn sicherstellen, dass das Fahrzeug sich in einem verkehrssicheren Zustand befindet. Er zudem kommt direkt in Berührung mit dem Fahrzeug und ist folglich in der Lage, Mängel unmittelbar zu bemerken und zu reagieren."],"rn":330},{"n":"1.2.23-002","t":"Was müssen Sie tun, wenn Sie unterwegs feststellen, dass Ihr Fahrzeug nicht mehr verkehrssicher ist?","p":3,"c":"1.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Bis zur nächsten Vertragswerkstatt weiterfahren","Das Fahrzeug auf kürzestem Weg aus dem Verkehr ziehen","Erst nach Beseitigung des Schadens weiterfahren"],"co":[1,2],"ex":["Eine Weiterfahrt bis zur nächsten Vertragswerkstatt kann mit erheblichen Risiken für alle am Straßenverkehr beteiligten verbunden sein und ist somit verboten.","Der Betrieb eines Fahrzeugs, das nicht mehr verkehrssicher ist, stellt eine erhebliche und vor allem unkalkulierbare Gefahr für Sie und für andere Verkehrsteilnehmer dar.","Erst dann ist das Fahrzeug wieder verkehrssicher."],"rn":331},{"n":"1.2.23-003","t":"Welche Mängel an einem Fahrzeug können zu einer Gefährdung des Straßenverkehrs führen?","p":4,"c":"1.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Unzureichende Bremswirkung","Defekte Schlussleuchten","Abgefahrene Reifen"],"co":[0,1,2],"ex":["Sind die Bremsen verschlissen, so wird der Bremsweg länger. Dadurch können Unfälle begünstigt werden.","Ist eine Schlussleuchte defekt, so kann der nachfolgende Verkehr dich unter Umständen nicht rechtzeitig erkennen. Dies kann zum Beispiel Auffahrunfälle begünstigen.","Abgefahrene Reifen können den Straßenverkehr gefährden. Sie sind nämlich häufig die Ursache dafür, dass Fahrzeug ins Rutschen kommen. Dadurch steigt das Risiko für einen Unfall."],"rn":332},{"n":"1.2.23-006","t":"Sie wollen während des Führens eines Fahrzeugs telefonieren. Was ist zu beachten?","p":3,"c":"1.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Die Bedienung des Telefons kann mich ablenken","Das Gespräch kann mich ablenken","Das Telefonieren mit einer Freisprecheinrichtung lenkt mich nicht ab"],"co":[0,1],"ex":["Beim Fahren benötigst du beide Hände und Augen, um eine sichere und konzentrierte Fahrweise zu ermöglichen. Die Bedienung eines Telefons nimmt beides in Anspruch und sollte deshalb vermieden werden.","Weil dich ein Telefonat während des Autofahrens ablenken kann, solltest du dies möglichst vermeiden und im Notfall mit Freisprecheinrichtung telefonieren.","Mit Freisprecheinrichtung ist das Telefonieren zwar erlaubt, sollte jedoch auf das nötigste begrenzt werden, weil es den Fahrer in seiner aufmerksamen und konzentrierten Fahrweise einschränkt."],"rn":333},{"n":"1.2.23-007","t":"Sie möchten während der Fahrt telefonieren. Was müssen Sie beachten?","p":3,"c":"1.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Ich darf ohne Freisprecheinrichtung telefonieren, wenn das Fahrzeug an geeigneter Stelle steht und der Motor vollständig abgestellt ist","Ich darf ohne Freisprecheinrichtung telefonieren, wenn das Fahrzeug mit Schrittgeschwindigkeit fährt","Ich benötige eine Freisprecheinrichtung"],"co":[0,2],"ex":["So gewährleistest du, dass kein Verkehrsteilnehmer gefährdet wird.","Du darfst nur ohne Freisprecheinrichtung telefonieren, wenn das Fahrzeug parkt.","Während der Fahrt ist telefonieren erlaubt, wenn du eine Freisprecheinrichtung verwendest. Trotzdem schränkt es dich etwas im aufmerksamen Fahren ein. Halte deshalb das Telefonat trotz Freisprecheinrichtung so kurz wie möglich."],"rn":334},{"n":"1.2.23-008","t":"Sie möchten ein Kraftfahrzeug auf öffentlichen Straßen in Betrieb nehmen. Was müssen Sie beachten?","p":3,"c":"1.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Ich muss der Fahrzeughalter sein","Das Kraftfahrzeug muss verkehrssicher sein","Für das Kraftfahrzeug muss eine Haftpflichtversicherung bestehen"],"co":[1,2],"ex":["Du musst hierfür nicht der Fahrzeughalter sein.","Nur wenn gewährleistet ist, dass das Fahrzeug verkehrssicher ist, darfst du es benutzen. Hierfür sind Fahrzeughalter und -fahrer verantwortlich.","Dies ist notwendig, um ein Kraftfahrzeug auf öffentlichen Straßen in Betrieb zu nehmen."],"rn":335},{"n":"1.2.26-005","t":"Was gilt unmittelbar vor und auf Zebrastreifen?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["- geparkt werden","- überholt werden","- gehalten werden"],"co":[0,1,2],"ex":["Vor und auf dem Zebrastreifen herrscht Parkverbot. Fußgänger, die die Straße überqueren möchten, könnten durch ein parkendes Fahrzeug verdeckt werden.","Vor und auf dem Zebrastreifen darf nicht überholt werden. So könnten Fußgänger übersehen werden, die die Straße überqueren wollen.","Vor und auf dem Zebrastreifen darf nicht gehalten werden. Dies würde einerseits den Verkehrsfluss und andererseits das Überqueren der Straße durch Fußgänger behindern."],"rn":336},{"n":"1.2.26-007","t":"Wie verhalten Sie sich richtig?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Ich halte an, weil ein Mann den Fußgängerüberweg überqueren möchte","Ich fahre langsam weiter, weil kein Fußgänger erkennbar den Fußgängerüberweg benutzen möchte","Ich halte an, weil ein Kind hinter dem Transporter auf die Fahrbahn treten wird"],"co":[0],"ex":["Du musst anhalten und warten, bis der Mann den Fußgängerüberweg vollständig passiert und kein weiterer Fußgänger in unmittelbarer Nähe diesen überqueren möchte.","Der Mann, der von rechts angelaufen kommt, möchte den Fußgängerüberweg erkennbar benutzen.","Hinter dem Transporter ist kein Kind in Sicht."],"v":["https://video4.kalaiwa.de/assets/1226007v1440.mp4"],"rn":337},{"n":"1.2.26-108","t":"Die Ampel zeigt „Grün“. Sie wollen rechts abbiegen. Wie verhalten Sie sich gegenüber Personen, welche die Straße überqueren, in die Sie einbiegen möchten?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Die Personen durch Hupen warnen","Zügig vor den Personen abbiegen","Den Personen das Überqueren der Straße ermöglichen"],"co":[2],"ex":["Die Hupe dient als Warnsignal, wenn man sich selbst oder andere gefährdet sieht. Nur dann ist das Hupen zulässig.","Du musst warten und die Fußgänger die Straße überqueren lassen. Erst dann darfst du rechts abbiegen.","Du musst die Personen erst die Straße überqueren lassen, bevor du nach rechts abbiegen darfst."],"rn":338},{"n":"1.2.26-111","t":"In welchen Fällen müssen Sie an einen Fußgängerüberweg besonders vorsichtig heranfahren?","p":5,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Wenn die Sicht auf den Fußgängerüberweg eingeschränkt ist","Wenn Fußgänger die Fahrbahn überqueren wollen","Wenn ein anderes Fahrzeug bereits vor dem Fußgängerüberweg wartet"],"co":[0,1,2],"ex":["So könnten herannahende Fußgänger nicht gleich gesehen werden. Stelle dich darauf ein und fahre langsam und vorsichtig und sei bremsbereit.","Wollen Fußgänger die Fahrbahn überqueren, dann musst du besonders vorsichtig heranfahren, im Bedarfsfall anhalten und mit dem Weiterfahren warten, bis diese den Fußgängerweg vollständig überquert haben.","Dann musst auch du anhalten und warten."],"rn":339},{"n":"1.2.26-113","t":"Eine Person will die Fahrbahn auf dem Fußgängerüberweg überqueren. Wie verhalten Sie sich?","p":5,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Ich überhole wartende Fahrzeuge mit besonderer Vorsicht","Ich bereite mich auf das Anhalten vor","Ich überhole nicht"],"co":[1,2],"ex":["An Fußgängerüberwegen ist das Überholen verboten.","Der Fußgänger hat am Fußgängerüberweg Vorrang. Du musst anhalten und ihn passieren lassen.","Das Überholen ist an Fußgängerüberwegen sehr gefährlich und daher verboten."],"rn":340},{"n":"1.2.26-114","t":"Wie verhalten Sie sich in dieser Situation?","p":5,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Ich schließe unmittelbar zum blauen Fahrzeug auf","Ich warte vor dem Fußgängerüberweg, bis das blaue Fahrzeug abgebogen ist","Ich lasse den Fußgänger die Fahrbahn überqueren"],"co":[1,2],"ex":["Du musst der Person, die den Fußgängerüberweg nutzen will, Vorrang gewähren. Zudem musst du bei stockendem Verkehr vor dem Fußgängerübergang halten, wenn du sonst darauf halten müsstest.","Du darfst den Fußgängerüberweg erst überqueren, wenn das blaue Fahrzeug abgebogen ist und die Person den Fußgängerüberweg vollständig überquert hat, da du sonst den Fußgängerüberweg blockieren würdest.","Die Person befindet sich an einem Fußgängerüberweg und hat Vorrang."],"i":["https://video2.kalaiwa.de/assets/1226114.webp"],"rn":341},{"n":"1.2.26-115","t":"Warum ist eine defensive Fahrweise beim Annähern an Fußgängerüberwege besonders wichtig?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Damit Fußgänger nicht verunsichert werden","Damit Auffahrunfälle vermieden werden","Damit nachfolgende Fahrzeuge leichter überholen können"],"co":[0,1],"ex":["Du musst den Fußgängern den Vorrang gewähren und solltest möglichst langsam auf den Fußgängerüberweg zufahren, um diese nicht zu verunsichern.","Bremst du rechtzeitig und gemäßigt ab, dann erkennt dies auch der nachfolgende Verkehr und kann sich dementsprechend verhalten.","Bei Fußgängerüberwegen darf nicht überholt werden."],"rn":342},{"n":"1.2.26-116","t":"Sie fahren auf einer Straße mit zwei Fahrstreifen in einer Richtung auf dem linken Fahrstreifen. Vor einem ca. 30 m entfernten Fußgängerüberweg hält auf dem rechten Fahrstreifen ein Lkw an. Wie verhalten Sie sich?","p":5,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Ich fahre mit mäßiger Geschwindigkeit heran","Ich fahre zügig weiter","Ich gebe Warnzeichen und fahre am Lkw vorbei"],"co":[0],"ex":["Du kannst den Fußgängerüberweg aufgrund des haltenden LKWs nicht einsehen. Ein wahrscheinlicher Grund, warum der LKW-Fahrer hält, ist, dass Personen den Fußgängerüberweg überqueren möchten. So oder so musst du in mäßiger Geschwindigkeit an den Fußgängerüberweg heranfahren, sodass du rechtzeitig vor ihm abbremsen kannst, falls Fußgänger diesen überqueren möchten.","Du reduzierst die Fahrgeschwindigkeit und stellst dich darauf ein, am Fußgängerüberweg anhalten zu müssen, falls Personen diesen überqueren möchten. Der Grund des haltenden LKWs ist für dein Verhalten am Fußgängerüberweg irrelevant.","Durch den LKW ist deine Sicht auf den Fußgängerüberweg eingeschränkt. Deswegen musst du die Geschwindigkeit reduzieren und dich darauf einstellen, dass du am Fußgängerüberweg halten musst, um Personen diesen passieren zu lassen."],"rn":343},{"n":"1.2.26-117","t":"Ein Radfahrer möchte - ohne abzusteigen - auf einem Fußgängerüberweg die Fahrbahn überqueren. Wie verhalten Sie sich?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Ich hupe und fahre vor dem Radfahrer weiter","Ich lasse den Radfahrer die Fahrbahn passieren","Ich bremse erst kurz vor dem Fußgängerüberweg ab"],"co":[1],"ex":["So riskierst du, den Radfahrer zu behindern oder sogar zu gefährden. Du solltest dem Radfahrer den Vorrang gewähren und unnötige Risiken vermeiden.","Damit keine gefährliche Situation ensteht, solltest du den Radfahrer die Fahrbahn passieren lassen. Es ist wichtiger, die Sicherheit im Straßenverkehr zu gewährleisten, als auf sein Recht zu beharren.","Sobald ersichtlich ist, dass der Radfahrer den Fußgängerweg nutzen möchte, um die Straße zu queren, solltest du deine Geschwindigkeit vermindern."],"rn":344},{"n":"1.2.26-118","t":"Vor Ihnen befindet sich ein Fußgängerüberweg, hinter dem der Verkehr auf Ihrem Fahrstreifen stockt. Wie verhalten Sie sich?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Auf dem Fußgängerüberweg warten, wenn keine Personen zu sehen sind","Auf dem Fußgängerüberweg warten, um den Fahrzeugrückstau zu verkürzen","Vor dem Fußgängerüberweg warten, um Personen das Überqueren zu ermöglichen"],"co":[2],"ex":["Das ist verboten. Du musst vor dem Fußgängerüberweg warten, bis sich der stockende Verkehr aufgelöst hat. So gewährleistest du, niemanden am Nutzen des Fußgängerüberwegs zu behindern.","Das verkürzt den Fahrzeugrückstau nicht und ist zudem laut StVO untersagt.","Du musst vor dem Fußgängerüberweg warten, bis der Verkehr wieder fließt."],"rn":345},{"n":"1.2.26-008-M","t":"Was gilt in dieser Situation?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["- nicht überholen","- nur mit mäßiger Geschwindigkeit überholen","- überholen, da kein Gegenverkehr erkennbar ist"],"co":[0],"ex":["Vor und auf einem Fußgängerüberweg ist das Überholen verboten.","Du darfst hier nicht Überholen.","Es könnte von links hinter dem Transporter jemand auf die Fahrbahn treten. Zudem ist das Überholen an Fußgängerüberwegen untersagt."],"i":["https://video2.kalaiwa.de/assets/1226008m.webp"],"rn":346},{"n":"1.2.26-009-M","t":"Womit müssen Sie bei derartigen Querungshilfen rechnen?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Radfahrer überqueren die Straße, ohne den Verkehr zu beachten","Fußgänger nehmen an, dass sie Vorrang vor dem Verkehr haben","Fußgänger beachten stets den Vorrang von Fahrzeugen"],"co":[0,1],"ex":["Radfahrer haben hier keinen Vorrang vor dir, empfinden das aber häufig so. Fahr deshalb vorsichtig und rechne damit, dass der Radfahrer unaufmerksam die Fahrbahn überquert.","Du musst damit rechnen, dass Fußgänger auf deine Fahrbahn laufen. Die Querungshilfen sollen Fußgängern das Überqueren der Fahrbahn in Etappen zwar erleichtern, haben aber keinen Vorrang. Sie empfinden das aber häufig so. Fahr deshalb vorsichtig.","Fußgänger gehen an Querungshilfen oft davon aus, dass sie Vorrang haben. Sie überqueren unaufmerksam die Fahrbahn."],"i":["https://video2.kalaiwa.de/assets/1226009m.webp"],"rn":347},{"n":"1.2.26-010-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Ich verringere meine Geschwindigkeit und bereite mich darauf vor, anzuhalten","Ich fahre mit gleicher Geschwindigkeit weiter","Ich beobachte die Fußgänger aufmerksam"],"co":[0,2],"ex":["Da die Fußgänger jederzeit die Straße über den Zebrastreifen überqueren könnten, musst du jetzt langsamer fahren. Falls die Fußgänger losgehen, solltest du darauf vorbereitet sein, sofort anzuhalten.","Es ist falsch, jetzt mit gleicher Geschwindigkeit weiterzufahren, da die Fußgänger bereits sehr nah an dem Zebrasteifen stehen. Es sieht so aus, als ob sie die Straße bald überqueren werden. Wenn du deine Geschwindigkeit beibehältst, kannst du wahrscheinlich nicht rechtzeitig zum Stehen kommen.","Du solltest die Fußgänger jetzt aufmerksam beobachten, da diese direkt vor einem Zebrastreifen stehen und jederzeit die Straße überqueren könnten. Dies musst du sofort erkennen, um früh genug anhalten zu können."],"i":["https://video2.kalaiwa.de/assets/1226010m.webp"],"rn":348},{"n":"1.2.26-119-M","t":"Wie verhalten Sie sich richtig?","p":4,"c":"1.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Ich biege vor dem entgegenkommenden Fußgänger ab, weil nur dieser warten muss","Ich warte, weil beide Fußgänger Vorrang haben","Ich fahre weiter, weil beide Fußgänger warten müssen"],"co":[1],"ex":["Beide Fußgänger haben Vorrang vor dir.","Du musst erst beide Fußgänger die Straße vollständig überqueren lassen, bevor du nach links einbiegen darfst.","Du musst warten. Die Fußgänger haben Vorrang."],"i":["https://video2.kalaiwa.de/assets/1226119m.webp"],"rn":349},{"n":"1.2.34-004","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- warte im Fahrzeug auf die Räumung der Unfallstelle","- verlasse den Tunnel über den Notausgang","- lasse beim Verlassen den Zündschlüssel oder Transponder im Fahrzeug"],"co":[1,2],"ex":["Verlasse auf schnellstmöglichem Weg den Tunnel über den nächstgelegenen Notausgang.","Nachdem du angehalten und den Motor abgestellt hast, musst du über den Notausgang den Tunnel verlassen.","So können Sicherheitskräfte dein Fahrzeug im Bedarfsfall bewegen."],"v":["https://video4.kalaiwa.de/assets/1234004v1440.mp4"],"rn":350},{"n":"1.2.34-006","t":"Sie sind an einem Unfall beteiligt. Welches Dokument müssen Sie anderen Unfallbeteiligten auf Verlangen vorweisen?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Den Führerschein","Den Vertrag zur Haftpflichtversicherung","Die Zulassungsbescheinigung Teil I oder die Betriebserlaubnis"],"co":[0,2],"ex":["Du musst auf Verlangen anderer Unfallbeteiligter deinen Führerschein und Anschrift vorzeigen, kannst dies allerdings gleichermaßen von anderen Personen einfordern.","Den Vertrag zur Haftpflichtversicherung musst du nicht vorweisen.","Die Feststellung des Fahrzeugs muss gemacht werden. Das bedeutet, dass du entweder die Zulassungsbescheinigung Teil I oder die Betriebserlaubnis vorweisen musst."],"rn":351},{"n":"1.2.34-007","t":"Sie kommen als Erster an eine Unfallstelle mit Verletzten. Sie sichern die Unfallstelle ab und haben sich einen Überblick verschafft. Was müssen Sie noch tun?","p":4,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- Rettungsdienst alarmieren","- Verletzten Erste Hilfe leisten","- Unfall dokumentieren"],"co":[0,1],"ex":["Bevor du dich um die Verletzten kümmerst, musst du den Rettungsdienst alarmieren.","Du bist dazu verpflichtet, den Verletzten Erste Hilfe zu leisten.","Du musst den Unfall nicht dokumentieren."],"rn":352},{"n":"1.2.34-008","t":"Sie sind an einem Unfall auf einem Parkplatz beteiligt. Es ist geringer Sachschaden entstanden. Alle Beteiligten sehen von einer Information der Polizei ab. Was ist für die Schadensregulierung jetzt hilfreich?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Der Austausch erforderlicher Angaben von Beteiligten","Die Beschreibung des Unfallhergangs im Unfallbericht","Das Fotografieren der Unfallstelle von mehreren Seiten"],"co":[0,1,2],"ex":["Du solltest die wichtigsten Angaben mit deinem Unfallgegner austauschen, um in Kontakt treten zu können und abgesichert zu sein.","Ihr solltet ebenfalls einvernehmlich den Unfallhergang festhalten.","Du solltest den Schaden mithilfe von Fotos dokumentieren. So kann die Versicherung den Schaden besser einschätzen und bewerten."],"rn":353},{"n":"1.2.34-009","t":"Sie haben mit Ihrem Fahrzeug ein fremdes geparktes Fahrzeug beschädigt. Trotz angemessener Wartezeit ist der Geschädigte nicht erschienen. Wie verhalten Sie sich jetzt richtig?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- meinen Namen und meine Anschrift einem unbeteiligten Zeugen mitteilen","- meinen Namen und meine Anschrift am Unfallort hinterlassen","- den Unfall der Polizei melden"],"co":[1,2],"ex":["Es wäre falsch, deinen Namen sowie deine Anschrift einem unbeteiligten Zeugen zu geben. Du kannst dich nicht darauf verlassen, dass dieser dem Geschädigten deine Daten auch wirklich zukommen lässt. Die Polizei musst du ohnehin verständigen.","Du musst zusätzlich zum Melden bei der Polizei deinen Namen und deine Anschrift am Unfallort hinterlassen, wenn der Geschädigte nicht erscheint. So weiß er sofort, wer für den Schaden verantwortlich ist und kann dich kontaktieren.","Wenn du ein fremdes geparktes Auto beschädigst, musst du es in jedem Fall als Unfall bei der Polizei melden. Es reicht nicht aus, nur einen Zettel mit deinen Kontaktdaten am Unfallort zu hinterlassen. Kontaktierst du die Polizei nicht, kannst du für Unfallflucht belangt werden."],"rn":354},{"n":"1.2.34-010","t":"Sie sind an einem Unfall mit einem Fahrzeug beteiligt, an dem die dargestellte orangefarbene Tafel angebracht ist. Sie sehen, dass aus dem Fahrzeug eine Flüssigkeit austritt. Wie verhalten Sie sich richtig?","p":4,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Ich versuche, das Leck am Fahrzeug abzudichten","Ich vermeide es, den Bereich mit der ausgelaufenen Flüssigkeit zu betreten","Ich gebe beim Notruf die Zahlen auf der orangefarbenen Tafel an"],"co":[1,2],"ex":["Versuche auf keinen Fall, das Leck am Fahrzeug abzudichten. Bei dem Stoff handelt es sich um ein Gefahrgut, dem man sich nie ungeschützt nähern sollte. Gib deshalb beim Notruf die Zahlen der Gefahrguttafel an.","Bei Gefahrgütern handelt es sich um Substanzen, die für Menschen und die Umwelt gefährlich sind. Vermeide den Kontakt mit der ausgelaufenen Flüssigkeit und halte nach Möglichkeit Abstand.","Bei einem Unfall mit einem Gefahrguttransport musst du beim Notruf die Zahlen auf dem orangefarbenen Schild angeben. So weiß die Notrufzentrale, welche Stoffe das Fahrzeug transportiert und kann entsprechende Spezialkräfte schicken."],"i":["https://video4.kalaiwa.de/assets/1234010.webp"],"rn":355},{"n":"1.2.34-011","t":"Unter welcher Notrufnummer erreichen Sie europaweit den Rettungsdienst?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","na":"112","e":"Unter der Rufnummer 112 erreichst du überall in Europa gebührenfrei die Notrufzentrale. So gelangst du unmittelbar zu Rettungsdienst, Polizei und Feuerwehr.","rn":356},{"n":"1.2.34-103","t":"Sie kommen als Erster an eine Unfallstelle mit Verletzten. Was sollten Sie in der Regel zuerst tun?","p":4,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Zur nächsten Telefonzelle fahren und Rettungsdienst alarmieren","Unfallstelle absichern","Prüfen, wie schwer die Verletzungen sind"],"co":[1],"ex":["Erst nachdem die Unfallstelle abgesichert und erste Hilfe geleistet wurde, ist der Rettungsdienst zu alarmieren.","Unfallstelle absichern bedeutet das Warndreieck aufstellen, Warnblinkanlage einschalten, um die Gefahrenstelle gut erkennbar zumachen (und wenn möglich die Unfallstelle räumen), damit das Risiko für einen Folgeunfall reduziert wird.","Erste Hilfe ist im zweiten Schritt, nach Absicherung der Unfallstelle, zu leisten."],"rn":357},{"n":"1.2.34-106","t":"Wie können Sie auf der Autobahn Hilfe anfordern?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Über die Telefonnummern 112 oder 110","Über Notrufsäulen","Über Autobahnraststätten"],"co":[0,1,2],"ex":["Die offiziellen Notrufnummern sind in Deutschland die \"110\" für die Polizei und die \"112\" für Feuerwehr und Notarzt. Diese sind allerdings nur im Notfall zu wählen, nicht jedoch im Falle einer Autopanne.","Notrufsäulen stehen am Autobahnrand im Abstand von 2 km. Kleine schwarze Pfeile an den Leitpfosten zeigen an, in welche Richtung gegangen werden muss, um schnellstmöglich die Nächste zu erreichen. Sobald die Klappe an der Notrufsäule angehoben wird, meldet sich die Straßenmeisterei. Zu deren Orientierung sollte man die an der Säule eingravierte Nummer oder/und die Kilometerzahl der Pannenstelle (alle 500 m stehen am Autobahnrand blaue Schilder mit Kilometerangaben) durchgeben.","Im Notfall sollten Notrufsäulen aufgesucht werden. Wenn es um eine Pannenhilfe geht, dann ist es jedoch riskanter, auf der Autobahn zur nächsten Notrufsäule zu wandern. Hier empfiehlt es sich, falls kein Handy zur Hand, sich an die nächstfolgende Raststätte zu wenden."],"rn":358},{"n":"1.2.34-109","t":"Sie bemerken im Tunnel einen Unfall. Was ist zu tun?","p":4,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Notdienste über Notrufstation informieren","Warnblinklicht einschalten","Fahrzeug nicht verlassen"],"co":[0,1],"ex":["Nur so kommt möglichst schnell Hilfe für Verletzte und zum Aufräumen der Unfallstelle.","Das ist der erste wichtige Schritt, um andere Verkehrsteilnehmer auf den Unfall aufmerksam zu machen und so erhöhte Vorsicht zu signalisieren.","Falls nötig, musst du erste Hilfe leisten und Notdienste über die Notrufstation informieren."],"rn":359},{"n":"1.2.34-110","t":"Sie sind an einem Verkehrsunfall beteiligt. Wozu sind Sie verpflichtet?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- den anderen Beteiligten angeben, dass ich auch am Unfall beteiligt war","- auf Verlangen den Berechtigten meinen Namen und meine Anschrift angeben","- bei geringfügigem Schaden unverzüglich zur Seite fahren"],"co":[0,1,2],"ex":["Wenn du an einem Verkehrsunfall beteiligt bist, dann musst du dies den anderen Beteiligten mitteilen.","Bist du an einem Verkehrsunfall beteiligt, dann musst du Name und Anschrift angeben, wenn dies verlangt wird, kannst dies aber auch gleichermaßen selbst einfordern.","Bei geringfügigem Schaden musst du unverzüglich zur Seite fahren, um eine Gefährdung und eine Behinderung zu vermeiden."],"rn":360},{"n":"1.2.34-111","t":"Sie haben auf einer Landstraße einen Unfall. Wie sichern Sie diese Unfallstelle ab?","p":4,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Ich warne, falls erforderlich, andere Fahrzeuge z. B. durch Handzeichen","Ich schalte sofort das Warnblinklicht ein","Ich stelle das Warndreieck gut sichtbar in ca. 100 m Entfernung vor der Unfallstelle auf"],"co":[0,1,2],"ex":["So können diese frühzeitig auf die Unfallsituation reagieren.","Das ist der erste Schritt bei der Absicherung einer Unfallstelle.","Zuvor musst du eine Warnweste anziehen, um für alle Verkehrsbeteiligten gut sichtbar zu sein."],"rn":361},{"n":"1.2.34-112","t":"Woran erkennen Sie den kürzesten Weg zur nächsten Notrufsäule auf Bundesautobahnen?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- Bodenmarkierungen auf dem Standstreifen","- Richtungsmarkierungen auf den Leitplanken","- schwarzen Pfeilen auf den Leitpfosten"],"co":[2],"ex":["Bodenmarkierungen auf dem Standstreifen sind kein Hinweis auf die nächstgelegene Notrufsäule.","Den Weg zur nächsten Notrufsäule zeigt ein schwarzer Pfeil auf dem Leitpfosten.","Auf Bundesautobahnen sind auf Leitpfosten schwarze Pfeile abgebildet, die anzeigen, in welcher Richtung die nächste Notrufsäule steht. Die Entfernung bis zu dieser beträgt maximal einen Kilometer."],"rn":362},{"n":"1.2.34-113","t":"Wozu sind Sie verpflichtet, wenn Sie an einem Verkehrsunfall beteiligt sind?","p":4,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- anhalten und mich über die Unfallfolgen vergewissern","- die Unfallstelle absichern","- Hilfe leisten, sollte es Verletzte geben"],"co":[0,1,2],"ex":["Das ist einer der Schritte, zu dem du verpflichtet bist, wenn du an einem Verkehrsunfall beteiligt bist.","Das musst du im zweiten Schritt tun.","Nachdem du dich im 3. Schritt über die Unfallfolgen vergewissert hast, musst du im Falle verletzter Personen Hilfe leisten."],"rn":363},{"n":"1.2.34-114","t":"Ein Kraftfahrer hat ein anderes Fahrzeug leicht beschädigt und entfernt sich unerlaubt. Welche Folge kann dies haben?","p":3,"c":"1.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Eine Geld- oder Haftstrafe","Eine Anordnung einer medizinisch-psychologischen Untersuchung","Einen Entzug der Fahrerlaubnis oder ein Fahrverbot"],"co":[0,1,2],"ex":["Nach dem Strafgesetzbuch kann eine begangene Fahrerflucht mit einer Geldstrafe oder einer Freiheitsstrafe von bis zu drei Jahren bestraft werden.","Die Anordnung einer medizinisch-psychologischen Untersuchung ist bei einem erheblichen Verstoß gegen die verkehrsrechtlichen Vorschriften grundsätzlich immer möglich.","Nach einer Fahrerflucht können Punkte in Flensburg, ein Fahrverbot von maximal drei Monaten sowie die Entziehung der Fahrerlaubnis folgen."],"rn":364},{"n":"1.2.36-001","t":"Ein Polizeibeamter regelt auf einer Kreuzung den Verkehr, obwohl die Ampeln in Betrieb sind. Was gilt?","p":4,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Die vorfahrtregelnden Verkehrszeichen","Die Zeichen des Polizeibeamten","Die Lichtzeichen der Ampeln"],"co":[1],"ex":["Die Vorfahrtsregeln treten nur in Kraft, wenn keine Polizeibeamten oder Verkehrszeichen den Verkehr regeln.","Verkehrsregelung ist in dieser Abfolge vorgeschrieben: 1. Anweisungen von Polizeibeamten, 2. Ampeln, 3. Verkehrszeichen, 4. Grundregel \"Rechts vor Links\"","Nach diesen müsste man sich richten, wenn kein Polizeibeamter auf der Kreuzung stünde."],"rn":365},{"n":"1.2.36-003","t":"Welche Bedeutung haben Weisungen von Polizeibeamten?","p":4,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Ihnen ist Folge zu leisten","Ihnen ist nur Folge zu leisten, wenn sie mit den aufgestellten Verkehrszeichen übereinstimmen","Sie entbinden von der eigenen Sorgfaltspflicht"],"co":[0],"ex":["Anweisungen der Polizei ist Folge zu leisten.","Die Weisungen eines Polizeibeamten setzten die Verkehrsregelung mit Verkehrszeichen außer Kraft.","Die Anweisungen des Polizeibeamten entbindet sie nicht von Ihrer Sorgfaltspflicht."],"rn":366},{"n":"1.2.36-007","t":"Im Rückspiegel sehen Sie auf dem Dach eines unmittelbar hinter Ihnen fahrenden Streifenwagens in roter Leuchtschrift „STOP POLIZEI“. Für wen gilt dies?","p":3,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Für alle Fahrzeuge, die sich auf der Straße befinden","Nur für Sie","Für alle nachfolgenden Fahrzeuge"],"co":[1],"ex":["Eine Anweisung auf der Leuchtschrift eines Streifenwagens gilt immer nur für den direkt vorausfahrenden Verkehrsteilnehmer oder das sich direkt hinter der Streife befindliche Fahrzeug.","Die Anweisung auf einem Hinweisschild eines Streifenwagens gilt entweder für das direkt vorausfahrende oder das direkt nachfolgende Fahrzeug. Da die Schrift im Rückspiegel zu erkennen ist und Sie direkt vor dem Polizeiauto fahren, sind Sie mit dieser Aufforderung gemeint.","Wären die nachfolgenden Fahrzeuge gemeint, könnten Sie im Rückspiegel keine Schrift erkennen. Dies kann von den Polizeibeamten eingestellt werden."],"rn":367},{"n":"1.2.36-011","t":"Ein Polizeifahrzeug überholt Sie und schert unmittelbar vor Ihnen ein. Auf dem Dach erscheint in roter Leuchtschrift „BITTE FOLGEN“. Wie müssen Sie sich verhalten?","p":3,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["- anhalten, wenn das Polizeifahrzeug anhält","- dem Polizeifahrzeug folgen","- nach dem Anhalten den Motor laufen lassen"],"co":[0,1],"ex":["Wenn das Polizeifahrzeug hält, musst auch du anhalten.","Du musst den Anweisungen der Polizei Folge leisten.","Den Motor kannst du abstellen, sobald du angehalten hast."],"rn":368},{"n":"1.2.36-012","t":"Ein Polizeifahrzeug überholt Sie und schert unmittelbar vor Ihnen ein. Auf dem Dach erscheint in roter Leuchtschrift „BITTE FOLGEN“. Für wen gilt dies?","p":3,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Für alle Fahrzeuge auf meinem Fahrstreifen","Für nachfolgende Polizei- und Rettungsfahrzeuge","Für mich"],"co":[2],"ex":["Die Anweisung gilt nur für dich und nicht für die übrigen Fahrzeuge auf deinem Fahrstreifen.","Die Anweisung bezieht sich nicht auf andere Polizei- oder Rettungsfahrzeuge, sondern auf dich.","Weil das Polizeifahrzeug unmittelbar vor dir einschert, kannst du davon ausgehen, dass es sich auf dich bezieht."],"rn":369},{"n":"1.2.36-013","t":"Aus einem unmittelbar vor Ihnen fahrenden Fahrzeug wird Ihnen mit der „Polizeikelle“ Zeichen gegeben. Was bedeutet dies?","p":3,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Ich muss in die gezeigte Richtung abbiegen","Ich muss dem Fahrzeug folgen, bis es anhält","Ich darf das Fahrzeug nicht überholen"],"co":[1,2],"ex":["Das signalisiert dir, dass du dem Polizeifahrzeug folgen sollst.","Wird aus einem Fahrzeug mit \"Polizeikelle\" gewunken, dann musst du dem Fahrzeug folgen.","Du musst hinter dem Fahrzeug herfahren und darfst es nicht überholen."],"rn":370},{"n":"1.2.36-004-B","t":"Welches Verhalten ist richtig?","p":4,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Der gelbe Pkw muss die Kreuzung räumen","Ich darf schon jetzt abbiegen","Ich muss mich auf die Weiterfahrt vorbereiten"],"co":[0,2],"ex":["Hebt der Polizeibeamte einen Arm, dann bedeutet das, dass der Verkehrsteilnehmer in der Kreuzung diese räumen muss.","Du darfst erst abbiegen, wenn der Polizist seitlich zu dir steht und beide Arme zu beiden Seiten ausstreckt.","Die Weiterfahrt ist erst erlaubt, sobald der Polizist nicht mehr quer sondern seitlich zu deiner Fahrtrichtung steht. Ein hochgehobener Arm signalisiert dir, dich auf die Weiterfahrt vorzubereiten."],"i":["https://video4.kalaiwa.de/assets/1236004b.webp"],"rn":371},{"n":"1.2.36-014-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Ich lasse das blaue Fahrzeug zuerst fahren","Ich warte vor der Kreuzung auf weitere Weisungen des Polizeibeamten","Ich überquere die Kreuzung vorsichtig"],"co":[2],"ex":["Der Polizeibeamte ordnet dem blauen Fahrzeug mit den seitlich ausgestreckten Armen an: \"Halt vor der Kreuzung\".","Der Polizeibeamte gibt dir bereits das Zeichen zur Weiterfahrt.","Den Zeichen des Polizeibeamten hast du Folge zu leisten. Dieser zeigt dir durch das seitliche Ausstrecken beider Arme, dass du vorsichtig auf deiner Fahrbahn weiterfahren darfst."],"i":["https://video2.kalaiwa.de/assets/1236014m.webp"],"rn":372},{"n":"1.2.36-015-M","t":"Wer darf zuerst fahren?","p":4,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Der rote Pkw","Das Motorrad","Ich"],"co":[0],"ex":["Da der Pkw geradeaus über die Kreuzung fahren will, hat er Vorrang vor dem linkabbiegenden Motorrad. Du musst ohnehin warten, da du keine Vorfahrt hast.","Das Motorrad möchte links abbiegen und hat somit keinen Vorrang vor dem geradeausfahrenden Pkw. Allerdings darf das Motorrad vor dir fahren, da es sich auf der Straße befindet, die in dieser Situation Vorfahrt hat.","Auch wenn du dich laut Verkehrsschild auf einer Vorfahrtsstraße befindest und die Ampel grün leuchtet, darfst du in dieser Situation nicht zuerst fahren. Der Polizist signalisiert, dass du keine Vorfahrt hast."],"i":["https://video2.kalaiwa.de/assets/1236015m.webp"],"rn":373},{"n":"1.2.36-016-M","t":"Was ist in dieser Situation richtig?","p":4,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["- vor der Kreuzung warten","- umkehren","- ohne zu warten nach rechts abbiegen"],"co":[0],"ex":["Der Verkehrspolizist mit Warnweste steht mit ausgestreckten Armen auf der Kreuzung. Das bedeutet, dass du abbremsen und vor der Kreuzung warten musst.","Die Handzeichen des Verkehrspolizisten bedeuten nicht, dass du umkehren sollst. Er zeigt dir an, dass du an der Haltelinie warten musst.","Du darfst nicht einfach nach rechts abbiegen. Der Verkehrspolizist in der Warnweste ersetzt in dieser Situation die Ampel und zeigt an, dass der Verkehr von rechts und links Vorrang hat."],"i":["https://video4.kalaiwa.de/assets/1236016m.webp"],"rn":374},{"n":"1.2.36-101-B","t":"Was gilt hier?","p":4,"c":"1.2.36","ch":"Zeichen Und Weisungen Der Polizeibeamten","th":"Verhalten Im Strassenverkehr","o":["Vor dem Einfahren in die Kreuzung muss auf weitere Zeichen des Polizeibeamten gewartet werden","Die Kreuzung darf überquert werden","Abbiegen ist nicht zulässig"],"co":[1],"ex":["Das wäre der Fall, wenn der Polizeibeamte einen Arm in die Höhe strecken würde.","Der Polizeibeamte steht seitlich zu dir mit beiden Armen seitlich ausgestreckt. Das signalisiert dir, dass du die Kreuzung überqueren darfst.","Du darfst die Kreuzung überqueren und somit auch abbiegen, wenn der Polizeibeamte in dieser Position zu dir steht."],"i":["https://video2.kalaiwa.de/assets/1236101b.webp"],"rn":375},{"n":"1.2.37-009","t":"Wo ist bei dieser Ampel mit Grünpfeilschild vor dem Abbiegen nach rechts anzuhalten?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["An der Haltlinie","Es muss nicht angehalten werden","Wenn keine Haltlinie vorhanden ist, vor der Kreuzung oder Einmündung"],"co":[0,2],"ex":["Werden keine Verkehrsteilnehmer behindert, dann kann nach dem Halten der auf dem rechten Fahrstreifen befindliche Fahrzeugführer nach rechts abbiegen.","Dies wäre der Fall, wenn der Grünpfeil in die Ampeleinrichtung integriert wäre und kein rotes Licht leuchten würde. Ein separates Verkehrsschild mit Grünpfeil bedeutet, dass vor dem Abbiegen gehalten werden muss.","So kann der Verkehr beobachtet und bei freier Bahn nach rechts abgebogen werden. Dieses Zeichen signalisiert, dass gehalten werden muss, bevor nach rechts abgebogen werden darf."],"i":["https://video2.kalaiwa.de/assets/1237009.webp"],"rn":376},{"n":"1.2.37-013","t":"Wie verhalten Sie sich?","p":5,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Abbremsen","Weiterfahren"],"co":[1],"ex":["Abbremsen wäre hier riskanter, als bei Gelb zu fahren, da der nachfolgende Verkehr sehr dicht auffährt und wahrscheinlich nicht mit einem Bremsen deinerseits rechnet.","Dein Bremsweg wäre länger, als der Abstand bis zur Ampel. In diesem Fall würdest du erst auf der Kreuzung zum stehen kommen. Deswegen darfst du in diesem Fall weiterfahren."],"v":["https://video4.kalaiwa.de/assets/1237013v1440.mp4"],"rn":377},{"n":"1.2.37-015","t":"Was gilt hier?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Ich darf ungehindert abbiegen","Ich muss in der Kreuzungsmitte anhalten","Ich muss den Gegenverkehr durchfahren lassen"],"co":[0],"ex":["Auf der gegenüberliegenden Straßenseite siehst du am linken Straßeneck eine Ampel mit grünem Linkspfeil. Du darfst hier ungehindert abbiegen.","Du musst nicht in der Mitte der Kreuzung anhalten. Das würde den Verkehrsfluss behindern und ist nicht notwendig.","Wenn für dich der Linksabbiegerpfeil grün leuchtet, kannst du davon ausgehen, dass der Gegenverkehr rot hat. Du musst ihn nicht durchlassen und darfst ungehindert abbiegen."],"i":["https://video4.kalaiwa.de/assets/1237015.webp"],"rn":378},{"n":"1.2.37-017","t":"Wie sollten Sie sich verhalten?","p":5,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Weiterfahren","Abbremsen"],"co":[1],"ex":["Hältst du nicht an, dann riskierst du, die Kreuzung bei Rot zu überqueren und dich und andere Verkehrsteilnehmer zu gefährden.","Dein Abstand zur Ampel ist noch groß genug, um rechtzeitig abbremsen und vor dieser zum Stehen zu kommen."],"v":["https://video4.kalaiwa.de/assets/1237017v1440.mp4"],"rn":379},{"n":"1.2.37-018","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Ich überquere die Kreuzung zügig, da „Gelb“ angezeigt wird","Ich gewähre möglichem Querverkehr die Vorfahrt","Ich warte an der Haltlinie auf die nächste Grünphase"],"co":[1],"ex":["Die Ampel blinkt gelb. Das bedeutet, dass die Ampel momentan nicht schaltet und daher die Verkehrszeichen gelten.","Aufgrund des \"Vorfahrt gewähren\"-Schildes musst du dem Querverkehr den Vorrang lassen.","Hier gelten die Verkehrszeichen, da die Ampeln nicht aktiv sind."],"v":["https://video4.kalaiwa.de/assets/1237018v1440.mp4"],"rn":380},{"n":"1.2.37-019","t":"Unter welchen Umständen dürfen Sie an einer Kreuzung eine rote Ampel überfahren?","p":2,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Unter keinen Umständen","Wenn ein Polizist den Verkehr auf der Kreuzung regelt","Um einem Einsatzfahrzeug mit blauem Blinklicht und Einsatzhorn vorsichtig Platz zu schaffen"],"co":[1,2],"ex":["In bestimmten Situationen kann ein Überfahren erlaubt sein.","Regeln von Polizisten haben immer Vorrang.","Für Einsatzfahrzeuge mit Blaulicht muss prinzipiell Platz geschafft werden. Das darf an Kreuzungen auch durch vorsichtiges Überfahren von roten Ampeln sein."],"rn":381},{"n":"1.2.37-021","t":"Was gilt an dieser ampelgeregelten Kreuzung mit Zusatzzeichen?","p":3,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["- dürfen Radfahrer nach rechts abbiegen, auch wenn die Ampel „Rot“ zeigt","- ist für Radfahrer die Fahrtrichtung nach rechts vorgeschrieben","- dürfen Kraftfahrzeuge nach rechts abbiegen, auch wenn die Ampel „Rot“ zeigt"],"co":[0],"ex":["Auch wenn die Ampel \"Rot\" zeigt, dürfen Fahrradfahrer an dieser Kreuzung rechts abbiegen.","Radfahrer dürfen an dieser Kreuzung möglicherweise auch geradeaus oder nach links abbiegen, müssen dann allerdings, wie alle anderen Verkehrsteilnehmer, warten, bis die Ampel zu \"Grün\" wechselt.","Das Zusatzzeichen gilt nur für Radfahrer. Deshalb dürfen Kraftfahrzeuge nicht bei \"Rot\" abbiegen."],"i":["https://video4.kalaiwa.de/assets/1237021.webp"],"rn":382},{"n":"1.2.37-101","t":"Sie wollen bei „Grün“ nach links abbiegen; links neben Ihnen will eine Straßenbahn geradeaus weiterfahren. Was ist richtig?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Die Straßenbahn muss warten","Gegenseitige Verständigung, weil keine Regel besteht","Sie müssen warten"],"co":[2],"ex":["Der Autofahrer muss warten, die Straßenbahn hat Vorfahrt.","Es gibt eine Regel. Die Straßenbahn hat Vorrang vor dem Fahrzeug.","Die Ampel steht auf Grün. Es erscheint jedoch kein Grünpfeil, welcher zur Vorfahrt gegenüber anderen Verkehrsteilnehmern berechtigt. Steht die Ampel auf \"Grün\", so darf die Haltelinie überfahren werden. Es muss jedoch am Abbiegepunkt gewartet werden um die Straßenbahn passieren zu lassen, bevor man abbiegt."],"rn":383},{"n":"1.2.37-104","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["- jetzt los","- erst los, wenn der Lkw weiterfährt","- erst los, wenn meine Ampel „Grün“ zeigt"],"co":[0],"ex":["Du darfst losfahren, da das rote Ampellicht erloschen ist und du die Kreuzung nicht blockieren würdest, wenn die vordere Ampel nicht direkt grün wird.","Du musst nicht warten, bis der Lkw weiterfährt, da noch genügend Platz hinter ihm ist.","Bei der Ampel handelt es sich um eine Zwei-Phasen-Ampel, die nicht über ein grünes Signal verfügt."],"v":["https://video2.kalaiwa.de/assets/1237104v1440.mp4"],"rn":384},{"n":"1.2.37-002-B","t":"Welches Verhalten ist richtig?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Der grüne Pkw muss warten","Ich darf unter Beachtung der Verkehrszeichen abbiegen","Ich darf erst abbiegen, wenn die Ampel „Grün“ zeigt"],"co":[0,1],"ex":["Der grüne PKW steht vor einer roten Ampel und muss somit warten.","Die Ampel betrifft dich nicht, weil du vor ihr abbiegen möchtest. Hier ist allerdings das \"Vorfahrt gewähren\"-Schild zu beachten, bevor du abbiegst.","Weil sich die Straße, in die du abbiegen möchtest, vor der Ampel befindet, musst du nicht warten, bis diese auf grün schaltet, um abzubiegen."],"i":["https://video2.kalaiwa.de/assets/1237002b.webp"],"rn":385},{"n":"1.2.37-010-M","t":"Wie verhalten Sie sich in dieser Situation?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["An der Sichtlinie anhalten","Die Kreuzung ohne anzuhalten überqueren","An der Haltlinie anhalten"],"co":[1],"ex":["Wenn die Ampel nicht eingeschaltet wäre, müsstest du zuerst an der Haltlinie beim Stoppschild anhalten und dich dann bis zur Sichtlinie in die Kreuzung vortasten.","Die Ampel zeigt für dich grün. Deswegen kannst du, ohne anzuhalten, die Kreuzung überqueren.","An der Haltlinie müsstest du anhalten, wenn die Ampel nicht eingeschaltet wäre. Dann müsstest du dich an die Verkehrszeichen halten. In deinem Fall wäre das ein \"Stoppschild\"."],"i":["https://video4.kalaiwa.de/assets/1237010m.webp"],"rn":386},{"n":"1.2.37-011-M","t":"Wo müssen Sie warten?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["An der Sichtlinie","In Höhe der Ampel","An der Haltlinie"],"co":[2],"ex":["Würde die Ampel nicht eingeschaltet sein, dann müsstest du dich am \"Stoppschild\" orientieren. Das bedeutet, zunächst an der Haltlinie zu halten und dich dann bis zur Sichtlinie vorzutasten. Die Sichtlinie ist eine imaginäre Linie, ab der du eine bessere Einsicht auf die Kreuzung hast, als von der Haltlinie aus.","Du musst an der Haltlinie warten, bis die Ampel umschaltet.","Du musst an der Haltlinie warten, bis die Ampel auf \"grün\" umschaltet."],"i":["https://video2.kalaiwa.de/assets/1237011m.webp"],"rn":387},{"n":"1.2.37-012-M","t":"Was gilt hier?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Linksabbieger dürfen fahren","Rechtsabbieger dürfen fahren","Geradeausfahrer dürfen fahren"],"co":[1],"ex":["Linksabbieger müssen warten, da die Ampel für sie rot ist.","Für Rechtsabbieger ist die Ampel grün.","Geradeausfahrer haben rot und müssen warten."],"i":["https://video4.kalaiwa.de/assets/1237012m.webp"],"rn":388},{"n":"1.2.37-020-M","t":"An dieser Ampel mit Grünpfeilschild möchten Sie jetzt nach rechts abbiegen. Wie verhalten Sie sich richtig?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Ich halte zunächst an der Haltlinie an","Ich schließe eine Behinderung anderer Verkehrsteilnehmer aus","Ich biege ohne anzuhalten mit Schrittgeschwindigkeit ab"],"co":[0,1],"ex":["Die Ampel ist rot. Deshalb musst du zunächst an der Haltlinie anhalten. Erst wenn eine Gefährdung oder Behinderung anderer Verkehrsteilnehmer ausgeschlossen ist, darfst du weiter fahren. Es gilt dasselbe Prinzip wie bei einem Stoppschild.","Bei einem Grünpfeilschild, ist es erlaubt eine rote Ampel zu überqueren, sofern du zuerst an der Haltlinie angehalten hast und dich versichert hast, dass der Weg frei ist. Hast du ausgeschlossen, dass du andere Verkehrsteilnehmer behindern könntest, darfst du abbiegen.","Da die Ampel rot ist, musst du zuerst an der Haltlinie anhalten. Erst danach, wenn du niemanden behinderst, kannst du langsam abbiegen."],"i":["https://video4.kalaiwa.de/assets/1237020m.webp"],"rn":389},{"n":"1.2.37-022-M","t":"Die Ampel zeigt schon längere Zeit „Grün“ für Ihre Richtung. Wie verhalten Sie sich jetzt richtig?","p":3,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Ich beobachte die Ampel aufmerksam","Ich fahre bremsbereit weiter, da die Ampel auf „Gelb“ umschalten kann","Ich beschleunige, um die Kreuzung noch sicher bei „Grün“ überqueren zu können"],"co":[0,1],"ex":["Beobachte die Ampel aufmerksam, um rechtzeitig bremsen zu können, falls sie jetzt auf Gelb schaltet.","Da die Ampel schon lange grün ist, ist die Wahrscheinlichkeit hoch, dass sie jeden Moment auf Gelb schaltet. Fahre bremsbereit weiter, weil du anhalten musst, falls sie auf Gelb schaltet.","Du darfst jetzt nicht beschleunigen, weil hier maximal 30 km/h erlaubt sind."],"v":["https://video2.kalaiwa.de/assets/1237022mv1440.mp4"],"rn":390},{"n":"1.2.37-102-B","t":"Sie haben sich versehentlich rechts eingeordnet, obwohl Sie nach links abbiegen möchten. Wie dürfen Sie weiterfahren?","p":4,"c":"1.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Nach links, sobald die Ampel dafür „Grün“ zeigt","Geradeaus","Nach rechts"],"co":[1,2],"ex":["Aufgrund der durchgezogenen Linie darfst du den Fahrstreifen nicht mehr wechseln.","Da links von dir eine durchgezogene Linie ist, darfst du nicht mehr auf den linken Abbiegestreifen wechseln.","Die Pfeile auf deiner Fahrspur zeigen nach geradeaus und rechts. Du darfst nur in diese beiden Richtungen fahren und aufgrund der durchgezogenen Linie nicht mehr auf den linken Abbiegestreifen wechseln."],"i":["https://video4.kalaiwa.de/assets/1237102b.webp"],"rn":391},{"n":"1.2.38-003","t":"Wovor kann gelbes Blinklicht auf einem Fahrzeug warnen?","p":3,"c":"1.2.38","ch":"Blaues Blinklicht Und Gelbes Blinklicht","th":"Verhalten Im Strassenverkehr","o":["Vor einem Fahrzeug mit ungewöhnlicher Breite","Vor Gefahren an einer Arbeits- oder Unfallstelle","Vor einem langsam fahrenden Großraumtransport"],"co":[0,1,2],"ex":["Es ist eine Verwendung möglich, um vor Fahrzeugen mit ungewöhnlicher Breite oder Länge zu warnen. Diesen fällt es nämlich in der Regel schwerer Fahrbahnbegrenzungen einzuhalten. Auch ein Risiko, dass diese Fahrzeuge in der Kurve weit ausscheren besteht. Daher kommt hier das gelbe Blinklicht zum Einsatz, damit andere Verkehrsteilnehmer gewarnt sind.","Das gelbe Blinklicht auf einem Fahrzeug warnt vor einer Gefahr. Es kann ortsfest oder von Fahrzeugen aus verwendet werden. Es darf verwendet werden, um vor Arbeits- oder Unfallstellen zu warnen.","Ein gelbes Blinklicht kann vor Fahrzeugen mit ungewöhnlich breiter oder langer Ladung zu warnen. Dies ist oft bei Großraumtransporten der Fall."],"rn":392},{"n":"1.2.38-101","t":"Was kann es bedeuten, wenn an einem Fahrzeug blaues Blinklicht - jedoch kein Einsatzhorn - eingeschaltet ist?","p":3,"c":"1.2.38","ch":"Blaues Blinklicht Und Gelbes Blinklicht","th":"Verhalten Im Strassenverkehr","o":["Ein Abschleppwagen fährt zu einem Einsatz","An einer Unfallstelle wird vor Gefahren gewarnt","Es wird vor einer Einsatzstelle der Feuerwehr gewarnt"],"co":[1,2],"ex":["Abschleppwägen verwenden keine blauen Blinklichter, wenn sie zum Einsatz fahren.","Das ohne Martinshorn eingeschaltete Blaulicht hat eine reine Warnfunktion. Es wird zum Beispiel eingesetzt, um an Unfallstellen vor einer Gefahr zu warnen. So wissen andere Verkehrsteilnehmer bereits von weitem, dass sie an dieser Stelle vorsichtig vorbei fahren müssen.","Das blaue Blinklicht kann bei einem Feuerwehreinsatz dazu genutzt werden, andere Verkehrsteilnehmer zu warnen."],"rn":393},{"n":"1.2.38-102","t":"Welche Bedeutung kann das blaue Blinklicht allein (ohne Einsatzhorn) haben?","p":3,"c":"1.2.38","ch":"Blaues Blinklicht Und Gelbes Blinklicht","th":"Verhalten Im Strassenverkehr","o":["Ohne Einsatzhorn hat das blaue Blinklicht keine Bedeutung","Ankündigung eines geschlossenen Verbandes","Das Fahrzeug befindet sich auf einer Einsatzfahrt. Sie sollten ihm Platz machen"],"co":[1,2],"ex":["Das blaue Blinklicht hat auch ohne Einsatzhorn eine Bedeutung. Das Einsatzhorn kann aus taktischen Gründen, oder um die Lärmbelästigung in der Nacht zu minimieren, ausgeschaltet sein.","Um einen geschlossenen Verband zu begleiten, wird das blaue Blinklicht eingeschaltet.","Auch ohne Einsatzhorn (Martinshorn), aber mit eingeschaltetem blauen Blinklicht kann sich das Fahrzeug in einem Einsatz befinden. In diesem Fall hat das Einsatzfahrzeug zwar kein Wegerecht, du solltest ihm aber trotzdem Platz machen."],"rn":394},{"n":"1.2.38-104","t":"Hinter Ihnen fährt ein Rettungswagen mit blauem Blinklicht und Einsatzhorn. Wie verhalten Sie sich?","p":4,"c":"1.2.38","ch":"Blaues Blinklicht Und Gelbes Blinklicht","th":"Verhalten Im Strassenverkehr","o":["Ich schaffe, ohne andere zu gefährden, sofort freie Bahn","Nach dem Umschalten der Ampel auf „Grün“ schaffe ich sofort freie Bahn","Ich fordere den Fahrer im Fahrzeug neben mir auf, sofort freie Bahn zu schaffen"],"co":[0],"ex":["So kann der Rettungswagen schnellstmöglich vorbeifahren.","Unabhängig von der Ampelschaltung muss dem Rettungswagen unverzüglich der Weg frei gemacht werden, ohne hierbei andere Verkehrsteilnehmer zu gefährden.","Nähert sich ein Rettungswagen im Einsatz, dann muss diesem schnellstmöglich freie Bahn gewährt werden."],"v":["https://video2.kalaiwa.de/assets/1238104v1440.mp4"],"rn":395},{"n":"1.3.01-001","t":"An welchen Stellen ohne vorfahrtregelnde Verkehrszeichen gilt die Regel „rechts vor links“?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["An Straßenkreuzungen und -einmündungen","An Grundstücksausfahrten","Am Ende eines verkehrsberuhigten Bereiches"],"co":[0],"ex":["Die Regel „Rechts-vor-Links“ gilt grundsätzlich an allen Kreuzungen und Einmündungen, an denen sonst keine verkehrsregelnden Zeichen (Schilder oder Ampeln) angebracht sind und die Vorfahrt nicht durch Polizeibeamte geregelt wird.","An Grundstücksausfahrten gilt die Regel „Rechts-vor-Links“ nicht. Hier muss derjenige, der vom Grundstück auf die Fahrbahn fährt so lange warten, bis alle anderen Fahrzeuge vorbei gefahren sind und die Fahrbahn wieder frei ist. Dann ist er an der Reihe.","Den aus dem verkehrsberuhigten Bereich ausfahrenden Verkehrsteilnehmern kommt eine besondere Sorgfaltspflicht zu. Darum gilt für sie an einer solchen Stelle nicht die Regelung „Rechts-vor-Links“. Sie müssen in aller Regel den Vorrang aller anderen Verkehrsteilnehmer beachten."],"rn":396},{"n":"1.3.01-002","t":"An welchen Stellen ohne vorfahrtregelnde Verkehrszeichen gilt die Regel „rechts vor links“?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["An Straßenkreuzungen und -einmündungen","Wo Feld- oder Waldwege in eine andere Straße münden","An Einmündungen mit abgesenktem Bordstein"],"co":[0],"ex":["Wenn keine Verkehrszeichen, Ampeln oder Polizisten den Verkehr regeln, gilt generell die Regel \"rechts vor links\".","Feld- und Waldwege sind i.d.R. keine befestigten Straßen, sondern vielmehr Schotterwege, auf denen auch nicht schnell gefahren werden kann. Die Bezeichnung \"Weg\" deutet schon an, dass es sich dabei um keine gleichberechtigte Straße handelt. Entsprechend gilt die Regel \"rechts vor links\" hier nicht.","Einmündungen mit abgesenktem Bordstein sind keine gleichberechtigten Straßen. Meist handelt es sich dabei um Ein- oder Ausfahrten zu Privatgrundstücken. Daher gilt hier die Regel \"rechts vor links\" nicht."],"rn":397},{"n":"1.3.01-003","t":"Sie kommen an eine Kreuzung, an der Sie die Vorfahrtlage nicht gleich überblicken. Wie verhalten Sie sich?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Nach der Regel „rechts vor links“ fahren","Warten, beobachten und sich gegebenenfalls mit anderen verständigen","Als Geradeausfahrer immer durchfahren"],"co":[1],"ex":["Wenn du dir über die Vorfahrtslage nicht im Klaren bist, kannst du dir nicht einfach eine Vorfahrtsregel aussuchen, da diese der an der Kreuzung tatsächlich geltenden Regelung widersprechen könnte. Versuche Kontakt mit den anderen Verkehrsteilnehmern aufzunehmen und gewähre ihnen gegebenenfalls die Vorfahrt.","Da du die Vorfahrtslage nicht überblicken und somit evtl. die Vorfahrt eines anderen Verkehrsteilnehmers missachten könntest, ist es in einem solchen Fall richtig, zu warten, zu beobachten und sich, wenn notwendig, mit anderen, zu verständigen.","Du kannst als Geradeausfahrer erst durch die Kreuzung durchfahren, sobald klar ist, dass du keinem anderen Verkehrsteilnehmer die Vorfahrt gewähren musst."],"rn":398},{"n":"1.3.01-052","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich verzichte auf meine Vorfahrt, um die Kreuzung nicht zu verstopfen","Ich darf vor der Radfahrerin links abbiegen","Ich muss die Radfahrerin durchfahren lassen"],"co":[0,2],"ex":["In der Straße steht ein Müllauto. Würdest du vor dem grünen PKW links abbiegen, dann würdest du die Kreuzung verstopfen. Verzichte daher auf die Vorfahrt und lass den grünen PKW zuerst fahren.","Die Radfahrerin darf vor dir geradeaus fahren.","Die Radfahrerin möchte geradeaus weiterfahren, du hingegen nimmst eine Richtungsänderung vor und musst dabei ihre Fahrbahn kreuzen. Deswegen hat die Radfahrerin Vorfahrt vor dir."],"i":["https://video2.kalaiwa.de/assets/1301052.webp"],"rn":399},{"n":"1.3.01-053","t":"Sie möchten nach rechts in eine Vorfahrtstraße einbiegen. Worauf müssen Sie achten?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Nur auf die von links kommenden Fahrzeuge","Auf von links und von rechts kommende Fahrzeuge","Auf Radfahrer und Fußgänger, die rechts neben oder noch hinter Ihnen sind"],"co":[1,2],"ex":["Du musst auf beiderseitigen Verkehr achten und dich vergewissern, dass keine Radfahrer oder Fußgänger neben oder hinter dir sind, wenn du abbiegst.","Die Fahrzeuge auf der Vorfahrtsstraße haben Vorrang vor dir. Auf einer Vorfahrtsstraße darf auch überholt werden, daher musst du auch nach rechts schauen.","Vor dem Abbiegen musst du dich vergewissern, dass du hierdurch keine Fußgänger oder Radfahrer gefährdest."],"rn":400},{"n":"1.3.01-112","t":"Sie wollen nach links abbiegen. Wer muss warten?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Das blaue Fahrzeug muss warten","Ich muss warten"],"co":[1],"ex":["Das blaue Fahrzeug hat Vorrang. Du musst mit dem Abbiegen warten, bis es vorbeigefahren ist.","Du möchtest aus einem Feldweg auf eine Vorfahrtsstraße fahren, deshalb musst du warten."],"i":["https://video2.kalaiwa.de/assets/1301112.webp"],"rn":401},{"n":"1.3.01-113","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss warten","Der Radfahrer muss warten"],"co":[0],"ex":["Aufgrund des \"Vorfahrt gewähren\"-Schildes musst du warten und dem Radfahrer den Vorrang lassen.","Der Radfahrer hat Vorfahrt und du musst warten."],"i":["https://video4.kalaiwa.de/assets/1301113.webp"],"rn":402},{"n":"1.3.01-116","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den Radfahrer durchfahren lassen","Der blaue Lkw darf zuerst fahren","Ich darf vor dem Radfahrer abbiegen"],"co":[0],"ex":["Der Radfahrer fährt vor dir und hat daher Vorrang.","An dieser Kreuzung herrscht die Verkehrsgrundregel \"rechts vor links\". Daher hast du Vorfahrt vor dem LKW.","Du darfst nicht vor dem Radfahrer abbiegen. Er fährt vor dir und hat daher Vorrang. Außerdem würdest du ihn dadurch gefährden."],"i":["https://video2.kalaiwa.de/assets/1301116.webp"],"rn":403},{"n":"1.3.01-119","t":"Sie möchten eine Vorfahrtstraße überqueren. Die Sicht nach beiden Seiten ist durch parkende Fahrzeuge stark eingeschränkt. Wie verhalten Sie sich?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich warne den kreuzenden Verkehr durch Hupen","Ich taste mich vorsichtig in die Kreuzung hinein","Ich überquere die Kreuzung zügig"],"co":[1],"ex":["Die Hupe darf innerorts nur als Warnsignal genutzt werden, um auf ein unmittelbares Risiko für dich oder andere Verkehrsteilnehmer aufmerksam zu machen. In diesem Fall musst du dich langsam und vorsichtig an die Kreuzung herantasten, bis du sie einsehen kannst.","Ist die Verkehrslage schwer abzuschätzen, musst du dich vorsichtig in die Kreuzung hineintasten. Aufgrund der parkenden Fahrzeuge kannst du vom übrigen Verkehr auch erst spät erkannt werden.","Du musst langsam an die Kreuzung heranfahren und darfst diese erst überqueren, wenn du Einsicht in den Querverkehr und Fußgänger hast und ein sicheres Überkreuzen gewährleistet ist."],"rn":404},{"n":"1.3.01-007-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den Radfahrer durchfahren lassen","Ich muss den Motorradfahrer durchfahren lassen","Ich darf vor dem Radfahrer abbiegen"],"co":[0,1],"ex":["Du musst die geradeaus fahrenden Verkehrsteilnehmer durchfahren lassen, bevor du links abbiegen darfst.","An dieser Kreuzung gilt die Grundregel \"rechts vor links\". Deswegen musst du den Motorradfahrer durchfahren lassen, bevor du nach links abbiegen darfst.","Du musst mit dem Abbiegen warten, bis sowohl der Radfahrer, als auch der Motorradfahrer die Kreuzung passiert haben. Erst dann darfst du abbiegen."],"i":["https://video2.kalaiwa.de/assets/1301007m.webp"],"rn":405},{"n":"1.3.01-013-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf als Erster die Kreuzung überqueren","Ich muss den roten Lkw abbiegen lassen","Ich muss den Radfahrer abbiegen lassen"],"co":[0],"ex":["Weil du rechts vom LKW stehst, darfst du als Erster die Kreuzung überqueren.","Der rote LKW muss dir den Vorrang lassen.","Der Radfahrer muss aufgrund der Grundregel \"rechts vor links\" den roten LKW durchfahren lassen, der wiederum dir die Vorfahrt gewähren muss."],"i":["https://video4.kalaiwa.de/assets/1301013m.webp"],"rn":406},{"n":"1.3.01-016-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den Traktor abbiegen lassen","Der blaue Lkw muss mich durchfahren lassen","Ich muss den blauen Lkw durchfahren lassen"],"co":[0,2],"ex":["Du musst den Traktor abbiegen lassen,weil du dich an das \"Vorfahrt gewähren\"-Schild halten musst.","Du musst den LKW durchfahren lassen.","Aufgrund des Verkehrszeichens \"Vorfahrt gewähren\" musst du dem blauen LKW den Vorrang lassen."],"i":["https://video2.kalaiwa.de/assets/1301016m.webp"],"rn":407},{"n":"1.3.01-017-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den Bus durchfahren lassen","Ich muss das Motorrad durchfahren lassen","Ich fahre vor dem Bus"],"co":[1,2],"ex":["Du hast Vorfahrt an dieser Kreuzung und darfst daher vor dem Bus fahren.","Weil der Motorradfahrer geradeaus weiterfahren möchte, du aber abbiegen willst, musst du ihn durchfahren lassen, bevor du abbiegst.","An dieser Kreuzung hast du Vorfahrt vor dem Querverkehr und kannst somit vor dem Bus abbiegen."],"i":["https://video2.kalaiwa.de/assets/1301017m.webp"],"rn":408},{"n":"1.3.01-018-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den Bus durchfahren lassen","Ich fahre vor dem Bus","Ich muss das Motorrad durchfahren lassen"],"co":[1,2],"ex":["Der Bus muss dich durchfahren lassen.","Weil der Bus abbiegen will, du aber geradeaus weiterfahren möchtest, darfst du fahren und er muss warten.","Aufgrund des \"Vorfahrt gewähren\"-Schildes musst du dem Querverkehr den Vorrang lassen."],"i":["https://video2.kalaiwa.de/assets/1301018m.webp"],"rn":409},{"n":"1.3.01-021-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["- vor dem gelben Pkw abbiegen","- erst nach dem Motorrad abbiegen","- als Erster abbiegen"],"co":[0,1],"ex":["Du darfst vor dem gelben PKW abbiegen, da du dich auf der Vorfahrtsstraße befindest und er dir Vorfahrt gewähren muss.","Da du nach links von der Vorfahrtsstraße abbiegst und somit eine Querung der Gegenverkehrsseite notwendig ist, musst du den Gegenverkehr, den Motorradfahrer zuerst abbiegen lassen, bevor du fahren kannst.","Du darfst abbiegen, sobald der Motorradfahrer durchgefahren und die Fahrbahn frei ist."],"i":["https://video2.kalaiwa.de/assets/1301021m.webp"],"rn":410},{"n":"1.3.01-034-M","t":"Wie verhalten Sie sich hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich biege vor dem gelben Fahrzeug ab","Ich biege vor dem roten Pkw ab","Ich lasse das gelbe Fahrzeug durchfahren"],"co":[2],"ex":["Das gelbe Fahrzeug darf vor dir fahren, denn der Gegenverkehr hat Vorrang.","Das rote Fahrzeug hat Vorfahrt, da es sich auf der Vorfahrtstraße befindet.","Das gelbe Fahrzeug befindet sich im Gegenverkehr und hat damit Vorrang."],"i":["https://video4.kalaiwa.de/assets/1301034m.webp"],"rn":411},{"n":"1.3.01-035-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den roten Pkw vorbeilassen","Ich lasse den grünen Pkw durchfahren","Ich biege vor dem grünen Pkw links ab"],"co":[1],"ex":["Der rote PKW muss dich vorbeilassen, weil an dieser Kreuzung die Grundregel \"rechts vor links\" gilt.","Hier sind keine Verkehrszeichen, Ampeln oder Polizeibeamte, die den Verkehr regeln. Daher gilt im Falle dieser Kreuzung die Grundregel \"rechts vor links\".","Du musst zuerst den grünen PKW durchfahren lassen. Dann kannst du, wenn du dir sicher bist, dass der rote PKW-Fahrer dich wahrgenommen hat, nach links abbiegen."],"i":["https://video4.kalaiwa.de/assets/1301035m.webp"],"rn":412},{"n":"1.3.01-038-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss das Motorrad durchfahren lassen","Ich darf vor dem blauen Pkw fahren","Ich muss den blauen Pkw durchfahren lassen"],"co":[0,2],"ex":["Das Verkehrszeichen bedeutet \"Vorfahrt gewähren\". Zudem zeigt es eine abknickende Vorfahrtsstraße, auf der sich der Motorradfahrer befindet. Du musst den Motorradfahrer also durchfahren lassen.","Du darfst nicht vor dem blauen PKW fahren. Ihr befindet euch beide auf \"untergeordneten\" Straßen. Somit gilt die Grundregel \"rechts vor links\".","Der blaue PKW befindet sich ebenfalls auf einer \"untergeordneten\" Straße und somit gilt die Regel \"rechts vor links\"."],"i":["https://video4.kalaiwa.de/assets/1301038m.webp"],"rn":413},{"n":"1.3.01-039-M","t":"Wer darf hier zuerst fahren?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Der rote Lkw","Der Elektroroller","Ich"],"co":[1],"ex":["Der rote Lkw biegt links auf die Vorfahrtstraße ab und darf deshalb als Letztes fahren.","Der Elektroroller folgt der Vorfahrtstraße und hat somit Vorfahrt.","Du verlässt durch das Linksabbiegen die Vorfahrtstraße. Du darfst nach dem Elektroroller abbiegen."],"i":["https://video2.kalaiwa.de/assets/1301039m.webp"],"rn":414},{"n":"1.3.01-040-M","t":"Welches Verhalten ist hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf vor dem roten Pkw fahren","Ich darf vor dem grünen Pkw fahren","Der grüne Pkw darf vor dem roten Pkw fahren"],"co":[2],"ex":["Auch wenn du geradeaus fahren willst, darfst du nicht vor dem roten, abbiegenden Pkw fahren, sondern musst Vorfahrt gewähren.","Du darfst nicht vor dem grünen Pkw fahren, sondern musst Vorfahrt gewähren und anhalten.","Sowohl der grüne als auch der rote Pkw wollen links abbiegen. In dieser Situation darf der grüne Pkw zuerst fahren, da er auf der Vorfahrtstraße bleibt. Der rote Pkw muss hingegen warten, da er die Vorfahrtstraße verlassen will."],"i":["https://video2.kalaiwa.de/assets/1301040m.webp"],"rn":415},{"n":"1.3.01-041-M","t":"Welches Verhalten ist hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf vor dem gelben Pkw fahren","Ich darf vor dem roten Pkw fahren","Der gelbe Pkw darf vor dem roten Pkw fahren"],"co":[1,2],"ex":["Da der gelbe Pkw weiterhin auf der Vorfahrtstraße bleibt und du diese verlässt, hat er Vorrang und darf zuerst abbiegen.","Du hast Vorrang vor dem roten Pkw, da du auf einer Vorfahrtstraße fährst.","Der rote Pkw muss dem gelben Pkw Vorfahrt gewähren. Dieser darf daher zuerst abbiegen, da er sich auf einer Vorfahrtstraße befindet."],"i":["https://video4.kalaiwa.de/assets/1301041m.webp"],"rn":416},{"n":"1.3.01-042-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Die Straßenbahn muss mich vorher abbiegen lassen","Ich muss das Motorrad durchfahren lassen","Ich muss die Straßenbahn durchfahren lassen"],"co":[1,2],"ex":["Du musst die Straßenbahn durchfahren lassen.","Weil du deine Fahrtrichtung änderst, musst du den Motorradfahrer zunächst durchfahren lassen und darfst erst abbiegen, wenn die Fahrbahn frei ist.","Aufgrund des \"Vorfahrt gewähren\"-Schildes musst du der Straßenbahn den Vorrang lassen."],"i":["https://video4.kalaiwa.de/assets/1301042m.webp"],"rn":417},{"n":"1.3.01-043-M","t":"Welches Verhalten ist hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Das Motorrad darf vor dem gelben Pkw fahren","Ich darf vor dem gelben Pkw fahren","Ich darf vor dem Motorrad fahren"],"co":[0,1],"ex":["Das Motorrad befindet sich auf einer abknickenden Vorfahrtstraße und darf deswegen vor dem gelben Pkw abbiegen.","Weder du, noch der gelbe Pkw fahren auf einer Vorfahrtstraße. Entsprechend der \"rechts-vor-links\"-Regelung an Kreuzungen darfst du zuerst geradeaus fahren, da du rechts von dem gelben Pkw aus einer Straße kommst.","Obwohl du geradeaus fahren willst und das Motorrad abbiegen möchte, musst du ihm Vorfahrt gewähren. Das rote \"Vorfahrt achten\" Zeichen mit dem Zusatzschild der abknickenden Vorfahrtstraße zeigt dir, dass du keine Vorfahrt hast."],"i":["https://video4.kalaiwa.de/assets/1301043m.webp"],"rn":418},{"n":"1.3.01-044-M","t":"Welches Verhalten ist hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf als Erster fahren","Ich muss den Radfahrer durchfahren lassen","Ich muss den roten Pkw abbiegen lassen"],"co":[0],"ex":["Du darfst hier als Erster fahren, da hier keine Ampel oder Verkehrszeichen die Vorfahrt regeln und somit die Regel \"Rechts-vor-Links\" gilt.","Du musst den Radfahrer nicht durchfahren lassen, weil du gemäß der \"Rechts-vor-Links\" Regelung Vorfahrt hast. Sei trotzdem aufmerksam und beobachte, ob er bremst.","Du musst den roten Pkw nicht abbiegen lassen. Er darf als letzter fahren, nachdem du und der Radfahrer durchgefahren seid."],"i":["https://video4.kalaiwa.de/assets/1301044m.webp"],"rn":419},{"n":"1.3.01-045-M","t":"Welches Verhalten ist hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den blauen Lkw durchfahren lassen","Ich muss den gelben Pkw durchfahren lassen","Ich darf vor dem gelben Pkw fahren"],"co":[0,1],"ex":["Beim Linksabbiegen hat der Gegenverkehr Vorrang. Du musst den blauen Lkw durchfahren lassen.","Du musst dem gelben Pkw Vorfahrt gewähren.","Der gelbe Pkw hat Vorfahrt und darf zuerst fahren."],"i":["https://video4.kalaiwa.de/assets/1301045m.webp"],"rn":420},{"n":"1.3.01-046-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den blauen Pkw durchfahren lassen","Ich darf durchfahren"],"co":[1],"ex":["Der blaue PKW muss dich durchfahren lassen, weil du Vorfahrt hast.","Du befindest dich auf der Vorfahrtsstraße und darfst daher vor dem blauen PKW durchfahren. Das Abbiegen musst du durch ein Blinken kennzeichnen."],"i":["https://video4.kalaiwa.de/assets/1301046m.webp"],"rn":421},{"n":"1.3.01-047-M","t":"Welches Verhalten ist hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["- den roten Pkw durchfahren lassen","- den blauen Pkw durchfahren lassen","- an der Haltlinie anhalten"],"co":[1,2],"ex":["Zwischen dir und dem roten Pkw gilt Rechts-vor-Links, weil ihr beide von einer Nebenstraße auf die Vorfahrtsstraße einbiegt.","Du fährst auf eine abbiegende Vorfahrtsstraße zu. Da du von einer Nebenstraße kommst, musst du den blauen Pkw, der die Vorfahrtsstraße verlässt, durchfahren lassen.","Bei einem Stoppschild musst du an der Haltlinie anhalten."],"i":["https://video2.kalaiwa.de/assets/1301047m.webp"],"rn":422},{"n":"1.3.01-048-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich lasse das Motorrad vor mir abbiegen","Ich fahre als Erster","Ich lasse den blauen Pkw abbiegen"],"co":[2],"ex":["Der Motorradfahrer muss dich durchfahren lassen, bevor er abbiegt, weil er die Fahrtrichtung ändert und du als Geradeausfahrer Vorrang hast.","Du musst zuerst den blauen PKW abbiegen lassen, bevor du fährst.","In diesem Fall gilt \"rechts vor links\" und du musst den blauen PKW abbiegen lassen."],"i":["https://video4.kalaiwa.de/assets/1301048m.webp"],"rn":423},{"n":"1.3.01-049-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf als Erster fahren","Ich muss den roten Pkw vorlassen","Ich muss die Straßenbahn vorlassen"],"co":[0],"ex":["Du bist auf der Vorfahrtsstraße und darfst deswegen als erster fahren.","Da du dich auf der Vorfahrtsstraße befindest, muss dir der Querverkehr die Vorfahrt gewähren.","Für den Straßenbahnfahrer gilt in diesem Fall das gleiche, wie für die anderen Verkehrsteilnehmer. Da du dich auf der Vorfahrtsstraße befindest, hast du Vorfahrt."],"i":["https://video4.kalaiwa.de/assets/1301049m.webp"],"rn":424},{"n":"1.3.01-050-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf durchfahren","Ich muss dem grünen Pkw Vorfahrt gewähren","Ich muss dem blauen Pkw Vorfahrt gewähren"],"co":[0],"ex":["Du befindest dich auf der Vorfahrtsstraße und darfst deshalb durchfahren.","Weil der grüne PKW die Vorfahrtsstraße verlässt, muss er warten, bis du durchgefahren bist, um abzubiegen.","Der blaue PKW befindet sich nicht auf einer Vorfahrtsstraße und muss dir deshalb Vorfahrt gewähren."],"i":["https://video4.kalaiwa.de/assets/1301050m.webp"],"rn":425},{"n":"1.3.01-051-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich lasse den Traktor abbiegen","Ich lasse die Straßenbahn durchfahren","Ich fahre als Erster"],"co":[1],"ex":["Das Verkehrsschild mit dem gelben Viereck bedeutet, dass du dich auf einer Vorfahrtsstraße befindest. Der Traktor möchte auf diese Vorfahrtsstraße wechseln und muss dir demnach den Vorrang lassen.","Du musst der Straßenbahn Vorrang gewähren, da diese auf einer Vorfahrtsstraße fährt, ihre Richtung nicht ändert und du nach links abbiegen möchtest.","Du darfst nicht als Erster fahren, da du mit deinem Fahrzeug nach links abbiegen willst und der Straßenbahn Vorrang gewähren musst."],"i":["https://video2.kalaiwa.de/assets/1301051m.webp"],"rn":426},{"n":"1.3.01-056-M","t":"Wie verhalten Sie sich richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["- vor den beiden Pkws","- nach dem blauen Pkw","- nach den beiden Pkws"],"co":[0],"ex":["Du hast hier Vorfahrt. Somit darfst du vor beiden PKWs fahren.","Du hast Vorrang vor dem blauen PKW.","Du darfst vor den beiden PKWs links abbiegen."],"i":["https://video4.kalaiwa.de/assets/1301056m.webp"],"rn":427},{"n":"1.3.01-057-M","t":"Wie verhalten Sie sich richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf vor dem blauen Lkw fahren","Ich muss den roten Pkw durchfahren lassen","Ich darf erst nach dem blauen Lkw fahren"],"co":[0,1],"ex":["Weil du dich auf der Vorfahrtsstraße befindest, hast du Vorrang vor dem blauen LKW und er muss warten.","Weil du von der Vorfahrtsstraße abfahren willst, musst du den Fahrzeugen, die darauf bleiben, den Vorrang lassen.","Du hast Vorfahrt vor dem blauen LKW."],"i":["https://video4.kalaiwa.de/assets/1301057m.webp"],"rn":428},{"n":"1.3.01-058-M","t":"Was gilt in dieser Situation?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Das Motorrad muss warten","Ich muss links blinken","Ich muss das Motorrad zuerst fahren lassen"],"co":[2],"ex":["Der Motorradfahrer hat Vorfahrt und du musst warten, weil du von der Vorfahrtsstraße abfahren willst.","Weil du geradeaus und nicht links fahren möchtest, musst du auch nicht links blinken.","Weil du von der Vorfahrtsstraße abfahren willst, musst du den Motorradfahrer, der darauf bleiben möchte, zuerst durchfahren lassen, bevor du fahren kannst."],"i":["https://video4.kalaiwa.de/assets/1301058m.webp"],"rn":429},{"n":"1.3.01-059-M","t":"Wer darf zuerst fahren?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Der grüne Traktor","Ich","Der rote Pkw"],"co":[1],"ex":["Der Traktor darf nach dir fahren. Er muss warten, bis du durchgefahren bist, weil er von der Vorfahrtsstraße abfahren möchte, auf der du bleiben willst.","Weil du auf der Vorfahrtsstraße bist und bleiben möchtest, hast du sowohl vor dem PKW, als auch vor dem Traktor Vorrang.","Der rote PKW darf als letzter fahren. Er befindet sich nicht auf der Vorfahrtsstraße und muss deshalb die Vorfahrt gewähren."],"i":["https://video2.kalaiwa.de/assets/1301059m.webp"],"rn":430},{"n":"1.3.01-060-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss warten","Der gelbe Pkw muss warten","Ich muss blinken"],"co":[1,2],"ex":["Es gilt rechts vor links. Somit hast du Vorfahrt und musst nicht warten.","Hier gilt rechts vor links, somit muss der gelbe Pkw warten.","Eine Fahrtrichtungsänderung musst du immer frühzeitig durch Blinken anzeigen."],"i":["https://video2.kalaiwa.de/assets/1301060m.webp"],"rn":431},{"n":"1.3.01-103-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss warten","Das Motorrad muss warten"],"co":[0],"ex":["Hier gilt die Grundregel \"rechts vor links\". Daher musst du warten und dem Motorradfahrer die Vorfahrt gewähren.","Du musst warten und Vorfahrt gewähren."],"i":["https://video2.kalaiwa.de/assets/1301103m.webp"],"rn":432},{"n":"1.3.01-114-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Der blaue Pkw muss mich abbiegen lassen","Ich muss den blauen Pkw durchfahren lassen","Ich muss den Radfahrer abbiegen lassen"],"co":[1,2],"ex":["Der blaue PKW hat Vorrang.","Aufgrund der Grundregel \"rechts vor links\" musst du den blauen PKW durchfahren lassen und warten.","Der Radfahrer hat Vorrang vor dir, daher musst du mit dem Abbiegen warten."],"i":["https://video2.kalaiwa.de/assets/1301114m.webp"],"rn":433},{"n":"1.3.01-117-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["- den Bus durchfahren lassen","- den Radfahrer durchfahren lassen","- an der Haltlinie anhalten"],"co":[0,1,2],"ex":["Weil du deine Fahrtrichtung ändern möchtest und hierzu die Fahrbahn des Gegenverkehrs queren musst, musst du den Bus durchfahren lassen, bevor du abbiegen darfst.","Am rechten Straßenrand steht ein \"Stoppschild\". Dieses signalisiert dir, an der Haltlinie anzuhalten und dem Querverkehr die Vorfahrt zu gewähren. Deswegen musst du die Radfahrerin durchfahren lassen.","Das \"Stoppschild\" schreibt vor, dass du an der Haltlinie anhalten musst. In diesem Fall ist hier das Verkehrsgeschehen gut einsehbar. Wäre dies nicht der Fall, dann müsstest du dich nach dem Halten an der Haltlinie bis zur Sichtlinie an die Kreuzung herantasten, um das Verkehrsgeschehen einschätzen zu können."],"i":["https://video4.kalaiwa.de/assets/1301117m.webp"],"rn":434},{"n":"1.3.01-118-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich darf vor dem Motorrad fahren","Die Radfahrerin muss mich vorbeilassen","Ich muss die Radfahrerin durchfahren lassen"],"co":[0,2],"ex":["Weil du dich zur Rechten des Motorradfahrers befindest, hat er dir den Vorrang zu lassen.","Du musst die Radfahrerin vorbeilassen.","Da sich die Radfahrerin von dir aus in der rechten Straße befindet, musst du ihr die Vorfahrt gewähren."],"i":["https://video4.kalaiwa.de/assets/1301118m.webp"],"rn":435},{"n":"1.3.01-120-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss das grüne Fahrzeug durchfahren lassen","Ich darf vor dem grünen Fahrzeug abbiegen","Ich muss das blaue Fahrzeug vorbeilassen"],"co":[1,2],"ex":["Das grüne Fahrzeug muss dich durchfahren lassen, weil du dich auf der Vorfahrtsstraße befindest.","Du befindest dich auf der Vorfahrtsstraße und hast somit ein Vorrecht vor dem grünen PKW.","Ihr befindet euch beide auf der Vorfahrtsstraße. Da du jedoch von dieser abfahren möchtest, musst du ihn zunächst vorbeilassen."],"i":["https://video2.kalaiwa.de/assets/1301120m.webp"],"rn":436},{"n":"1.3.01-125-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss dem blauen Pkw Vorfahrt gewähren","Ich muss dem roten Pkw Vorfahrt gewähren","Ich habe Vorfahrt vor dem blauen Pkw"],"co":[1,2],"ex":["Du hast Vorfahrt vor dem blauen PKW.","Du musst dem roten PKW, der rechts von dir ist, die Vorfahrt gewähren.","Weil du rechts vom blauen PKW bist, musst er dir die Vorfahrt gewähren."],"i":["https://video4.kalaiwa.de/assets/1301125m.webp"],"rn":437},{"n":"1.3.01-126-M","t":"Welches Verhalten ist richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich muss den gelben Pkw durchfahren lassen","Ich fahre zuerst"],"co":[1],"ex":["Der gelbe PKW muss dich durchfahren lassen.","Du hast Vorfahrt und darfst folglich als erster fahren."],"i":["https://video2.kalaiwa.de/assets/1301126m.webp"],"rn":438},{"n":"1.3.01-127-M","t":"In welcher Reihenfolge müssen die Fahrzeuge hier weiterfahren?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Der Radfahrer, ich, der gelbe Pkw","Der Radfahrer, der gelbe Pkw, ich","Ich, der Radfahrer, der gelbe Pkw"],"co":[0],"ex":["Der Radfahrer ist vor dir und hat somit Vorrang. Danach darfst du weiterfahren und dann erst der gelbe PKW. Er möchte von der Vorfahrtsstraße abbiegen und muss euch daher die Vorfahrt gewähren.","Du hast Vorfahrt vor dem gelben PKW.","Der Radfahrer hat Vorfahrt vor dir."],"i":["https://video4.kalaiwa.de/assets/1301127m.webp"],"rn":439},{"n":"1.3.01-128-M","t":"Wer darf in dieser Situation zuerst fahren?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich selbst","Der blaue Traktor","Der rote Pkw"],"co":[0],"ex":["Ich fahre geradeaus auf meiner Fahrbahn weiter. Der rote Pkw vom Feldweg muss dir Vorfahrt gewähren.","Der blaue Traktor will links abbiegen. Der Abbiegende muss dem geradeaus fahrenden Gegenverkehr immer den Vorrang gewähren.","Der rote Pkw kommt rechts von einem Feldweg und muss deshalb warten."],"i":["https://video2.kalaiwa.de/assets/1301128m.webp"],"rn":440},{"n":"1.3.01-129-M","t":"Wie verhalten Sie sich hier richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Ich fahre vor dem Radfahrer","Ich warte, bis der Radfahrer abgebogen ist","Ich warne den Radfahrer durch Hupen"],"co":[1],"ex":["Der Radfahrer kommt von rechts und wird weiterfahren ohne zu stoppen.","Der Radfahrer kommt von rechts. Du musst ihm Vorfahrt gewähren.","Es gibt keinen Grund zu hupen."],"i":["https://video2.kalaiwa.de/assets/1301129m.webp"],"rn":441},{"n":"1.3.01-130-M","t":"Was ist in dieser Situation richtig?","p":5,"c":"1.3.01","ch":"Vorfahrt Vorrang","th":"Vorfahrt Vorrang","o":["Der blaue Pkw muss warten","Ich muss mich mit dem Fahrer des blauen Pkws verständigen","Ich muss warten"],"co":[2],"ex":["Da es sich hier um keinen Kreisverkehr handelt, gilt die Regel rechts vor links. Der blaue Pkw hat also Vorfahrt.","Die Vorfahrt ist hier klar geregelt. Du musst dich deshalb nicht mit dem Pkw verständigen.","Durch die Beschilderung erkennst du, dass es sich hier nicht um einen Kreisverkehr handelt. Deshalb gilt rechts vor links. Du musst also warten."],"v":["https://video4.kalaiwa.de/assets/1301130mv1440.mp4"],"rn":442},{"n":"1.4.40-001","t":"Wie verhalten Sie sich bei diesem Verkehrszeichen?","p":4,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Nur den von rechts kommenden Verkehr beobachten","Geschwindigkeit vermindern","Bremsbereit sein"],"co":[1,2],"ex":["Natürlich musst du auf den von rechts kommenden Verkehr achten. Dies bedeutet aber keineswegs, dass du das restliche Verkehrsgeschehen außer Acht lassen darfst.","Damit du einem eventuell von rechts kommenden Fahrzeug Vorfahrt gewähren kannst, solltest du deine Geschwindigkeit verringern, um notfalls halten zu können.","Damit du einem eventuell von rechts kommenden Fahrzeug Vorfahrt gewähren kannst, solltest du jederzeit bremsbereit sein."],"i":["https://video4.kalaiwa.de/assets/1440001.webp"],"rn":443},{"n":"1.4.40-006","t":"Welches Verhalten verlangt dieses Verkehrszeichen von Ihnen?","p":5,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Bremsbereitschaft","Geschwindigkeit vermindern","Höchste Aufmerksamkeit"],"co":[0,1,2],"ex":["Da es wahrscheinlich ist, dass Kinder abrupt auf die Fahrbahn laufen könnten, musst du jederzeit bremsbereit sein.","Du solltest hier so langsam wie möglich fahren, um im Falle einer notwendigen Bremsung einen möglichst kurzen Bremsweg zu haben, damit niemand gefährdet wird.","In solchen Bereichen sollte mit höchster Aufmerksamkeit gefahren werden, da plötzlich Kinder auf der Fahrbahn auftauchen könnten."],"i":["https://video4.kalaiwa.de/assets/1440006.webp"],"rn":444},{"n":"1.4.40-009","t":"Worauf weist diese Kombination von Verkehrszeichen hin?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf eine Gefahrstelle im Zusammenhang mit Gespannfuhrwerken","Auf den Vorrang von Gespannfuhrwerken vor Kraftfahrzeugen","Auf ein Durchfahrtsverbot für Gespannfuhrwerke"],"co":[0],"ex":["Hier ist erhöhte Wachsamkeit und vorsichtiges, vorausschauendes Fahren geboten.","Dieses Verkehrszeichen gewährt Gespannfuhrwerken nicht den Vorrang.","Das sagt dieses Verkehrszeichen nicht aus."],"i":["https://video2.kalaiwa.de/assets/1440009.webp"],"rn":445},{"n":"1.4.40-010","t":"Womit müssen Sie bei diesem Verkehrszeichen rechnen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit einem Fußgängerüberweg, der schwer zu erkennen ist","Mit Fußgängern, die die Fahrbahn nur von rechts überqueren dürfen","Mit Fußgängern, die möglicherweise die Fahrbahn überqueren"],"co":[0,2],"ex":["Fußgängerüberwege werden durch dieses Verkehrszeichen angekündigt und verdeutlicht.","Fußgängerüberwege dürfen immer von rechts und links verwendet werden.","Wo ein Fußgängerüberweg ist, muss mit Fußgängern gerechnet werden."],"i":["https://video4.kalaiwa.de/assets/1440010.webp"],"rn":446},{"n":"1.4.40-011","t":"Wie müssen Sie sich bei diesem Verkehrszeichen verhalten?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["- besonders aufmerksam sein","- mit mäßiger Geschwindigkeit an den Fußgängerüberweg heranfahren","- bremsbereit sein"],"co":[0,1,2],"ex":["An einem Fußgängerüberweg musst du möglicherweise anhalten und Fußgänger die Straße überqueren lassen. Deshalb solltest du besonders aufmerksam sein.","Es handelt sich um das Gefahrenzeichen Fußgängerüberweg. Du musst also darauf gefasst sein, dass Fußgänger an dieser Stelle die Straße überqueren wollen. Um diese nicht zu gefährden, musst du langsam an den Fußgängerüberweg heranfahren.","Es kann sein, dass Fußgänger unvermittelt am Straßenrand auftauchen und diese den Fußgängerüberweg überqueren wollen. Du musst also jederzeit bremsbereit sein. Die Fußgänger haben Vorrang und könnten unaufmerksam auf die Straße laufen."],"i":["https://video2.kalaiwa.de/assets/1440011.webp"],"rn":447},{"n":"1.4.40-012","t":"Vor welcher Gefahr warnt Sie dieses Verkehrszeichen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Vor einem seitlichen Versetzen meines Fahrzeugs","Vor Flugbetrieb","Vor Seitenwind"],"co":[0,2],"ex":["Durch den starken Seitenwind könnte sich dein Fahrzeug seitlich versetzen. Stelle dich auf nötiges Gegenlenken ein.","Dies ist nicht das Verkehrszeichen, das auf Flugbetrieb hinweist.","Das Verkehrszeichen warnt vor starkem Seitenwind. Halte dein Lenkrad mit beiden Händen fest, damit dein Fahrzeug durch den Seitenwind nicht von der Spur gedrückt wird."],"i":["https://video2.kalaiwa.de/assets/1440012.webp"],"rn":448},{"n":"1.4.40-013","t":"Sie fahren auf einer Straße mit einem Fahrstreifen für jede Richtung. Bei welchem Verkehrszeichen müssen Sie dem Gegenverkehr grundsätzlich Vorrang gewähren?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video2.kalaiwa.de/assets/1440013o3.png","https://video4.kalaiwa.de/assets/1440013o1.png","https://video2.kalaiwa.de/assets/1440013o2.png"],"co":[1,2],"ex":["Beim Verkehrsschild „Gegenverkehr“ musst du dem entgegenkommenden Verkehr grundsätzlich keinen Vorrang einräumen.","Das Verkehrsschild „einseitig verengte Fahrbahn von rechts“ bedeutet, dass sich deine Fahrspur deutlich verengen wird. Hier musst du dem Gegenverkehr Vorrang gewähren.","Das Verkehrsschild „Vorrang gewähren“ zeigt durch den roten Pfeil an, dass du dem Gegenverkehr Vorrang gewähren musst."],"rn":449},{"n":"1.4.40-101","t":"Sie fahren außerorts an diesem Verkehrszeichen vorbei. In welcher Entfernung ist die Gefahrstelle zu erwarten?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Zwischen 50 m und 150 m","Zwischen 150 m und 250 m","Zwischen 250 m und 350 m"],"co":[1],"ex":["Ein Schild, das in dieser Entfernung angebracht wäre, würde dem Fahrer bei den außerorts üblichen Geschwindigkeiten nicht genügend Zeit lassen, um seine Geschwindgkeit zu reduzieren oder ggf. sogar anzuhalten.","An der dreieckigen Form ist zu erkennen, dass es sich bei diesem Verkehrszeichen um ein Gefahrzeichen handelt. Diese werden außerhalb geschlossener Ortschaften in aller Regel etwa 150 m bis 250 m vor der Gefahrstelle angebracht.","Diese Entfernung wäre zu weit von der Gefahrstelle weg. Der Verkehr würde unnötig verlangsamt."],"i":["https://video2.kalaiwa.de/assets/1440101.webp"],"rn":450},{"n":"1.4.40-103","t":"Worauf müssen Sie sich bei diesen Verkehrszeichen einstellen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["- Wintersport nur auf den Gehwegen stattfindet","- auf der Fahrbahn Wintersport betrieben wird","- auf der Fahrbahn Schnee- oder Eisglätte herrscht"],"co":[1,2],"ex":["Dafür ist hier kein Hinweis gegeben.","Diese Schilder weisen darauf hin, dass hier Skifahrer die Fahrbahn kreuzen.","Da hier Wintersport betrieben wird, ist das vermutlich eine schneereiche Gegend. Daher kannst du auch davon ausgehen, dass die Fahrbahn verschneit, vereist und glatt sein kann."],"i":["https://video4.kalaiwa.de/assets/1440103.webp"],"rn":451},{"n":"1.4.40-105","t":"Wie verhalten Sie sich bei diesem Verkehrszeichen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Geschwindigkeit vermindern","Möglichst weit rechts fahren","Gleich nach der Rechtskurve kräftig beschleunigen"],"co":[0,1],"ex":["Es ist notwendig, die Geschwindigkeit bei einem solchen Fahrbahnverlauf zu reduzieren. Dies gilt schon bei einfachen Kurven, um nicht aus der Kurve geschleudert zu werden.","Man sollte an einer solchen Stelle ebenfalls möglichst weit rechts fahren, da beispielsweise entgegenkommende Fahrer aufgrund zu hoher Geschwindigkeit die Kurve schneiden könnten oder große Fahrzeuge einen Teil deines Fahrstreifens mitbenutzen müssen, um die Doppelkurve befahren zu können.","Wenn du sofort nach der Rechtskurve wieder Gas gibst, dann fährst du mit erhöhter Geschwindigkeit auf die Linkskurve zu. Das ist sehr gefährlich, weil das Auto im schlimmsten Fall zu schnell ist, um die Folgekurve nehmen zu können."],"i":["https://video4.kalaiwa.de/assets/1440105.webp"],"rn":452},{"n":"1.4.40-106","t":"Was kommt nach diesen Verkehrszeichen?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Ein Gefälle von 800 m Länge","Ein Gefälle in 800 m Entfernung","Eine Steigung in 800 m Entfernung"],"co":[0],"ex":["Auf diesem Verkehrszeichen wird ein Gefälle mit einer Länge von 800m angezeigt. Dass es sich um ein Gefälle handelt ist daran zu erkennen, dass der Hang im Verkehrszeichen schräg von links oben nach rechts unten abfällt. Wenn es sich um eine Steigung handelt, dann ist der Hang von links unten nach rechts oben geneigt. Da links und rechts der Angabe „800m“ Pfeile angebracht sind, handelt es sich hier um die Information „auf eine Länge von 800m“.","Das wäre der Fall, wenn das untere der beiden Verkehrsschilder nur die Angabe \"800m\" ohne Pfeile zeigen würde.","Das wäre der Fall, wenn das untere der beiden Verkehrsschilder nur die Angabe \"800m\" ohne Pfeile zeigen würde und im oberen Verkehrsschild der Hang \"bergauf\" geneigt wäre."],"i":["https://video4.kalaiwa.de/assets/1440106.webp"],"rn":453},{"n":"1.4.40-108","t":"Was müssen Sie tun, wenn Sie sich diesem Verkehrszeichen nähern?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Geschwindigkeit erhöhen","Durch schnelle Lenkbewegungen den Unebenheiten ausweichen","Geschwindigkeit verringern"],"co":[2],"ex":["Durch schnelleres Fahren steigt das Risiko einer Gefahrensituation. Du könntest ins Schleudern geraten, das Fahrzeug eine Achsen- oder Federbruch bekommen oder mitgeführte Ladung durch starke Stöße beschädigt werden.","Schnelle Lenkbewegungen würden bei diesem Untergrund die Gefahr erhöhen ins Schleudern zu geraten.","Durch verringerte Geschwindigkeit kannst du die unebene Fahrbahn mit höherer Sicherheit und geringerem Risiko für dich, dein Fahrzeug und andere Verkehrsteilnehmer passieren."],"i":["https://video4.kalaiwa.de/assets/1440108.webp"],"rn":454},{"n":"1.4.40-109","t":"Welche Gefahren können sich durch Nichtbeachten dieses Verkehrszeichens ergeben?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Die Ladung könnte beschädigt werden","Das Fahrzeug könnte schleudern und den Gegenverkehr gefährden","Das Fahrzeug könnte einen Achs- oder Federbruch erleiden"],"co":[0,1,2],"ex":["Auch gut gesicherte Ladung kann bei starken Auf- und Abbewegungen im Fahrzeug herumgeschleudert und beschädigt werden.","Daher sollte die Geschwindigkeit unbedingt reduziert werden.","Heftige Auf- und Abbewegungen des Fahrzeugs bei hoher Geschwindigkeit und unebener Fahrbahnoberfläche belasten Achse und Feder sehr stark. Bei Überbeanspruchung können diese brechen. Auch hier hilft verringerte Geschwindigkeit, einen Schaden am Fahrzeug zu vermeiden."],"i":["https://video2.kalaiwa.de/assets/1440109.webp"],"rn":455},{"n":"1.4.40-112","t":"Wovor warnt dieses Verkehrszeichen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Vor Schleudergefahr bei verschmutzter Fahrbahn","Vor alkoholisierten Autofahrern","Vor Schleudergefahr bei nasser Fahrbahn"],"co":[0,2],"ex":["Eine verschmutzte Fahrbahn erhöht das Risiko, ins Schleudern zu geraten.","Das Fahrzeug weist nicht auf alkoholisierte Fahrer hin.","Daher sollten Geschwindigkeit und Fahrstil der Gefahrensituation angepasst werden, um ein Schleudern zu vermeiden."],"i":["https://video2.kalaiwa.de/assets/1440112.webp"],"rn":456},{"n":"1.4.40-114","t":"Wie verhalten Sie sich bei diesem Verkehrszeichen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Nicht mehr überholen","Vor Erreichen der Verengung immer anhalten","Geschwindigkeit verringern"],"co":[0,2],"ex":["Bei diesem Verkehrszeichen darf nicht überholt werden, weil sich die Straße deutlich verengt.","Es muss nicht unbedingt vor der Verengung angehalten werden. Dies würde den Verkehr unnötig ins Stocken bringen. Beachte jedoch die Verkehrsregelung an der verengten Stelle selbst.","Die verengte Fahrbahn gibt möglicherweise nur Platz für ein Fahrzeug her, um die Engstelle zu durchfahren. Daher ist es ratsam die Geschwindigkeit zu verringern und bremsbereit an die Gefahrenstelle heranzufahren."],"i":["https://video4.kalaiwa.de/assets/1440114.webp"],"rn":457},{"n":"1.4.40-115","t":"Womit müssen Sie bei diesen Verkehrszeichen rechnen?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit einer Ausweichstelle in 50 m Entfernung","Mit einer verengten Fahrbahn in etwa 50 m Entfernung","Mit einer verengten Fahrbahn von 50 m Länge"],"co":[1],"ex":["Es gibt kein offizielles Verkehrszeichen für eine Ausweichstelle. Es gibt nur ein Verkehrszeichen für eine Notfall- und Pannenbucht.","Das Verkehrszeichen deutet auf eine verengte Fahrbahn in etwa 50m Entfernung hin.","Das Verkehrszeichen für eine \"Verengte Fahrbahn von 50m Länge\" hätte auf dem Zusatzzeichen zwei schwarze, nach oben weisende Richtungspfeile."],"i":["https://video4.kalaiwa.de/assets/1440115.webp"],"rn":458},{"n":"1.4.40-116","t":"Womit müssen Sie bei diesem Verkehrszeichen rechnen?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit Baumaterial auf der Fahrbahn","Mit Arbeitern auf der Fahrbahn","Mit Verkehr von Baustellenfahrzeugen"],"co":[0,1,2],"ex":["Dieses kann von Baustellenfahrzeugen herunterfallen oder unbeabsichtigt auf die Fahrbahn gelangen. Hier ist erhöhte Aufmerksamkeit geboten.","Mit Bauarbeitern kann auf einer Baustelle gerechnet werden. Diese können teilweise sehr nahe am Fahrbahnrand arbeiten. Daher sollten Geschwindigkeit und Fahrstil an diese Gefahrensituation angepasst werden, um die Arbeiter nicht zu gefährden.","Es ist wahrscheinlich, dass sich Baustellenfahrzeuge in Baustellennähe befinden."],"i":["https://video2.kalaiwa.de/assets/1440116.webp"],"rn":459},{"n":"1.4.40-118","t":"Womit müssen Sie bei diesem Verkehrszeichen rechnen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit einem Stau","Mit Erweiterung der Fahrbahn auf drei Fahrstreifen","Mit plötzlichem Bremsen der Vorausfahrenden"],"co":[0,2],"ex":["Dieses Gefahrenzeichen weist auf eine mögliche Staustelle hin.","Das Verkehrszeichen, dass auf die Erweiterung der Fahrbahn auf drei Fahrstreifen hinweist, ist blau und rechteckig und zeigt drei weiße Pfeile in Fahrtrichtung.","Der vorausfahrende Fahrer kann durch stockenden oder bremsenden Verkehr selbst zu plötzlichem Bremsen veranlasst sein, vor allem wenn das Stauende sich an eine unübersichtlichen Stelle oder in einer Kurve befindet. Daher sollte ausreichend Abstand gehalten und vorausschauend gefahren werden."],"i":["https://video2.kalaiwa.de/assets/1440118.webp"],"rn":460},{"n":"1.4.40-121","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf einen Bahnübergang mit rotem Blinklicht","Auf eine Ampel","Auf eine Zollstelle"],"co":[1],"ex":["Ein Bahnübergang wird durch das Verkehrszeichen \"Andreaskreuz\" mit Blinklicht gekennzeichnet.","Das Verkehrszeichen bedeutet \"Lichtzeichenanlage\" und weist auf eine Ampel hin.","Das Verkehrszeichen für eine Zollstelle ist ein Kreis mit rotem Rand und der Schrift Zoll/Douane."],"i":["https://video4.kalaiwa.de/assets/1440121.webp"],"rn":461},{"n":"1.4.40-127","t":"Worauf weisen diese Verkehrszeichen hin?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf eine Umleitung, die den Bahnübergang umgeht","Auf einen Bahnübergang in der nach rechts führenden Straße","Auf die Richtung, aus der ein Zug kommen kann"],"co":[1],"ex":["Das Verkehrszeichen zeigt auch keine Umleitung, die den Bahnübergang umgeht.","Das obere Verkehrszeichen weist auf einen unbeschrankten Bahnübergang hin. Das Zusatzzeichen \"In Richtung der Gefahrenstelle, rechtsweisend\" zeigt, dass der Bahnübergang sich in der nach rechts führenden Straße befindet.","Es gibt kein Verkehrszeichen, welches die Fahrtrichtung eines Schienenfahrzeugs anzeigt. Dies würde auch wenig Sinn geben, da Schienen in beide Richtungen genutzt werden und sich die Richtung folglich ändern kann."],"i":["https://video4.kalaiwa.de/assets/1440127.webp"],"rn":462},{"n":"1.4.40-130","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf einen Bahnübergang in etwa 160 m Entfernung","Auf einen Bahnübergang in etwa 240 m Entfernung","Auf einen Bahnübergang in etwa 80 m Entfernung"],"co":[0],"ex":["Das Verkehrszeichen ist eine Entfernungsbake mit zwei roten Streifen. Pro Streifen sind 80 Meter Distanz bis zum Bahnübergang gemeint. In diesem Fall sind es also noch 160 Meter. Verläuft der Streifen von links unten nach rechts oben, dann befindet sich diese Bake auf der rechten Fahrbahnseite und andersherum.","Würde sich die Bake in 240 m Entfernung vom Bahnübergang befinden, würde sie drei roten Streifen aufweisen. (3 x 80 m = 240 m)","Würde sich die Bake in 80 m Entfernung vom Bahnübergang befinden, würde sie nur einen roten Streifen aufweisen. (1 x 80 m = 80 m)"],"i":["https://video2.kalaiwa.de/assets/1440130.webp"],"rn":463},{"n":"1.4.40-131","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf einen Bahnübergang in etwa 160 m Entfernung","Auf einen Bahnübergang in etwa 80 m Entfernung","Auf einen Bahnübergang in etwa 240 m Entfernung"],"co":[1],"ex":["Würde der Bahnübergang in 160 m Entfernung sein, müsste die Warnbake zwei rote Streifen haben. Ein Streifen steht nämlich für 80 m Distanz zum Bahnübergang. ( 2 x 80 m = 160 m)","Das abgebildete Verkehrszeichen ist eine einstreifige Entfernungsbake. Der einzelne Rote Streifen bedeutet, dass sich in 80 Meter Distanz ein Bahnübergang befindet.","Würde der Bahnübergang in 240 m Entfernung sein, müsste die Warnbake drei rote Streifen haben. ( 3 x 80 m = 240 m)"],"i":["https://video2.kalaiwa.de/assets/1440131.webp"],"rn":464},{"n":"1.4.40-132","t":"Worauf weist diese Verkehrszeichenkombination hin?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["- in etwa 80 m Entfernung","- in etwa 160 m Entfernung","- in etwa 240 m Entfernung"],"co":[2],"ex":["Wäre der Bahnübergang 80 entfernt, dann hätte die Bake nur einen roten Streifen.","Wäre der Bahnübergang 160 entfernt, dann hätte die Bake zwei rote Streifen.","Die Bake zeigt drei rote Streifen. Ein Streifen steht für 80 Meter. Somit ist der unbeschrankte Bahnübergang noch 240 m (3 x 80 m) entfernt."],"i":["https://video4.kalaiwa.de/assets/1440132.webp"],"rn":465},{"n":"1.4.40-135","t":"Was müssen Sie bei dieser Verkehrszeichenkombination beachten?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Einen Bahnübergang in 240 m Entfernung","Kraftfahrzeuge dürfen nicht überholt werden","Einen Bahnübergang in 120 m Entfernung"],"co":[0,1],"ex":["Diese Verkehrszeichenkombination sagt aus, dass sich in 240 m Entfernung (drei Streifen, also 3 x 80 m) ein unbeschrankter Bahnübergang befindet.","Es muss gewährleistet sein, dass man im Bedarfsfall rechtzeitig vor dem Bahnübergang zum Stehen kommt. Daher dürfen hier keine Kraftfahrzeuge mehr überholt werden.","Die Verkehrszeichenkombination zeigt einen Bahnübergang in 240 m Entfernung. Ein Streifen auf der Bake würde 80 m, und zwei Streifen 160 m Entfernung bedeuten."],"i":["https://video2.kalaiwa.de/assets/1440135.webp"],"rn":466},{"n":"1.4.40-142","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf einen Bahnübergang","Auf einen Bahnhof","Auf eine Bahnunterführung"],"co":[0],"ex":["Das Verkehrszeichen weist auf einen Bahnübergang hin.","Das Verkehrszeichen weist nicht auf einen Bahnhof, sondern auf einen Bahnübergang hin.","Das Verkehrszeichen weist nicht auf eine Bahnunterführung, sondern auf einen Bahnübergang hin."],"i":["https://video4.kalaiwa.de/assets/1440142.webp"],"rn":467},{"n":"1.4.40-143","t":"Womit müssen Sie bei diesem Verkehrszeichen rechnen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Entgegenkommende Fahrzeuge könnten die Kurve schneiden","Es folgt eine scharfe Rechtskurve","Fahrzeuge vor mir könnten stark bremsen"],"co":[0,1,2],"ex":["Weil die Kurve für den Gegenverkehr gleichermaßen scharf ist, kann es passieren, das entgegenkommende Fahrzeuge die Kurve schneiden. Vermindere deine Fahrgeschwindigkeit.","Vermindere daher deine Geschwindigkeit und fahre hier sehr vorsichtig und vorausschauend.","Bremse eben so ab und halte ausreichend Sicherheitsabstand."],"i":["https://video2.kalaiwa.de/assets/1440143.webp"],"rn":468},{"n":"1.4.40-144","t":"Womit müssen Sie bei diesem Verkehrszeichen rechnen?","p":4,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit einer Unterführung für Radfahrer","Mit einem Verkehrsverbot für Radfahrer","Mit Radfahrern, welche die Fahrbahn kreuzen"],"co":[2],"ex":["Das Zeichen deutet nicht auf eine Unterführung hin.","Das Gegenteil ist der Fall. Du musst hier erhöhte Wachsamkeit für Radfahrer zeigen.","Hier musst du damit rechnen, dass Radfahrer die Fahrbahn kreuzen."],"i":["https://video4.kalaiwa.de/assets/1440144.webp"],"rn":469},{"n":"1.4.40-147","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf eine Gefahrstelle im Zusammenhang mit Pferden","Auf den Vorrang von Reitern vor Kraftfahrzeugen","Auf ein Durchfahrtsverbot wegen eines Reitweges"],"co":[0],"ex":["Das Verkehrszeichen warnt vor einer Gefahrenstelle mit Pferden.","Das Verkehrszeichen regelt nicht die Vorfahrt.","Verkehrszeichen sagt nichts über eine verbotene Durchfahrt aus."],"i":["https://video4.kalaiwa.de/assets/1440147.webp"],"rn":470},{"n":"1.4.40-148","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf Eisglätte","Auf Lawinen","Auf Schneeglätte"],"co":[0,2],"ex":["Mit Eisglätte ist zu rechnen.","Das Verkehrsschild mit einer Schneeflocke weist ohne Zusatzschild nicht auf eine Lawinengefahr hin.","Das Verkehrszeichen warnt vor Glätte durch Schnee auf der Fahrbahn."],"i":["https://video2.kalaiwa.de/assets/1440148.webp"],"rn":471},{"n":"1.4.40-149","t":"Womit müssen Sie bei diesem Verkehrszeichen rechnen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit Weidetieren auf der Fahrbahn","Mit stark verschmutzter Fahrbahn","Mit Wildwechsel"],"co":[0,1],"ex":["Möglicherweise könnten sich Weidetiere auf der Fahrbahn befinden.","Sie müssen mit einer stark verschmutzten Fahrbahn rechnen.","Das Gefahrenzeichen zeigt Viehtrieb an - keinen Wildwechsel."],"i":["https://video4.kalaiwa.de/assets/1440149.webp"],"rn":472},{"n":"1.4.40-150","t":"Wie sollten Sie sich bei einer so gekennzeichneten Gefahrstelle verhalten?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["- plötzliche Lenkbewegungen vermeiden","- einen möglichst großen Abstand zum vorausfahrenden Fahrzeug einhalten","- starkes Beschleunigen vermeiden"],"co":[0,1,2],"ex":["Durch Split oder Schotter auf der Fahrbahn könnte dein Fahrzeug bei plötzlichem Lenken ins Schleudern geraten.","Bei unbefestigten Straßenbelägen verlängert sich der Bremsweg. Der Abstand zum Vordermann sollte deshalb möglichst groß gehalten werden.","Starkes Beschleunigen kann bei nicht befestigten Straßen gefährlich sein."],"i":["https://video4.kalaiwa.de/assets/1440150.webp"],"rn":473},{"n":"1.4.40-151","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Auf Kanalarbeiten","Auf eine bewegliche Brücke","Auf eine Fähre"],"co":[1],"ex":["Das Gefahrenzeichen zeigt keine Kanalarbeiten an.","Das Gefahrenzeichen warnt vor einer beweglichen Brücke. Diese kann geöffnet werden und stellt somit ein Hindernis für die Weiterfahrt dar.","Das Verkehrszeichen weist nicht auf eine Fähre hin."],"i":["https://video2.kalaiwa.de/assets/1440151.webp"],"rn":474},{"n":"1.4.40-152","t":"Was haben Sie bei diesem Verkehrszeichen zu beachten?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Die Ein- und Ausfahrstelle für schwimmfähige Fahrzeuge ist frei zu halten","Wasserflächen sind bei Dunkelheit oder schlechter Sicht schwer von der Fahrbahn zu unterscheiden","Die Straße führt auf ein Ufer zu"],"co":[1,2],"ex":["Das Schild deutet nicht auf eine Ein- oder Ausfahrt hin.","Bei Dunkelheit, Nebel etc. sollte das Ufer aufmerksam im Blick behalten werden.","Das Gefahrenzeichen zeigt an, dass die Straße auf ein Ufer zu führt."],"i":["https://video2.kalaiwa.de/assets/1440152.webp"],"rn":475},{"n":"1.4.40-153","t":"Was haben Sie bei diesem Verkehrszeichen zu beachten?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Halten und Parken ist zu vermeiden","Steine könnten auf der Fahrbahn liegen","Vorausfahrende Fahrzeuge könnten plötzlich abbremsen"],"co":[0,1,2],"ex":["Hier sollte aus Sicherheitsgründen nicht gehalten oder geparkt werden.","Es könnten sich Steine von einer Felswand gelöst haben, die nun auf der Fahrbahn liegen.","Aufgrund von herabfallenden Steinen oder Steinen auf der Fahrbahn muss mit einer Gefahrenbremsung vorausfahrender Fahrzeuge gerechnet werden."],"i":["https://video4.kalaiwa.de/assets/1440153.webp"],"rn":476},{"n":"1.4.40-154","t":"Womit müssen Sie bei diesem Verkehrszeichen rechnen?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit plötzlich auftretendem Fluglärm","Mit plötzlich bremsenden Fahrzeugen","Mit der Ablenkung anderer Verkehrsteilnehmer"],"co":[0,1,2],"ex":["Bei Flugplätzen in der Nähe sollte immer mit überraschend auftretendem Fluglärm gerechnet werden.","Durch Flugzeuge und Fluglärm in der Nähe könnten sich andere Verkehrsteilnehmer erschrecken und auf die Bremse treten.","In der Nähe landen und starten Flugzeuge. Das kann zur Ablenkung anderer Verkehrsteilnehmer führen."],"i":["https://video4.kalaiwa.de/assets/1440154.webp"],"rn":477},{"n":"1.4.40-156","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe. Was müssen Sie bei diesem Verkehrszeichen berücksichtigen?","p":3,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Bei längerer Betätigung der Bremse kann die Bremswirkung nachlassen","Die Bremswirkung wird besser, wenn kein Gang eingelegt ist","Der Bremsweg verlängert sich"],"co":[0,2],"ex":["Aufgrund der langen Betätigung der Bremse und der damit verbundenen stärkeren Erhitzung kann die Bremswirkung nachlassen. Es kann dann sogar zum völligen Ausfall der Bremsanlage kommen.","Im Leerlauf fällt die Bremswirkung des Motors weg. Dadurch wird deine Bremse noch mehr belastet.","Das Verkehrsschild zeigt dir an, dass ein Gefälle von 10% erfolgt. Dein Auto wird schneller, weil es bergab geht. Somit dauert es länger als in der Ebene, bis dein Fahrzeug zum Stillstand kommt."],"i":["https://video2.kalaiwa.de/assets/1440156.webp"],"rn":478},{"n":"1.4.40-157","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe. Wie verhalten Sie sich bei diesem Verkehrszeichen richtig?","p":2,"c":"1.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Ich befahre vorsichtig dieses Gefälle","Ich schalte gegebenenfalls in einen niedrigeren Gang","Ich schalte stets in einen höheren Gang"],"co":[1],"ex":["Dieses Verkehrszeichen zeigt dir eine 12-prozentige Steigung an und kein Gefälle.","Die höhere Kraftwirkung eines niedrigeren Ganges kann genutzt werden, um die Geschwindigkeit in einer Steigung beizubehalten.","In einem höheren Gang hat der Motor weniger Kraft. Das ist in einer Steigung keine gute Idee."],"i":["https://video2.kalaiwa.de/assets/1440157.webp"],"rn":479},{"n":"1.4.41-001","t":"In welchem Fall müssen Sie vor diesem Verkehrszeichen warten?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Wenn sich ein Schienenfahrzeug nähert","Wenn Sie den Übergang nicht überqueren können, ohne auf ihm anhalten zu müssen","Wenn ein Bahnbediensteter eine weiß-rot-weiße Fahne schwenkt"],"co":[0,1,2],"ex":["Die Distanz zum und die Geschwindigkeit des Schienenfahrzeugs kann sehr schwer eingeschätzt werden. Daher musst du unbedingt vor dem Übergang warten, um das Risiko eines schweren Zusammenpralls zu vermeiden.","Ist hinter dem Bahnübergang stockender Verkehr, so ist unbedingt davor zu warten, bis dieser ohne Risiko überquert werden kann. Züge fahren mit hoher Geschwindigkeit und haben zudem aufgrund ihres Gewichts einen langen Bremsweg. Ein auf den Schienen befindliches Fahrzeug könnte einen schweren Zusammenstoß verursachen.","Wenn ein Bahnbediensteter eine weiß-rot-weiße Fahne schwenkt, bedeutet dies, dass in Kürze ein Schienenfahrzeug den Bahnübergang passieren wird. Deshalb muss in dieser Situation vor dem Bahnübergang gewartet werden."],"i":["https://video2.kalaiwa.de/assets/1441001.webp"],"rn":480},{"n":"1.4.41-004","t":"Wie verhalten Sie sich bei diesem Verkehrszeichen?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Sie dürfen nur nach rechts weiterfahren","Sie müssen die Fahrtrichtungsänderung nach rechts anzeigen","Sie dürfen nicht nach rechts abbiegen"],"co":[0,1],"ex":["Du musst bei diesem Verkehrszeichen nach rechts weiterfahren.","Steht das Vorschriftszeichen \"rechts abbiegen\" am Straßenrand, dann darf nur nach rechts weitergefahren werden. Die Änderung der Fahrtrichtung musst du anzeigen.","Es muss hier nach rechts weitergefahren oder abgebogen werden."],"i":["https://video2.kalaiwa.de/assets/1441004.webp"],"rn":481},{"n":"1.4.41-006","t":"In welche Richtungen dürfen Sie weiterfahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Nach links","Geradeaus","Nach rechts"],"co":[1,2],"ex":["Auf dem Verkehrszeichen ist kein Linkspfeil abgebildet. Daher darf auch nicht nach links weitergefahren werden.","Du darfst geradeaus fahren.","Weil der Pfeil sowohl geradeaus, als auch nach rechts zeigt, darfst du geradeaus fahren oder nach rechts abbiegen."],"i":["https://video2.kalaiwa.de/assets/1441006.webp"],"rn":482},{"n":"1.4.41-007","t":"Wie müssen Sie sich bei diesem Verkehrszeichen verhalten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Sie dürfen vor diesem Zeichen nicht nach links abbiegen","Sie sind verpflichtet, nach rechts abzubiegen","Sie müssen an Verkehrsinseln rechts vorbeifahren"],"co":[2],"ex":["Ein Abbiegen nach links (vor der Verkehrsinsel oder dem Hindernis) mag hier möglich sein. Das Zeichen verpflichtet dich nur, rechts an dem Hindernis oder der Verkehrsinsel vorbeizufahren.","Es muss rechts vorbeigefahren werden. Rechts abbiegen signalisiert das Vorschriftszeichen mit einem waagrechten weißen Rechtspfeil auf blauem Grund.","Der Pfeil, welcher von links oben nach rechts unten verläuft, signalisiert, rechtsseitig vorbeizufahren. Zeigt ein Pfeil nach links unten, dann muss dieses linksseitig passiert werden."],"i":["https://video2.kalaiwa.de/assets/1441007.webp"],"rn":483},{"n":"1.4.41-008","t":"Sie nähern sich einer so gekennzeichneten Haltestelle. Wie verhalten Sie sich, wenn Sie dort Kinder sehen?","p":5,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Geschwindigkeit vermindern und bremsbereit bleiben","Eine Verminderung der Geschwindigkeit ist nur erforderlich, wenn dort ein Schulbus hält","Die Geschwindigkeit muss nicht vermindert werden, wenn ein Bus in einer Haltebucht hält"],"co":[0],"ex":["Die Kinder an der Bushaltestelle warten vermutlich auf einen Bus. Das Verhalten von Kindern ist nicht vorauszusagen. Es ist damit zu rechnen, dass die Kinder unachtsam für den Straßenverkehr sind, weil sie eine andere Gefahrenwahrnehmung haben als Erwachsene. Ein Kind könnte ein anderes unüberlegt auf die Fahrbahn schubsen, oder selbst darauf rennen. Hier muss mit sehr hoher Wachsamkeit und Bremsbereitschaft gefahren werden, um niemanden zu gefährden.","Sobald Kinder in Sicht sind, ist erhöhte Aufmerksamkeit geboten. Sie verhalten sich oft spontan und unüberlegt. Daher gilt, unabhängig davon, ob dort ein Schulbus steht, oder nicht: Wenn Kinder in Sicht sind - Fuß vom Gas.","Du musst die Geschwindigkeit vermindern und bremsbereit sein, sobald sich Kinder in Sichtweite befinden."],"i":["https://video2.kalaiwa.de/assets/1441008.webp"],"rn":484},{"n":"1.4.41-012","t":"Womit darf man hier nicht fahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Mit Leichtkrafträdern","Mit Mofas","Mit Kleinkrafträdern"],"co":[1],"ex":["Als Leichtkrafträder werden kleine Motorräder bezeichnet, die über einen Hubraum von mehr als 50 cm³, aber höchstens 125 cm³ verfügen. Dieses Verkehrszeichen verbietet jedoch Mofas die Durchfahrt.","Das im Verbotszeichen dargestellte Symbol verbietet ausschließlich Mofas die Durchfahrt. Somit bezieht sich das Verbot auch nur auf diese Fahrzeuge, alle anderen dürfen hier verkehren.","Kleinkrafträder sind alle motorisierten Zwei- oder Dreiräder mit einem maximalen Hubraum von 50 cm³ oder bis zu 4 kW Motorleistung und einer durch die Bauart bedingten Höchstgeschwindigkeit von nicht mehr als 45 km/h (für Ausnahmen 60 km/h). Diese Definition bezieht Mofas, aber auch u.a. Roller und Mopeds mitein. Das hier dargestellte Verkehrszeichen bezieht sich aber ausschließlich auf Mofas."],"i":["https://video2.kalaiwa.de/assets/1441012.webp"],"rn":485},{"n":"1.4.41-015","t":"Was ist bei diesem Verkehrszeichen erlaubt?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Das Halten zum Be- oder Entladen sowie zum Ein- oder Aussteigen","Das Parken, wenn eine Parkscheibe benutzt wird","Das Halten bis zu 3 Minuten"],"co":[0,2],"ex":["Parken ist hier allerdings untersagt.","Parken ist hier generell nicht erlaubt. Das gilt unabhängig davon, ob eine Parkscheibe benutzt wird, oder nicht.","Wer länger als drei Minuten hält, der parkt. Das ist in diesem Fall nicht gestattet."],"i":["https://video4.kalaiwa.de/assets/1441015.webp"],"rn":486},{"n":"1.4.41-017","t":"Was gilt bei dieser Verkehrszeichenkombination?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- den Verkehr mit Elektrorollern von links und rechts beachten","- nur den Kraftfahrzeugverkehr auf der Vorfahrtstraße von links und rechts beachten","- den Radverkehr von links und rechts beachten"],"co":[0,2],"ex":["Das Zusatzzeichen zeigt an, dass nicht nur dem Kraftfahrzeugverkehr Vorfahrt gewährt werden muss, sondern explizit auch dem Radverkehr. Dazu zählen auch Elektroroller.","Zusätzlich zum Kraftfahrzeugverkehr muss auch dem Radverkehr Vorfahrt gewährt werden.","Das Zusatzzeichen zeigt an, dass nicht nur dem Kraftfahrzeugverkehr Vorfahrt gewährt werden muss, sondern explizit auch dem Radverkehr."],"i":["https://video4.kalaiwa.de/assets/1441017.webp"],"rn":487},{"n":"1.4.41-018","t":"Welche Fahrzeuge dürfen in eine so gekennzeichnete Fahrradstraße einfahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Alle Pkws, wenn sie Schrittgeschwindigkeit fahren","Alle Fahrzeuge, die von Anliegern gefahren werden","Alle Mofas mit bauartbedingter Höchstgeschwindigkeit unter 25 km/h"],"co":[1],"ex":["Nur Anlieger (und deren Besucher) dürfen hier mit Pkws fahren.","Als Bewohner oder Besucher der Bewohner darfst du bei dem Zusatzzeichen \"Anlieger frei\" die Fahrradstraße benutzen.","Du darfst mit einem Mofa keine Fahrradstraße befahren, auch wenn du die in Fahrradstraßen erlaubt Höchstgeschwindigkeit von 30 km/h bauartbedingt nicht überschreitest."],"i":["https://video2.kalaiwa.de/assets/1441018.webp"],"rn":488},{"n":"1.4.41-019","t":"Was gilt bezüglich gelber Fahrbahnmarkierungen?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- gelten nur für Baustellenfahrzeuge","- ersetzen die Gültigkeit weißer Fahrbahnmarkierungen","- werden nur vorübergehend angebracht (zum Beispiel an Baustellen)"],"co":[1,2],"ex":["Alle Fahrzeuge müssen sich an die gelben Fahrbahnmarkierungen halten.","Die Anordnungen und Bedeutungen von gelben Fahrbahnmarkierungen gehen weißen Markierungen vor.","Die gelbe Fahrbahnmarkierungen zeigen an, dass sich die Verkehrsführung vorübergehend geändert hat."],"rn":489},{"n":"1.4.41-021","t":"Welche Fahrzeuge dürfen in eine so gekennzeichnete Zone einfahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Fahrräder","Fahrzeuge, die von Anwohnern gefahren werden","Elektrokleinstfahrzeuge"],"co":[0,1,2],"ex":["Es handelt sich um eine Fahrradzone. Hier dürfen Fahrräder fahren.","Durch das Zusatzzeichen \"Anlieger frei\" dürfen auch Fahrzeuge, die von Anwohnern gefahren werden, in dieser Zone fahren.","Fahrradzonen dürfen ebenfalls von Elektrokleinstfahrzeugen befahren werden. Das sind z. B. elektrische Tretroller und Segways."],"i":["https://video4.kalaiwa.de/assets/1441021.webp"],"rn":490},{"n":"1.4.41-022","t":"Was müssen Sie innerorts beim Befahren einer Straße mit dieser Verkehrszeichenkombination beachten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Beim Überholen von Radfahrern muss ich einen seitlichen Mindestabstand von 1,5 m einhalten","Radfahrer können mir entgegenkommen","Radfahrer müssen die Gehwege rechts und links der Fahrbahn nutzen"],"co":[0,1],"ex":["Innerorts musst du beim Überholen von Radfahrern immer einen seitlichen Mindestabstand von 1,5 m einhalten.","Das Einbahnstraßenschild gilt zwar grundsätzlich auch für Radfahrer, allerdings dürfen sie bei dieser Verkehrszeichenkombination in beide Richtungen fahren.","Radfahrer dürfen den Gehweg nicht befahren."],"i":["https://video4.kalaiwa.de/assets/1441022.webp"],"rn":491},{"n":"1.4.41-023","t":"Dieses Verkehrszeichen ist am rechten Fahrbahnrand aufgestellt. Welche Bedeutung hat es?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- dahinter nicht halten","- davor parken","- davor nicht halten"],"co":[0,2],"ex":["Die Pfeile zeigen in beide Richtungen. Der Pfeil nach links zeigt an, dass du nach dem Schild nicht halten darfst.","Nicht halten zu dürfen ist restriktiver als parken, somit darfst du hier auch nicht parken.","Die Pfeile zeigen in beide Richtungen. Der Pfeil nach rechts zeigt an, dass du vor dem Schild nicht halten darfst."],"i":["https://video2.kalaiwa.de/assets/1441023.webp"],"rn":492},{"n":"1.4.41-024","t":"Dieses Verkehrszeichen ist am rechten Fahrbahnrand aufgestellt. Welche Bedeutung hat es?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- den Beginn eines eingeschränkten Haltverbots","- den Beginn eines absoluten Haltverbots","- das Ende eines absoluten Haltverbots"],"co":[1],"ex":["Das Verkehrsschild hat ein rotes Kreuz und signalisiert dadurch ein absolutes Haltverbot.","Der Pfeil nach links heißt, dass das Haltverbot ab dem Schild gilt. Das bedeutet also den Beginn eines absoluten Haltverbots.","Der Pfeil nach links bedeutet, dass das Haltverbot ab dem Schild gilt. Das heißt hier beginnt das absolute Haltverbot und nicht, dass es dort endet."],"i":["https://video2.kalaiwa.de/assets/1441024.webp"],"rn":493},{"n":"1.4.41-025","t":"Was müssen Sie bei diesem Verkehrszeichen beachten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- halten, um Mitfahrer aussteigen zu lassen","- zum kurzzeitigen Beladen halten","- nicht halten"],"co":[2],"ex":["Bei einem absoluten Haltverbot darfst du grundsätzlich nicht halten. Auch nicht, um Mitfahrer aussteigen zu lassen.","Bei einem absoluten Haltverbot darfst du nicht halten. Auch nicht nur kurzzeitig.","Das Verkehrszeichen signalisiert ein absolutes Haltverbot in diesem Bereich. Du darfst dort nicht halten."],"i":["https://video2.kalaiwa.de/assets/1441025.webp"],"rn":494},{"n":"1.4.41-027","t":"Wann dürfen Sie hier halten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["An Sonntagen","An Samstagen","An Feiertagen"],"co":[0,2],"ex":["Das absolute Halteverbot ist auf Werktage beschränkt. An Sonntagen darfst du hier halten.","Da der Samstag ein Werktag ist, darfst du hier samstags nicht halten.","Das absolute Halteverbot gilt nur an Werktagen. An Feiertagen darfst du hier halten."],"i":["https://video4.kalaiwa.de/assets/1441027.webp"],"rn":495},{"n":"1.4.41-029","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- mit Schrittgeschwindigkeit befahren","- als Anlieger befahren","- nicht befahren"],"co":[2],"ex":["Du darfst eine Straße mit diesem Verkehrsschild mit keinem Fahrzeug befahren, egal mit welcher Geschwindigkeit.","Auch als Anlieger darfst du die Straße nicht befahren.","In eine Straße mit diesem Verkehrsschild darfst du nicht hineinfahren. Es bedeutet „Verbot für Fahrzeuge aller Art.“"],"i":["https://video4.kalaiwa.de/assets/1441029.webp"],"rn":496},{"n":"1.4.41-030","t":"Sie befahren eine so beschilderte Einbahnstraße. Was ist richtig?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich darf entgegen der Fahrtrichtung parken","Ich muss mich zum Linksabbiegen möglichst weit links einordnen","Ich darf auch am linken Fahrbahnrand parken"],"co":[1,2],"ex":["Du darfst nicht entgegen der Fahrtrichtung der Einbahnstraße parken, da du diese nur in einer Richtung befahren darfst.","Um beim Linksabbiegen den nachfolgenden Verkehr hinter dir nicht zu behindern, musst du dich so weit wie möglich nach links einordnen. So lässt du genügend Platz für Fahrzeuge, die geradeaus fahren oder rechts abbiegen wollen.","Da du auf einer Einbahnstraße befindest, darfst du am rechten wie auch linken Fahrbahnrand in Fahrtrichtung (der Einbahnstraße) parken."],"i":["https://video4.kalaiwa.de/assets/1441030.webp"],"rn":497},{"n":"1.4.41-031","t":"Sie befahren eine Vorfahrtstraße. Welches Verkehrszeichen beendet Ihre Vorfahrt?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video4.kalaiwa.de/assets/1441031o3.png","https://video2.kalaiwa.de/assets/1441031o2.png","https://video4.kalaiwa.de/assets/1441031o1.png"],"co":[1,2],"ex":["Das Verkehrsschild „Einmalige Vorfahrt“ bedeutet, dass du einmalig an der kommenden Kreuzung oder Einmündung Vorfahrt hast.","Das Verkehrszeichen „Ende Vorfahrtsstraße“ signalisiert dir, dass die Vorfahrtsregelung aufgehoben ist und die Vorfahrtsstraße hier endet.","Wenn du bisher auf einer Vorfahrtsstraße gefahren bist, weißt dich das Verkehrszeichen „Vorfahrt gewähren“ darauf hin, dass diese Vorfahrtsstraße nun endet. Du musst anderen Verkehrsteilnehmern nun Vorfahrt gewähren."],"rn":498},{"n":"1.4.41-032","t":"Bei welcher Verkehrsregelung müssen Sie vor dem Rechtsabbiegen grundsätzlich anhalten?","p":4,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video2.kalaiwa.de/assets/1441032o1.png","https://video4.kalaiwa.de/assets/1441032o2.png","https://video2.kalaiwa.de/assets/1441032o3.png"],"co":[0,1],"ex":["Das „Stop-Schild“ zeigt dir an, dass du grundsätzlich an der Haltelinie oder Sichtlinie anhalten musst.","Der „Grünpfeil“ neben dem roten Ampelsignal signalisiert dir, dass du trotz der roten Ampel nach rechts abbiegen darfst. Jedoch erst, nachdem du an der Halte- oder Sichtlinie angehalten und dich vergewissert hast, dass du niemanden gefährdest.","Das Verkehrsschild „Einmalige Vorfahrt“ bedeutet, dass du nur an der nächsten Kreuzung oder Einmündung Vorfahrt hast. Hier musst du nicht halten."],"rn":499},{"n":"1.4.41-033","t":"Welches Verkehrszeichen verbietet Ihnen das Einfahren in den beschilderten Bereich?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video2.kalaiwa.de/assets/1441033o1.png","https://video4.kalaiwa.de/assets/1441033o3.png","https://video2.kalaiwa.de/assets/1441033o2.png"],"co":[0,2],"ex":["In eine Straße mit diesem Verkehrsschild darfst du nicht einfahren, da es einen Fußgängerzone anzeigt. Diese darf nur von Fußgängern benutzt werden.","Dieses Verkehrsschild zeigt lediglich an, dass du dem Gegenverkehr Vorrang gewähren musst. Du darfst jedoch den beschilderten Bereich befahren.","Das Verkehrsschild bedeutet „Einfahren verboten“. Das Einfahren in den beschilderten Bereich ist demnach verboten."],"rn":500},{"n":"1.4.41-106","t":"In welche Richtungen dürfen Sie weiterfahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Nach rechts","Nach links","Geradeaus"],"co":[0,1],"ex":["Du darfst hier nach rechts abbiegen.","Du darfst hier nach links abbiegen.","Die vorgeschriebenen Fahrtrichtungen sind links und rechts. Geradeaus darf hier nicht gefahren werden."],"i":["https://video2.kalaiwa.de/assets/1441106.webp"],"rn":501},{"n":"1.4.41-109","t":"Etwa 80 m vor Ihnen hält ein Schulbus auf der Fahrbahn. Können daraus Gefahren entstehen?","p":5,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Nein, weil an jeder Schulbushaltestelle Schülerlotsen den Verkehr sichern","Ja, weil Kinder nicht immer auf kürzestem Weg die Fahrbahn überqueren","Ja, weil Kinder häufig über die Straße rennen, um den Bus noch zu erreichen"],"co":[1,2],"ex":["Nicht jede Schulbushaltestelle wird von einem Schülerlotsen gesichert. Selbst wenn die Haltestelle einen Schülerlotsen hat, musst du dennoch besonders vorsichtig sein. Auch mit Schülerlotsen verhalten sich Kinder nicht immer der Verkehrssituation angemessen.","Oft sind Kinder ungeduldig und vergessen ihre Umwelt. Es kann passieren, dass sie ohne Umsicht die Straße überqueren, oder ohne erkennbaren Grund vom Fußgängerweg auf die Straße wechseln. Daher musst du an dieser Stelle besonders aufmerksam und langsam fahren und dich auf plötzliches Abbremsen einstellen.","Kinder sind im Verkehr besonders gefährdet, weil sie Verkehrssituationen häufig falsch einschätzen und noch kein ausgeprägtes Gefahrenbewusstsein besitzen. Dieses entsteht erst im Laufe der Entwicklung. Daher ist es möglich, dass sie, um den Bus noch zu bekommen, einfach auf die Straße rennen, ohne sich davor umzuschauen. Vorausschauendes, langsames Fahren ist hier oberstes Gebot, um niemanden zu gefährden!"],"i":["https://video2.kalaiwa.de/assets/1441109.webp"],"rn":502},{"n":"1.4.41-114","t":"Wer darf auf dieser Straße mit einem Kraftfahrzeug fahren?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Wer jemanden besuchen will","Wer Waren liefern muss","Wer etwas einkaufen will"],"co":[1],"ex":["Zu Fuß darf man diese Strecke verwenden, um jemanden zu besuchen. Mit dem Fahrzeug darf hier allerdings nicht durchgefahren werden.","Eine so beschilderte Straße darf lediglich von Fahrzeugen des Lieferverkehrs, nicht aber von anderen Fahrzeugen genutzt werden. Zudem dürfen Fußgänger diesen Weg benutzen.","Der Einkauf in einem Geschäft ist keine Liefertätigkeit. Zu Fuß darf hier eingekauft werden, das Auto darf hierfür jedoch nicht genutzt werden."],"i":["https://video4.kalaiwa.de/assets/1441114.webp"],"rn":503},{"n":"1.4.41-115","t":"Welche Fahrzeuge dürfen den so gekennzeichneten Sonderfahrstreifen benutzen?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Pkws","Lkws","Linienbusse"],"co":[2],"ex":["PKWs dürfen diesen Fahrstreifen nicht benutzen.","LKWs ist die Nutzung dieses Fahrstreifens nicht gestattet.","Nur Omnibusse dürfen diesen Sonderfahrstreifen benutzen."],"i":["https://video4.kalaiwa.de/assets/1441115.webp"],"rn":504},{"n":"1.4.41-116","t":"Wer darf in eine so beschilderte Straße einfahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Bewohner","Besucher der Bewohner","Fahrzeuge im Durchgangsverkehr"],"co":[0,1],"ex":["Bewohner sind Anlieger und dürfen folglich das Schild passieren.","Besucher der Bewohner dieser Straße sind Anlieger. Ihnen ist es gestattet, in die so beschilderte Straße einzufahren.","Diesen Fahrzeugen ist die Durchfahrt untersagt."],"i":["https://video2.kalaiwa.de/assets/1441116.webp"],"rn":505},{"n":"1.4.41-118","t":"Welche Fahrzeuge dürfen eine so beschilderte Straße nicht befahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Pkws","Lkws","Motorräder"],"co":[0,1],"ex":["Der PKW ist ein mehrspuriges Kraftfahrzeug und darf somit die so beschilderte Straße nicht passieren.","Das Verkehrszeichen verbietet allen mehrspurigen Kraftfahrzeugen die dahinterliegende Straße zu befahren. Es bezieht sich nicht nur auf PKWs -wie auf dem Zeichen abgebildet- sondern auch auf andere Fahrzeuge wie LKWs oder Busse.","Motorräder zählen nicht zu den mehrspurigen Kraftfahrzeugen und dürften somit auch eine so beschilderte Straße befahren."],"i":["https://video2.kalaiwa.de/assets/1441118.webp"],"rn":506},{"n":"1.4.41-119","t":"Welche Fahrzeuge dürfen eine so beschilderte Straße nicht befahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Motorräder","Pkws","Fahrräder"],"co":[2],"ex":["Würde dieses Verkehrsverbot für Motorräder gelten, müsste das Symbol ein Motorrad sein.","Würde dieses Verbot für PKWs gelten, dann müsste das Symbol auf dem Schild einen PKW zeigen. Dies würde ein Verkehrsverbot für mehrspurige Kraftfahrzeuge sein und somit zusätzlich LKWs und Busse miteinbeziehen.","Das Verkehrszeichen bedeutet \"Verbot für Fahrräder\". Es gehört zu der Gruppe der Verkehrsverbote."],"i":["https://video2.kalaiwa.de/assets/1441119.webp"],"rn":507},{"n":"1.4.41-120","t":"Welche Fahrzeuge dürfen eine so beschilderte Straße nicht befahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Lkws","Motorräder","Pkws"],"co":[1],"ex":["Das Symbol für ein Verkehrsverbot für LKW wäre ein von der Seite abgebildeter LKW.","Alle Arten von Motorrädern, auch mit Beiwagen, Kleinkrafträder und Mofas, dürfen hier nicht fahren. Allerdings besteht die Möglichkeit, das Kraftrad zu schieben.","Das Symbol für ein Verkehrsverbot für PKW wäre ein von vorne abgebildetes Auto."],"i":["https://video4.kalaiwa.de/assets/1441120.webp"],"rn":508},{"n":"1.4.41-121","t":"Worauf weisen diese Verkehrszeichen hin?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Auf eine Zollstelle in 100 m Entfernung","Auf eine Einbahnstraße von 100 m Länge","Auf das Verbot der Einfahrt in 100 m Entfernung"],"co":[2],"ex":["Das Verkehrszeichen für eine Zollstelle ist ein Kreis mit rotem Rand und der Aufschrift Zoll/Douane.","Dieses Verkehrszeichen steht oft am Ende einer Einbahnstraße, um dadurch die Fahrzeuge an einem falschen Einfahren in die Straße zu hindern. Das Verkehrszeichen für Einbahnstraße ist ein weißer Pfeil auf blauem Grund, auf dem \"Einbahnstraße\" steht.","Das Verkehrszeichen weist auf ein Verbot der Einfahrt in 100 m hin."],"i":["https://video4.kalaiwa.de/assets/1441121.webp"],"rn":509},{"n":"1.4.41-124","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- vorgeschriebenen Mindestgeschwindigkeit von 30 km/h","- zulässigen Höchstgeschwindigkeit von 30 km/h","- Richtgeschwindigkeit von 30 km/h"],"co":[1],"ex":["Das Verkehrszeichen \"Vorgeschriebene Mindestgeschwindigkeit 30 km/h\" wäre die Zahl 30 in weißer Schrift auf blauem Kreis.","Das Verkehrszeichen symbolisiert den Beginn einer Zone mit zulässiger Höchstgeschwindigkeit 30 (Tempo-30-Zone).","Das Verkehrszeichen für \"Richtgeschwindigkeit von 30 km/h\" wäre die Zahl 30 in weißer Schrift auf blauem Viereck."],"i":["https://video2.kalaiwa.de/assets/1441124.webp"],"rn":510},{"n":"1.4.41-125","t":"Hier beginnt ein verkehrsberuhigter Geschäftsbereich. Wie müssen Sie sich verhalten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Höchstparkdauer beachten","Mindestgeschwindigkeit von 20 km/h einhalten","Auf regen Fußgängerverkehr besonders achten"],"co":[0,2],"ex":["Das Zusatzschild erlaubt eine Höchstparkdauer von 2 Stunden mit einer Parkscheibe. Diese darf nicht überschritten werden.","Das oberste Verkehrszeichen bedeutet \"zulässige Höchstgeschwindigkeit in dieser Zone 20 km/h\". Das Verkehrszeichen für eine Mindestgeschwindigkeit ist eine weiße Zahl auf einem blauen Kreis.","In Geschäftsbereichen ist damit zu rechnen, dass Passanten ohne besonders auf den Verkehr zu achten, von einer Straßenseite auf die andere wechseln. Deshalb solltest du hier besonders aufmerksam sein."],"i":["https://video4.kalaiwa.de/assets/1441125.webp"],"rn":511},{"n":"1.4.41-126","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- Richtgeschwindigkeit von 30 km/h","- zulässigen Höchstgeschwindigkeit von 30 km/h","- vorgeschriebenen Mindestgeschwindigkeit von 30 km/h"],"co":[1],"ex":["Das Verkehrsschild einer vorgeschriebenen Richtgeschwindigkeit von 30 km/h wäre eine weiße 30 auf einem blaue, quadratischen Schild.","Das Verkehrszeichen symbolisiert das Ende einer Zone, deren zulässige Höchstgeschwindigkeit auf 30 km/h beschränkt ist.","Das Verkehrsschild für eine vorgeschriebenen Mindestgeschwindigkeit von 30 km/h wäre eine weiße 30 auf einem blauen, runden Hintergrund."],"i":["https://video2.kalaiwa.de/assets/1441126.webp"],"rn":512},{"n":"1.4.41-129","t":"Welche Fahrzeuge dürfen Sie bei diesem Verkehrszeichen überholen?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Motorrad ohne Beiwagen","Pkw","Motorrad mit Beiwagen"],"co":[0],"ex":["Dieses Verkehrszeichen ordnet an, dass mehrspurige Kraftfahrzeuge und Motorräder mit Beiwagen nicht überholt werden dürfen. Ein Motorrad ohne Beiwagen ist ein einspuriges Kraftfahrzeug und darf somit überholt werden.","PKW zählen zur Gruppe der mehrspurigen Kraftfahrzeuge und dürfen somit nicht überholt werden.","Ein Motorrad mit einem Beiwagen ist zwar kein zweispuriges Kraftfahrzeug, ist aber aufgrund seiner Breite auch von diesem Verbot betroffen. Daher ist auch das Überholen von Motorrädern mit Beiwagen nicht erlaubt."],"i":["https://video4.kalaiwa.de/assets/1441129.webp"],"rn":513},{"n":"1.4.41-130","t":"Worauf weisen diese Verkehrszeichen hin?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Auf ein Überholverbot, das in 3 km Entfernung beginnt","Auf eine Überholverbotsstrecke von 3 km Länge","Auf eine Fahrbahn mit zwei Fahrstreifen für eine Richtung von 3 km Länge"],"co":[1],"ex":["Die beiden Pfeile geben an, wie lange das Verbot gilt. Ohne diese Pfeile wäre es eine Angabe, ab wo das Verbot gilt.","Das Verkehrszeichen zeigt ein Überholverbot. Das Zusatzzeichen bedeutet, dass dieses Überholverbot auf einer Strecke von 3 km gilt.","Die beiden Fahrzeuge nebeneinander könnten irrtümlicherweise als 2 Fahrstreifen für eine Fahrbahn gedeutet werden. Das ist falsch. Das Verkehrszeichen weist auf ein Überholverbot von 3 km Länge hin."],"i":["https://video4.kalaiwa.de/assets/1441130.webp"],"rn":514},{"n":"1.4.41-131","t":"Worauf weisen diese Verkehrszeichen hin?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Auf eine Überholverbotsstrecke von 200 m Länge","Auf ein Überholverbot, das nach 200 m endet","Auf ein Überholverbot, das in 200 m Entfernung beginnt"],"co":[2],"ex":["Würde es sich um ein Überholverbot von 200 m Länge handeln, dann wären an dem Zusatzschild zwei schwarze Pfeile nach oben angebracht.","Das Verkehrsschild, das für ein Ende des Überholverbotes steht, ist das durchgestrichene Überholverbotszeichen, komplett in grau mit weißem Grund.","Das Verkehrszeichen weist auf ein Überholverbot hin, das in 200 Metern beginnt."],"i":["https://video4.kalaiwa.de/assets/1441131.webp"],"rn":515},{"n":"1.4.41-133","t":"Welche Verbote werden mit diesem Verkehrszeichen aufgehoben?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Parkverbote","Geschwindigkeitsbeschränkungen","Überholverbote"],"co":[1,2],"ex":["Parkverbote sind keine Streckenverbote und werden somit durch dieses Zeichen auch nicht aufgehoben.","Dieses Verkehrsschild signalisiert ein Ende aller Streckenverbote. Das bedeutet, dass vorherig angeordnete Geschwindigkeitsbeschränkungen aufgehoben werden.","Dieses Verkehrszeichen hebt alle Streckenverbote auf. Dies bezieht sich, neben Geschwindigkeitsbeschränkungen, auf vorherig angeordnete Überholverbote."],"i":["https://video4.kalaiwa.de/assets/1441133.webp"],"rn":516},{"n":"1.4.41-134","t":"Worauf weisen diese Verkehrszeichen hin?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- das auf der Fahrbahn und auch auf dem Seitenstreifen gilt","- das nur auf dem Seitenstreifen gilt","- das nur für Lkws gilt"],"co":[0],"ex":["Das entspricht exakt der Beschilderung.","Das Zusatzschild \"Haltverbot auch auf dem Seitenstreifen\" erweitert das Halteverbot. Es schränkt es nicht ein. Eine Einschränkung des Haltverbotes, welches sich nur auf den Seitenstreifen bezieht, müsste mit dem Zusatzschild \"Auf dem Seitenstreifen\" angezeigt werden.","Das Haltverbot gilt für alle Verkehrsteilnehmer und somit auch für LKWs."],"i":["https://video4.kalaiwa.de/assets/1441134.webp"],"rn":517},{"n":"1.4.41-135","t":"Was ist in der hier beginnenden Zone erlaubt?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Das Halten bis zu 3 Minuten","Das Parken, wenn eine Parkscheibe benutzt wird","Das Halten zum Be- oder Entladen sowie zum Aus- oder Einsteigen"],"co":[0,2],"ex":["In dieser Zone darf bis zu 3 Minuten gehalten werden.","Ein Parken ist verboten, sofern andere Verkehrszeichen dies nicht ausdrücklich erlauben. Zum Parken mit Parkscheibe müsste dies durch ein Verkehrszeichen ausgeschildert sein.","Zum Be- und Entladen eines Fahrzeugs sowie zum Ein- und Aussteigen darf in dieser Zone gehalten werden."],"i":["https://video4.kalaiwa.de/assets/1441135.webp"],"rn":518},{"n":"1.4.41-136","t":"Was endet hier?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Eine Zone mit absolutem Haltverbot","Eine Zone mit eingeschränktem Haltverbot","Vorausgegangene Streckenverbote"],"co":[1],"ex":["Es gibt kein Verkehrsschild, das ganze Zonen mit absolutem Haltverbot ausweist. Verkehrszeichen, die Halteverbote kennzeichnen, zeigen einen roten Kreis auf blauem Untergrund mit rotem Kreuz und weißen Pfeilen, die Beginn, Verlauf und Ende von Halteverboten ausweisen.","Nach diesem Verkehrsschild darf wieder geparkt werden.","Mit diesem Schild wird nur das eingeschränkte Haltverbot aufgehoben. Ein Verkehrszeichen, das sämtliche Streckenverbote aufhebt, zeigt drei schwarze diagonale Striche von links unten nach rechts oben auf einem weißen, runden Hintergrund."],"i":["https://video4.kalaiwa.de/assets/1441136.webp"],"rn":519},{"n":"1.4.41-141","t":"Sie nähern sich folgender Verkehrszeichen-Kombination. Was ist hier zu beachten?","p":4,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Die im Kreis befindlichen Fahrzeuge haben Vorfahrt","Beim Einfahren in den Kreis muss geblinkt werden","Das Verlassen des Kreises muss durch Blinken angezeigt werden"],"co":[0,2],"ex":["Die beiden Verkehrszeichen legen fest, dass die Fahrzeuge im Kreisverkehr Vorfahrt gegenüber anderen Fahrzeugen, die in den Kreisverkehr einfahren, haben.","Das Verkehrszeichen signalisiert, dass man beim Einfahren in den Kreisverkehr den darin befindlichen Fahrzeugen Vorfahrt gewähren muss.","Fahrzeugführer müssen das Verlassen des Kreisverkehrs durch Blinken anzeigen."],"i":["https://video2.kalaiwa.de/assets/1441141.webp"],"rn":520},{"n":"1.4.41-145","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Auf Radfahrer, die die Fahrbahn kreuzen","Auf ein Verbot für Radfahrer","Auf einen benutzungspflichtigen Radweg"],"co":[2],"ex":["Nein, darauf weist dieses Verkehrszeichen nicht hin.","Ein Verbotsschild für Radfahrer zeigt ein schwarzes Fahrrad auf weißem Grund mit rotem runden Rahmen.","Darauf weist dieses Verkehrszeichen hin."],"i":["https://video4.kalaiwa.de/assets/1441145.webp"],"rn":521},{"n":"1.4.41-146","t":"Was wird durch diese Verkehrszeichenkombination angekündigt?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- „Halt. Vorfahrt gewähren.“","- „Vorfahrt gewähren.“","- „Vorrang des Gegenverkehrs“"],"co":[0],"ex":["Du musst in 100 m den anderen Verkehrsteilnehmern die Vorfahrt gewähren.","Hier musst du noch keine Vorfahrt gewähren. Erst in 100 m kommt das Verkehrsschild.","Du musst in 100 m anderen Verkehrsteilnehmern die Vorfahrt gewähren."],"i":["https://video2.kalaiwa.de/assets/1441146.webp"],"rn":522},{"n":"1.4.41-147","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Auf einen Gehweg","Auf den Beginn eines verkehrsberuhigten Bereichs","Auf ein Verbot für Fahrrad- und Mofa-Verkehr"],"co":[0,2],"ex":["Das Verkehrszeichen weist auf einen Gehweg, einen Weg für Fußgänger also, hin.","Das Verkehrszeichen, das einen verkehrsberuhigten Bereich ausschildert, ist ein anderes.","Hier dürfen nur Fußgänger laufen."],"i":["https://video2.kalaiwa.de/assets/1441147.webp"],"rn":523},{"n":"1.4.41-149","t":"Wie müssen Sie sich in dieser Straße verhalten, wenn Sie ein Kraftfahrzeug im Lieferverkehr fahren?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich muss auf Fußgänger besondere Rücksicht nehmen","Wenn keine Personen in der Nähe sind, darf ich schneller als Schrittgeschwindigkeit fahren","Ich darf nur mit Schrittgeschwindigkeit fahren"],"co":[0,2],"ex":["Du befindest dich in einer Fußgängerstraße. Daher musst du auf diese besondere Rücksicht nehmen.","Du musst hier mit Schrittgeschwindigkeit fahren.","Du musst hier mit Fußgängern rechnen und darfst diese nicht behindern."],"i":["https://video2.kalaiwa.de/assets/1441149.webp"],"rn":524},{"n":"1.4.41-152","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich darf nur geradeaus weiterfahren","Ich habe Vorrang vor dem Gegenverkehr","Ich befinde mich in einer Einbahnstraße"],"co":[0],"ex":["Dieses Verkehrszeichen schreibt vor, dass du nur geradeaus weiterfahren darfst.","Das Verkehrszeichen berechtigt dich nicht zur Vorfahrt. Es schreibt dir die Fahrtrichtung vor.","Das Verkehrszeichen, das eine Einbahnstraße ausweist, ist ein anderes. Hier wird dir die Fahrtrichtung vorgeschrieben."],"i":["https://video2.kalaiwa.de/assets/1441152.webp"],"rn":525},{"n":"1.4.41-153","t":"Wie verhalten Sie sich bei diesem Verkehrszeichen?","p":4,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich fahre bremsbereit mit mäßiger Geschwindigkeit heran","Wenn ich rechts abbiege, bin ich nicht wartepflichtig","Ich gewähre dem Querverkehr die Vorfahrt"],"co":[0,2],"ex":["Du musst dich darauf einstellen, bei Querverkehr anzuhalten, um diesem die Vorfahrt zu gewähren.","Du bist dem Querverkehr gegenüber in der Wartepflicht.","Dieses Verkehrszeichen weist dich an, dem Querverkehr die Vorfahrt zu gewähren."],"i":["https://video2.kalaiwa.de/assets/1441153.webp"],"rn":526},{"n":"1.4.41-154","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Auf einen Reitweg, dessen Benutzung für andere Verkehrsteilnehmer verboten ist","Auf einen Reitweg, den Reiter benutzen müssen","Auf einen Weg, dessen Benutzung für Reiter verboten ist"],"co":[0,1],"ex":["Nur Reiter dürfen diesen Weg nehmen. Anderen Verkehrsteilnehmern ist er untersagt.","Diesen Weg müssen und dürfen ausschließlich Reiter benutzen.","Reiter müssen diesen Weg sogar benutzen."],"i":["https://video2.kalaiwa.de/assets/1441154.webp"],"rn":527},{"n":"1.4.41-156","t":"Wie müssen Sie sich in dieser Verkehrssituation verhalten?","p":4,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- nur bei Querverkehr anhalten","- an der Sichtlinie anhalten und Vorfahrt gewähren","- nicht anhalten, da keine Haltlinie vorhanden ist"],"co":[1],"ex":["Du musst allen Verkehrsteilnehmern, die die Kreuzung passieren möchten, die Vorfahrt gewähren.","Hier ist keine Haltlinie eingezeichnet. Daher musst du aufgrund des \"Stopp\"-Schildes an der Sichtlinie halten und den übrigen Verkehrsteilnehmern die Vorfahrt gewähren.","Du musst an der Sichtlinie anhalten und die Vorfahrt gewähren."],"i":["https://video4.kalaiwa.de/assets/1441156.webp"],"rn":528},{"n":"1.4.41-159","t":"Was müssen Sie bei diesem Verkehrszeichen beachten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich muss links blinken","Ich darf nicht blinken","Ich darf nur nach links weiterfahren"],"co":[0,2],"ex":["Jede Fahrtrichtungsänderung, auch wenn sie vorgeschrieben ist, muss durch Blinken angezeigt werden.","Du musst nach links blinken und fahren.","Dieses Verkehrszeichen schreibt dir die Fahrtrichtung nach links vor."],"i":["https://video2.kalaiwa.de/assets/1441159.webp"],"rn":529},{"n":"1.4.41-160","t":"Was gilt bei diesem Verkehrszeichen?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich bin verpflichtet, nach links abzubiegen","Ich muss an Hindernissen links vorbeifahren","Ich darf vor dem Zeichen nicht nach rechts abbiegen"],"co":[1],"ex":["Du musst links an einem Hindernis vorbeifahren.","Das ist die vorgeschriebene Richtung, in der du vorbeifahren musst.","Du darfst vor dem Zeichen rechts abbiegen, wenn keine anderen Verkehrsschilder dies verbieten. Am Hindernis musst du allerdings links vorbeifahren."],"i":["https://video2.kalaiwa.de/assets/1441160.webp"],"rn":530},{"n":"1.4.41-161","t":"Was gilt in dem Bereich von 15 m vor und hinter diesem Verkehrszeichen?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- ein- oder aussteigende Fahrgäste nicht behindern","- parken","- halten"],"co":[0,2],"ex":["Du musst hier besondere Aufmerksamkeit auf ein- und aussteigende Personen haben. Halte dich bremsbereit und fahre mit Schrittgeschwindigkeit, wenn hier ein Bus hält oder Personen auf der Fahrbahn sind.","Das Parken ist hier untersagt.","Im Bereich 15 m vor und hinter dem Haltestellenzeichen darfst du halten, wenn du hierbei niemanden behinderst."],"i":["https://video2.kalaiwa.de/assets/1441161.webp"],"rn":531},{"n":"1.4.41-162","t":"Was gilt bei diesem Verkehrszeichen?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich darf auch nach links weiterfahren","Ich muss rechts blinken","Ich darf nur nach rechts weiterfahren"],"co":[1,2],"ex":["Du darfst nur nach rechts weiterfahren.","Jede Richtungsänderung, auch wenn vorgeschrieben, muss durch Blinken angezeigt werden. Somit musst du hier rechts blinken.","Das Verkehrszeichen besagt \"Vorgeschriebene Fahrtrichtung rechts\". Folglich musst du nach rechts weiterfahren."],"i":["https://video2.kalaiwa.de/assets/1441162.webp"],"rn":532},{"n":"1.4.41-163","t":"Was gilt bei diesem Verkehrszeichen?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich darf parken","Ich darf halten","Ich muss mit an- und abfahrenden Taxis rechnen"],"co":[2],"ex":["Es dürfen ausschließlich Taxen parken.","Es dürfen ausschließlich Taxen halten.","Das Verkehrszeichen kennzeichnet einen Taxenstand. Somit kannst du davon ausgehen, dass hier Taxen an- und abfahren."],"i":["https://video2.kalaiwa.de/assets/1441163.webp"],"rn":533},{"n":"1.4.41-164","t":"Worauf weist diese Verkehrszeichenkombination hin?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- von Wintersportlern benutzt werden","- im Winter nicht befahren werden","- nur mit Schneeketten benutzt werden"],"co":[0],"ex":["Die Verkehrszeichenkombination besagt \"Achtung, Wintersportler!\". Du kannst davon ausgehen, dass hier Wintersportler die Fahrbahn kreuzen.","Die Straße darf befahren werden, allerdings mit besonderer Aufmerksamkeit auf Wintersportler, die die Straße kreuzen könnten.","Schneeketten sind hier nicht verpflichtend."],"i":["https://video2.kalaiwa.de/assets/1441164.webp"],"rn":534},{"n":"1.4.41-165","t":"Was müssen Sie in dieser Verkehrssituation beachten?","p":4,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- nicht überfahren","- überfahren, wenn es der Gegenverkehr zulässt","- zum Überholen überfahren"],"co":[0],"ex":["Die Fahrstreifenbegrenzung zeigt eine durchgezogene Linie. Du darfst diese also nicht überfahren.","Du darfst diese Linie unabhängig vom Gegenverkehr nicht überfahren.","Die durchgezogene Linie darf nicht überfahren werden. Somit ist auch Überholen verboten."],"i":["https://video2.kalaiwa.de/assets/1441165.webp"],"rn":535},{"n":"1.4.41-167","t":"Sie möchten überholen. Was ist richtig?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- nicht überholen","- nur überholen, wenn ich dabei im rechten Fahrstreifen bleibe","- überholen"],"co":[2],"ex":["Du darfst überholen.","So würdest du den Radfahrer gefährden. Du darfst den linken Fahrstreifen zum Überholen nutzen und dies tun, wenn es der Gegenverkehr zulässt.","Wenn es der Gegenverkehr zulässt und du ausreichend Sicherheitsabstand zum Radfahrer einhalten kannst, darfst du überholen."],"i":["https://video2.kalaiwa.de/assets/1441167.webp"],"rn":536},{"n":"1.4.41-168","t":"Sie möchten als Anlieger in eine so gekennzeichnete Fahrradstraße einfahren. Was müssen Sie dabei beachten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Radverkehr darf nicht behindert werden","Fahrzeuge dürfen nicht schneller als 30 km/h fahren","Fahrräder dürfen nebeneinander fahren"],"co":[0,1,2],"ex":["Radfahrer haben Vorrang. Der Radverkehr darf nicht behindert werden. Du musst ggf. deine Geschwindigkeit weiter verringern.","In einer Fahrradstraße gilt für Fahrzeuge die Höchstgeschwindigkeit von 30 km/h.","Es ist eine Fahrradstraße, weswegen diese nebeneinander fahren dürfen. Sie müssen nicht auf Pkws Rücksicht nehmen."],"i":["https://video4.kalaiwa.de/assets/1441168.webp"],"rn":537},{"n":"1.4.41-169","t":"Wer darf in eine so gekennzeichnete Straße einfahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Alle Mofafahrer","Alle Besucher von Anwohnern","Alle Radfahrer"],"co":[1,2],"ex":["Das Verkehrszeichen sagt dir, dass es sich um eine Fahrradstraße handelt. Mofafahrer dürfen nicht in die Straße einfahren.","Das Zusatzzeichen \"Anlieger frei\" sagt dir, dass Anwohner oder Besucher von Anwohnern in die Straße einfahren dürfen.","Da es sich um eine Fahrradstraße handelt, dürfen alle Radfahrer in eine solche Straße einfahren."],"i":["https://video2.kalaiwa.de/assets/1441169.webp"],"rn":538},{"n":"1.4.41-170","t":"Ihr Fahrstreifen ist mit diesem Verkehrszeichen gekennzeichnet. Was müssen Sie beachten?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich muss mindestens 60 km/h fahren, wenn es die Straßen- und Verkehrsverhältnisse zulassen","Ich benutze diesen Fahrstreifen nur, wenn mein Fahrzeug mindestens 60 km/h fahren kann und dies auch darf","Ich darf nicht schneller als 60 km/h fahren"],"co":[0,1],"ex":["Dieses Verkehrszeichen gibt die vorgeschriebene Mindestgeschwindigkeit an. Du musst also mindestens 60 km/h fahren, sofern es möglich ist.","Da es sich dabei um die vorgeschriebene Mindestgeschwindigkeit handelt, muss dein Fahrzeug mindestens 60 km/h fahren können.","Das Verkehrszeichen für die zulässige Höchstgeschwindigkeit ist weiß mit roter Umrandung."],"i":["https://video2.kalaiwa.de/assets/1441170.webp"],"rn":539},{"n":"1.4.41-171","t":"Mit welcher Geschwindigkeit dürfen Fahrzeuge in einer so gekennzeichneten Zone höchstens fahren?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","na":"30 km/h","e":"Radfahrer, Elektrokleinstfahrzeuge und andere zugelassene Fahrzeuge dürfen in Fahrradzonen höchstens 30 km/h fahren.","i":["https://video2.kalaiwa.de/assets/1441171.webp"],"rn":540},{"n":"1.4.41-172","t":"Was gilt bei diesem Verkehrszeichen?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- zwischen 6 und 22 Uhr gilt","- zwischen 22 und 6 Uhr gilt","- nicht für Elektrofahrzeuge gilt"],"co":[1],"ex":["Die Geschwindigkeitsbegrenzung dient dem Lärmschutz und bezieht sich auf den Zeitraum zwischen 22 und 6 Uhr.","Das Verkehrszeichen zeigt an, dass die Höchstgeschwindigkeit zwischen 22 und 6 Uhr auf 30 km/h begrenzt ist.","Die Geschwindigkeitsbegrenzung zwischen 22 und 6 Uhr gilt für alle Fahrzeuge, auch für Elektrofahrzeuge."],"i":["https://video4.kalaiwa.de/assets/1441172.webp"],"rn":541},{"n":"1.4.41-173","t":"Wie müssen Sie sich bei diesem Verkehrszeichen verhalten?","p":2,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- vor dem Verkehrszeichen nach links abbiegen","- hinter dem Verkehrszeichen nach links abbiegen","- links blinken"],"co":[0,2],"ex":["Der gerade Pfeil auf dem Verkehrszeichen zeigt dir an, dass du vor dem Schild nach links abbiegen musst.","Du darfst nicht erst nach dem Verkehrsschild nach links abbiegen, da der Pfeil auf dem Schild gerade ist. Ein gerader Pfeil zeigt an, dass du direkt vor dem Schild abbiegen musst.","Du musst links blinken, da das Verkehrsschild dir anzeigt, dass du nach links abbiegen musst."],"i":["https://video4.kalaiwa.de/assets/1441173.webp"],"rn":542},{"n":"1.4.41-174","t":"Bei welchem Verkehrszeichen ist das Wenden verboten?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video4.kalaiwa.de/assets/1441174o3.png","https://video2.kalaiwa.de/assets/1441174o1.png","https://video4.kalaiwa.de/assets/1441174o2.png"],"co":[0,1,2],"ex":["Das Verkehrszeichen signalisiert dir, dass hier ein Tunnel beginnt. Im Tunnel ist das Wenden strengstens verboten.","Das Verkehrszeichen zeigt dir an, dass das Wenden hier verboten ist.","Dieses Verkehrsschild zeigt dir an, dass du dich auf einer Autobahn befindest. Auf der Autobahn ist das Wenden strengstens verboten."],"rn":543},{"n":"1.4.41-175","t":"Ab welchem Verkehrszeichen dürfen Sie eine zulässige Höchstgeschwindigkeit von 60 km/h nicht überschreiten?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video4.kalaiwa.de/assets/1441175o3.png","https://video4.kalaiwa.de/assets/1441175o2.png","https://video2.kalaiwa.de/assets/1441175o1.png"],"co":[2],"ex":["Dieses Verkehrszeichen zeigt dir an, dass auf dieser Straße eine Mindestgeschwindigkeit von 60 km/h vorgegeben ist. Fahrzeuge, die bauartbedingt nicht mindestens 60 km/h fahren können, dürfen diese Straße nicht befahren. Solange die Straßenverhältnisse und die Wetterlage es zulassen, solltest du nicht langsamer als 60 km/h fahren.","Das Verkehrsschild zeigt dir an, dass die zulässige Höchstgeschwindigkeit von 60 km/h aufgehoben ist. Nach dem Schild darfst du demnach schneller als 60 km/h fahren.","Auf einer Straße mit diesem Verkehrszeichen darfst du die zulässige Höchstgeschwindigkeit von 60 km/h nicht überschreiten."],"rn":544},{"n":"1.4.41-020-M","t":"Was gilt in dieser Situation?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- nicht befahren","- zum Wenden befahren","- bei einem Stau nutzen"],"co":[0],"ex":["Eine Sperrfläche darf grundsätzlich nicht befahren werden.","Eine Sperrfläche darf in keinem Fall befahren werden, auch nicht um zu wenden.","Auch im Falle eines Staus darf die Sperrfläche nicht befahren werden."],"i":["https://video4.kalaiwa.de/assets/1441020m.webp"],"rn":545},{"n":"1.4.41-026-M","t":"Was ist in dieser Situation richtig?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- nach dem entgegenkommenden Pkw durchfahren","- vor dem entgegenkommenden Pkw durchfahren","- nur mit Schrittgeschwindigkeit durchfahren"],"co":[0],"ex":["Das Schild zeigt an, dass du dem Gegenverkehr an der Engstelle Vorrang gewähren musst. Der entgegenkommende Pkw ist schon nah an der Engstelle. Warte, um ihn ohne Gefährdung passieren zu lassen.","Du darfst die Engstelle erst nach dem entgegenkommenden Pkw durchfahren, da der Gegenverkehr Vorrang hat.","Es gibt keinen Grund, die Geschwindigkeit weiter zu reduzieren. Achte aber die Vorfahrt des Gegenverkehrs."],"i":["https://video2.kalaiwa.de/assets/1441026m.webp"],"rn":546},{"n":"1.4.41-028-M","t":"Was gilt an dieser Kreuzung?","p":4,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- nach rechts abbiegen","- die Kreuzung überqueren","- nach links abbiegen"],"co":[1],"ex":["Nach rechts darfst du nicht abbiegen, da es sich um eine Fahrradstraße handelt, in die du nicht einbiegen darfst.","Du musst nicht unbedingt am Verkehrsschild „Vorfahrt gewähren“ anhalten und darfst die Kreuzung vorsichtig überqueren, da kein Verkehr von rechts oder links zu sehen ist.","Du darfst nicht nach links abbiegen, da dort eine Fahrradstraße ist, in der keine anderen Fahrzeuge erlaubt sind."],"i":["https://video4.kalaiwa.de/assets/1441028m.webp"],"rn":547},{"n":"1.4.41-140-B","t":"Wann müssen Sie blinken?","p":3,"c":"1.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Beim Verlassen des Kreisverkehrs","Beim Einfahren in den Kreisverkehr"],"co":[0],"ex":["Die Richtung, in die in den Kreisverkehr eingefahren wird, ist nach rechts vorgegeben. Deswegen muss beim Einfahren nicht geblinkt werden.","Um anderen Verkehrsteilnehmern das Verlassen des Kreisverkehrs zu signalisieren, muss beim Herausfahren geblinkt werden."],"i":["https://video2.kalaiwa.de/assets/1441140b.webp"],"rn":548},{"n":"1.4.42-001","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- nur an der nächsten Kreuzung oder Einmündung","- an allen Kreuzungen und Einmündungen dieser Straße","- bis zum Ortsende"],"co":[0],"ex":["Laut StVO § 42 Abs. 2 bedeutet dieses Verkehrszeichen \"Vorfahrt\" an der nächsten Kreuzung oder Einmündung.","Soll die Vorfahrt an allen Kreuzungen und Einmündungen gelten, dann wird dies durch das Verkehrszeichen \"Vorfahrtsstraße\" angezeigt.","Ein Verkehrsschild, dass die Vorfahrt bis zum Ortsende gewährt, gibt es nicht."],"i":["https://video2.kalaiwa.de/assets/1442001.webp"],"rn":549},{"n":"1.4.42-005","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf den Anfang einer Kraftfahrstraße","Auf den Anfang einer Autobahn","Auf das Ende der Autobahn"],"co":[1],"ex":["Das Verkehrszeichen für den Anfang einer Kraftfahrstraße ist ein weißer PKW auf einem blauen Viereck.","Das dargestellte Verkehrszeichen weist auf den Beginn einer Autobahn hin.","Das Verkehrszeichen für das Ende einer Autobahn ist dieses Verkehrszeichen mit einem roten diagonalen Strich darauf."],"i":["https://video2.kalaiwa.de/assets/1442005.webp"],"rn":550},{"n":"1.4.42-011","t":"Ab welchem Verkehrszeichen dürfen Sie nur mit Schrittgeschwindigkeit weiterfahren?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video2.kalaiwa.de/assets/1442011o3.png","https://video4.kalaiwa.de/assets/1442011o1.png","https://video2.kalaiwa.de/assets/1442011o2.png"],"co":[1],"ex":["Dieses Verkehrsschild bedeutet „Schleuder- und Rutschgefahr bei Nässe oder Schmutz auf der Fahrbahn“. Eine Schrittgeschwindigkeit ist hierbei nicht vorgegeben. Falls nötig, solltest Du jedoch deine Geschwindigkeit verringern, um rechtzeitig auf Gefahrensituationen reagieren zu können.","Das Verkehrsschild zeigt dir an, dass ein verkehrsberuhigter Bereich beginnt. Hier darfst du mit deinem Fahrzeug nur in Schrittgeschwindigkeit fahren, da du jederzeit mit Fußgängern oder spielenden Kindern rechnen musst.","Diese Verkehrszeichen-Kombination kündigt dir einen Kreisverkehr mit Vorfahrtsregelung an. Eine \"Schrittgeschwindigkeit\" gibt dieses Schild jedoch nicht vor."],"rn":551},{"n":"1.4.42-012","t":"Bei welchem Verkehrszeichen haben Sie an der nächsten Kreuzung grundsätzlich Vorfahrt?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["","",""],"oi":["https://video2.kalaiwa.de/assets/1442012o3.png","https://video4.kalaiwa.de/assets/1442012o2.png","https://video2.kalaiwa.de/assets/1442012o1.png"],"co":[2],"ex":["Dieses Verkehrsschild zeigt dir an, dass du auf der verengten Fahrbahn Vorrang vor dem Gegenverkehr hast. Allerdings regelt das Schild nicht die Vorfahrt an der nächsten Kreuzung. Soweit nichts anderes angezeigt ist, musst du an der nächsten Kreuzung die „rechts vor links\"-Regel beachten.","Dieses Verkehrszeichen weist dich auf eine „Kreuzung oder Einmündung mit Vorfahrt von rechts“ hin. Demnach hast du keine Vorfahrt und musst den Fahrzeugen von rechts Vorrang gewähren.","Das Verkehrszeichen signalisiert dir, dass du bei der nächsten Kreuzung Vorfahrt hast. Dieses Schild hat jedoch keine Auswirkung auf die übernächste Kreuzung."],"rn":552},{"n":"1.4.42-102","t":"Welches Verkehrszeichen gibt Vorfahrt?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Verkehrszeichen 3","Verkehrszeichen 1","Verkehrszeichen 2"],"co":[2],"ex":["Das Verkehrszeichen weist die Straße als eine Bundesstraße aus.","Das Verkehrszeichen symbolisiert \"Kurve, rechts\" und warnt vor einer scharfen Rechtskurve.","Das Verkehrszeichen symbolisiert \"Vorfahrt\" an der nächsten Kreuzung oder Einmündung."],"i":["https://video4.kalaiwa.de/assets/1442102.webp"],"rn":553},{"n":"1.4.42-104","t":"Was ist außerorts auf Vorfahrtstraßen erlaubt?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Halten am rechten Fahrbahnrand","Parken auf der Fahrbahn","Parken auf dem Seitenstreifen"],"co":[0,2],"ex":["Außerorts darf man auf Vorfahrtsstraßen am Fahrbahnrand halten.","Das Parken auf der Fahrbahn würde eine erhebliche Behinderung für den fließenden Verkehr darstellen und ist aus diesem Grund verboten.","Außerorts darf am Seitenstreifen geparkt werden, da dies den Verkehr nicht behindert."],"i":["https://video2.kalaiwa.de/assets/1442104.webp"],"rn":554},{"n":"1.4.42-107","t":"Wie verhalten Sie sich bei diesem Verkehrszeichen?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Sie müssen dem Gegenverkehr Vorrang gewähren","Ihren Vorrang dürfen Sie nur dann nutzen, wenn die Engstelle frei ist","Trotz Vorrang müssen Sie sich auf ein Anhalten einstellen"],"co":[1,2],"ex":["Der Vorrang des Gegenverkehrs würde dir mit einem anderen Verkehrszeichen angezeigt werden. Dieses ist ein roter Kreis auf weißem Untergrund, der in deiner Fahrtrichtung einen roten und in Gegenfahrtrichtung einen schwarzen Pfeil zeigt.","Es macht keinen Sinn, in die Engstelle einzufahren, wenn diese bereits durch ein entgegenkommendes Fahrzeug blockiert wird. Hierbei würde eine unnötige Behinderung oder Gefährdung entstehen.","Da an solchen Stellen häufig Fahrzeuge (trotz vorrangsberechtigten Gegenverkehrs) in die Engstelle einfahren, musst du dich auf ein jederzeit notwendiges Anhalten einstellen."],"i":["https://video4.kalaiwa.de/assets/1442107.webp"],"rn":555},{"n":"1.4.42-109","t":"Was ist bei diesen Verkehrszeichen erlaubt?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Bewohner mit entsprechend nummeriertem Parkausweis dürfen hier parken","Alle Bewohner dürfen jeden dieser Parkplätze benutzen","Solange noch andere Parkplätze frei sind, darf jeder diesen Parkplatz benutzen"],"co":[0],"ex":["Durch ein Zusatzzeichen kann die Parkerlaubnis beschränkt sein. Dies ist hier der Fall. Dann dürfen dort nur Bewohner parken, die den Parkausweis mit der vorgeschriebenen Nummer gut lesbar im Auto auslegen.","Nur Bewohner mit der auf dem Zusatzzeichen angegebenen Parkausweisnummer dürfen in diesem Bereich parken.","Nur Bewohner mit der auf dem Zusatzzeichen angegebenen Parkausweisnummer dürfen in diesem Bereich parken. Ist nur ein Verkehrszeichen mit einem weißen \"P\" auf blauem, quadratischen Untergrund abgebildet, dann darf jeder hier parken."],"i":["https://video4.kalaiwa.de/assets/1442109.webp"],"rn":556},{"n":"1.4.42-110","t":"Dürfen Sie hier parken?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Ja, als Schwerbehinderter mit amtlichem Parkausweis","Ja, für kurzfristige Einkäufe","Ja, als Begleitperson von Blinden mit amtlichem Parkausweis"],"co":[0,2],"ex":["Diesen Parkplatz dürfen Schwerbehinderte mit entsprechendem Ausweis benutzen. Der Parkplatz darf nur genutzt werden, wenn der Parkausweis gut sichtbar im Fahrzeug ausgelegt ist.","Für kurzfristige Einkäufe ist die Nutzung eines solchen Parkplatzes untersagt, da so möglicherweise ein Berechtigter an der Nutzung gehindert wird. Ein Verkehrszeichen, das generell das Parken erlaubt, ist ein weißes \"P\" auf blauem, quadratischen Untergrund. Ist nur dieses Verkehrszeichen ohne Zusatzschild angebracht, dann darf hier jeder parken.","Diesen Parkplatz dürfen Blinde mit entsprechendem Ausweis benutzen. Da Blinde nicht selbst fahren dürfen, gilt diese Vorschrift für die Begleitperson. Der Parkplatz darf nur genutzt werden, wenn der Parkausweis gut sichtbar im Fahrzeug ausgelegt ist."],"i":["https://video4.kalaiwa.de/assets/1442110.webp"],"rn":557},{"n":"1.4.42-111","t":"Was ist hier beim Parken zu beachten?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Der Parkschein muss für Kontrollen gut lesbar ausgelegt sein","Die auf dem Parkschein angegebene Parkzeit darf nicht überschritten werden","Parkschein und Parkscheibe sind gleichgestellt"],"co":[0,1],"ex":["Damit die Polizei überprüfen kann, ob die bezahlte Parkzeit auch eingehalten und nicht länger als erlaubt geparkt wurde, muss der Parkschein gut sichtbar ausgelegt werden. In der Regel wird er hinter der Windschutzscheibe ausgelegt.","Für die Dauer des Parkens muss ein Parkschein gelöst werden. Diese Zeit darf nicht überschritten werden. D.h. du darfst nicht länger dort parken, als auf dem Parkschein steht.","Wenn ein Parkschein vorgeschrieben ist, reicht eine Parkscheibe nicht aus."],"i":["https://video2.kalaiwa.de/assets/1442111.webp"],"rn":558},{"n":"1.4.42-112","t":"Welche Fahrzeuge dürfen hier parken?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Motorräder","Fahrzeuge über 3,5 t zulässiger Gesamtmasse","Fahrzeuge bis 2,8 t zulässiger Gesamtmasse"],"co":[0,2],"ex":["Motorräder dürfen hier parken.","Das Verkehrszeichen beinhaltet keine Fahrzeuge über 3,5 t zulässiger Gesamtmasse. Somit dürfen diese hier nicht parken.","Das Auto auf dem Verkehrszeichen ist ein Hinweis darauf, dass nur Fahrzeuge bis 2,8 t zulässigem Gesamtgewicht hier parken dürfen."],"i":["https://video2.kalaiwa.de/assets/1442112.webp"],"rn":559},{"n":"1.4.42-116","t":"Wie hoch muss die durch die Bauart bestimmte Höchstgeschwindigkeit eines Kraftfahrzeugs mindestens sein, wenn man diese Straße benutzen will?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["61 km/h","81 km/h","51 km/h"],"co":[0],"ex":["Durch das Verkehrszeichen wird der Beginn einer Kraftfahrstraße angezeigt. Sie darf ausschließlich von solchen Fahrzeugen benutzt werden, deren bauartbedingte Höchstgeschwindigkeit mindestens 61 km/h beträgt.","Für die Benutzung der Straße ist eine durch die Bauart bestimmte Höchstgeschwindigkeit von 61 km/h nötig. Dies ist das Minimum, um diese Straße befahren zu dürfen. Fährt ein Auto bauartbedingt höchstens 81 km/h, so darf es diese Straße aber selbstverständlich auch nutzen.","Kann ein Kraftfahrzeug bauartbedingt nur maximal 51 km/h fahren, so ist es für diese Straße nicht zugelassen, da es die Mindestgeschwindigkeit von 61 km/h unterschreitet."],"i":["https://video2.kalaiwa.de/assets/1442116.webp"],"rn":560},{"n":"1.4.42-119","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf eine für den Fahrzeugverkehr gesperrte Straße","Auf eine Sackgasse","Auf eine Unterführung"],"co":[1],"ex":["Das Verkehrszeichen für eine für den Fahrzeugverkehr gesperrte Straße ist ein roter Kreis auf weißer Fläche.","Das dargestellte Verkehrszeichen ist das Symbol der StVO für eine Sackgasse.","Es gibt für Fußgänger ein Verkehrszeichen für eine Unterführung, siehe Abbildung."],"i":["https://video2.kalaiwa.de/assets/1442119.webp"],"rn":561},{"n":"1.4.42-120","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf eine Gefahrstelle","Auf eine Kreuzung","Auf eine Erste-Hilfe-Station"],"co":[2],"ex":["Das Verkehrszeichen \"Gefahrstelle\" ist ein anderes.","Dieses Verkehrszeichen kündigt eine Erste-Hilfe-Station an, nicht eine Kreuzung.","Das Verkehrszeichen weist auf eine Erste-Hilfe-Station hin."],"i":["https://video2.kalaiwa.de/assets/1442120.webp"],"rn":562},{"n":"1.4.42-125","t":"Was ist bei diesem Verkehrszeichen zu beachten?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Fahrzeuge dürfen hier nicht geparkt werden","Die Straßenbeleuchtung brennt nicht die ganze Nacht","Fahrzeuge dürfen hier ohne Beleuchtung die ganze Nacht geparkt werden"],"co":[1],"ex":["Fahrzeuge dürfen hier parken. Allerdings müssen sie bei Dämmerung und in der Nacht ausreichend kenntlich gemacht werden. Dies kann durch das Parklicht, durch Begrenzungsleuchten (Standlicht) oder auch Park-Warntafeln geschehen.","Das Verkehrszeichen bedeutet, dass die Laterne nicht die ganze Nacht brennt.","Fahrzeuge, welche am Straßenrand parken wo dieses Zeichen angebracht ist, müssen mindesten das Parklicht einschalten oder ihr Fahrzeug auf andere Weise ausreichend kenntlich machen."],"i":["https://video2.kalaiwa.de/assets/1442125.webp"],"rn":563},{"n":"1.4.42-126","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Es muss mindestens 35 km/h gefahren werden","Es darf nicht schneller als 35 km/h gefahren werden","Auf eine Bundesstraße"],"co":[2],"ex":["Das Verkehrsschild, das die Mindestgeschwindigkeit festlegt, ist eine weiße Zahl auf blauem Kreis.","Das Verkehrsschild, das die Geschwindigkeit begrenzt, ist eine schwarze Zahl mit rot umrandeten Kreis auf weißem Hintergrund.","Das Verkehrszeichen zeigt die Nummer der Bundesstraße."],"i":["https://video2.kalaiwa.de/assets/1442126.webp"],"rn":564},{"n":"1.4.42-128","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf eine in der Regel weniger befahrene Autobahnstrecke","Auf eine vorgeschriebene Umleitung für Fahrzeuge mit gefährlichen Gütern","Auf eine Stelle, an der man die Autobahn verlassen muss"],"co":[0],"ex":["Das als „Umlenkungspfeil“ bezeichnete Verkehrszeichen soll auf eine weniger befahrene Alternativstrecke auf einer anderen Autobahn hinweisen. Die andere Strecke führt jedoch zum selben Ziel.","Die Farbgebung des Umlenkungspfeils ist verwirrend: Orange ist auch die Farbe der Warntafeln an Fahrzeugen, die Gefahrgut transportieren. Dennoch bezeichnet dieses Verkehrszeichen keine vorgeschriebene Umleitungsstrecke für Gefahrguttransporte.","Es ist nicht erforderlich die Autobahn zu verlassen, wenn dieses Schild erscheint. Es zeigt nur eine Möglichkeit auf auf einer Alternativroute zum gleichen Ziel zu gelangen. Daher ist der Umlenkungspfeil an Autobahnkreuzen und -dreiecken angebracht."],"i":["https://video4.kalaiwa.de/assets/1442128.webp"],"rn":565},{"n":"1.4.42-132","t":"Sie fahren in einen so gekennzeichneten, hell erleuchteten Tunnel. Wie verhalten Sie sich?","p":4,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Ich fahre mit Tagfahrlicht","Ich fahre ohne Licht","Ich fahre mit Abblendlicht"],"co":[2],"ex":["Das Tagfahrlicht reicht nicht aus, um eine angemessene Sicht im Tunnel zu gewährleisten. Du musst das Abblendlicht einschalten.","Das wäre sehr gefährlich. Abblendlicht einschalten, damit du ausreichend Sicht hast und ausreichend gesehen wirst.","Im Tunnel muss immer das Abblendlicht eingeschaltet sein."],"i":["https://video4.kalaiwa.de/assets/1442132.webp"],"rn":566},{"n":"1.4.42-133","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- eines verkehrsberuhigten Bereichs","- eines Fußgängerbereichs","- eines Spielplatzes"],"co":[0],"ex":["Dieses Schild zeigt das Ende eines verkehrsberuhigten Bereichs.","Das Verkehrszeichen weist nicht auf das Ende einer Fußgängerzone hin.","Es gibt kein Verkehrszeichen, das auf das Ende eines Spielplatzes hinweist."],"i":["https://video2.kalaiwa.de/assets/1442133.webp"],"rn":567},{"n":"1.4.42-135","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf die U-Bahn Linie 3","Auf eine nummerierte Umleitung","Auf eine nummerierte Tiefgarage"],"co":[1],"ex":["U-Bahnstationen sind mit einem weißen U auf blauem Untergrund gekennzeichnet.","Darauf weist dieses Verkehrszeichen hin.","Das Verkehrszeichen weist auf eine nummerierte Umleitung hin."],"i":["https://video2.kalaiwa.de/assets/1442135.webp"],"rn":568},{"n":"1.4.42-136","t":"Was müssen Sie bei dieser Verkehrszeichenkombination beachten?","p":4,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Wenn ich geradeaus weiterfahre, muss ich rechts blinken","Die Fahrtrichtung nach links ist vorgeschrieben","Wenn ich der Vorfahrtstraße folge, muss ich links blinken"],"co":[2],"ex":["Wenn du geradeaus fährst, musst und darfst du gar nicht blinken. Wenn du nach rechts abbiegen möchtest, musst du nach rechts blinken.","Die Vorfahrtsstraße knickt nach links ab. Du kannst dennoch geradeaus oder nach rechts weiterfahren.","Jede Richtungsänderung, auch wenn vorgegeben, muss durch Blinken angezeigt werden."],"i":["https://video4.kalaiwa.de/assets/1442136.webp"],"rn":569},{"n":"1.4.42-138","t":"Wie müssen Sie sich bei diesem Verkehrszeichen verhalten?","p":4,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Ich darf nicht auf dem Fußgängerüberweg zum Stehen kommen, wenn der Verkehr stockt","Ich muss den Fußgängern das Überqueren der Fahrbahn ermöglichen","Ich muss mit mäßiger Geschwindigkeit heranfahren, wenn Fußgänger die Fahrbahn erkennbar überqueren möchten"],"co":[0,1,2],"ex":["Wenn der Verkehr stockt, musst du vor dem Fußgängerüberweg zum Stehen kommen.","Gegebenenfalls musst du anhalten, damit sie die Straße hier ungehindert passieren können.","Du musst bei Bedarf stehen bleiben, damit diese den Fußgängerüberweg überqueren können."],"i":["https://video2.kalaiwa.de/assets/1442138.webp"],"rn":570},{"n":"1.4.42-139","t":"Worauf müssen Sie sich hier einstellen?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Dass der fließende Verkehr anhält","Dass Kinder häufiger als sonst über die Fahrbahn laufen","Dass Kinder unter Anleitung auf der Fahrbahn spielen"],"co":[0,1],"ex":["Die Sicherheit der Kinder hat oberstes Gebot im Straßenverkehr. Daher muss der Fließverkehr anhalten, wenn ein Verkehrshelfer dies anzeigt.","Da diese Schilder in Gebieten aufgestellt sind, in denen Kinder häufig in der Regel viel befahrene Straßen nutzen müssen, kannst du davon ausgehen, dass hier öfter als sonst Kinder über die Fahrbahn laufen.","Das sagt dieses Verkehrszeichen nicht aus. Es weist auf Verkehrshelfer hin."],"i":["https://video4.kalaiwa.de/assets/1442139.webp"],"rn":571},{"n":"1.4.42-141","t":"Was bedeutet diese Verkehrszeichenkombination für Sie?","p":4,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Ich darf nicht nach rechts abbiegen oder geradeaus fahren","Ich befinde mich auf einer Vorfahrtstraße, die nach links abknickt","Ich muss die Vorfahrt der von rechts kommenden Fahrzeuge beachten, wenn ich geradeaus weiterfahre"],"co":[1],"ex":["Du darfst nach rechts abbiegen oder geradeaus fahren. Du verlässt allerdings die Vorfahrtsstraße und hast somit keinen Vorrang vor anderen Verkehrsteilnehmern mehr.","Hier wird eine nach links abknickende Vorfahrtsstraße angezeigt. Diejenigen, die sich auf dieser Straße befinden, haben Vorfahrt vor dem übrigen Verkehr.","Weil du von der Vorfahrtsstraße abfährst, hast du das Vorrecht vor den Fahrzeugen, die auf der Vorfahrtsstraße einfahren."],"i":["https://video4.kalaiwa.de/assets/1442141.webp"],"rn":572},{"n":"1.4.42-142","t":"Was müssen Sie bei diesem Verkehrszeichen beachten?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Kraftfahrzeuge müssen mit Schrittgeschwindigkeit fahren","Fußgänger dürfen die ganze Straßenbreite nutzen","Kinder dürfen auf der gesamten Straße spielen"],"co":[0,1,2],"ex":["Halte dich hier in Bremsbereitschaft und fahre maximal mit Schrittgeschwindigkeit.","Fußgänger haben hier Vorrang vor Fahrzeugen.","Daher musst du hier besonders vorsichtig fahren."],"i":["https://video4.kalaiwa.de/assets/1442142.webp"],"rn":573},{"n":"1.4.42-143","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf ein Durchfahrtsverbot","Auf eine Zollstelle","Auf eine mautpflichtige Straße"],"co":[1],"ex":["Das Verkehrszeichen, das die Durchfahrt untersagt, ist ein roter Kreis auf weißem Untergrund.","Darauf weist dieses Verkehrszeichen hin.","Das Schild, das eine mautpflichtige Straße ankündigt, ist diesem ähnlich. Allerdings steht darauf nicht \"Zoll/Douane\", sondern \"Maut\" und es sind Münzen abgebildet."],"i":["https://video4.kalaiwa.de/assets/1442143.webp"],"rn":574},{"n":"1.4.42-144","t":"Was gilt hier?","p":2,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- endet eine Umleitung","- beginnt eine geschlossene Ortschaft","- endet eine geschlossene Ortschaft"],"co":[2],"ex":["Das Verkehrszeichen, das das Ende einer Umleitung ankündigt, sieht aus wie der untere Teil des hier abgebildeten Verkehrszeichens, nur, dass statt dem Ortsnamen das Wort \"Umleitung\" geschrieben steht.","Den Beginn einer geschlossenen Ortschaft zeigt ein ebenfalls gelbes Straßenschild diesen Formats, allerdings steht hier in schwarzer Schrift ein Ortsname mittig auf dem Schild.","Die Ortschaft \"Wilster\" endet hier und in 6 km beginnt die geschlossene Ortschaft \"Schotten\"."],"i":["https://video4.kalaiwa.de/assets/1442144.webp"],"rn":575},{"n":"1.4.42-145","t":"Was müssen Sie in Verkehrssituationen wie dieser beachten?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- überfahren, um an Hindernissen vorbeizufahren","- überfahren, um zu überholen","- nicht überfahren, wenn dadurch der Verkehr gefährdet wird"],"co":[0,1,2],"ex":["Du darfst die Leitlinie überfahren, um an der Person vorbeizufahren, die das Mofa schiebt. Du könntest zudem anhalten und die Person fragen, ob sie Hilfe benötigt.","Um an Hindernissen vorbeizufahren oder zu überholen, ist das Überfahren der gestrichelten Leitlinie gestattet.","Du darfst die gestrichelte Leitlinie nur überfahren, wenn hierdurch kein Verkehrsteilnehmer behindert oder gefährdet wird."],"i":["https://video4.kalaiwa.de/assets/1442145.webp"],"rn":576},{"n":"1.4.42-146","t":"Worauf weist dieses Verkehrszeichen hin?","p":4,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf eine Nothalte- und Pannenbucht","Auf eine Haltemöglichkeit für Pausen und Fahrerwechsel","Auf einen vorübergehenden Zusatzfahrstreifen"],"co":[0],"ex":["Nur bei einer Panne oder im Notfall darfst du hier anhalten.","Es ist verboten, die Nothalte- und Pannenbucht für Pausen und Fahrerwechsel zu benutzen.","Es ist verboten, die Nothalte- und Pannenbucht als Zusatzfahrstreifen zu benutzen."],"i":["https://video2.kalaiwa.de/assets/1442146.webp"],"rn":577},{"n":"1.4.42-009-M","t":"Welche Bedeutung hat die weiße Markierung auf der Fahrbahn in dieser Situation?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- kennzeichnet einen verkehrsberuhigten Bereich","- hebt eine Wartepflicht infolge der Rechts-vor-links-Regelung hervor","- warnt vor einem schlechten Fahrbahnzustand"],"co":[1],"ex":["Die Haifischzähne machen lediglich auf bereits geltende Vorfahrtsregeln aufmerksam. Sie dienen nicht dazu, einen verkehrsberuhigten Bereich zu kennzeichnen.","Die Haifischzähne heben die Wartepflicht hervor, wenn \"Rechts-vor-Links\" gilt.","Die Haifischzähne dienen der Hervorhebung der Wartepflicht bei geltender \"Rechts-vor-Links\" Regelung, aber nicht der Warnung vor einem schlechten Fahrbahnzustand. Dieser wird durch ein Gefahrenzeichen mit Ausrufezeichen markiert."],"i":["https://video4.kalaiwa.de/assets/1442009m.webp"],"rn":578},{"n":"1.4.42-010-M","t":"Was gilt in dieser Situation aufgrund der Fahrbahnmarkierung?","p":4,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- dem roten Fahrzeug Vorfahrt gewähren","- vor der Fahrbahnmarkierung stehen bleiben","- mich der Kreuzung vorsichtig nähern"],"co":[2],"ex":["Du hast Vorfahrt vor dem roten Bus. Es gilt \"Rechts-vor-Links\".","Es gilt \"Rechts-vor-Links\". Wenn von rechts kein Fahrzeug kommt, gibt es keinen Grund für dich, stehenzubleiben.","Es gilt \"Rechts-vor-Links\" und du hast Vorfahrt. Trotzdem solltest du dich der Kreuzung vorsichtig nähern, um sicherzugehen, dass von rechts kein Fahrzeug kommt und dass der rote Bus anhält."],"v":["https://video4.kalaiwa.de/assets/1442010mv1440.mp4"],"rn":579},{"n":"1.4.42-147-M","t":"Sie fahren auf dieser Straße mit einem Schutzstreifen für Radfahrer. Wie dürfen Sie den Schutzstreifen nutzen?","p":3,"c":"1.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- auf dem Schutzstreifen parken","- den Schutzstreifen bei Bedarf befahren","- auf dem Schutzstreifen halten"],"co":[1],"ex":["Auf dem Schutzstreifen für Radfahrer darf man weder Halten noch Parken.","Bei Bedarf darfst du den Schutzstreifen befahren. Die Radfahrer gefährden darfst du dabei nicht.","Auf dem Schutzstreifen für Radfahrer darf man weder Halten noch Parken."],"i":["https://video4.kalaiwa.de/assets/1442147m.webp"],"rn":580},{"n":"1.4.43-101","t":"Worauf können rot-weiße Warntafeln an Fahrzeugen hinweisen?","p":3,"c":"1.4.43","ch":"Verkehrseinrichtungen","th":"Verkehrszeichen","o":["Auf ein Gefahrgutfahrzeug","Auf ein Fahrzeug mit Überbreite","Auf einen Anhänger, der innerhalb einer geschlossenen Ortschaft auf der Fahrbahn abgestellt ist"],"co":[1,2],"ex":["Auf Warntafeln an Gefahrgutfahrzeugen wird durch Bilder und Piktogramme auf die Gefahren des transportierten Stoffs hingewiesen. Weiterhin wird auf zusätzlichen orangenen Tafeln genau angegeben, was das Fahrzeug geladen hat. Rot-weiß schraffierte Tafeln werden hier nicht zur Warnung eingesetzt.","Diese Warntafeln können unter anderem Fahrzeuge mit Überbreite kennzeichnen. Sie sind bereits auf große Entfernung erkennbar und warnen so andere Verkehrsteilnehmer bereits rechtzeitig vor den besonderen Maßen des Fahrzeugs.","Anhänger, die auf der Fahrbahn abgestellt sind, müssen innerhalb geschlossener Ortschaften mit rot-weiß gestreiften Park-Warntafeln abgesichert werden, da sie durch eine fehlende Energiequelle sonst nicht beleuchtet werden können."],"rn":581},{"n":"1.5.01-004","t":"Wie wirkt sich eine wesentliche Unterschreitung des empfohlenen Reifendrucks aus?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Der Schadstoffausstoß nimmt ab","Der Reifenabrieb nimmt zu","Der Kraftstoffverbrauch nimmt zu"],"co":[1,2],"ex":["Ist der Reifendruck zu niedrig, so müssen wir mehr Gas geben um die Geschwindigkeit aufrecht zu erhalten. Daher wird auch mehr Kraftstoff verbraucht. Wenn der Kraftstoffverbrauch ansteigt, dann nimmt auch der Schadstoffausstoß zu.","Wenn der Reifen zu wenig Luft hat, dann rollt er schwerer. Wir müssen also einen höheren Rollwiderstand überwinden. Das bedeutet aber, dass wir mehr Kraft übertragen müssen. Je höher die zu übertragende Kraft am Rad ist, desto mehr wird auch der Reifen beansprucht. Der Verschleiß und damit auch der Reifenabrieb nehmen zu.","Wer schon mal mit dem Fahrrad gefahren ist und dabei sehr wenig Luft im Reifen hatte, der weiß dass sich das Fahrrad dann schwerer fährt als sonst. Man braucht viel mehr Kraft, um vorwärts zu kommen. Beim Auto ist das ganz genauso, der Reifen rollt schwerer und dadurch geben wir für die gleiche Geschwindigkeit viel mehr Gas. Damit steigt der Kraftstoffverbrauch an."],"rn":582},{"n":"1.5.01-006","t":"Ihr Kraftfahrzeug verliert etwas Öl. Wie viel Trinkwasser kann bereits durch einen Tropfen Öl ungenießbar werden?","p":4,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["600 Liter","1 Liter","50 Liter"],"co":[0],"ex":["Ein kleiner Tropfen Öl kann bis zu 600 Liter Wasser ungenießbar machen.","Ein kleiner Tropfen Öl kann mehr als einen Liter Wasser ungenießbar machen.","Ein kleiner Tropfen Öl kann mehr als 50 Liter Wasser ungenießbar machen."],"rn":583},{"n":"1.5.01-007","t":"Was soll man beim Tanken beachten?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Nicht nachtanken, wenn der Tank voll ist und die Zapfpistole abgeschaltet hat","Keine Kraftstoffdämpfe einatmen","Möglichst randvoll tanken"],"co":[0,1],"ex":["Der Kraftstoff kommt mit 6 - 8 °C aus dem Tank und hat entsprechend dieser Temperatur ein bestimmtes Volumen. Liegt die Außentemperatur höher, dann fängt der Kraftstoff im Tank sofort an sich zu erwärmen. Dadurch vergrößert sich also sein Volumen. Wenn die Zapfpistole abschaltet, dann ist noch genügend Luft im Tank, die bei der Ausdehnung des Kraftstoffs entweichen kann. Tanke ich randvoll, dann fehlt dieses Luftpolster. Der Kraftstoff dehnt sich aus und der Teil, der nicht mehr in den Tank passt tritt aus. Dies entspricht nicht dem Umwelt- und Brandschutzbestimmung. Ein Nachtanken sollte daher unterlassen werden.","Das Einatmen von Kraftstoffdämpfen zieht möglicherweise gesundheitliche Schäden oder Störungen in der Informationsverarbeitung im Gehirn nach sich. Daher sollte man darauf lieber verzichten.","Der Kraftstoff kommt mit 6 - 8 °C aus dem Tank und hat entsprechend dieser Temperatur ein bestimmtes Volumen. Liegt die Außentemperatur höher, dann fängt der Kraftstoff im Tank sofort an sich zu erwärmen. Dadurch vergrößert sich also sein Volumen. Wenn die Zapfpistole abschaltet, dann ist noch genügend Luft im Tank, die bei der Ausdehnung des Kraftstoffs entweichen kann. Tanke ich randvoll, dann fehlt dieses Luftpolster. Der Kraftstoff dehnt sich aus und der Teil, der nicht mehr in den Tank passt tritt aus."],"rn":584},{"n":"1.5.01-010","t":"Wo können Altöle, Schmierstoffe und Fahrzeugbatterien einer fachgerechten Entsorgung zugeführt werden?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Im Hausmüll","In Kfz-Werkstätten","Auf Wertstoffhöfen"],"co":[1,2],"ex":["Der Hausmüll ist hierfür nicht angebracht. Du musst mit solchem Sondermüll auf den Wertstoffhof oder in eine Kfz-Werkstatt.","In Kfz-Werkstätten kann derartiger Müll fachgerecht entsorgt werden.","Auf Wertstoffhöfen kannst du Altöl, Schmierstoffe und Fahrzeugbatterien angemessen entsorgen."],"rn":585},{"n":"1.5.01-014","t":"Welche Maßnahmen tragen zur Umweltschonung bei?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- Leichtlaufölen","- Klimaanlagen","- Leichtlaufreifen"],"co":[0,2],"ex":["Leichtlauföl ist ein Motoröl, das besonders wenig Reibung im Motor verursacht. Hierdurch geht weniger Energie verloren, wodurch weniger Kraftstoff notwendig ist. Das kommt der Umwelt zugute.","Klimaanlagen erhöhen den Spritverbrauch.","Hier wird der Rollwiderstand auf ein Minimum reduziert und somit Kraftstoff gespart, was wiederum der Umwelt zugute kommt."],"rn":586},{"n":"1.5.01-016","t":"Wozu kann eine regelmäßige Fahrzeugwartung beitragen?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Die Verkehrssicherheit zu gewährleisten","Die Emissionswerte gering zu halten","Den Kraftstoffverbrauch gering zu halten"],"co":[0,1,2],"ex":["Bei der Wartung werden Fahrzeugteile geprüft, die für die Verkehrssicherheit wichtig sind. Darum geht es um Bremsen, freie Sicht durch Scheiben und Spiegel, etc.","Nur ein technisch einwandfrei arbeitender und richtig eingestellter Motor sowie Auspuff, Katalysator, Abgasreinigungsanlage usw. sind umweltfreundlich.","Der Kraftstoffverbrauch wird erhöht, wenn die Luftfilter verschmutzt, Zündkerzen verrußt und die Zündung, Vergaser und Einspritzanlage schlecht eingestellt sind."],"rn":587},{"n":"1.5.01-017","t":"In welcher Situation sollten Sie den Motor abstellen, um Kraftstoff zu sparen und die Umweltbelastung zu verringern?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- im Stau absehbar länger warten muss","- an einem beschrankten Bahnübergang warten muss","- an einem „Stop“-Schild anhalten muss"],"co":[0,1],"ex":["Wenn du dich in einem Verkehrsstau befindest, in dem längere Wartezeiten absehbar sind, musst du den Motor abschalten. So schonst du die Umwelt und sparst Kraftstoff.","Vor einem beschrankten Bahnübergang solltest du den Motor abstellen, da du die Länge der Wartezeit nicht genau abschätzen kannst. So kannst du die Umweltbelastung reduzieren und gleichzeitig Kraftstoff sparen.","An einem „Stop“-Schild musst du den Motor nicht abschalten, da du hier lediglich kurz an der Halte- oder Sichtlinie anhältst, bevor du weiterfährst."],"rn":588},{"n":"1.5.01-110","t":"Wie fahren Sie umweltbewusst?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Unnötiges Beschleunigen und unnötiges Abbremsen vermeiden","Bei „Grün“ immer voll beschleunigen","Rechtzeitig Gas wegnehmen und Schwung ausnutzen, wenn die nächste Ampel „Rot“ zeigt"],"co":[0,2],"ex":["Jedes Beschleunigen kostet Kraftstoff. Unnötiges Abbremsen kostet keinen Kraftstoff, danach muss man allerdings wieder beschleunigen und verbraucht folglich Kraftstoff.","Je stärker man beschleunigt, desto schneller und mehr Kraftstoff wird verbraucht. Dadurch wird die Umwelt auch stärker belastet.","Gehst du frühzeitig vom Gas, dann rollt das Fahrzeug weiter. Du nutzt also den restlichen Schwung und die Massenträgheit aus. Dadurch wird die Kraftstoffzufuhr stark reduziert und man schont die Bremsen."],"rn":589},{"n":"1.5.01-114","t":"Was kann dazu beitragen, Kraftstoff zu sparen und die Umweltbelastung zu verringern?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Schon beim Kauf eines Kraftfahrzeugs auf den Kraftstoffverbrauch achten","Nach Möglichkeit öffentliche Verkehrsmittel benutzen, mit dem Fahrrad fahren oder zu Fuß gehen","Durch vorausschauende Fahrweise zu einem gleichmäßigen Verkehrsfluss beitragen"],"co":[0,1,2],"ex":["Entscheidet man sich bereits beim Fahrzeugkauf für eines, das wenig Kraftstoff verbraucht, dann spart man so langfristig Geld und belastet die Umwelt weniger.","Reduziert man die Nutzung eines Fahrzeugs, dann spart das natürlich den Kraftstoffverbrauch. Auch der Umwelt kommt das zugute, da so weniger Abgase in die Atmosphäre gehen.","Fährt man vorausschauend und vermeidet so häufiges Abbremsen und Anfahren/Beschleunigen, dann spart das Kraftstoff und belastet die Umwelt weniger."],"rn":590},{"n":"1.5.01-115","t":"Was können Sie tun, um die Umwelt zu schonen?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- Fahrten mit Vollgas","- Kurzstreckenfahrten","- Fahrten in überfüllte Innenstädte"],"co":[0,1,2],"ex":["Mit Vollgas fahren verbraucht sehr viel Kraftstoff und verschmutzt unnötig die Umwelt.","Kurze Strecken können auch zu Fuß, mit dem Rad oder öffentlichen Verkehrsmitteln zurückgelegt werden. So kannst du die Umwelt schonen und zusätzlich Kraftstoff sparen.","In überfüllten Innenstädten ist häufig \"Stop and Go\". Du musst also, aufgrund des hohen Verkehrsaufkommens, häufig Anfahren und wieder Abbremsen, was viel Kraftstoff verbraucht und die Umwelt verschmutzt."],"rn":591},{"n":"1.5.01-118","t":"Warum ist die Nutzung von Leichtlaufölen vorteilhaft?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- im Hausmüll entsorgt werden können","- den Kraftstoffverbrauch verringern","- weniger Reibung im Motor erzeugen"],"co":[1,2],"ex":["Öle haben nichts im Hausmüll zu suchen. Du kannst sie fachgerecht auf dem Wertstoffhof oder in einer Werkstatt entsorgen.","Aufgrund der verminderten Reibung wird Energie gespart, was sich im Kraftstoffverbrauch niederschlägt.","Weil Leichtlauföl aufgrund seiner dünnflüssigen Konsistenz besonders wenig Reibung im Motor verursacht, geht weniger Energie verloren als bei herkömmlichem Motoröl."],"rn":592},{"n":"1.5.01-121","t":"Wie können Sie den Reifenverschleiß gering halten?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Ich kontrolliere regelmäßig den Reifenfülldruck","Ich verzichte möglichst auf starkes Beschleunigen","Ich verwende ganzjährig Winterreifen"],"co":[0,1],"ex":["Wenn nicht der vorgegebene Reifendruck vorhanden ist, wird der Reifen ungleichmäßig abgefahren.","Starkes Beschleunigen wirkt sich negativ auf den Verschleiß der Reifen aus.","Winterreifen haben einige Nachteile im Sommer, unter anderem einen erhöhten Verschleiß."],"rn":593},{"n":"1.5.01-122","t":"Welche Kraftfahrzeuge sind vom Verkehrsverbot für „Umweltzonen“ grundsätzlich ausgenommen?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Krankenwagen im Einsatz","Alle Kraftfahrzeuge der Umweltzonenbewohner","Land- und forstwirtschaftliche Zugmaschinen"],"co":[0,2],"ex":["Diese dürfen hier fahren.","Bewohner der Umweltzonen haben keinen Sonderstatus.","Eine Ausnahme betrifft land- und forstwirtschaftliche Zugmaschinen. Diesen ist hier das Fahren gestattet."],"rn":594},{"n":"1.5.01-124","t":"Sie fahren zur Hauptverkehrszeit im Stadtverkehr. Welche Auswirkung hat das Fahren im Stop-and-go-Verkehr?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- verursacht mehr Belästigungen für andere","- verursacht mehr Abgase","- verbraucht mehr Kraftstoff"],"co":[0,1,2],"ex":["Zum einen verursacht das Fahren im Stop-and-go-Verkehr mehr Abgase, zum anderen erhöht das den Lärmpegel, was für Fußgänger und Anwohner sehr belästigend ist.","Weil du mehr Kraftstoff verbrauchst, verursacht das mehr Abgase.","Durch das ständige Abbremsen und erneute Anfahren verbraucht dein Fahrzeug mehr Kraftstoff, als im fließenden Verkehr."],"rn":595},{"n":"1.5.01-125","t":"Was ist eine Voraussetzung für umweltschonendes und energiesparendes Fahren?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Regelmäßige Kontrolle des Reifenfülldrucks","Regelmäßige Fahrzeugwartung","Regelmäßige Motorwäsche"],"co":[0,1],"ex":["Prüfe regelmäßig den Luftdruck deiner Reifen. Bei zu geringem Druck hat dein Reifen eine höhere Reibung und verschleißt dadurch schneller. Auch der Spritzverbrauch ist dadurch höher. Das entlastet auch die Umwelt.","Bei der Fahrzeugwartung werden viele Dinge an einem Fahrzeug geprüft, die sich auf umweltschonendes und energiesparendes Fahren auswirken können, z.B. Motor, Abgasreinigung, etc.","Ein Motorwäsche hat keine Auswirkung auf umweltschonendes und energiesparendes Fahren."],"rn":596},{"n":"1.5.01-126","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe. Welche Fahrweise führt innerorts zu einem hohen Kraftstoffverbrauch?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Starkes Beschleunigen","Fahren in hohem Gang","Fahren mit hoher Motordrehzahl"],"co":[0,2],"ex":["Starkes Beschleunigen fordert den Motor stark und erhöht den Kraftstoffverbrauch.","Ein frühes Hochschalten der Gänge ist kraftstoffsparend.","Fahren mit hoher Motordrehzahl führt zu mehr Reibung im Motor und erhöht den Spritverbrauch."],"rn":597},{"n":"1.5.01-127","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe. Wodurch können Sie den Kraftstoffverbrauch Ihres Fahrzeugs reduzieren?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch vorausschauendes Fahren, um häufige Geschwindigkeitswechsel zu vermeiden","Durch frühes Schalten in nächsthöhere Gänge","Durch Fahren mit hoher Motordrehzahl"],"co":[0,1],"ex":["Beim Autofahren erfordert häufiges Beschleunigen einen erhöhten Kraftstoffverbrauch. Fahre deshalb vorausschauend, dann musst du weniger oft beschleunigen.","Ein frühes Hochschalten ist kraftstoffsparend.","Je höher die Drehzahl, desto höher der Spritverbrauch."],"rn":598},{"n":"1.5.01-128","t":"Wie können Sie den Lärm verringern, der durch Ihr Kraftfahrzeug verursacht wird?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch die Verwendung von Reifen mit geringem Rollgeräusch","Durch das Entfernen des Luftfiltereinsatzes","Durch das Fahren mit niedriger Motordrehzahl"],"co":[0,2],"ex":["Reifen unterscheiden sich beim Rollgeräusch. Wenn du deine Reifen erneuerst, kaufe leise Reifen. Das schont auch deine Nerven.","Wenn du den Luftfiltereinsatz entfernst, wird dein Motor lauter, da der Einsatz deinen Motor nicht mehr dämmen kann. Außerdem zieht dein Motor dadurch Fremdpartikel ein, was zu Motorschäden führen kann.","Bei niedriger Drehzahl ist der Motor leiser als bei hohen Drehzahlen."],"rn":599},{"n":"1.5.01-129","t":"Was sollten Sie tun, um die Umwelt zu schonen?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- auf unnützes Hin- und Herfahren verzichten","- bei übermäßiger Rauchentwicklung aus der Auspuffanlage das Kraftfahrzeug überprüfen lassen","- bei längerem Warten den Motor abstellen"],"co":[0,1,2],"ex":["Verzichte der Umwelt zuliebe auf unnütze Fahrten.","Falls die Rauchentwicklung mehr als gewöhnlich sein sollte, könnte ein Defekt vorliegen. Lass dein Fahrzeug überprüfen, um Folgeschäden zu vermeiden.","Wenn du z.B. vor einem Bahnübergang warten musst, stelle deinen Motor ab."],"rn":600},{"n":"1.5.01-130","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe. Wodurch kann beim Fahren eine vermeidbare Lärmbelästigung entstehen?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch schnelles Fahren in niedrigen Gängen","Durch schadhafte Schalldämpfer","Durch unnötig starkes Beschleunigen"],"co":[0,1,2],"ex":["In niedrigen Gängen arbeitet der Motor mit hoher Drehzahl und ist somit lauter. Vermeide dies.","Die Aufgabe des Schalldämpfers ist das Unterdrücken der lauten Geräusche des Auspuffs. Falls dieser kaputt ist, musst du ihn reparieren lassen oder erneuern.","Starkes Beschleunigen erzeugt viel Lärm. Immer, wenn es möglich ist, vermeide es."],"rn":601},{"n":"1.5.01-131","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe auf ebener Fahrbahn. Wie sollten Sie schalten, um besonders umweltbewusst und sparsam zu fahren?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["So früh wie möglich hochschalten","So spät wie möglich zurückschalten","Gänge bis in den oberen Drehzahlbereich ausfahren und dann schalten"],"co":[0,1],"ex":["Du solltest beim Beschleunigen möglichst frühzeitig in den nächst höheren Gang schalten, um möglichst kraftstoffsparend und umweltbewusst zu fahren.","Du solltest beim langsamer werden möglichst spät in den nächst kleineren Gang zurückschalten, um möglichst kraftstoffsparend und umweltbewusst zu fahren.","Der Kraftstoffverbrauch und die Umweltbelastung steigen bei hohen Drehzahlen."],"rn":602},{"n":"1.5.01-132","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe. Welches Verhalten belastet die Umwelt?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Eine ungleichmäßige Fahrweise","Ein Fahren bergab in hohem Gang","Ein häufiges Gasgeben beim Warten an der Ampel"],"co":[0,2],"ex":["Eine ungleichmäßige Fahrweise, also häufiges Beschleunigen, belastet die Umwelt und ist zu vermeiden.","Bergab im hohen Gang fahren, ist keine Belastung für die Umwelt.","Gas geben beim Warten an der Ampel ist eine sinnlose Umweltbelastung."],"rn":603},{"n":"1.5.01-133","t":"Sie fahren ein Kraftfahrzeug mit manuellem Schaltgetriebe. Wodurch erreichen Sie einen sparsamen Kraftstoffverbrauch?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch eine gleichmäßige Fahrweise mit niedriger Motordrehzahl","Durch den richtigen Reifenfülldruck","Durch ein spätes Hochschalten beim Beschleunigen"],"co":[0,1],"ex":["Fährst du niedertourig und vorausschauend sparst du Kraftstoff und dadurch Geld.","Nur bei korrektem Luftdruck hat ein Fahrzeug optimale Fahreigenschaften, geringen Kraftstoffverbrauch und einen niedrigen Reifenverschleiß.","Schalte immer rechtzeitig in den nächsthöheren Gang, wenn du beschleunigst."],"rn":604},{"n":"1.5.01-134","t":"Worauf sollten Sie nach dem Starten Ihres Fahrzeugs achten?","p":3,"c":"1.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- mit niedriger Motordrehzahl fahren","- den Motor im Stand warmlaufen lassen","- unverzüglich losfahren"],"co":[0,2],"ex":["Der Motor und das Motoröl sind nach dem Starten noch kalt. Dadurch ist die optimale Schmier- und Kühlwirkung noch nicht erreicht. Wenn du jetzt mit hohen Drehzahlen fahren würdest, kannst du den Motor beschädigen.","Moderne Autos müssen nicht mehr im Stand warmlaufen. Vermeide das, da es die Umwelt belastet.","Fahre unverzüglich los und lass den Motor nicht im Stand warmlaufen."],"rn":605},{"n":"1.8.01-003","t":"Wann werden im Fahreignungsregister eingetragene Ordnungswidrigkeiten getilgt, die mit zwei Punkten bewertet wurden?","p":3,"c":"1.8.01","ch":"Eignung Und Befaehigung Von Kraftfahrern","th":"Eignung Und Befaehigung Von Kraftfahrern","o":["- 5 Jahren","- 2 Jahren","- 3 Jahren"],"co":[0],"ex":["Es dauert mindestens fünf Jahre, bis mit zwei Punkten bewertete Ordnungswidrigkeiten gelöscht werden.","Es dauert mindestens drei weitere Jahre, bis derartige Ordnungswidrigkeiten getilgt werden.","Frühestens nach fünf Jahren werden diese aus dem Fahreignungsregister gelöscht."],"rn":606},{"n":"2.1.01-004","t":"Wodurch kann eine Gefährdung entstehen?","p":4,"c":"2.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Durch zu spätes Abblenden","Durch Kurvenschneiden","Durch zu großen Abstand nach vorn"],"co":[0,1],"ex":["Fernlicht blendet den Gegenverkehr. Dadurch können gefährliche Verkehrssituationen entstehen, weil dieser die Verkehrssituation aufgrund der Blendung nur noch eingeschränkt einschätzen kann.","Durch das Schneiden einer Kurve befindet man sich mit einem Teil des Fahrzeugs auf der Gegenfahrbahn, beziehungsweise sehr nah daran. Vor allem in Kurven ist der Gegenverkehr nicht weit einsichtig. Das kann zu gefährlichen Zusammenstößen führen.","Das erhöht die Sicherheit und stellt keine Gefährdung dar."],"rn":607},{"n":"2.1.01-102","t":"Wozu führt das Hören von lauter Musik, vor allem mit extremen Bässen, im Auto?","p":4,"c":"2.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Blinde erkennen dadurch leichter den Verlauf der Fahrbahn","In der Nähe solcher Fahrzeuge verlieren Blinde die Orientierung","Die Aufmerksamkeit des Fahrers wird erheblich beeinträchtigt"],"co":[1,2],"ex":["Blinde können hierdurch ihre Orientierung verlieren.","Der Gehörssinn ist bei Blinden besser ausgeprägt, als bei Sehenden. Laute Musik übertönt die akustischen Hinweise in der Umwelt, mit deren Hilfe Blinde sich orientieren.","Sehr laute Musik lenkt den Fahrer von einer konzentrierten Fahrweise ab."],"rn":608},{"n":"2.1.01-103","t":"Wodurch kann eine Gefährdung beim Fahren entstehen?","p":4,"c":"2.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Durch ein nicht funktionierendes Abblendlicht","Durch ein zu großes Spiel in der Lenkung","Durch eine stark einseitig wirkende Betriebsbremse"],"co":[0,1,2],"ex":["Alle Lichter am Auto müssen immer einwandfrei funktionieren. Durch ein falsch eingestelltes Abblendlicht im Auto kannst du außerdem ein Bußgeld erhalten.","Zu viel Lenkspielraum sind Hinweise darauf, dass etwas mit der Lenkvorrichtung nicht stimmt. Also: Reparieren lassen.","Die Bremsen müssen immer einwandfrei funktionieren. Lass deine Bremsen sofort reparieren, sobald du feststellst, dass sie nicht ordnungsgemäß funktionieren."],"rn":609},{"n":"2.1.01-007-M","t":"Wie sollten Sie sich jetzt verhalten?","p":4,"c":"2.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Ich behalte meine Geschwindigkeit bei, da der Sicherheitsabstand ausreichend ist","Ich beschleunige, damit der Überholende sich hinter mir einordnen kann","Ich verringere meine Geschwindigkeit, damit der Überholende sich vor mir einordnen kann"],"co":[2],"ex":["Dein Sicherheitsabstand wird nicht mehr ausreichend sein, wenn der weiße Pkw sich vor die eingeordnet hat. Darum verringere jetzt dein Geschwindigkeit.","Es könnte zu einem Unfall kommen, weil die Zeit zum Einordnen nicht mehr ausreicht. Der Gegenverkehr könnte mit dem Überholenden kollidieren.","Ermögliche durch Verringern deiner Geschwindigkeit das Einordnen des weißen Fahrzeugs, so dass ihr beide die geforderten Sicherheitsabstände einhalten könnt."],"v":["https://video2.kalaiwa.de/assets/2101007mv1440.mp4"],"rn":610},{"n":"2.1.01-008-M","t":"Warum sollten Sie dem Lkw den Fahrstreifenwechsel ermöglichen?","p":4,"c":"2.1.01","ch":"Grundformen Des Verkehrsverhaltens","th":"Gefahrenlehre","o":["Weil der Fahrer des Lkws mich übersehen kann","Weil ich Rücksicht auf den Lkw nehmen soll","Weil hier das Reißverschlussverfahren anzuwenden ist"],"co":[0,1],"ex":["Möglicherweise übersieht dich der Lkw-Fahrer. Lasse den Fahrstreifenwechsel zu, um eine Kollision dadurch zu vermeiden.","Der Lkw-Fahrer bemerkt hier wohl, dass er links abbiegen muss. Ermögliche ihm den Wechsel auf den linken Fahrstreifen. Ansonsten muss er stärker abbremsen und könnte den Verkehrsfluss behindern.","Das Reißverschlussverfahren ist anzuwenden, wenn sich zwei Fahrstreifen zu einem verengen, etwa wegen einer Baustelle. Hier ist das nicht der Fall."],"v":["https://video4.kalaiwa.de/assets/2101008mv1440.mp4"],"rn":611},{"n":"2.1.02-002","t":"Sie fahren auf einer schmalen Straße. Etwa 20 m vor Ihnen läuft plötzlich ein Kind auf die Fahrbahn. Wann ist ein Zusammenprall trotz Gefahrbremsung unvermeidbar?","p":4,"c":"2.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["50 km/h","20 km/h","30 km/h"],"co":[0],"ex":["Bei 50 km/h wäre dein Anhalteweg trotz Gefahrenbremsung 27,5 m und somit zu lang.","Bei 20 km/h läge dein Anhalteweg mit Gefahrenbremsung bei 8 m.","Hier wäre der Anhalteweg bei Gefahrenbremsung 13,5 m und somit ausreichend."],"rn":612},{"n":"2.1.02-003","t":"Warum müssen Sie bremsen?","p":4,"c":"2.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Weil Fahrgäste aus der Straßenbahn steigen","Weil eine Person auf die Straße läuft","Weil der Lkw auf meinen Fahrstreifen wechselt"],"co":[1],"ex":["Es können keine Fahrgäste aus der Straßenbahn steigen, weil diese fährt.","Vor dem rechts haltenden LKW läuft eine Person auf die Straße. Um diese nicht zu gefährden, musst du bremsen.","Der LKW hält auf dem rechten Fahrstreifen und hat das Warnblinklicht eingeschaltet. Er wird also nicht auf deine Fahrbahn wechseln."],"v":["https://video4.kalaiwa.de/assets/2102003v1440.mp4"],"rn":613},{"n":"2.1.02-005-M","t":"Womit müssen Sie in dieser Situation rechnen?","p":4,"c":"2.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Es folgt ein Fußgängerüberweg","Kinder laufen auf die Fahrbahn","Personen steigen zur Fahrbahnseite aus"],"co":[1,2],"ex":["Ein Fußgängerüberweg ist hier nicht signalisiert.","Das Verkehrsschild signalisiert erhöhte Vorsicht vor Kindern, die zwischen den Fahrzeugen über die Fahrbahn laufen könnten.","Da jeweils am Straßenrand Fahrzeuge parken, musst du damit rechnen, dass Personen zur Fahrbahnseite aussteigen."],"i":["https://video4.kalaiwa.de/assets/2102005m.webp"],"rn":614},{"n":"2.1.02-006-M","t":"Wie verhalten Sie sich jetzt richtig?","p":5,"c":"2.1.02","ch":"Verhalten Gegenueber Fussgaengern","th":"Gefahrenlehre","o":["Ich beschleunige","Ich fahre unverändert weiter","Ich halte an"],"co":[2],"ex":["Versuche nicht, durch Beschleunigen noch vor der Joggerin über den Fußgängerüberweg zu kommen. Das wäre sehr gefährlich.","Weil die Fußgängerampel grün zeigt, musst du die Joggerin die Straße überqueren lassen.","Beim Rechtsabbiegen haben die Fußgänger Vorrang, da die Fußgängerampel grün ist. Hier musst du anhalten und die Joggerin durchlassen."],"v":["https://video4.kalaiwa.de/assets/2102006mv1440.mp4"],"rn":615},{"n":"2.1.03-015","t":"Was kann auf nasser Fahrbahn zu Aquaplaning (Wasserglätte) führen?","p":5,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Abgefahrene Reifen","Spurrillen in der Fahrbahn","Hohe Geschwindigkeit"],"co":[0,1,2],"ex":["Je höher die Profiltiefe der Reifen, desto mehr Raum ist in den Profilrillen vorhanden, um trotz des Wasserfilms auf der Fahrbahn zu haften.","Auf abgefahrenen Straßen sammelt sich in Spurrillen das Wasser, was auf ebenen Straßen über die gesamte Fahrbahnfläche verteilt ist. Somit ist hier der Wasserstand auch höher und Fahrzeuge geraten leichter ins Rutschen aufgrund von Aquaplaning.","Je höher die Geschwindigkeit, desto eher besteht Aquaplaninggefahr. Bei niedriger Geschwindigkeit kann das Wasser durch die Reifen zur Seite weggedrückt werden, bei höheren Geschwindigkeiten fehlt diese Zeit und das Auto schlittert über den Wasserfilm."],"rn":616},{"n":"2.1.03-025","t":"Wozu kann eine plötzliche Verschlechterung des Fahrbahnzustandes führen?","p":3,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Zu Schleuder- und Rutschgefahr","Zu längerem Reaktionsweg","Zu veränderten Reifengeräuschen"],"co":[0,2],"ex":["Aufgrund des schlechteren Fahrbahnzustandes kann sich auch die Bodenhaftung der Reifen verschlechtern. So kann ein Fahrzeug eher ins Rutschen oder Schleudern geraten.","An deiner Reaktionszeit ändert sich nichts. Das Erkennen eines Hindernisses oder einer Gefahr hat nichts mit der Beschaffenheit der Straße zu tun.","Das Rollgeräusch der Reifen ist von der Beschaffenheit der Straße abhängig. Somit ändert sich dieses auch in Abhängigkeit des Fahrbahnzustandes."],"rn":617},{"n":"2.1.03-028","t":"Wie verhalten Sie sich richtig?","p":5,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich bleibe in der Mitte meines Fahrstreifens","Ich bremse","Ich fahre möglichst weit rechts"],"co":[1,2],"ex":["So würdest du einen Zusammenstoß mit dem LKW und eine Gefährdung der Radfahrerin riskieren.","Um eine gefährliche Situation zu vermeiden, solltest du hier abbremsen.","So gibst du dem LKW mehr Raum, die Radfahrerin ungefährdet zu überholen."],"v":["https://video2.kalaiwa.de/assets/2103028v1440.mp4"],"rn":618},{"n":"2.1.03-029","t":"Warum sollten Sie jetzt bremsen?","p":3,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["- Traktors","- blauen Pkws","- grünen Pkws"],"co":[2],"ex":["Der Traktor ist von der Fahrbahn abgebogen und stellt für dich keinen Grund zu bremsen dar.","Der blaue PKW befindet sich in ausreichendem Abstand hinter dir und gibt dir somit keinen Anlass, jetzt zu bremsen.","Er sieht aufgrund des hohen Schnees nur unzureichend auf die Straße ein. Zudem ist es möglich, dass er aufgrund der Witterungsbedingungen beim Abbremsen ins Rutschen gerät. Bremse hier daher rechtzeitig vorsichtig ab."],"v":["https://video2.kalaiwa.de/assets/2103029v1440.mp4"],"rn":619},{"n":"2.1.03-033","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich vermeide ruckartige Lenkbewegungen","Ich lenke stark nach rechts","Ich reduziere meine Geschwindigkeit"],"co":[0,2],"ex":["Ruckartige Lenkmanöver sollten auf glatten Fahrbahnen unbedingt vermieden werden.","Durch starkes Einlenken könnte dein Fahrzeug ins Rutschen geraten.","Bei Glätte solltest du deine Geschwindigkeit vorsichtig reduzieren."],"v":["https://video2.kalaiwa.de/assets/2103033v1440.mp4"],"rn":620},{"n":"2.1.03-034","t":"Was kann Aquaplaning (Wasserglätte) zur Folge haben?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Eine vergrößerte Haftreibung der Reifen","Eine eingeschränkte Lenkfähigkeit des Fahrzeugs","Eine verringerte Bremsfähigkeit des Fahrzeugs"],"co":[1,2],"ex":["Bei Aquaplaning kann man nicht mehr bremsen. Eine höhere Haftreibung würde \"besser bremsen\" bedeuten.","Bei Aquaplaning kann man nicht mehr lenken.","Bei Aquaplaning kann man nicht mehr bremsen."],"rn":621},{"n":"2.1.03-036","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":3,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich verringere die Geschwindigkeit","Ich vermeide ruckartiges Lenken","Ich bremse stark ab"],"co":[0,1],"ex":["Das Verkehrsschild zeigt Schleuder- und Rutschgefahr an. Um nicht ins Schleudern zu geraten, solltest du deine Geschwindigkeit reduzieren, vor allem dann, wenn es, wie hier, regnet und Laub auf die Straße fällt.","Durch ruckartiges Lenken können die Reifen an Haftung verlieren und du könntest ins Schleudern geraten, vor allem dann, wenn es, wie hier, regnet und Laub auf die Straße fällt.","Durch starkes Bremsen oder Beschleunigen können die Reifen ihre Haftung verlieren und du könntest ins Rutschen oder Schleudern geraten."],"i":["https://video2.kalaiwa.de/assets/2103036.webp"],"rn":622},{"n":"2.1.03-037","t":"Worauf sollten Sie sich hier einstellen?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Auf einen verlängerten Bremsweg","Auf eine erhöhte Bodenhaftung der Reifen","Auf eine schlechte Sichtbarkeit meines Fahrzeugs"],"co":[0,2],"ex":["Aufgrund des vielen Regenwassers auf der Fahrbahn, musst du dich auf einen verlängerten Bremsweg einstellen.","Das Gegenteil ist der Fall: Anstelle einer erhöhten Bodenhaftung besteht ein erhöhtes Risiko für Aquaplaning, also das sogenannte \"Aufschwimmen\" deiner Reifen auf der nassen Fahrbahn.","Trotz eingeschaltetem Licht bist du bei diesen Witterungsbedingungen für andere Verkehrsteilnehmer nur schlecht zu erkennen. Du siehst z.B. auch den vor dir fahrenden Lkw aufgrund des starken Regens sehr schlecht."],"i":["https://video4.kalaiwa.de/assets/2103037.webp"],"rn":623},{"n":"2.1.03-038","t":"Wann sind Sie hier beim Überholvorgang besonders gefährdet?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Beim Herausfahren aus dem Windschatten des Lkws","Beim Einfahren in den Windschatten des Lkws","Beim Fahrstreifenwechsel nach dem Überholen"],"co":[0,1],"ex":["Wenn du den Windschatten verlässt, wird der starke Wind von rechts wieder spürbar sein und deinen Wagen nach links drücken. Du läufst Gefahr, direkt nach links getrieben zu werden. Daher musst du beim Herausfahren auf dem Windschatten rechtzeitig mit dem Gegenlenken beginnen.","Sobald du in den Windschatten des Lkws fährst, ist der Luftwiderstand, gegen den du vorher gelenkt hast, nicht mehr vorhanden. Damit es dich nicht direkt nach rechts zieht, musst du das Gegenlenken im Windschatten sofort unterlassen. Sonst ist das Risiko hoch, dass du mit dem Lkw kollidierst.","Wenn du den Fahrstreifen nach dem Überholen wechselst, dann bist du nicht mehr besonders gefährdet. Du hast dich bereits an den veränderten Luftwiderstand angepasst, dieser verändert sich durch einen bloßen Spurwechsel nicht mehr abrupt."],"i":["https://video2.kalaiwa.de/assets/2103038.webp"],"rn":624},{"n":"2.1.03-101","t":"Wo tritt besonders häufig Aquaplaning (Wasserglätte) auf?","p":5,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["An Bahnübergängen","Bei Spurrillen in der Fahrbahn","In Fahrbahnsenken"],"co":[1,2],"ex":["Hier ist nicht von einer erhöhten Aquaplaninggefahr auszugehen.","Spurrillen sind Vertiefungen in der Fahrbahn, die durch Abnutzung der Straße entstanden sind. Hier kann eher Aquaplaning entstehen, als auf geraden Flächen.","Hier kann sich besonders leicht Wasser sammeln, was zu Aquaplaning führen kann."],"rn":625},{"n":"2.1.03-103","t":"Worauf müssen Sie sich einstellen, wenn es nach längerer Trockenheit anfängt zu regnen?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Auf eine gefährliche Schmierschicht auf der Fahrbahn","Auf einen kürzeren Bremsweg","Auf schlechtere Sicht gleich nach Einschalten der Scheibenwischer"],"co":[0,2],"ex":["Schmutz und andere Abtragungen bleiben auf der Fahrbahn liegen, wenn es nicht regnet. Sobald Regen kommt kann es passieren, dass diese Ablagerungen hierdurch eine rutschige Schmierschicht bilden.","Wenn sich die Fahrbahnverhältnisse verschlechtern, verlängert sich der Bremsweg eher, als dass er sich verkürzt.","Wenn die Scheibenwischer seit längerer Zeit nicht betätigt wurden, bilden sich hierauf Ablagerungen, die zu Beginn der erneuten Benutzung Schlieren auf der Scheibe hinterlassen können."],"rn":626},{"n":"2.1.03-104","t":"Es fängt an zu regnen. Warum müssen Sie den Sicherheitsabstand sofort vergrößern?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Weil die Sicht schlechter werden kann und die Scheibenwischer nicht sofort ein klares Sichtfeld schaffen","Weil sich ein Schmierfilm bilden kann, der den Bremsweg verlängert","Weil die Bremsen schneller ansprechen"],"co":[0,1],"ex":["In der Regel müssen die Scheibenwischer ein paar Mal hin- und herwischen, bis die Sicht klar ist. Daher kann sich die Sicht kurzzeitig verschlechtern.","Durch den Schmierfilm verschlechtert sich die Haftung der Reifen auf der Fahrbahn und der Bremsweg verlängert sich.","Die Bremsen funktionieren nicht besser, wenn sich die Fahrverhältnisse verschlechtern."],"rn":627},{"n":"2.1.03-105","t":"Sie fahren außerorts bei dichtem Nebel auf einer Bundesstraße. Dürfen Sie auf der Fahrbahnmitte ständig über der Leitlinie fahren?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ja, wenn Nebelscheinwerfer und Nebelschlussleuchte eingeschaltet sind","Ja, weil man weniger in Gefahr gerät, von der Fahrbahn abzukommen","Nein, weil der Gegenverkehr gefährdet werden kann"],"co":[2],"ex":["Du darfst die Leitlinie hier nicht überfahren.","Du musst deine Spur halten, weil du aufgrund des dichten Nebels entgegenkommende Fahrzeuge erst spät erkennst.","Du darfst nie ständig über der Leitlinie fahren. Erst recht nicht, wenn die Sicht schlecht ist, wie es bei dichtem Nebel der Fall ist. Entgegenkommende Fahrzeuge können erst spät erkannt werden."],"rn":628},{"n":"2.1.03-106","t":"Was müssen Sie am Tage bei einer plötzlich auftretenden Nebelbank tun?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Nur Standlicht einschalten","Geschwindigkeit sofort den Sichtverhältnissen anpassen","Abblendlicht einschalten"],"co":[1,2],"ex":["Das Standlicht ist nicht ausreichend. Du musst das Abblendlicht einschalten.","Nebel beeinträchtigt die Sicht. Daher musst du umgehend die Geschwindigkeit anpassen, um niemanden zu gefährden.","Um von anderen Verkehrsteilnehmern besser gesehen zu werden und auch selbst besser zu sehen, musst du das Abblendlicht einschalten."],"rn":629},{"n":"2.1.03-107","t":"Wie können Sie ausreichende Sicht durch die Frontscheibe erhalten?","p":3,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Bei innen beschlagener Scheibe Lüftung ausschalten und Fenster geschlossen halten","Bei Schneematsch die Scheibenwischer schon einschalten, bevor Ihnen andere Fahrzeuge Matsch auf die Scheibe schleudern","Bei Nebel den Scheibenwischer von Zeit zu Zeit einschalten"],"co":[1,2],"ex":["Andersherum. Bei einer von innen beschlagenen Scheibe musst du die Lüftung einschalten und die Fenster öffnen.","So wird der Matsch sofort weggewischt, sobald er auf der Scheibe gelandet ist und deine Sicht ist weniger lang eingeschränkt.","Nebel besteht aus feinen Wassertröpfchen, die sich mit der Zeit auch auf der Frontscheibe ablagern können. Schalte daher gelegentlich den Scheibenwischer ein, um die Sicht zu verbessern."],"rn":630},{"n":"2.1.03-111","t":"Sie sind beim Überholen mehrerer Lkws in diese Situation geraten. Wie verhalten Sie sich jetzt?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich stelle nach dem Einscheren wieder ausreichenden Sicherheitsabstand her","Ich überhole zügig weiter und schere vor dem roten Lkw ein","Ich breche den Überholvorgang ab"],"co":[0,2],"ex":["Dies ist vor allem wichtig, weil in Kürze eine Kurve kommt, bei der abgebremst werden muss.","Das ist zu gefährlich, weil du keine ausreichende Sicht auf möglichen Gegenverkehr hast und eine Kurve kommt.","Du kannst nicht weit genug in die Kurve einsehen, um möglichen Gegenverkehr rechtzeitig erkennen und ein sicheres Überholen gewährleisten zu können. Schere daher wieder ein und warte mit dem Überholen, bis du ausreichend Sicht hast."],"i":["https://video2.kalaiwa.de/assets/2103111.webp"],"rn":631},{"n":"2.1.03-115","t":"Wie verhalten Sie sich richtig?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich verzögere weiter","Ich wechsle jetzt nach links","Ich warte vor dem Hindernis"],"co":[0,2],"ex":["So gibst du dem grünen PKW die Möglichkeit, dich rechtzeitig zu überholen, ohne dass ein Verkehrsteilnehmer gefährdet wird.","Dann würdest du mit dem grünen PKW, der dich überholt, zusammenstoßen. Bleibe rechts und reduziere die Geschwindigkeit.","Fahre erst an dem Hindernis vorbei, wenn es der Gegenverkehr zulässt. Du darfst den grünen PKW nicht gefährden und musst daher warten, bis dieser die Schneewehe passiert hat."],"v":["https://video4.kalaiwa.de/assets/2103115v1440.mp4"],"rn":632},{"n":"2.1.03-117","t":"Sie fahren auf der Autobahn. Was ist in dieser Situation richtig?","p":5,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["- höchstens 50 km/h fahren","- höchstens 80 km/h fahren","- die Nebelschlussleuchte einschalten"],"co":[0,2],"ex":["Bei dieser geringen Sichtweite darf höchstens mit 50 km/h gefahren werden.","Bei diesem Nebel dürfen höchstens 50 km/h gefahren werden. Auch wenn die Geschwindigkeitsbegrenzung laut Verkehrsschild bei 80 km/h liegt.","Bei weniger als 50 Metern Sichtweite darf die Nebelschlussleuchte eingeschaltet werden."],"v":["https://video4.kalaiwa.de/assets/2103117v1440.mp4"],"rn":633},{"n":"2.1.03-119","t":"Sie benutzen auf Ihrer Fahrt die Adaptive Geschwindigkeitsregelanlage (AGR) Ihres Fahrzeugs. Womit müssen Sie bei dieser Witterung rechnen?","p":3,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Die AGR hält das Fahrzeug an","Ich muss die Geschwindigkeit und den Abstand selbst regulieren","Die AGR kann in ihrer Funktion beeinträchtigt sein"],"co":[1,2],"ex":["Die AGR könnte zwar den Abstand falsch einschätzen und somit die Geschwindigkeit unnötig reduzieren - Anhalten allerdings nicht.","Die AGR ist nicht an die Witterungsverhältnisse angepasst. Der Traktor vor dir fährt wohl langsamer als 60 km/h und somit wird die AGR abbremsen, sobald der Abstand zu gering wird. Da die AGR nicht weiß, dass die Straße womöglich glatt ist, könnte sie zu spät abbremsen und es könnte zu einem Auffahrunfall kommen.","Der Schnee könnte die Sensoren der AGR, welche den Abstand und die Geschwindigkeit messen, beeinträchtigen. Auch das Bremsen könnte durch die glatte Fahrbahn beeinträchtigt sein."],"i":["https://video4.kalaiwa.de/assets/2103119.webp"],"rn":634},{"n":"2.1.03-120","t":"Sie befahren eine schmale Allee. Was müssen Sie beachten?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["- innerhalb der halben von mir übersehbaren Strecke anhalten können","- bei Gegenverkehr gegebenenfalls anhalten","- mit Unebenheiten am Fahrbahnrand durch Baumwurzeln rechnen"],"co":[0,1,2],"ex":["Sowohl du, als auch dein Gegenverkehr, müssen rechtzeitig anhalten können - somit jeder auf halber Strecke. Die gesamte übersehbare Strecke entspricht also zweimal dem Anhalteweg.","Sollte es in der Allee zu Gegenverkehr kommen, musst du anhalten können, um das entgegenkommende Fahrzeug somit leichter an dir vorbeifahren zu lassen.","Durch die Nähe der Bäume zur Straße musst du mit Unebenheiten durch die Wurzeln rechnen. Hier solltest du besonders langsam und vorsichtig fahren."],"rn":635},{"n":"2.1.03-121","t":"Die Anzeige für die Fahrdynamikregelung (ESC) hat mehrfach geleuchtet. Wie verhalten Sie sich in dieser Situation richtig?","p":3,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich verringere meine Geschwindigkeit, da sie zu hoch ist","Ich suche eine Werkstatt auf, da die ESC-Anzeige auf einen Defekt hinweist","Ich behalte meine Geschwindigkeit bei, da das ESC-System eine sichere Weiterfahrt ermöglicht"],"co":[0],"ex":["Die Fahrdynamikregelung setzt ein, wenn das Fahrzeug dabei ist auszubrechen. Ohne diese Regelung wäre das Fahrzeug wahrscheinlich ins Schleudern gekommen. Die Straßenverhältnisse wurden falsch eingeschätzt. Du solltest deine Geschwindigkeit verringern.","Die ESC-Anzeige weißt nicht auf einen Defekt hin.","Das ESC-System verhindert zwar das Ausbrechen deines Fahrzeugs, allerdings nur dort, wo die Straße noch genügend Halt bietet. Verringere deine Geschwindigkeit, um sicher weiterfahren zu können."],"v":["https://video4.kalaiwa.de/assets/2103121v1440.mp4"],"rn":636},{"n":"2.1.03-122","t":"Womit müssen Sie hier rechnen?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Mit einem verringerten Seitenabstand zum Gegenverkehr","Mit Fußgängern auf der Fahrbahn","Mit Blendung durch die tief stehende Sonne"],"co":[0,1],"ex":["Durch die Schneeverwehungen rechts und links an den Straßenrändern ist die Fahrbahn verkleinert. Daher musst du damit rechnen, dass der Seitenabstand zum Gegenverkehr geringer ist.","Wie du am Verkehrsschild erkennen kannst, kommt auf deiner rechten Seite ein Parkplatz für Wanderer. Daher musst du mit Fußgängern auf der Straße rechnen, die dort ihr Auto abstellen und an der Straße ihre Wanderung beginnen.","Du musst nicht damit rechnen, von tief stehender Sonnen geblendet zu werden. Die dichten Wolken und der Schneefall lassen keine Sonnenstrahlen durch."],"i":["https://video4.kalaiwa.de/assets/2103122.webp"],"rn":637},{"n":"2.1.03-123","t":"Bei einer Geradeausfahrt verlieren Sie durch Aquaplaning die Kontrolle über Ihr Fahrzeug. Wie reagieren Sie jetzt richtig?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Ich halte das Lenkrad möglichst gerade","Ich bremse stark ab","Ich nehme vorsichtig den Fuß vom Gaspedal"],"co":[0,2],"ex":["Während des Aquaplanings kannst du nicht lenken oder die Fahrtrichtung verändern. Allerdings solltest du versuchen, das Lenkrad so lange gerade zu halten, bis deine Reifen wieder die Fahrbahn berühren.","Du darfst nicht stark bremsen. Deine Reifen haben während des Aquaplanings keine Haftung zum Boden und eine abrupte Bremsung könnte dazu führen, dass dein Wagen ins Schleudern gerät.","Du solltest jetzt weder beschleunigen noch bremsen. Nimm also nur vorsichtig den Fuß vom Gaspedal."],"rn":638},{"n":"2.1.03-124","t":"Warum ist das Überholen auf dieser verschneiten Fahrbahn gefährlich?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Weil meine Sicht noch stärker beeinträchtigt werden kann","Weil mein Fahrzeug ins Schleudern geraten kann","Weil die Fahrbahn stellenweise vereist sein kann"],"co":[0,1,2],"ex":["Fahrzeuge, die über Schnee und Schneematsch fahren, schleudern viel mehr Material hoch, als wenn sie auf einer geräumten Spur fahren. Du musst deshalb mit einer deutlich schlechteren Sicht rechnen, sobald du hier auf die linke Spur wechselst.","Durch den Schnee auf der Fahrbahn kann dein Fahrzeug ins Schleudern kommen und du könntest beim Überholen die Kontrolle über dein Fahrzeug verlieren.","Unter der Schneedecke ist die Fahrbahn möglicherweise an manchen Stellen vereist. Dadurch könntest du die Kontrolle über dein Fahrzeug verlieren und andere und dich selbst beim Überholen gefährden."],"i":["https://video4.kalaiwa.de/assets/2103124.webp"],"rn":639},{"n":"2.1.03-044-M","t":"Womit müssen Sie in dieser Situation rechnen?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["Beim Einfahren in den Windschatten des Lkws kann mein Kraftfahrzeug nach rechts versetzt werden","Mein Kraftfahrzeug kann nach links versetzt werden","Der vorausfahrende Lkw kann nach rechts versetzt werden"],"co":[0,1],"ex":["Im Windschatten des Lkws könnte dein Kraftfahrzeug nach rechts versetzt werden, weil seine große Fläche den Seitenwind abhält. Sei bereit, nach links gegenzulenken, um nicht mit dem Lkw zu kollidieren.","Durch den starken Wind könnte dein Kraftfahrzeug nach links versetzt werden. Sei bereit, nach rechts gegenzulenken.","Der Lkw könnte nach links versetzt werden, wenn ihn ein starker Windstoß erfasst."],"i":["https://video2.kalaiwa.de/assets/2103044m.webp"],"rn":640},{"n":"2.1.03-116-M","t":"Wie sollten Sie sich hier verhalten?","p":4,"c":"2.1.03","ch":"Fahrbahn Und Witterungsverhaeltnisse","th":"Gefahrenlehre","o":["- auf meinem Fahrstreifen weiterfahren","- die Geschwindigkeit stark reduzieren","- links an den Fahrbahnschäden vorbeifahren"],"co":[0,1],"ex":["Du musst auf deinem Fahrstreifen bleiben und kannst den Fahrbahnschäden nicht ausweichen, weil eine Kurve kommt und die Sicht in diese eingeschränkt ist.","Aufgrund der Fahrbahnschäden und der eingeschränkten Sicht solltest du die Geschwindigkeit vermindern.","Wegen der Kurve hast du keine Einsicht auf herannahenden Gegenverkehr und musst deshalb auf deiner Spur bleiben."],"i":["https://video2.kalaiwa.de/assets/2103116m.webp"],"rn":641},{"n":"2.1.04-002","t":"Wie müssen Sie sich verhalten, wenn im Fernlicht plötzlich Wild auftaucht?","p":3,"c":"2.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Hupen und bremsen","Mit Fernlicht unverändert weiterfahren","Sofort abblenden"],"co":[0,2],"ex":["Du musst dich im Notfall auf ein Anhalten einstellen, damit das Wild die Fahrbahn kreuzen kann, ohne dass jemand gefährdet wird.","Du musst abblenden, da das Wild sonst im Lichtkegel stehen bleibt.","Wild bleibt im Lichtkegel stehen. Daher muss abgeblendet werden, damit das Wild die Situation als gefährlich wahrnimmt."],"rn":642},{"n":"2.1.04-005","t":"Was müssen Sie in dieser Situation beachten?","p":4,"c":"2.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["- muss ich mit besonderer Aufmerksamkeit fahren","- kann ich für andere Verkehrsteilnehmer schlecht erkennbar sein","- kann ich Entfernungen leichter einschätzen"],"co":[0,1],"ex":["Der Wechsel von Licht und Schatten ist beim Fahren anstrengend. Fahre hier besonders aufmerksam und setze eine Sonnenbrille auf, oder justiere deine Sonnenblende so, dass du nicht mehr geblendet wirst.","Andere Verkehrsteilnehmer könnten geblendet und unaufmerksam sein und dich übersehen","Die Bäume einer Allee machen es nicht leichter, Entfernungen besser einschätzen zu können."],"i":["https://video4.kalaiwa.de/assets/2104005.webp"],"rn":643},{"n":"2.1.04-102","t":"Bei Dunkelheit und Regen kommen Ihnen auf einer Landstraße Fahrzeuge mit Abblendlicht entgegen. Was müssen Sie berücksichtigen?","p":4,"c":"2.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Durch Spiegelung auf der nassen Fahrbahn können Sie geblendet werden","Durch Einschalten von Fernlicht können Sie eine Blendung vermeiden","Durch Schlieren auf der Windschutzscheibe verschlechtert sich die Sicht"],"co":[0,2],"ex":["Die Lichter der Fahrzeuge können sich auf der nassen Fahrbahn spiegeln. Wirst du stark geblendet, dann orientiere dich am rechten Fahrbahnrand. Vermindere im Bedarfsfall die Geschwindigkeit.","Das Fernlicht blendet den Gegenverkehr und verbessert die Sichtverhältnisse nicht.","Passe deine Fahrweise den Sichtverhältnissen an."],"rn":644},{"n":"2.1.04-103","t":"Welche Gefahren können entstehen, wenn Sie mit eingeschaltetem Fernlicht fahren?","p":4,"c":"2.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["Wild auf der Fahrbahn wird geblendet und bleibt im Lichtkegel stehen","Entgegenkommende werden geblendet","Liegen gebliebene Fahrzeuge auf meiner Fahrbahnseite werden zu spät erkannt"],"co":[0,1],"ex":["Tritt dieser Fall ein, dann musst du Abblenden, in der Hoffnung, dass das Wild das Weite sucht.","Daher solltest du, sobald Gegenverkehr in Sicht ist, das Fernlicht ausschalten.","Liegen gebliebene Fahrzeuge auf deiner Fahrbahnseite werden frühzeitig erkannt."],"rn":645},{"n":"2.1.04-104","t":"Sie erkennen nachts auf einer Landstraße Personen auf Ihrer Fahrbahnseite. Wie verhalten Sie sich, wenn Sie durch ein entgegenkommendes Fahrzeug geblendet werden?","p":4,"c":"2.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["- halte nötigenfalls an","- schalte Fernlicht ein","- schaue zum rechten Fahrbahnrand"],"co":[0,2],"ex":["Vermindere die Geschwindigkeit und halte an, falls das notwendig ist, um die Personen auf der Fahrbahn nicht zu gefährden.","Das würde den entgegenkommenden Verkehr und die Personen auf der Fahrbahn blenden.","Zudem solltest du die Geschwindigkeit vermindern und notfalls anhalten, um die Fußgänger nicht zu gefährden."],"rn":646},{"n":"2.1.04-106","t":"Was erhöht die Unfallgefahr?","p":3,"c":"2.1.04","ch":"Dunkelheit Und Schlechte Sicht","th":"Gefahrenlehre","o":["- mit vereisten Seitenscheiben","- mit einer beschlagenen Frontscheibe","- bei tief stehender Sonne von vorn"],"co":[0,1,2],"ex":["Wenn deine Seitenscheiben vereist sind, kannst du den Verkehr nur unzureichend beobachten. Befreie alle Scheiben von Eis bevor du losfährst.","Wenn deine Frontscheibe beschlagen ist, hast du kein Sichtfeld nach vorn. Halte an, bzw. fahre nicht los. Richte das Gebläse und die Heizung auf die Frontscheibe oder wische die Scheibe trocken, bevor du losfährst.","Du könntest geblendet werden, wenn du auf die tief stehende Sonne zufährst. So könntest du andere Verkehrsteilnehmer später wahrnehmen und die Unfallgefahr erhöht sich. Sei besonders konzentriert, setze eine Sonnenbrille auf oder klappe deine Sonnenblende runter."],"rn":647},{"n":"2.1.05-002","t":"Wozu kann langes Fahren mit höherer Geschwindigkeit führen?","p":4,"c":"2.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["Die Reaktionsbereitschaft nimmt zu","Das Gefühl für die Geschwindigkeit lässt nach","Es wird zu dicht aufgefahren"],"co":[1,2],"ex":["Die Reaktionsbereitschaft nimmt bei langem Fahren ab.","Man gewöhnt sich an die Geschwindigkeit. Dadurch läuft man Gefahr, in Risikosituationen verzögert zu reagieren.","Die hohe Geschwindigkeit wird nicht mehr als solche wahrgenommen und dadurch werden Abstände größer eingeschätzt, als sie eigentlich sind."],"rn":648},{"n":"2.1.05-008","t":"Sie nähern sich mit hoher Geschwindigkeit einer engen Linkskurve. Warum müssen Sie die Geschwindigkeit bereits vor der Kurve vermindern?","p":4,"c":"2.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["- links aus der Kurve rutschen kann","- rechts aus der Kurve rutschen kann","- ins Schleudern geraten kann"],"co":[1,2],"ex":["Wenn Du mit zu hoher Geschwindigkeit versuchst, nach links zu fahren, dann rutscht Du geradeaus (rechts aus der Kurve).","Wenn Du mit zu hoher Geschwindigkeit in eine Linkskurve fährst, dann kann das Fahrzeug bei der Kurvendurchfahrt nicht auf der Fahrbahn gehalten werden und kommt somit rechts von der Fahrbahn ab.","Wenn die Geschwindigkeit, mit der Du in eine Kurve fährst, zu hoch ist, entstehen hohe Kräfte und die Reifen deines Fahrzeugs verlieren die Bodenhaftung. Dadurch kann dein Fahrzeug ins Schleudern geraten."],"rn":649},{"n":"2.1.05-009","t":"In welcher Situation wird die eigene Geschwindigkeit häufig unterschätzt?","p":4,"c":"2.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["Bei schmalen Straßen mit unebener Fahrbahnoberfläche","Nach längerer Fahrt mit höherer Geschwindigkeit","Bei breiten und gut ausgebauten Straßen"],"co":[1,2],"ex":["Schmale und unebene Fahrbahnen erfordern besondere Vorsicht und langsames und sicheres Fahren. Hier ist es wahrscheinlicher, dass du deine Geschwindigkeit überschätzt.","Bist du längere Zeit mit sehr hoher Geschwindigkeit gefahren, bist du daran gewöhnt und könntest die Geschwindigkeit deshalb unterschätzen.","Breite und gut ausgebaute Straßen wirken sicherer und lassen sich leichter befahren. Hier kann es dir schnell passieren, dass du deine Geschwindigkeit unterschätzt, weil man dadurch weniger die tatsächliche Geschwindigkeit spürt."],"rn":650},{"n":"2.1.05-010","t":"Womit sollten Sie rechnen, wenn Sie auf der Autobahn mit sehr hoher Geschwindigkeit fahren?","p":3,"c":"2.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["Andere Verkehrsteilnehmer unterschätzen meine Geschwindigkeit","Seitenwind kann meine Fahrstabilität beeinträchtigen","Ich kann möglicherweise nicht rechtzeitig auf Gefahren reagieren"],"co":[0,1,2],"ex":["Andere Verkehrsteilnehmer könnten deine Geschwindigkeit unterschätzen und z.B. plötzlich zum Überholen ausscheren. Sei besonders vorausschauend und rechne mit dem Fehlverhalten anderer.","Bei hohen Geschwindigkeiten kann schon leichter Seitenwind dein Fahrzeug nach rechts oder links versetzen.","Möglicherweise kannst du bei hoher Geschwindigkeit nicht rechtzeitig abbremsen, wenn eine Gefahrensituation auftritt. Falls du siehst, dass Gefahren drohen, reduziere deine Geschwindigkeit dementsprechend vorher."],"rn":651},{"n":"2.1.05-101","t":"Was ist für die Wahl der Geschwindigkeit beim Befahren von Alleen mit geringer Fahrbahnbreite von besonderer Bedeutung?","p":4,"c":"2.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["Das gleichzeitige Abschätzen des Seitenabstands zu den Bäumen und zum Gegenverkehr","Die schnell wechselnden Lichtverhältnisse erleichtern das Abschätzen der seitlichen Abstände","Dass bei einem entgegenkommenden breiten Fahrzeug unter Umständen in der halben übersehbaren Strecke angehalten werden muss"],"co":[0,2],"ex":["Das ist notwendig, um ungefährdet an beiden vorbeifahren zu können. Fahre im Zweifelsfall lieber langsamer.","Der schnelle Wechsel von Licht und Schatten aufgrund der Bäume erleichtert das Abschätzen der seitlichen Abstände nicht, sondern erschwert es. Die Augen müssen sich jedes Mal von neuem an die Lichtverhältnisse gewöhnen.","So haben dieses Fahrzeug und du ausreichend Zeit, die Geschwindigkeit zu reduzieren, sowie ungefährdet und ungefährdend aneinander vorbeizufahren."],"rn":652},{"n":"2.1.05-105-M","t":"Worauf sollten Sie sich in dieser Situation einstellen?","p":4,"c":"2.1.05","ch":"Geschwindigkeit","th":"Gefahrenlehre","o":["Auf Wildwechsel","Auf Gegenverkehr, der die Kurve schneidet","Auf ein langsam fahrendes Fahrzeug auf meinem Fahrstreifen"],"co":[0,1,2],"ex":["Aufgrund der starken Bewaldung kann Wild erst spät erkannt werden. Stelle dich darauf ein und fahre langsam und in Bremsbereitschaft.","Du kannst nicht weit in die Kurve einsehen und solltest daher die Geschwindigkeit beim Einfahren reduzieren.","Es ist möglich, dass ein anderes Fahrzeug langsam vor dir fährt."],"i":["https://video2.kalaiwa.de/assets/2105105m.webp"],"rn":653},{"n":"2.1.06-011","t":"Warum müssen Sie jetzt stark bremsen?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Wegen des Lkws","Wegen des Pkws","Wegen des Traktors"],"co":[1],"ex":["Der LKW bleibt an der Einfahrt stehen und ist somit kein Grund für dich, stark abzubremsen.","Der PKW schwenkt beim Einfahren in die Straße auf deine Fahrbahnseite. Daher musst du stark bremsen, um nicht mit ihm zusammenzustoßen.","Der Traktor ist kein Grund, um abzubremsen."],"v":["https://video2.kalaiwa.de/assets/2106011v1440.mp4"],"rn":654},{"n":"2.1.06-013","t":"Sie möchten überholen. Wie verhalten Sie sich jetzt richtig?","p":5,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich behalte die Geschwindigkeit bei und setze den Überholvorgang fort","Ich breche den Überholvorgang ab und bleibe hinter dem Lkw","Ich beschleunige und setze den Überholvorgang zügig fort"],"co":[1],"ex":["Breche den Überholvorgang ab und bleibe hinter dem LKW.","Lass den roten PKW überholen und warte mit deinem Überholvorgang, bis dieser vorbeigefahren ist.","Warte, bis der rote PKW auf der rechten Spur an dir vorbeigefahren ist und starte dann den Überholvorgang."],"v":["https://video2.kalaiwa.de/assets/2106013v1440.mp4"],"rn":655},{"n":"2.1.06-014","t":"Wie verhalten Sie sich richtig?","p":5,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich bremse, setze den Überholvorgang aber fort","Ich breche den Überholvorgang ab und schere wieder nach rechts ein","Ich setze den Überholvorgang zügig fort"],"co":[2],"ex":["Das wäre nicht zielführend und würde den Fahrer hinter dir provozieren.","Du bist bereits auf Höhe des LKWs. Daher solltest du den Überholvorgang beenden und erst danach rechts einscheren.","Der rote PKW kommt sehr schnell angefahren. Da du bereits auf der linken Spur bist, setze den Überholvorgang zügig fort."],"v":["https://video2.kalaiwa.de/assets/2106014v1440.mp4"],"rn":656},{"n":"2.1.06-015","t":"Wie verhalten Sie sich richtig?","p":5,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich überhole den Transporter und wechsle dann auf den mittleren Fahrstreifen","Ich wechsle sofort auf den Fahrstreifen nach rechts","Ich fordere den Nachfolgenden durch leichtes Bremsen auf, mehr Abstand herzustellen"],"co":[0],"ex":["Versuche dich nicht durch den Drängler an deinem Überholvorgang stören zu lassen und wechsle nach Überholen des Transporters auf den Mittelstreifen.","In deinem toten Winkel befindet sich ein Fahrzeug. Überhole den Transporter und ordne dich dann wieder rechts ein.","So würdest du ihn nur provozieren und könnte gefährlich werden."],"v":["https://video4.kalaiwa.de/assets/2106015v1440.mp4"],"rn":657},{"n":"2.1.06-030","t":"Sie möchten auf einer Allee überholen. Welche Besonderheit sollten Sie beachten?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Fahrzeuge mit hohen Aufbauten weichen hier häufig Ästen aus","Die Häufigkeit von Baumunfällen ist hier besonders hoch","Seitenabstände werden hier häufig falsch eingeschätzt"],"co":[0,1,2],"ex":["Fahrzeuge mit hohen Aufbauten wie z.B. Lkws können durch die Äste besonders stark beeinträchtigt werden. Insbesondere während eines Überholvorgangs musst du also damit rechnen, dass diese Fahrzeuge eventuell Ästen ausweichen, um eine Kollision zu vermeiden.","Durch die Vielzahl an Bäumen an den Straßenrändern steigt das Risiko für Baumunfälle erheblich, z.B. durch die Kollision mit einem (umgefallenen) Baum.","Durch die Bäume links und rechts am Straßenrand neigen viele Verkehrsteilnehmer dazu, auf einer Allee mehr in der Straßenmitte zu fahren. Dadurch besteht die Gefahr, dass du andere Fahrzeuge ohne ausreichenden Seitenabstand überholst."],"rn":658},{"n":"2.1.06-032","t":"Sie fahren auf einer Straße mit einem Fahrstreifen für jede Richtung. Vor Ihnen fährt ein geschlossener Verband von Kraftfahrzeugen. Warum sollten Sie zur Vermeidung von gefährlichen Situationen auf ein Überholen verzichten?","p":3,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil ich die Verkehrssituation vor dem geschlossenen Verband nicht überblicken kann","Weil ich den geschlossenen Verband nicht durch vorzeitiges Einscheren unterbrechen soll","Weil der Überholweg deutlich größer als bei Einzelfahrzeugen ist"],"co":[0,1,2],"ex":["Je nach Länge des geschlossenen Verbandes kannst du die Verkehrssituation davor nicht überblicken. Um eine Kollision mit möglichem Gegenverkehr zu vermeiden, solltest auf das Überholen verzichten.","Du sollst nicht zwischen Fahrzeugen einscheren, die in einem geschlossenen Verband fahren. Beim Überholvorgang könntest du aber gezwungen sein, vorzeitig einzuscheren.","Fahrzeuge, die in einem geschlossenen Verband fahren, gelten de facto als ein einziges Fahrzeug. Du darfst nur den kompletten Verband überholen, nicht die Einzelfahrzeuge, was den Überholweg deutlich größer macht."],"rn":659},{"n":"2.1.06-105","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich bremse auf Schrittgeschwindigkeit ab","Ich fahre möglichst weit rechts","Ich fahre an den Fußgängern vorbei"],"co":[0,1],"ex":["Bevor du an den Fußgängern vorbeifahren kannst, musst du den Gegenverkehr passieren lassen. Bremse auf Schrittgeschwindigkeit ab, um den Gegenverkehr passieren zu lassen und die Fußgänger nicht zu gefährden oder zu verängstigen.","Dir kommt ein Fahrzeug entgegen. Dieses wird die Fußgänger passieren. Er wird auch dich passieren. Vereinfache dies, indem du weit rechts fährst.","Dir kommt ein Fahrzeug entgegen, du darfst nicht überholen."],"v":["https://video2.kalaiwa.de/assets/2106105v1440.mp4"],"rn":660},{"n":"2.1.06-007-M","t":"Sie möchten überholen. Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich behalte die Geschwindigkeit bei","Ich verzichte auf das Überholen","Ich beschleunige"],"co":[1],"ex":["Du solltest leicht abbremsen, um nicht auf den vor Dir fahrenden Pkw aufzufahren.","Du wirst gerade von einem anderen Verkehrsteilnehmer überholt. Ein blauer Pkw befindet sich in Deinem toten Winkel. Warte, bis er seinen Überholvorgang abgeschlossen hat.","Durch Beschleunigen würdest Du Dich und die anderen Verkehrsteilnehmer in Gefahr bringen."],"v":["https://video2.kalaiwa.de/assets/2106007mv1440.mp4"],"rn":661},{"n":"2.1.06-008-M","t":"Sie möchten überholen. Was sollten Sie beachten?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- gleichzeitig mit dem blauen Pkw","- erst dann, wenn kein Fahrzeug entgegenkommt","- nur, wenn ich die dafür erforderliche Strecke übersehen kann"],"co":[1,2],"ex":["Du darfst erst überholen, wenn Du die Strecke selbst einsehen kannst. Du darfst dich beim Überholen nicht auf andere Verkehrsteilnehmer verlassen.","Der Gegenverkehr darf beim Überholen keinesfalls in Gefahr gebracht werden.","Beim Überholen darf weder der Gegenverkehr noch das überholte Fahrzeug in Gefahr geraten. Dafür muss die gesamte Strecke übersehbar und frei sein."],"v":["https://video2.kalaiwa.de/assets/2106008mv1440.mp4"],"rn":662},{"n":"2.1.06-012-M","t":"Wie verhalten Sie sich richtig?","p":5,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich überhole den roten Transporter und wechsle dann in den mittleren Fahrstreifen","Ich fordere den Nachfolgenden durch leichtes Bremsen auf, mehr Abstand herzustellen","Ich überhole den blauen Pkw und wechsle dann in den mittleren Fahrstreifen"],"co":[2],"ex":["Zwischen dem roten Transporter und dem blauen PKW ist nicht ausreichend Abstand, um einzuscheren. Überhole den blauen PKW und wechsle dann auf die mittlere Spur.","Das würde den ohnehin schon aggressiven Autofahrer zusätzlich provozieren und eine gefährliche Situation herbeiführen. Setze dein Überholmanöver wie gewohnt fort und schere ein, sobald ausreichend Platz auf der mittleren Spur vorhanden ist.","Lass dich nicht von dem Drängler irritieren. Überhole den blauen PKW und wechsle anschließend auf die mittlere Fahrbahn, wenn ausreichend Platz ist."],"v":["https://video2.kalaiwa.de/assets/2106012mv1440.mp4"],"rn":663},{"n":"2.1.06-017-M","t":"Warum müssen Sie hier verzögern?","p":3,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil maximal 80 km/h erlaubt sind","Wegen des überholenden Pkws","Wegen des Traktors"],"co":[1],"ex":["Auf Landstraßen sind 100 km/h zulässig.","Verzögere hier, damit der Überholende den Vorgang beenden kann, ohne jemanden zu gefährden.","Der Traktor stellt keinen Grund zu verzögern dar."],"v":["https://video2.kalaiwa.de/assets/2106017mv1440.mp4"],"rn":664},{"n":"2.1.06-018-M","t":"Wie sollten Sie sich jetzt verhalten?","p":5,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich fahre äußerst rechts","Ich beschleunige","Ich verzögere"],"co":[0,2],"ex":["Dann kann der rote PKW so früh wie möglich einscheren.","Dann würdest du riskieren, dass der rote PKW nicht mehr rechtzeitig vor dem Gegenverkehr einschert und mit diesem zusammenstößt.","Dadurch erleichterst du es dem Überholenden, den Überholvorgang abzuschließen."],"v":["https://video4.kalaiwa.de/assets/2106018mv1440.mp4"],"rn":665},{"n":"2.1.06-021-M","t":"Sie möchten überholen. Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich überhole den Lkw nicht, da ich die dafür erforderliche Strecke nicht einsehen kann","Ich folge dem Motorrad, da der Lkw durch Blinken eine Überholmöglichkeit signalisiert","Ich verringere den Abstand zum Lkw, damit ich schneller überholen kann"],"co":[0],"ex":["Überholen ist nur erlaubt, wenn eine Behinderung des Gegenverkehrs während des gesamten Überholvorgangs ausgeschlossen ist. Durch Kurven, Hügel und Bäume ist die Strecke nicht gut einsehbar. Der Lkw sollte erst überholt werden, wenn die Fahrbahn besser überblickt werden kann.","Du solltest niemals überholen, wenn Du den entgegenkommenden Verkehr nicht einsehen kannst.","Wenn Du den Abstand verringerst, kannst Du die Strecke vor dir möglicherweise noch schlechter einsehen."],"v":["https://video4.kalaiwa.de/assets/2106021mv1440.mp4"],"rn":666},{"n":"2.1.06-023-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- vorsichtig, da der Traktor mich dazu auffordert","- nicht, da der Traktor nach links ausscheren wird","- sofort, da der Überholweg dafür ausreicht"],"co":[1],"ex":["Der Traktor fordert nicht zum Überholen auf, da er links und nicht rechts blinkt.","Durch seinen Blinker auf der linken Seite signalisiert der Traktor, dass er gleich den Fahrradfahrer, der vor ihm fährt, überholen wird.","Es muss damit gerechnet werden, dass der Traktor sofort nach links ausschert. Somit ist der Überholweg nicht frei."],"v":["https://video4.kalaiwa.de/assets/2106023mv1440.mp4"],"rn":667},{"n":"2.1.06-024-M","t":"Sie möchten überholen. Wie verhalten Sie sich hier richtig?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich überhole nicht, da Gegenverkehr auftauchen könnte","Ich überhole, da kein Gegenverkehr zu erkennen ist","Ich überhole nicht, da das gelbe Fahrzeug überholen könnte"],"co":[0,2],"ex":["Die Strecke ist nicht sehr gut einsehbar. Die Straße verläuft nicht eben und ist vermutlich kurvig. Es könnte jederzeit ein Fahrzeug in entgegenkommender Richtung auftauchen.","In dieser Situation ist es sicherer, auf das Überholen zu verzichten.","Vor dem gelben Fahrzeug befindet sich ein weiteres Fahrzeug. Da das gelbe Fahrzeug vor Dir das Vorrecht zum Überholen hat, musst Du abwarten."],"i":["https://video2.kalaiwa.de/assets/2106024m.webp"],"rn":668},{"n":"2.1.06-026-M","t":"Warum dürfen Sie jetzt nicht überholen?","p":5,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- roten Pkws","- Straßenverlaufs","- Motorrads"],"co":[1,2],"ex":["Der rote Pkw wäre im Falle eines Überholmanövers nicht gefährdet.","Aufgrund des kurvigen Straßenverlaufs ist die Fahrbahn schlecht einsehbar. Du darfst nur überholen, wenn eine Gefährdung sicher ausgeschlossen werden kann!","Du darfst nicht überholen, wenn Gegenverkehr kommt."],"v":["https://video4.kalaiwa.de/assets/2106026mv1440.mp4"],"rn":669},{"n":"2.1.06-027-M","t":"Warum dürfen Sie jetzt nicht überholen?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- Motorrads","- roten Pkws","- ausgeschilderten Überholverbots"],"co":[0],"ex":["Man darf nur überholen, wenn man die vor einem liegende Straße überblicken kann. Erst wenn man dies getan hat, kann man sicher sein, dass kein Gegenverkehr kommt. Das ist hier noch nicht geschehen. Deshalb darf man hier nicht überholen. Offensichtlich kommt wirklich ein Motorrad, den orangefarbenen Helm sieht man schon.","Der rote Pkw ist bereits an dir vorbeigefahren und kommt dir beim Überholvorgang nicht in die Quere.","Ein solches Verkehrszeichen steht nirgendwo an der Straße."],"v":["https://video4.kalaiwa.de/assets/2106027mv1440.mp4"],"rn":670},{"n":"2.1.06-028-M","t":"Warum dürfen Sie hier nicht überholen?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- den weiteren Straßenverlauf nicht ausreichend einsehen kann","- die Leitlinie nicht überfahren darf","- bei Gegenverkehr keinen ausreichenden Seitenabstand zu den Radfahrern einhalten kann"],"co":[0,2],"ex":["Durch die Kurve und die Bäume kannst du den weiteren Straßenverlauf nicht ausreichend einsehen. Deshalb darfst du hier nicht überholen.","Die Leitlinie ist nicht durchgezogen, du darfst sie also überfahren.","Außerorts musst du bei Radfahrern einen seitlichen Mindestabstand von 2 Metern einhalten. Bei plötzlich auftretendem Gegenverkehr könntest du beim Überholen diesen Abstand nicht einhalten."],"i":["https://video2.kalaiwa.de/assets/2106028m.webp"],"rn":671},{"n":"2.1.06-029-M","t":"Warum dürfen Sie hier nicht überholen?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil eine Gefährdung des Gegenverkehrs möglich ist","Weil der Seitenabstand zu den Radfahrern zu gering wird","Weil die Leitlinie nicht überfahren werden darf"],"co":[0,1],"ex":["Aus der entgegengesetzten Richtung nähern sich bereits andere Fahrzeuge. Der Abstand reicht vermutlich nicht aus, um zu überholen. Wenn du jetzt überholst, läufst du Gefahr, mit dem Gegenverkehr zu kollidieren, bevor du wieder vor den Radfahrern einscheren kannst.","Beim Überholen sollte der Seitenabstand zu den Radfahrern mindestens 1,5 Meter betragen. Dieser Abstand kann in dieser Situation nicht gewährleistet werden, da die Fahrbahn zu schmal ist. Auf der Gegenseite parken Autos nah an der Straße, die ebenfalls berücksichtigt werden müssen und den Platz beim Überholen verringern.","Die Mittellinie ist nicht durchgezogen und dürfte überfahren werden. Dies stellt also keinen Grund dafür dar, nicht zu überholen."],"i":["https://video2.kalaiwa.de/assets/2106029m.webp"],"rn":672},{"n":"2.1.06-031-M","t":"Warum müssen Sie den Überholvorgang jetzt abbrechen?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil ein Überholverbotsschild in Sicht ist","Weil der Traktor nach links abbiegen wird","Weil das Motorrad mich überholen wird"],"co":[1],"ex":["Es ist kein Überholverbotsschild in Sicht.","Der Traktor hat den Blinker gesetzt und wird nach links abbiegen. Um eine Kollision und eine Gefährdung zu vermeiden, musst du deinen Überholvorgang abbrechen.","Das Motorrad scheint nicht überholen zu wollen."],"v":["https://video2.kalaiwa.de/assets/2106031mv1440.mp4"],"rn":673},{"n":"2.1.06-033-M","t":"Warum ist ein Überholen in dieser Situation zu gefährlich?","p":5,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil vorausfahrende Fahrzeuge ausscheren könnten","Weil ich die zum Überholen notwendige Strecke nicht weit genug einsehen kann","Weil zwischen den vorausfahrenden Fahrzeugen nicht ausreichend Platz zum Wiedereinscheren ist"],"co":[0,1,2],"ex":["Rechne damit, dass der Pkw vor dir zum Überholen ausschert. Beachte, dass die Fahrzeuge vor dir Überholvorrang haben.","In der Linkskurve kannst du die Überholstrecke nicht ausreichend einsehen. Wahrscheinlich musst du den Überholvorgang abbrechen und zwischen zwei Fahrzeugen einscheren.","Wenn du zwischen den vorausfahrenden Fahrzeugen einscherst, habt ihr zu wenig Abstand zueinander. Dadurch gefährdest du dich und die anderen Verkehrsteilnehmer."],"v":["https://video2.kalaiwa.de/assets/2106033mv1440.mp4"],"rn":674},{"n":"2.1.06-035-M","t":"Die Fahrzeuge vor Ihnen fahren mit etwa 30 km/h. Warum dürfen Sie vor der Kurve nicht überholen?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil der rote Pkw zum Überholen ausscheren könnte","Weil mein Überholweg zu lang ist","Weil ich die Leitlinie nicht überfahren darf"],"co":[0,1],"ex":["Der rote Pkw hat das Vorrecht, vor dir zu überholen.","Dein Überholweg ist zu lange, um beide Fahrzeuge vor der Kurve zu überholen. Um zwischen den beiden Pkws einzuscheren, reicht der Abstand nicht aus. Weil die Kurve nicht einsehbar ist, kannst du nicht wissen, ob Gegenverkehr kommt.","Grundsätzlich darfst du die gestrichelte Linie überfahren."],"i":["https://video2.kalaiwa.de/assets/2106035m.webp"],"rn":675},{"n":"2.1.06-103-M","t":"Weshalb müssen Sie jetzt auf den rechten Fahrstreifen wechseln?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["- gelben Traktors","- roten Pkws","- blauen Pkws"],"co":[1],"ex":["Der gelbe Traktor ist weit genug entfernt. Von ihm geht keine Gefahr aus.","Der rote Pkw überholt den Traktor und befindet sich somit unmittelbar auf deiner Fahrbahn. Damit du einen Zusammenstoß vermeiden kannst, musst du bereits jetzt sofort auf die rechte Spur wechseln.","Der blaue Pkw spielt in diesem Fall keine Rolle."],"v":["https://video2.kalaiwa.de/assets/2106103mv1440.mp4"],"rn":676},{"n":"2.1.06-104-M","t":"Wie verhalten Sie sich hier richtig?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich fordere die Radfahrerinnen durch Hupen auf, hintereinanderzufahren","Ich überhole die Radfahrerinnen","Ich überhole die Radfahrerinnen vorerst nicht"],"co":[2],"ex":["Das Hupen innerorts ist grundsätzlich verboten, außer es liegt eine Gefährdung vor. Außerdem könntest du durch Hupen die Radfahrerinnen erschrecken.","Überholst du mit zu wenig seitlichem Abstand, gefährdest du die Radfahrerinnen.","Du kannst seitlich nicht genügend Abstand zu den Radfahrerinnen einhalten, da sie nebeneinander fahren. Du solltest vorerst nicht überholen."],"v":["https://video4.kalaiwa.de/assets/2106104mv1440.mp4"],"rn":677},{"n":"2.1.06-106-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Ich verringere meine Geschwindigkeit","Ich überhole den Radfahrer","Ich behalte meine Geschwindigkeit bei"],"co":[0],"ex":["Vor dir befindet sich eine Straßeninsel, durch die du nicht mehr genug Platz hast, um den Radfahrer zu überholen. Du musst deine Geschwindigkeit verringern und so lange hinter dem Radfahrer bleiben, bis die Fahrbahn wieder breiter ist.","Du kannst den Radfahrer erst nach der verengten Fahrbahnstelle wieder überholen. Überholst du jetzt, kannst du keinen ausreichenden Abstand zum Radfahrer einhalten und könntest mit ihm kollidieren.","Wenn du deine Geschwindigkeit beibehältst, dann erreichst du die Stelle mit der Fahrbahnverengung zu selben Zeit wie der Radfahrer. Das führt dazu, dass du entweder mit dem Radfahrer oder der Straßeninsel in der Mitte kollidieren würdest oder sehr abrupt bremsen müsstest. Letzteres ist ebenfalls keine gute Option, da du damit das Risiko eines Auffahrunfalls für den Wagen hinter dir erhöhst."],"v":["https://video4.kalaiwa.de/assets/2106106mv1440.mp4"],"rn":678},{"n":"2.1.06-107-M","t":"Warum sollten Sie den Mofafahrer in dieser Situation nicht überholen?","p":4,"c":"2.1.06","ch":"Ueberholen","th":"Gefahrenlehre","o":["Weil ich nicht wesentlich schneller als der Mofafahrer fahren darf","Weil der Mofafahrer dann stürzen könnte","Weil ich den erforderlichen Seitenabstand nicht einhalten kann"],"co":[0,1,2],"ex":["Im Baustellenbereich ist die Geschwindigkeit auf 30 km/h begrenzt. Du darfst also nicht so schnell fahren wie nötig, um den Mofafahrer sicher zu überholen.","Wegen der Enge der Fahrbahn und des schlechten Zustands der Fahrbahn könnte der Mofafahrer stürzen, falls du ihn überholst.","Durch die Baustellenbegrenzung auf der linken Seite kannst du den erforderlichen Seitenabstand zum Überholen nicht einhalten."],"v":["https://video4.kalaiwa.de/assets/2106107mv1440.mp4"],"rn":679},{"n":"2.1.07-020","t":"Wie sollten Sie sich jetzt verhalten?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich fahre so weit wie möglich nach rechts","Ich bremse","Ich wechsle auf den linken Fahrstreifen"],"co":[0,1],"ex":["Mache zudem die Warnblinkanlage an, um andere Verkehrsteilnehmer darauf aufmerksam zu machen.","Fahre so weit wie möglich nach rechts und bremse.","So würdest du dem Geisterfahrer direkt entgegenkommen. Das würde die Situation noch zusätzlich verschärfen."],"v":["https://video4.kalaiwa.de/assets/2107020v1440.mp4"],"rn":680},{"n":"2.1.07-029","t":"Was müssen Sie beim Befahren von schmalen Alleen beachten?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- muss ich besonders defensiv fahren","- bin ich vor Eisglätte geschützt","- kann ich Kurven häufig schlecht einsehen"],"co":[0,2],"ex":["Du musst in Alleen wegen der eingeschränkten Sicht mit vielen Gefahren rechnen. Fahre deshalb defensiver als sonst.","Die Bäume einer Allee schützen dich nicht vor Eisglätte.","In Kurven könnte deine Sicht auf die Fahrbahn nach der Kurve eingeschränkt sein. Deshalb siehst du Hindernisse möglicherweise erst sehr spät."],"rn":681},{"n":"2.1.07-101","t":"Wann kann ein schnell fahrender Pkw auf trockener, gerader Straße seitwärts ausbrechen?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Wenn ein Reifen platzt","Wenn plötzlich Gegenwind auftritt","Wenn er plötzlich von starkem Seitenwind erfasst wird"],"co":[0,2],"ex":["Im Falle eines geplatzten Reifens gibt es keine gleichmäßige Belastung mehr. Es kann passieren, dass vor allem bei hohen Geschwindigkeiten das Fahrzeug seitlich ausbricht.","Gegenwind kann dich Abbremsen, dadurch dass er jedoch frontal kommt, ist es kein Auslöser für seitliches Ausbrechen.","Durch starken Seitenwind kann es passieren, dass ein PKW seitwärts ausbricht."],"rn":682},{"n":"2.1.07-102","t":"Was erleichtert das Fahren im Kolonnenverkehr?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Fahren mit ständig eingeschaltetem Warnblinklicht","Das Beobachten der Kolonne durch die Scheiben der Vorausfahrenden","Leicht versetztes Fahren im eigenen Fahrstreifen"],"co":[1,2],"ex":["Das ist in diesem Fall nicht erlaubt, da du hier niemanden warnen musst.","So kannst du dich frühzeitig auf Veränderungen einstellen.","So siehst du besser, was vor dir geschieht und kannst frühzeitig darauf reagieren."],"rn":683},{"n":"2.1.07-106","t":"Bei schneller Autobahnfahrt platzt ein Reifen an Ihrem Pkw. Wie verhalten Sie sich?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Möglichst auf dem Seitenstreifen anhalten, Warnblinklicht einschalten und Warndreieck aufstellen","Gas wegnehmen, wenn nötig gegenlenken und vorsichtig abbremsen","Sofort Vollbremsung durchführen, anschließend auf den Seitenstreifen wechseln"],"co":[0,1],"ex":["Du musst das Fahrzeug so schnell wie möglich von der Fahrbahn bekommen. Vergiss anschließend nicht, deine Warnweste anzuziehen, bevor du aus dem Auto aussteigst. Nach Absicherung der Pannenstelle solltest du den Pannendienst anrufen.","Im nächsten Schritt solltest du das Fahrzeug auf den Seitenstreifen lenken, um den Fließverkehr nicht weiter zu behindern. Reduziere die Geschwindigkeit und verzichte auf gefährliche Manöver.","Eine Vollbremsung mit einem geplatzten Reifen ist zu vermeiden, da du wahrscheinlich sofort ins Schleudern gerätst."],"rn":684},{"n":"2.1.07-109","t":"Sie erhöhen Ihre Geschwindigkeit von 50 km/h auf 100 km/h. Wie verändert sich der Bremsweg entsprechend der Faustformel?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Er halbiert sich von 50 m auf 25 m","Er verdoppelt sich von 15 m auf 30 m","Er vervierfacht sich von 25 m auf 100 m"],"co":[2],"ex":["Bei einer Erhöhung der Geschwindigkeit verkürzt sich der Bremsweg nicht.","Der Bremsweg vervierfacht sich, wenn du die Geschwindigkeit verdoppelst.","Der Bremsweg vervierfacht sich, wenn du die Geschwindigkeit verdoppelst."],"rn":685},{"n":"2.1.07-111","t":"Warum müssen Sie in dieser Situation bremsbereit sein?","p":5,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Weil das andere Fahrzeug weiterfahren könnte","Weil eine Geschwindigkeitsbegrenzung erkennbar ist","Weil der Straßenverlauf dies erfordert"],"co":[0],"ex":["Du bist zwar auf der Vorfahrtsstraße, jedoch scheint dies dem Fahrer des anderen Autos nicht bewusst zu sein, oder er sieht dich aufgrund der Bewaldung nicht. Stell dich darauf ein, im Bedarfsfall zu bremsen.","Es ist keine Geschwindigkeitsbegrenzung erkennbar.","Der Straßenverlauf erfordert kein Bremsen."],"v":["https://video2.kalaiwa.de/assets/2107111v1440.mp4"],"rn":686},{"n":"2.1.07-112","t":"Warum sollten Sie jetzt Ihre Geschwindigkeit verringern?","p":5,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Weil der Straßenverlauf dies erfordert","Weil ich für andere Verkehrsteilnehmer schlecht zu sehen bin","Weil ich Vorfahrt gewähren muss"],"co":[1],"ex":["Der Straßenverlauf erfordert keine Verminderung der Geschwindigkeit.","Du befindest dich zwar auf der Vorfahrtsstraße, jedoch hat das Fahrzeug, das in die Straße einfahren will, aufgrund der starken Bewaldung schwere Einsicht. Verringere die Geschwindigkeit, sodass es einfahren kann, ohne dass jemand gefährdet wird.","Du bist auf der Vorfahrtsstraße und musst keine Vorfahrt gewähren."],"v":["https://video2.kalaiwa.de/assets/2107112v1440.mp4"],"rn":687},{"n":"2.1.07-115","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":5,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich bremse kurz, damit der nachfolgende Fahrer seine Geschwindigkeit reduziert","Ich beschleunige, um einen ausreichenden Sicherheitsabstand herzustellen","Ich behalte die Geschwindigkeit bei und fahre unverändert weiter"],"co":[2],"ex":["Lass dich nicht vom nachfolgenden Fahrer beunruhigen und behalte deine Fahrgeschwindigkeit bei.","Fahre unverändert nach vorgeschriebener Geschwindigkeit weiter.","Hier ist die vorgeschriebene Fahrgeschwindigkeit 80 km/h. Diese hältst du ein. Lass dich nicht von dem Drängler irritieren."],"v":["https://video4.kalaiwa.de/assets/2107115v1440.mp4"],"rn":688},{"n":"2.1.07-119","t":"Wie müssen Sie sich verhalten, wenn sich ein Zusammenstoß mit Wild nicht mehr vermeiden lässt?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich behalte die Fahrtrichtung bei","Ich weiche immer aus","Ich bremse so stark wie möglich"],"co":[0,2],"ex":["Damit vermeidest du, andere Verkehrsteilnehmer zu gefährden.","Du darfst nur ausweichen, wenn hierdurch kein anderer Verkehrsteilnehmer gefährdet wird.","So wird der Schaden so gering wie möglich gehalten."],"rn":689},{"n":"2.1.07-122","t":"Sie fahren auf einer bei Motorradfahrern beliebten kurvenreichen Strecke. Womit müssen Sie rechnen?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Motorradfahrer ragen, wegen ihrer starken Schräglage in Kurven, in meinen Fahrstreifen hinein","Motorradfahrer schneiden Kurven","Motorradfahrer überholen mich riskant"],"co":[0,1,2],"ex":["Wegen ihrer dynamischen Fahrweise können Motorradfahrer in Kurven in deine Fahrbahn hinein ragen. Rechne damit.","Berücksichtige die dynamische Fahrweise von Motorradfahrern und sei darauf gefasst, dass sie auf kurvenreichen Strecken Kurven schneiden.","Wegen der kurzen Sichtweiten ist es riskant, auf kurvenreichen Strecken zu überholen. Rechne damit, dass dich Motorradfahrer riskant überholen, indem sie schnell beschleunigen und einen größeren Kurvenradius nutzen."],"rn":690},{"n":"2.1.07-202","t":"Wie verhalten Sie sich?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf den linken Fahrstreifen wechseln","Geschwindigkeit verringern, bremsbereit sein","Weiterfahren, Lichtzeichen geben"],"co":[1],"ex":["Das ist nicht möglich, weil das Motorrad auf gleicher Höhe auf der linken Spur ist.","So kann der rote PKW ungefährdet einparken und du weiterfahren, sobald er kein Hindernis mehr für dich darstellt.","Der Fahrer wird hierauf nicht reagieren können, weil er mit Einparken beschäftigt ist. Reduziere die Geschwindigkeit und halte dich bremsbereit."],"v":["https://video4.kalaiwa.de/assets/2107202v1440.mp4"],"rn":691},{"n":"2.1.07-203","t":"Was müssen Sie über die Benutzung der Rückspiegel wissen?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Rückspiegel müssen auf den Fahrer eingestellt sein","Nach rechts hat der Innenspiegel keinen toten Winkel","Fahrzeuge und Fußgänger im toten Winkel kann ich nicht sehen"],"co":[0,2],"ex":["Nur so ist die bestmögliche Sicht auf den hinter dir befindlichen Verkehr gewährleistet.","Der Innenspiegel hat rechts und links einen toten Winkel.","Deswegen musst du ständig auch durch den Rückspiegel beobachten, was sich hinter dir abspielt, damit du im Bedarfsfall niemanden übersiehst."],"rn":692},{"n":"2.1.07-206","t":"Sie fahren auf einer Landstraße. Vor Ihnen hat sich eine langsam fahrende Fahrzeugschlange von ca. 15 Fahrzeugen gebildet. Wie verhalten Sie sich?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich bleibe zunächst hinter der Fahrzeugschlange","Ich fordere Vorausfahrende durch Lichthupe und Blinken zum Überholen auf","Ich überhole die Fahrzeugschlange schnellstmöglich"],"co":[0],"ex":["Bleibe hier und gewinne einen Überblick über die Verkehrssituation.","Dies ist nicht das richtige Verhalten. Du weißt nicht, weshalb sich die Fahrzeugschlange gebildet hat. Deshalb bleibe zunächst hinter der Fahrzeugschlange, bis du die Verkehrssituation einschätzen kannst.","Bleibe erst einmal hinten und beobachte die Verkehrssituation."],"rn":693},{"n":"2.1.07-207","t":"Sie halten mit Ihrem Fahrzeug an, um Mitfahrende rechts aussteigen zu lassen. Dort verläuft ein Radweg. Was sollten Sie tun?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich sollte mich vergewissern, dass keine Radfahrer kommen","Ich sollte nur den Verkehr im Innenspiegel beobachten","Ich sollte die Aussteigenden auf den Radweg hinweisen"],"co":[0,2],"ex":["Die Mitfahrenden sollten erst aussteigen, wenn ihr euch vergewissert habt, dass keine Radfahrer kommen, damit niemand gefährdet wird.","Das reicht nicht aus. Du musst den Verkehr im Innen- und Außenspiegel sowie durch jede Sichtmöglichkeit beobachten.","So gehst du auf Nummer Sicher, dass sie beim Aussteigen auf mögliche Radfahrer achten."],"rn":694},{"n":"2.1.07-208","t":"Sie erhöhen Ihre Geschwindigkeit von 50 km/h auf 100 km/h. Wie verändert sich der Reaktionsweg entsprechend der Faustformel?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Er vervierfacht sich von 25 m auf 100 m","Er verdoppelt sich von 15 m auf 30 m","Er halbiert sich von 50 m auf 25 m"],"co":[1],"ex":["Der Bremsweg wird viermal so lang, aber dein Reaktionsweg verdoppelt sich nur.","Verdoppelst du die Geschwindigkeit, dann verdoppelt sich dein Reaktionsweg.","Eine Erhöhung der Geschwindigkeit hat immer eine Erhöhung des Reaktionsweges zur Folge."],"rn":695},{"n":"2.1.07-009-M","t":"Warum müssen Sie jetzt bremsen?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- grünen Fahrzeugs","- gelben Pkws","- Motorrads"],"co":[0],"ex":["Vor dir biegt ein grünes Fahrzeug, das vom Traktor-Anhänger verdeckt wird, aus einer Seitenstraße auf deine Fahrbahn ein, obwohl du Vorfahrt hast.","Wegen dem Pkw musst du nicht abbremsen.","Das Motorrad befindet sich auf der Gegenfahrbahn. Ihr könnt beide ungehindert aneinander vorbei fahren."],"v":["https://video2.kalaiwa.de/assets/2107009mv1440.mp4"],"rn":696},{"n":"2.1.07-010-M","t":"Womit müssen Sie auf diesem Parkplatz rechnen?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Mit ausparkenden Fahrzeugen","Mit falsch parkenden Lkws","Mit Personen auf der Fahrbahn"],"co":[0,1,2],"ex":["Man muss generell auf Parkplätzen damit rechnen, dass jemand ausparken will.","Du musst damit rechnen, dass Lkws falsch parken, weil der Parkplatz sehr gut besucht ist.","Man muss generell auf Parkplätzen damit rechnen, dass jemand herumläuft."],"i":["https://video2.kalaiwa.de/assets/2107010m.webp"],"rn":697},{"n":"2.1.07-014-M","t":"Womit sollten Sie in dieser Situation rechnen?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Der Fahrer des roten Fahrzeugs übersieht mich","Der grüne Lkw wendet","Der Traktor befährt die Straße"],"co":[0],"ex":["Der rote Pkw will abbiegen und könnte es einfach tun, ohne mir die Vorfahrt zu gewähren. Er hat dich nicht gesehen oder schätzt deine Geschwindigkeit falsch ein.","Der grüne Lkw ist auf deine Gegenfahrbahn eingebogen und wird geradeaus weiterfahren.","Der Traktor ist keine Gefahr. Er steht. Es ist nicht mal ein Fahrer im Traktor."],"v":["https://video4.kalaiwa.de/assets/2107014mv1440.mp4"],"rn":698},{"n":"2.1.07-015-M","t":"Warum sollten Sie hier die Geschwindigkeit weiter verringern?","p":5,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Weil der rote Pkw auf meinen Fahrstreifen ausweichen könnte","Weil der blaue Pkw weiterfahren könnte","Weil weitere Personen die Fahrbahn betreten könnten"],"co":[0,2],"ex":["Eventuell wird der blaue Pkw durch den Busch verdeckt oder es wurde kein Warndreieck aufgestellt. Der rote Pkw könnte also zu spät erkennen, dass das Fahrzeug vor ihm stehen geblieben ist. Du solltest deshalb vorausschauend fahren und damit rechnen, dass der rote Pkw auf deinen Fahrstreifen ausweicht.","Es befindet sich eine Person aus dem blauen Pkw auf der Fahrbahn, deshalb ist es unwahrscheinlich, dass er weiterfährt. Selbst wenn, würde es dich nicht beeinträchtigen.","Es befindet sich bereits eine Person auf der Fahrbahn. Hier ist besondere Vorsicht geboten. Es ist ebenfalls möglich, dass noch weitere Personen aus dem Fahrzeug aussteigen und auf die Fahrbahn laufen."],"v":["https://video4.kalaiwa.de/assets/2107015mv1440.mp4"],"rn":699},{"n":"2.1.07-022-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- bremsbereit sein","- die Geschwindigkeit weiter verringern","- eine Gefahrbremsung durchführen"],"co":[0,1],"ex":["Für den Fall, dass die Rehe über die Fahrbahn rennen, solltest du bremsbereit sein.","Die Rehe auf der Fahrbahn sind unberechenbar. Du solltest deshalb deine Geschwindigkeit weiter reduzieren und aufmerksam verfolgen, was geschieht.","Hinter dir befindet sich ein Fahrzeug. Ist der Fahrer unaufmerksam, könnte er bei einer Gefahrenbremsung möglicherweise nicht schnell genug reagieren und es könnte zu einem Auffahrunfall kommen. Außerdem erfordern die Rehe auf der Straße jetzt keine Gefahrenbremsung. Im Gegenteil würde diese die Rehe eher erschrecken."],"v":["https://video2.kalaiwa.de/assets/2107022mv1440.mp4"],"rn":700},{"n":"2.1.07-023-M","t":"Warum sollten Sie jetzt die Geschwindigkeit verringern?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Wegen des roten Pkws","Wegen der Geschwindigkeitsbeschränkung","Wegen des Tieres"],"co":[2],"ex":["Der rote Pkw beeinträchtigt dich in deiner Fahrweise nicht.","Die zulässige Höchstgeschwindigkeit sind hier 60 km/h. Diese hältst du ein.","Das Tier rennt unmittelbar vor dir auf die Straße. Um einen Unfall zu vermeiden, musst du deine Geschwindigkeit reduzieren."],"v":["https://video4.kalaiwa.de/assets/2107023mv1440.mp4"],"rn":701},{"n":"2.1.07-025-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich fahre unverändert weiter","Ich verzichte auf meine Vorfahrt","Ich bremse stark ab"],"co":[1,2],"ex":["Wenn du unverändert weiterfährst, gefährdest du dich und andere Verkehrsteilnehmer.","Verzichte auf deine Vorfahrt, um eine Kollision mit dem blauen Pkw zu vermeiden. Die Pflicht zur Unfallvermeidung steht über dem Vorfahrtrecht.","Der blaue Pkw fährt mit unverminderter Geschwindigkeit auf die Kreuzung zu. Offensichtlich sieht dich der Fahrer nicht. Um eine Kollision zu vermeiden, musst du stark abbremsen."],"v":["https://video4.kalaiwa.de/assets/2107025mv1440.mp4"],"rn":702},{"n":"2.1.07-026-M","t":"Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich verringere meine Geschwindigkeit weiter","Ich ermögliche dem Traktor das Einscheren","Ich wechsle auf den linken Fahrstreifen"],"co":[0,1],"ex":["Ermögliche dem Traktor das Einscheren, indem du deine Geschwindigkeit weiter verringerst.","Der Traktor blinkt links und will auf die Fahrbahn wechseln. Ermögliche ihm das Einscheren.","Wenn du jetzt auf den linken Fahrstreifen wechselst, wirst du mit dem Gegenverkehr kollidieren."],"v":["https://video4.kalaiwa.de/assets/2107026mv1440.mp4"],"rn":703},{"n":"2.1.07-028-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich fahre mit erhöhter Aufmerksamkeit weiter","Ich vergrößere den Abstand zum vorausfahrenden Pkw","Ich überhole den vorausfahrenden Pkw mit großem Seitenabstand"],"co":[0,1],"ex":["Die abrupten Brems- und Lenkmanöver des vorausfahrenden Pkws sind gefährlich. Achte darauf, wie er weiterfährt und sei bereit zu bremsen.","Vergrößere deinen Abstand, um eine Gefährdung auszuschließen.","Überhole den gelben Pkw nicht. Wenn du ihn überholst, riskierst du offensichtlich eine Kollision."],"v":["https://video2.kalaiwa.de/assets/2107028mv1440.mp4"],"rn":704},{"n":"2.1.07-113-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":5,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich beschleunige","Ich fahre gleichmäßig weiter","Ich verzögere"],"co":[2],"ex":["So würdest du dich und den Transporter gefährden. Bremse ab und gib ihm somit die Möglichkeit, noch rechtzeitig einzuscheren, bevor die Fahrbahnverengung kommt.","Vermindere die Geschwindigkeit und erleichtere dem Transporter das Einscheren.","Verzögere und lass den Transporter vor der Fahrbahnverengung einscheren."],"v":["https://video2.kalaiwa.de/assets/2107113mv1440.mp4"],"rn":705},{"n":"2.1.07-114-M","t":"Womit sollten Sie in dieser Situation rechnen?","p":5,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["- Traktor wartet","- Motorradfahrer abbremst","- Traktor weiterfährt"],"co":[1,2],"ex":["Der Traktor müsste warten, jedoch sieht es im Moment eher danach aus, als würde er auf die Straße fahren.","Der Motorradfahrer bremst möglicherweise ab, weil unklar ist, ob der Traktor in die Straße einfährt oder wartet.","Wenn der Traktor in die Straße einfährt, dann müssen der Motorradfahrer und du abbremsen."],"v":["https://video2.kalaiwa.de/assets/2107114mv1440.mp4"],"rn":706},{"n":"2.1.07-117-M","t":"Worauf müssen Sie beim Einbiegen nach rechts achten?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Auf das Motorrad","Auf den Traktor","Auf von links kommende Fahrzeuge"],"co":[0,2],"ex":["Das Motorrad ist nämlich gerade dabei, den Traktor zu überholen. Du musst mit dem Abbiegen warten, bis es vorbeigefahren ist.","Auf den Traktor musst du nicht achten, da er von der Straße, auf die du einfahren möchtest, abbiegt.","Du musst hier dem Querverkehr die Vorfahrt gewähren und darfst erst dann einbiegen."],"v":["https://video4.kalaiwa.de/assets/2107117mv1440.mp4"],"rn":707},{"n":"2.1.07-121-M","t":"Wie müssen Sie sich in dieser Situation verhalten?","p":5,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich weiche nach links aus","Ich weiche nicht aus","Ich bremse sofort stark ab"],"co":[1,2],"ex":["Du solltest keinesfalls nach links ausweichen. Du würdest die entgegenkommenden Fahrzeuge behindern und den Gegenverkehr schlimmstenfalls in Gefahr bringen.","Durch Ausweichen nach links könntest du den Gegenverkehr behindern oder in Gefahr bringen. Durch Ausweichen nach rechts könntest du in den Straßengraben oder gegen einen Baum fahren. Hier ist es besser gerade auf das Hindernis zu lenken.","Wenn ein Gegenstand dieser Größe auf der Fahrbahn liegt und du nicht ausweichen kannst, ohne andere Verkehrsteilnehmer zu gefährden, muss eine Gefahrenbremsung durchgeführt werden."],"v":["https://video4.kalaiwa.de/assets/2107121mv1440.mp4"],"rn":708},{"n":"2.1.07-123-M","t":"Wie sollten Sie sich jetzt verhalten?","p":4,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich verringere meine Geschwindigkeit","Ich fahre zügig an dem roten Fahrzeug vorbei","Ich bleibe zunächst hinter dem roten Fahrzeug"],"co":[0,2],"ex":["Der Fahrer des roten Fahrzeugs schneidet die Kurve. Bremse ab und fahr erst an ihm vorbei, wenn du sicher bist, dass er nach der Kurve auf seiner Fahrspur bleibt.","Du riskierst einen Unfall, wenn du an dem roten Fahrzeug vorbeifährst. Der Fahrer schneidet die Kurve. Bleibe hinter ihm.","Solange das rote Fahrzeug die Mittellinie überfährt, musst du hinter ihm bleiben. Ansonsten würdest du euch beide gefährden."],"v":["https://video2.kalaiwa.de/assets/2107123mv1440.mp4"],"rn":709},{"n":"2.1.07-124-M","t":"Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.1.07","ch":"Besondere Verkehrssituationen","th":"Gefahrenlehre","o":["Ich fahre möglichst weit rechts","Ich verringere meine Geschwindigkeit","Ich signalisiere dem Motorradfahrer, dass er mich überholen kann"],"co":[0,1],"ex":["Du solltest so weit wie möglich rechts fahren, um eine Kollision mit dem entgegenkommenden Lkw zu vermeiden. Du kannst durch den Baum nicht sehen, wie weit mittig der entgegenkommende Lkw fährt. Zudem schaffst du mehr Platz auf der Fahrbahn, falls das Motorrad hinter dir noch zum Überholen ansetzt und den Lkw bisher nicht gesehen hat.","Du solltest deine Geschwindigkeit verringern, um mögliche Gefahrensituationen mit dem entgegenkommenden Lkw und dem Motorrad hinter dir zu vermeiden. Die Straße hat keine Fahrbahnmarkierungen, ist sehr eng und die Sicht auf den Lkw ist durch den Baum verdeckt.","Du darfst dem Motorradfahrer nicht signalisieren, dass er dich überholen kann, da auf der Gegenspur ein breiter Lkw entgegenkommt. So könnte es zu einer möglichen Kollision zwischen Lkw und Motorradfahrer kommen."],"v":["https://video2.kalaiwa.de/assets/2107124mv1440.mp4"],"rn":710},{"n":"2.1.08-010","t":"Womit müssen Sie bei Steigungen auf Autobahnen rechnen?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Mit plötzlichen Überholmanövern anderer Verkehrsteilnehmer","Mit großen Geschwindigkeitsunterschieden zwischen Fahrzeugen","Mit langsam fahrenden Lkws auf dem rechten Fahrstreifen"],"co":[0,1,2],"ex":["Bei Steigungen auf Autobahnen werden einige Fahrzeuge aufgrund ihrer Motorisierung und Beladung in der Regel langsamer - das kann wiederum andere Verkehrsteilnehmer zum Überholen motivieren.","Je nach Leistung können Fahrzeuge Steigungen unterschiedlich schnell hinauf fahren. Deshalb können große Geschwindigkeitsdifferenzen entstehen.","Aufgrund der großen Last, die sie transportieren, werden Lkws an Steigungen meist langsamer."],"rn":711},{"n":"2.1.08-011","t":"Wie müssen Sie sich verhalten?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Geschwindigkeit und Fahrstreifen beibehalten","Verzögern und Fahrstreifen beibehalten","Auf den linken Fahrstreifen wechseln"],"co":[1],"ex":["Du musst verzögern, weil ein Fahrzeug auf deine Spur ausschert und du den Sicherheitsabstand zu diesem beibehalten musst.","Vor dir schert ein LKW auf deine Fahrspur aus. Du kannst nicht ausweichen, weil sich auf der linken Spur ebenfalls ein Fahrzeug befindet. Verzögere daher und bleibe auf deinem Fahrstreifen.","Auf dem linken Fahrstreifen ist gerade ein Transporter dabei, dich zu überholen. Du kannst nicht auf den linken Fahrstreifen wechseln."],"v":["https://video2.kalaiwa.de/assets/2108011v1440.mp4"],"rn":712},{"n":"2.1.08-013","t":"Was müssen Sie beim Einfahren auf die Autobahn beachten?","p":5,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Auf dem Einfädelungsstreifen darf ich schneller fahren als auf der durchgehenden Fahrbahn","Der Verkehr auf der durchgehenden Fahrbahn hat Vorfahrt","Der Verkehr auf dem durchgehenden rechten Fahrstreifen muss das Einfahren ermöglichen"],"co":[0,1],"ex":["Damit du dich leichter in den Fließverkehr auf der Autobahn einordnen kannst, darfst du hier schneller Fahren als auf der durchgehenden Fahrbahn.","Du darfst dich nur einordnen, wenn du hierbei niemanden, der sich auf der durchgehenden Fahrbahn befindet, behinderst.","Du musst dem Verkehr auf dem durchgehenden Fahrstreifen die Vorfahrt lassen, bevor du dich selbst einordnen darfst."],"rn":713},{"n":"2.1.08-014","t":"Sie fahren mit Richtgeschwindigkeit auf der Autobahn und möchten diese an der nächsten Ausfahrt verlassen. Wie müssen Sie sich verhalten?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Ich beende Überholvorgänge rechtzeitig","Ich setze die Geschwindigkeit bereits auf dem rechten Fahrstreifen der Autobahn deutlich herab","Ich setze die Geschwindigkeit auf dem Ausfädelungsstreifen deutlich herab"],"co":[0,2],"ex":["Wäge hier ab, ob ein Überholen noch notwendig ist, wenn du bei der nächsten Ausfahrt bereits rausfährst.","Du verminderst die Geschwindigkeit erst, wenn du dich auf dem Ausfädelungsstreifen befindest.","Du setzt die Geschwindigkeit vor allem erst herab, wenn du dich auf dem Ausfädelungsstreifen befindest. So wird der übrige Verkehr nicht behindert."],"rn":714},{"n":"2.1.08-016","t":"Wie sollten Sie sich jetzt verhalten?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Ich schalte das Warnblinklicht ein","Ich fahre in die freie Gasse","Ich bremse mein Fahrzeug ab"],"co":[0,2],"ex":["Um den nachfolgenden Verkehr zu warnen, solltest du das Warnblinklicht einschalten.","Die Gasse dient den Rettungsfahrzeugen, um bei Stau schneller an eine Unfallstelle zu gelangen. Du darfst hier also nicht einfahren.","Zwar ist der Stau für dich noch nicht direkt zu erkennen, jedoch weisen die herausfahrenden Fahrzeuge durch eingeschaltetes Warnblinklicht darauf hin. Bremse also ab."],"v":["https://video4.kalaiwa.de/assets/2108016v1440.mp4"],"rn":715},{"n":"2.1.08-018","t":"Was ist in dieser Situation richtig?","p":5,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Der Lkw muss warten","Der Lkw hat Vorfahrt","Ich muss meine Geschwindigkeit verringern"],"co":[1,2],"ex":["Der LKW hat Vorfahrt, du musst warten.","Du musst hier dem LKW die Vorfahrt gewähren.","Auf deiner Spur steht ein \"Vorfahrt gewähren\"-Schild. Daher musst du die Geschwindigkeit verringern und dem Querverkehr den Vorrang lassen."],"i":["https://video4.kalaiwa.de/assets/2108018.webp"],"rn":716},{"n":"2.1.08-021","t":"Sie fahren mindestens 20 km/h schneller als der grüne Lkw. Wie sollten Sie sich verhalten?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Ich bremse ab und fahre hinter dem grünen Lkw auf die Autobahn","Ich fahre vor dem grünen Lkw auf die Autobahn","Ich halte am Ende des Einfädelungsstreifens an und fahre nach dem blauen Lkw auf die Autobahn"],"co":[1],"ex":["Beschleunige weiter und fahre vor dem grünen LKW auf die Autobahn, weil hier die Fahrbahn ausreichend frei ist, um sich einzuordnen.","Du befindest dich auf dem Einfädelungs- bzw. Beschleunigungsstreifen und seitlich neben dem grünen LKW. Beschleunige hier weiter und fahre vor dem grünen LKW auf die Autobahn. Zwischen ihm und dem nachfolgenden LKW ist wenig Platz, um sich einzuordnen und du fährst bereits mindestens 20 km/h schneller als dieser.","Ordne dich vor dem grünen LKW in den Fließverkehr ein."],"i":["https://video4.kalaiwa.de/assets/2108021.webp"],"rn":717},{"n":"2.1.08-025","t":"Sie möchten auf die Autobahn auffahren. Welcher Fahrlinie müssen Sie folgen?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","na":"Antwort: Fahrlinie Nr. 3","e":"Die dritte Fahrlinie zeigt den richtigen Weg an, den du fahren musst, um auf die Autobahn zu gelangen. Die anderen beiden Wege sind durch ein Verkehrszeichen, dass die Durchfahrt aus deiner Richtung untersagt, gekennzeichnet.","i":["https://video4.kalaiwa.de/assets/2108025.webp"],"rn":718},{"n":"2.1.08-031","t":"Warum sollten Sie auf Autobahnen die Richtgeschwindigkeit von 130 km/h einhalten?","p":3,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["- Unfälle vermieden werden können","- die Schwere möglicher Unfälle verringert werden kann","- ein gleichmäßiger Verkehrsfluss erreicht werden kann"],"co":[0,1,2],"ex":["Je höher die Geschwindigkeit ist, desto länger werden auch Reaktionsweg, Bremsweg usw. Durch langsameres Fahren können Unfälle vermieden werden. Ebenfalls strengt schnelles Fahren mehr an und ist deshalb gefährlicher.","Durch eine geringere Geschwindigkeit kann die Schwere möglicher Unfälle reduziert werden.","Fahren alle Fahrzeuge mit einer ähnlichen Geschwindigkeit, wird der Verkehrsfluss gleichmäßiger. Treten hohe Geschwindigkeitsunterschiede auf, muss viel abgebremst und wieder beschleunigt werden, dies führt zu einem ungleichmäßigen Verkehrsfluss."],"rn":719},{"n":"2.1.08-102","t":"Warum sollten Sie es vermeiden, im Baustellenbereich zu überholen?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Das Unfallrisiko erhöht sich deutlich","Fahrzeuge auf dem rechten Fahrstreifen können die gelbe Fahrbahnmarkierung überfahren","Die Zeitersparnis ist oft gering"],"co":[0,1,2],"ex":["Überholen im Baustellenbereich erhöht das Unfallrisiko erheblich, aufgrund der möglichen Verschmutzung und Enge der Fahrbahn, sowie der Ablenkungen am Fahrbahnrand.","Beim Überholen im Baustellenbereich besteht die Gefahr, dass das Fahrzeug, welches du überholen möchtest, die gelbe Fahrbahnmarkierung überfährt. Die Fahrbahnmarkierungen sind hier meistens enger und die Ablenkungen am Fahrbahnrand können zu Unaufmerksamkeit führen. Nicht zuletzt wegen möglicher Hindernisse auf der Fahrbahn solltest du es vermeiden, hier zu überholen.","Das Überholen im Baustellenbereich spart oft kaum Zeit, da die meisten Fahrzeuge im ohnehin meist kurzen Baustellenbereich mit der hier erlaubten Maximalgeschwindigkeit fahren."],"v":["https://video4.kalaiwa.de/assets/2108102v1440.mp4"],"rn":720},{"n":"2.1.08-103","t":"Wie können Sie die Gefahr verringern, eine Autobahn entgegen der vorgeschriebenen Fahrtrichtung zu befahren?","p":3,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Ich suche bei Autobahnauffahrten gezielt nach Verkehrszeichen für die richtige Fahrtrichtung","Ich achte bei geänderter Verkehrsführung genau auf die Beschilderung","Ich folge bei Baustellen ausschließlich den Angaben des Navigationssystems"],"co":[0,1],"ex":["Folge bei der Autobahnauffahrt gezielt den Schildern, die die richtige Fahrtrichtung angeben.","Bei geänderter Verkehrsführung solltest du aufmerksam der Beschilderung folgen.","Navigationssysteme können wissen zwar wissen, wo es Baustellen gibt, aber über die konkrete Streckenführung in einer Baustelle können Navigationssysteme keine sichere Aussage liefern. Zudem wird die Streckenführung in Baustellen auch häufig geändert. Ignoriere deshalb in Baustellen die Hinweise und Ansagen des Navis und halte dich ausschließlich an die aktuelle Beschilderung."],"rn":721},{"n":"2.1.08-005-B","t":"Womit müssen Sie hier rechnen?","p":3,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Mit dem Ende des rechten Fahrstreifens","Mit einem Fahrstreifenwechsel des Vorausfahrenden","Mit einer Verdichtung des Verkehrs hinter der Unterführung"],"co":[1,2],"ex":["Der linke Fahrstreifen endet.","Ein Schild weist darauf hin, dass in 200 m Entfernung die linke Spur mit der rechten zusammenläuft. Die linke Spur fällt also weg. Daher wird das vorausfahrende Fahrzeug auf deine Spur wechseln.","Weil hier die Fahrbahn einspurig wird, kann sich der Verkehr nach zusammenlaufen der Fahrspuren verdichten."],"i":["https://video4.kalaiwa.de/assets/2108005b.webp"],"rn":722},{"n":"2.1.08-008-B","t":"Hier bildet sich ein Stau. Wie verhalten Sie sich richtig?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Möglichst Warnblinklicht einschalten, um nachfolgende Fahrzeuge zu warnen","So weit links wie möglich fahren, um rechts Platz für eine Gasse zu machen","So weit rechts wie möglich fahren, um links Platz für eine Gasse zu machen"],"co":[0,2],"ex":["So kann der nachfolgende Verkehr frühzeitig darauf reagieren.","Die \"Rettungsgasse\" muss zwischen dem linken und dem mittleren Fahrstreifen gebildet werden.","Bei mehrspuriger Fahrbahn wird immer zwischen den beiden linken Fahrstreifen eine \"Rettungsgasse\" gebildet werden, damit Rettungsfahrzeuge möglichst schnell zum Unfallort gelangen können."],"i":["https://video4.kalaiwa.de/assets/2108008b.webp"],"rn":723},{"n":"2.1.08-024-M","t":"Wie sollten Sie sich jetzt verhalten?","p":3,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["- den Fahrstreifen, damit ich den gelben Pkw nicht behindere","- in den mittleren Fahrstreifen, da mein Überholvorgang abgeschlossen ist","- den Fahrstreifen nicht, da der rote Pkw bereits wechselt"],"co":[2],"ex":["Du kannst den Fahrstreifen nicht wechseln, weil sich auf der mittleren Spur ein Fahrzeug auf deiner Höhe befindet.","Du kannst aufgrund des roten PKWs nicht auf den mittleren Fahrstreifen wechseln.","Auch wenn das gelbe Fahrzeug schnell von hinten angefahren kommt, musst du auf der linken Spur bleiben, weil das rote Fahrzeug auf die mittlere Spur gewechselt hat und du deshalb nicht ausweichen kannst."],"v":["https://video2.kalaiwa.de/assets/2108024mv1440.mp4"],"rn":724},{"n":"2.1.08-026-M","t":"Worauf sollten Sie sich jetzt einstellen?","p":3,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Der gelbe Pkw verlässt die Autobahn","Der blaue Bus vor mir bremst wegen eines Staus","Das Motorrad verlässt die Autobahn"],"co":[0],"ex":["Der gelbe PKW hat abgebremst, den Rechtsblinker eingeschaltet und bewegt sich auf die rechte Spur zu. Verzögere also und lass ihn Einfahren.","Dafür gibt es keine Anzeichen.","Es gibt keine Hinweise darauf, dass das Motorrad die Autobahn verlässt."],"v":["https://video4.kalaiwa.de/assets/2108026mv1440.mp4"],"rn":725},{"n":"2.1.08-027-M","t":"Sie möchten die Autobahn verlassen. Wodurch ergibt sich hier eine gefährliche Situation?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Durch den gelben Lkw","Durch das Motorrad","Durch das grüne Fahrzeug"],"co":[1],"ex":["Der gelbe Lkw fährt hinter dir und stellt keine Gefahr dar.","Rechts neben dir fährt ein Motorrad. Deshalb kannst du jetzt nicht auf die Abbiegespur wechseln.","Das grüne Fahrzeug vor dir stellt keine Gefahr dar."],"v":["https://video2.kalaiwa.de/assets/2108027mv1440.mp4"],"rn":726},{"n":"2.1.08-028-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Ich bleibe auf dem linken Fahrstreifen","Ich fahre unverändert weiter","Ich verringere meine Geschwindigkeit"],"co":[0,2],"ex":["Auf dem rechten Fahrstreifen befindet sich ein Gegenstand. Du solltest deshalb auf dem linken Fahrstreifen bleiben.","Fährst du unverändert weiter, könnte es zu einem Zusammenstoß mit dem Lkw kommen.","Vor dem Lkw befindet sich ein Gegenstand auf der Fahrbahn. Er wird dem Gegenstand über den linken Fahrstreifen ausweichen. Deshalb solltest du deine Geschwindigkeit reduzieren."],"v":["https://video2.kalaiwa.de/assets/2108028mv1440.mp4"],"rn":727},{"n":"2.1.08-029-M","t":"Warum müssen Sie jetzt die Geschwindigkeit verringern?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Wegen des blauen Pkws","Wegen des Lkws","Wegen der Geschwindigkeitsbeschränkung"],"co":[1],"ex":["Der blaue Pkw stellt für dich keinen Grund dar deine Geschwindigkeit zu verringern.","Vor dem Lkw ist der rechte Fahrstreifen gesperrt. Er muss auf den linken Fahrstreifen wechseln. Um ihm dies zu ermöglichen, solltest du deine Geschwindigkeit reduzieren.","Die zulässige Höchstgeschwindigkeit beträgt hier 120 km/h. Diese hältst du ein."],"v":["https://video2.kalaiwa.de/assets/2108029mv1440.mp4"],"rn":728},{"n":"2.1.08-030-M","t":"Sie möchten die Autobahn verlassen. Wie verhalten Sie sich richtig?","p":3,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Ich verringere meine Geschwindigkeit erst beim Erreichen der Kurve","Ich verringere meine Geschwindigkeit ab jetzt","Ich prüfe meine Geschwindigkeit in kurzen Abständen anhand des Tachos"],"co":[1,2],"ex":["Würdest du erst bei der Kurve abbremsen, könntest du deine Geschwindigkeit nicht mehr rechtzeitig reduzieren. Generell solltest du immer vor einer Kurve und nicht erst in der Kurve abbremsen.","Sobald du den Ausfädelungsstreifen befahren hast, solltest du abbremsen. Bremst du bereits schon vor dem Einfädeln auf den Verzögerungsstreifen, würdest du den Verkehr auf der Autobahn unnötig beeinträchtigen.","Du solltest hier öfter den Tacho prüfen, um sicherzugehen, dass du nicht zu schnell in die Kurve fährst. Auf Autobahnen besteht die Gefahr, dass du dich zu sehr an die hohe Geschwindigkeit gewöhnst und deshalb zu schnell in eine Ausfahrt fährst."],"i":["https://video2.kalaiwa.de/assets/2108030m.webp"],"rn":729},{"n":"2.1.08-032-M","t":"Womit müssen Sie jetzt rechnen?","p":4,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Der Fahrer des gelben Lkws sieht das Stauende zu spät","Der blaue Pkw schert vor mir ein","Das Motorrad fährt zwischen den Fahrzeugreihen durch"],"co":[0,2],"ex":["Der Fahrer des gelben Lkws scheint das Stauende nicht zu sehen, da er mit unverminderter Geschwindigkeit weiterfährt. Bedenke aber, dass du wegen dem Motorrad links von dir jetzt noch nicht spontan auf den linken Fahrstreifen wechseln kannst, um eine Kollision zu vermeiden.","Der blaue Pkw bremst vor dem Stauende und will nicht vor dir einscheren.","Das Motorrad ist bereits links von dir und fährt zwischen den Fahrzeugreihen durch. Sei darauf gefasst."],"v":["https://video4.kalaiwa.de/assets/2108032mv1440.mp4"],"rn":730},{"n":"2.1.08-033-M","t":"Womit müssen Sie beim Befahren der Ausfahrt rechnen?","p":3,"c":"2.1.08","ch":"Autobahn","th":"Gefahrenlehre","o":["Mit Personen auf der Fahrbahn","Mit einem defekten Fahrzeug","Mit herabgefallener Ladung"],"co":[0,1,2],"ex":["Das Warndreieck weist darauf hin, dass Personen auf der Fahrbahn sein könnten.","Das Warndreieck könnte vor einem defekten Fahrzeug in der Ausfahrt warnen.","Das Warndreieck könnte auf herabgefallene Ladung auf der Fahrbahn hinweisen."],"i":["https://video4.kalaiwa.de/assets/2108033m.webp"],"rn":731},{"n":"2.1.10-002","t":"Was wirkt auf langen Fahrten der Ermüdung entgegen?","p":4,"c":"2.1.10","ch":"Ermuedung Ablenkung","th":"Gefahrenlehre","o":["Gymnastische Übungen während der Pausen","Kaffeetrinken statt Pausen","Rechtzeitige und ausreichende Pausen"],"co":[0,2],"ex":["Bewegung in den Pausen ist notwendig, um bei langen Fahrten der Ermüdung entgegenzuwirken. Das bringt den Kreislauf in Schwung und versorgt dein Gehirn mit ausreichend Sauerstoff, um wieder konzentriert weiterfahren zu können.","Kaffee enthält zwar Koffein und kann dich kurzzeitig wacher machen, jedoch kannst du langfristiger Ermüdung beim Autofahren nur durch ausgedehnte Pausen, frische Luft und Bewegung entgegenwirken.","Beim Autofahren ist ständige Konzentration erforderlich. Um diese bei einer langen Fahrt aufrechterhalten zu können, musst du zwischendurch ausgedehnte Pausen einlegen, in denen du dich an der frischen Luft bewegst."],"rn":732},{"n":"2.1.10-004","t":"Welche Gefahr besteht, wenn Sie durch die Nutzung elektronischer Geräte während der Fahrt abgelenkt werden?","p":3,"c":"2.1.10","ch":"Ermuedung Ablenkung","th":"Gefahrenlehre","o":["Mein Anhalteweg kann sich verkürzen","Ich kann Verkehrszeichen übersehen","Ich kann von meinem Fahrstreifen abkommen"],"co":[1,2],"ex":["Die Nutzung elektronischer Geräte wird den Anhalteweg verlängern.","Durch die Ablenkung, die elektronische Geräte während der Fahrt darstellen, werden Verkehrsschilder gegebenenfalls übersehen.","Wenn du elektronische Geräte während des Fahrens benutzt, konzentrierst du dich weniger auf den Straßenverlauf. Dadurch kann es passieren, dass du von der Fahrbahn abkommst."],"rn":733},{"n":"2.1.10-005","t":"Welche Ursache führt bei jungen Fahrern häufig zu sogenannten Disco-Unfällen?","p":4,"c":"2.1.10","ch":"Ermuedung Ablenkung","th":"Gefahrenlehre","o":["- übermüdet sind","- körperlich erschöpft sind","- fahruntauglich sind"],"co":[0,1,2],"ex":["Bei Übermüdung kann es neben einer eingeschränkten Reaktionsfähigkeit zum Sekundenschlaf kommen. Übermüdung ist demnach ein großer Risikofaktor für Autofahrten nach einer langen Disco-Nacht.","Körperliche Erschöpfung kann sich auf vielfältige Weise zeigen: geringere Aufmerksamkeit, eingeschränktes Sichtfeld oder lange Reaktionszeiten. Dadurch kann es leichter zu Unfällen kommen.","Fahruntauglichkeit entsteht neben fehlendem Schlaf bei Disco-Unfällen auch durch den Konsum legaler und illegaler Drogen."],"rn":734},{"n":"2.1.10-101","t":"Was kann die Aufmerksamkeit im Straßenverkehr beeinträchtigen?","p":4,"c":"2.1.10","ch":"Ermuedung Ablenkung","th":"Gefahrenlehre","o":["Starke Emotionen (z. B. Freude, Ärger, Ungeduld)","Lebhafte Unterhaltung","Spannende Sendungen im Autoradio"],"co":[0,1,2],"ex":["Emotionen können sich auf deinen Fahrstil auswirken. Bist du stark emotional aufgewühlt, dann solltest du eine Pause einlegen, um dann wieder konzentriert weiterfahren zu können.","Das lenkt von einer konzentrierten Fahrweise ab.","Hierdurch wird der Radiosendung Aufmerksamkeit geschenkt, die für ein konzentriertes Autofahren notwendig ist."],"rn":735},{"n":"2.1.10-102","t":"Was lenkt Sie während der Fahrt stark ab?","p":4,"c":"2.1.10","ch":"Ermuedung Ablenkung","th":"Gefahrenlehre","o":["Telefonieren","Quengelnde Kinder auf den Rücksitzen","Anzünden einer Zigarette"],"co":[0,1,2],"ex":["Hier konzentrierst du dich neben dem Fahren auf das Gespräch. Das lenkt ab.","Hierum sollte sich, falls vorhanden, der Beifahrer kümmern, damit der Fahrer sich auf das Verkehrsgeschehen konzentrieren kann.","Beim Anzünden einer Zigarette kannst du kurzzeitig nicht auf die Fahrbahn schauen. Dies lenkt dich von einer sicheren Fahrweise ab."],"rn":736},{"n":"2.1.11-008","t":"Nachdem Sie längere Zeit auf einer Landstraße einem sehr langsam fahrenden Pkw folgen mussten, können Sie endlich überholen. Wie verhalten Sie sich?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["- fahre ich betont langsam, um dem anderen Fahrer die Auswirkungen seines Verhaltens zu verdeutlichen","- schere ich mit ausreichendem Abstand ein, um den anderen Fahrer nicht zu behindern","- bremse ich kurz ab, um den anderen Fahrer auf sein langsames Fahren hinzuweisen"],"co":[1],"ex":["Du kennst die Gründe für das langsame Fahren nicht. Provoziere den Fahrer nicht, sondern überhole sicher und fahre vorausschauend weiter.","So sieht sicheres Überholen aus.","Du bist kein Verkehrserzieher. Provoziere den anderen nicht, sondern schere ein, wenn ausreichend Abstand gewährleistet ist."],"rn":737},{"n":"2.1.11-012","t":"Was müssen Sie beachten, wenn Sie nach einem langen Arbeitstag noch ein Fahrzeug führen?","p":3,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich werde schneller müde","Ich fahre weniger konzentriert","Ich mache weniger Fahrfehler"],"co":[0,1],"ex":["Lege deshalb eine Pause ein, sobald du merkst, dass du müde wirst und bewege dich an der frischen Luft.","Sei dir dessen bewusst, wenn du nach einem langen Arbeitstag noch fährst.","Du neigst zu mehr Fahrfehlern, wenn du nach einem langen Arbeitstag noch Auto fährst, weil du unkonzentrierter bist."],"rn":738},{"n":"2.1.11-013","t":"Woran erkennt man einen guten Fahrzeugführer?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["- geht nicht auf Provokationen im Straßenverkehr ein","- weist andere Verkehrsteilnehmer stets auf ihre Fahrfehler hin","- zeichnet sich durch eine ruhige und gelassene Fahrweise aus"],"co":[0,2],"ex":["Es gehört zu einem guten Fahrer, nicht nur sein Fahrzeug zu beherrschen, sondern auch seine Gefühle. Lass dich nicht von Affekten beeinflussen.","Achte selbst auf deine eigene Fahrweise und denke für andere mit. Du musst sie aber nicht auf Fehler hinweisen.","Eine ruhige und gelassene Fahrweise ist eine sichere Fahrweise."],"rn":739},{"n":"2.1.11-015","t":"Welche Ursache führt bei jungen Fahrern häufig zu sogenannten Disco-Unfällen?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Eine defensive Fahrweise","Eine hohe Risikobereitschaft","Eine mangelnde Verkehrswahrnehmung"],"co":[1,2],"ex":["Eine defensive Fahrweise ist ungefährlich und kann Unfälle vermeiden.","Bei jungen Fahrern kommt es meist durch mangelnde Fahrpraxis oder Imponiergehabe zu einer höheren Risikobereitschaft und somit einer riskanteren, gefährlichen Fahrweise.","Meist kommt es durch fehlende Erfahrung, Alkohol- oder Drogenkonsum, zu laute Musik oder Ablenkung durch Mitfahrer zu einer mangelnden Verkehrswahrnehmung und somit zu Unfällen."],"rn":740},{"n":"2.1.11-016","t":"Warum kann das Fahren unter Zeitdruck gefährlich sein?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["- Gefahren unterschätzt werden","- zu schnell gefahren wird","- defensiv gefahren wird"],"co":[0,1],"ex":["Wenn du es eilig hast, kann es passieren, dass du Gefahren unterschätzt, weil deine Risikobereitschaft unter Zeitdruck steigt. Du solltest dennoch vorsichtig und vorausschauend fahren, um dich und andere nicht zu gefährden.","Unter Zeitdruck fährt man häufig zu schnell. Du musst dich aber dennoch an die Geschwindigkeitsbegrenzungen halten.","Unter Zeitdruck fährt man meist offensiver."],"rn":741},{"n":"2.1.11-017","t":"Auf einer Straße außerorts fährt vor Ihnen ein Pkw deutlich langsamer, als es erlaubt ist und für ihn möglich wäre. Wie verhalten Sie sich richtig?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich passe meine Geschwindigkeit der des Pkws an","Ich betätige die Lichthupe, bis der Pkw schneller fährt","Ich überhole an geeigneter Stelle"],"co":[0,2],"ex":["Auch wenn es dir nicht gefällt, musst du deine Geschwindigkeit an die des Pkws anpassen und darfst ihm nicht zu nahe auffahren.","Das Betätigen der Lichthupe gilt in diesem Fall als Drängeln und ist nicht erlaubt.","Überhole erst an geeigneter Stelle und nicht davor. Gefährde weder dich noch andere."],"rn":742},{"n":"2.1.11-018","t":"Warum ist ein häufiger Wechsel des Fahrstreifens nicht sinnvoll?","p":3,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Weil der Zeitgewinn dadurch in der Regel sehr gering ist","Weil dadurch die Gefahr von Fahrfehlern zunehmen kann","Weil dadurch andere Verkehrsteilnehmer gefährdet werden können"],"co":[0,1,2],"ex":["Der Zeitgewinn durch häufiges Wechseln des Fahrstreifens ist sehr gering und deshalb unnötig.","Jeder Fahrstreifenwechsel erfordert gewisse Tätigkeiten: Verkehr beobachten, blinken, das Wechseln selbst. Hierbei können Fehler passieren. Je häufiger du den Fahrstreifen wechselst, umso anstrengender ist es und umso wahrscheinlicher sind Fehler.","Durch häufiges Wechseln des Fahrstreifens können schnell andere Verkehrsteilnehmer übersehen und somit gefährdet werden."],"rn":743},{"n":"2.1.11-019","t":"Sie sind durch eine Gefahrbremsung nur knapp einem Verkehrsunfall entgangen. Ihre Hände und Knie zittern. Wie verhalten Sie sich richtig?","p":3,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich denke später darüber nach, ob ich die Situation hätte vermeiden können","Ich fahre direkt weiter, um mich zu beruhigen","Ich lege schnellstmöglich eine Pause ein, um mich zu beruhigen"],"co":[0,2],"ex":["Indem du die Situation später im Kopf noch einmal durchgehst, wird dir möglicherweise klar, was dabei nicht optimal lief. So kannst du dein Fahrverhalten in Zukunft anpassen.","Möglicherweise bist du jetzt unaufmerksam. Fahre erst weiter, wenn du dich beruhigt hast, um Folgefehler zu vermeiden.","Halte bei der nächsten Möglichkeit an und lege eine Pause ein, bis du dich beruhigt hast. Vielleicht kannst du aussteigen, ein paar Meter gehen und tief durchatmen."],"rn":744},{"n":"2.1.11-020","t":"Während der Fahrt ärgern Sie sich sehr über das Verhalten eines anderen Verkehrsteilnehmers. Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich lege falls nötig eine Pause ein, um mich zu beruhigen","Ich konzentriere mich weiterhin auf den Verkehr","Ich fahre so weiter, dass mein Ärger sich nicht negativ auf die Verkehrssicherheit auswirkt"],"co":[0,1,2],"ex":["Wenn du beim Fahren emotional erregt bist, könntest du Gefährdungen übersehen. Lege, falls nötig, eine Pause ein und fahre erst weiter, wenn du dich beruhigt hast.","Es ist wichtig, dass du dich nicht vom Verkehr ablenken lässt, wenn dich das Verhalten anderer Fahrer ärgert.","Die Verkehrssicherheit steht an oberster Stelle. Konzentriere dich auf den Verkehr und fahre ruhig weiter."],"rn":745},{"n":"2.1.11-118","t":"Ein Pkw schert nach dem Überholen ohne ausreichenden Abstand vor Ihnen ein. Wie verhalten Sie sich?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich bleibe gelassen, um Konflikte zu vermeiden","Ich bremse ab, um den Sicherheitsabstand wiederherzustellen","Ich betätige die Lichthupe, um auf die Behinderung aufmerksam zu machen"],"co":[0,1],"ex":["Lass dich nicht provozieren und bremse ab, um wieder ausreichend Sicherheitsabstand herzustellen.","Das ist die korrekte Verhaltensweise.","Reagiere hier gelassen und lass den Drängler einscheren, ohne dass eine risikoreiche Verkehrssituation entsteht."],"rn":746},{"n":"2.1.11-119","t":"Das Risiko, beim Fahren eines Kraftfahrzeugs einen Unfall zu verursachen, ist zwischen dem 18. und 24. Lebensjahr deutlich erhöht. Welche Ursachen sind dafür häufig von Bedeutung?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Zu wenig Fahrerfahrung","Erhöhte Risikobereitschaft","Überschätzung der eigenen Fähigkeiten"],"co":[0,1,2],"ex":["Fahranfänger müssen das Fahrzeug, sowie den Umgang mit unterschiedlichen Verkehrssituationen erst noch beherrschen lernen. Das Bedarf jahrelanger Praxis.","Diese ist im Straßenverkehr nicht von Vorteil. Wichtiger ist es, vorsichtig und vorausschauend zu fahren, um risikoreiche Verkehrssituationen zu vermeiden.","Überschätzt man die eigenen Fähigkeiten, dann handelt man leichtsinniger und unterschätzt somit das Risiko, das bestimmte Verkehrssituationen mit sich bringen."],"rn":747},{"n":"2.1.11-120","t":"Während Sie in einem Verkehrsstau stehen, sehen Sie im Rückspiegel, wie sich ein Motorradfahrer an der wartenden Fahrzeugschlange „vorbeischlängelt“. Wie verhalten Sie sich?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich hupe und notiere sein Kennzeichen","Ich lasse ihn vorbeifahren","Ich sorge dafür, dass auch er anhalten muss"],"co":[1],"ex":["Zwar ist das \"vorbeischlängeln\" rein juristisch verboten, es ist jedoch nicht deine Aufgabe, hierauf zu reagieren.","Lass den Motorradfahrer sich weiter \"vorbeischlängeln\".","Lass ihn vorbeifahren."],"rn":748},{"n":"2.1.11-121","t":"Sie fahren auf einer Landstraße und werden von einem hinter Ihnen fahrenden Pkw bedrängt. Wie sollten Sie reagieren?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich erhöhe meine Geschwindigkeit, bis der nachfolgende Pkw aufhört, mich zu bedrängen","Ich vermindere meine Geschwindigkeit, bis der nachfolgende Pkw aufhört, mich zu bedrängen","Ich behalte meine Geschwindigkeit bei und halte mich rechts, um dem nachfolgenden Pkw das Überholen zu ermöglichen"],"co":[2],"ex":["Behalte deine Geschwindigkeit bei und gib ihm die Möglichkeit, dich zu überholen.","Versuche nicht, den Fahrer des nachfolgenden PKWs zu \"erziehen\". Fahre weiter mit gleichbleibender Geschwindigkeit und gib ihm die Möglichkeit, dich zu überholen.","Wenn der nachfolgende PKW es eilig hat, muss sich dies nicht auf dein Fahrverhalten auswirken. Daher gib ihm die Möglichkeit, zu überholen."],"rn":749},{"n":"2.1.11-123","t":"Fünf junge Freunde fahren im Auto zu einer Freizeitveranstaltung. Die Stimmung ist ausgelassen. Welche Gefahren können dadurch entstehen?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["- zu langsamerem Fahren verleitet","- zu riskantem Fahren verleitet","- vom Verkehrsgeschehen abgelenkt"],"co":[1,2],"ex":["Der Fahrer wird eher zu riskantem, schnellen Fahren verleitet.","Die Risikobereitschaft kann steigen, was zu riskanterem Fahrverhalten führt.","Dadurch, dass mehrere Personen im Fahrzeug sind und die Stimmung ausgelassen ist, kann es passieren, dass der Fahrer vom Verkehrsgeschehen abgelenkt wird."],"rn":750},{"n":"2.1.11-125","t":"Sie wollen überholen. Was steht dem entgegen?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Der Gegenverkehr","Der Fahrbahnzustand","Der Straßenverlauf"],"co":[0,2],"ex":["Auf der Gegenfahrbahn kommt ein PKW, der durch den LKW verdeckt ist.","Der Fahrbahnzustand würde nicht gegen ein Überholen sprechen.","Aufgrund der Kurve und der fehlenden Einsicht in den weiteren Fahrbahnverlauf eignet sich diese Stelle nicht zum Überholen."],"v":["https://video2.kalaiwa.de/assets/2111125v1440.mp4"],"rn":751},{"n":"2.1.11-126","t":"Vor Fahrtantritt haben Sie sich geärgert. Welche Folgen sollten Sie beim Fahren vermeiden?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Aggressivität","Ablenkung","Vorsicht"],"co":[0,1],"ex":["Du darfst den Ärger nicht \"mit ins Auto\" nehmen. Fahre erst los, wenn die Wut verflogen ist, damit sich dies nicht auf deinen Fahrstil auswirkt.","Fahre erst los, wenn der Ärger verflogen ist. Lenk dich während der Fahrt jedoch nicht ab, sonder konzentriere dich auf den Straßenverkehr.","Vorsichtiges Fahrverhalten ist im Straßenverkehr förderlich."],"rn":752},{"n":"2.1.11-127","t":"Was zeichnet einen verantwortungsvollen Fahrzeugführer aus?","p":3,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Er vermeidet es, bei Müdigkeit zu fahren","Er kann sich im Straßenverkehr durchsetzen","Er rechnet mit Fehlern von anderen Verkehrsteilnehmern"],"co":[0,2],"ex":["Bei Müdigkeit sind Konzentration und Reaktionsvermögen eingeschränkt. Daher sollte man bei Müdigkeit nicht fahren.","Einen verantwortungsvollen Fahrzeugführer zeichnet aus, der Verkehrssicherheit zuliebe auf sein Recht zu verzichtet, wenn so andere gefährdet würden.","Durch vorausschauendes Fahren kann rechtzeitig auf mögliche Fahrfehler von anderen reagiert werden."],"rn":753},{"n":"2.1.11-128","t":"Welche Gefühle können das Fahrverhalten beeinflussen?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ärger und Wut","Freude und Ausgelassenheit","Angst und Trauer"],"co":[0,1,2],"ex":["Dies kann sich in aggressivem Fahrverhalten niederschlagen. Daher sollte es vermieden werden, bei dieser Gefühlslage zu fahren.","Hierdurch kann es passieren, dass mögliche Gefahrensituationen unterschätzt werden.","Das lenkt von einer konzentrierten Fahrweise ab. Bei intensiven Gefühlen von Angst und Trauer sollte man kein Auto fahren."],"rn":754},{"n":"2.1.11-129","t":"Was sind Anzeichen dafür, dass Sie Ihre Fahrt unterbrechen sollten?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Schwierigkeiten beim Spurhalten","Drohendes Zufallen der Augen","Vermehrtes Gähnen"],"co":[0,1,2],"ex":["Hier fehlt es an Konzentration. Du solltest umgehend eine Pause einlegen.","Das weist bereits auf sehr starke Ermüdung hin. Halte umgehend bei der nächsten Parkmöglichkeit an und mache eine lange Pause. Du solltest eine Runde schlafen oder dir die Füße vertreten.","Das ist ein Anzeichen für Müdigkeit. Halte bei der nächsten Parkmöglichkeit an und mache einen Spaziergang an der frischen Luft."],"rn":755},{"n":"2.1.11-130","t":"Ihr Beifahrer möchte mit Ihnen während der Fahrt diskutieren. Wie sollten Sie sich verhalten?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["- meine Fahrtätigkeit","- die Diskussion"],"co":[0],"ex":["Bitte den Beifahrer, die Diskussion fortzuführen, wenn ihr die Fahrt beendet habt. Du musst dich auf den Straßenverkehr konzentrieren.","Das würde dich von einer konzentrierten Fahrweise ablenken."],"rn":756},{"n":"2.1.11-131","t":"Ihr Beifahrer weist Sie während der Fahrt darauf hin, dass Sie mehrfach zu dicht aufgefahren sind. Wie sollten Sie sich verhalten?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich nehme die Hinweise des Beifahrers ernst","Ich ignoriere die Hinweise des Beifahrers","Ich halte einen größeren Abstand ein"],"co":[0,2],"ex":["Prüfe ernsthaft, was dein Beifahrer sagt und sehe es nicht als persönliche Kritik.","Ignoriere deinen Beifahrer nicht. Wahrscheinlich hat er Angst.","Auch wenn du es anders siehst, dein Beifahrer scheint Angst zu haben. Gehe seiner Bitte daher nach und vergrößere den Abstand."],"rn":757},{"n":"2.1.11-132","t":"An einer roten Ampel innerorts möchte Sie ein anderer Fahrer offensichtlich zu einem Straßenrennen provozieren. Wie sollten Sie sich verhalten?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich nehme die Herausforderung an, ohne jedoch 50 km/h zu überschreiten","Ich schenke diesem Verhalten keine Beachtung","Ich steige aus und stelle den Fahrer zur Rede"],"co":[1],"ex":["Du konzentrierst dich auf dein sicheres Verhalten im Straßenverkehr und ignorierst den Provokateur.","Ignoriere den anderen und lass dich nicht provozieren.","Ignoriere den anderen Fahrer und setze deine Fahrt wie geplant fort."],"rn":758},{"n":"2.1.11-133","t":"Welche Ursache führt bei jungen Fahrern häufig zu sogenannten Disco-Unfällen?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Wenig Erfahrung mit voll besetzten Fahrzeugen","Eine Ablenkung durch Mitfahrer","Eine geringe Fahrerfahrung bei Dunkelheit"],"co":[0,1,2],"ex":["Meist sind junge Autofahrer nicht daran gewöhnt, ein voll besetztes Fahrzeug zu führen. Die hohe Anzahl an Mitfahrern kann die Konzentration und Aufmerksamkeit des Fahrers beeinträchtigen.","Feiernde, betrunkene oder laute Mitfahrer können schnell zu einer Ablenkung des Fahrers führen.","Jungen Fahren fehlt meist die nötige Fahrerfahrung, Situationen und Gefahren bei Dunkelheit richtig einzuschätzen."],"rn":759},{"n":"2.1.11-009-M","t":"Der Vorausfahrende hindert Sie seit Längerem am Überholen. Wie verhalten Sie sich richtig?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich hupe und blende mehrmals lange auf (Lichthupe)","Ich fahre dichter auf","Ich warte, bis ich überholen kann"],"co":[2],"ex":["So verunsicherst du den Fahrer vor dir nur. Halte ausreichend Sicherheitsabstand und warte, bis du überholen kannst.","Die Straße ist dicht befahren. Halte den Sicherheitsabstand ein und warte, bis der rote PKW sich rechts eingeordnet hat, um zu überholen.","Es ist sehr viel Verkehr, auch auf der rechten Spur. Warte daher, bis der rote PKW die Spur gewechselt hat, um den Überholvorgang fortzusetzen."],"i":["https://video4.kalaiwa.de/assets/2111009m.webp"],"rn":760},{"n":"2.1.11-014-M","t":"Der rote Pkw vor Ihnen fährt schon längere Zeit langsam. Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"2.1.11","ch":"Affektiv Emotionales Verhalten Im Strassenverkehr","th":"Gefahrenlehre","o":["Ich verringere den Abstand und hupe","Ich behalte meine Geschwindigkeit bei","Ich überhole, da die Straße frei ist"],"co":[1],"ex":["Drängeln, wie zu nahes Auffahren und hupen ist im Straßenverkehr verboten.","Um dem roten Pkw nicht zu nah aufzufahren und den benötigten Sicherheitsabstand trotzdem einzuhalten, behältst du deine Geschwindigkeit bei.","Die Straße ist zwar frei, allerdings siehst du nur bis zur nächsten Kurve. Die einsehbare Strecke ist für einen Überholvorgang zu kurz."],"v":["https://video4.kalaiwa.de/assets/2111014mv1440.mp4"],"rn":761},{"n":"2.2.02-006","t":"Sie fahren außerorts auf einer Straße mit drei markierten Fahrstreifen in jeder Fahrtrichtung. Auf dem rechten Fahrstreifen fahren in größeren Abständen einzelne, langsamere Fahrzeuge. Welchen Fahrstreifen dürfen Sie durchgängig befahren?","p":3,"c":"2.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["Den mittleren","Den linken"],"co":[0],"ex":["In diesem Fall darfst du den mittleren Fahrstreifen durchgängig befahren, weil du dauerhaft überholst.","Du darfst den linken Fahrstreifen nur zum Überholen von Fahrzeugen auf dem mittleren Fahrstreifen verwenden. Da auf dem mittleren Fahrstreifen niemand fährt, darfst du den linken Fahrstreifen auch nicht verwenden."],"rn":762},{"n":"2.2.02-101-M","t":"Wie verhalten Sie sich in dieser Einbahnstraße jetzt richtig?","p":3,"c":"2.2.02","ch":"Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["Ich fahre rückwärts","Ich wende und fahre zurück","Ich warte, bis die Arbeiten eine Weiterfahrt zulassen"],"co":[2],"ex":["Du darfst in einer Einbahnstraße nicht rückwärts fahren. Für einen möglichen Unfall trägst du die Verantwortung.","In einer Einbahnstraße darfst du nur in eine Fahrtrichtung fahren. Du darfst hier also nicht wenden.","Du fährst erst dann weiter, wenn die Arbeiten es zulassen."],"i":["https://video2.kalaiwa.de/assets/2202101m.webp"],"rn":763},{"n":"2.2.03-006","t":"Sie fahren 100 km/h, haben 1 Sekunde Reaktionszeit und führen eine normale Bremsung durch. Wie lang ist der Anhalteweg nach der Faustformel?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"130 m","e":"Anhalteweg = Reaktionsweg + Bremsweg Reaktionsweg = (Geschwindigkeit : 10) x 3 Bremsweg = (Geschwindigkeit : 10) x (Geschwindigkeit : 10) Daraus folgt: 30 m + 100 m = 130 m","rn":764},{"n":"2.2.03-007","t":"Sie fahren 100 km/h und führen eine normale Bremsung durch. Wie lang ist der Bremsweg nach der Faustformel?","p":2,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"100 m","e":"Bremsweg = (Geschwindigkeit : 10) x (Geschwindigkeit : 10)","rn":765},{"n":"2.2.03-008","t":"Sie fahren 100 km/h und haben 1 Sekunde Reaktionszeit. Wie lang ist der Reaktionsweg nach der Faustformel?","p":2,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"30 m","e":"Die Fausformel für den Reaktionsweg lautet: (Geschwindigkeit : 10) x 3 Also hier: 100 km/h : 10 x 3 = 30 m Reaktionsweg.","rn":766},{"n":"2.2.03-009","t":"Sie fahren 50 km/h, haben 1 Sekunde Reaktionszeit und führen eine normale Bremsung durch. Wie lang ist der Anhalteweg nach der Faustformel?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"40 m","e":"Anhalteweg = Reaktionsweg + Bremsweg Reaktionsweg = (Geschwindigkeit : 10) x 3 Bremsweg = (Geschwindigkeit : 10) x (Geschwindigkeit : 10)","rn":767},{"n":"2.2.03-010","t":"Sie fahren 50 km/h und führen eine normale Bremsung durch. Wie lang ist der Bremsweg nach der Faustformel?","p":2,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"25 m","e":"Bremsweg = (Geschwindigkeit : 10) x (Geschwindigkeit : 10)","rn":768},{"n":"2.2.03-011","t":"Sie fahren 50 km/h und haben 1 Sekunde Reaktionszeit. Wie lang ist der Reaktionsweg nach der Faustformel?","p":2,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"15 m","e":"Reaktionsweg = (Geschwindigkeit : 10) x 3","rn":769},{"n":"2.2.03-012","t":"Sie fahren auf einer sehr schmalen Straße und haben 50 m Sichtweite. Wie lang darf Ihr Anhalteweg höchstens sein?","p":4,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"25 m","e":"Man muss innerhalb der halben Sichtweite anhalten können, weil aufgrund der schmalen Straße auch der Gegenverkehr rechtzeitig anhalten muss. Somit darf hier der Anhalteweg maximal 25 m betragen.","rn":770},{"n":"2.2.03-015","t":"Wie lautet die Faustformel, um den Bremsweg einer Gefahrbremsung auf ebener, trockener und asphaltierter Fahrbahn auszurechnen?","p":4,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["Geschwindigkeit in km/h 10 x 3 : 2","Geschwindigkeit in km/h 10 x Geschwindigkeit in km/h 10 : 2","Geschwindigkeit in km/h 10 x 5 : 2"],"co":[1],"ex":["Das ist nicht die richtige Formel.","Das ist die richtige Formel für den Bremsweg bei Gefahrenbremsung. Der normale Bremsweg errechnet sich durch diese Formel, ohne dass am Ende durch zwei geteilt wird.","Das ist nicht die richtige Formel."],"rn":771},{"n":"2.2.03-016","t":"Sie fahren 40 km/h. Bei einer Gefahrbremsung beträgt der Bremsweg ca. 8 Meter. Wie lang ist der Bremsweg unter sonst gleichen Bedingungen bei 50 km/h?","p":4,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["9,5 m","11,0 m","12,5 m"],"co":[2],"ex":["Diese Antwort stimmt nicht. Der Bremsweg liegt hier bei 12,5 m.","Diese Antwort ist falsch.","Wendet man die Formel an, so ergibt sich: [(50:10) x (50:10)] : 2 = 12,5 m"],"rn":772},{"n":"2.2.03-018","t":"Wie schnell dürfen Sie mit einem Pkw und einem Anhänger außerhalb geschlossener Ortschaften höchstens fahren?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"80 km/h","e":"Die Maximalgeschwindigkeit, mit der mit Anhänger außerorts gefahren werden darf, ist 80 km/h.","rn":773},{"n":"2.2.03-024","t":"Sie fahren bei Dunkelheit auf einer gut ausgebauten Landstraße und nutzen das Abblendlicht. Innerhalb welcher Strecke müssen Sie anhalten können?","p":4,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["- Abblendlichts","- Standlichts","- Fernlichts"],"co":[0],"ex":["Du musst innerhalb der Reichweite des Abblendlichts anhalten können. Falls dir diese Reichweite nicht zum Anhalten reichen würde, riskierst du eine Kollision.","Das Standlicht ist so schwach, dass es keine für dich sichtbare Ausleuchtung hat.","Falls du die Reichweite des Fernlichts zum Anhalten brauchst, riskierst du eine Kollision, wenn du nur das Abblendlicht an hast."],"rn":774},{"n":"2.2.03-025","t":"Sie fahren bei Nebel auf der Autobahn. Ihre Sichtweite beträgt weniger als 50 m. Wie schnell dürfen Sie höchstens fahren?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"50 km/h","e":"Aufgrund der schlechten Witterungsverhältnisse darfst du maximal 50 km/h fahren. Dabei handelt es sich um die erlaubte Maximalgeschwindigkeit bei einer Sichtweite von unter 50 Metern.","rn":775},{"n":"2.2.03-101","t":"Wie schnell darf ein Kraftfahrzeug mit Schneeketten höchstens fahren?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"50 km/h","e":"Mit Schneeketten liegt die vorgeschriebene Maximalgeschwindigkeit bei 50km/h. Bei höheren Geschwindigkeiten wäre die Fahrstabilität des Fahrzeugs nicht mehr ausreichend gewährleistet und die Fahrbahn würde beschädigt werden.","rn":776},{"n":"2.2.03-104","t":"Wie schnell dürfen Sie mit einem Pkw außerhalb geschlossener Ortschaften auf Straßen mit einem Fahrstreifen für jede Richtung höchstens fahren?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"100 km/h","e":"In der StVO § 3 Abs. 3 Ziffer 2c heißt es: \"Die zulässige Höchstgeschwindigkeit beträgt auch unter günstigen Umständen (...) außerhalb geschlossener Ortschaften (...) für Personenkraftwagen sowie für sonstige Kraftfahrzeuge mit einem zulässigen Gesamtgewicht bis 3,5 t 100 km/h.(...)\"","rn":777},{"n":"2.2.03-109","t":"Sie fahren eine Fahrzeugkombination. Diese besteht aus einem Kraftfahrzeug bis 3,5 t zulässiger Gesamtmasse und einem Anhänger ohne 100-km/h-Zulassung. Wie schnell dürfen Sie auf Autobahnen höchstens fahren?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"80 km/h","e":"Die Höchstgeschwindigkeit für Fahrzeugkombinationen bis 3,5 t zulässiger Gesamtmasse mit Anhänger beträgt außerhalb geschlossener Ortschaften 80 km/h.","rn":778},{"n":"2.2.03-305","t":"Auf welchen Straßen gilt die Richtgeschwindigkeit von 130 km/h?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","o":["Auf Autobahnen","Auf Kraftfahrstraßen außerhalb geschlossener Ortschaften mit baulich getrennten Fahrbahnen für jede Richtung","Auf Kraftfahrstraßen außerhalb geschlossener Ortschaften mit mindestens zwei markierten Fahrstreifen für jede Richtung"],"co":[0,1,2],"ex":["Hier darfst du 130 km/h fahren.","Hier kannst du dich an die Richtgeschwindigkeit von 130 km/h halten.","In diesem Fall ist 130 km/h die Richtgeschwindigkeit."],"rn":779},{"n":"2.2.03-026-M","t":"Wie schnell dürfen Sie nach dem Abbiegen höchstens fahren?","p":3,"c":"2.2.03","ch":"Geschwindigkeit","th":"Verhalten Im Strassenverkehr","na":"50 km/h","e":"Falls nicht anders angezeigt, gilt innerorts die maximale Höchstgeschwindigkeit von 50 km/h. Die 30km/h der vorherigen Vorfahrtsstraße gelten hier nicht mehr.","v":["https://video2.kalaiwa.de/assets/2203026mv1440.mp4"],"rn":780},{"n":"2.2.04-001","t":"Sie fahren mit 80 km/h hinter einem Auto her. Welchen Sicherheitsabstand müssen Sie mindestens einhalten?","p":4,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["Einen „Ein-Sekunden-Abstand“","Einen Abstand von 15 Metern","Einen „Zwei-Sekunden-Abstand“"],"co":[2],"ex":["Das reicht nicht aus. Ein \"Zwei-Sekunden-Abstand\" muss eingehalten werden.","Der Sicherheitsabstand ist abhängig von der Fahrgeschwindigkeit.","Diese Regel gilt für normale Wetter- und Sichtverhältnisse. Bei widrigen Witterungsbedingungen muss der Sicherheitsabstand entsprechend erhöht werden."],"rn":781},{"n":"2.2.04-002","t":"Sie fahren im Stadtverkehr auf trockener Fahrbahn in einer Kolonne, die sich mit einer Geschwindigkeit von 50 km/h bewegt. Welchen Sicherheitsabstand zum vorausfahrenden Fahrzeug müssen Sie mindestens einhalten?","p":4,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["5 m entsprechend etwa 1 Pkw-Länge","15 m entsprechend etwa 3 Pkw-Längen","10 m entsprechend etwa 2 Pkw-Längen"],"co":[1],"ex":["Dieser Sicherheitsabstand reicht nicht aus.","Du musst so viel Sicherheitsabstand halten, dass du innerhalb dieses Rahmens bei Bremsbedarf rechtzeitig reagieren kannst. Hier gilt die Faustformel für den Reaktionsweg: (Geschwindigkeit : 10) x 3.","10 m sind bei einer Geschwindigkeit von 50 km/h kein ausreichender Sicherheitsabstand."],"rn":782},{"n":"2.2.04-004","t":"Welchen Sicherheitsabstand sollten Sie bei einer Geschwindigkeit von 100 km/h zum vorausfahrenden Fahrzeug mindestens einhalten?","p":3,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","na":"50 m","e":"Um rechtzeitig Bremsen zu können, solltest du die halbe Geschwindigkeit in Metern Abstand einhalten.","rn":783},{"n":"2.2.04-005","t":"Welchen Sicherheitsabstand sollten Sie außerorts zum vorausfahrenden Fahrzeug mindestens einhalten?","p":4,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["Die Hälfte der Tachoanzeige in Metern","Ein Fünftel der Tachoanzeige in Metern","Ein Drittel der Tachoanzeige in Metern"],"co":[0],"ex":["Außerorts solltest du mindestens die Hälfte deiner Tachoanzeige in Metern Abstand zum vorausfahrenden Fahrzeug halten.","Ein Abstand zum vorausfahrenden Fahrzeug von einem Fünftel der Tachoanzeige in Metern ist zu wenig und kann gefährlich werden.","Ein Drittel der Tachoanzeige in Metern Abstand zu halten, genügt außerorts nicht."],"rn":784},{"n":"2.2.04-102","t":"Wann muss ein Pkw mit Anhänger außerorts auf Straßen mit nur einem Fahrstreifen für jede Richtung vom Vorausfahrenden einen so großen Abstand halten, dass ein Überholer einscheren kann?","p":3,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","na":"Antwort: Bei einer Zuglänge über 7 m","e":"Laut StVO § 4 Abs. 2 gilt: \"Kraftfahrzeuge, für die eine besondere Geschwindigkeitsbeschränkung gilt, sowie für Züge, die länger als 7 m sind, müssen außerhalb geschlossener Ortschaften ständig so großen Abstand zu vorausfahrenden Fahrzeugen halten, das ein überholendes Fahrzeug einscheren kann. (...)\"","rn":785},{"n":"2.2.04-106","t":"Sie fahren einen schwer beladenen Pkw. Warum sollten Sie einen größeren Sicherheitsabstand zu vorausfahrenden Fahrzeugen einhalten?","p":3,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["- der Bremsweg verlängern kann","- das Fahrverhalten des Pkws verändern kann","- meine Reaktionszeit verlängern kann"],"co":[0,1],"ex":["Je schwerer dein Pkw beladen ist, desto länger kann sein Bremsweg sein, da mehr Gewicht zum Stehen gebracht werden muss. Deswegen solltest du einen größeren Sicherheitsabstand zu vorausfahrenden Fahrzeugen einhalten.","Durch das zusätzliche Gewicht kann sich der Schwerpunkt deines Pkws verlagern. Das kann dazu führen, dass sich sein Fahrverhalten in bestimmten Situationen verändert und er ins Schlingern oder Pendeln gerät.","Die Beladung deines Pkws steht in keinem Zusammenhang mit deiner Reaktionszeit. Diese wird dadurch nicht verlängert."],"rn":786},{"n":"2.2.04-107","t":"Ab welcher Länge einer Fahrzeugkombination müssen Sie außerorts einen so großen Abstand zum vorausfahrenden Fahrzeug halten, dass ein überholendes Kraftfahrzeug einscheren kann?","p":3,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","na":"Antwort: Ab einer Länge von mehr als 7 m","e":"Du musst außerorts einen Einkehrabstand zum vorausfahrenden Fahrzeug einhalten, wenn die Länge der Fahrzeugkombination mehr als 7 Meter beträgt. So gibst du überholenden Fahrzeugen die Möglichkeit, vor dir einzuscheren. Das ist wichtig, um diese nicht zu gefährden.","rn":787},{"n":"2.2.04-105-M","t":"Sie fahren einen Pkw mit Wohnanhänger. Was gilt hier für den Abstand zum vorausfahrenden Fahrzeug?","p":4,"c":"2.2.04","ch":"Abstand","th":"Verhalten Im Strassenverkehr","o":["- ist zu groß, weil er die Länge meiner Fahrzeugkombination um ein Vielfaches überschreitet","- zum überholenden Pkw muss nach dessen Einscheren wiederhergestellt werden","- ist angemessen, weil der überholende Pkw vor mir einscheren kann"],"co":[1,2],"ex":["Dein Abstand zum vorausfahrenden Fahrzeug ist nicht zu groß, sondern angemessen, damit das überholende Auto genug Platz zum Einscheren hat.","Sobald der überholende Pkw vor dir eingeschert ist, musst du einen ausreichenden Abstand zu diesem herstellen. Das ist wichtig, damit dich auch weitere Fahrzeuge überholen und wieder vor dir einscheren können.","Durch deinen Wohnanhänger bist du langsamer und länger als andere Verkehrsteilnehmer. Du musst also einen ausreichenden Abstand zum vorausfahrenden Fahrzeug halten, damit ein überholendes Fahrzeug problemlos vor dir einscheren kann."],"i":["https://video2.kalaiwa.de/assets/2204105m.webp"],"rn":788},{"n":"2.2.05-005","t":"Sie fahren mit 100 km/h auf einer Straße außerhalb geschlossener Ortschaften. Vor Ihnen fährt ein Lkw mit 70 km/h. Wie weit müssen Sie bei Beginn eines Überholvorgangs von einer Straßenkuppe mindestens noch entfernt sein?","p":5,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["200 m","800 m","400 m"],"co":[1],"ex":["200 m reichen nicht zum Überholen aus. Du musst die Geschwindigkeit des LKWs und des möglichen Gegenverkehrs mit einkalkulieren.","Du musst mindestens 800 m entfernt sein, weil du hier deine Geschwindigkeit, die Geschwindigkeit des LKWs und von möglichem Gegenverkehr einplanen musst, wenn du den LKW noch vor der Straßenkuppe sicher überholen willst.","Weil du zusätzlich zu deiner Geschwindigkeit und der des LKWs das Tempo von möglichem Gegenverkehr mit einplanen musst, brauchst du mindestens 800 m Distanz, um den LKW sicher noch vor der Straßenkuppe überholen zu können."],"rn":789},{"n":"2.2.05-011","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":5,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Ich beschleunige und setze den Überholvorgang fort","Ich breche den Überholvorgang ab und ordne mich rechts ein","Ich setze den Überholvorgang mit gleichbleibender Geschwindigkeit fort"],"co":[1],"ex":["Wenn du weiter beschleunigst, überschreitest du die zulässige Höchstgeschwindigkeit. Breche den Überholvorgang ab und ordne dich rechts ein.","Das Fahrzeug, das du überholen wolltest, beschleunigt. Folglich kannst du nicht mehr überholen, ohne die zulässige Höchstgeschwindigkeit zu überschreiten. Breche den Überholvorgang ab und ordne dich rechts ein.","Weil der zu Überholende beschleunigt, macht dies keinen Sinn. Breche den Überholvorgang ab und ordne dich rechts ein."],"v":["https://video2.kalaiwa.de/assets/2205011v1440.mp4"],"rn":790},{"n":"2.2.05-012","t":"Worauf müssen Sie sich jetzt einstellen?","p":5,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- Überholvorgang des grünen Lkws länger dauert","- weiße Lkw beschleunigt","- blaue Pkw zum Überholen ansetzt"],"co":[0,2],"ex":["Der LKW darf nicht so schnell fahren wie ein PKW, weshalb der Überholvorgang länger dauert.","Da der weiße LKW soeben überholt wird, ist es unwahrscheinlich, dass er beschleunigt.","Es ist wahrscheinlich, dass der blaue PKW, um ebenfalls den weißen LKW zu überholen, auf deine Spur wechselt."],"v":["https://video2.kalaiwa.de/assets/2205012v1440.mp4"],"rn":791},{"n":"2.2.05-013","t":"Auf wen müssen Sie in dieser Situation besonders achten?","p":5,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- weißen Lkw","- Radfahrer","- roten Pkw"],"co":[1],"ex":["Der weiße LKW ist weit entfernt und somit musst du ihn nicht besonders beachten.","Der Radweg kreuzt kurz nach dem haltenden LKW die Fahrbahn. Der Radfahrer muss diese überqueren. Beachte dies, wenn du den haltenden LKW überholst, um den Radfahrer nicht zu gefährden.","Der rote PKW benötigt hier keine besondere Beachtung."],"v":["https://video4.kalaiwa.de/assets/2205013v1440.mp4"],"rn":792},{"n":"2.2.05-017","t":"Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- rechts","- nicht","- links"],"co":[1],"ex":["Rechts ist nicht ausreichend Platz, um die Straßenbahn zu überholen.","Du hast keine Möglichkeit, die Straßenbahn zu überholen.","Du siehst links zum einen nicht ausreichend in die Kurve und die Überholstrecke ein, zudem ist Gegenverkehr auf der anderen Fahrbahn."],"v":["https://video4.kalaiwa.de/assets/2205017v1440.mp4"],"rn":793},{"n":"2.2.05-018","t":"Sie möchten einen Lkw mit Anhänger überholen. Was müssen Sie dabei beachten?","p":4,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Der Fahrzeugumriss des Lastzugs kann vorausfahrende Fahrzeuge verdecken","Das Ausscheren zum Überholen darf erst unmittelbar hinter dem Lastzug erfolgen","Der erforderliche Überholweg verlängert sich wegen des Anhängers deutlich"],"co":[0,2],"ex":["Die Größe des Lkws samt Anhänger schränkt die Sicht auf vorausfahrende Fahrzeuge erheblich ein.","Unmittelbar hinter dem Lastzug ist die Sicht eingeschränkt. Besser in geeignetem Abstand zum Lkw ausscheren, um den Gegenverkehr gut einsehen zu können.","Lkws mit Anhänger dürfen eine Länge von maximal 18,75 Metern haben. Dadurch ergibt sich ein sehr langer Überholweg."],"rn":794},{"n":"2.2.05-019","t":"Warum dürfen Sie den vor Ihnen fahrenden Bus jetzt nicht überholen?","p":5,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Wegen der fehlenden Fahrbahnmarkierungen","Wegen des eingeschalteten Warnblinklichts am Bus","Wegen des Motorrads"],"co":[1,2],"ex":["Eine fehlende Fahrbahnmarkierung ist nicht unüblich und stellt für dich keinen Grund dar, nicht zu überholen.","Du darfst den Bus nicht überholen, da er das Warnblinklicht eingeschaltet hat und sich vermutlich einer Haltestelle nähert.","Das überholende Motorrad befindet sich gerade in deinem toten Winkel. Wenn du jetzt zum Überholen nach links ausscherst, würdest du mit dem Motorrad kollidieren."],"v":["https://video2.kalaiwa.de/assets/2205019v1440.mp4"],"rn":795},{"n":"2.2.05-014-M","t":"Warum müssen Sie jetzt verzögern?","p":4,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- Geländewagens","- Traktors","- Motorrads"],"co":[2],"ex":["Der Geländewagen hält seine Spur und ist kein Grund für dich, zu verzögern.","Der Traktor ist außerhalb der Fahrbahn und stellt für dich kein Risiko dar.","Das Motorrad überholt die Fahrkolonne im Gegenverkehr. Es befindet sich hierfür auf deiner Spur. Da unklar ist, wann es einschert und ob ausreichend Platz hierfür gegeben ist, solltest du verzögern."],"v":["https://video2.kalaiwa.de/assets/2205014mv1440.mp4"],"rn":796},{"n":"2.2.05-016-M","t":"Sie möchten überholen. Wie sollten Sie sich jetzt verhalten?","p":3,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Ich überhole noch nicht, da der blaue Pkw überholen könnte","Ich überhole alle Fahrzeuge in einem Überholvorgang","Ich folge dem blauen Pkw unmittelbar, falls dieser überholt"],"co":[0],"ex":["Es sieht so aus, als würde der blaue PKW zum Überholen ansetzen. Warte also noch, bis er dies getan hat, bevor du selbst überholst.","Warte mit dem Überholen, bis du das Fahrverhalten des blauen PKWs besser einschätzen kannst.","Warte mit dem Überholen, bis der blaue PKW dies abgeschlossen hat und du wieder volle Einsicht auf die Gegenfahrbahn hast."],"v":["https://video2.kalaiwa.de/assets/2205016mv1440.mp4"],"rn":797},{"n":"2.2.05-020-M","t":"Sie möchten das vor Ihnen fahrende Fahrzeug überholen. Was ist hierfür erforderlich?","p":3,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["- den rückwärtigen und seitlichen Verkehr beobachten","- meine Überholabsicht durch Blinken anzeigen","- meine Geschwindigkeit wesentlich erhöhen"],"co":[0,1,2],"ex":["Behalte beim Überholen den Verkehr hinter dir und seitlich von dir im Blick. Erst wenn die linke Fahrbahn frei ist, darfst du zum Überholvorgang ansetzen.","Bevor du beim Überholen die Fahrbahn wechselst, musst du anderen Verkehrsteilnehmern deine Überholabsicht durch Blinken anzeigen.","Um den Überholvorgang zügig abzuschließen, musst du deine Geschwindigkeit wesentlich erhöhen und schneller werden, als der Lkw."],"v":["https://video4.kalaiwa.de/assets/2205020mv1440.mp4"],"rn":798},{"n":"2.2.05-021-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Ich bleibe hinter dem Traktor","Ich rechne mit einem Abbiegen des Traktors","Ich folge der durch Blinken gegebenen Überholaufforderung des Traktorfahrers"],"co":[0,1],"ex":["Der Traktor scheint auf den Feldweg auf der rechten Seite abbiegen zu wollen. Bleibe hinter dem Traktor und warte, bis er abgebogen ist. Ihn zu überholen ist gefährlich, weil das am Heck installierte Arbeitsgerät ausscheren könnte.","Der Traktor blinkt und auf der rechten Seite biegt ein Feldweg von der Straße ab. Rechne damit, dass der Traktor abbiegt.","Das Blinken eines Traktors solltest du nie als Überholaufforderung werten. Stelle dich darauf ein, dass der Traktor abbiegt."],"v":["https://video4.kalaiwa.de/assets/2205021mv1440.mp4"],"rn":799},{"n":"2.2.05-103-M","t":"Wodurch kann diese Situation gefährlich werden?","p":4,"c":"2.2.05","ch":"Ueberholen","th":"Verhalten Im Strassenverkehr","o":["Durch den Traktor","Durch Gegenverkehr","Durch den roten Pkw"],"co":[1,2],"ex":["Der Traktor ist nicht auf der Fahrbahn und somit auch kein Risikofaktor.","Aufgrund der Straßenkuppe sieht man den Gegenverkehr nicht kommen. Wenn jemand entgegenkommt, muss der rote PKW sehr plötzlich einscheren. Daher ist es sinnvoll, hier zu verzögern, damit der Überholvorgang schnell beendet werden kann, um die Situation zu entschärfen.","Der rote PKW überholt hier, obwohl keine ausreichende Einsicht auf die Gegenfahrbahn gegeben ist. Das kann sehr gefährlich werden, wenn Gegenverkehr auftaucht und er einscheren muss."],"v":["https://video4.kalaiwa.de/assets/2205103mv1440.mp4"],"rn":800},{"n":"2.2.06-101-M","t":"Wie verhalten Sie sich hier richtig?","p":5,"c":"2.2.06","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich reihe mich rechts hinter den bereits wartenden Fahrzeugen ein","Ich fahre mit verringerter Geschwindigkeit weiter","Ich bremse ab und warte"],"co":[2],"ex":["Die Autos rechts am Straßenrand warten nicht, sondern parken in gekennzeichneten Parkflächen. Du musst dich nicht dahinter einreihen, sondern kannst direkt weiter fahren, sobald der Radfahrer weggefahren ist. Der Radfahrer hat genug Platz, um an dir vorbeizufahren.","Es reicht nicht aus, deine Geschwindigkeit zu verringern und weiterzufahren. Dafür ist der Platz zwischen Radfahrer und parkenden Autos nicht groß genug. Du musst also bremsen und den Radfahrer zuerst vorbeifahren lassen.","Die parkenden Autos auf deiner Fahrbahnseite verengen die Straße. Du musst in dieser Situation bremsen und warten, bis der Radfahrer vorübergefahren ist. Dann kannst du links an den parkenden Autos vorbei weiterfahren. Fährst du bereits jetzt an den parkenden Autos vorbei, dann würdest du den Radfahrer bedrängen und gefährden."],"v":["https://video2.kalaiwa.de/assets/2206101mv1440.mp4"],"rn":801},{"n":"2.2.07-002","t":"Für welche Kraftfahrzeuge gilt innerorts die freie Fahrstreifenwahl?","p":3,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","na":"Antwort: Für alle Kraftfahrzeuge bis 3,5 t zulässiger Gesamtmasse","e":"Bei der freien Fahrstreifenwahl darf man innerorts bei mehreren markierten Fahrstreifen für eine Richtung frei einen Fahrstreifen wählen. Es wäre also möglich, auf einer ansonsten leeren Fahrbahn auch den äußersten linken Fahrstreifen zu benutzen. Jedoch gilt diese Ausnahme vom Rechtsfahrgebot nur für Fahrzeuge mit einer zulässigen Gesamtmasse bis 3,5 t.","rn":802},{"n":"2.2.07-004","t":"Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich bleibe auf dem mittleren Fahrstreifen","Ich wechsle auf den linken Fahrstreifen","Ich wechsle auf den rechten Fahrstreifen"],"co":[2],"ex":["Du musst nach rechts wechseln, weil kein langsameres Fahrzeug vor dir auf der rechten Spur ist.","Du hast keinen Grund, auf den linken Fahrstreifen zu wechseln, weil der blaue Pkw deutlich schneller ist als du.","Das Rechtsfahrgebot gilt auch auf dreispurigen Autobahnen. Weil kein langsameres Fahrzeug vor dir fährt, das du überholen kannst, solltest du jetzt auf den rechten Fahrstreifen wechseln."],"v":["https://video4.kalaiwa.de/assets/2207004v1440.mp4"],"rn":803},{"n":"2.2.07-005","t":"Wodurch könnte eine gefährliche Situation entstehen?","p":5,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["- vorausfahrenden Pkws","- gelben Lkws","- grünen Lkws"],"co":[1],"ex":["Der PKW fährt in großem Abstand vor dir und stellt somit kein konkretes Risiko in dieser Situation dar. Würde er den Fahrstreifen wechseln, dann wäre hier immernoch ausreichend Sicherheitsabstand vorhanden.","Falls du dich in seinem toten Winkel befindest und der gelbe LKW plötzlich ausschert, müsstest du stark abbremsen. Auf die linke Spur auszuweichen ist hier keine Option, da von hinten ein Fahrzeug herangefahren kommt.","Den grünen LKW hast du bereits überholt. Er stellt somit auch keinen Risikogrund für dich dar."],"v":["https://video4.kalaiwa.de/assets/2207005v1440.mp4"],"rn":804},{"n":"2.2.07-007","t":"Wie sollten Sie sich verhalten?","p":2,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich bleibe auf dem mittleren Fahrstreifen und verzögere","Ich wechsle auf den rechten Fahrstreifen und verzögere","Ich wechsle auf den linken Fahrstreifen und überhole den roten Pkw vor mir"],"co":[0],"ex":["So verhältst du dich korrekt in dieser Situation.","Auf deiner Höhe befindet sich auf der rechten Spur ein LKW. Bleibe daher auf dem mittleren Fahrstreifen.","Der linke Fahrstreifen endet in Kürze und du bist noch recht weit vom roten PKW entfernt. Verzögere und bleibe auf dem mittleren Fahrstreifen."],"v":["https://video4.kalaiwa.de/assets/2207007v1440.mp4"],"rn":805},{"n":"2.2.07-008","t":"Wie verhalten Sie sich richtig?","p":5,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich reduziere meine Geschwindigkeit","Ich ordne mich auf dem rechten Fahrstreifen ein","Ich fahre mit unveränderter Geschwindigkeit weiter"],"co":[0],"ex":["Noch ist unklar, ob der PKW, der vom Einfädelungsstreifen auf die rechte Spur einfährt, ein weiteren Spurenwechsel auf den mittleren Fahrbahnstreifen anstrebt und dich hierbei übersieht. Verzögere daher und warte ab.","Auf der rechten Fahrbahn neben dir befindet sich ein LKW. Du kannst in diesem Moment also nicht nach rechts fahren.","Du solltest die Geschwindigkeit vermindern, um in dem Fall, dass der graue PKW auf die mittlere Spur wechselt, ausreichend Sicherheitsabstand zu ihm zu haben."],"v":["https://video4.kalaiwa.de/assets/2207008v1440.mp4"],"rn":806},{"n":"2.2.07-009","t":"Womit müssen Sie in dieser Situation rechnen?","p":5,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["- gelbe Lkw vor mir zum Überholen ausscheren wird","- graue Pkw auf den mittleren Fahrstreifen wechseln wird","- graue Pkw auf dem rechten Fahrstreifen bleiben wird"],"co":[1],"ex":["Es sieht nicht danach aus, als würde der gelbe LKW zum Überholen ansetzen.","Der graue PKW rast regelrecht auf die mittlere Spur. Daher solltest du umgehend verzögern.","Der graue PKW blinkt und schert nach links aus. Er wird wahrscheinlich auf die mittlere Spur wechseln."],"v":["https://video4.kalaiwa.de/assets/2207009v1440.mp4"],"rn":807},{"n":"2.2.07-010","t":"Wie verhalten Sie sich richtig?","p":5,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich behalte die Geschwindigkeit bei und bleibe auf dem mittleren Fahrstreifen","Ich behalte die Geschwindigkeit bei und wechsle auf den rechten Fahrstreifen","Ich reduziere die Geschwindigkeit und bleibe auf dem mittleren Fahrstreifen"],"co":[2],"ex":["Vermindere die Geschwindigkeit, um den blauen PKW nicht rechts zu überholen.","Damit du den blauen PKW nicht rechts überholst, musst die Geschwindigkeit reduzieren.","Der rote PKW hat den blauen rechts überholt. Das ist jedoch verboten. Daher musst du hier verzögern, um es ihm nicht gleichzutun."],"v":["https://video4.kalaiwa.de/assets/2207010v1440.mp4"],"rn":808},{"n":"2.2.07-011","t":"Sie fahren auf einer Straße mit mehreren markierten Fahrstreifen für eine Richtung. Wann ist das Reißverschlussverfahren anzuwenden?","p":3,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Wenn ein Einfädelungsstreifen auf der Autobahn endet","Wenn ein Fahrstreifen endet","Wenn ein Fahrstreifen wegen eines Hindernisses nicht durchgehend befahrbar ist"],"co":[1,2],"ex":["Reißverschlussverfahren ist nicht bei Einfädelungsstreifen anzuwenden.","Reißverschlussverfahren ist anzuwenden, wenn von mehreren gleichberechtigten Fahrstreifen einer endet.","Reißverschlussverfahren ist anzuwenden, wenn von mehreren gleichberechtigten Fahrstreifen einer nicht mehr befahrbar ist."],"rn":809},{"n":"2.2.07-012-M","t":"Was gilt für die Nutzung des Seitenstreifens in dieser Situation?","p":4,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["- darf nur von Lkws genutzt werden","- darf nur bei einer Panne genutzt werden","- muss wie ein rechter Fahrstreifen genutzt werden"],"co":[2],"ex":["Der Seitenstreifen darf sowohl von Autos als auch von Lkws genutzt werden. Die Beschilderung zeigt diesbezüglich keine Einschränkung.","Der Seitenstreifen muss als normaler Fahrstreifen genutzt werden. Das zeigt so die Beschilderung.","Die Beschilderung zeigt an, dass du den Seitenstreifen hier als ganz normalen rechten Fahrstreifen nutzen musst."],"i":["https://video2.kalaiwa.de/assets/2207012m.webp"],"rn":810},{"n":"2.2.07-013-M","t":"Was gilt in dieser Situation für die Nutzung des Seitenstreifens?","p":4,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["– darf nur bei einer Panne genutzt werden","– darf nur von Lkws genutzt werden","– muss wie ein rechter Fahrstreifen genutzt werden"],"co":[0],"ex":["Der Seitenstreifen darf nicht regulär benutzt werden. Du darfst ihn nur im Falle einer Panne nutzen.","Der Seitenstreifen ist gesperrt und darf auch nicht von Lkws genutzt werden. Der Lkw in deinem Rückspiegel muss also den Fahrstreifen wechseln.","Der Seitenstreifen darf regulär nicht befahren werden."],"i":["https://video4.kalaiwa.de/assets/2207013m.webp"],"rn":811},{"n":"2.2.07-014-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.2.07","ch":"Benutzung Von Fahrstreifen Durch Kraftfahrzeuge","th":"Verhalten Im Strassenverkehr","o":["Ich verringere meine Geschwindigkeit","Ich beschleunige","Ich lasse den blauen Pkw vor mir einscheren"],"co":[0,2],"ex":["Du solltest deine Geschwindigkeit verringern, um dem blauen Pkw den Wechsel auf die rechte Fahrspur zu ermöglichen.","In dieser Situation wäre es zu gefährlich zu beschleunigen, da der blaue Pkw auf die rechte Fahrspur wechseln will und seine linke Fahrspur bereits in Sichtweite endet. Es könnte eine gefährliche Verkehrssituation entstehen, bei der der blaue Pkw plötzlich abbremsen muss oder mit dir kollidiert.","Du solltest den blauen Pkw vor dir einscheren lassen, da seine Fahrspur bereits in Sichtweite endet. So verhinderst du, dass der blaue Pkw abrupt abbremsen muss oder mit dir kollidiert."],"v":["https://video2.kalaiwa.de/assets/2207014mv1440.mp4"],"rn":812},{"n":"2.2.09-101","t":"Wie verhalten Sie sich beim Rückwärtsfahren richtig?","p":3,"c":"2.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- sichere den Verkehrsraum zusätzlich durch einen Rundumblick","- fahre aufmerksam und langsam","- achte darauf, dass sich keine Personen im toten Winkel befinden"],"co":[0,1,2],"ex":["Auf diese Weise kannst Du Dich davon überzeugen, dass Du niemanden beim Rückwärtsfahren gefährdest.","Der Bereich hinter Deinem Fahrzeug ist meist nicht so gut einsehbar. Kinder und kleinere Hindernisse können leicht übersehen werden. Besondere Aufmerksamkeit und Ruhe sind beim Rückwärtsfahren deshalb zwingend notwendig.","Wenn Personen an Deinem Fahrzeug vorbei laufen und im toten Winkel befinden, siehst Du sie nicht durch Deine Spiegel. Um sicher zu gehen, musst du einen Rundumblick machen."],"rn":813},{"n":"2.2.09-002-M","t":"Warum müssen Sie vor dem Linksabbiegen warten?","p":5,"c":"2.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- Pkws","- Fahrrads","- Motorrads"],"co":[2],"ex":["Du und der andere PKW könnt voreinander abbiegen. Daher ist er kein Grund für dich zu warten.","Die Radfahrerin hält vorschriftsgemäß an und ist somit kein Wartegrund für dich.","Der entgegenkommende PKW verdeckt den Motorradfahrer. So kannst du nicht sehen, wie dieser weiterfahren möchte. Dieser wiederum sieht dich nicht blinken und es besteht die Gefahr, dass er am PKW vorbeifährt. Warte daher das Verhalten des Motorradfahrers ab, bevor du abbiegst."],"v":["https://video4.kalaiwa.de/assets/2209002mv1440.mp4"],"rn":814},{"n":"2.2.09-003-M","t":"Wie verhalten Sie sich richtig?","p":5,"c":"2.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["- jetzt ab, um die Nachfolgenden durch mein Zögern nicht zu verunsichern","- ab, nachdem mich das rote Fahrzeug überholt hat","- jetzt ab, um die Fahrbahn frei zu machen"],"co":[1],"ex":["Warte mit dem Abbiegen, bis das rote Fahrzeug dich überholt hat.","So verhinderst du, dass jemand gefährdet wird.","Dann würdest du mit dem roten Fahrzeug zusammenstoßen. Lass ihn überholen und biege dann ab."],"v":["https://video4.kalaiwa.de/assets/2209003mv1440.mp4"],"rn":815},{"n":"2.2.09-004-M","t":"Sie möchten nach links abbiegen. Wie verhalten Sie sich richtig?","p":5,"c":"2.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Ich fahre weiter, da ich hier nicht abbiegen darf","Ich beschleunige und biege zügig ab","Ich halte auf Höhe des Feldweges und warte"],"co":[2],"ex":["Du darfst hier abbiegen, nur musst du damit warten, bis der Motorradfahrer das Überholmanöver beendet hat.","So würdest du den überholenden Motorradfahrer gefährden und wärst zu schnell, um in den Feldweg einzubiegen. Lass ihn überholen und biege dann ab.","Warte bis dich das Motorrad überholt hat und biege dann in den Feldweg ein. Es ist unwahrscheinlich, dass das Motorrad in den Feldweg einbiegen wird."],"v":["https://video4.kalaiwa.de/assets/2209004mv1440.mp4"],"rn":816},{"n":"2.2.09-010-M","t":"Sie möchten nach links abbiegen. Welcher Fahrlinie müssen Sie folgen?","p":3,"c":"2.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Der rechten Fahrlinie","Der linken Fahrlinie","Der mittleren Fahrlinie"],"co":[2],"ex":["Du solltest dich beim Linksabbiegen möglichst weit links einordnen. Hier kannst du allerdings nicht ganz links fahren, weil dir möglicherweise Radfahrer entgegenkommen. Folge der mittleren Fahrlinie.","Folge nicht der linken Fahrspur, weil hier möglicherweise Radfahrer entgegenkommen.","Du fährst in einer Einbahnstraße, in der Radverkehr in beide Richtungen erlaubt ist. Folge der mittleren Fahrlinie, um potentiell entgegenkommende Radfahrer nicht zu behindern."],"i":["https://video2.kalaiwa.de/assets/2209010m.webp"],"rn":817},{"n":"2.2.09-011-M","t":"Sie möchten nach links abbiegen. Welcher Fahrlinie müssen Sie folgen?","p":3,"c":"2.2.09","ch":"Abbiegen Wenden Und Rueckwaertsfahren","th":"Verhalten Im Strassenverkehr","o":["Der linken Fahrlinie","Der mittleren Fahrlinie","Der rechten Fahrlinie"],"co":[0],"ex":["Wenn du in einer Einbahnstraße nach links abbiegen willst, fahre ganz links.","Weil du in einer Einbahnstraße fährst, musst du der linken Fahrlinie folgen.","In der Einbahnstraße musst du beim Linksabbiegen der linken Fahrlinie folgen."],"i":["https://video4.kalaiwa.de/assets/2209011m.webp"],"rn":818},{"n":"2.2.11-001-M","t":"Warum müssen Sie jetzt besonders aufmerksam sein?","p":4,"c":"2.2.11","ch":"","th":"","o":["Weil die Ampel auf „Rot“ umschalten könnte","Weil sich der Verkehr in der Straße, in die ich einbiegen möchte, staut","Weil der Lkw beim Abbiegen sehr langsam werden wird"],"co":[0,1,2],"ex":["Weil der Lkw sehr langsam abbiegt und sich der Verkehr staut, könnte die Ampel auf \"Rot\" umschalten, bevor du abbiegen kannst. Warte bis zur nächsten Grünphase, bevor du abbiegst.","In der Straße, auf die du einbiegen möchtest, staut sich der Verkehr. Es ist abzusehen, dass du wegen des stockenden Verkehrs nicht rechtzeitig abbiegen kannst, ohne die Kreuzung zu blockieren. Warte, wenn nötig, mit dem Abbiegen bis zur nächsten Grünphase deiner Ampel.","Weil der Schwerpunkt bei einem Betonmischer hoch liegt, wird der Lkw beim Abbiegen sehr langsam. Außerdem stockt der Verkehr auf der Straße, in die du und der Lkw abbiegen wollt."],"v":["https://video2.kalaiwa.de/assets/2211001mv1440.mp4"],"rn":819},{"n":"2.2.12-001","t":"Wo ist das Halten verboten?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["An Bus-Haltestellen","Im Bereich von scharfen Kurven","Auf Autobahnen und Kraftfahrstraßen außerhalb der Parkplätze"],"co":[1,2],"ex":["An Bushaltestellen ist das Halten erlaubt, solange kein öffentliches Verkehrsmittel behindert wird.","Die StVo schreibt vor: \"§ 12 Halten und Parken (1) Das Halten ist unzulässig (...) 2. im Bereich von scharfen Kurven (...)\" In scharfen Kurven ist die Sicht eingeschränkt. Steht dort schwer einsehbar ein Fahrzeug, dann kann der herannahende Verkehr nicht rechtzeitig reagieren.","Laut StVO gilt: \"§ 18 Autobahnen und Kraftfahrstraßen (...) (8) Halten, auch auf Seitenstreifen, ist verboten.(...)\" Folglich darfst du außerhalb der Parkplätze nicht auf Autobahnen oder Kraftfahrstraßen halten."],"rn":820},{"n":"2.2.12-003","t":"Wo ist das Parken verboten?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Auf schmalen Fahrbahnen gegenüber Ein- und Ausfahrten von Grundstücken","Unmittelbar hinter Fußgängerüberwegen","An Taxenständen"],"co":[0,2],"ex":["Dadurch behinderst du diejenigen, die die Ein- und Ausfahrt nutzen.","Unmittelbar hinter Fußgängerüberwegen darfst du parken. Unmittelbar vor Fußgängerüberwegen ist dies jedoch verboten.","Hier gilt absolutes Halteverbot. Es dürfen nur Taxen in diesen Zonen halten."],"rn":821},{"n":"2.2.12-102","t":"Bis zu welcher zulässigen Gesamtmasse dürfen Fahrzeuge auf besonders gekennzeichneten Gehwegen geparkt werden?","p":2,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"2,8 t","e":"Laut StVO § 42 Abs. 4 dürfen Fahrzeuge bis zu einer Gesamtmasse von 2,8 t auf besonders gekennzeichneten Gehwegen parken.","rn":822},{"n":"2.2.12-104","t":"Welchen Mindestabstand von einer Ampel muss ein Fahrzeug beim Halten einhalten, wenn diese durch das Fahrzeug verdeckt würde?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"10 m","e":"Ein Fahrzeug muss mindestens 10 m vor der Ampel halten, damit die freie Sicht auf die Lichtzeichen in jedem Fall gewährleistet ist.","rn":823},{"n":"2.2.12-105","t":"Wo dürfen Sie innerorts einen Anhänger mit einer zulässigen Gesamtmasse von mehr als 2 t an Sonn- und Feiertagen sowie zwischen 22.00 und 6.00 Uhr regelmäßig parken?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["In Gewerbegebieten","In Sondergebieten, die der Erholung dienen, auf ausreichend breiten Straßen","In reinen Wohngebieten auf entsprechend gekennzeichneten Parkplätzen"],"co":[0,2],"ex":["Das regelmäßige Parken von Anhängern mit einer zulässigen Gesamtmasse über 2 t in der Zeit von 22:00 Uhr – 6:00 Uhr ist in Gewerbegebieten gestattet.","Hier dürfen diese Anhänger nicht parken.","Hier dürfen Anhänger mit über 2 t zulässiger Gesamtmasse zu diesen Zeiten parken."],"rn":824},{"n":"2.2.12-106","t":"Worauf müssen Sie achten, wenn Sie einen Anhänger ohne Zugfahrzeug parken?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["- entsprechend gekennzeichneten Parkplätzen länger als 2 Wochen geparkt werden","- öffentlichen Straßen nicht länger als 2 Wochen geparkt werden","- ausreichend befestigten Seitenstreifen zeitlich unbegrenzt geparkt werden"],"co":[0,1],"ex":["Ausgenommen von diesem allgemeinen Parkverbot sind lediglich speziell gekennzeichnete Parkplätze für Anhänger.","Anhänger ohne Zugfahrzeug dürfen im öffentlichen Verkehrsraum generell nicht länger als 2 Wochen geparkt werden. Dies gilt auch für Parkplätze. Damit soll ein Dauerparken auf der Straßen- und Parkflächen speziell durch Wohnanhänger verhindert werden.","Das Parkverbot für Anhänger ohne Zugfahrzeug gilt im gesamten öffentlichen Verkehrsraum, also auch auf dem Seitenstreifen einer Fahrbahn."],"rn":825},{"n":"2.2.12-203","t":"Vor welchen Zeichen müssen Sie mindestens 10 m Abstand halten, wenn diese sonst durch Ihr Fahrzeug verdeckt würden?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Halt. Vorfahrt gewähren.","Haltverbot","Andreaskreuz"],"co":[0,2],"ex":["Vor einem \"Vorfahrt gewähren\"-Verkehrszeichen muss mindestens 10 m Abstand gehalten werden, wenn dies sonst durch dein Fahrzeug verdeckt würde.","Hier muss kein Abstand zum Verkehrszeichen gehalten werden.","Vor einem Andreaskreuz musst du mindestens 10 m Abstand halten, wenn du es sonst durch dein Fahrzeug verdecken würdest."],"rn":826},{"n":"2.2.12-204","t":"Sie möchten am rechten Fahrbahnrand parken. Wie groß muss der Abstand zwischen Ihrem Fahrzeug und der durchgehenden Fahrstreifenbegrenzungslinie mindestens sein?","p":2,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","na":"3 m","e":"Bei einem Mindestabstand von 3 m ist gewährleistet, dass du für den fließenden Verkehr kein Hindernis darstellst.","rn":827},{"n":"2.2.12-107-M","t":"Sie möchten am rechten Fahrbahnrand parken. Wie sollten Sie sich in dieser Situation verhalten?","p":2,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Ich parke jetzt ein, weil ich Vorrang habe","Ich verzichte auf den Parkplatz, obwohl ich Vorrang habe"],"co":[1],"ex":["Würdest du jetzt einparken könnte es zu einem Zusammenstoß kommen.","Du hast zuerst geblinkt und deshalb Vorrang auf den Parkplatz. Um einem Konflikt aus dem Weg zu gehen, solltest du trotzdem auf den Parkplatz verzichten."],"v":["https://video4.kalaiwa.de/assets/2212107mv1440.mp4"],"rn":828},{"n":"2.2.12-108-M","t":"Sie möchten am rechten Fahrbahnrand parken. Wer hat in dieser Situation Vorrang?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Keiner hat Vorrang, wir müssen uns verständigen","Der blaue Pkw hat Vorrang","Ich habe Vorrang"],"co":[1],"ex":["Eine Verständigung ist nicht nötig. Der blaue Pkw hat den Vorrang.","Der blaue Pkw hat zuerst geblinkt und bereits mit dem Einparken begonnen. Er hat Vorrang.","Du hast erst nach dem blauen Pkw geblinkt und hast deshalb keinen Vorrang."],"v":["https://video2.kalaiwa.de/assets/2212108mv1440.mp4"],"rn":829},{"n":"2.2.12-109-M","t":"Sie möchten auf der rechten Seite rückwärts einparken. Was ist in dieser Situation richtig?","p":3,"c":"2.2.12","ch":"Halten Und Parken","th":"Verhalten Im Strassenverkehr","o":["Ich schalte das Warnblinklicht ein","Ich rechne mit ausparkenden Fahrzeugen","Ich achte vor dem Einlenken auf den Gegenverkehr"],"co":[1,2],"ex":["Das Einschalten des Warnblinkers ist beim Einparken nicht nötig.","Rechne bei Parkbuchten und Parkplätzen immer mit Fahrzeugen, die ausparken.","Beim Einlenken in die Parklücke könnte dein Fahrzeug auf die Gegenfahrbahn ragen. Achte darauf, dass kein Gegenverkehr kommt."],"i":["https://video2.kalaiwa.de/assets/2212109m.webp"],"rn":830},{"n":"2.2.13-001","t":"Wo müssen Sie zum Parken eine Parkscheibe benutzen?","p":2,"c":"2.2.13","ch":"Einrichtungen Zur Ueberwachung Der Parkzeit","th":"Verhalten Im Strassenverkehr","o":["An einer defekten Parkuhr","Wo es durch Verkehrszeichen angeordnet ist","Im eingeschränkten Haltverbot"],"co":[0,1],"ex":["Du darfst die zu einer Parkuhr gehörige Parkfläche auch dann benutzen, wenn diese defekt ist. Die Einhaltung der Höchstparkdauer muss dennoch gewährleistet sein. Darum bist du dann zum Benutzen einer Parkscheibe verpflichtet.","Verkehrszeichen, die das Benutzen einer Parkscheibe anordnen, schreiben zugleich auch die zulässige Höchstparkdauer vor. Damit diese überwacht werden kann, musst du hier zum Parken eine Parkscheibe benutzen.","Im eingeschränkten Haltverbot ist das Benutzen einer Parkscheibe nicht vorgeschrieben. Es wäre auch nicht sinnvoll, da du hier ohnehin nur 3 Minuten halten darfst."],"rn":831},{"n":"2.2.13-002","t":"Eine Parkuhr ist noch nicht abgelaufen. Wie verhalten Sie sich?","p":2,"c":"2.2.13","ch":"Einrichtungen Zur Ueberwachung Der Parkzeit","th":"Verhalten Im Strassenverkehr","o":["- ausnutzen, ohne die Parkuhr erneut zu betätigen","- nur ausnutzen, wenn Sie eine Parkscheibe verwenden","- nicht ausnutzen"],"co":[0],"ex":["Wenn die Parkuhr läuft, darfst du dort halten. Dabei ist unwichtig, ob du die Parkuhr betätigt hast oder ob sie bei deiner Ankunft noch nicht abgelaufen war.","Du darfst die Parkuhr nutzen und brauchst hierfür keine Parkscheibe. Die Parkscheibe ist lediglich zu verwenden, falls die Parkuhr defekt ist.","Du darfst die Restparkzeit ausnutzen."],"rn":832},{"n":"2.2.13-003","t":"Sie kommen um 10.40 Uhr in einem Bereich an, in dem mit Parkscheibe 2 Stunden lang geparkt werden darf. Welche Uhrzeit müssen Sie auf der Parkscheibe einstellen?","p":2,"c":"2.2.13","ch":"Einrichtungen Zur Ueberwachung Der Parkzeit","th":"Verhalten Im Strassenverkehr","o":["12.40 Uhr","11.00 Uhr","13.00 Uhr"],"co":[1],"ex":["Dies ist nicht die richtige Uhrzeit.","Das ist die halbe Stunde, die dem Zeitpunkt des Anhaltens folgt.","Stelle den Beginn des Parkens ein und nicht das Ende."],"rn":833},{"n":"2.2.13-004","t":"Sie wollen auf einem Platz mit Parkscheinautomat parken. Was haben Sie zu beachten?","p":2,"c":"2.2.13","ch":"Einrichtungen Zur Ueberwachung Der Parkzeit","th":"Verhalten Im Strassenverkehr","o":["Die auf dem Parkschein angegebene Parkzeit nicht überschreiten","Ein Parkschein ist immer überflüssig, wenn Sie eine Parkscheibe benutzen","Gültigen Parkschein am Fahrzeug so anbringen, dass er von außen gut lesbar ist"],"co":[0,2],"ex":["Du darfst hier nur so lange parken, wie es auf dem Parkschein steht.","Parkzonen sind dementsprechend gekennzeichnet. Es gibt solche, in denen Parkscheiben ausreichen und solche, in denen Parkscheine notwendig sind.","Nur dann kann die Parkzeit kontrolliert werden."],"rn":834},{"n":"2.2.13-101","t":"Wozu darf an nicht laufenden Parkuhren gehalten werden?","p":2,"c":"2.2.13","ch":"Einrichtungen Zur Ueberwachung Der Parkzeit","th":"Verhalten Im Strassenverkehr","o":["Zu einem kurzen Einkauf","Zum Ein- oder Aussteigen","Zum Be- oder Entladen"],"co":[1,2],"ex":["Sobald du dich vom Fahrzeug entfernst, gilt das nicht mehr als halten, sondern als parken. Dann musst du die Parkuhr betätigen.","Zum Ein- oder Aussteigen darfst du hier halten.","An einer nicht-laufenden Parkuhr darfst du zum Be- oder Entladen halten."],"rn":835},{"n":"2.2.14-102","t":"Was müssen Sie beim Verlassen Ihres Pkws tun?","p":3,"c":"2.2.14","ch":"Sorgfaltspflichten","th":"Verhalten Im Strassenverkehr","o":["Vor dem Öffnen der Tür den nachfolgenden Verkehr beachten","Das Fahrzeug gegen Wegrollen sichern","Das Fahrzeug gegen unbefugte Benutzung sichern"],"co":[0,1,2],"ex":["Du darfst die Tür erst öffnen, wenn du gewährleisten kannst, dass hierdurch kein herannahender Verkehrsteilnehmer behindert oder gefährdet wird und du selbst dich hierdurch keiner Gefahr aussetzt.","Hierzu solltest du einen Gang einlegen oder die Handbremse betätigen. Parkst du an Steigungen, dann solltest du beides tun. Im Winter empfiehlt sich der Gang, weil die Handbremse einfrieren kann. Bei Automatikgetrieben kannst du den Wahlhebel auf \"P\" stellen.","Du musst sicherstellen, dass unbefugte dein Fahrzeug nicht benutzen. Zieh deshalb den Zündschlüssel ab und dreh das Lenkrad bis das Lenkradschloss einrastet. Achte zudem darauf, dass alle Fenster und Türen geschlossen sind."],"rn":836},{"n":"2.2.14-104","t":"Ihr Pkw steht am Fahrbahnrand. Was ist beim Einsteigen richtig?","p":3,"c":"2.2.14","ch":"Sorgfaltspflichten","th":"Verhalten Im Strassenverkehr","o":["Türen auf der Fahrbahnseite erst öffnen, wenn es der Verkehr erlaubt","Mitfahrer möglichst vom Gehweg aus einsteigen lassen","Das Öffnen der Türen auf der rechten Seite ist immer gefahrlos möglich"],"co":[0,1],"ex":["So wird niemand behindert oder gefährdet.","So wird weder der fließende Verkehr behindert, noch werden die Mitfahrer gefährdet.","Auf der rechten Seite könnten sich Passanten oder Radfahrer befinden. Du solltest eine Fahrzeugtür niemals unbedacht öffnen."],"rn":837},{"n":"2.2.14-109","t":"Wie sichern Sie Ihren Pkw beim Verlassen gegen unbefugte Benutzung?","p":3,"c":"2.2.14","ch":"Sorgfaltspflichten","th":"Verhalten Im Strassenverkehr","o":["Ich verschließe die Türen","Ich aktiviere die Kindersicherung","Ich schließe die Fenster"],"co":[0,2],"ex":["Du bist dazu verpflichtet, deinen geparkten Pkw gegen unbefugte Benutzung abzusichern. Du musst also die Türen verschließen, damit keine unbefugte Person Zugang zu deinem Pkw hat.","Eine aktivierte Kindersicherung bietet keinen Schutz gegen das unbefugte Eindringen in deinen Pkw von außen.","Wenn du die Fenster nicht schließt, kann es sein, dass andere darüber ins Wageninnere greifen und sich Zugang zu deinem Pkw verschaffen."],"rn":838},{"n":"2.2.14-110","t":"Sie möchten ein Kind aus Ihrem Pkw aussteigen lassen. Was sollten Sie dabei beachten?","p":4,"c":"2.2.14","ch":"Sorgfaltspflichten","th":"Verhalten Im Strassenverkehr","o":["- die Fahrbahn nicht mehr überqueren müssen","- auf der Gehwegseite aussteigen","- vor möglichen Gefahren beim Aussteigen gewarnt werden"],"co":[0,1,2],"ex":["Lass das Kind da aussteigen, wo es keine Straße mehr überqueren muss. Jede Straßenüberquerung ist für ein Kind eine Gefahr und sollte vermieden werden, wenn möglich.","Stelle sicher, dass das Kind nach Möglichkeit auf der Gehwegseite und nicht auf der Fahrbahn aussteigt.","Warne das Kind beim Aussteigen vor möglichen Gefahren wie Radfahrern oder Eisglätte und hilf ihm, sich auf die Gefahrensituation einzustellen."],"rn":839},{"n":"2.2.14-107-M","t":"Warum dürfen Sie jetzt nicht aussteigen?","p":4,"c":"2.2.14","ch":"Sorgfaltspflichten","th":"Verhalten Im Strassenverkehr","o":["Wegen der Fußgängerin","Wegen des Motorrads","Wegen des Radfahrers"],"co":[2],"ex":["Die Fußgängerin befindet sich auf der Beifahrerseite, sie wird dadurch nicht beeinträchtigt.","Das Motorrad ist weit genug entfernt und wird durch dich nicht behindert.","Der Radfahrer fährt unmittelbar an deiner Fahrertür vorbei. Bevor du diese öffnest, musst du dich immer vergewissern, dass du niemanden behinderst und erst dann darfst du die Tür öffnen."],"v":["https://video4.kalaiwa.de/assets/2214107mv1440.mp4"],"rn":840},{"n":"2.2.14-108-M","t":"Sie haben auf einem Parkstreifen angehalten und möchten aussteigen. Wie müssen Sie sich in dieser Situation verhalten?","p":3,"c":"2.2.14","ch":"Sorgfaltspflichten","th":"Verhalten Im Strassenverkehr","o":["- im linken Außenspiegel vor dem Öffnen der Tür","- durch einen Schulterblick nach links vor dem Öffnen der Tür","- ausschließlich durch die leicht geöffnete Tür"],"co":[0,1],"ex":["Bevor du die Tür öffnest und aussteigst, musst du dich im linken Außenspiegel vergewissern, dass niemand von hinten kommt. Du darfst erst dann aussteigen, wenn sich niemand nah an deinem Auto befindet und du den Verkehr nicht mit dem Öffnen behinderst.","Du musst einen Schulterblick nach links vor dem Öffnen der Tür machen, da du nur so Verkehrsteilnehmer entdecken kannst, die sich im toten Winkel befinden.","Du darfst nahenden Verkehr nicht erst durch die leicht geöffnete Tür beobachten. Bereits eine leicht geöffnete Tür kann andere Verkehrsteilnehmer verunsichern. Außerdem stellt sie ein Hindernis für z.B. Radfahrer da, die sehr nah am rechten Rand fahren."],"i":["https://video4.kalaiwa.de/assets/2214108m.webp"],"rn":841},{"n":"2.2.15-105","t":"Ein Pkw mit Servolenkung ist mit Motorschaden liegen geblieben und soll abgeschleppt werden. Was ist richtig?","p":3,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["- ist nicht beeinträchtigt","- geht wesentlich schwerer","- ist blockiert"],"co":[1],"ex":["Die Lenkung ist durchaus beeinträchtigt.","Die Servolenkung funktioniert nur, wenn der Motor läuft. Bei einem Motorschaden muss die gesamte Lenkkraft vom Fahrer übernommen werden.","Die Lenkung ist nicht blockiert, sie funktioniert nur wesentlich schwerer."],"rn":842},{"n":"2.2.15-107","t":"Wie müssen Sie nachts ein Fahrzeug sichern, das an einer Stelle liegen geblieben ist, an der es eine Gefahr für den übrigen Verkehr bildet?","p":4,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["Sofort Warnblinklicht einschalten","Warndreieck in ausreichender Entfernung aufstellen","Rückfahrscheinwerfer einschalten"],"co":[0,1],"ex":["Das ist der erste notwendige Schritt, um andere Verkehrsteilnehmer auf dein Pannenfahrzeug hinzuweisen.","Zuvor solltest du den Warnblinker einschalten und die Warnweste anziehen, damit dich andere Verkehrsteilnehmer bei Dunkelheit erkennen können.","Das ist weder notwendig, noch hilfreich."],"rn":843},{"n":"2.2.15-109","t":"Was ist beim Abschleppen zu beachten?","p":3,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["Abschleppseil/Abschleppstange muss deutlich gekennzeichnet sein","Der Abstand zwischen den Fahrzeugen darf nicht größer als 5 m sein","Motorräder dürfen nur mit fester Verbindung abgeschleppt werden"],"co":[0,1],"ex":["Dies ist notwendig, damit dies vom übrigen Verkehr wahrgenommen werden kann.","Das ist der Maximalabstand, der zwischen den Fahrzeugen bestehen darf.","Motorräder dürfen nicht abgeschleppt werden."],"rn":844},{"n":"2.2.15-110","t":"Ihr Pkw hat auf der Autobahn eine Reifenpanne. Wie müssen Sie sich verhalten?","p":4,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["- das Warndreieck in etwa 100 m Entfernung aufstellen","- bis zur nächsten Ausfahrt weiterfahren","- das Warnblinklicht einschalten und möglichst weit rechts anhalten"],"co":[0,2],"ex":["Auf Schnellstraßen beträgt der Abstand 100 m. Zieh dir allerdings vor Verlassen des Fahrzeugs deine Warnweste an.","Das wäre sehr gefährlich. Fahre möglichst weit rechts heran, schalte das Warnblinklicht ein und stelle das Warndreieck auf.","So machst du andere Verkehrsteilnehmer auf dich aufmerksam und sie können möglichst ungehindert an dir vorbeifahren."],"rn":845},{"n":"2.2.15-111","t":"Ihr Pkw hat einen Defekt und ist nicht mehr fahrbereit. Was ist beim Abschleppen zu beachten?","p":3,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["- zusätzlich die Nebelschlussleuchte zur Signalisierung des Abschleppvorgangs anzuschalten","- bei Ausfall des Motors die aufzubringende Kraft am Bremspedal erheblich höher","- nach Möglichkeit eine Abschleppstange zu benutzen"],"co":[1,2],"ex":["Das musst und darfst du nicht tun.","Da der Bremskraftverstärker nur bei aktivem Motor funktioniert, muss hier bei Betätigung des Bremspedals erheblich mehr Kraft aufgebracht werden.","Durch das Verwenden einer Abschleppstange wird das Risiko eines Auffahrunfalls beim Abschleppen vermieden."],"rn":846},{"n":"2.2.15-112","t":"Ihr Pkw hat einen Defekt und ist nicht mehr fahrbereit. Was ist beim Abschleppen zu beachten?","p":3,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["- darf die Autobahn nur als Abkürzung zur nächsten Werkstatt benutzt werden","- ist das Abschleppseil möglichst straff zu halten","- ist an beiden Fahrzeugen Warnblinklicht einzuschalten"],"co":[1,2],"ex":["Auf der Autobahn ist Abschleppen nur dann erlaubt, wenn die Panne auch dort passiert ist.","So zieht man möglichst ruckfrei und verhindert, dass das Seil reißt. Ein Abschleppseil darf die Länge von 5 m nicht überschreiten.","Das informiert und warnt andere Verkehrsteilnehmer, dass diese beiden Fahrzeuge nicht \"normal\" am Straßenverkehr teilnehmen, sondern z.B. viel langsamer als gewohnt fahren."],"rn":847},{"n":"2.2.15-114","t":"Ihr Pkw hat einen Motorschaden und soll mit einem Abschleppseil abgeschleppt werden. Was müssen Sie beachten?","p":3,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["Ein defekter Pkw mit Lenkunterstützung lässt sich schwerer lenken","Zum Abschleppen eines Pkws wird mindestens die Fahrerlaubnisklasse BE benötigt","Beim Abschleppen eines Elektrofahrzeugs müssen die Vorgaben des Herstellers beachtet werden"],"co":[0,2],"ex":["Die Lenkunterstützung eines Pkws wirkt nicht, wenn der Motor nicht läuft. Heißt: Du kannst noch lenken, musst jedoch die komplette Kraft zum Lenken selbst aufbringen.","Du benötigst zum Abschleppen den üblichen Führerschein der Klasse B. Abschleppen hat nichts mit Hänger-Fahren zu tun.","Beachte die Herstellervorgaben, um eine Beschädigung der elektrischen Komponenten zu vermeiden."],"rn":848},{"n":"2.2.15-115","t":"Sie haben außerorts eine Panne. Ihr Kraftfahrzeug steht hinter einer Kurve auf der Fahrbahn. Was ist in dieser Situation richtig?","p":4,"c":"2.2.15","ch":"Liegenbleiben Und Abschleppen Von Fahrzeugen","th":"Verhalten Im Strassenverkehr","o":["Ich muss etwa 100 m hinter dem Fahrzeug mindestens ein auffällig warnendes Zeichen aufstellen","Ich muss das Warnblinklicht einschalten","Ich sollte eine Warnweste tragen"],"co":[0,1,2],"ex":["Bei einer Panne musst du etwa 100 m hinter deinem Fahrzeug ein Warndreieck aufstellen, um anfahrende Fahrzeuge zu warnen.","Wenn du eine Panne hast, solltest du anfahrende Fahrzeuge mit Warnblinklicht davor warnen, dass sich dein Auto stehend auf der Fahrbahn befindet.","Um besser sichtbar zu sein, solltest du nach einer Panne eine Warnweste anziehen."],"rn":849},{"n":"2.2.16-001","t":"Wo dürfen Sie die Lichthupe zum Anzeigen der Überholabsicht benutzen?","p":2,"c":"2.2.16","ch":"Warnzeichen","th":"Verhalten Im Strassenverkehr","o":["Außerorts bei Dunkelheit","Innerorts bei Dunkelheit","Außerorts am Tage"],"co":[0,2],"ex":["Um außerorts die Überholabsicht anzuzeigen, darf die Lichthupe getätigt werden.","Innerorts darf die Lichthupe nicht verwendet werden.","In diesem Fall darf die Lichthupe genutzt werden."],"rn":850},{"n":"2.2.16-101","t":"Wann müssen Sie an Ihrem Kraftfahrzeug das Warnblinklicht einschalten?","p":4,"c":"2.2.16","ch":"Warnzeichen","th":"Verhalten Im Strassenverkehr","o":["- an einer unübersichtlichen Stelle eine Panne hat","- von mir kurz in zweiter Reihe geparkt wird","- abgeschleppt wird"],"co":[0,2],"ex":["Hast du an einer unübersichtlichen Stelle eine Panne, solltest du andere Verkehrsteilnehmer mit deinem Warnblinklicht warnen.","Das Parken in zweiter Reihe ist kein Grund, das Warnblinklicht einzuschalten.","Während dein Auto abgeschleppt wird, musst du das Warnblinklicht anschalten."],"rn":851},{"n":"2.2.17-001","t":"Woran können Sie erkennen, ob die Nebelschlussleuchte eingeschaltet ist?","p":2,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["An der roten Kontrollleuchte","An der gelben Kontrollleuchte","An der blauen Kontrollleuchte"],"co":[1],"ex":["Es gibt mehrere rote Kontrollleuchten mit unterschiedlichen Bedeutungen. Auf eine eingeschaltete Nebelschlussleuchte deuten diese allerdings nicht hin.","Die gelbe Kontrollleuchte weist auf die Nebelschlussleuchte hin.","Die blaue Kontrollleuchte zeigt das Fernlicht an."],"rn":852},{"n":"2.2.17-005","t":"Die Sicht ist erheblich behindert. Wann dürfen Sie Nebelscheinwerfer einschalten?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Bei Schneefall","Bei Regen","Bei Nebel"],"co":[0,1,2],"ex":["Wenn die Sichtverhältnisse dies erfordern, dürfen bei Schneefall die Nebelscheinwerfer eingeschaltet werden.","Ist die Sicht hier deutlich eingeschränkt, dürfen die Nebelscheinwerfer eingeschaltet werden.","Nebelscheinwerfer dürfen bei erheblicher Einschränkung der Sicht aufgrund von Nebel benutzt werden."],"rn":853},{"n":"2.2.17-008","t":"Sie fahren nachts auf unbeleuchteter Straße. Ein Fahrzeug fährt in geringem Abstand voraus. Welches Licht müssen Sie dabei eingeschaltet haben?","p":4,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Standlicht allein","Fernlicht","Abblendlicht"],"co":[2],"ex":["Das Standlicht allein reicht nicht aus. Dieses wird im Stand verwendet. Beim Fahren im Dunkeln muss das Abblendlicht eingeschaltet sein.","Damit würdest du den vorausfahrenden Fahrzeugführer blenden.","Bei Dunkelheit muss immer das Abblendlicht eingeschaltet sein. Vergrößere zudem den Sicherheitsabstand."],"rn":854},{"n":"2.2.17-010","t":"Die hinteren Beleuchtungseinrichtungen Ihres Kraftfahrzeugs sind verdeckt. Was ist zu tun?","p":2,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["- in jedem Fall anzubringen","- nur bei Strecken über 5 km anzubringen","- nur bei Fahrten bei Dämmerung oder Dunkelheit anzubringen"],"co":[0],"ex":["Dies ist notwendig, um am Straßenverkehr teilhaben zu dürfen.","Bei jeder Streckenlänge ist ein Leuchtenträger notwendig.","Ein Leuchtenträger ist in jedem Fall anzubringen."],"rn":855},{"n":"2.2.17-012","t":"Welche Beleuchtungseinrichtung müssen Sie bei einer Fahrt in Dunkelheit an Ihrem Kraftfahrzeug grundsätzlich einschalten?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Nur das Standlicht","Das Fernlicht","Das Abblendlicht"],"co":[2],"ex":["Du darfst mit dem Standlicht alleine nicht fahren. Dieses dient nur der Kenntlichmachung deines Kraftfahrzeugs beim Halten oder Parken.","Das Fernlicht darf nur verwendet werden, wenn kein entgegenkommender Verkehr da ist. Dieser wird sonst geblendet.","Du nutzt bei Dunkelheit das Abblendlicht, um gesehen zu werden."],"rn":856},{"n":"2.2.17-101","t":"Wann dürfen Sie auch am Tage Nebelscheinwerfer einschalten?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["- Regen","- Nebel oder Schneefall","- Eis auf der Windschutzscheibe"],"co":[0,1],"ex":["Bei erheblicher Sichtbehinderung durch Regen dürfen die Nebelscheinwerfer benutzt werden.","In diesem Fall dürfen die Nebelscheinwerfer benutzt werden.","Durch die Benutzung der Nebelscheinwerfer wird die Sicht nicht verbessert. Bei vereister Windschutzscheibe darfst du nicht fahren. Du musst dieses erst mithilfe eines Eiskratzer beseitigen und darfst erst dann losfahren, wenn du ausreichend Sicht hast."],"rn":857},{"n":"2.2.17-102","t":"Wann dürfen Sie Nebelschlussleuchten einschalten?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Wenn durch Nebel die Sichtweite 100 m beträgt","Wenn durch starken Regen die Sicht behindert wird","Wenn durch Nebel die Sichtweite weniger als 50 m beträgt"],"co":[2],"ex":["Dann würdest du hinter dir fahrende Verkehrsteilnehmer stark blenden. Die Nebelschlussleuchte darf nur bei einer Sichtweite von maximal 50 m eingeschaltet werden.","Du darfst die Nebelschlussleuchten nur einschalten, wenn die Sichtweite unter 50 m ist.","Die Nebelschlussleuchte darf erst bei einer Sichtweite von 50 m und darunter eingeschaltet werden."],"rn":858},{"n":"2.2.17-103","t":"Wo genügen beim Parken eines Pkws auf unbeleuchteten Straßen Parkleuchten?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Auf Seitenstreifen von Autobahnen","Innerhalb geschlossener Ortschaften","Außerhalb geschlossener Ortschaften"],"co":[1],"ex":["Auf Autobahnen und somit auch auf Seitenstreifen von Autobahnen darf nicht geparkt werden.","Das Beleuchten eines parkenden PKW auf unbeleuchteten Straßen mit Parkleuchten ist nur innerhalb geschlossener Ortschaften ausreichend, da der Verkehr hier in aller Regel mit geringerer Geschwindigkeit fließt und das parkende Fahrzeug somit von anderen Fahrzeugführern rechtzeitig gesehen werden kann.","Außerhalb geschlossener Ortschaften ist die Kenntlichmachung eines parkenden PKW mit Parkleuchten unzureichend, da hiermit ein rechtzeitiges Erkennen nicht gewährleistet ist."],"rn":859},{"n":"2.2.17-109","t":"Wann müssen Sie auch am Tage mit Abblendlicht fahren?","p":4,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["- beschlagene Windschutzscheibe","- Nebel oder Schneefall","- Regen"],"co":[1,2],"ex":["Hier hilft das Abblendlicht nicht weiter. Du musst die Belüftung einschalten.","Du musst das Abblendlicht einschalten, wenn du durch Nebel und Schnee sichtbehindert bist.","Liegt eine Sichtbehinderung aufgrund von Regen vor, dann musst du das Abblendlicht einschalten."],"rn":860},{"n":"2.2.17-111","t":"In welchen Fällen müssen Sie bei Dämmerung oder Dunkelheit nur die Begrenzungsleuchten (Standlicht) einschalten?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Wenn das Fahrzeug außerhalb geschlossener Ortschaften auf dem Seitenstreifen geparkt wird","Beim Fahren auf Straßen mit durchgehender, ausreichender Beleuchtung"],"co":[0],"ex":["Parkst du außerhalb geschlossener Ortschaften auf dem Seitenstreifen, dann muss das Standlicht eingeschaltet sein.","Bei Dämmerung und Dunkelheit musst immer das Abblendlicht eingeschaltet sein, wenn das Auto fährt."],"rn":861},{"n":"2.2.17-114","t":"Wann müssen Sie Abblendlicht einschalten?","p":4,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Bei Dunkelheit","Beim Durchfahren eines Tunnels","Während der Dämmerung"],"co":[0,1,2],"ex":["Bei Dunkelheit musst du das Abblendlicht an haben.","Wenn ein Tunnel durchfahren wird, ist ein eingeschaltetes Abblendlicht notwendig.","In diesem Fall muss das Abblendlicht eingeschaltet sein."],"rn":862},{"n":"2.2.17-115","t":"Was kann eine falsche Einstellung der manuellen Leuchtweitenregelung zur Folge haben?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Die Lebensdauer des Leuchtmittels für das Abblendlicht kann sich verringern","Der Gegenverkehr kann durch mein Abblendlicht geblendet werden","Die Leuchtweite vor meinem Fahrzeug kann zu gering sein"],"co":[1,2],"ex":["Die Einstellung der manuellen Leuchtweitenregelung hat keine Auswirkung auf die Lebensdauer des Leuchtmittels.","Sind deine Lichter zu hoch eingestellt, blendest du damit den Gegenverkehr.","Sind deine Lichter zu tief eingestellt, leuchten sie nicht weit genug und deine Sichtweite verringert sich."],"rn":863},{"n":"2.2.17-116","t":"Welche Funktion soll der Fernlichtassistent bei Dunkelheit erfüllen?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["- reinigt die Scheinwerfer für das Fernlicht","- aktiviert bei geeigneten Umgebungsbedingungen das Fernlicht","- blendet das Fernlicht bei Gegenverkehr rechtzeitig ab"],"co":[1,2],"ex":["Ein Fernlichtassistent kann keine Scheinwerfer reinigen.","Der Fernlichtassistent erkennt, ob Gegenverkehr da ist oder jemand vor dir fährt, und aktiviert das Fernlicht bei passenden Bedingungen.","Der Fernlichtassistent soll den Gegenverkehr erkennen und das Fernlicht rechtzeitig abblenden."],"rn":864},{"n":"2.2.17-117","t":"In welcher Situation kann der Fernlichtassistent Ihres Kraftfahrzeugs bei Gegenverkehr möglicherweise nicht rechtzeitig abblenden?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Beim Überqueren einer Kuppe","Beim Durchfahren einer Kurve","Bei Blendung durch ein entgegenkommendes Fahrzeug"],"co":[0,1],"ex":["Beim Überqueren einer Kuppe kann die Kamera des Fernlichtassistenten den Gegenverkehr möglicherweise nicht rechtzeitig erkennen. Schalte das Fernlicht manuell aus, wenn du es bemerkst, um den Gegenverkehr nicht zu blenden und euch zu gefährden.","Weil die Kamera deines Fernlichtassistenten in Kurven Gegenverkehr später erkennt, kann er möglicherweise nicht rechtzeitig abblenden.","Der Fernlichtassistent kann nicht geblendet werden."],"rn":865},{"n":"2.2.17-118","t":"An Ihrem Pkw ist das automatische Lichtsystem aktiviert. Womit müssen Sie bei den dargestellten Lichtverhältnissen rechnen?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Das Abblendlicht schaltet sich nicht automatisch ein","Das automatische Lichtsystem schaltet die Nebelscheinwerfer ein","Ich werde von nachfolgenden Verkehrsteilnehmern erst spät gesehen"],"co":[0,2],"ex":["Das automatische Lichtsystem erkennt schlechte Lichtverhältnisse nie. Schalte das Abblendlicht manuell ein.","Das automatische Lichtsystem stellt nur das Abblendlicht an und aus.","Wegen der tief stehenden Sonne und der dunstigen Luft sind die Sichtverhältnisse schlecht. Schalte das Abblendlicht an, damit dich nachfolgende Verkehrsteilnehmer besser sehen können."],"i":["https://video2.kalaiwa.de/assets/2217118.webp"],"rn":866},{"n":"2.2.17-402","t":"Sie fahren bei Dunkelheit mit Fernlicht. Wann müssen Sie abblenden?","p":4,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Wenn ein Fahrzeug mit geringem Abstand vorausfährt","Wenn Personen in gleicher Richtung vorausgehen","Wenn ein Fahrzeug entgegenkommt"],"co":[0,2],"ex":["Sonst würdest du den Vorausfahrenden blenden.","In diesem Fall musst du nicht abblenden.","Du musst hier abblenden, da du sonst den Fahrer des entgegenkommenden Fahrzeugs blenden würdest."],"rn":867},{"n":"2.2.17-403","t":"Sie fahren bei Dunkelheit mit Fernlicht. Wann müssen Sie abblenden?","p":3,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Wenn Fußgänger in gleicher Richtung vorausgehen","Wenn ich eine Straße mit durchgehender, ausreichender Beleuchtung befahre","Wenn ich vor einem Bahnübergang warten muss und andere blende"],"co":[1,2],"ex":["Vorausgehende Fußgänger, die in die gleiche Richtung gehen, sind kein Grund abzublenden, da du ihnen den Weg ausleuchtest und sie nicht blendest.","Ist die Straße ausreichend beleuchtet, dann ist kein Fernlicht mehr notwendig. Blende hier ab.","Sobald du andere Verkehrsteilnehmer durch dein Fernlicht blenden würdest, musst du abblenden."],"rn":868},{"n":"2.2.17-404","t":"Warum müssen Sie auch am Tage mit Abblendlicht fahren, wenn die Sicht durch Nebel, Regen oder Schneefall erheblich behindert ist?","p":4,"c":"2.2.17","ch":"Beleuchtung","th":"Verhalten Im Strassenverkehr","o":["Um Verkehrszeichen in größerer Entfernung besser sehen zu können","Um mit erhöhter Geschwindigkeit fahren zu können","Um von anderen Verkehrsteilnehmern besser gesehen werden zu können"],"co":[2],"ex":["Bei guten Lichtverhältnissen hat das Abblendlicht keinen großen Effekt und hilft dir somit auch nicht, weit entfernte Verkehrszeichen besser sehen zu können.","Bei schlechten Sichtverhältnissen solltest du nicht mit erhöhter Geschwindigkeit fahren.","Bei schlechten Sichtverhältnissen musst du am auch Tage mit Abblendlicht fahren, damit dich andere Verkehrsteilnehmer besser sehen können, aber auch, damit du eine bessere Sicht hast."],"rn":869},{"n":"2.2.18-003","t":"Welche Richtgeschwindigkeit gilt für Pkws und Motorräder auf Autobahnen?","p":2,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","na":"130 km/h","e":"Dies ist die vorgeschriebene Richtgeschwindigkeit auf Autobahnen. Geben Verkehrszeichen Geschwindigkeitsbegrenzungen an, dann sind diese einzuhalten.","rn":870},{"n":"2.2.18-006","t":"Sie nähern sich auf dem linken von zwei Fahrstreifen einem Fahrzeug, das gerade zum Überholen ausschert. Wie verhalten Sie sich?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Dichter auffahren, hupen und blinken","Zum Vorausfahrenden ausreichenden Abstand einhalten","Den Vorausfahrenden überholen lassen"],"co":[1,2],"ex":["Das würde den anderen Fahrer irritieren und eine gefährliche Situation entstehen lassen. Fahre stattdessen vorausschauend und rücksichtsvoll.","Falls es die Situation erfordert, musst du verzögern, um einen ausreichenden Sicherheitsabstand einhalten zu können.","Danach kannst du überholen und dich bei Gelegenheit wieder rechts einordnen."],"rn":871},{"n":"2.2.18-007","t":"Sie fahren bei geringer Verkehrsdichte auf einer Autobahn. Wie lange dürfen Sie den linken Fahrstreifen benutzen?","p":3,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ständig, solange kein anderes Fahrzeug Sie überholen will","Solange Sie hinter einem Fahrzeug fahren, das auf dem linken Fahrstreifen überholt","Solange es nötig ist, um andere Fahrzeuge zu überholen"],"co":[1,2],"ex":["Die linke Spur dient ausschließlich dem Überholen. Die dauerhafte Nutzung ist nicht gestattet.","Du darfst so lange auf der linken Spur fahren, bis du den Überholvorgang beendet hast.","Es gilt das Rechtsfahrgebot. Du musst also, um andere Verkehrsteilnehmer nicht unnötig zu behindern, nach Abschluss eines Überholvorgangs wieder auf den rechten Fahrstreifen wechseln."],"rn":872},{"n":"2.2.18-009","t":"Was gilt auf Kraftfahrstraßen?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Wenden verboten","Bei Dunkelheit darf schneller gefahren werden, als es die Reichweite des Abblendlichts zulässt","Einfahren nur an Kreuzungen und Einmündungen"],"co":[0,2],"ex":["Auf Kraftfahrstraßen ist sowohl das Wenden, als auch das Halten verboten.","Auch auf Kraftfahrstraßen darf bei Dunkelheit nicht schneller gefahren werden, als es die Reichweite des Abblendlichts zulässt.","Auf Kraftfahrstraßen darf nur an Kreuzungen oder Einmündungen eingefahren werden."],"rn":873},{"n":"2.2.18-011","t":"Auf einer Autobahn mit 3 Fahrstreifen hat sich ein Stau gebildet. Wo ist die Gasse für Rettungsfahrzeuge zu bilden?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Zwischen dem mittleren und dem rechten Fahrstreifen","Auf dem Seitenstreifen","Zwischen dem linken und dem mittleren Fahrstreifen"],"co":[2],"ex":["Die Gasse muss zwischen linkem und mittlerem Fahrstreifen gebildet werden.","Dieser muss jedoch freigehalten werden.","Hier muss eine freie Gasse gebildet werden."],"rn":874},{"n":"2.2.18-013","t":"Wie müssen Sie sich jetzt verhalten?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["- in der Mitte","- weit nach links","- weit nach rechts"],"co":[2],"ex":["Du musst möglichst weit zur rechten Seite fahren.","Wenn du möglichst weit nach links fährst, behinderst du den Rettungswagen an der Durchfahrt.","Die Fahrzeuge der linken und mittleren Spur müssen eine Rettungsgasse bilden, damit der Rettungswagen schnellstmöglich an den Unfallort gelangen kann."],"v":["https://video2.kalaiwa.de/assets/2218013v1440.mp4"],"rn":875},{"n":"2.2.18-014","t":"Wie sollten Sie sich verhalten?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich fahre weiter","Ich ordne mich auf der Standspur (Seitenstreifen) ein","Ich halte auf meinem Fahrstreifen und warte auf eine Lücke"],"co":[0],"ex":["Du darfst dich nicht auf dem Standstreifen einordnen, um eine Ausfahrt zu nehmen. Wähle die nächste Möglichkeit, von der Autobahn abzufahren.","Fahre weiter und bei der nächsten Möglichkeit von der Autobahn ab.","Das wäre sehr gefährlich. Fahre bei der nächsten Ausfahrt von der Autobahn ab."],"v":["https://video4.kalaiwa.de/assets/2218014v1440.mp4"],"rn":876},{"n":"2.2.18-019","t":"Wie müssen Sie sich in einem Stau auf Autobahnen und auf Kraftfahrstraßen mit zwei Fahrstreifen für eine Richtung verhalten?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["- rechten Fahrstreifen möglichst weit links fahren","- linken Fahrstreifen möglichst weit links fahren","- rechten Fahrstreifen möglichst weit rechts fahren"],"co":[1,2],"ex":["Du musst auf dem rechten Fahrstreifen möglichst weit rechts fahren.","Auf dem linken Fahrstreifen muss möglichst weit links, auf dem rechten Fahrstreifen möglichst weit rechts gefahren werden.","So kann eine Gasse gebildet werden, durch die Rettungskräfte schnell an den Unfallort gelangen können."],"rn":877},{"n":"2.2.18-022","t":"Sie möchten die Autobahn an der nächsten Ausfahrt verlassen. Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich beginne jetzt, rechts zu blinken","Ich beobachte den nachfolgenden Verkehr","Ich bremse ab jetzt gleichmäßig auf 60 km/h ab"],"co":[0,1],"ex":["Beim Verlassen der Autobahn solltest du spätestens 200 m vor der Ausfahrt den Blinker setzen.","Beobachte bei Autobahnfahrten immer aufmerksam den nachfolgenden Verkehr. Achte besonders beim Abbiegen darauf, dass dich niemand rechts auf der Abbiegespur überholt.","Bremse erst ab, wenn du auf dem Verzögerungsstreifen der Ausfahrt bist."],"v":["https://video4.kalaiwa.de/assets/2218022v1440.mp4"],"rn":878},{"n":"2.2.18-101","t":"Ihr Fahrzeug ist auf der Autobahn liegen geblieben. Was ist beim Abschleppen zu beachten?","p":3,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Während des Abschleppens haben beide Fahrzeuge Warnblinklicht einzuschalten","Die Autobahn darf bis zu der Ausfahrt befahren werden, die einer geeigneten Werkstatt am nächsten liegt","Die Autobahn muss bei der nächsten Ausfahrt verlassen werden"],"co":[0,2],"ex":["Fahrzeuge die abgeschleppt werden und solche die abschleppen müssen beide das Warnblinklicht einschalten.","Die Autobahn muss bei der nächsten Ausfahrt verlassen werden.","Sonst würde der fließende Verkehr nur zunehmend behindert werden."],"rn":879},{"n":"2.2.18-103","t":"Sie fahren auf der Autobahn und haben die Ausfahrt verpasst. Wie verhalten Sie sich richtig?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich halte auf dem Seitenstreifen, um die weitere Fahrtstrecke zu planen","Ich fahre auf dem Seitenstreifen zurück, wenn die Ausfahrt weniger als 100 m entfernt ist","Ich fahre weiter und verlasse die Autobahn an einer der nächsten Ausfahrten"],"co":[2],"ex":["Auf Autobahnen ist das Halten auch auf dem Seitenstreifen verboten.","Das ist verboten.","Das ist in diesem Fall die korrekte Verhaltensweise."],"rn":880},{"n":"2.2.18-105","t":"Was ist bei der Benutzung von Autobahnen verboten?","p":3,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Das Halten auf dem Seitenstreifen","Das Wenden","Das Rückwärtsfahren"],"co":[0,1,2],"ex":["Das Halten und Parken auf Autobahnen ist verboten und kann zu schweren Unfällen führen.","Auf Autobahnen darf nicht gewendet werden.","Das Rückwärtsfahren ist auf Autobahnen strengstens untersagt."],"rn":881},{"n":"2.2.18-215","t":"Warum sollte bei Autobahnfahrten der Verkehrsfunk eingeschaltet sein?","p":3,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["- über Staus informiert","- bei Autobahnfahrten vorgeschrieben ist","- vor Geisterfahrern warnt"],"co":[0,2],"ex":["Diesen kann man im Bedarfsfall so frühzeitig ausweichen.","Dies ist nicht der Fall.","So ist man vorgewarnt und kann im Notfall schneller reagieren."],"rn":882},{"n":"2.2.18-015-M","t":"Wie müssen Sie sich verhalten, wenn sich auf dieser Straße ein Stau bildet?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["- möglichst weit links","- weiterhin in der Mitte","- möglichst weit rechts"],"co":[0],"ex":["Zwischen den Spuren muss nämlich im Falle eines Unfalls ein Rettungswagen durchfahren können. Halte dich daher möglichst weit links.","So würdest du einen Rettungswagen an der Durchfahrt zum Unfallort hindern.","Du solltest möglichst weit links fahren, um eine Rettungsgasse zu bilden."],"i":["https://video2.kalaiwa.de/assets/2218015m.webp"],"rn":883},{"n":"2.2.18-016-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich fahre möglichst weit rechts","Ich warne den Fahrer mit Schall- und Leuchtzeichen","Ich verständige die Polizei"],"co":[0,1,2],"ex":["So schützt du dich selbst, falls der Fahrer nicht reagieren kann oder will.","Mach ihn mit allen dir möglichen Mitteln darauf aufmerksam, dass sich der Fahrer auf der falschen Spur befindet.","Diese kann hier schnellstmöglich eingreifen und den Verkehrsfunk verständigen, um so Warnungen im Radio melden zu können."],"v":["https://video4.kalaiwa.de/assets/2218016mv1440.mp4"],"rn":884},{"n":"2.2.18-017-M","t":"Wie sollten Sie sich jetzt verhalten?","p":3,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich verzögere und fädele zwischen dem roten Pkw und dem Lkw ein","Ich verzögere und fädele nach dem gelben Fahrzeug ein","Ich beschleunige und fädele vor dem Lkw ein"],"co":[2],"ex":["Vor dem LKW ist ausreichend Platz. Daher solltest du beschleunigen und dich hier einfädeln.","Zwischen dem gelben Fahrzeug und dem danach Folgenden ist sehr wenig Abstand. Du müsstest hierfür zunächst abbremsen und müsstest dann den fließenden Verkehr behindern. Beschleunige und ordne dich vor dem LKW ein.","So kommst du noch rechtzeitig vom Einfädelungsstreifen auf die Autobahn, ohne abbremsen zu müssen oder jemanden zu behindern."],"v":["https://video2.kalaiwa.de/assets/2218017mv1440.mp4"],"rn":885},{"n":"2.2.18-018-M","t":"Sie möchten die Autobahn verlassen. Wie verhalten Sie sich in dieser Situation richtig?","p":3,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich fahre auf dem Seitenstreifen weiter","Ich wechsle auf den linken Fahrstreifen","Ich beachte entgegenkommende Fahrzeuge"],"co":[1],"ex":["Da hier vermutlich eine Baustelle oder ein anderes Hindernis ist, musst du dich links einordnen und bei der nächsten Gelegenheit von der Autobahn abfahren.","Wechsle hier, wie vorgegeben, auf den linken Fahrstreifen und fahre bei der nächsten Gelegenheit von der Autobahn ab.","Auf deiner Fahrspur kommen keine Fahrzeuge entgegen. Deswegen musst du hier auch nicht darauf achten."],"i":["https://video2.kalaiwa.de/assets/2218018m.webp"],"rn":886},{"n":"2.2.18-021-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich bleibe auf dem mittleren Fahrstreifen","Ich wechsle auf den rechten Fahrstreifen","Ich wechsle auf den linken Fahrstreifen"],"co":[0],"ex":["Du kannst momentan weder auf den linken noch auf den rechten Fahrstreifen wechseln, da du in beiden Fällen Fahrzeuge behindern würdest. Du musst also auf dem mittleren Fahrstreifen bleiben.","Auf dem rechten Fahrstreifen befindet sich ein Motorrad, welches du behindern würdest. Dieses ist gerade auf der Autobahnauffahrt auf die Autobahn gefahren.","Auf dem linken Fahrstreifen fährt der Pkw, der dich gerade überholt hat. Du kannst also nicht nach links fahren."],"v":["https://video2.kalaiwa.de/assets/2218021mv1440.mp4"],"rn":887},{"n":"2.2.18-023-M","t":"Wie sollten Sie sich jetzt verhalten?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["Ich beschleunige","Ich wechsle auf den mittleren Fahrstreifen","Ich verringere meine Geschwindigkeit"],"co":[2],"ex":["Wenn du jetzt beschleunigst, kann der blaue Pkw nicht einfädeln. Im schlimmsten Fall verursachst du einen Unfall.","Du darfst nicht auf den mittleren Fahrstreifen wechseln, weil links von dir ein Fahrzeug fährt.","Verringere deine Geschwindigkeit und ermögliche dem blauen Pkw, auf die Autobahn aufzufahren und dabei ausreichend Sicherheitsabstand einzuhalten."],"v":["https://video2.kalaiwa.de/assets/2218023mv1440.mp4"],"rn":888},{"n":"2.2.18-024-M","t":"Womit müssen Sie jetzt rechnen?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["- beschleunigen","- abbremsen","- auf dem mittleren Fahrstreifen bleiben"],"co":[1,2],"ex":["Du Lkw auf deiner Spur wird voraussichtlich nicht beschleunigen. Der linke Lkw hat bereits seine Warnblinkanlage eingeschaltet und signalisiert dadurch eine Gefahrensituation, bei der alle Fahrzeuge bereits abbremsen.","Du musst mit einem Abbremsen des Lkw vor dir rechnen, da der andere Lkw auf der rechten Spur bereits langsamer wird und sein Warnblinklicht angeschaltet hat. Dieses signalisiert dir, dass ein mögliches Stauende vor dir liegen könnte.","Der Lkw wird voraussichtlich auf dem mittleren Fahrstreifen bleiben, da er auf der rechten Spur zu wenig Platz zum Einordnen hat."],"v":["https://video4.kalaiwa.de/assets/2218024mv1440.mp4"],"rn":889},{"n":"2.2.18-104-M","t":"Wie kann ein Spurwechsel-Assistent ohne Lenkeingriff Sie in dieser Situation unterstützen?","p":4,"c":"2.2.18","ch":"Autobahnen Und Kraftfahrstrassen","th":"Verhalten Im Strassenverkehr","o":["- warnt vor einer Kollision mit einem Fahrzeug auf dem mittleren Fahrstreifen","- führt selbstständig einen Spurwechsel durch","- bremst mein Fahrzeug ab"],"co":[0],"ex":["Der Spurwechsel-Assistent erkennt das Fahrzeug auf dem mittleren Fahrstreifen als Gefahr und warnt dich davor, auf diese Spur zu wechseln.","Um selbstständig einen Spurwechsel durchzuführen, würde es einen Lenkeingriff erfordern.","Der Spurwechsel-Assistent greift nicht in deine Geschwindigkeit ein."],"i":["https://video4.kalaiwa.de/assets/2218104m.webp"],"rn":890},{"n":"2.2.21-007","t":"Warum ist es gefährlich, wenn Personen auf den hinteren Sitzen die Sicherheitsgurte nicht benutzen?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["- kann es zur Gefährdung der Personen auf den vorderen Sitzen kommen","- kann es schon bei niedrigen Geschwindigkeiten zu Verletzungen kommen","- können diese Personen aus dem Fahrzeug geschleudert werden"],"co":[0,1,2],"ex":["Das ist ein Grund, weshalb du auch auf dem hinteren Sitz immer den Sicherheitsgurt benutzen musst.","Das ist eine mögliche Gefahr und ein Grund, warum alle Autoinsassen während der Fahrt immer angeschnallt sein müssen.","Daher muss man auch auf den hinteren Sitzen während der Fahrt durchgehend den Sicherheitsgurt benutzen."],"rn":891},{"n":"2.2.21-105","t":"Wie dürfen Sie in Ihrem Pkw ein fünfjähriges Kind mitnehmen?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Auf der hinteren Sitzbank mit angelegtem Beckengurt","In einem für das Kind geeigneten Kindersitz mit Prüfzeichen","Auf einem hinteren Sitz mit serienmäßigem Dreipunktgurt"],"co":[1],"ex":["Die Sicherung eines Kindes mit Beckengurt ist generell nicht gestattet.","So darf ein fünfjähriges Kind im PKW transportiert werden.","Das ist hier nicht gestattet."],"rn":892},{"n":"2.2.21-111","t":"Ab welcher Aufprallgeschwindigkeit müssen Sie mit schweren oder tödlichen Verletzungen rechnen, wenn Sie keinen Sicherheitsgurt angelegt haben?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Ab 80 km/h","Ab 30 km/h","Ab 50 km/h"],"co":[1],"ex":["Schon ab 30 km/h kann ein Aufprall ohne Sicherheitsgurt zu schweren Verletzungen führen.","Bereits bei einer Geschwindigkeit von 30 km/h kann ein Aufprall zu schweren bis tödlichen Verletzungen führen, wenn man keinen Sicherheitsgurt trägt.","Wenn man keinen Sicherheitsgurt trägt, kann ein Aufprall bereits bei 30 km/h sehr gefährlich werden."],"rn":893},{"n":"2.2.21-112","t":"Ein Pkw ist mit zwei Frontairbags ausgerüstet. Auf welchen Sitzplätzen müssen Sicherheitsgurte angelegt werden?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Nur auf den Vordersitzen","Nicht auf den Vordersitzen","Auf allen Sitzen"],"co":[2],"ex":["Auch wenn das Fahrzeug mit Airbags ausgestattet ist, besteht die Anschnallpflicht auf allen Sitzen im Fahrzeug.","Auf allen Sitzen müssen Insassen einen Sicherheitsgurt anlegen.","Ein Airbag entbindet nicht von der Anschnallpflicht im Fahrzeug. Er bietet nur einen zusätzlichen Schutz."],"rn":894},{"n":"2.2.21-114","t":"Sie wollen nach einem Kindergeburtstag mehrere kleine Kinder nach Hause bringen. Was ist bei der Beförderung in Ihrem Pkw zu beachten?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Die Kinder sind mit den vorgeschriebenen Rückhalteeinrichtungen zu sichern","Das Anschnallen der Kinder mit den vorhandenen Sicherheitsgurten reicht aus","Rückhalteeinrichtungen für Kinder brauchen innerhalb geschlossener Ortschaften nicht benutzt zu werden"],"co":[0],"ex":["Nur dann dürfen sie im Fahrzeug transportiert werden.","Dies ist nicht ausreichend.","Rückhalteeinrichtungen müssen beim Transport von Kindern auch innerhalb geschlossener Ortschaften genutzt werden."],"rn":895},{"n":"2.2.21-118","t":"Während der Fahrt leuchtet die Airbag-Kontrollleuchte ständig. Was müssen Sie tun?","p":3,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Nichts, weil das ein Signal für die Werkstatt ist","Das Fahrzeug sofort aus dem Straßenverkehr entfernen","Eine Werkstatt aufsuchen"],"co":[2],"ex":["Das Signal weist darauf hin, dass etwas mit dem Airbag nicht stimmt. Daher solltest du möglichst schnell eine Werkstatt aufsuchen, um die Störung beheben zu lassen.","Die Airbagkontrollleuchte signalisiert eine Störung. Du kannst hiermit jedoch noch bis zur nächsten Werkstatt fahren und musst dein Fahrzeug nicht sofort aus dem Straßenverkehr entfernen.","Du musst eine Werkstatt aufsuchen, um die Störung zu beseitigen. Hier liegt eine Störung vor und der Airbag könnte ohne ersichtlichen Grund aufgehen."],"rn":896},{"n":"2.2.21-121","t":"Wie können Sie verhindern, dass ein Kind während der Fahrt eine hintere Tür öffnet?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["- die Kindersicherung der hinteren Türen","- die Zentralverriegelung"],"co":[0],"ex":["So ist es nicht möglich, von innen die Türe zu öffnen.","Dann ist das Fahrzeug nur von außen nicht zu öffnen."],"rn":897},{"n":"2.2.21-122","t":"Sie möchten in Ihrem Pkw ein Kind mitnehmen. Wann müssen Sie hierzu einen Kindersitz verwenden?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Wenn das Kind älter als 12 Jahre und größer als 150 cm ist","Wenn das Kind älter als 12 Jahre und kleiner als 150 cm ist","Wenn das Kind jünger als 12 Jahre und kleiner als 150 cm ist"],"co":[2],"ex":["Hier muss kein Kindersitz verwendet werden.","Hier muss kein Kindersitz verwendet werden.","Kinder unter 12 Jahren, die kleiner als 150 cm sind, müssen im Pkw auf einem Kindersitz sitzen."],"rn":898},{"n":"2.2.21-123","t":"Sie möchten auf dem Beifahrersitz ein Baby mitnehmen. Was müssen Sie bei der Verwendung einer Baby-Trageschale beachten?","p":4,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Das Baby muss in der Baby-Trageschale angeschnallt sein","Die Baby-Trageschale muss entgegen der Fahrtrichtung angebracht sein","Ein vorhandener Beifahrer-Airbag muss deaktiviert sein"],"co":[0,1,2],"ex":["Das Baby könnte sonst aus der Baby-Trageschale fallen oder geschleudert werden.","Nur so kann die Baby-Trageschale seine Schutzfunktion erfüllen.","Das Baby könnte schwer verletzt werden, wenn der Airbag auslöst."],"rn":899},{"n":"2.2.21-124","t":"Was ist bei der Benutzung eines Sicherheitsgurts zu beachten?","p":3,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Ein beschädigter Sicherheitsgurt muss ausgetauscht werden","Der Sicherheitsgurt sollte nach dem Anlegen straff gezogen werden","Der Sicherheitsgurt sollte nicht verdreht sein"],"co":[0,1,2],"ex":["Beschädigte Sicherheitsgurte müssen sofort ersetzt werden, weil sonst Leib und Leben gefährdet würde.","Der Sicherheitsgurt sollte straff am Körper sitzen, um im Notfall zu verhindern, dass du nach vorne geschleudert wirst.","Ein verdrehter Sicherheitsgurt kann die Schutzwirkung im Fall eines Unfalls beeinträchtigen."],"rn":900},{"n":"2.2.21-125","t":"Was schränkt die Funktion eines Dreipunkt-Sicherheitsgurts ein?","p":3,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Das Tragen einer dicken Winterjacke","Das Durchführen des Gurts unter beide Arme","Das unvollständige Einrasten des Gurts im Gurtschloss"],"co":[0,1,2],"ex":["Das Tragen einer dicken Winterjacke kann die Funktion des Sicherheitsgurtes beeinträchtigen, da zwischen Körper und Sicherheitsgurt viel Luft ist. Fahre deshalb eher mit einer dünneren Jacke oder einem Pulli, falls möglich.","Das Durchführen des Gurts unter beide Arme kann zu Verletzungen führen. Um die maximale Schutzwirkung des Sicherheitsgurtes sicherzustellen, muss dieser über die Schulter und Hüfte des Insassen verlaufen.","Wenn der Sicherheitsgurt nicht ins Gurtschloss eingerastet ist, hat er keinerlei Schutzwirkung. Ein unvollständiges Einrasten ist sehr gefährlich und deshalb zu unterlassen."],"rn":901},{"n":"2.2.21-126","t":"Was sollten Sie vor Fahrtantritt prüfen?","p":3,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["- jede mitfahrende Person den Sicherheitsgurt angelegt hat","- ich die Zulassungsbescheinigung Teil II mitführe","- ich eine ausreichende Verkehrsbeobachtung sicherstellen kann"],"co":[0,2],"ex":["Achte darauf, dass jede mitfahrende Person den Sicherheitsgurt angelegt hat. Als Fahrer bist du für deren Sicherheit verantwortlich.","Die Zulassungsbescheinigung Teil II musst und darfst du gar nicht mitführen. Sie ist der Fahrzeugbrief und wird nur bei einem Autokauf oder Verkauf, oder der Ummeldung benötigt.","Versichere dich, dass du den Verkehr um dich herum ausreichend beobachten kannst. Verstellte oder kaputte Seiten- oder Rückspiegel, dreckige Scheiben oder Kofferraumbeladung könnten unter anderem dein Sichtfeld einschränken."],"rn":902},{"n":"2.2.21-127","t":"Was ist hinsichtlich der gewünschten Schutzwirkung von Airbags zu beachten?","p":3,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Der Entfaltungsraum von Airbags darf nicht beeinträchtigt sein","Airbags können ihre volle Funktion nur bei richtiger Sitzposition der mitfahrenden Personen erzielen","Airbags können bei Fahrten in der Stadt den Sicherheitsgurt ersetzen"],"co":[0,1],"ex":["Achte darauf, dass keine Gegenstände oder Hindernisse die Entfaltung der Airbags behindern.","Die gewünschte Schutzwirkung von Airbags ist nur dann gewährleistet, wenn die mitfahrenden Personen aufrecht und mit dem Rücken an der Rückenlehne sitzen.","Airbags ergänzen die Sicherheitswirkung von Sicherheitsgurten, sie ersetzen diese jedoch nicht."],"rn":903},{"n":"2.2.21-128","t":"Sie möchten in einem Kraftfahrzeug eine Person befördern, die während der Fahrt im Rollstuhl sitzen bleiben muss. Was müssen Sie beachten?","p":3,"c":"2.2.21","ch":"Personenbefoerderung","th":"Verhalten Im Strassenverkehr","o":["Der Rollstuhl muss mit einem Rollstuhl-Rückhaltesystem gesichert sein","Die Person muss mit einem Rollstuhlnutzer-Rückhaltesystem gesichert sein","Das Kraftfahrzeug muss mit einem Rollstuhlstellplatz ausgerüstet sein"],"co":[0,1,2],"ex":["Ein Rollstuhl-Rückhaltesystem sichert den Rollstuhl und verhindert, dass er sich während der Fahrt bewegt.","Um Personen im Rollstuhl sicher zu befördern, müssen diese mit einem Rollstuhlnutzer-Rückhaltesystem gesichert sein. Dieses System verhindert, dass der Rollstuhlfahrer aus dem Rollstuhl fallen kann.","Im Fahrzeug muss es einen Rollstuhlstellplatz geben. Personen, die während der Fahrt im Rollstuhl sitzen müssen, dürfen nicht einfach auf der Ladefläche befördert werden."],"rn":904},{"n":"2.2.22-104","t":"Was müssen Sie tun, wenn Sie auf dem Dach Ihres Pkws Fahrräder mitnehmen?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Befestigung regelmäßig kontrollieren","Haltevorrichtung und Fahrräder sicher befestigen","Hohe Geschwindigkeiten vermeiden"],"co":[0,1,2],"ex":["Du bist verpflichtet, regelmäßig die sichere Befestigung zu kontrollieren.","Du bist verpflichtet, Fahrräder und andere Gegenstände gegen Verrutschen und Herabfallen (auch bei einer Vollbremsung) zu sichern.","Das Fahr- und Bremsverhalten eines Fahrzeugs ändert sich durch die Ladung auf dem Dach. Deshalb sind hohe Geschwindigkeiten zu vermeiden."],"rn":905},{"n":"2.2.22-105","t":"Was ist beim Transport von Fahrrädern auf einem Hecktragesystem zu prüfen?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Ob Beleuchtungseinrichtungen oder das Kennzeichen verdeckt werden","Ob das System und die Fahrräder sicher befestigt sind","Ob das System nach Herstellerangaben für das Fahrzeug geeignet ist"],"co":[0,1,2],"ex":["Wenn Beleuchtung oder Kennzeichen verdeckt werden, darf dieses Hecktragesystem nicht verwendet werden.","Als Fahrer ist man für eine sichere Befestigung der Ladung verantwortlich. Ein Fahrrad und das Fahrrad-Tragesystem sind in diesem Fall Ladung und Ladeeinrichtung.","Nur dann darf das Hecktragesystem zum Transport von Fahrrädern genutzt werden."],"rn":906},{"n":"2.2.22-108","t":"Wie ist eine Ladung bei Dunkelheit oder schlechter Sicht kenntlich zu machen, wenn sie seitlich mehr als 40 cm über die Begrenzungsleuchten des Fahrzeugs hinausragt?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Nach hinten durch rotes Licht","Nach vorn durch weißes Licht","Durch Einschalten der Warnblinkanlage"],"co":[0,1],"ex":["Wenn die Ladung mehr als 40 cm über die „normalen“ Beleuchtungseinrichtungen hinausragt und nicht kenntlich gemacht wird, so ist sie sowohl für den Gegenverkehr als auch für nachfolgende Fahrzeuge, die einen Überholvorgang durchführen, eine Gefahr, weil die tatsächliche Fahrzeugbreite nicht zu erkennen ist. Deshalb muss die Ladung nach hinten mit rotem Licht gekennzeichnet werden.","Wenn die Ladung mehr als 40 cm über die „normalen“ Beleuchtungseinrichtungen hinausragt und nicht kenntlich gemacht wird, so ist sie sowohl für den Gegenverkehr als auch für nachfolgende Fahrzeuge, die einen Überholvorgang durchführen eine Gefahr, weil die tatsächliche Fahrzeugbreite nicht zu erkennen ist. Deshalb muss die Ladung nach vorne mit weißem Licht gekennzeichnet werden.","Das Einschalten der Warnblinkanlage ist zwar ein Warnhinweis für andere Verkehrsteilnehmer, die Breite der Ladung kann hierdurch jedoch nicht erkannt werden."],"rn":907},{"n":"2.2.22-109","t":"Wie hoch darf eine rote Leuchte, die eine nach hinten hinausragende Ladung kennzeichnet, höchstens über der Fahrbahn angebracht sein?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["2,00 m","2,50 m","1,50 m"],"co":[2],"ex":["Die rote Leuchte muss mindestens 1,50 m über der Fahrbahn angebracht sein. Bei einer Höhe von 2,00 m wäre nicht mehr gewährleistet, dass sich diese im Blickfeld anderer Verkehrsteilnehmer befindet.","2,50 m ist zu hoch. Die Leuchte muss im Blickfeld der folgenden Fahrzeuge sein und darf daher höchstens 1,50 m über der Fahrbahn befestigt sein.","Die rote Leuchte darf maximal 1,50 m über der Fahrbahn angebracht sein. Bei einer höheren Befestigung wäre sie möglicherweise nicht mehr im Blickfeld herannahender Fahrzeugführer."],"rn":908},{"n":"2.2.22-111","t":"Bis zu welcher Höhe darf die Ladung nicht nach vorn über das Fahrzeug hinausragen?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","na":"2,5 m","e":"Ladung darf bis zu einer Höhe von 2,5 m nicht nach vorne über das Fahrzeug hinausragen. Erst darüber ist ein Herausstehen der Ladung von bis zu 50 cm nach vorne gestattet.","rn":909},{"n":"2.2.22-117","t":"Was ist bei der Beladung von Fahrzeugen zu beachten?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Ladung mit hohem Gewicht muss nicht gesichert werden","Ladung darf oberhalb einer Höhe von 2,50 m maximal 50 cm nach vorn hinausragen","Ladung, die mehr als 1 m über die Rückstrahler nach hinten hinausragt, muss gekennzeichnet werden"],"co":[1,2],"ex":["Ladung mit hohem Gewicht muss besonders gut gesichert werden.","Laut StVO § 22 Abs. 3 gilt: \"Die Ladung darf bis zu einer Höhe von 2,50 m nicht nach vorn über das Fahrzeug, bei Zügen über das ziehende Fahrzeug hinausragen. Im Übrigen darf der Ladungsüberstand nach vorn bis zu 50 cm über das Fahrzeug, bei Zügen bis zu 50 cm über das ziehende Fahrzeug betragen.\"","Laut StVO § 22 Abs. 4 gilt: \"(...) Ragt das äußerste Ende der Ladung mehr als 1 m über die Rückstrahler des Fahrzeugs nach hinten hinaus, so ist es kenntlich zu machen (...).\""],"rn":910},{"n":"2.2.22-122","t":"Was haben Sie zu beachten, wenn Sie Ladung transportieren möchten?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["- darf in Form einzelner Stangen seitlich hinausragen","- muss gesichert sein","- darf keinen vermeidbaren Lärm verursachen"],"co":[1,2],"ex":["Die Ladung darf nicht in Form einzelner Stangen seitlich hinausragen.","Nur dann darfst du Ladung transportieren.","Das muss beim Transport von Ladung gewährleistet sein."],"rn":911},{"n":"2.2.22-123","t":"Sie möchten Urlaubsgepäck auf dem Dach Ihres voll besetzten Pkws mitnehmen. Was müssen Sie beachten?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Die Angabe zur Dachlast in der Zulassungsbescheinigung Teil I","Die zulässige Gesamtmasse meines Pkws","Die Angabe des Fahrzeugherstellers zur Dachlast in der Betriebsanleitung"],"co":[1,2],"ex":["Die Angaben zur Dachlast findest du in der Betriebsanleitung des Fahrzeugherstellers.","Diese darf nicht überschritten werden.","Du musst dich nach der Betriebsanleitung des Fahrzeugherstellers richten und darfst nach dieser dein Dach beladen."],"rn":912},{"n":"2.2.22-124","t":"Sie möchten Ladung transportieren. Was müssen Sie dabei beachten?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Ich darf beim Fahren nicht durch die Ladung behindert werden","Die Verkehrssicherheit des Fahrzeugs darf nicht beeinträchtigt werden","Die Ladung darf während der Fahrt nicht verrutschen oder umfallen"],"co":[0,1,2],"ex":["Der Fahrerraum sollte frei bleiben, sodass deine Sicht nicht blockiert und deine zum Fahren nötigen Tätigkeiten nicht eingeschränkt sind.","Die Ladung darf die Verkehrssicherheit deines Fahrzeugs nicht beeinträchtigen. Das sind zum Beispiel verdeckte Leuchten, nicht markierte überstehende Ladung, Überschreitung des maximal erlaubten Überstandes der Ladung usw..","Die Ladung muss gesichert werden, beispielsweise mit Spanngurten oder Netzen, um während der Fahrt nicht zu verrutschen oder umzufallen."],"rn":913},{"n":"2.2.22-125","t":"Was sind Ladungssicherungsmittel zur Verwendung im Pkw?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Zurrgurte","Unterlegkeile","Sicherungsnetze"],"co":[0,2],"ex":["Mit Zurrgurten bzw. Spanngurten kann Ladung im Pkw gesichert werden.","Durch Unterlegkeile kann Ladung im Pkw nicht sicher befestigt werden.","Verschiedene Sicherungsnetze können Ladung im Pkw zuverlässig sichern."],"rn":914},{"n":"2.2.22-126","t":"Sie möchten Ladung auf dem Dach Ihres Pkws transportieren. Welchen Einfluss hat dies auf das Fahrverhalten Ihres Pkws?","p":2,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Das Beschleunigungsvermögen nimmt ab","Der Bremsweg verlängert sich","Die Seitenwindempfindlichkeit nimmt ab"],"co":[0,1],"ex":["Durch die zusätzliche Last und die vergrößerte Angriffsfläche der Luft wird Ihr Pkw eine merklich geringere Beschleunigung aufweisen.","Durch das aufgrund der Ladung höhere Gewicht des Pkws, verlängert sich der Bremsweg.","Die Seitenwindempfindlichkeit nimmt aufgrund der vergrößerten Angriffsfläche der Luft zu."],"rn":915},{"n":"2.2.22-127","t":"Welche Möglichkeit der Ladungssicherung gibt es in einem Pkw?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["Den Spanngurt","Die Anti-Rutschmatte","Das Gepäcknetz"],"co":[0,1,2],"ex":["Einen Spanngurt darf man verwenden.","Eine Anti-Rutschmatte darf man verwenden.","Ein Gepäcknetz darf man verwenden."],"rn":916},{"n":"2.2.22-128","t":"Was sollten Sie bei der Beladung eines Kofferraums mit Gepäck beachten?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["- das Gepäck gegen Verrutschen sichern","- das Warndreieck leicht zugänglich verstauen","- schweres Gepäck weit unten verstauen"],"co":[0,1,2],"ex":["Ladung darf weder verrutschen, umfallen, herumrollen, herabfallen oder vermeidbaren Lärm erzeugen.","Du musst immer schnell an dein Warndreieck gelangen können.","Das wirkt sich positiv auf das Fahrverhalten aus, weil so der Schwerpunkt des Fahrzeugs niedrig bleibt."],"rn":917},{"n":"2.2.22-129","t":"Wie weit darf eine gekennzeichnete Ladung nach hinten über Ihr Fahrzeug hinausragen, wenn Ihre Wegstrecke mehr als 100 km beträgt?","p":2,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","na":"Antwort: Bis zu 1,5 m","e":"Legst du auf deiner Strecke mehr als 100 km zurück, dann darf deine Ladung maximal 1,5 Meter hinten über dein Fahrzeug hinausragen. Die Überlänge muss gekennzeichnet werden.","rn":918},{"n":"2.2.22-130","t":"Worauf sollten Sie sich einstellen, wenn Sie auf dem Dach Ihres Pkws Ladung befördern?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["- sich in Kurven stärker zur Seite neigen","- empfindlicher gegenüber Seitenwind reagieren","- einen erhöhten Kraftstoffverbrauch haben"],"co":[0,1,2],"ex":["Der Schwerpunkt des Pkw verlagert sich durch die Ladung nach oben. Das führt dazu, dass sich das Fahrzeug in Kurven stärker zur Seite neigt.","Durch die Ladung trifft der Wind auf eine größere Fläche, weshalb der Pkw möglicherweise empfindlicher auf Seitenwind reagiert.","Ein höheres Gewicht und eine größere Stirnfläche führen zu einem erhöhten Luftwiderstand, was wiederum zu einem höheren Kraftstoffverbrauch führt."],"rn":919},{"n":"2.2.22-131","t":"Sie transportieren mit einem Kleintransporter Möbel. Während einer Pause stellen Sie fest, dass ein Zurrgurt stark beschädigt ist. Unter welcher Bedingung dürfen Sie weiterfahren?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["- den Zurrgurt ausgetauscht habe","- mit maximal 50 km/h weiterfahre","- andere geeignete Ladungssicherungsmittel nutze"],"co":[0,2],"ex":["Stelle sicher, dass alle Möbel im Transporter gesichert sind, bevor du weiterfährst. Tausche den Zurrgurt aus oder sichere die Möbel mit anderen geeigneten Ladungssicherungsmitteln.","Solange deine Ladung nicht ordnungsgemäß gesichert ist, darfst du nicht weiterfahren.","Anstatt den Zurrgurt auszutauschen, kannst du auch andere geeignete Ladungssicherheitsmittel benutzen, um die Ladung zu sichern."],"rn":920},{"n":"2.2.22-132","t":"Was ist beim Transport von Pedelecs auf einem Hecktragesystem für die Anhängekupplung zu beachten?","p":3,"c":"2.2.22","ch":"Ladung","th":"Verhalten Im Strassenverkehr","o":["- die Stützlast der Anhängekupplung geeignet sein","- das Hecktragesystem geeignet sein","- der Reifenfülldruck des Pkws entsprechend angepasst werden"],"co":[0,1,2],"ex":["Pedelecs sind schwerer als normale Fahrräder. Prüfe deshalb, ob die Stützlast der Anhängekupplung für das höhere Gewicht geeignet ist.","Pedelecs sind schwerer als normale Fahrräder. Prüfe deshalb, ob dein Hecktragesystem für das höhere Gewicht geeignet ist.","Pedelecs sind schwerer als normale Fahrräder. Prüfe deshalb, ob du den Reifendruck des Pkws anpassen musst."],"rn":921},{"n":"2.2.23-034","t":"Was ist bei amtlichen Kennzeichen wichtig?","p":2,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Sie müssen an den vorgesehenen Stellen fest angebracht sein","Die hinteren Kennzeichen müssen bei Dunkelheit beleuchtet sein","Sie müssen immer gut lesbar sein"],"co":[0,1,2],"ex":["Die vorgesehenen Stellen befinden sich an der Vorder- und Rückseite des Kraftfahrzeugs.","Das hintere Kennzeichen muss eine Beleuchtungseinrichtung haben, um dieses bei Dunkelheit erkennbar zu machen.","Der Fahrzeugführer ist dafür verantwortlich, dass die Kennzeichen immer gut lesbar sind."],"rn":922},{"n":"2.2.23-035","t":"Was ist vorgeschrieben, wenn die Haftpflichtversicherung Ihres Fahrzeugs erloschen ist?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- muss bei der Zulassungsstelle abgemeldet werden","- darf im Straßenverkehr nicht mehr benutzt werden","- muss bei der Zulassungsstelle vorgeführt werden"],"co":[0,1],"ex":["Ist die Haftpflicht des Fahrzeugs erloschen, dann muss das der Zulassungsstelle gemeldet werden.","Wenn die Haftpflicht nicht mehr gültig ist, haftet auch niemand mehr für Schäden, die mit diesem Fahrzeug an anderen Fahrzeugen verursacht werden. Das Fahrzeug darf dann nicht mehr im Straßenverkehr genutzt werden.","Es gibt hier keinen Grund, das Fahrzeug bei der Zulassungsstelle vorzuführen."],"rn":923},{"n":"2.2.23-036","t":"Was dürfen Sie am amtlichen Kennzeichen verändern?","p":2,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Zum Schutz der Beschriftung eine Folie aufkleben","Bunte Aufkleber aufbringen","Es darf nichts verändert werden"],"co":[2],"ex":["Du darfst keine Folie auf das Nummernschild kleben.","Das amtliche Kennzeichen darf nicht verändert werden.","Du darfst am amtlichen Kennzeichen, also an deinem Nummernschild, nichts verändern."],"rn":924},{"n":"2.2.23-053","t":"Welche Änderung müssen Sie als Fahrzeughalter der zuständigen Zulassungsbehörde unverzüglich melden?","p":2,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- meines Namens","- meines Wohnsitzes","- meiner Haftpflichtversicherung"],"co":[0,1],"ex":["Eine Namensänderung muss der Zulassungsstelle sofort mitgeteilt werden.","Änderst du deinen Wohnsitz, dann musst du dies der Zulassungsbehörde unmittelbar weiterleiten.","Eine Änderung deiner Haftpflichtversicherung muss der Zulassungsbehörde nicht mitgeteilt werden."],"rn":925},{"n":"2.2.23-054","t":"Sie sind neuer Halter eines zugelassenen Fahrzeugs. Was müssen Sie tun?","p":2,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- der Zulassungsbehörde einen Nachweis über das Bestehen einer Haftpflichtversicherung für das Fahrzeug vorlegen","- generell eine Hauptuntersuchung bei Halterwechsel durchführen lassen","- die Zulassungsbehörde über den Halterwechsel informieren"],"co":[0,2],"ex":["Eine gültige Haftpflichtversicherung ist für jedes Fahrzeug notwendig. Der Zulassungsbehörde muss ein Nachweis vorgelegt werden.","Wenn das Fahrzeug noch ein gültige Hauptuntersuchung hat, muss hierzu nichts gemacht werden","Nach Annahme des neuen Fahrzeugs muss du die Zulassungsbehörde über den Halterwechsel informieren."],"rn":926},{"n":"2.2.23-063","t":"Was kann während der Fahrt dazu führen, dass Sie Warnsignale überhören?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Das Hören von lauter Musik","Eine Ablenkung durch Telefonieren","Das Fahren mit geringer Motordrehzahl"],"co":[0,1],"ex":["Sehr laute Musik lässt dich möglicherweise Warnsignale überhören. Stelle Musik immer nur so laut, dass du akustische Warnsignale noch hören kannst.","Ablenkungen durch das Telefonat könnten dazu führen, dass du Warnsignale überhörst.","Eine geringe Motordrehzahl macht weniger Lärm als eine hohe Motordrehzahl. Dass du Warnsignale überhörst, wird eher bei hoher Motordrehzahl möglich."],"rn":927},{"n":"2.2.23-101","t":"Was ist bei Fahrzeugen mit Planen zu beachten?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Unbeladene Anhänger mit hohen Planenaufbauten sind gegen Seitenwind besonders empfindlich","Die Planen dürfen die Sicht des Fahrers über die Außenspiegel nach hinten nicht behindern","Bei Fahrzeugen mit Planen kann auf eine besondere Sicherung der Ladung verzichtet werden"],"co":[0,1],"ex":["Bei Seitenwind sollte mit einem Fahrzeug mit hohen Planenaufbauten besonders vorsichtig gefahren werden, weil die Planen den Wind auffangen und das Fahrzeug hierdurch seitlich kippen oder ausscheren kann. Unbeladen sind solche Fahrzeuge besonders anfällig für Wind, da sie ein deutlich geringeres Gewicht als im beladenen Zustand haben.","Planen müssen so befestigt sein, dass die Rücksicht durch die Außenspiegel nicht behindert wird.","Die Ladung muss bei Fahrzeugen mit Planen gleichermaßen gesichert werden, wie bei Fahrzeugen ohne Planen."],"rn":928},{"n":"2.2.23-104","t":"Wie sichert man einen Pkw mit Schaltgetriebe am Berg gegen Wegrollen?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Schalthebel in Leerlaufstellung bringen","Ersten Gang oder Rückwärtsgang einlegen","Feststellbremse betätigen"],"co":[1,2],"ex":["Stellt man den Schalthebel auf Leerlauf, dann wird die zusätzliche Bremswirkung des Motors nicht genutzt.","Du solltest den ersten Gang oder Rückwärtsgang einlegen, da so der Motor bremst. Zusätzlich ist die Handbremse zu betätigen, um eine größere Bremswirkung zu haben.","Um einen Pkw mit Schaltgetriebe gegen Wegrollen zu sichern, betätigt man mindestens die Feststellbremse (Handbremse). Zusätzlich solltest du einen Gang einlegen, damit zusätzlich der Motor bremst."],"rn":929},{"n":"2.2.23-107","t":"Wodurch kann Ihre Sicht beeinträchtigt werden?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Durch abgenutzte Wischerblätter (Schlierenbildung)","Durch die Ladung","Durch verschmierte Scheiben"],"co":[0,1,2],"ex":["Abgenutzte Scheibenwischer reinigen die Frontscheibe nicht mehr richtig. So bilden sich Schlieren, welche die Sicht des Fahrers behindern.","Durch Ladung kann deine Sicht beeinträchtigt sein. Du solltest allerdings trotz Ladung nach vorne, seitlich und durch die Rückspiegel nach hinten uneingeschränkte Einsicht auf den Verkehr haben.","Dies kann durch abgenutzte Scheibenwischer und/oder starke Verschmutzung entstehen."],"rn":930},{"n":"2.2.23-113","t":"Ein auflaufgebremster Wohnanhänger mit einer Achse wird im Gefälle abgestellt. Wie ist er gegen Wegrollen zu sichern?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Unterlegkeile vor die Räder legen","Feststellbremse anziehen","Je einen Unterlegkeil vor und hinter ein Rad legen"],"co":[0,1],"ex":["Die Unterlegkeile müssen vor die Räder gelegt werden, um den Wohnanhänger gegen Wegrollen zu sichern.","Durch betätigen der Feststellbremse sicherst du den Wohnanhänger im Gefälle gegen Wegrollen.","Die Keile sind vor den Rädern zu platzieren."],"rn":931},{"n":"2.2.23-119","t":"Was ist bei der Einstellung von Kopfstützen im Fahrzeug zu beachten?","p":4,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Der Abstand zwischen Hinterkopf und Kopfstütze sollte möglichst gering sein","Die höchste Stelle des Kopfes sollte mit der Oberkante der Kopfstütze etwa gleichauf sein","Die Oberkante der Kopfstütze sollte mit dem oberen Halswirbel abschließen"],"co":[0,1],"ex":["So ist die Verletzungsgefahr im Falle eines Aufpralls am geringsten, da die Kopfstütze schon direkt an deinem Kopf ist.","So schützt dich die Kopfstütze im Bedarfsfall bestmöglich.","Die Oberkante der Kopfstütze sollte mit der höchsten Stelle des Kopfes abschließen. Auf Halswirbelhöhe kann sie deinen Kopf im Falle eines Aufpralls nicht schützen."],"rn":932},{"n":"2.2.23-120","t":"Wann sollten Sie trotz vorhandener Freisprecheinrichtung auf das Telefonieren verzichten?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["In komplizierten Verkehrssituationen","Wenn ich dadurch abgelenkt werde","Bei schwierigen Gesprächen"],"co":[0,1,2],"ex":["In komplizierten Verkehrssituationen musst Du Dich voll und ganz auf die Verkehrsführung und die Verkehrsteilnehmer konzentrieren. Du solltest Dich keinesfalls ablenken lassen.","Ablenkung führt dazu, dass du etwas im Straßenverkehr übersiehst und nicht schnell genug reagieren kannst. Während des Fahrens solltest Du jedoch immer voll und ganz konzentriert sein.","Bei schwierigen Gesprächen bist Du vermutlich nervös und aufgeregt. Dabei achtest Du mehr auf Deinen Gesprächspartner und konzentrierst Dich weniger auf den Straßenverkehr."],"rn":933},{"n":"2.2.23-121","t":"Sie möchten Ihr im Kraftfahrzeug befestigtes Smartphone als Navigationsgerät nutzen. Was sollten Sie beachten?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- die Sprachausgabe des Geräts benutzen","- das Fahrtziel bei stehendem Fahrzeug eingeben","- das Gerät möglichst nicht während der Fahrt bedienen"],"co":[0,1,2],"ex":["Ohne Sprachausgabe müsstest du zur Navigation immer wieder auf den Bildschirm deines Smartphones schauen. Dazu müsstest du den Blick­ vom Straßenverkehr abwenden, was das Risiko eines Unfalls deutlich erhöht.","Jegliche Bedienung des Smartphones während der Fahrt lenkt dich vom Verkehrsgeschehen ab. Somit sollte die Bedienung während der Fahrt auf das Nötigste reduziert werden. Zur Eingabe des Fahrtziels oder das Anpassen von Optionen beispielsweise, sollten im stehenden Fahrzeug erledigt werden.","Die Bedienung des Smartphones lenkt dich während der Fahrt vom Verkehrsgeschehen ab. Reduziere deshalb die Bedienung beim Fahren."],"rn":934},{"n":"2.2.23-122","t":"Während der Fahrt bekommen Sie einen Anruf. Was müssen Sie beachten?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- das Telefon hierzu nicht länger als 7 Sekunden bedient wird","- die Nutzung des Telefons höchstens eine kurze Blickzuwendung erfordert","- das Telefon hierzu nicht gehalten wird"],"co":[1,2],"ex":["Die Bedienung sollte über eine Freisprecheinrichtung laufen und sollte blind, also nur mit kurzem Blickkontakt, bedient werden können.","Ein kurzer Blick auf das Telefon ist erlaubt.","Du darfst mit einer Freisprecheinrichtung telefonieren."],"rn":935},{"n":"2.2.23-124","t":"Was ist die Hauptfunktion der Kopfstütze im Pkw?","p":2,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- erhöht die Sicherheit für die Insassen","- ersetzt den Sicherheitsgurt auf der Rücksitzbank","- verbessert die Sitzposition"],"co":[0],"ex":["Die Kopfstütze vermindert bei Unfällen oder starkem Bremsen die Krafteinwirkung auf die Halswirbelsäule der Insassen. Sie erhöht also die Sicherheit der Insassen.","Die Kopfstütze ersetzt keinesfalls den Sicherheitsgurt auf der Rücksitzbank.","Die Verbesserung der Sitzposition ist keine Hauptfunktion der Kopfstütze."],"rn":936},{"n":"2.2.23-125","t":"Während der Fahrt beschlägt die Frontscheibe Ihres Fahrzeugs von innen. Wie können Sie dem entgegenwirken?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Ich richte die Lüftung mit maximaler Leistung auf die Frontscheibe","Ich schalte die Klimaanlage ein","Ich öffne bei hoher Außenluftfeuchtigkeit die Fenster"],"co":[0,1],"ex":["Indem du die Luftzirkulation an der Scheibe erhöhst, kannst du dem Beschlagen der Scheibe entgegenwirken.","Die Klimaanlage trocknet die Luft und hilft so, die Feuchtigkeit von der Scheibe zu entfernen.","Das Fenster zu öffnen hilft nur gegen das Beschlagen der Scheibe, wenn die Außenluftfeuchtigkeit niedrig ist."],"rn":937},{"n":"2.2.23-126","t":"Ihr Kraftfahrzeug ist eingeschneit. Wie müssen Sie sich vor Fahrtantritt verhalten?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- vom Fahrzeugdach entfernen","- von den Beleuchtungseinrichtungen entfernen","- vom Nummernschild entfernen"],"co":[0,1,2],"ex":["Bevor du losfährst, musst du den Schnee vom Fahrzeugdach entfernen, da dieser während der Fahrt herunterfallen und dadurch andere Verkehrsteilnehmer gefährden könnte. Außerdem könnte dir der Schnee bei Bremsmanövern auf die Frontscheibe rutschen, die Sicht nehmen und dich so komplett handlungsunfähig machen. Das wäre sehr gefährlich.","Der Schnee muss von den Beleuchtungseinrichtungen entfernt werden, sodass du von anderen Verkehrsteilnehmern rechtzeitig gesehen wirst. Zudem stellt die Beleuchtungseinrichtungen sicher, du bei dunklen Lichtverhältnissen angemessene Sicht hast.","Vor dem Fahrtantritt musst du sicherstellen, dass kein Schnee deine Nummernschilder verdeckt. Falls die Nummernschilder unleserlich sind, riskierst du eine Ordnungswidrigkeit mit Bußgeld."],"rn":938},{"n":"2.2.23-127","t":"Welche Teile Ihres Kraftfahrzeugs müssen Sie vor Fahrtantritt vollständig von Schnee und Eis befreien?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["Die Seitenscheiben","Die Frontscheibe","Die Außenspiegel"],"co":[0,1,2],"ex":["Bevor du losfährst, musst du Schnee und Eis von den Seitenscheiben entfernen. Du brauchst die Sicht aus allen Fensterscheiben, um sicher am Straßenverkehr teilnehmen zu können.","Vor Fahrtantritt musst du deine Frontscheibe komplett von Schnee und Eis befreien, um eine ausreichende Sicht auf die Straße zu haben und dich angemessen im Straßenverkehr orientieren zu können.","Die Außenspiegel müssen vor Fahrtantritt von Schnee und Eis befreit werden, damit du auch den Verkehr hinter dir angemessen sehen kannst. So kannst du rechtzeitig auf andere Verkehrsteilnehmer reagieren und das Unfallrisiko bei Überholvorgängen reduzieren."],"rn":939},{"n":"2.2.23-128","t":"Sie möchten bei winterlichen Witterungsverhältnissen eine Fahrt antreten. Was müssen Sie beachten?","p":3,"c":"2.2.23","ch":"Sonstige Pflichten Des Fahrzeugfuehrers","th":"Verhalten Im Strassenverkehr","o":["- nach vorn die eigene Sicht beeinträchtigen","- andere Fahrzeuge beschädigen","- Unfälle verursachen"],"co":[0,1,2],"ex":["Bei einem plötzlichen Bremsmanöver kann Schnee und Eis von deinem Fahrzeugdach auf deine Frontscheibe rutschen. Dadurch wird deine Sicht beeinträchtigt, was zu einem erhöhten Unfallrisiko führt.","Wenn während der Fahrt Eisstücke von deinem Fahrzeugdach nach hinten auf die Straße fallen, könnten diese Eisstücke andere Fahrzeuge im vorderen Bereich beschädigen.","Während der Fahrt können Schnee und Eis auf deinem Fahrzeugdach nach hinten auf die Straße fallen. Das kann die Verkehrsteilnehmer hinter dir irritieren oder für rutschige Fahrbahnverhältnisse sorgen, was die Unfallgefahr erhöht."],"rn":940},{"n":"2.2.26-102","t":"Sie kommen unerwartet auf einem Fußgängerüberweg zum Stehen. Wie verhalten Sie sich?","p":4,"c":"2.2.26","ch":"Verhalten An Fussgaengerueberwegen Und Gegenueber Fussgaengern","th":"Verhalten Im Strassenverkehr","o":["Etwas vorwärts- oder rückwärtsfahren, um den Überweg so weit wie möglich frei zu machen","Halbseitig auf den Gehweg fahren, um damit den Überweg frei zu machen","Keinesfalls rückwärtsfahren, auch wenn hinten frei ist"],"co":[0],"ex":["Du solltest den Fußgängerüberweg so weit wie möglich frei machen. Fahre, wenn es geht, vorwärts, da so die Sicht des nachfolgenden Verkehr auf den Fußgängerüberweg frei ist. Andernfalls kannst du auch rückwärts fahren.","Gehwege dienen der Nutzung durch Fußgänger. Dein Fahrzeug muss auf der Straße stehen.","Wenn hinten frei ist, kannst du rückwärts fahren. Vorzugsweise solltest du jedoch nach vorne fahren, um die Sicht des nachfolgenden Verkehrs auf den Fußgängerüberweg nicht zu verdecken."],"rn":941},{"n":"2.2.29-001","t":"Was kann die Teilnahme an illegalen Straßenrennen zur Folge haben?","p":4,"c":"2.2.29","ch":"Uebermaessige Strassenbenutzung","th":"Verhalten Im Strassenverkehr","o":["Den Entzug der Fahrerlaubnis für den Fahrzeugführer","Das Entstehen schwerer Verkehrsunfälle","Die Anordnung einer Freiheitsstrafe für den Fahrzeugführer"],"co":[0,1,2],"ex":["Die Fahrerlaubnis des Fahrers von illegalen Straßenrennen kann entzogen werden.","Durch die hohe Geschwindigkeit und unvorsichtiges, emotionales Verhalten, können illegale Straßenrennen sehr schwere Verkehrsunfälle und häufig auch Personenschäden zur Folge haben.","Die Teilnahme an illegalen Autowettrennen ist eine Straftat. Je nachdem, ob eine Gefährdung vorliegt, werden die Fahrer illegaler Autorennen mit einer Freiheitsstrafe von bis zu zehn Jahren bestraft."],"rn":942},{"n":"2.2.30-103","t":"Für welche Kraftfahrzeuge gilt bei einer geschäftsmäßigen oder entgeltlichen Beförderung von Gütern das Fahrverbot an Sonn- und Feiertagen?","p":3,"c":"2.2.30","ch":"Sonntagsfahrverbot","th":"Verhalten Im Strassenverkehr","o":["Für Pkws mit einem Anhänger","Für Lkws mit einem Anhänger","Für Lkws mit einer zulässigen Gesamtmasse über 7,5 t"],"co":[1,2],"ex":["Für Pkws mit Anhänger gilt das Fahrverbot an Sonntagen und Feiertagen nicht.","Für Lkws mit Anhänger gilt ebenso wie für Lkws über 7,5 t ohne Anhänger ein Fahrverbot an Sonntagen und Feiertagen von 0 bis 22 Uhr. Lkws unter 7,5 t dürfen hingegen auch an Sonn- und Feiertagen gefahren werden.","Lastkraftwagen ab 7,5 t dürfen an Sonn- und Feiertagen von 0 Uhr bis 22 Uhr nicht gefahren werden."],"rn":943},{"n":"2.2.32-101","t":"Sie fahren aus unbefestigtem Gelände (z. B. Acker, Baustelle) auf eine öffentliche Straße und verschmutzen diese erheblich. Wer ist für die Beseitigung dieses Verkehrshindernisses verantwortlich?","p":3,"c":"2.2.32","ch":"Verkehrshindernisse","th":"Verhalten Im Strassenverkehr","o":["Die Anlieger dieses Straßenabschnitts","Das zuständige Straßenbauamt","Sie als Verursacher"],"co":[2],"ex":["Die Anlieger des Straßenabschnitts sind nicht für die Reinigung der verschmutzten Straße zuständig, sondern du als Verursacher.","Nicht das Straßenbauamt, sondern du als Verursacher musst dieses Verkehrshindernis beseitigen.","Du als Verursacher musst den Schmutz beseitigen."],"rn":944},{"n":"2.2.32-102","t":"Was müssen Sie tun, um eine Gefährdung anderer durch von Ihrem Fahrzeug gefallene Ausrüstungs- oder Ladungsteile zu verhindern?","p":3,"c":"2.2.32","ch":"Verkehrshindernisse","th":"Verhalten Im Strassenverkehr","o":["- die Teile selbst beseitigen","- die Gefahrstelle absichern und umgehend Straßendienst oder Polizei verständigen","- weiterfahren und das nächste Ordnungsamt informieren"],"co":[0,1],"ex":["Wenn es möglich ist, dies eigenständig zu tun, musst du die Teile selbst beseitigen.","Ist es nicht möglich, die Ausrüstungs- oder Ladungsteile selbst zu beseitigen, dann muss die Gefahrstelle abgesichert und Straßendienst oder Polizei alarmiert werden.","Du darfst hier unter keinen Umständen weiterfahren. Du musst die heruntergefallenen Gegenstände entweder selbst beseitigen oder, falls dies nicht möglich ist, die Gefahrstelle absichern und Polizei oder Straßendienst verständigen."],"rn":945},{"n":"2.2.34-001-M","t":"Wie verhalten Sie sich in dieser Situation richtig?","p":4,"c":"2.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Ich bremse sofort stark ab","Ich fotografiere die Unfallstelle","Ich fahre unverändert weiter"],"co":[2],"ex":["Es gibt keinen Grund für unmittelbares, starkes Bremsen. Fahre unverändert weiter.","Das behindert den Verkehrsfluss und ist den Unfallbeteiligten gegenüber respektlos. Fahre unverändert weiter.","Fahre unverändert an der Unfallstelle vorbei."],"v":["https://video2.kalaiwa.de/assets/2234001mv1440.mp4"],"rn":946},{"n":"2.2.34-101","t":"Sie hatten einen Wildunfall. Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Ich sichere die Unfallstelle ab","Ich nehme das Wild mit","Ich verständige die Polizei"],"co":[0,2],"ex":["Nach einem Wildunfall solltest du das Warnblinklicht einschalten, eine Warnweste anziehen und ein Warndreieck aufstellen, um die Unfallstelle abzusichern.","Entfernst du das Wild von der Unfallstelle, machst du dich strafbar. Dir könnte eine Anzeige wegen Wilderei drohen.","Du solltest die Polizei verständigen, deinen Unfall schildern und deinen genauen Standort durchgeben."],"rn":947},{"n":"2.2.34-102","t":"Warum sollten Sie während der Fahrt stets den Europäischen Unfallbericht mitführen?","p":3,"c":"2.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- eine selbstständige Unfallaufnahme durch die Beteiligten ermöglicht","- die Unfallaufnahme mit fremdsprachigen Unfallbeteiligten erleichtert","- die Haftungsfrage am Unfallort eindeutig beantwortet"],"co":[0,1],"ex":["Der Europäische Unfallbericht ist europaweit einheitlich und ermöglicht so eine selbstständige Aufnahme des Unfalls in allen europäischen Ländern. Mit diesem Formular kannst du auch im Ausland deinen Unfall richtig dokumentieren.","Den Europäischen Unfallbericht gibt es in einer mehrsprachigen Version. Er erleichtert so die Unfallaufnahme bei einem Unfall in anderen Ländern oder bei einem Unfall in Deutschland mit fremdsprachigen Unfallbeteiligten.","Haftungsfragen am Unfallort können mit einem Unfallbericht nicht eindeutig geklärt werden. Dafür ist die ein Bericht der Polizei notwendig."],"rn":948},{"n":"2.2.34-103","t":"Welche Funktion erfüllt das eCall-System im Falle eines schweren Unfalls?","p":2,"c":"2.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["- den Zeitpunkt des Unfalls","- die Verletzungsschwere der Personen im Kraftfahrzeug","- die Position des Kraftfahrzeugs"],"co":[0,2],"ex":["Den Zeitpunkt des Unfalls übermittelt das eCall-System automatisch, wenn es einen Notruf absetzt.","Die Verletzungsschwere der Personen in einem Unfallfahrzeug kann das eCall-System nicht einschätzen und übermitteln.","Bei einem Notruf übermittelt das eCall-System automatisch die Position des Kraftfahrzeugs."],"rn":949},{"n":"2.2.34-104","t":"In welcher Situation ist eine manuelle Auslösung des eCall-Systems vorgesehen?","p":2,"c":"2.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Wenn mein Fahrzeug eine Reifenpanne hat","Wenn ich Zeuge eines schweren Unfalls werde","Wenn eine mitfahrende Person einen medizinischen Notfall erleidet"],"co":[1,2],"ex":["Eine Reifenpanne bedarf keinen Notruf. Löse das eCall-System nicht aus, wenn du eine Reifenpanne hast.","Wenn du Zeuge eines Unfalls wirst, darfst du das eCall-System auch manuell auslösen und so schnell einen Notruf absetzen.","Wenn Mitfahrende einen medizinischen Notfall erleiden, der nicht von einem Unfall herrührt, darfst du das eCall-System manuell auslösen."],"rn":950},{"n":"2.2.34-003-M","t":"Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.2.34","ch":"Unfall","th":"Verhalten Im Strassenverkehr","o":["Ich fahre unverändert weiter","Ich fahre so weit wie möglich links","Ich verringere meine Geschwindigkeit weiter"],"co":[1,2],"ex":["Ein Unfall birgt immer ein erhöhtes Gefahrenpotential. Sei deswegen sehr aufmerksam.","Fahre möglichst weit links, so dass du möglichst viel Platz zwischen Unfall und deinem Fahrzeug hast, um keine Fußgänger zu gefährden und auch nicht in Fahrzeugteile oder Öl zu fahren.","Fahre stets langsam an einer Unfallstelle vorbei. Du musst damit rechnen, dass Fußgänger auf der Straße herumlaufen oder stehen. Es könnten auch Fahrzeugteile oder Öl auf der Fahrbahn sein."],"v":["https://video2.kalaiwa.de/assets/2234003mv1440.mp4"],"rn":951},{"n":"2.2.36-001-M","t":"Wie verhalten Sie sich bei der Annäherung an diesen Schwertransport richtig?","p":3,"c":"2.2.36","ch":"","th":"","o":["Ich überhole mit großer Vorsicht","Ich überhole nicht","Ich wechsle auf den rechten Fahrstreifen"],"co":[1,2],"ex":["Du darfst den Schwertransport auf keinen Fall überholen.","Der Schwertransport ist mit einem mobilen Überholverbotsschild ausgestattet. Du darfst ihn nicht überholen.","Du darfst den Schwertransport nicht überholen. Wechsle auf den rechten Fahrstreifen, es gilt das Rechtsfahrgebot."],"i":["https://video4.kalaiwa.de/assets/2236001m.webp"],"rn":952},{"n":"2.2.37-002","t":"Sie fahren mit ungefähr 40 km/h. Etwa 10 m vor Ihnen wechselt die Ampel von „Grün“ auf „Gelb“. Wie verhalten Sie sich?","p":4,"c":"2.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Anhalten","Weiterfahren"],"co":[1],"ex":["Ein risikofreies Anhalten ist nicht mehr möglich, weil der Anhalteweg zu lang wäre, um noch vor der Ampel zum Stehen zu kommen.","Der Anhalteweg wäre zu lang um noch vor der Ampel zum Stehen zu kommen. Daher solltest du weiterfahren."],"rn":953},{"n":"2.2.37-003","t":"Sie fahren mit ungefähr 40 km/h. Etwa 40 m vor Ihnen wechselt die Ampel von „Grün“ auf „Gelb“. Wie verhalten Sie sich?","p":4,"c":"2.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Anhalten","Weiterfahren"],"co":[0],"ex":["Der Anhalteweg ist ausreichend, um noch vor der Ampel zum Stehen zu kommen. Daher musst du anhalten.","40 m sind noch ausreichend, um hier vor der Ampel zum Halten zu kommen."],"rn":954},{"n":"2.2.37-007","t":"Was gilt bei Dauerlichtzeichen?","p":2,"c":"2.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["Dauerlichtzeichen sperren den Fahrstreifen oder geben ihn zum Befahren frei","Auf Fahrstreifen mit Dauerlichtzeichen besteht Haltverbot","Dauerlichtzeichen gelten nur für mehrspurige Kraftfahrzeuge"],"co":[0,1],"ex":["In diesem Fall sind die beiden linken Fahrstreifen vollständig gesperrt, der zweite von rechts zeigt einen Spurwechsel auf die rechte Spur an und die rechte Spur ist hier uneingeschränkt befahrbar.","Unabhängig davon, ob sie generell befahren werden dürfen, oder nicht, gilt absolutes Haltverbot auf Fahrstreifen mit Dauerlichtzeichen.","Dauerlichtzeichen gelten für alle auf der Fahrbahn befindlichen Verkehrsteilnehmer."],"i":["https://video2.kalaiwa.de/assets/2237007.webp"],"rn":955},{"n":"2.2.37-008","t":"Was bedeuten diese Dauerlichtzeichen?","p":4,"c":"2.2.37","ch":"Wechsellichtzeichen Und Dauerlichtzeichen","th":"Verhalten Im Strassenverkehr","o":["- 1 dürfen diesen weiter befahren","- 3 und 4 müssen anhalten","- 2 müssen auf den Fahrstreifen nach rechts wechseln"],"co":[0,2],"ex":["Der grüne Pfeil erlaubt das weitere Befahren dieses Fahrstreifens.","Fahrbahn 3 und 4 dürfen nicht befahren werden.","Der gelbe Rechtspfeil deutet den Verkehrsteilnehmern, auf die rechte Spur zu wechseln."],"i":["https://video4.kalaiwa.de/assets/2237008.webp"],"rn":956},{"n":"2.2.38-101","t":"Von hinten nähert sich ein Fahrzeug mit eingeschaltetem blauen Blinklicht und Einsatzhorn. Wie verhalten Sie sich jetzt richtig?","p":4,"c":"2.2.38","ch":"Fahrzeuge Mit Vorfahrt","th":"Verhalten Im Strassenverkehr","o":["Ich halte sofort an","Ich verringere meine Geschwindigkeit","Ich fahre möglichst weit rechts"],"co":[1,2],"ex":["Es ist nicht notwendig anzuhalten, da kein Gegenverkehr in Sichtweite ist und das Einsatzfahrzeug genug Platz hat, dich zu überholen.","Du musst deine Geschwindigkeit verringern, damit das Einsatzfahrzeug dich leichter und früher überholen kann. Je früher dich das Einsatzfahrzeug überholt, desto früher kann auch der Vorausfahrende sehen, dass er ein Einsatzfahrzeug vorbeilassen muss und kann sich darauf einstellen.","Wenn du möglichst weit rechts fährst, gibst du dem Einsatzfahrzeug mehr Platz, dich zu überholen und erleichterst so seine Weiterfahrt."],"i":["https://video2.kalaiwa.de/assets/2238101.webp"],"rn":957},{"n":"2.4.40-002","t":"Wie verhalten Sie sich auf einer Autobahn bei diesem Verkehrszeichen?","p":4,"c":"2.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Aufmerksamkeit erhöhen, vorsorglich Abstand vergrößern","Bei Stau abbremsen und Warnblinklicht einschalten","Bei Stau auf den Seitenstreifen wechseln und dort weiterfahren"],"co":[0,1],"ex":["Weil dieses Verkehrszeichen auf Streckenteilen steht, wo erhöhte Staugefahr herrscht, musst du erhöhte Aufmerksamkeit zeigen und den Abstand vergrößern. So trägst du deinen Teil dazu bei, dass die Staugefahr vermindert wird und kannst im Falle eines bereits entstandenen Staus rechtzeitig reagieren.","Sobald du ein Stauende erkennst, musst du abbremsen und das Warnblinklicht einschalten, um hinter dir herannahende Fahrzeuge zu warnen.","Das ist nicht gestattet."],"i":["https://video4.kalaiwa.de/assets/2440002.webp"],"rn":958},{"n":"2.4.40-003","t":"Wie müssen Sie sich bei diesem Verkehrszeichen verhalten?","p":3,"c":"2.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Geschwindigkeit vor der Kurve vermindern","Vor der Kurve links blinken","Möglichst weit rechts fahren"],"co":[0,2],"ex":["Du musst mit deutlich niedrigerer Geschwindigkeit in die Kurve einfahren, als die für diese Strecke angegebene Höchstgeschwindigkeit.","Da du weiterhin auf der Fahrbahn bleibst und keinen Wechsel vornimmst, musst du auch nicht blinken.","Du musst damit rechnen, dass Verkehrsteilnehmer auf der Gegenfahrbahn die Kurve unterschätzen und auf deine Fahrbahn kommen. Zudem kannst du besser in die Kurve einfahren, wenn du dich weiter rechts hältst. Daher ist es sicherer möglichst weit rechts zu fahren."],"i":["https://video2.kalaiwa.de/assets/2440003.webp"],"rn":959},{"n":"2.4.40-004","t":"Wie verhalten Sie sich im Bereich dieser Gefahrstrecke?","p":3,"c":"2.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Abblenden und bremsen, wenn Wild in Sicht kommt","Langsamer fahren, auf Wild achten","Nicht vor Wild ausweichen, wenn der Gegenverkehr gefährdet würde"],"co":[0,1,2],"ex":["Falls Wild auf die Straße läuft, musst du abbremsen und abblenden. Durch das Abblenden machst du es auf dich aufmerksam und bringst es möglicherweise dazu, die Fahrbahn zu verlassen.","In diesem Gebiet herrscht erhöhter Wildwechsel. Daher solltest du langsam fahren und darauf achten.","Kannst du aufgrund von Gegenverkehr nicht ausweichen, dann musst du stark abbremsen, wenn sich Wild vor dir auf der Straße befindet."],"i":["https://video2.kalaiwa.de/assets/2440004.webp"],"rn":960},{"n":"2.4.40-007","t":"Womit sollten Sie bei diesem Verkehrszeichen rechnen?","p":3,"c":"2.4.40","ch":"Gefahrzeichen","th":"Verkehrszeichen","o":["Mit Ästen, die auf der Fahrbahn liegen","Mit vorausfahrenden Fahrzeugen, die plötzlich bremsen","Mit vorausfahrenden Fahrzeugen, die plötzlich nach links ausweichen"],"co":[0,1,2],"ex":["Es ist gut möglich, dass ein Fahrzeug vor dir mit den Bäumen in Kontakt war und deshalb Äste auf der Fahrbahn liegen.","Du musst damit rechnen, dass Fahrzeuge plötzlich bremsen, weil die Höhe eingeschränkt ist.","Eventuell müssen Fahrzeuge nach links ausweichen, um nicht mit niedrig hängenden Ästen zu kollidieren. Überholen ist hier gefährlich."],"i":["https://video4.kalaiwa.de/assets/2440007.webp"],"rn":961},{"n":"2.4.41-101","t":"Was müssen Sie bei diesem Verkehrszeichen beachten?","p":2,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Kettenfahrzeuge haben Vorfahrt","Schneeketten benutzen","Zulässige Höchstgeschwindigkeit 50 km/h"],"co":[1,2],"ex":["Dieses Verkehrszeichen regelt keine Vorfahrt, es ordnet lediglich an, dass Schneeketten benutzt werden müssen.","Hier müssen Schneeketten an den Reifen angebracht werden, um die Strecke benutzen zu dürfen.","Mit Schneeketten darf nicht schneller als 50 km/h gefahren werden."],"i":["https://video2.kalaiwa.de/assets/2441101.webp"],"rn":962},{"n":"2.4.41-102","t":"Welches Verkehrszeichen bezieht sich auf die zulässige Gesamtmasse?","p":2,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","na":"Antwort: Nr. 2","e":"Das Verbotsschild Nummer 1 bezieht sich auf die tatsächlich vorhandene Gesamtmasse eines Fahrzeugs. Bei Verkehrsschild Nummer 2 gilt das Verbot in Bezug auf die zulässige Gesamtmasse des Kraftfahrzeugs, einschließlich Anhänger.","i":["https://video4.kalaiwa.de/assets/2441102.webp"],"rn":963},{"n":"2.4.41-103","t":"Welches Verkehrszeichen bezieht sich auf die tatsächliche Masse?","p":2,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","na":"Antwort: Nr. 1","e":"Das Verkehrszeichen Nummer 1 bezieht sich auf die tatsächliche Gesamtmasse des Fahrzeugs, einschließlich Ladung. Das Verkehrszeichen Nummer 2 bezieht sich auf die zulässige Gesamtmasse.","i":["https://video4.kalaiwa.de/assets/2441103.webp"],"rn":964},{"n":"2.4.41-104","t":"Für welche Fahrzeuge ist das Befahren einer so beschilderten Straße verboten?","p":2,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["- tatsächliche Achslast 2 t überschreitet","- zulässige Gesamtmasse 2 t nicht überschreitet","- zulässige Achslast 2 t überschreitet"],"co":[0],"ex":["Das Verkehrszeichen verbietet Fahrzeugen mit einer tatsächlichen Achslast über 2 t die Weiterfahrt.","Das Verkehrszeichen bezieht sich auf die Achslast, nicht auf die Gesamtmasse.","Das Verkehrszeichen bezieht sich auf die tatsächliche, nicht auf die zulässige Achslast."],"i":["https://video2.kalaiwa.de/assets/2441104.webp"],"rn":965},{"n":"2.4.41-105","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Auf eine Fahrbahn von 2 m Breite","Auf ein Verbot für Fahrzeuge, deren Breite einschließlich Ladung 2 m überschreitet","Auf einen vorgeschriebenen Seitenabstand von mindestens 2 m zu anderen Fahrzeugen"],"co":[1],"ex":["Das Verkehrszeichen untersagt Fahrzeugen, die breiter als 2 m sind, die Durchfahrt.","Das Verkehrszeichen verbietet Fahrzeugen mit einer Breite über 2 m die Durchfahrt.","Ein Verkehrszeichen, das das besagt, gibt es nicht."],"i":["https://video2.kalaiwa.de/assets/2441105.webp"],"rn":966},{"n":"2.4.41-106","t":"Durch welche Fahrzeuge können bei Missachtung dieses Verkehrszeichens schwere Unfälle entstehen?","p":3,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Länge 10 m, Breite 3,9 m, Höhe 3 m","Länge 4 m, Breite 2,5 m, Höhe 2,5 m","Länge 8 m, Breite 2,5 m, Höhe 4 m"],"co":[2],"ex":["Das Fahrzeug liegt unter der vorgeschriebenen Maximalhöhe und ist somit kein Risikofaktor.","Mit einer Höhe von 2,5 m ist dieses Fahrzeug keine Gefährdung.","Hier geht es ausschließlich um die Höhe. Fahrzeuge, die höher als 3,8 m hoch sind, dürfen nicht durchfahren. Da ein Fahrzeug mit diesen Maßen über der Maximalhöhe ist, können bei Missachtung schwere Unfälle entstehen."],"i":["https://video2.kalaiwa.de/assets/2441106.webp"],"rn":967},{"n":"2.4.41-107","t":"Mit welchen Fahrzeugen dürfen Sie eine so gekennzeichnete Straße nicht befahren?","p":2,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Lkw mit einer Länge von 9 m einschließlich Ladung","Pkw mit Wohnanhänger, Gesamtlänge des Zuges 11 m","Traktor mit Anhänger, Gesamtlänge des Zuges 12 m"],"co":[1,2],"ex":["Da der LKW mit 9 m unter der vorgeschriebenen Maximallänge ist, darf dieser hier weiterfahren.","Da die Gesamtlänge hier 10 m übersteigt, dürfen diese hier nicht fahren.","Der Traktor ist mit Anhänger länger als die vorgeschriebene maximale Gesamtlänge von 10 m und darf hier somit nicht durchfahren."],"i":["https://video2.kalaiwa.de/assets/2441107.webp"],"rn":968},{"n":"2.4.41-108","t":"Welche Fahrzeuge dürfen Sie bei diesem Verkehrszeichen überholen?","p":3,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Mehrspurige Fahrzeuge","Einspurige Fahrzeuge","Keine Fahrzeuge"],"co":[2],"ex":["Das Überholverbot beinhaltet auch mehrspurige Fahrzeuge.","Das Überholverbot beinhaltet einspurige Fahrzeuge.","Du darfst nicht überholen, weder ein- noch mehrspurige Fahrzeuge."],"i":["https://video4.kalaiwa.de/assets/2441108.webp"],"rn":969},{"n":"2.4.41-109","t":"Für welche Kraftfahrzeuge gilt das so gekennzeichnete Überholverbot?","p":2,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Für Kraftomnibusse","Für einspurige Kraftfahrzeuge","Für Pkws ohne Anhänger"],"co":[0],"ex":["Für Kraftomnibusse gilt auch das Überholverbot.","Das Überholverbot gilt nicht für einspurige Kraftfahrzeuge.","Das Überholverbot gilt nicht für Pkws ohne Anhänger."],"i":["https://video2.kalaiwa.de/assets/2441109.webp"],"rn":970},{"n":"2.4.41-004-M","t":"Sie fahren auf dieser Autobahn. Wie verhalten Sie sich richtig?","p":3,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich befahre den linken Fahrstreifen nur im Falle einer Panne","Ich bleibe auf meinem jetzigen Fahrstreifen","Ich wechsle auf den rechten Fahrstreifen"],"co":[2],"ex":["Der linke Fahrstreifen ist gesperrt. Ihn darfst du in keinem Fall befahren. Auch nicht wenn du eine Panne hast.","Es gilt das Rechtsfahrgebot, weshalb du auf die rechte Fahrbahn wechseln musst.","Grundsätzlich gilt auf Autobahnen das Rechtsfahrgebot. Du bist also dazu verpflichtet auf dem rechten Fahrstreifen zu fahren, sofern du nicht überholen möchtest. Vor dir ist niemand zum Überholen"],"i":["https://video2.kalaiwa.de/assets/2441004m.webp"],"rn":971},{"n":"2.4.41-005-M","t":"Wie verhalten Sie sich jetzt richtig?","p":3,"c":"2.4.41","ch":"Vorschriftzeichen","th":"Verkehrszeichen","o":["Ich beschleunige erst, wenn die Geschwindigkeitsbegrenzung durch ein Verkehrszeichen aufgehoben wird","Ich beschleunige","Ich behalte meine Geschwindigkeit bei"],"co":[1],"ex":["Du musst in dieser Situation nicht auf ein Verkehrszeichen warten, da dir die Verkehrsschildkombination anzeigt, dass die 40 km/h Geschwindigkeitsbegrenzung nur für den Baustellenbereich gelten. Du hast die Baustelle bereits passiert und bist wieder auf der richtigen Fahrspur.","Du darfst beschleunigen, da du die Baustelle mit der Geschwindigkeitsbeschränkung passiert hast, zurück auf die richtige Fahrspur gewechselt bist und die Straße vor dir frei ist.","Du musst die Geschwindigkeit nicht beibehalten, da die Geschwindigkeitsbeschränkung nur für das sichere Vorbeifahren an der Baustelle dient. Diese Baustelle hast du bereits passiert."],"v":["https://video4.kalaiwa.de/assets/2441005mv1440.mp4"],"rn":972},{"n":"2.4.42-001","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf das Ende der Autobahn","Auf eine vorübergehende Sperrung der Autobahn","Auf das Ende der Kraftfahrstraße"],"co":[0],"ex":["Dieses Verkehrszeichen kündigt das Ende einer Autobahn an.","Dieses Verkehrszeichen weist auf das Ende einer Autobahn und nicht auf eine vorübergehende Sperrung hin.","Das Verkehrszeichen, das auf das Ende einer Kraftfahrstraße hinweist, sieht anders aus."],"i":["https://video4.kalaiwa.de/assets/2442001.webp"],"rn":973},{"n":"2.4.42-002","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf das Ende der Autobahn","Auf das Ende der Kraftfahrstraße","Auf ein Verbot für Kraftwagen"],"co":[1],"ex":["Das Verkehrszeichen, das das Ende einer Autobahn kennzeichnet, sieht anders aus.","Dieses Verkehrszeichen weist auf das Ende einer Kraftfahrstraße hin.","Das Verkehrszeichen \"Verbot für Kraftwagen und sonstige mehrspurige Fahrzeuge\" ist ein Kreis mit rotem Rand und einem schwarzen PKW-Symbol in der Mitte."],"i":["https://video2.kalaiwa.de/assets/2442002.webp"],"rn":974},{"n":"2.4.42-004","t":"Worauf weisen solche Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf die Nummer einer Europastraße","Auf die Nummer einer Autobahn","Auf die Entfernung bis zur nächsten Tankstelle"],"co":[1],"ex":["Das Verkehrszeichen, das auf eine Europastraße hinweist, ist grün mit weißer Nummer.","Dieses Verkehrszeichen weist auf die Nummer einer Autobahn hin.","Das Verkehrszeichen, das auf die nächste Tankstelle hinweist, ist ein anderes."],"i":["https://video2.kalaiwa.de/assets/2442004.webp"],"rn":975},{"n":"2.4.42-005","t":"Worauf weist die Zahl „26“ in diesem Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf die Entfernung von der Ausfahrt bis Düsseldorf-Benrath","Auf die A 26","Auf die Autobahnausfahrt Nummer 26"],"co":[2],"ex":["Auf dem Verkehrszeichen ist die Entfernung zur Ausfahrt, nicht aber zu den Orten angegeben.","Das Verkehrszeichen, das eine Autobahn bezeichnet, ist ein anderes.","Diese Zahl gibt die Nummer der Ausfahrt an."],"i":["https://video2.kalaiwa.de/assets/2442005.webp"],"rn":976},{"n":"2.4.42-006","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf eine Bedarfsumleitung für den Autobahnverkehr","Auf eine U-Bahnstation","Auf die Bundesstraße 22"],"co":[0],"ex":["Dieses Verkehrszeichen weist auf eine Bedarfsumleitung hin. Das bedeutet, dass hier bei Bedarf eine Umleitung gefahren werden kann, die wieder auf die Autobahn führt. Dies ist für die Umfahrung von Staus gedacht.","U-Bahn-Stationen werden anders gekennzeichnet. Dies kann individuell von Stadt zu Stadt variieren.","Bundesstraßen sind mit gelben Verkehrszeichen beschildert. Blaue Verkehrszeichen kennzeichnen Autobahnen."],"i":["https://video4.kalaiwa.de/assets/2442006.webp"],"rn":977},{"n":"2.4.42-101","t":"Was gilt nach diesem Verkehrszeichen?","p":3,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Bei Dunkelheit darf mit Standlicht gefahren werden","Parkende Pkws dürfen mit der Parkleuchte gesichert werden","Überholen darf nicht durch Hupen angekündigt werden"],"co":[1,2],"ex":["Mit Standlicht darf nie gefahren werden, auch nicht innerorts. Bei Dunkelheit ist das Abblendlicht einzuschalten.","Innerorts dürfen parkende PKWs mit Parkleuchte gesichert werden.","Nur außerorts darf Überholen durch Hupen angekündigt werden. Innerorts ist dies untersagt."],"i":["https://video4.kalaiwa.de/assets/2442101.webp"],"rn":978},{"n":"2.4.42-102","t":"Wie darf hier mit Fahrzeugen bis 2,8 t zulässiger Gesamtmasse geparkt werden?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Pkws entsprechend der Abbildung","Wohnwagen entsprechend der Abbildung","Kleine Pkws auch quer zur Fahrtrichtung"],"co":[0,1],"ex":["Das Zeichen erlaubt Fahrzeugen mit einem zulässigen Gesamtgewicht bis zu 2,8 t das Parken auf Gehwegen.","Wohnwagen dürfen hier entsprechend der Abbildung parken.","Hier darf nur längs zur Fahrtrichtung geparkt werden."],"i":["https://video2.kalaiwa.de/assets/2442102.webp"],"rn":979},{"n":"2.4.42-103","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- Wasserstofftankstelle","- Autogastankstelle","- Erdgastankstelle"],"co":[0],"ex":["Dieses Verkehrszeichen weist auf eine Wasserstofftankstelle hin. Das H2 steht für Wasserstoff.","Das Verkehrszeichen, das auf eine Autogastankstelle hinweist, ist ähnlich zu diesem, nur dass statt dem H2 ein LPG (Liquid Petroleum Gas) neben der Zapfsäule steht.","Das Verkehrszeichen, das auf eine Erdgastankstelle hinweist, ist ähnlich zu diesem, nur dass statt dem H2 ein CNG (Compressed Natural Gas) neben der Zapfsäule steht."],"i":["https://video4.kalaiwa.de/assets/2442103.webp"],"rn":980},{"n":"2.4.42-104","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- Wasserstofftankstelle","- Erdgastankstelle","- Autogastankstelle"],"co":[1],"ex":["Das Verkehrszeichen, das auf eine Wasserstofftankstelle hindeutet, ist ähnlich zu diesem. Statt dem CNG steht hier jedoch ein H2.","Dieses Verkehrszeichen weist auf eine Erdgastankstelle hin. Das CNG steht für \"Compressed Natural Gas\".","Das Verkehrszeichen, das auf eine Autogastankstelle hinweist, ist ähnlich zu diesem. Statt dem CNG steht hier jedoch ein LPG für \"Liquid Petroleum Gas\"."],"i":["https://video4.kalaiwa.de/assets/2442104.webp"],"rn":981},{"n":"2.4.42-105","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- Erdgastankstelle","- Wasserstofftankstelle","- Autogastankstelle"],"co":[2],"ex":["Eine Erdgastankstelle würde mit einem ähnlichen Verkehrszeichen angekündigt werden, nur dass statt LPG ein CNG steht, was \"Compressed Natural Gas\" bedeutet.","Eine Erdgastankstelle würde mit einem ähnlichen Verkehrszeichen angekündigt werden, nur dass statt LPG ein H2 steht, was für Wasserstoff steht.","Dieses Verkehrszeichen kündigt eine Autogastankstelle an. LPG steht hier für \"Liquid Petroleum Gas\"."],"i":["https://video2.kalaiwa.de/assets/2442105.webp"],"rn":982},{"n":"2.4.42-106","t":"Worauf weist dieses Verkehrszeichen hin?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf die Möglichkeit zum Aufladen von Mobiltelefonen","Auf eine Ladestation für Elektrofahrzeuge","Auf Explosionsgefahr an einer Tankstelle durch Elektrogeräte"],"co":[1],"ex":["Mobiltelefone können an der Ladestation für Elektrofahrzeuge nicht aufgeladen werden.","Dieses Verkehrszeichen kennzeichnet eine Ladestation für Elektrofahrzeuge.","Darauf weist dieses Verkehrszeichen nicht hin. Es schildert eine Tankstelle für Elektrofahrzeuge aus."],"i":["https://video2.kalaiwa.de/assets/2442106.webp"],"rn":983},{"n":"2.4.42-107","t":"Worauf weist dieses Verkehrszeichen hin?","p":3,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Auf einen Fahrzeugverleih mit Reparaturwerkstatt („Pannenservice + Reparatur“)","Auf eine Tankstelle mit Waschanlage („Pflegen + Reinigen“)","Auf einen Parkplatz mit Anschluss an öffentliche Verkehrsmittel („Parken + Reisen“)"],"co":[2],"ex":["Das Verkehrszeichen steht nicht für \"Pannenservice & Reparatur\", sondern für \"Parken & Reisen\".","Darauf weist dieses Verkehrszeichen nicht hin.","Dieses Verkehrszeichen steht für einen Parkplatz, der an öffentliche Verkehrsmittel angebunden ist."],"i":["https://video2.kalaiwa.de/assets/2442107.webp"],"rn":984},{"n":"2.4.42-110","t":"Welches Dokument erlaubt es Ihnen, hier zu parken?","p":2,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["Der EU-Parkausweis eines von mir beförderten Schwerbehinderten","Mein EU-Parkausweis für Schwerbehinderte","Mein Anwohnerparkausweis"],"co":[0,1],"ex":["Dir ist es erlaubt hier zu parken, wenn du eine Person mit einem EU-Parkausweis für Schwerbehinderten beförderst.","Du darfst auf dem Parkplatz mit diesem Schild parken, wenn du selbst einen EU-Parkausweis für Schwerbehinderte besitzt.","Mit einem Anwohnerparkausweis darfst du an dieser Stelle nicht parken, da das Verkehrsschild einen Parkplatz für schwerbehinderte Personen markiert."],"i":["https://video2.kalaiwa.de/assets/2442110.webp"],"rn":985},{"n":"2.4.42-008-M","t":"Was gilt nach diesem Verkehrszeichen?","p":3,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- auf dem rechten Fahrstreifen schneller fahren als Fahrzeuge auf dem linken Fahrstreifen","- den Fahrstreifen für meine Richtung frei wählen","- aufgrund der mehrstreifigen Fahrbahn schneller als 50 km/h fahren"],"co":[0,1],"ex":["Auf zweispurigen Straßen innerhalb einer Ortschaft dürfen Fahrzeuge auf dem rechten Fahrstreifen auch schneller fahren als Fahrzeuge auf dem linken Fahrstreifen.","Innerorts darfst du bei mehrspurigen Straßen die Fahrbahn für deine Richtung frei wählen.","Trotz der mehrspurigen Fahrbahn darfst du innerorts nicht schneller als 50 km/h fahren."],"i":["https://video4.kalaiwa.de/assets/2442008m.webp"],"rn":986},{"n":"2.4.42-109-M","t":"Was ist in dieser Situation richtig?","p":4,"c":"2.4.42","ch":"Richtzeichen","th":"Verkehrszeichen","o":["- befahren, nachdem ich durch sorgfältige Verkehrsbeobachtung eine Gefährdung von Radfahrern ausgeschlossen habe","- nicht befahren","- nur so lange befahren, bis ich an dem Lkw vorbeigefahren bin"],"co":[0,2],"ex":["Um gefahrlos an dem Lkw vorbeifahren zu können, darfst du den Schutzstreifen befahren. Stelle sicher, dass du keine Radfahrer auf dem Schutzstreifen gefährdest.","Der Schutzstreifen ist Teil der Fahrbahn und darf bei Bedarf und wenn der Radverkehr dadurch nicht gefährdet wird, von Kraftfahrzeugen befahren werden.","Du darfst den Schutzstreifen nur befahren, um an dem Lkw vorbeizukommen und solange du den Radverkehr nicht gefährdest. Wechsle deshalb nach dem Passieren wieder zurück auf die Fahrspur."],"i":["https://video4.kalaiwa.de/assets/2442109m.webp"],"rn":987},{"n":"2.4.43-002","t":"Sie brauchen Hilfe auf der Autobahn. Welche Information gibt Ihnen dafür der Pfeil am Leitpfosten?","p":2,"c":"2.4.43","ch":"Verkehrseinrichtungen","th":"Verkehrszeichen","o":["Nächster Parkplatz in Pfeilrichtung","Nächste Ausfahrt in Pfeilrichtung","Nächste Notrufsäule in Pfeilrichtung"],"co":[2],"ex":["Nicht der nächste Parkplatz, sondern die nächstgelegene Notrufsäule ist der Pfeilrichtung zu entnehmen.","Der Pfeil zeigt an, in welcher Richtung die nächstgelegene Notrufsäule steht.","Der Pfeil auf dem Leitpfosten zeigt die Richtung an, in der die nächstgelegene Notrufsäule steht."],"i":["https://video2.kalaiwa.de/assets/2443002.webp"],"rn":988},{"n":"2.5.01-007","t":"Warum ist scharfes Anfahren zu vermeiden?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Weil stärkerer Reifenverschleiß entsteht","Weil dadurch die Hinterradbremse stark belastet wird","Weil der entstehende Lärm andere belästigt"],"co":[0,2],"ex":["Die Reifen werden bei scharfem Anfahren unnötig stark abgenutzt.","Bei scharfem Anfahren wird die Hinterradbremse nicht belastet, da hier Gas gegeben und nicht abgebremst wird.","Durch scharfes Anfahren entsteht vermeidbarer Lärm."],"rn":989},{"n":"2.5.01-011","t":"Was hat das Fahren mit Winterreifen in den Sommermonaten zur Folge?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- der Kraftstoffverbrauch","- die Fahrstabilität","- der Reifenverschleiß"],"co":[0,2],"ex":["Aufgrund des weicheren Gummis der Winterreifen ist der Rollwiderstand größer. Damit steigt der Kraftstoffverbrauch.","Die Fahrstabilität wird hierdurch nicht erhöht. Ganz im Gegenteil. Das Fahrverhalten bei Winterreifen in sommerlichen Monaten ist sogar unsicherer.","Winterreifen bestehen aus weicherem Gummi und verursachen bei sommerlichen Temperaturen eine höhere Reibung. Somit ist auch der Reifenverschleiß höher."],"rn":990},{"n":"2.5.01-012","t":"Welche Kraftfahrzeuge dürfen in die so gekennzeichnete Umweltzone einfahren?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Krafträder","Kraftfahrzeuge mit einer grünen Feinstaub-Plakette","Kraftfahrzeuge, die die Anforderungen an eine grüne Feinstaub-Plakette erfüllen, auch wenn keine solche Plakette angebracht ist"],"co":[0,1],"ex":["Krafträder sind von den Regelungen der Umweltzone ausgenommen und dürfen ohne Einschränkung fahren.","Mit einer grünen Plakette darfst du hier einfahren.","Eine Plakette ist Pflicht, sonst drohen Geldstrafen."],"i":["https://video2.kalaiwa.de/assets/2501012.webp"],"rn":991},{"n":"2.5.01-013","t":"Sie möchten Ihr Fahrzeug waschen. Wo sollten Sie dies im Interesse des Umweltschutzes tun?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Auf einem Parkplatz","Auf einer öffentlichen Straße","In einer Autowaschanlage"],"co":[2],"ex":["Hierdurch verschmutzt du den Parkplatz. Säubere dein Auto in einer Autowaschanlage.","Wäscht du den Auto auf einer öffentlichen Straße, dann wird diese verdreckt und das schmutzige Wasser läuft ungefiltert ins Abwasser.","Die Nutzung einer Autowaschanlage ist die umweltschonendste Variante, um sein Fahrzeug sauber zu bekommen. Die meisten Autowaschanlagen fangen das Schmutzwasser auf, filtern dieses und verwenden es mehrmals."],"rn":992},{"n":"2.5.01-014","t":"Was erhöht den Kraftstoffverbrauch Ihres Fahrzeugs deutlich?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- des Navigationsgerätes","- der Sitzheizung","- der Klimaanlage"],"co":[1,2],"ex":["Die Nutzung des Navigationssystems erhöht den Kraftstoffverbrauch nicht merklich.","Die dauerhafte Benutzung der Sitzheizung erhöht den Kraftstoffverbrauch deines Fahrzeugs erheblich.","Wenn du die Klimaanlage deines Fahrzeugs lange und häufig benutzt, wird der Spritverbrauch hierdurch deutlich gesteigert."],"rn":993},{"n":"2.5.01-016","t":"Welche Auswirkungen hat das Fahren mit hoher Geschwindigkeit bei Kraftfahrzeugen mit Verbrennungsmotor?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Der Kraftstoffverbrauch erhöht sich","Der Schadstoffausstoß erhöht sich","Der Lärmpegel verringert sich"],"co":[0,1],"ex":["Das Fahren mit hoher Geschwindigkeit führt zu einem größeren Kraftstoffverbrauch.","Je höher die Geschwindigkeit, desto mehr Schadstoffe werden ausgestoßen.","Der Lärmpegel wird hier eher erhöht."],"rn":994},{"n":"2.5.01-018","t":"Warum wirkt sich eine umweltbewusste Fahrweise auch günstig auf die Verkehrssicherheit aus?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- hohe Geschwindigkeiten vermieden werden","- vorausschauend gefahren wird","- mit alternativen Kraftstoffen nur langsam gefahren werden kann"],"co":[0,1],"ex":["Beim umweltbewussten Fahren werden hohe Geschwindigkeiten vermieden. Dadurch kann die Anzahl und die Schwere von Unfällen reduziert werden.","Eine umweltbewusste Fahrweise beinhaltet auch vorausschauendes Fahren. Dadurch entsteht eine erhöhte Verkehrssicherheit.","Mit alternativen Kraftstoffen kann auch schnell gefahren werden."],"rn":995},{"n":"2.5.01-106","t":"Wodurch erhöht sich der Kraftstoffverbrauch Ihres Pkws?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch Dachgepäckträger oder Skihalter","Durch Mitführen unnötiger Gegenstände","Durch zu hohen Reifendruck"],"co":[0,1],"ex":["Dachgepäckträger oder Skihalter erhöhen den Luftwiderstand. Hierdurch wird ein größerer Luftwiderstand notwendig, wodurch mehr Kraftstoff verbraucht wird.","Je schwerer ein Fahrzeug ist, desto mehr Kraftstoff wird verbraucht, um dieses zu bewegen.","Das Fahren mit zu hohem Reifendruck verringert sogar den Kraftstoffverbrauch, weil weniger Reibung entsteht. Allerdings ist so auch weniger Haftung vorhanden und der Reifen wird schneller abgenutzt."],"rn":996},{"n":"2.5.01-107","t":"Wie können Sie Kraftstoff sparen?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Mindestens Reifendruck nach Betriebsanleitung einhalten","Nicht im höchsten Gang fahren","Dachgepäckträger oder Skihalter abnehmen"],"co":[0,2],"ex":["Ist der Reifendruck zu gering, dann erhöht sich der Rollwiderstand. Es ist eine stärkere Motorleistung erforderlich. Dadurch wird mehr Kraftstoff verbrannt. Hat der Luftdruck den richtigen Wert, dann ist der Rollwiderstand entsprechend geringer und es wird weniger Kraftstoff verbraucht.","Bei der richtigen Drehzahl hat man im höchsten Gang den geringsten Kraftstoffverbrauch.","Dachgepäckträger und Skihalter erhöhen den Luftwiderstand und damit den Kraftstoffverbrauch."],"rn":997},{"n":"2.5.01-111","t":"Wie kann Lärm vermindert werden?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch Fahren mit hoher Geschwindigkeit","Durch Fahren mit hoher Motordrehzahl","Durch Fahren im 4. oder 5. Gang in Ortschaften"],"co":[2],"ex":["Durch Fahren mit hoher Geschwindigkeit wird kein Lärm vermindert. Im Gegenteil, hierdurch entsteht Lärm","Beim Fahren mit hoher Drehzahl entsteht ein vermeidbarer hoher Lärmpegel. Fahre in hohen Gängen und somit mit niedriger Drehzahl, um Lärm zu vermindern.","In hohen Gängen arbeitet der Motor mit niedriger Drehzahl und ist somit leiser. So kann Lärm vermindert werden."],"rn":998},{"n":"2.5.01-117","t":"Wo ist die Feinstaub-Plakette zur Kennzeichnung schadstoffarmer Fahrzeuge anzubringen?","p":4,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Deutlich sichtbar auf der Innenseite der Heckscheibe","Deutlich sichtbar auf der Außenseite der Windschutzscheibe","Deutlich sichtbar auf der Innenseite der Windschutzscheibe"],"co":[2],"ex":["Du musst die Feinstaub-Plakette deutlich sichtbar auf der Innenseite der Windschutzscheibe anbringen.","Die Feinstaub-Plakette muss innenseitig auf der Windschutzscheibe angebracht sein.","Hier ist die Feinstaub-Plakette anzubringen."],"rn":999},{"n":"2.5.01-119","t":"Wo können Sie Ihr Gepäck unterbringen, um den Kraftstoffverbrauch nicht unnötig zu erhöhen?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Im Kofferraum","Auf dem Dachgepäckträger","Hinter den Vordersitzen"],"co":[0,2],"ex":["Der Kofferraum dient als Stauraum für Gepäck. Seine Beladung erhöht den Kraftstoffverbrauch nicht erheblich.","Wenn du dein Gepäck auf dem Dachgepäckträger anbringst, verbraucht das mehr Kraftstoff, als wenn du es im Innenraum deines Fahrzeugs verräumst.","Hinter den Vordersitzen und im Kofferraum kannst du Gepäck verstauen, ohne hierdurch unnötig Kraftstoff zu verbrauchen."],"rn":1000},{"n":"2.5.01-121","t":"Welche Maßnahme kann zum umweltschonenden Fahren beitragen?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Die Nutzung von Fahrzeugen mit Elektroantrieb","Die Bildung von Fahrgemeinschaften","Die Teilnahme an einem fahrpraktischen Training zur kraftstoffsparenden Fahrweise"],"co":[0,1,2],"ex":["Ein Elektrofahrzeug versursacht beim Fahren kein CO2 und ist deshalb gut für die Umwelt.","Fahrgemeinschaften entlasten den Verkehr und schonen die Umwelt. Es werden weniger Fahrzeuge genutzt.","Eine kraftstoffsparende Fahrweise kann man erlernen. Dafür gibt es auch Trainings."],"rn":1001},{"n":"2.5.01-122","t":"Wodurch können Sie Kraftstoff sparen, wenn Sie einen Pkw mit Automatikgetriebe fahren?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Beim Befahren eines Gefälles den Motor ausschalten","Beim Anfahren auf den \"Kick-down\" verzichten","Beim Fahren den Eco-Modus nutzen"],"co":[1,2],"ex":["Den Motor sollte man beim Fahren nie ausmachen.","Der Kraftstoffverbrauch ist beim Kick-down maximal.","Mit dem Eco-Modus kannst du Sprit sparen."],"rn":1002},{"n":"2.5.01-123","t":"Welche Pkws, die eine ausgewiesene Umweltzone befahren, unterliegen der Kennzeichnungspflicht mit einer Feinstaub-Plakette?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- Elektromotor","- Dieselmotor","- Ottomotor"],"co":[0,1,2],"ex":["Ein Pkw mit Elektromotor unterliegt der Kennzeichnungspflicht.","Ein Pkw mit Dieselmotor unterliegt der Kennzeichnungspflicht.","Ein Pkw mit Ottomotor unterliegt der Kennzeichnungspflicht."],"rn":1003},{"n":"2.5.01-124","t":"Welche Auswirkung kann das Hören sehr lauter Musik beim Autofahren haben?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Signale des übrigen Verkehrs werden nicht wahrgenommen","Andere Verkehrsteilnehmer werden belästigt","Die Reaktionsfähigkeit des Fahrers verbessert sich"],"co":[0,1],"ex":["Durch zu laute Musik können Warnsignale etc. der restlichen Verkehrsteilnehmer überhört werden.","Zu laute Musik kann auch die anderen Verkehrsteilnehmer belästigen, stören und dadurch gefährden.","Die Reaktionsfähigkeit des Fahrers verschlechtert sich durch die laute Musik und die dadurch entstehende geringere Konzentrationsfähigkeit."],"rn":1004},{"n":"2.5.01-125","t":"Der Luftwiderstand wirkt sich auf den Kraftstoffverbrauch eines Fahrzeugs aus. Was beeinflusst den Luftwiderstand am stärksten?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Die gefahrene Geschwindigkeit","Die Profiltiefe der Reifen","Die Anzahl der Mitfahrer"],"co":[0],"ex":["Umso schneller du fährst, umso stärker wird der Luftwiderstand, der auf dein Fahrzeug einwirkt. Eine Verdopplung der Geschwindigkeit führt zu 4-fachem Luftwiderstand. Die Geschwindigkeit ist der größte Beitrag zum Luftwiderstand.","Die Profiltiefe der Reifen wirkt sich zum größten Teil auf den Rollwiderstand der Reifen aus.","Die Anzahl der Mitfahrer wirkt sich nicht direkt auf den Luftwiderstand aus."],"rn":1005},{"n":"2.5.01-126","t":"Sie müssen wegen geschlossener Bahnschranken warten. Wie können Sie dabei die Umwelt schonen?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch Einlegen des ersten Gangs","Durch Nutzung der Start-Stopp-Automatik","Durch Betätigen der Handbremse"],"co":[1],"ex":["Einlegen des ersten Gangs wirkt sich nicht positiv auf die Umweltbelastung aus.","Durch die Nutzung der Start-Stopp-Automatik kann das Fahrzeug während des Wartens ausgestellt und mit wenig Aufwand sofort wieder angestellt werden. Somit kann der Schadstoffausstoß minimiert werden.","Das Betätigen der Handbremse hat keinen Einfluss auf den Schadstoffausstoß des Fahrzeugs."],"rn":1006},{"n":"2.5.01-127","t":"Was erhöht die Reichweite eines Elektrofahrzeugs?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Reduzierung der Heiztemperatur","Kurzes starkes Beschleunigen","Nutzung einer hohen Stufe der Energierückgewinnung (Rekuperation)"],"co":[0,2],"ex":["Die Heizung beim E-Auto wird direkt von der Batterie gespeist und verbraucht somit Energie, die man auch zum Fahren verwenden könnte. Die Heizung eines Verbrenners nutzt die Wärme, die ein Verbrennungsmotor sowieso produziert.","Durch kurzes, starkes Beschleunigen kann die Reichweite nicht erhöht werden.","Ein Elektroauto hat keinen Effekt wie die Motorbremse eines Verbrenners. Dadurch verliert das E-Auto nicht so schnell an Geschwindigkeit. Bist du dieses Verhalten nicht gewöhnt, musst du öfter bremsen. Bremst du nur leicht, wird per Elektromotor gebremst und die Bewegungsenergie zurückgewonnen. Bremst du stärker, wird mechanisch gebremst und die Bewegungsenergie wird nicht zurückgewonnen. Durch eine hohe Rekuperationsstufe verhält sich ein E-Auto wie ein Verbrenner, dadurch musst du eventuell weniger stark, also mechanisch, bremsen."],"rn":1007},{"n":"2.5.01-128","t":"Welchen Vorteil bietet die Rekuperation an einem Elektrofahrzeug?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- ermöglicht eine Energierückgewinnung aus dem Bremsvorgang","- erhöht die Reichweite","- schont die Betriebsbremsanlage"],"co":[0,1,2],"ex":["Durch die Rekuperation funktioniert der Motor des Elektrofahrzeugs beim Bremsen wie ein Generator. Das Bremsen ist damit regenerativ. Das heißt, es erzeugt Strom und lädt automatisch den Akku des Autos auf.","Durch die Energierückgewinnung mittels Rekuperation kann das Elektrofahrzeug weitere Strecken zurücklegen, da der Akku bei Bremsen aufgeladen wird und folglich länger hält.","Durch den Vorgang des Rekuperation-Bremssystems wir die Betriebsbremsanlage weniger mechanisch belastet und damit geschont."],"rn":1008},{"n":"2.5.01-129","t":"Ihr Pkw ist mit einer Start-Stopp-Automatik ausgerüstet. Welchen Vorteil bietet die Nutzung dieses Fahrzeugsystems für den Umweltschutz?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- den Reifenabrieb","- die Lärmbelastung","- den Kraftstoffverbrauch"],"co":[1,2],"ex":["Die Start-Stopp-Automatik hat keinen Einfluss auf den Reifenabrieb.","Durch das Abschalten des Motors, etwa an Ampeln, kann durch die Start-Stopp-Automatik die Lärmbelastung reduziert werden.","Durch eine Start-Stopp-Automatik können im Stadtverkehr oder im Stau bis zu 15 Prozent Kraftstoff eingespart werden."],"rn":1009},{"n":"2.5.01-130","t":"Sie fahren einen Pkw mit der Antriebsart Plug-in-Hybrid. Wie können Sie den Kraftstoffverbrauch optimieren?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Ich lade die Batterie regelmäßig am Stromnetz auf","Ich nutze durch meine Fahrweise den elektrischen Antrieb","Ich nutze ausschließlich die Rekuperation zum Aufladen der Batterie"],"co":[0,1],"ex":["Durch das regelmäßige Aufladen der Batterie deines Plug-in-Hybrids am Stromnetz, kannst du den elektrischen Motor deines Fahrzeugs häufiger nutzen. So reduzierst du den Kraftstoffverbrauch oder minimierst ihn durch rein elektrisches Fahren.","Durch eine vorausschauende Fahrweise – mit sanftem Beschleunigen und rechtzeitigem Abbremsen – kannst du den Kraftstoffverbrauch deines Fahrzeugs reduzieren. Bei dieser Fahrweise kommt häufig der Elektromotor zum Einsatz, was den Verbrauch an Kraftstoff verringert.","Die Energiegewinnung durch Rekuperation reicht nicht aus, um die Batterie deines Plug-in-Hybrids vollständig aufzuladen. So kannst du den elektrischen Antrieb deines Fahrzeugs weniger nutzen und bist häufiger auf den Verbrennungsmotor angewiesen, was deinen Kraftstoffverbrauch erhöht."],"rn":1010},{"n":"2.5.01-207","t":"Wie können Sie bereits bei der Planung Ihrer Fahrten zum Umweltschutz beitragen?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- plane, öffentliche Verkehrsmittel statt des eigenen Fahrzeugs zu nutzen","- Fahrgemeinschaften mit anderen Fahrzeugnutzern bilde","- mehrere Fahrziele in einer Fahrt zusammenlege"],"co":[0,1,2],"ex":["So sparst du Kraftstoff und Geld und belastest die Umwelt nicht unnötig.","Wenn mehrere Personen ein Fahrzeug nutzen, statt jeder einzeln, spart das Kraftstoff und kommt der Umwelt zugute.","So fährst du nicht mehrmals sondern alle Fahrziele in einem ab. Das schont die Umwelt und deinen Geldbeutel, da du so weniger Kraftstoff verbrauchst."],"rn":1011},{"n":"2.5.01-208","t":"Wie durchfahren Sie sicher eine Gefällestrecke?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- in einen Gang, in dem ich wenig bremsen muss","- in den Leerlauf","- die Zündung aus"],"co":[0],"ex":["So bremst du mit dem Motor und schonst deine Bremsen.","Du musst einen Gang einlegen, bei dem die Motorbremse aktiv wird und die normalen Bremsen geschont werden. Je niedriger der Gang, desto stärker wirkt die Motorbremse beim Fahren im Gefälle.","Die Zündung solltest du in keinem Fall ausschalten. Du musst vom Gaspedal gehen und in einen Gang schalten, bei dem der Motor abbremst."],"rn":1012},{"n":"2.5.01-209","t":"Welche Kraftfahrzeuge dürfen ohne Feinstaub-Plakette in eine Umweltzone einfahren?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Alle zwei- und dreirädrigen Kraftfahrzeuge","Alle Kraftfahrzeuge mit Katalysator","Alle land- und forstwirtschaftlichen Zugmaschinen"],"co":[0,2],"ex":["Alle zwei- und dreirädrigen Kraftfahrzeuge dürfen auch ohne Feinstaub-Plakette in eine Umweltzone einfahren.","Kraftfahrzeuge mit Katalysator dürfen nur in eine Umweltzone einfahren, wenn eine entsprechende Feinstaub-Plakette am Auto angebracht ist.","Land- und forstwirtschaftlichen Zugmaschinen ist die Einfahrt in eine Umweltzone auch ohne Feinstaub-Plakette gestattet."],"rn":1013},{"n":"2.5.01-211","t":"Warum sind Kurzstreckenfahrten mit kaltem Motor besonders umweltschädlich?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["- der Materialverschleiß größer ist","- die Fahrzeugbatterie überladen wird","- mehr Kraftstoff verbraucht wird"],"co":[0,2],"ex":["Motoröl schmiert erst bei bestimmten Temperaturen optimal. Bis dahin besteht ein erhöhter Materialverschleiß.","Die Fahrzeugbatterie wird bei Kurzstreckenfahrten nicht überladen.","Wenn der Motor kalt ist, sind Verschleiß und innerer Widerstand höher und der Katalysator arbeitet noch nicht richtig."],"rn":1014},{"n":"2.5.01-212","t":"Wodurch entsteht vermeidbarer Lärm?","p":3,"c":"2.5.01","ch":"Umweltschutz","th":"Umweltschutz","o":["Durch Fahren mit einem Dachgepäckträger","Durch Hupen zur Begrüßung","Durch heftiges Zuschlagen von Türen"],"co":[1,2],"ex":["Fahren mit einem Dachgepäckträger verursacht keinen Lärm.","Die Hupe ist ein Warnsignal und darf nur hierfür verwendet werden.","Durch heftiges Zuschlagen von Türen entsteht ein Lärm, der vermeidbar ist."],"rn":1015},{"n":"2.6.01-003","t":"Woran können Sie erkennen, wann Sie Ihr Fahrzeug zur nächsten Hauptuntersuchung vorführen müssen?","p":2,"c":"2.6.01","ch":"Untersuchung Der Fahrzeuge","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["An der Prüfplakette auf dem hinteren amtlichen Kennzeichen","An der Eintragung in der Zulassungsbescheinigung Teil I","An der Eintragung in der Bedienungsanleitung meines Fahrzeugs"],"co":[0,1],"ex":["Von der Prüfplakette am hinteren amtlichen Kennzeichen kann die nächste fällige Hauptuntersuchung abgelesen werden.","In der Zulassungsbescheinigung Teil I steht, wann die nächste Hauptuntersuchung fällig ist.","Hier ist keine Information über die Hauptuntersuchung enthalten."],"rn":1016},{"n":"2.6.01-106","t":"Sie haben Ihren zugelassenen Wohnanhänger während des Winterhalbjahres auf einem Campingplatz abgestellt. Was gilt hinsichtlich der Hauptuntersuchung?","p":2,"c":"2.6.01","ch":"Untersuchung Der Fahrzeuge","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Der auf der Prüfplakette angegebene Termin verschiebt sich um die Standzeit","Der auf der Prüfplakette angegebene Termin ist einzuhalten"],"co":[1],"ex":["Standzeiten verlängern nicht den angegebenen Prüfungstermin für die nächste Hauptuntersuchung.","Der auf der Prüfplakette ersichtliche Termin kündigt die nächste Hauptuntersuchung an."],"rn":1017},{"n":"2.6.01-108","t":"Sie haben einen 3 Jahre alten Pkw gekauft und möchten diesen privat nutzen. Die Hauptuntersuchung ist neu. Welche Frist gilt für die nächste Hauptuntersuchung?","p":2,"c":"2.6.01","ch":"Untersuchung Der Fahrzeuge","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","na":"Antwort: Die Frist beträgt 24 Monate","e":"Nach der ersten Hauptuntersuchung müssen Pkws alle 2 Jahre weiteren Hauptuntersuchungen unterzogen werden. Im Fahrzeugschein bzw. in der Zulassungsbescheinigung Teil I ist dieser Zeitpunkt für die Hauptuntersuchung eingetragen. Er ist außerdem auf der Prüfplakette des hinteren amtlichen Kennzeichens ersichtlich.","rn":1018},{"n":"2.6.02-027","t":"Welche Dokumente müssen Sie mitführen, wenn Sie ein zulassungspflichtiges Kraftfahrzeug führen möchten?","p":2,"c":"2.6.02","ch":"Zulassung Zum Strassenverkehr Fahrzeugpapiere Fahrerlaubnis","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Den Führerschein","Die Zulassungsbescheinigung Teil II (Fahrzeugbrief)","Die Zulassungsbescheinigung Teil I (Fahrzeugschein)"],"co":[0,2],"ex":["Du musst, sobald du ein zulassungspflichtiges Fahrzeug fährst, den Führerschein dabei haben.","Diese musst du nicht mit dir führen. Den Führerschein und die Zulassungsbescheinigung Teil I musst du jedoch mit dir führen.","Den Fahrzeugschein musst du mit dir führen, wenn du ein zulassungspflichtiges Kraftfahrzeug nutzt."],"rn":1019},{"n":"2.6.02-030","t":"Durch eine technische Änderung an Ihrem Fahrzeug ist die Betriebserlaubnis erloschen. Mit welchen Folgen müssen Sie rechnen, wenn Sie das Fahrzeug dennoch auf öffentlichen Straßen benutzen?","p":3,"c":"2.6.02","ch":"Zulassung Zum Strassenverkehr Fahrzeugpapiere Fahrerlaubnis","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Mit dem Verlust meines Versicherungsschutzes","Mit einem Bußgeld","Mit einem Eintrag im Fahreignungsregister"],"co":[0,1,2],"ex":["Der Verlust des Versicherungsschutzes ist eine mögliche Konsequenz beim Fahren ohne gültige Betriebserlaubnis.","Ohne Betriebserlaubnis darfst du das Fahrzeug nicht benutzen und musst somit mit einem Bußgeld rechnen.","Fährst du ohne gültige Betriebserlaubnis mit deinem Kraftfahrzeug, dann folgt neben einem Bußgeld ein Eintrag im Fahrzeugregister."],"rn":1020},{"n":"2.6.02-036","t":"Wegen einer technischen Änderung an Ihrem Fahrzeug ist eine Begutachtung erfolgt. Wozu sind Sie verpflichtet?","p":3,"c":"2.6.02","ch":"Zulassung Zum Strassenverkehr Fahrzeugpapiere Fahrerlaubnis","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- an der dafür vorgesehenen Stelle in der Zulassungsbescheinigung Teil II einkleben","- mitführen und gegebenenfalls die Zulassungsbescheinigung Teil I berichtigen lassen","- dem Fahrzeughersteller übersenden"],"co":[1],"ex":["Das musst du nicht. Es muss jedoch die Zulassungsbescheinigung Teil I gegebenenfalls korrigiert werden.","Wird an deinem Fahrzeug eine technische Änderung vorgenommen, dann muss das Gutachten oder die Bestätigung mitgeführt und der Teil I der Zulassungsbescheinigung gegebenenfalls aktualisiert werden.","Hierzu bist du nicht verpflichtet."],"rn":1021},{"n":"2.6.02-038","t":"Nach Umbauten an Ihrem Fahrzeug ist eine Begutachtung erforderlich. Wann muss diese erfolgen?","p":3,"c":"2.6.02","ch":"Zulassung Zum Strassenverkehr Fahrzeugpapiere Fahrerlaubnis","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Unverzüglich nach dem Umbau","Bei der nächsten Inspektion","Nach Aufforderung durch die Zulassungsstelle"],"co":[0],"ex":["Umbauten müssen direkt nach dem Umbau begutachtet werden.","Eine Begutachtung bei der nächsten Inspektion ist zu spät. Es muss eine sofortige Begutachtung stattfinden.","Du musst deine Umbauten ohne Aufforderung direkt begutachten lassen."],"rn":1022},{"n":"2.6.03-001","t":"Was ist beim Rückwärtsfahren mit einer Fahrzeugkombination richtig, wenn die Sicht nach hinten beeinträchtigt ist?","p":4,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Wenn die Sichtverbindung zur einweisenden Person abreißt, muss angehalten werden","Nur beim Einfahren in eine Vorfahrtstraße ist Einweisung erforderlich","Auf einem Betriebsgelände kann auf Einweisung verzichtet werden"],"co":[0],"ex":["Die Sichtverbindung zur einweisenden Person ist unabdingbar, um ein sicheres Rückwärtsfahren zu gewährleisten.","Du solltest das Rückwärtsfahren in eine Vorfahrtsstraße mit Fahrzeugkombination nach Möglichkeit vermeiden. Ist dies nicht möglich, dann ist hier ein durchgehender Blickkontakt zur einweisenden Person notwendig.","Auch auf Betriebsgelände kann Einweisen notwendig sein."],"rn":1023},{"n":"2.6.03-111","t":"Sie möchten einen Anhänger mitführen. Wann müssen zusätzliche Rückspiegel an Ihrem Kraftfahrzeug angebracht werden?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Wenn die Ladefläche des Anhängers eine Breite von 1,5 m und eine Höhe von 1 m überschreitet","Wenn nicht alle wesentlichen Verkehrsvorgänge ohne zusätzliche Rückspiegel beobachtet werden können","Wenn es sich um einen Wohnanhänger oder um einen land- und forstwirtschaftlich genutzten Anhänger handelt"],"co":[1],"ex":["Sobald zusätzliche Rückspiegel notwendig wären, müssen diese montiert werden.","Ist die Einsicht über die normalen Rückspiegel eingeschränkt, dann müssen zusätzliche Rückspiegel am Kraftfahrzeug angebracht werden.","Zusätzliche Rückspiegel müssen angebracht werden, sobald diese aufgrund eingeschränkter Rücksicht notwendig sind."],"rn":1024},{"n":"2.6.03-112","t":"Sie möchten einen gebremsten Anhänger mitführen. Wo finden Sie Angaben bzw. Hinweise zur zulässigen Anhängelast Ihres Pkws?","p":2,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["In der Zulassungsbescheinigung Teil I meines Anhängers","Im Versicherungsschein","In der Zulassungsbescheinigung Teil I meines Pkws"],"co":[2],"ex":["Hier findest du keine Angaben zur zulässigen Anhängelast.","Im Versicherungsschein sind keine Informationen über die zulässige Anhängelast enthalten. Diese findest du in der Zulassungsbescheinigung Teil I.","Die Zulassungsbescheinigung Teil I gibt Auskunft über die zulässige Anhängelast des PKWs."],"rn":1025},{"n":"2.6.03-113","t":"Sie möchten an Ihren Pkw einen Anhänger ankuppeln. Wo können Sie die Angabe über die zulässige Stützlast Ihres Pkws finden?","p":2,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- Zulassungsbescheinigung Teil II","- Betriebsanleitung","- Zulassungsbescheinigung Teil I"],"co":[1,2],"ex":["Diese gibt keine Auskunft über die zulässige Stützlast.","In der Betriebsanleitung sind Informationen über die zulässige Stützlast des PKWs enthalten.","Die Zulassungsbescheinigung Teil I gibt dir Auskunft über die zulässige Stützlast deines PKWs."],"rn":1026},{"n":"2.6.03-114","t":"Sie möchten einen Anhänger mitführen. Was müssen Sie beachten?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- Zuladung des Anhängers","- Stützlast an der Anhängekupplung","- Anhängelast des Zugfahrzeugs"],"co":[0,1,2],"ex":["Das tatsächliche Gewicht des Anhängers (Leergewicht + Zuladung) darf das zulässige Gesamtgewicht bzw. die zulässige Anhängelast nicht übersteigen.","Die Stützlast ist die Masse, mit der der Anhänger die Anhängekupplung deines Autos nach unten drückt. Die vorgeschriebene minimale Stützlast beträgt 4% des tatsächlichen Gesamtgewichts des Hängers oder 25kg.","Du darfst die Anhängerlast laut Zulassungsbescheinigung Teil I oder Betriebsanleitung nicht überschreiten. Beachte auch die Achslast."],"rn":1027},{"n":"2.6.03-115","t":"Sie fahren mit einem Anhänger auf einer Straße mit Schlaglöchern. Ihre Fahrzeugkombination schaukelt sich auf. Wie müssen Sie sich jetzt verhalten?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- die Geschwindigkeit verringern, um ein Schleudern zu verhindern","- beschleunigen, um die Fahrzeugkombination gestreckt zu halten","- schnell gegenlenken, um ein Schleudern zu verhindern"],"co":[0],"ex":["Durch das Verringern der Geschwindigkeit kannst du das Schleudern verhindern.","Würdest du beschleunigen, würde die Fahrzeugkombination durch die Schlaglöcher noch mehr schaukeln und ins Schleudern geraten.","Durch Gegenlenken verstärkst du das Schaukeln."],"rn":1028},{"n":"2.6.03-116","t":"Wie viele Anhänger dürfen hinter einem Pkw mitgeführt werden?","p":2,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","na":"1 Anhänger","e":"Hinter einem Pkw darfst du immer nur einen Anhänger mitführen.","rn":1029},{"n":"2.6.03-117","t":"Sie möchten einen Anhänger mit einer zulässigen Gesamtmasse über 750 kg mit Ihrem Pkw verbinden. Was müssen Sie dabei beachten?","p":2,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Das Abreißseil muss sachgerecht angebracht sein","Der Handgriff der Zugkugelkupplung muss mechanisch und optisch überprüft werden","Die Beleuchtungseinrichtung des Anhängers muss nach dem Ankuppeln auf ihre Funktion hin überprüft werden"],"co":[0,1,2],"ex":["Anhänger mit einer zulässigen Gesamtmasse von über 750 kg müssen zusätzlich mit einem Abreißseil gesichert werden. Prüfe vor Fahrtantritt, ob es sachgerecht angebracht ist.","Damit der Anhänger richtig angeschlossen ist, muss die Kupplungsklaue den Kugelkopf vollständig umschließen. Wenn die Sicherung einrastet, ist gewährleistet, dass sich die Kupplungsklaue nicht selbstständig lösen kann. Prüfe dies mit Hand und Auge.","Bevor du losfährst, musst du überprüfen, ob alle Lichter des Anhängers funktionieren."],"rn":1030},{"n":"2.6.03-118","t":"Sie fahren einen Pkw mit einem voll beladenen auflaufgebremsten Anhänger. Welche Besonderheit ist zu beachten?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Die Auflaufbremse ist bei einer bergauf stehenden Fahrzeugkombination unwirksam","Vor dem Trennen der Fahrzeugkombination muss die Feststellbremse des Anhängers angezogen werden","Bei längeren Bergabfahrten kann es zur Überhitzung der Anhängerbremse kommen"],"co":[0,1,2],"ex":["Die Auflaufbremse wird nur aktiviert, wenn der Anhänger auf das Zugfahrzeug aufläuft. Wenn du bergauf fährst, ist das beim Bremsen möglicherweise nicht der Fall, je nachdem wie stark du bremst.","Damit der Anhänger nicht wegrollt, wenn du ihn vom Zugfahrzeug trennst, solltest du die Feststellbremse des Anhängers anziehen.","Die Anhängerbremse kann bei längeren Bergabfahrten überhitzen. Möglicherweise musst du in dem Fall Pausen bei der Abfahrt einlegen."],"rn":1031},{"n":"2.6.03-119","t":"Was ist beim Führen eines Pkws zu beachten, nachdem Sie einen Wohnanhänger angekuppelt haben?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- verkleinert sich der benötigte Kurvenradius beim Abbiegen","- verlängert sich der Überholweg","- verschlechtert sich das Beschleunigungsvermögen"],"co":[1,2],"ex":["Der Kurvenradius beim Abbiegen bleibt gleich, wenn du einen Wohnanhänger angekuppelt hast.","Beim Überholen verlängert sich dein Überholweg um die Länge des Wohnanhängers. Da dein Fahrzeug durch das Gewicht des Wohnanhängers deutlich schlechter beschleunigt, verlängert den Überholweg zusätzlich.","Durch das Gewicht des Wohnanhängers brauchst du länger, um zu beschleunigen."],"rn":1032},{"n":"2.6.03-120","t":"Sie besitzen eine Fahrerlaubnis der Klasse B. Welchen Anhänger dürfen Sie mitführen?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- von 3.500 kg","- über 750 kg, wenn die zulässige Gesamtmasse der Fahrzeugkombination 3.500 kg nicht überschreitet","- bis 750 kg"],"co":[1,2],"ex":["Nein, Anhänger von 3.500 kg dürfen mit Klasse B nicht mitgeführt werden.","Solange die zulässige Gesamtmasse der Fahrzeugkombination 3.500 kg nicht überschreitet, darf die zulässige Gesamtmasse deines Anhängers auch größer als 750 kg sein.","Ja, mit der Klasse B darfst du einen Anhänger mit einer zulässigen Gesamtmasse bis 750 kg mitführen."],"rn":1033},{"n":"2.6.03-121","t":"Was kann die Fahrstabilität eines mitgeführten Anhängers beeinträchtigen?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Ein weit hinten im Anhänger liegender Ladungsschwerpunkt","Ein zu niedriger Reifenfülldruck der Anhängerreifen","Ein undichter Stoßdämpfer"],"co":[0,1,2],"ex":["Ein weit hinten liegender Ladungsschwerpunkt kann die Fahrstabilität deines Anhängers stark beeinträchtigen. Dadurch kann der Anhänger bei plötzlichen Lenkbewegungen oder höheren Geschwindigkeiten leichter ins Schlingern geraten und die Unfallgefahr erhöhen. Zusätzlich ist bei einem Anhänger, der weit hinter der Achse beladen ist, so, dass weniger Druck auf der Hinterachse des Zugfahrzeugs lastet. Das kann die Bodenhaftung des Zugfahrzeugs beeinträchtigen und zu weniger Grip führen.","Ein zu niedriger Reifendruck beim Anhänger kann die Fahrstabilität deines Anhängers beeinträchtigen. Zum einen führt der niedrige Reifendruck zu einer schlechteren Straßenhaftung, was deinen Anhänger in Kurven unkontrollierbarer macht. Zum anderen führt der niedrige Reifendruck zu einem erhöhtem Reifenverschleiß, welcher Reifenschäden während der Fahrt begünstigt.","Bereits ein undichter Stoßdämpfer kann die Fahrstabilität deines Anhängers negativ beeinflussen. Der undichte Stoßdämpfer an deinem Anhänger verliert seine Dämpfungseigenschaft, was zu einem unruhigen Fahrverhalten und zu schwer kontrollierbaren Gefahrensituationen führen kann."],"rn":1034},{"n":"2.6.03-406","t":"Ein einachsiger Anhänger hat eine tatsächliche Gesamtmasse von 600 kg. Wie groß muss die Stützlast mindestens sein?","p":3,"c":"2.6.03","ch":"Anhaengerbetrieb","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["60 kg (= 10 %)","90 kg (= 15 %)","24 kg (= 4 %)"],"co":[2],"ex":["Eine Stützlast von 10 % ist zwar auch gestattet, es müssen jedoch mindestens 4 % sein.","Da hier die Frage nach der Mindeststützlast gestellt wird, ist 4 %, also 24 kg, die richtige Antwort.","Die Stützlast muss mindestens 4 % des tatsächlichen Anhängergewichts betragen."],"rn":1035},{"n":"2.6.06-102","t":"Was bezeichnet man als zulässige Nutzlast?","p":3,"c":"2.6.06","ch":"Abmessungen Gewichte Und Geschwindigkeitsbegrenzer","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Die Differenz aus zulässiger Gesamtmasse und Leermasse","Die maximal zulässige Zuladung","Die zulässige Gesamtmasse"],"co":[0,1],"ex":["Ziehst du die Leermasse von der zulässigen Gesamtmasse ab, erhältst du die zulässige Nutzlast.","Die zulässige Nutzlast bezieht sich auf die Menge an Frachtgut, oder Zuladung, die du beladen kannst, bis die zulässige Gesamtmasse erreicht ist.","Die zulässige Nutzlast ist ein Teil der zulässigen Gesamtmasse."],"rn":1036},{"n":"2.6.06-103","t":"Wie lang darf eine Fahrzeugkombination bestehend aus Pkw und Anhänger ohne überstehende Ladung höchstens sein?","p":2,"c":"2.6.06","ch":"Abmessungen Gewichte Und Geschwindigkeitsbegrenzer","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","na":"18 m","e":"Dein Pkw darf mit Anhänger höchstens 18 Meter lang sein.","rn":1037},{"n":"2.6.06-104","t":"Was gilt beim Betrieb von Fahrzeugen hinsichtlich der Fahrzeughöhe einschließlich der Höhe der Ladung?","p":3,"c":"2.6.06","ch":"Abmessungen Gewichte Und Geschwindigkeitsbegrenzer","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- die gesetzlich zulässige Höhe von maximal 4,5 m einhalten","- mich in der Zulassungsbescheinigung Teil I über die Fahrzeughöhe informieren","- bei nach oben über den Fahrzeugumriss hinausragender Ladung die tatsächliche Höhe ermitteln"],"co":[1,2],"ex":["Dein Fahrzeug mit dazugehöriger Ladung darf die maximal zulässige Höhe von 4 m nicht überschreiten.","Du musst dich in der Zulassungsbeschränkung Teil 1, des sogenannten Fahrzeugscheins, über deine genaue Fahrzeughöhe informieren. So verhinderst du zum einen Gefahrensituationen auf Straßenabschnitten mit begrenzter Höhe und zum anderen Verstöße gegen die zulässige Gesamthöhe, falls du dein Fahrzeug beladen möchtest.","Falls die Ladung über den Fahrzeugumriss hinausragt, musst du die tatsächliche Höhe deines Fahrzeugs mit jeweiliger Ladung ermitteln. So stellst du sicher, dass die zulässige Gesamthöhe nicht überschritten wird."],"rn":1038},{"n":"2.6.06-213","t":"Wann dürfen Sie in dieser Situation weiter auf dem linken Fahrstreifen verbleiben?","p":3,"c":"2.6.06","ch":"Abmessungen Gewichte Und Geschwindigkeitsbegrenzer","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- gemäß Zulassungsbescheinigung Teil I (Fahrzeugschein) 2 m breit ist","- einschließlich Ladung tatsächlich maximal 2 m breit ist"],"co":[1],"ex":["Die Breite bezieht sich auf das Fahrzeug einschließlich Ladung.","Dieses Verkehrszeichen weist darauf hin, dass auf der linken Spur nur weiterhin Fahrzeuge fahren dürfen, die maximal 2 m breit sind."],"i":["https://video4.kalaiwa.de/assets/2606213.webp"],"rn":1039},{"n":"2.6.06-216","t":"Was müssen Sie in dieser Situation beachten?","p":3,"c":"2.6.06","ch":"Abmessungen Gewichte Und Geschwindigkeitsbegrenzer","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Mein Fahrzeug ist mit Außenspiegeln breiter als in den Fahrzeugpapieren angegeben","Nach 200 m verringert sich die Breite des linken Fahrstreifens","Auf einer Länge von 200 m verringert sich die Breite des linken Fahrstreifens"],"co":[0,1],"ex":["Dies musst du hier einplanen, wenn du auf der linken Spur bleiben möchtest. Bist du mit Außenspiegeln breiter als 2 m, dann musst du den Fahrstreifen wechseln.","Die Breite des linken Fahrstreifens verringert sich in 200 m auf 2 m.","Nach 200 m verringert sich die Breite des linken Fahrstreifens."],"i":["https://video2.kalaiwa.de/assets/2606216.webp"],"rn":1040},{"n":"2.6.07-001","t":"Was müssen Sie bei der Benutzung von Navigationssystemen und Straßenkarten beachten?","p":2,"c":"2.6.07","ch":"Lesen Einer Strassenkarte Und Streckenplanung","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Alle Navigationssysteme können sich automatisch aktualisieren","Die Inhalte können schon kurz nach dem Kauf veraltet sein","Auch aktuelle Inhalte können von der Realität abweichen"],"co":[1,2],"ex":["Davon ist nicht auszugehen.","Navigationssysteme und Straßenkarten können schon länger beim Verkäufer gelegen haben. Deshalb kann das Kartenmaterial sogar beim Kauf bereits veraltet sein.","Verkehrsführungen können sich beispielsweise durch Unfälle, Baustellen oder Veranstaltungen kurzfristig ändern."],"rn":1041},{"n":"2.6.07-101","t":"Was sollten Sie bei der Streckenplanung ins Ausland beachten?","p":2,"c":"2.6.07","ch":"Lesen Einer Strassenkarte Und Streckenplanung","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["- Kennzeichnungspflichten für das Befahren von Umweltzonen bestehen","- Bedingungen für die innerstädtische Straßennutzung gelten (zum Beispiel City-Maut)","- Geschwindigkeitsbeschränkungen gelten"],"co":[0,1,2],"ex":["Fahrverbote in Umweltzonen betreffen grundsätzlich auch im Ausland zugelassene Fahrzeuge.","Die Verkehrsregeln innerstädtischer Straßennutzung im Ausland unterscheidet sich häufig von deutschen Vorschriften.","Nicht nur auf der Autobahn gelten im Ausland meist stärker begrenzte Geschwindigkeiten als in Deutschland."],"rn":1042},{"n":"2.6.07-220","t":"Welche Tätigkeiten können beim Fahren zu risikoreichen Ablenkungen führen?","p":3,"c":"2.6.07","ch":"Lesen Einer Strassenkarte Und Streckenplanung","th":"Vorschriften Ueber Den Betrieb Der Fahrzeuge","o":["Die Eingabe einer Adresse in ein Navigationsgerät","Das Telefonieren auch mit Freisprecheinrichtung","Das Schreiben einer Textnachricht"],"co":[0,1,2],"ex":["Dies lenkt dich vom Verkehrsgeschehen ab. Lass deinen Beifahrer dies tun, oder halte hierfür an, wenn du allein im Fahrzeug bist.","Trotz Freisprecheinrichtung lenkt ein Telefonat ab. Versuche dies daher möglichst zu vermeiden.","Schreibe keine Textnachrichten während der Fahrt. Dein Reaktionsvermögen ist deutlich eingeschränkt und du bist nicht in der Lage, den Verkehr konzentriert zu beobachten."],"rn":1043},{"n":"2.7.01-045","t":"Was ist beim Kontrollieren des Reifenluftdrucks zu berücksichtigen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Beladung/Besetzung des Fahrzeugs","Werkstoff der Felgen (Stahl/Leichtmetall)","Temperatur der Reifen"],"co":[0,2],"ex":["Abhängig von der Beladung/Besetzung des Fahrzeugs muss der Reifenluftdruck angepasst werden.","Der Werkstoff der Felgen ist irrelevant für die Kontrolle des Reifendrucks.","Der Reifendruck steigt und fällt mit steigender bzw. sinkender Temperatur. Das musst du berücksichtigen, wenn du den Reifendruck kontrollierst."],"rn":1044},{"n":"2.7.01-047","t":"Wodurch wird die auf ein Fahrzeug wirkende Fliehkraft bei Kurvenfahrt vergrößert?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Durch kleineren Kurvenradius","Durch höheren Reifenluftdruck","Durch höhere Geschwindigkeit"],"co":[0,2],"ex":["Je enger eine Kurve ist, desto stärker zieht es das Fahrzeug bei gleicher Geschwindigkeit von der Straße.","Der Reifenluftdruck beeinflusst die Fliehkraft nicht.","Je schneller du eine Kurve durchfährst, desto stärker zieht es das Fahrzeug von der Straße."],"rn":1045},{"n":"2.7.01-058","t":"Sie fahren bei Nässe mit einem Pkw und Anhänger auf einer schmalen Landstraße und nähern sich einer übersichtlichen, aber engen Linkskurve. Wie verhalten Sie sich?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Ich bleibe in der Mitte des Fahrstreifens und beschleunige erst wieder beim Übergang in die Gerade","Ich verringere die Geschwindigkeit vor der Kurve","Ich bremse erst im Scheitelpunkt der Kurve"],"co":[0,1],"ex":["Fahre sehr langsam in die Kurve ein, halte dich mittig und beschleunige erst wieder, wenn sich sowohl PKW als auch Anhänger auf gerader Strecke befinden.","Du solltest unter diesen Bedingungen die Geschwindigkeit deutlich verringern und sehr vorsichtig um die Kurve fahren.","Du musst die Geschwindigkeit bereits vor Einfahren in die Kurve deutlich reduzieren und darfst in der Kurve nicht bremsen, um zu vermeiden, aus der Kurve zu \"fliegen\"."],"rn":1046},{"n":"2.7.01-065","t":"Was müssen Sie beim Fahren mit einem Quad beachten?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Beim Durchfahren von engen Kurven neigen Quads zum Kippen","Die Fahreigenschaften entsprechen denen von Pkws","Das Tragen eines geeigneten Schutzhelms ist Pflicht"],"co":[0,2],"ex":["Besondere Vorsicht gilt beim Befahren von engen Kurven. Zu hohe Geschwindigkeiten führen zum Kippen.","Die Fahreigenschaften von Quads und Pkws unterscheiden sich aufgrund des anderen Radstands und des Gewichts sehr. Sei deshalb vorsichtig, wenn du das erste Mal mit einem Quad unterwegs bist.","Du musst beim Fahren mit dem Quad einen geeigneten Schutzhelm tragen."],"rn":1047},{"n":"2.7.01-066","t":"Was ist beim Fahren mit einem Quad zu beachten?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Die notwendigen Lenkkräfte können deutlich höher sein als bei einem Pkw","Es sollte Motorradschutzkleidung getragen werden","Es muss ein Warndreieck mitgeführt werden"],"co":[0,1,2],"ex":["Um ein Quad zu lenken, können deutlich höhere Kräfte vom Fahrer erforderlich sein, weil eventuell keine Lenkunterstützung vorhanden ist.","Da ein Quad offen ist, ist Motorradschutzkleidung zu tragen.","Für das Warndreieck besteht eine Mitführpflicht."],"rn":1048},{"n":"2.7.01-072","t":"Wodurch erhöht sich in Kurven mit schlechtem Straßenzustand das Risiko, ins Schleudern zu geraten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Durch eine falsche Beladung","Durch ein beschädigtes Fahrwerk","Durch einen falschen Reifenfülldruck"],"co":[0,1,2],"ex":["Wenn das Fahrzeug falsch beladen ist, z.B. wenn viel Gewicht auf einer Seite ist, dann haben auch nicht mehr alle Reifen einen optimalen Halt auf der Straße.","Das Fahrwerk hat die Aufgabe alle Reifen mit gleicher Kraft mit der Straße in Berührung zu Halten. Ist das Fahrwerk beschädigt, kann es dies nicht mehr tun.","Bei falschem Reifenfülldruck ist zwar die Kraft des Reifens auf die Straße gegeben, jedoch kann dieser aufgrund des falschen Reifendrucks nicht optimal auf der Straße haften."],"rn":1049},{"n":"2.7.01-102","t":"Was ändert sich durch das Mitführen eines Wohnanhängers?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Der Bremsweg wird wesentlich kürzer","Der Überholweg wird wesentlich länger","Hastige Lenkbewegungen erhöhen die Schleudergefahr"],"co":[1,2],"ex":["Der Bremsweg verlängert sich durch das Mitführen eines Wohnanhängers.","Der Überholweg verlängert sich, weil die Gesamtlänge des Fahrzeugs zunimmt, das Fahrzeug aufgrund der Zuglast langsamer ist und der Motor mehr Energie benötigt, um zu beschleunigen.","Hastige Lenkbewegungen sollten generell und vor allem in Kombination mit Anhängern vermieden werden, da dies die Schleudergefahr deutlich erhöht."],"rn":1050},{"n":"2.7.01-104","t":"Sie fahren mit Ihrem Pkw und Anhänger auf einer Straße mit Gegenverkehr und wollen nach links abbiegen. Was ist beim Wiederanfahren besonders wichtig?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["An die eigene Zuglänge denken","Das geringere Beschleunigungsvermögen berücksichtigen","Den Gegenverkehr mit der Lichthupe warnen"],"co":[0,1],"ex":["Bedenke beim Abbiegen, dass die eigene Zuglänge aufgrund des Anhängers um einiges größer ist als normal.","Aufgrund des Anhängers ist das Beschleunigungsvermögen des PKWs geringer. Plane das ein, wenn du nach links abbiegen möchtest.","Es besteht kein Grund, den Gegenverkehr hier mit Lichthupe zu warnen. Du musst mit dem Abbiegen warten, bis die Bahn frei ist und darfst den Gegenverkehr nicht behindern."],"rn":1051},{"n":"2.7.01-105","t":"Sie fahren einen Pkw mit einem ungebremsten Anhänger. Es kommt ein längeres, starkes Gefälle. Was ist richtig?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Wenn nötig Geschwindigkeit verringern, rechtzeitig niedrigen Gang einlegen, bremsbereit sein","Bremse des Pkws durch häufiges Auskuppeln entlasten","Schieben des Anhängers berücksichtigen"],"co":[0,2],"ex":["Durch die höhere Masse muss mehr Kraft aufgewendet werden, um zu bremsen. Du solltest die Geschwindigkeit verringern. Nutze hierbei die Motorbremse, indem du einen niedrigen Gang einlegst.","Ein Auskuppeln entlastet nicht die Bremse, sondern bewirkt das genaue Gegenteil. Durch das Auskuppeln wirkt die Bremswirkung des Motors nicht mehr und die Bremsen werden stärker belastet.","Ein ungebremster Anhänger wird durch Auflaufen (\"Schieben\") auf das Zugfahrzeug gebremst. Das bedeutet, dass das Zugfahrzeug mehr Masse abbremsen muss, als nur das Eigengewicht."],"rn":1052},{"n":"2.7.01-107","t":"Was müssen Sie bei einem Pkw mit Wohnanhänger vor Fahrtbeginn prüfen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Ob die Sicht nach hinten durch die Rückspiegel ausreicht","Ob die Mitfahrer im Wohnanhänger die Sicherheitsgurte angelegt haben","Ob die Beleuchtungseinrichtung des Anhängers funktioniert"],"co":[0,2],"ex":["Ist dies nicht gegeben, dann musst du zusätzliche Rückspiegel anbringen, um eine ausreichende Rücksicht zu gewährleisten.","Im Wohnanhänger darf während der Fahrt niemand sitzen.","Nur dann darfst du mit ihm fahren. Deine Beleuchtung und vor allem Warnsignale muss der nachfolgende Verkehr erkennen können."],"rn":1053},{"n":"2.7.01-108","t":"Sie fahren einen Pkw mit voll beladenem Anhänger ohne eigene Bremse. Was ist richtig?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Der Anhalteweg wird kürzer","Der Bremsweg wird länger","Der Reaktionsweg wird länger"],"co":[1],"ex":["Da mit einer zusätzlichen Last des Anhängers der Bremsweg verlängert wird, wird auch der Anhalteweg länger und nicht kürzer.","Durch das zusätzliche Gewicht des Anhängers werden die Bremsen des PKW stärker belastet. Dadurch sinkt die Bremsleistung und der Bremsweg verlängert sich.","Der Reaktionsweg wird hierdurch nicht länger."],"rn":1054},{"n":"2.7.01-109","t":"Sie wollen an Ihren Pkw einen einachsigen Wohnwagen anhängen. Was müssen Sie prüfen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Ob der Wohnwagen für die Beförderung von Personen zugelassen ist","Ob wegen der Breite des Wohnwagens zusätzliche Rückspiegel angebracht werden müssen","Ob die zulässige Anhängelast oder die zulässige Stützlast des Pkws überschritten wird"],"co":[1,2],"ex":["Wohnwägen sind nie zur Beförderung von Personen zugelassen.","Ist deine Rücksicht nicht ausreichend vorhanden, dann musst du zusätzliche Rückspiegel anbringen.","Angaben zur Anhängelast findest du im Fahrzeugschein oder in der Bedienungsanleitung. Angaben zur Stützlast entnimmst du ebenfalls der Bedienungsanleitung oder einem Schild in der Nähe der Anhängerkupplung. Wird die Anhänge- oder die Stützlast überschritten, dann kann es zu Schäden am Fahrzeug kommen."],"rn":1055},{"n":"2.7.01-110","t":"Sie wollen mit einem Automatik-Pkw (hydraulischer Wandler) losfahren. Was müssen Sie wissen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Beim Einlegen einer Fahrstufe muss der Pkw in der Regel mit der Betriebsbremse festgehalten werden","Der Wählhebel darf nur bei stehendem Motor betätigt werden","Die Drehzahl muss wesentlich erhöht werden, damit der Motor nicht abgewürgt wird"],"co":[0],"ex":["Der Motor lässt sich bei Automatikfahrzeugen nur in den Stellungen P (Parken) und N (Neutral) starten. Um ein Losrollen nach Anlassen des Motors zu zu vermeiden, sollte beim Parken die Feststellbremse aktiviert sein.","Den Wählhebel kann man auch bei laufendem Motor betätigen.","Das Automatikgetriebe arbeitet mit einem Wandler. Es gibt im Gegensatz zur Handschaltung keine direkte Verbindung zwischen Motor und Getriebe. Der Motor kann beim Automatikgetriebe nicht abgewürgt werden."],"rn":1056},{"n":"2.7.01-111","t":"Worauf ist beim Luftdruck der Reifen zu achten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Luftdruck regelmäßig kontrollieren, einschließlich Reserverad","Luftdruck vor längeren Fahrten verringern","Luftdruck bei starker Beladung nach Betriebsanleitung erhöhen"],"co":[0,2],"ex":["Der Luftdruck muss regelmäßig kontrolliert werden. Dies gilt auch für das Reserverad, da auch bei diesem im Bedarfsfall der Druck stimmen muss.","Ein zu geringer Reifendruck führt zu erhöhtem Rollwiderstand. Damit erhöht sich der Verschleiß am Reifen und der Kraftstoffverbrauch. Daher solltest du den Luftdruck nicht vor längeren Fahrten verringern.","Entsprechend der Beladung oder der Besetzung des Fahrzeugs muss der Reifendruck angepasst werden."],"rn":1057},{"n":"2.7.01-112","t":"Sie mussten nach einer Reifenpanne das Notrad montieren. Was ist bei der Weiterfahrt verboten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Mit dem Notrad länger als unbedingt erforderlich zu fahren","Schneller als 80 km/h zu fahren","Personen mitzunehmen"],"co":[0,1],"ex":["Du darfst mit einem Notrad nicht länger als unbedingt notwendig fahren.","Mit Notrad darfst du nur maximal 80 km/h fahren.","Ein Notrad ist kein Grund, keine Personen mehr zu transportieren. Du solltest hiermit jedoch nicht länger als unbedingt erforderlich fahren."],"rn":1058},{"n":"2.7.01-115","t":"Wozu neigt ein Pkw mit Hinterradantrieb, wenn man in der Kurve zu viel Gas gibt?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Er neigt zum Untersteuern","Er neigt dazu, vorne auszubrechen","Er neigt dazu, hinten auszubrechen"],"co":[2],"ex":["Gibt man in der Kurve zu viel Gas, dann kann es passieren, dass der PKW übersteuert.","Ein PKW mit Hinterradantrieb neigt dazu, hinten auszubrechen.","Ein PKW mit Hinterradantrieb neigt in der Kurve dazu, hinten auszubrechen, bzw. zu übersteuern, wenn man zu viel Gas gibt."],"rn":1059},{"n":"2.7.01-118","t":"Welche Vorteile bietet eine Antriebs-Schlupf-Regelung (ASR)?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Beim Anfahren auf glatter Fahrbahn wird die Gefahr des seitlichen Wegrutschens geringer","Beim Anfahren wird das Durchdrehen der Räder verhindert","Beim Bremsen wird das Blockieren der Räder verhindert"],"co":[0,1],"ex":["Die ASR minimiert die Gefahr, auf glatter Fahrbahn seitlich wegzurutschen.","Aufgrund der Antriebs-Schlupf-Regelung drehen die Reifen beim Anfahren nicht durch.","Das Blockieren der Räder verhindert das Antiblockiersystem (ABS)."],"rn":1060},{"n":"2.7.01-120","t":"Sie wollen einen Anhänger mit Kugelkupplung ankuppeln. Was ist richtig?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Stützrad so einstellen, dass es während der Fahrt mitlaufen kann","Die Kupplungsklaue muss den Kugelkopf sicher umschließen. Die Sicherung muss einrasten","Die elektrische Verbindung muss hergestellt werden"],"co":[1,2],"ex":["Ein vorhandenes Stützrad dient als Hilfe beim An- und Abkuppeln oder zum Abstellen. Während der Fahrt muss es vollständig nach oben gekurbelt sein.","Damit der Anhänger richtig angeschlossen ist, muss die Kupplungsklaue den Kugelkopf vollständig umschließen. Wenn die Sicherung einrastet, ist gewährleistet, dass sich die Kupplungsklaue nicht selbstständig lösen kann.","Die elektrische Verbindung muss hergestellt sein, damit Rückbeleuchtung des Fahrzeugs an den Anhänger weitergegeben werden können."],"rn":1061},{"n":"2.7.01-121","t":"Was müssen Sie nach dem Ankuppeln eines einachsigen Anhängers mit Auflaufbremse tun?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Abreißseil an der Anhängekupplung des Motorwagens einhängen","Vorhandenes Stützrad in die oberste Stellung bringen","Funktion der Bremse prüfen"],"co":[0,1,2],"ex":["Wenn der Anhänger sich während der Fahrt unbeabsichtigt vom Zugfahrzeug löst, dann betätigt das Abreißseil die Handbremse des Anhängers und reißt danach ab. Der Anhänger wird dadurch zum Stillstand gebracht.","Das Stützrad dient nur der Stütze des Anhängers im Stand. Nach Ankuppeln muss das Stützrad in die oberste Stellung gebracht werden, um während der Fahrt nicht zu bremsen oder blockieren.","Die Funktion der Bremse muss immer vor Fahrtantritt geprüft werden."],"rn":1062},{"n":"2.7.01-122","t":"Was müssen Sie beim Beladen eines einachsigen Anhängers beachten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- Achslast","- Stützlast","- Gesamtmasse"],"co":[0,1,2],"ex":["Die zulässige Achslast musst du beim Beladen des Anhängers berücksichtigen. Wenn zu viel Gewicht auf dem Anhänger ist, besteht die Gefahr, dass die Achsen dabei zu stark belastet werden und schlimmstenfalls zu einem Achsbruch führt.","Ist die Stützlast zu hoch, dann wird die Anhängerkupplung durch das Gewicht des Anhängers zu stark belastet und das Risiko eines Bruchs steigt.","Beim Beladen des Anhängers musst du die zulässige Gesamtmasse beachten. Diese muss eingehalten werden, damit der Anhänger verkehrssicher bleibt und die Ladung sicher transportiert werden kann."],"rn":1063},{"n":"2.7.01-123","t":"Sie wollen Ihren einachsigen Anhänger (Auflaufbremse, 1.000 kg zulässige Gesamtmasse) im Gefälle abstellen. Was müssen Sie tun?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Feststellbremse anziehen","Rückfahrsperre verriegeln","Unterlegkeile vor die Räder legen"],"co":[0,2],"ex":["Du musst die Feststellbremse anziehen, um den Anhänger so gegen ein Wegrollen abzusichern.","Die Rückfahrsperre muss beim Abstellen im Gefälle nicht verriegelt sein.","Du musst die Unterlegkeile entgegen dem Gefälle unter die Räder legen, um den Anhänger so zusätzlich zur gezogenen Feststellbremse gegen ein Wegrollen abzusichern."],"rn":1064},{"n":"2.7.01-124","t":"Welche gefährlichen Mängel können an einem auflaufgebremsten Anhänger nach längerer Standzeit vorhanden sein?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Kabelverbindungen können beschädigt sein","Die Bremse kann wegen Rost wirkungslos sein","Der Reifendruck kann sich durch Sonneneinstrahlung stark erhöht haben"],"co":[0,1],"ex":["Witterungsbedingt kann Feuchtigkeit die Metallteile (Stecker und Anschlüsse) derart verändern, dass die elektrische Übertragung nicht mehr funktioniert. Ebenfalls können die Gummiteile im Laufe der Zeit porös werden und es kommt dadurch zu Beschädigungen des Kabels.","Rost kann dazu führen, dass die Mechanik der Auflaufbremse so beeinträchtigt wird, dass die Bremswirkung vermindert oder die Bremsanlage vollständig ohne Funktion ist.","Es ist eher wahrscheinlich, dass die Luft mit der Zeit entweicht und der Reifendruck dadurch abnimmt."],"rn":1065},{"n":"2.7.01-125","t":"Was müssen Sie beim Beladen eines Anhängers beachten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- darf nach hinten ohne zusätzliche Kennzeichnung höchstens 1 m über die Rückstrahler hinausragen","- darf nach vorn höchstens 1 m über das Zugfahrzeug hinausragen","- muss sicher verstaut werden"],"co":[0,2],"ex":["Ladung muss nicht kenntlich gemacht werden, wenn sie weniger als 1 m über die Rückstrahler des Fahrzeuges nach hinten hinausragt.","Ladung darf auf einem Anhänger nicht über das Zugfahrzeug hinausragen.","Die Ladung muss auf dem Anhänger sicher verstaut werden, damit sie während der Fahrt nicht hin- und herrutscht oder vom Anhänger fällt."],"rn":1066},{"n":"2.7.01-127","t":"Warum soll ein längeres, starkes Gefälle nicht mit getretener Kupplung durchfahren werden?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Weil dann der Bremskraftverstärker nicht mehr wirken kann","Weil dadurch unnötiger Verschleiß an den Bremsen eintritt","Weil die Motorbremswirkung nicht zum Tragen kommen kann"],"co":[1,2],"ex":["Der Bremskraftverstärker wird durch den Motor angetrieben und funktioniert somit solange der Motor an ist.","Ohne Motorbremswirkung wird die Betriebsbremse stärker belastet, was zu höherem Verschleiß führt.","Ist die Kupplung durchgetreten, dann wirkt die Motorbremse nicht. Diese sollte jedoch bei starkem Gefälle betätigt werden, um die Bremsen zu schonen oder die Bremswirkung zu verstärken."],"rn":1067},{"n":"2.7.01-130","t":"Sie müssen in einer Kurve auf nasser Fahrbahn plötzlich bremsen. Welche Besonderheiten bestehen bei einem Fahrzeug mit Antiblockiersystem (ABS)?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Das Fahrzeug bleibt immer fahrstabil","Die Lenkfähigkeit bleibt länger erhalten","Das Fahrzeug kann nicht aus der Kurve rutschen"],"co":[1],"ex":["Das ABS sorgt lediglich dafür, dass die Reifen nicht blockieren.","Das ABS verhindert, dass bei einer Vollbremsung die Reifen blockieren. Dadurch bleibt die Lenkfähigkeit länger erhalten.","Das ABS sorgt nicht dafür, dass ein Fahrzeug nicht aus der Kurve rutscht. Es sorgt nur dafür, dass die Reifen nicht blockieren."],"rn":1068},{"n":"2.7.01-131","t":"Wie wirken sich die Kurvenlaufeigenschaften einer Fahrzeugkombination (Pkw mit Wohnanhänger) beim Abbiegen aus?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- kann die Kurve schneiden","- läuft in der Regel in der Spur des Pkws","- kann ausschwenken"],"co":[0,2],"ex":["Wenn der PKW-Fahrer die Kurve zu eng nimmt, kann es passieren, dass der Wohnanhänger die Kurve schneidet.","Davon kann nicht ausgegangen werden.","Der Wohnanhänger kann beim Abbiegen oder Einfahren in eine Kurve ausschwenken."],"rn":1069},{"n":"2.7.01-133","t":"Was kann die Funktion eines Spurhalteassistenten einschränken?","p":2,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Fehlende Leitplanken","Fehlende Fahrbahnmarkierungen","Eine verschmutzte Fahrbahn"],"co":[1,2],"ex":["Leitplanken sind nicht notwendig, damit der Spurhalteassistent funktioniert.","Fehlt die Fahrbahnmarkierung, dann kann der Spurhalteassistent die einzuhaltende Fahrspur nicht erkennen.","Da die Sicht auf die Fahrbahnmarkierungen bei verschmutzter Fahrbahn vermindert ist, kann die Funktion des Spurhalteassistenten hierdurch eingeschränkt sein."],"rn":1070},{"n":"2.7.01-134","t":"Worüber sollten Sie sich vor einer Fahrt mit einem reinen Elektrofahrzeug informieren?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["An welchen Orten ich das Fahrzeug aufladen kann","Wie ich mich nach einem Unfall verhalten muss","Über Einflussfaktoren auf die Reichweite"],"co":[0,1,2],"ex":["Da es nur sehr wenige Aufladestationen gibt, musst du dich vor der Fahrt darüber informieren, wo diese sind.","Da Akkus bei Beschädigung ein erhebliches Gefahrenrisiko sein können, musst du dich vor der Fahrt darüber informieren, wie du dich im Falle eines Unfalls verhalten musst.","Die Reichweite ist abhängig von der Größe der Batterien, Fahrzeugleistung, der Beschaffenheit der Strecke und von der Fahrweise. Informiere dich über diese Einflussfaktoren, bevor du die Fahrt antrittst."],"rn":1071},{"n":"2.7.01-135","t":"Sie planen eine längere Reise mit einem reinen Elektrofahrzeug. Was sollten Sie beachten?","p":2,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Die Verfügbarkeit von Elektrotankstellen","Den Einfluss extremer Außentemperaturen auf die Reichweite","Die Ladezeit der Batterien"],"co":[0,1,2],"ex":["Noch nicht alle Tankstellen haben Aufladestationen für Elektrofahrzeuge. Daher solltest du die Verfügbarkeit von Elektrotankstellen vor Fahrtantritt herausfinden.","Extreme Außentemperaturen können die Reichweite deines Elektrofahrzeugs beeinflussen, weil die Batterien nur bei bestimmten Temperaturen optimal arbeiten können.","Vor Fahrtantritt solltest du dich darüber informieren, wie viel Zeit die Batterien zum Aufladen benötigen."],"rn":1072},{"n":"2.7.01-136","t":"Was sollten Sie beim Laden von reinen Elektrofahrzeugen beachten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Das Laden sollte nur mit Ladekabeln erfolgen, die vom Hersteller freigegeben sind","Die Ladedauer hängt vom Stromanschluss ab","Das Laden kann an jeder Tankstelle erfolgen"],"co":[0,1],"ex":["Das Nutzen anderer Ladekabel kann gefährlich werden, weil dies den Akku beschädigen kann.","Je mehr Leistung der Stromanschluss bereitstellt, desto schneller erfolgt die Aufladung des Elektrofahrzeugs.","Das Laden kann nur an Tankstellen erfolgen, die auch Ladestationen für Elektroautos haben."],"rn":1073},{"n":"2.7.01-137","t":"Was unterscheidet reine Elektrofahrzeuge von Fahrzeugen mit Verbrennungsmotor?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- keinen direkten Schadstoffausstoß","- einen geringeren Luftwiderstand","- ein geringeres Motorgeräusch"],"co":[0,2],"ex":["Elektrofahrzeuge produzieren keine Schadstoffe wie Fahrzeuge mit Verbrennungsmotor, die während der Fahrt ausgestoßen werden müssen.","Der Luftwiderstand von Elektroautos unterscheidet sich nicht von dem gewöhnlicher Kraftfahrzeuge.","Das Motorgeräusch ist bei Elektrofahrzeugen geringer als bei Fahrzeugen mit Verbrennungsmotor. Deshalb kann man bei niedrigen Geschwindigkeiten sehr leicht überhört werden."],"rn":1074},{"n":"2.7.01-138","t":"Sie fahren ein reines Elektrofahrzeug in einem Wohngebiet. Worauf sollten Sie sich aufgrund Ihrer geringen Fahrgeräusche einstellen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Nachfolgende Fahrzeuge fahren zu dicht auf","Fußgänger nehmen mich nicht oder verspätet wahr","Vorausfahrende Radfahrer biegen nach links ab, ohne nach hinten zu schauen"],"co":[1,2],"ex":["Dies ist kein mögliches Resultat geringer Fahrgeräusche, da du von nachfolgenden Fahrzeugen gesehen wirst.","Du musst auf diese besonders Acht geben, da sie möglicherweise nicht mit dir rechnen, weil sie dich nicht kommen hören.","Da die Radfahrer dich aufgrund des geringen Fahrgeräuschs möglicherweise nicht wahrnehmen, fahren sie, ohne dich zu berücksichtigen."],"rn":1075},{"n":"2.7.01-139","t":"Sie fahren ein Kraftfahrzeug mit einem Automatischen Blockierverhinderer (ABV). Wie erreichen Sie einen möglichst kurzen Bremsweg?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- mehrfach in kurzen Abständen mit maximaler Pedalkraft","- vorsichtig und dann zunehmend kräftiger","- schlagartig und mit maximaler Pedalkraft"],"co":[2],"ex":["Hier wird kein möglichst kurzer Bremsweg erreicht.","Das gewährleistet keinen möglichst kurzen Bremsweg.","Bei einer Gefahrenbremsung ist der Bremsweg am kürzesten."],"rn":1076},{"n":"2.7.01-141","t":"Sie fahren sehr schnell in eine enge Kurve. Was kann passieren, wenn Sie plötzlich stark bremsen müssen?","p":4,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- verliert die Straßenhaftung","- bleibt mit Stabilitätskontrolle jederzeit fahrstabil","- rutscht aus der Kurve"],"co":[0,2],"ex":["Zwischen einer Straße und den Reifen eines Fahrzeugs herrscht eine Reibungskraft, die durch das Gewicht eines Fahrzeugs entsteht. Wenn ein Fahrzeug jedoch mit zu schneller Geschwindigkeit in eine Kurve fährt und bremst, übersteigen die dadurch entstehenden Fliehkräfte diese Reibungskraft, und das Fahrzeug verliert die Bodenhaftung.","Bei zu hoher Geschwindigkeit und zu engen Kurven kann ein Fahrzeug trotz Stabilitätskontrolle ins Rutschen geraten.","Bei einer starken Bremsung blockieren die Räder eines Pkws und die Lenkung reagiert nicht mehr. Dadurch rutscht das Fahrzeug unabhängig vom Lenkungsgrad geradeaus aus einer Kurve."],"rn":1077},{"n":"2.7.01-142","t":"Was kann in Kurven zum Schleudern Ihres Kraftfahrzeugs führen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Zu schnelles Fahren","Starke Lenkeinschläge","Leichtes Beschleunigen am Kurvenausgang"],"co":[0,1],"ex":["Zu schnelle Geschwindigkeiten können in Kurven dazu führen, dass die entstehenden Fliehkräfte die Haftreibungskräfte eines Fahrzeugs übersteigen. Das führt dazu, dass die Reifen eines Fahrzeugs ihre Bodenhaftung verlieren.","Bei zu starken Lenkeinschlägen kann es passieren, dass das Fahrzeug untersteuert. Das bedeutet, es „schiebt” trotz eingeschlagener Lenkung in der Kurve nach außen.","Am Kurvenausgang kann problemlos leicht beschleunigt werden. Dabei kommt ein Kfz in der Regel nicht ins Schleudern."],"rn":1078},{"n":"2.7.01-143","t":"Der Spurhalte-Assistent warnt Sie durch akustische, haptische oder optische Signale. Was kann die Ursache dafür sein?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Mein Fahrzeug unterschreitet den Sicherheitsabstand zum vorausfahrenden Fahrzeug","Ein anderes Fahrzeug überholt mich mit zu geringem Seitenabstand","Mein Fahrzeug nähert sich der seitlichen Fahrbahnmarkierung an"],"co":[2],"ex":["Der Spurhalte-Assistent warnt nur vor dem Verlassen der Fahrspur und nicht vor zu dichtem Auffahren.","Der Spurhalte-Assistent warnt nur vor dem Verlassen der Fahrspur und nicht vor zu geringem seitlichen Abstand.","Der Spurhalte-Assistent schaut darauf, dass du in deiner Spur bleibst."],"rn":1079},{"n":"2.7.01-144","t":"In welcher Situation kann Sie der Spurhalte-Assistent mit Lenkeingriff unterstützen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- in engen Baustellen mit schlechter Markierung","- auf Autobahnen","- auf Landstraßen"],"co":[1,2],"ex":["Durch die schlechte Markierung und die enge Fahrbahn ist der Lenkeingriff des Spurhalte-Assistenten nicht möglich, da sie mit hoher Wahrscheinlichkeit nicht richtig erkannt werden wird.","Auf Autobahnen kann ein Lenkeingriff durch den Spurhalte-Assistent hilfreich sein, da die Markierungen dort eindeutig zu erkennen sind.","Auch auf Landstraßen kann der Spurhalte-Assistent mit Lenkeingriff helfen, das Abkommen von der Fahrbahn zu verhindern."],"rn":1080},{"n":"2.7.01-145","t":"Bei welcher Fahraufgabe kann der Spurhalte-Assistent mit Lenkeingriff den Fahrzeugführer unterstützen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Beim Überholen","Beim Abbiegen","Beim Geradeausfahren"],"co":[2],"ex":["Beim Überholen signalisierst du dem Spurhalte-Assistenten durch Blinken, dass du die Fahrbahnmarkierung absichtlich überquerst. Somit greift er während des Überholvorgangs nicht ein.","Beim Abbiegen kreuzt du Fahrstreifen und Markierungen, der Spurhalte-Assistent kann hierbei nicht unterstützend eingreifen.","Bei guten Fahrbahnmarkierungen kann dir der Spurhalte-Assistent mit Lenkeingriff helfen das Fahrzeug auf der Fahrbahn zu halten."],"rn":1081},{"n":"2.7.01-146","t":"Was kann die Funktion des Spurhalte-Assistenten mit Lenkeingriff beeinträchtigen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Die Witterungsverhältnisse","Der Zustand der Fahrbahnmarkierungen","Zusätzliche Fahrbahnmarkierungen im Baustellenbereich"],"co":[0,1,2],"ex":["Die Witterungsverhältnisse können die Sensoren des Spurhalte-Assistenten beeinträchtigen. Außerdem können Wasser oder Schnee die Markierungen verfälschen.","Ist die Fahrbahnmarkierung in einem schlechten Zustand, kann der Spurhalte-Assistent nicht erkennen, wo die einzuhaltende Fahrspur verläuft.","Durch zusätzliche Fahrbahnmarkierungen in Baustellenbereichen ist es für den Spurhalte-Assistenten möglicherweise nicht ersichtlich, welche die einzuhaltende Fahrbahn ist."],"rn":1082},{"n":"2.7.01-147","t":"Unter welcher Voraussetzung funktioniert der Spurhalte-Assistent mit Lenkeingriff bestmöglich?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Bei eindeutigen Fahrbahnmarkierungen","Bei zusätzlichen Baustellenmarkierungen","Bei Schneeresten auf der Fahrbahn"],"co":[0],"ex":["Durch eindeutige Fahrbahnmarkierungen kann der Spurhalte-Assistent mit Lenkeingriff bestmöglich erkennen, wie die einzuhaltende Fahrspur verläuft.","Zusätzliche Baustellenmarkierungen führen dazu, dass der Spurhalte-Assistent möglicherweise nicht erkennen kann, welche die einzuhaltende Fahrspur ist.","Durch Schneereste auf der Fahrbahn können die Fahrbahnmarkierungen verdeckt sein. Dadurch kann der Spurhalte-Assistent die Fahrbahn nicht mehr eindeutig erkennen."],"rn":1083},{"n":"2.7.01-149","t":"Wie können Fahrerassistenzsysteme Sie unterstützen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- mir bei der Bewältigung von Fahraufgaben helfen","- in kritischen Verkehrssituationen automatisch eingreifen","- mich vor Gefahren warnen"],"co":[0,1,2],"ex":["Fahrerassistenzsysteme können dich bei Fahraufgaben, wie z. B. das Halten der Fahrspur, unterstützen.","In kritischen Verkehrssituationen können Fahrerassistenzsysteme schnell reagieren und durch Lenken oder Bremsen etc. automatisch eingreifen.","Droht eine Gefahr, können dich Fahrerassistenzsysteme durch Licht-, Ton- und Haptiksignale warnen."],"rn":1084},{"n":"2.7.01-150","t":"Was kann die Folge sein, wenn Sie bei einem Pkw mit Frontantrieb in der Kurve zu stark beschleunigen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- über die Hinterachse ausbrechen","- über die Vorderachse ausbrechen","- in der Lenkfähigkeit eingeschränkt sein"],"co":[1,2],"ex":["Der Pkw hat Vorderantrieb. Er neigt also dazu vorne auszubrechen und nicht hinten.","Gibst du bei einem Pkw mit Frontantrieb in der Kurve zu viel Gas, könnte er über die Vorderachse ausbrechen. Die Frontreifen verlieren dabei die Haftung zur Straße und dadurch würde dein Fahrzeug nicht mehr lenken, sondern geradeaus weiterfahren und somit ausbrechen.","Durch zu starkes Beschleunigen könnte der Pkw in der Lenkfähigkeit eingeschränkt sein. Die Frontreifen verlieren dabei die Haftung zur Straße und dadurch würde dein Fahrzeug nicht mehr lenken, sondern geradeaus weiterfahren und somit ausbrechen."],"rn":1085},{"n":"2.7.01-151","t":"Unter welcher Voraussetzung kann ein Aktiver Spurwechsel-Assistent einen Fahrstreifenwechsel durchführen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- eine ausreichende Lücke im Gegenverkehr erkannt hat","- keine Fahrzeuge im relevanten Sicherheitsbereich erkannt hat","- eine ausreichend markierte Fahrbahn mit mehreren Fahrstreifen erkannt hat"],"co":[1,2],"ex":["Eine Lücke im Gegenverkehr spielt für den aktiven Spurwechsel keine Rolle.","Der Aktive Spurwechsel-Assistent führt erst dann einen Spurwechsel durch, wenn er kein Fahrzeug im relevanten Sicherheitsbereich erkennt.","Für einen aktiven Spurwechsel muss der Assistent zuerst eine markierte Fahrbahn mit mehreren Fahrstreifen erkennen."],"rn":1086},{"n":"2.7.01-152","t":"Ihr Kraftfahrzeug ist mit einem Aktiven Spurhalte-Assistenten ausgerüstet. Welche Information kann über die Statusanzeige dieses Systems angezeigt werden?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- ist eingeschaltet","- ist ausgeschaltet","- hat eine Störung"],"co":[0,1,2],"ex":["Das System muss anzeigen können, wenn es eingeschaltet ist, da dies für den Fahrer wichtig ist.","Das System muss anzeigen können, wenn es aus geschaltet ist, da dies für den Fahrer wichtig ist.","Das System muss anzeigen können, wenn es eine Störung hat, da dies für den Fahrer wichtig ist."],"rn":1087},{"n":"2.7.01-153","t":"Ihr Kraftfahrzeug ist mit einem Spurhalte-Assistenten ausgerüstet. In welcher Situation kann Sie dieses System unterstützen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- unbeabsichtigten Verlassen der Fahrspur","- zu schnellen Durchfahren von Spurrillen","- Überschreiten der zulässigen Höchstgeschwindigkeit"],"co":[0],"ex":["Der Spurhalte-Assistent unterstützt dich dabei, die Fahrspur zu halten. Er warnt dich bei unabsichtlichem Verlassen der Fahrspur. Unbeabsichtigt ist, wenn du nicht blinkst.","Der Spurhalte-Assistent warnt nicht bei zu schnellem Durchfahren von Spurrillen, sondern nur, wenn du die Spur nicht hältst.","Der Spurhalte-Assistent warnt nicht bei Geschwindigkeitsüberschreitungen, sondern nur, wenn du die Spur nicht hältst."],"rn":1088},{"n":"2.7.01-154","t":"Sie nutzen in Ihrem Kraftfahrzeug den Spurhalte-Assistenten. Er warnt Sie während der Fahrt mit einem Signal. Was kann die Ursache dafür sein?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Ich verlasse unbeabsichtigt meinen Fahrstreifen","Ich habe beim Fahrstreifenwechsel vergessen, den Blinker zu betätigen","Ich unterschreite den Mindestabstand zum vorausfahrenden Fahrzeug"],"co":[0,1],"ex":["Bei unbeabsichtigtem Verlassen deines Fahrstreifens warnt der Spurhalte-Assistent. Wenn du also z. B. nach rechts von der Straße abkommst.","Vergisst du beim Fahrstreifenwechsel das Blinken, erkennt der Spurhalte-Assistent dies als unbeabsichtigtes Verlassen deines Fahrstreifens und warnt dich.","Der Spurhalte-Assistent erkennt den Mindestabstand zum vorausfahrenden Fahrzeug nicht, sondern nur, ob du die Spur hältst."],"rn":1089},{"n":"2.7.01-155","t":"Sie nutzen in Ihrem Kraftfahrzeug während der Fahrt den Spurhalte-Assistenten. Das System reagiert beim Verlassen des Fahrstreifens nicht. Was kann die Ursache dafür sein?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Starker Niederschlag","Fehlende Fahrstreifenmarkierungen","Eine unzureichende Fahrbahnausleuchtung"],"co":[0,1,2],"ex":["Bei starkem Niederschlag sind die Sensoren des Spurhalte-Assistenten beeinträchtigt, wodurch die Spur nicht zuverlässig erkannt wird.","Durch fehlende Fahrstreifenmarkierungen kann der Spurhalte-Assistent nicht erkennen, wie die Fahrstreifen verlaufen.","Ist die Fahrbahnausleuchtung unzureichend, kann der Spurhalte-Assistent die Fahrstreifenmarkierungen nicht erkennen."],"rn":1090},{"n":"2.7.01-156","t":"Ihr Kraftfahrzeug ist mit einem Spurwechsel-Assistenten ohne Lenkeingriff ausgerüstet. Im Bereich des linken Außenspiegels leuchtet während der Fahrt die Warnleuchte auf. Worauf weist Sie diese Warnleuchte hin?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Ein Fahrstreifenwechsel nach links ist jetzt gefahrlos möglich","Im Überwachungsbereich befindet sich ein anderes Fahrzeug","Ein Fahrstreifenwechsel nach links darf jetzt nicht vorgenommen werden"],"co":[1,2],"ex":["Ein Fahrstreifenwechsel nach links ist nicht möglich, da sich dort ein Fahrzeug befindet.","Befindet sich ein Fahrzeug im Überwachungsbereich, wird dies durch das Aufleuchten der Warnleuchte am Außenspiegel signalisiert.","Leuchtet die Warnleuchte auf, befindet sich ein Fahrzeug im Überwachungsbereich. Du darfst jetzt keinen Spurwechsel vornehmen."],"rn":1091},{"n":"2.7.01-157","t":"Sie nutzen während der Fahrt den Aktiven Spurhalte-Assistenten. Wie können Sie dieses Fahrerassistenzsystem im Falle des Systemeingriffs manuell übersteuern?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Durch Beschleunigen","Durch Betätigung des Blinkers","Durch Gegenlenken"],"co":[1,2],"ex":["Durch Beschleunigen wird der Eingriff des Spurhalte-Assistenten nicht beeinflusst.","Durch Betätigen des Blinkers wird der Eingriff übersteuert.","Durch Gegenlenken wird der Eingriff des Spurhalte-Assistenten übersteuert."],"rn":1092},{"n":"2.7.01-158","t":"In welcher Situation kann ein Aktiver Spurwechsel-Assistent sinnvoll eingesetzt werden?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- Autobahnen","- autobahnähnlichen Straßen","- Straßen ohne Markierung"],"co":[0,1],"ex":["Auf Autobahnen sind die Fahrstreifenmarkierungen gut zu sehen und die Fahrbahnen verlaufen meist gerade. Hier bietet sich ein Aktiver Spurwechsel-Assistent an.","Auf autobahnähnlichen Straßen bietet sich ein Aktiver Spurwechsel-Assistent ebenfalls an, da die Fahrstreifenmarkierungen gut zu sehen sind und die Fahrbahnen meist gerade verlaufen.","Auf Straßen ohne Markierungen kann der Spurwechsel-Assistent nicht erkennen, wie die Fahrbahnen verlaufen. Ohne erkannte Fahrbahnen kann der Spurwechsel-Assistent nicht helfen."],"rn":1093},{"n":"2.7.01-159","t":"Sie möchten überholen und haben über den Aktiven Spurwechsel-Assistenten einen Spurwechsel eingeleitet. Was ist richtig?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Das System führt den Spurwechsel selbstständig durch","Das System hält immer alle Sicherheitsabstände selbstständig ein","Ich muss den Spurwechsel überwachen"],"co":[0,2],"ex":["Der Aktive Spurwechsel-Assistent kann den Spurwechsel nach Einleitung selbstständig durchführen.","Die Sicherheitsabstände hält das System nicht immer selbstständig ein. Hier musst du immer aufpassen.","Einen vom Aktiven Spurwechsel-Assistenten durchgeführten Spurwechsel, musst du immer überwachen, da z. B. Sicherheitsabstände nicht immer selbstständig eingehalten werden."],"rn":1094},{"n":"2.7.01-160","t":"Welches Fahrerassistenzsystem müssen Sie manuell aktivieren, wenn Sie in bestimmten Situationen unterstützt werden möchten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Die Adaptive Geschwindigkeitsregelanlage (AGR)","Den Aktiven Park-Assistenten","Den Notbremsassistenten"],"co":[0,1],"ex":["Die Adaptive Geschwindigkeitsregelanlage (AGR) musst du manuell aktivieren, wenn du willst, dass z.B. auf Autobahnen oder Kraftfahrstraßen deine Geschwindigkeit automatisch an ein vorausfahrendes Fahrzeug angepasst wird.","Den Aktiven Park-Assistenten musst du bei Bedarf beim Parken selbst aktivieren. Eine automatische Aktivierung lässt sich nicht umsetzen, da dein Auto nicht wissen kann, wann du einparken willst.","Der Notbremsassistent ermittelt automatisch den Abstand zu anderen Fahrzeugen, warnt dich vor Zusammenstößen und kann notfalls eine Vollbremsung durchführen."],"rn":1095},{"n":"2.7.01-161","t":"Sie möchten mit dem dargestellten Kleintransporter (bis 3,5 t) Möbel transportieren. Was müssen Sie im Vergleich zum Führen eines Pkws beachten?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- erfordert eine besondere Beachtung der Durchfahrtshöhe","- ist anfälliger für Seitenwind","- kann in Kurven leichter umkippen"],"co":[0,1,2],"ex":["Der Transporter könnte die Durchfahrtshöhe von Unterführungen oder Einfahrten überschreiten.","Beachte, dass der Transporter wegen seiner Seitenfläche mehr Angriffsfläche für Seitenwind bietet.","Durch den erhöhten Schwerpunkt kann der Kleintransporter, insbesondere wenn er mit Möbeln beladen ist, in Kurven leichter umkippen."],"i":["https://video2.kalaiwa.de/assets/2701161.webp"],"rn":1096},{"n":"2.7.01-162","t":"Wie kann Sie der Aktive Park-Assistent beim Einparken unterstützen?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- prüft, ob das Parken an einer bestimmten Stelle erlaubt ist","- erkennt ausreichend große Parklücken","- erkennt alle Hindernisse während des Parkens"],"co":[1],"ex":["Ob du an einer bestimmten Stelle parken darfst, kann der Aktive Park-Assistent nicht prüfen. Vergewissere dich immer, dass du nicht im Halte- oder im Parkverbot parkst.","Ein Aktiver Park-Assistent kann erkennen, welche Parklücken für den Pkw ausreichend groß sind.","Der Aktive Park-Assistent kann nicht alle Hindernisse während des Parkens erkennen. Sei immer aufmerksam, wenn du in eine Parklücke fährst."],"rn":1097},{"n":"2.7.01-163","t":"Was kann der Grund dafür sein, dass ein Abbiegeassistent einen Radfahrer nicht zuverlässig erkennt?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Eine Beschädigung des Sensors","Eine Verdeckung des Radfahrers durch parkende Fahrzeuge","Eine Verschmutzung des Sensors"],"co":[0,1,2],"ex":["Eine Beschädigung des Sensors kann dazu führen, dass er Radfahrer nicht erkennt. Beobachte beim Abbiegen aufmerksam, ob Radfahrer neben dir fahren.","Parken zwischen deinem Pkw und dem Radfahrer Fahrzeuge, kann der Sensor einen Radfahrer möglicherweise nicht erkennen. Achte darauf, wenn du abbiegst.","Ist der Sensor des Abbiegeassistenten verschmutzt, kann er Radfahrer nicht zuverlässig erkennen. Vergewissere dich beim Abbiegen selbst, dass kein Radfahrer neben dir fährt."],"rn":1098},{"n":"2.7.01-164","t":"Was müssen Sie bei der Nutzung des Aktiven Park-Assistenten beachten?","p":2,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- muss bei entstehenden Gefahren manuell übersteuert werden","- entbindet mich von der Verkehrsbeobachtung","- erkennt während des Parkens zuverlässig alle Hindernisse"],"co":[0],"ex":["Beachte, dass der Aktive Park-Assistent entstehende Gefahren nicht immer erkennt und sei bereit, den Parkvorgang aktiv zu stoppen, um eine Kollision zu verhindern.","Ein Aktiver Park-Assistent entbindet dich nicht von der Verkehrsbeobachtung. Auch mit Aktivem Park-Assistent trägst du die volle Verantwortung.","Der Aktive Park-Assistent kann nicht jedes Hindernis zuverlässig erkennen. Achte selbst auf mögliche Hindernisse."],"rn":1099},{"n":"2.7.01-165","t":"Sie fahren ein Elektrofahrzeug. In welchem Fall kann die Bremswirkung durch Rekuperation eingeschränkt sein?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- mit vollgeladener Batterie","- im Eco-Modus","- unterhalb der Betriebstemperatur der Batterie"],"co":[0,2],"ex":["Wenn die Batterie des Elektrofahrzeugs bereits vollständig aufgeladen ist, kann das Fahrzeug die Energie nicht zurückgewinnen und die Bremswirkung durch Rekuperation ist möglicherweise nicht verfügbar. Stattdessen muss das Fahrzeug auf herkömmliche Bremsen zurückgreifen.","Der Eco-Modus hat keine Auswirkungen auf die Bremswirkung durch Rekuperation.","Wenn die Batterie zu kalt ist, kann die Rekuperation reduziert oder deaktiviert werden, um die Batterie zu schützen. So kann sich die Bremswirkung durch Rekuperation verringern."],"rn":1100},{"n":"2.7.01-166","t":"Ihr Fahrzeug ist mit einer Berganfahrhilfe ausgerüstet. Welchen Vorteil bietet Ihnen dieses Assistenzsystem?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["- das Lösen der Bremse übernehmen","- ein ungewolltes Zurückrollen meines Fahrzeugs verhindern","- alle Räder gleichzeitig antreiben"],"co":[0,1],"ex":["Die Berganfahrhilfe kann dir das Anfahren an einem Berg erleichtern, indem sie das Lösen der Bremsen übernimmt.","Eine Berganfahrhilfe verhindert, dass dein Fahrzeug beim Anfahren an einer Steigung zurückrollt.","Die Berganfahrhilfe kann dich beim Anfahren an einer Steigung unterstützen. Das hat aber keinen Einfluss darauf, welche Räder angetrieben werden. Es geht ausschließlich um das automatische Bedienen der Bremse."],"rn":1101},{"n":"2.7.01-167","t":"Was gilt bei der Nutzung von Fahrerassistenzsystemen für die Längs- und Querführung Ihres Kraftfahrzeugs?","p":3,"c":"2.7.01","ch":"Fahrbetrieb Fahrphysik Fahrtechnik","th":"Technik","o":["Ich muss bei einer Fehlfunktion das Fahrerassistenzsystem unverzüglich übersteuern","Ich kann bei Müdigkeit die Längs- und Querführung dem Fahrerassistenzsystem überlassen","Ich muss die Systemgrenzen des Fahrerassistenzsystems kennen"],"co":[0,2],"ex":["Wenn du eine Fehlfunktion des Fahrerassistenzsystems bemerkst, solltest du so schnell wie möglich übersteuern, um einen möglichen Unfall zu vermeiden.","Bei Müdigkeit darfst du dich nicht auf das Fahrerassistenzsystem verlassen, sondern musst dein Fahrzeug abstellen und eine Pause machen. So riskierst du keine Gefahrensituationen mit anderen Verkehrsteilnehmern, falls das Assistenzsystem fehlerhaft reagiert.","Du solltest dich vor dem Benutzen des Fahrerassistenzsystems mit den Grenzen des Systems auseinandersetzen. So weißt du genau, auf welche Gefahrensituationen du vermehrt achten musst."],"rn":1102},{"n":"2.7.02-020","t":"In welchen Fällen ist eine Bremsprobe unerlässlich?","p":3,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Bei Übernahme eines anderen Fahrzeugs","Nach jedem Motorölwechsel","Nach längerer Standzeit eines Fahrzeugs"],"co":[0,2],"ex":["Wenn du ein fremdes Fahrzeug übernimmst, musst du die Verkehrs- und Betriebssicherheit überprüfen und somit auch die Bremsanlage kontrollieren. Zudem ist es unabdingbar, zu wissen, wie die Bremse reagiert.","Der Motorölwechsel wirkt sich nicht auf die Bremsanlage aus. Somit ist hier auch keine Bremsprobe notwendig.","Hat ein Fahrzeug eine längere Zeit gestanden, dann kann sich Rost an Teilen der Bremsanlage bilden oder diese (z.B. durch einen Marderbiss) beschädigt sein. Das führt zu einer veränderten Bremswirkung. Daher ist hier eine Bremsprobe unerlässlich."],"rn":1103},{"n":"2.7.02-027","t":"Warum muss eine durchgerostete Auspuffanlage unverzüglich repariert werden?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Weil Teile der Auspuffanlage auf die Fahrbahn fallen können","Wegen der Lärmbelästigung","Weil der Motor sonst zu heiß wird"],"co":[0,1],"ex":["Damit keine Auspuffteile auf die Fahrbahn fallen, musst du die Anlage umgehend reparieren, um niemanden zu gefährden.","Ist die Auspuffanlage durchgerostet, dann ist sie weitaus lauter als normal und stellt eine Lärmbelästigung dar.","Die Temperatur des Motors wird durch das Kühlsystem gesteuert und hat nichts mit der Abgasanlage zu tun."],"rn":1104},{"n":"2.7.02-033","t":"Das Bremslicht Ihres Fahrzeugs funktioniert nicht. Was kann die Ursache sein?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Das Leuchtmittel ist defekt","Die entsprechende Sicherung ist defekt","Der Füllstand der Bremsflüssigkeit ist zu gering"],"co":[0,1],"ex":["Wenn das Leuchtmittel defekt ist, funktioniert das Bremslicht des Fahrzeugs nicht. Du kannst dieses selbst austauschen oder durch eine Werkstatt machen lassen.","Eine defekte Sicherung kann der Grund für ein nicht funktionierendes Bremslicht sein. Du solltest diesen Schaden umgehend beheben.","Das hat nichts mit einem defekten Bremslicht zu tun."],"rn":1105},{"n":"2.7.02-034","t":"Wie müssen Sie sich verhalten, wenn nach dem Motorstart die Öldruckkontrollleuchte nicht erlischt?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ich kontrolliere den Motorölstand","Ich fahre bis zum nächsten Ölwechsel weiter","Ich stelle den Motor umgehend ab"],"co":[0,2],"ex":["Ein möglicher Grund für zu wenig Öldruck kann sein, dass zu wenig Öl im Motor ist.","Damit wirst du höchstwahrscheinlich den Motor beschädigen.","Falls sich der nötige Öldruck nicht direkt nach dem Starten des Motors einstellt, sollte man den Motor wieder abstellen, da man ihn sonst beschädigen könnte."],"rn":1106},{"n":"2.7.02-037","t":"Sie sind mit einem Rad heftig gegen eine Bordsteinkante gefahren. Was sollten Sie beachten?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Das Fahrzeug sollte in der Werkstatt überprüft werden","Das Fahrverhalten des Fahrzeugs kann sich verschlechtern","Der Reifen kann schleichend Luft verlieren"],"co":[0,1,2],"ex":["Um mögliche Folgeschäden oder Unfälle zu verhindern, solltest du dein Fahrzeug zur Sicherheit von Fachpersonal in einer Werkstatt überprüfen lassen.","Wenn das Rad bei dem Zusammenstoß Schaden genommen hat, könnte sich dieser negativ auf das Fahrverhalten des Fahrzeugs auswirken.","Ist der Reifen nur gering oder nicht offensichtlich beschädigt, könnte er trotzdem schleichend Luft verlieren."],"rn":1107},{"n":"2.7.02-038","t":"Die Schlussleuchte Ihres Fahrzeugs funktioniert nicht. Was kann die Ursache dafür sein?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Die entsprechende Sicherung ist defekt","Der Fernlichtschalter ist defekt","Das Leuchtmittel ist defekt"],"co":[0,2],"ex":["Wenn die entsprechende Sicherung durchgebrannt ist, führt es dazu, dass die Schlussleuchte nicht mehr funktioniert.","Ist der Fernlichtschalter defekt, funktioniert das Fernlicht nicht. Die Schlussleuchte hat damit aber nichts zu tun.","Die Glühlampe könnte defekt sein und somit die nicht funktionierende Schlussleuchte erklären."],"rn":1108},{"n":"2.7.02-040","t":"Das Bremslicht an Ihrem Fahrzeug ist ohne Funktion. Wie verhalten Sie sich richtig?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ich versuche, die Ursache zu erkennen, und behebe den Fehler selbst","Ich lasse die Bremsflüssigkeit austauschen","Ich lasse das Fahrzeug in einer Werkstatt reparieren"],"co":[0,2],"ex":["Es spricht nichts dagegen, das Bremslicht selbst auszutauschen, wenn es defekt ist. Möglicherweise liegt die Ursache woanders und du benötigst die Hilfe einer Werkstatt.","Es bringt nichts, die Bremsflüssigkeit auszutauschen, wenn das Bremslicht nicht funktioniert.","Du kannst das Bremslicht in einer Werkstatt reparieren oder austauschen lassen."],"rn":1109},{"n":"2.7.02-044","t":"Wie können Sie einen defekten Blinker erkennen?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Die Kontrollleuchte für den Blinker blinkt schneller als üblich","Die Kontrollleuchte für den Blinker leuchtet dauerhaft rot","Durch eine Funktionsprüfung vor Fahrtantritt"],"co":[0,2],"ex":["Wenn die Blinker-Kontrollleuchte während der Fahrt schneller als üblich blinkt, ist möglicherweise ein Blinker defekt. Behebe den Defekt unverzüglich.","Die Kontrollleuchte für den Blinker kann nur grün leuchten.","Prüfe die Funktion des Blinkers vor Fahrtantritt, indem du den Blinkhebel betätigst und das Blinken kontrollierst."],"rn":1110},{"n":"2.7.02-049","t":"Eine Anzeige Ihres flüssigkeitsgekühlten Kraftfahrzeugs informiert Sie über eine zu hohe Motortemperatur. Wie sollten Sie sich jetzt verhalten?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ich halte schnellstmöglich an geeigneter Stelle an","Ich fahre für eine bessere Motorkühlung mit erhöhter Motordrehzahl langsam weiter","Ich fahre in niedrigem Gang bis zur nächsten geplanten Fahrtunterbrechung weiter"],"co":[0],"ex":["Halte so schnell wie möglich an einer geeigneten Stelle an und schalte den Motor aus, um Schäden durch Überhitzung zu vermeiden.","Eine erhöhte Drehzahl bewirkt keine bessere Kühlung. Ganz im Gegenteil: Der Motor wird dadurch noch wärmer. Wenn du mit überhitztem Motor weiterfährst, riskierst du ernsthafte Schäden am Motor. Suche dir eine geeignete Stelle, um anzuhalten.","Fahre möglichst nicht weiter, wenn dein Motor überhitzt ist. Halte an geeigneter Stelle an und schalte den Motor aus."],"rn":1111},{"n":"2.7.02-050","t":"Eine Anzeige Ihres flüssigkeitsgekühlten Fahrzeugs informiert Sie über eine zu hohe Kühlmitteltemperatur. Was kann die Ursache dafür sein?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Der Kühler ist verschmutzt","Das Kühlsystem ist undicht","Der Kühlerlüfter ist ausgefallen"],"co":[0,1,2],"ex":["Ablagerungen und Schmutz können die Wärmeableitung verringern und die Kühlmitteltemperatur erhöhen.","Durch Lecks oder defekte Dichtungen kann Kühlmittel austreten. Wenn du weniger Kühlmittel hast, erwärmt es sich schneller. Kontrolliere dein Fahrzeug auf sichtbare Lecks und lasse sie gegebenenfalls reparieren.","Wenn der Kühlerlüfter defekt ist, steigt die Temperatur schnell an. Prüfe den Kühlerlüfter auf Verstopfungen und lasse ihn, wenn nötig, in einer Werkstatt instand setzen."],"rn":1112},{"n":"2.7.02-107","t":"Die Bremse an Ihrem Pkw wirkt stark einseitig. Welche Folgen können beim Bremsen eintreten?","p":3,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ausfall des Antiblockiersystems (ABS)","Seitliches Ausbrechen des Fahrzeugs","Längerer Bremsweg"],"co":[1,2],"ex":["Das ABS fällt nicht aus, wenn die Bremse des PKW stark einseitig wirkt.","Wenn Bremsen auf der einen Seite stärker bremsen als auf der anderen Seite des Fahrzeuges, wird das Fahrzeug ungleich abgebremst. Durch die stärkere Bremsung auf der einen Seite kann es passieren, dass das Fahrzeug ausbricht.","Durch ungleiche Bremsleistungen wird nicht die optimale Bremsleistung auf allen Rädern erzeugt. Dies wird zu einem längeren Bremsweg führen."],"rn":1113},{"n":"2.7.02-109","t":"Das Bremspedal lässt sich bis zum Fahrzeugboden durchtreten. Erst bei mehrmaliger Betätigung wird der Pedalweg kürzer. Was müssen Sie tun?","p":5,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Fahrzeug sofort abstellen","Bremse reparieren lassen","Bremsflüssigkeit nachfüllen genügt"],"co":[0,1],"ex":["Die Bremsanlage ist nicht funktionstüchtig. Da die Bremsanlage aber zur Verkehrs- und Betriebssicherheit gehört, muss sie während der Fahrt funktionieren. Daher musst du das Fahrzeug umgehend abstellen.","Damit du das Fahrzeug wieder nutzen kannst, musst du die Bremsanlage reparieren lassen.","Das Nachfüllen der Bremsflüssigkeit genügt nicht. Du musst die Bremse reparieren lassen."],"rn":1114},{"n":"2.7.02-117","t":"Die Scheibenwaschanlage funktioniert nicht. Woran kann das liegen?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Sicherung defekt","Kein Wasser im Vorratsbehälter","Düsen verstopft"],"co":[0,1,2],"ex":["Die Pumpe der Scheibenwaschanlage arbeitet mit Strom. Bei einer defekten Sicherung, ist der Stromkreislauf unterbrochen und die Pumpe kann nicht funktionieren.","Ohne Wasser im Vorratsbehälter funktioniert die Scheibenwaschanlage nicht.","Wenn die Düsen der Scheibenwischanlage verstopft sind, funktioniert diese nicht."],"rn":1115},{"n":"2.7.02-118","t":"Aus den Düsen der Scheibenwaschanlage kommt zu wenig Wasser. Was kann die Ursache dafür sein?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Wasserförderpumpe defekt","Zu viel Wasser im Vorratsbehälter","Düsen sind teilweise verstopft"],"co":[0,2],"ex":["Ist die Wasserförderpumpe kaputt, dann pumpt sie kein Wasser und die Scheibenwaschanlage funktioniert nicht oder nicht richtig.","Ein zu voller Vorratsbehälter läuft über, mehr passiert nicht. Es kommt weiterhin Wasser aus den Düsen und die Scheibenwaschanlage funktioniert.","Wenn nur wenig Wasser aus der Scheibenwischanlage kommt, kann die Ursache hierfür in teils verstopften Düsen liegen."],"rn":1116},{"n":"2.7.02-119","t":"Woran kann es liegen, wenn die Scheibenwischer nicht mehr sauber wischen?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Scheibenheizung ist defekt","Scheibenwischerblätter sind abgenutzt","Ölfilm auf der Scheibe"],"co":[1,2],"ex":["Eine defekte Scheibenheizung ist kein Grund dafür, dass Scheibenwischer nicht mehr sauber wischen.","Mit der Zeit nutzen sich die Scheibenwischerblätter ab und funktionieren somit nicht mehr richtig. Dann musst du sie erneuern.","Ein Ölfilm auf der Scheibe hindert die Scheibenwischer am sauberen wischen."],"rn":1117},{"n":"2.7.02-127","t":"Welche Auswirkung hat das Lenken im Stand für Ihr Fahrzeug?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["An der Lauffläche des Reifens können Beschädigungen entstehen","Die Mechanik der Vorderachse wird stark belastet","Die Lenkung wird leichtgängiger"],"co":[0,1],"ex":["Durch das Lenken im Stand werden die Reifen sehr stark abgenutzt. So können Beschädigungen an der Lauffläche entstehen.","Durch das Lenken im Stand wird die Mechanik der Vorderachse stark belastet, da die Lenkung stark gegen das stehende Rad arbeitet. Abhängig vom Fahrzeugtyp werden das Lenkgetriebe und Teile wie die Servopumpe stark belastet und neigen zu schnellerem Verschleiß.","Die Lenkung wird hierdurch nicht leichtgängiger. Das Lenkgetriebe wird hierdurch stark belastet und neigt zu frühzeitigerem Verschleiß."],"rn":1118},{"n":"2.7.02-128","t":"Wann sollten Sie bei Ihrem Pkw die Bremsanlage überprüfen lassen?","p":3,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Wenn die Bremskontrollleuchte während der Fahrt aufleuchtet","Wenn mit meinem Pkw eine Gefahrbremsung durchgeführt wurde","Wenn mein Pkw bei einer Bremsung nicht in der Spur bleibt"],"co":[0,2],"ex":["Das sollte eigentlich nicht passieren und deutet auf eine nicht funktionierende Bremsanlage hin. Das muss sofort überprüft werden.","Eine Gefahrbremsung stellt für eine Bremsanlage nichts Besonderes dar und erfordert keine Überprüfung.","Wenn das Fahrzeug beim Bremsen nach links oder rechts zieht, muss die Bremsanlage überprüft werden."],"rn":1119},{"n":"2.7.02-129","t":"Während der Fahrt merken Sie, dass Ihr Pkw beim Bremsen stark nach links zieht. Wie verhalten Sie sich richtig?","p":3,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["- nur mit geringer Geschwindigkeit weiterfahren","- meinen Pkw umgehend in einer Werkstatt überprüfen lassen","- nur noch mit der Handbremse bremsen"],"co":[0,1],"ex":["Da mit deiner Bremse offensichtlich etwas nicht in Ordnung ist, solltest du Situationen vermeiden, in denen du stark bzw. vollbremsen musst. Idealerweise fährst du sowieso direkt in die Werkstatt.","Wenn sich dein Fahrzeug ungewöhnlich verhält, solltest du immer umgehend eine Werkstatt aufsuchen. Somit kannst du mögliche Unfälle verhindern.","Das Bremsen mit der Handbremse kann dazu führen, dass dein Pkw aus der Spur ausbricht. Dies solltest du während der Fahrt nie machen."],"rn":1120},{"n":"2.7.02-130","t":"Ihr Fahrzeug lässt sich deutlich schwerer lenken als üblich. Wie verhalten Sie sich richtig?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ich achte zunächst bei weiteren Fahrten auf dieses Lenkverhalten","Ich verringere den Reifenfülldruck an der Vorderachse","Ich lasse das Fahrzeug umgehend in einer Werkstatt überprüfen"],"co":[2],"ex":["Eine erneute Fahrt würde zu viel Risiko mit sich bringen. Dadurch würdest du dich und andere Verkehrsteilnehmer in Gefahr bringen.","Da du nicht weißt, warum sich dein Fahrzeug deutlich schwerer lenken lässt, solltest du nicht einfach den Reifenfülldruck verringern. Du solltest dein Auto von Fachpersonal überprüfen lassen.","Wenn sich dein Fahrzeug ungewöhnlich verhält, solltest du immer sofort eine Werkstatt aufsuchen."],"rn":1121},{"n":"2.7.02-131","t":"Sie stellen fest, dass die Reifen an der Vorderachse Ihres Fahrzeugs ungleichmäßig abgenutzt sind. Was sollte überprüft werden?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Die Stoßdämpfer","Die Fahrwerkseinstellungen","Der Reifenfülldruck"],"co":[0,1,2],"ex":["Ein defekter Stoßdämpfer kann dazu führen, dass sich der Reifen schneller abnutzt. Somit kann es sein, dass der Stoßdämpfer am abgefahrenen Reifen wirklich defekt sein könnte und überprüft werden sollte.","Falsche Fahrwerkeinstellungen, wie eine verstelle Achsengeometrie, kann dazu führen, dass sich die Reifen ungleichmäßig abnutzen.","Ist der Reifendruck zu hoch, zu niedrig oder in den Reifen unterschiedlich hoch, kann dies zu ungleichmäßiger Abnutzung führen."],"rn":1122},{"n":"2.7.02-132","t":"Während der Fahrt zieht Ihr Fahrzeug nach rechts. Wie verhalten Sie sich richtig?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ich versuche, das Fahrverhalten durch kräftiges Bremsen zu verbessern","Ich beobachte nur das Lenkverhalten bei weiteren Fahrten","Ich überprüfe den Reifenfülldruck und fahre bei Bedarf in eine Werkstatt"],"co":[2],"ex":["Durch kräftiges Bremsen lässt sich das Fahrverhalten nicht verbessern. Es führt nur zu einer riskanteren Fahrweise und könnte dich und andere Verkehrsteilnehmer gefährden.","Verhält sich dein Auto ungewöhnlich, solltest du dem sofort aktiv nachgehen. Durch weitere Fahrten gefährdest du dich und andere Verkehrsteilnehmer.","Zieht dein Fahrzeug während der Fahrt nach rechts, könnte dies auf einen falschen Reifenfülldruck hinweisen. Überprüfe ihn und fahre gegebenenfalls in eine Werkstatt."],"rn":1123},{"n":"2.7.02-133","t":"Wann müssen Sie Ihren Pkw in einer Werkstatt überprüfen lassen?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["- am Fahrwerk","- an der Lenkanlage","- an der Lackierung"],"co":[0,1],"ex":["Stellst du Mängel an deinem Fahrwerk fest, solltest du umgehend eine Werkstatt aufsuchen. Diese könnten sich sonst negativ auf das Fahrverhalten und insbesondere die Sicherheit deines Pkws auswirken.","Mängel an der Lenkanlage können sehr gefährlich sein. Um dich und andere zu schützen, solltest du diese umgehend von einem Fachpersonal überprüfen lassen.","Hast du Mängel an der Lackierung festgestellt, kannst du diese in einer Werkstatt überprüfen lassen. Allerdings bist du hierzu nicht verpflichtet. Denn durch diese Mängel geht keine direkte Gefahr aus."],"rn":1124},{"n":"2.7.02-134","t":"Die Kontrollleuchte des Blinkers blinkt erheblich schneller als üblich. Was kann die Ursache dafür sein?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ein Leuchtmittel ist defekt","Das Warnblinklicht ist eingeschaltet","Die Sicherung ist defekt"],"co":[0],"ex":["Aufgrund der Art und Weise wie die Blinker vorne und hinten elektrisch miteinander verschalten sind, blinkt das noch intakte Leuchtmittel mit doppelter Geschwindigkeit, wenn das andere Blinkerleuchtmittel defekt ist. Auch die Kontrollleuchte im Cockpit blinkt dann doppelt so schnell. Somit sieht man sogar während der Fahrt, dass ein Blinker ausgefallen ist.","Ist das Warnblinklicht eingeschaltet blinken beide Kontrollleuchten nicht schneller als üblich, sondern im gewohnten Tempo.","Eine defekte Sicherung wird nicht durch schnelleres Blinken der Kontrollleuchte signalisiert. Wenn die Sicherung defekt ist, leuchten die Blinker gar nicht mehr."],"rn":1125},{"n":"2.7.02-135","t":"Wann sollten Sie Ihren Pkw in einer Werkstatt überprüfen lassen?","p":3,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Wenn die Airbag-Kontrollleuchte nach dem Motorstart nicht erlischt","Wenn beim Bremsen dauerhaft Geräusche auftreten","Wenn beim Geradeausfahren ein ständiges Gegenlenken erforderlich ist"],"co":[0,1,2],"ex":["Nach dem Motorstart sollte die Airbag-Kontrollleuchte nach kurzer Zeit erlöschen. Ist dies nicht der Fall, könnte etwas mit dem Airbag oder z. B. der Gurtanlage nicht stimmen. Du solltest das in einer Werkstatt prüfen lassen.","Ein dauerhaftes Geräusch beim Bremsen könnte auf Schäden an der Bremsanlage hinweisen. Das solltest du in einer Werkstatt prüfen lassen.","Im Normalfall fährt dein Auto, auch ohne das Lenkrad festzuhalten, geradeaus. Musst du beim Geradeausfahren allerdings ständig gegenlenken, um die Spur zu halten, solltest du das in einer Werkstatt prüfen lassen."],"rn":1126},{"n":"2.7.02-136","t":"Beim Beschleunigen stellen Sie fest, dass das Lenkrad „flattert“. Wie sollten Sie sich verhalten?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["- Radbefestigung der Vorderräder","- Lenkradbefestigung","- Vorderräder auf Beschädigungen"],"co":[0,2],"ex":["Sind die Vorderräder nicht richtig befestigt, kann dies ebenfalls zu einem Flattern des Lenkrads führen.","Die Lenkradbefestigung kann kein Auslöser für ein Flattern des Lenkrads sein.","Ein Flattern des Lenkrads könnte an beschädigten Vorderrädern liegen. Du solltest überprüfen, ob Schäden zu erkennen sind."],"rn":1127},{"n":"2.7.02-138","t":"Sie fahren bei Dunkelheit innerorts. Entgegenkommende Fahrzeugführer warnen Sie mit der Lichthupe. Was kann das in dieser Situation bedeuten?","p":3,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ich sollte das Fernlicht einschalten","Ich habe vergessen, das Abblendlicht einzuschalten","Mein Fahrzeug blendet entgegenkommende Fahrzeuge"],"co":[1,2],"ex":["Innerorts solltest du nicht mit Fernlicht fahren.","Du könntest vergessen haben, das Abblendlicht einzuschalten. Andere Verkehrsteilnehmer könnten dich warnen.","Falls du das Fernlicht eingeschaltet hast, oder deine Scheinwerfer zu hoch eingestellt sind, könntest du entgegenkommende Fahrzeuge damit blenden."],"rn":1128},{"n":"2.7.02-139","t":"Die Kontrollleuchte der Fahrdynamikregelung (ESC) Ihres Pkws leuchtet dauerhaft. Worauf kann das hinweisen?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["- wurde deaktiviert","- ist defekt","- ist aktiv"],"co":[0,1],"ex":["Wenn du die Fahrdynamikregelung deaktivierst, leuchtet die Kontrollleuchte dafür. Das solltest du nur tun, wenn du einen Grund dafür hast.","Die Kontrollleuchte wird aktiviert, um den Fahrer über einen Defekt in der Fahrdynamikregelung zu informieren. Lass dies in der Werkstatt prüfen.","Wenn die Kontrollleuchte nicht leuchtet, ist das ESC-System aktiv."],"rn":1129},{"n":"2.7.02-140","t":"In Ihrem Pkw ist der Sicherheitsgurt für den Beifahrer defekt. Wie verhalten Sie sich richtig?","p":2,"c":"2.7.02","ch":"Maengelerkennung Lokalisierung Von Stoerungen","th":"Technik","o":["Ich lasse den Sicherheitsgurt reparieren","Ich passe die Gurthöhenverstellung an","Ich lasse keinen Beifahrer mitfahren"],"co":[0,2],"ex":["Du solltest den Sicherheitsgurt unverzüglich reparieren lassen, um die Sicherheit des Beifahrers zu gewährleisten.","Es reicht nicht aus, wenn du die Gurthöhenverstellung anpasst, da ein Funktionieren des Gurtes nicht ausreichend gewährleistet werden kann. Bei einem Unfall könnte dadurch die Sicherheit des Beifahrers gefährdet sein.","Du solltest keinen Beifahrer mitfahren lassen, da ein defekter Sicherheitsgurt bei Unfällen die Sicherheit deines Beifahrers gefährdet."],"rn":1130},{"n":"2.7.03-101","t":"Welche Folge kann eine zu geringe Menge Kühlflüssigkeit im Motor haben?","p":2,"c":"2.7.03","ch":"Verbrennungsmaschine Fluessigkeiten Kraftstoffsystem Elektrische Anlage Zuendung Kraftuebertragung","th":"Technik","o":["- zur Erhöhung des Kraftstoffverbrauchs führen","- zur Überhitzung des Motors führen","- zum Motorschaden führen"],"co":[1,2],"ex":["Die Menge der Kühlflüssigkeit im Motor hat keine Auswirkungen auf den Kraftstoffverbrauch.","Wenn ein Motor nicht ausreichend gekühlt wird, dann überhitzt er sich immer weiter.","Wenn die Kühlflüssigkeit nicht ausreicht, überhitzt der Motor. Das kann schlimmstenfalls zu einem kapitalen Motorschaden führen."],"rn":1131},{"n":"2.7.03-102","t":"Sie fahren mit Schrittgeschwindigkeit in einem Stau. Wann ist der Kupplungsverschleiß an Ihrem Kraftfahrzeug mit manuellem Schaltgetriebe am geringsten?","p":2,"c":"2.7.03","ch":"Verbrennungsmaschine Fluessigkeiten Kraftstoffsystem Elektrische Anlage Zuendung Kraftuebertragung","th":"Technik","o":["- in einem niedrigen Gang möglichst ohne Betätigung der Kupplung fahre","- wiederholt anfahre und anhalte","- langsam mit schleifender Kupplung fahre"],"co":[0],"ex":["Wenn du die Kupplung nicht betätigst, ist der Verschleiß am geringsten.","Bei ständigem Anfahren und Anhalten erhitzen die Kupplungsbeläge und verschleißen.","Eine Kupplung wird am stärksten belastet, wenn du sie schleifen lässt. Bei einer \"schleifender Kupplung\" liegt die Kupplungsscheibe nicht mit vollem Druck an der Schwungscheibe des Motors an. Dadurch erhöht sich u. a. der Verschleiß an den Kupplungsbelägen."],"rn":1132},{"n":"2.7.04-002","t":"Welche Aufgabe hat Motoröl in einem Verbrennungsmotor?","p":2,"c":"2.7.04","ch":"Schmier Und Frostschutzmittel","th":"Technik","o":["- der Kühlung","- der Reinigung","- dem Verschleißschutz"],"co":[0,1,2],"ex":["Motoröl verringert die Reibung der beweglichen Motorteile und sorgt für eine gleichmäßige Verteilung der Wärme im gesamten Motor. Bei zu viel Reibung würde sich ein Motor erheblich mehr erhitzen. Das könnte schlimmstenfalls zu einem Motorschaden führen.","Motoröl ist ein Reinigungsmittel für den Motor. Durch seine klebrige Konsistenz fängt es kleinste Partikel wie Metallspäne und Staub auf, die sich andernfalls im Motor ablagern würden.","Motoröl schmiert viele bewegliche Teile eines Motors. Somit entsteht weniger Reibung und die Motorteile verschleißen weniger schnell."],"rn":1133},{"n":"2.7.04-101","t":"Wie können Sie den Motorölstand kontrollieren?","p":2,"c":"2.7.04","ch":"Schmier Und Frostschutzmittel","th":"Technik","o":["- Fahrerinformationssystem","- Ölmessstab","- Momentanverbrauchsanzeige"],"co":[0,1],"ex":["Manche Autos zeigen den Ölstand im Bordcomputer an.","Bei manchen Autos muss man den Ölstand mit dem Ölmessstab ermitteln.","Für das Motoröl gibt es keine Verbrauchsanzeige."],"rn":1134},{"n":"2.7.05-001","t":"Welche Bedeutung hat das auf dem Reifen angegebene Herstellungsdatum „1217“?","p":2,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["- im 12. Monat (Dezember) des Jahres 2017 hergestellt","- am 1.2.2017 hergestellt","- in der 12. Kalenderwoche des Jahres 2017 hergestellt"],"co":[2],"ex":["Der Reifen wurde in der 12. Woche des Jahres 2017 hergestellt.","Das Herstellungsdatum \"1217\" bedeutet, dass der Reifen in der 12. Kalenderwoche des Jahres 2017 hergestellt wurde.","Die ersten beiden Ziffern stehen für die Kalenderwoche und die letzten beiden für das Jahr, in dem der Reifen hergestellt wurde."],"i":["https://video4.kalaiwa.de/assets/2705001.webp"],"rn":1135},{"n":"2.7.05-002","t":"Wann sollten Sie den Reifendruck überprüfen?","p":2,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Unmittelbar nach jeder Fahrt","Regelmäßig bei kalten Reifen","Unmittelbar nach jedem Reifenwechsel"],"co":[1,2],"ex":["Der Reifendruck muss nicht nach jeder Fahrt geprüft werden.","Die Angaben der Automobilhersteller beziehen sich immer auf Reifen im kalten Zustand. Kalt sind Reifen immer vor jeder Fahrt oder nach einer sehr kurzen Fahrt - durch längere Fahrten werden Reifen zu warm.","Direkt nach dem Wechsel auf Winter- oder Sommerreifen sollte der Reifendruck überprüft werden."],"rn":1136},{"n":"2.7.05-005","t":"Sie fahren mit deutlich zu niedrigem Reifenfülldruck im Straßenverkehr. Was ist die Folge?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Das Lenkverhalten des Fahrzeugs verschlechtert sich erheblich","Der Reifenverschleiß nimmt stark ab","Die Fahrstabilität in Kurven nimmt gefährlich ab"],"co":[0,2],"ex":["Durch einen zu niedrigen Reifenfülldruck hat der Reifen nicht genug Haftung auf der Straße. Dies kann dein Lenkverhalten erheblich beeinträchtigen, da die Richtungsänderung nicht mehr richtig ausgeführt werden kann. Deine Fahrsicherheit wird stark beeinträchtigt.","Das Gegenteil ist der Fall: Ist der Reifenfülldruck zu niedrig, so steigt der Reifenverschleiß. Es droht eine unregelmäßige Abnutzung der Reifen.","Sind deine Reifen nicht ausreichend mit Luft gefüllt, so verringert sich deren Fahrstabilität. Das kann vor allem in Kurven sehr gefährlich werden und dazu führen, dass dein Auto ins Schleudern gerät."],"rn":1137},{"n":"2.7.05-006","t":"Worauf müssen Sie bei der regelmäßigen Überprüfung der Reifen Ihres Fahrzeugs achten?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Auf die Profiltiefe","Auf den Luftdruck","Auf äußere Beschädigungen"],"co":[0,1,2],"ex":["Überprüfe die Profiltiefe deiner Reifen regelmäßig. Abgefahrene Reifen können die Sicherheit gefährden, besonders im Winter.","Verschiedene Ursachen, etwa Beschädigungen oder Temperaturschwankungen, können dazu führen, dass der Reifendruck nicht mehr optimal ist. Prüfe regelmäßig den Luftdruck deiner Reifen, denn deine Sicherheit und die anderer hängt davon ab.","Achte darauf, deine Reifen regelmäßig auf äußere Beschädigungen zu prüfen. Beschädigte Reifen können im Extremfall während der Fahrt platzen und zu gefährlichen Situationen führen."],"rn":1138},{"n":"2.7.05-101","t":"Was ist beim Radwechsel mit einem Wagenheber zu beachten?","p":2,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Der Wagenheber darf nur an den vom Fahrzeughersteller festgelegten Aufnahmepunkten angesetzt werden","Der Wagenheber ist immer mittig an der Längsseite des Fahrzeugs anzubringen","Der Untergrund sollte immer stabil und rutschfest sein"],"co":[0,2],"ex":["Nur so stellst du sicher, dass keine Schäden am Fahrzeug entstehen und der Wagen sicher gehoben wird.","Der Wagenheber ist so anzusetzen, wie es der Fahrzeughersteller festgelegt hat.","Ein stabiler und rutschfester Untergrund ist notwendig, um ein Rad sicher wechseln zu können."],"rn":1139},{"n":"2.7.05-102","t":"Sie müssen ein defektes Rad demontieren. In welcher Reihenfolge sollten Sie vorgehen?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Fahrzeug gegen Wegrollen sichern, Wagenheber ansetzen, Fahrzeug anheben, Radmuttern lösen, Radmuttern herausdrehen","Fahrzeug gegen Wegrollen sichern, Wagenheber ansetzen, Radmuttern lösen, Fahrzeug anheben, Radmuttern herausdrehen","Wagenheber ansetzen, Fahrzeug gegen Wegrollen sichern, Radmuttern lösen, Fahrzeug anheben, Radmuttern herausdrehen"],"co":[1],"ex":["Nachdem du den Wagenheber angesetzt hast, musst du zuerst die Radmuttern lösen und dann das Fahrzeug anheben.","Das ist die richtige Reihenfolge in der du ein defektes Rad demontieren musst.","Du musst im ersten Schritt das Fahrzeug gegen Wegrollen sichern und dann den Wagenheber ansetzen."],"rn":1140},{"n":"2.7.05-103","t":"Was bedeutet das rot gekennzeichnete Symbol auf dem Reifen?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["- unterstützt die Fahreigenschaften auch bei Schnee","- darf nur in Verbindung mit Schneeketten benutzt werden","- ist für winterliche Wetterverhältnisse geeignet"],"co":[0,2],"ex":["Winterreifen mit dem Alpine-Zeichen sind genormten Bremstests auf Schnee unterzogen worden. Sie unterstützen also das Fahren bei Schnee.","Es gibt keine Reifen, die ausschließlich in Verbindung mit Schneeketten genutzt werden dürfen.","Das Alpine-Zeichen kennzeichnet die Eignung von Reifen bei winterlichen Straßenverhältnissen."],"i":["https://video4.kalaiwa.de/assets/2705103.webp"],"rn":1141},{"n":"2.7.05-104","t":"Was müssen Sie beim Fahren mit Winterreifen besonders beachten?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["- höchstens so schnell fahren wie bei der Nutzung von Schneeketten","- die zulässige Höchstgeschwindigkeit für diese Reifen nicht überschreiten","- nicht schneller als 80 km/h fahren"],"co":[1],"ex":["Die zulässige Höchstgeschwindigkeit für Schneeketten liegt bei etwa 40 bis 50 km/h. Winterreifen vertragen in der Regel deutlich höhere Geschwindigkeiten.","Der Geschwindigkeitsindex der Winterreifen darf nicht überschritten werden.","Winterreifen verfügen je nach Angabe über eine individuelle zulässige Höchstgeschwindigkeit. Diese sollte eingehalten werden."],"rn":1142},{"n":"2.7.05-105","t":"Ihr Pkw ist mit Winterreifen ausgerüstet. Welche Bedeutung hat der Geschwindigkeits-Aufkleber „max. 190 km/h“ am Armaturenbrett?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["- gilt nicht bei trockenen Straßenverhältnissen","- gilt nur bei winterlichen Straßenverhältnissen","- darf nicht überschritten werden"],"co":[2],"ex":["Die zugelassene Höchstgeschwindigkeit von Winterreifen gilt unabhängig von Wetter und Straßenverhältnissen.","Egal zu welcher Jahreszeit: Die zugelassene Höchstgeschwindigkeit der Reifen gilt unabhängig von den Straßenverhältnissen.","Die Winterreifen sind für eine Höchstgeschwindigkeit von 190 km/h zugelassen. Somit darf diese Geschwindigkeit nicht überschritten werden."],"rn":1143},{"n":"2.7.05-106","t":"Was ist nach dem Anbau von Winterreifen an Ihrem Pkw zu beachten?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Der Reifenfülldruck ist entsprechend den Herstellervorgaben zu überprüfen","Die zulässige Höchstgeschwindigkeit der Reifen ist zu berücksichtigen","Der Luftdruck sollte 0,5 bar niedriger sein als die Herstellervorgabe für Sommerreifen"],"co":[0,1],"ex":["Die Herstellervorgaben zum Reifendruck können in der Regel im Tankdeckel, im Rahmen der Fahrertür oder in der Bedienungsanleitung eines Fahrzeugs nachgelesen werden.","Die zulässige Höchstgeschwindigkeit der aufgezogenen Winterreifen ist auch die maximale Geschwindigkeit, mit der das jeweilige Fahrzeug gefahren werden sollte.","Der Luftdruck sollte den Herstellervorgaben entsprechen."],"rn":1144},{"n":"2.7.05-107","t":"Diese Kontrollleuchte leuchtet auf. Was kann die Ursache dafür sein?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Ein zu niedriger Reifenfülldruck in einem Reifen","Eine lose Radmutter","Ein kürzlich erfolgter Radwechsel"],"co":[0,2],"ex":["Die Reifendruckkontrollleuchte zeigt üblicherweise einen zu geringen Reifendruck an.","Es gibt keine Kontrollleuchte für lose Radmuttern.","Bei einem Reifenwechsel kann bzgl. Reifenfülldrucksensor viel schiefgehen. Die Sensoren könnten sich noch nicht richtig angepasst haben. Kontrolliere zunächst, ob dir äußerlich etwas am Reifen auffällt. Falls der Reifen optisch in Ordnung ist und die Kontrollleuchte noch immer leuchtet, frage in der Werkstatt nach."],"i":["https://video4.kalaiwa.de/assets/2705107.webp"],"rn":1145},{"n":"2.7.05-108","t":"Welche gesetzlich vorgeschriebene Mindestprofiltiefe müssen alle Reifen Ihres Pkws am Hauptprofil aufweisen?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","na":"Antwort: Die Mindestprofiltiefe beträgt 1,6 mm","e":"Die gesetzlich vorgeschriebene Mindestprofiltiefe der Reifen beträgt 1,6 mm. Das Hauptprofil sind die Rillen in den mittleren Laufflächenbereichen.","rn":1146},{"n":"2.7.05-217","t":"Welche Folgen kann es haben, wenn die Radbefestigungen nach einem Radwechsel nicht nachgezogen werden?","p":3,"c":"2.7.05","ch":"Verwendung Und Wartung Von Reifen","th":"Technik","o":["Das Rad kann sich vom Fahrzeug lösen","Der Reifen kann sich von der Felge lösen","Das Rad kann beschädigt werden"],"co":[0,2],"ex":["Wenn die Radschrauben nach dem Radwechsel (in der Regel nach 50 Kilometern) nicht nachgezogen werden, kann es passieren, dass sich das Rad vom Fahrzeug löst.","Das ist keine mögliche Konsequenz.","Da sich die Schrauben lösen können und das Rad somit locker werden kann, kann es hierdurch beschädigt werden."],"rn":1147},{"n":"2.7.06-101","t":"Was bewirkt ein Antiblockiersystem (ABS)?","p":4,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Beim Bremsen bleibt die Lenkfähigkeit weitgehend erhalten","Auch bei glatter Fahrbahn wird das Fahrzeug bestmöglich gebremst","Aquaplaning wird verhindert"],"co":[0,1],"ex":["Da das ABS ein Blockieren der Reifen verhindert, bleibt die Lenkfähigkeit auch bei starkem Bremsen weitestgehend erhalten.","Das Antiblockiersystem sorgt dafür, dass ein Fahrzeug auch bei glatter Fahrbahn bestmöglich bremsen kann. Bestmöglich bremst man, wenn die Räder nicht blockieren.","Das ABS kann Aquaplaning nicht verhindern."],"rn":1148},{"n":"2.7.06-103","t":"Welche Vorteile bietet ein Antiblockiersystem (ABS)?","p":4,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Kurven können wesentlich schneller durchfahren werden","Beim Bremsen wird das Blockieren der Räder verhindert","Selbst bei starkem Bremsen bleibt die Lenkfähigkeit erhalten"],"co":[1,2],"ex":["Das ABS sorgt nicht dafür, dass man Kurven schneller durchfahren kann.","Wie der Name schon sagt, verhindert das Antiblockiersystem ein Blockieren der Reifen.","Aufgrund des Antiblockiersystems blockieren die Reifen nicht und das Lenkvermögen bleibt trotz starkem Bremsen erhalten."],"rn":1149},{"n":"2.7.06-104","t":"Welche Vorteile bietet ein Antiblockiersystem (ABS)?","p":4,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Beim Bremsen in Kurven wird die Kippgefahr vermindert","Das Durchdrehen der Räder beim Anfahren wird verhindert","Starkes Bremsen und gleichzeitiges Ausweichen ist möglich"],"co":[2],"ex":["Die Kippgefahr in Kurven hängt mit der Geschwindigkeit, der Bodenhaftung und der Schwerpunktlage des Fahrzeuges zusammen. Das Antiblockiersystem hat damit nichts zu tun.","Das System, welches das Durchdrehen der Räder beim Anfahren verhindert, heißt ASR (Antriebs-Schlupf-Regelung).","Das Antiblockiersystem verhindert das Blockieren der Räder beim Bremsen. Somit ist starkes Bremsen und gleichzeitiges Ausweichen möglich."],"rn":1150},{"n":"2.7.06-105","t":"Wann tritt bei einem Anhänger mit Auflaufbremse die Bremswirkung ein?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Beim Auflaufen des Anhängers auf das Zugfahrzeug","Zeitgleich mit der Betätigung des Bremspedals im Zugfahrzeug","Vor Eintreten der Bremswirkung beim Zugfahrzeug, damit der Zug gestreckt bleibt"],"co":[0],"ex":["In diesem Moment tritt die Bremswirkung ein.","Die Bremswirkung tritt erst nach Betätigung der Bremse ein, wenn der Anhänger auf das Zugfahrzeug aufläuft.","Die Bremswirkung tritt nach Auflaufen des Anhängers auf das Zugfahrzeug ein."],"rn":1151},{"n":"2.7.06-110","t":"Was kann aus einem zu späten Ausschalten der Geschwindigkeitsregelanlage (Tempomat) folgen?","p":2,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Eine Überschreitung der zulässigen Höchstgeschwindigkeit","Eine zu hohe Kurvengeschwindigkeit","Ein zu dichtes Auffahren"],"co":[0,1,2],"ex":["Die Geschwindigkeitsregelanlage hält eine Geschwindigkeit, die der Fahrer eingestellt hat. Ändert sich die zulässige Höchstgeschwindigkeit, dann muss dies dementsprechend angepasst werden, damit diese nicht überschritten wird.","Da der Tempomat die Geschwindigkeit nicht an die Kurven anpasst sondern hält, muss er frühzeitig ausgeschaltet werden, damit der Fahrer die Geschwindigkeit rechtzeitig reduzieren kann.","Der Tempomat sorgt dafür, dass eine bestimmte Geschwindigkeit konstant gehalten wird. Den Abstand zum Vordermann regelt er nicht. Achtet man also aufgrund des Tempomats zu wenig auf den Verkehr, so kann dies zu dichterem Auffahren führen."],"rn":1152},{"n":"2.7.06-111","t":"Wobei kann Sie eine Geschwindigkeitsregelanlage (Tempomat) unterstützen?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Beim Einhalten einer gleichbleibenden Geschwindigkeit","Bei einer energiesparenden Fahrweise","Beim Einhalten des Mindestabstands zum vorausfahrenden Fahrzeug"],"co":[0,1],"ex":["Ein Tempomat regelt die Geschwindigkeit automatisch so, dass das Fahrzeug eine vom Fahrer vorgegebene Geschwindigkeit nach Möglichkeit einhält.","Da ein Tempomat dafür sorgt, dass das Fahrzeug eine gleichbleibende Geschwindigkeit hält, fördert dies eine energiesparende Fahrweise.","Hierfür ist die Geschwindigkeitsregelanlage nicht zuständig, sondern die adaptive Geschwindigkeitsregelung."],"rn":1153},{"n":"2.7.06-112","t":"Was sollten Sie bei der Benutzung einer adaptiven Geschwindigkeitsregelanlage beachten?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Auch bei längerer Nutzung des Systems muss ich stets aufmerksam bleiben","Durch die Benutzung von Gas- oder Bremspedal kann das System jederzeit übersteuert werden","Durch starken Regen oder Schneefall kann das System beeinträchtigt werden"],"co":[0,1,2],"ex":["Das System ist unterstützend tätig und ersetzt im keinen Fall einen konzentrierten, vorausschauenden Fahrer. Daher musst du auch bei längeren Fahrten gleichermaßen aufmerksam bleiben.","Das System schätzt selbstständig die Distanz und Geschwindigkeit des vorausfahrenden Fahrzeugs. Wenn hier eine zusätzliche Nutzung von Gas- oder Bremspedal durch den Fahrer stattfindet, kann das System übersteuert werden.","Die Position und die Geschwindigkeit des vorausfahrenden Fahrzeugs werden bei der adaptiven Geschwindigkeitsregelanlage über Radar ermittelt. Dieser kann bei Regen und Schneefall beeinträchtigt sein."],"rn":1154},{"n":"2.7.06-114","t":"Welchen Vorteil bringt die Nutzung einer Geschwindigkeitsregelanlage (Tempomat) für den Fahrer eines Kraftfahrzeugs?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["- entlastet den Fahrer bei der Fahrzeugbedienung","- passt die Geschwindigkeit an die Verkehrsdichte an","- hält eine eingestellte Fahrgeschwindigkeit auf ebener Fahrbahn konstant"],"co":[0,2],"ex":["In einem Fahrzeug mit Tempomat muss ein Fahrer seinen Fuß nicht die ganze Zeit am Gaspedal halten. Das entlastet Fahrer besonders auf langen geraden Strecken.","Bei einem Tempomat lässt sich eine konstante Geschwindigkeit einstellen. Bei hoher Verkehrsdichte eignet sich der Einsatz eines Tempomats weniger. Gas geben und Bremsen muss der Fahrer beispielsweise bei Stop-und-Go-Verkehr immer noch selbst.","Ein Tempomat kontrolliert die Treibstoffzufuhr, sodass ein Kraftfahrzeug auf einer ebenen Fahrbahn konstant mit einer festgelegten Geschwindigkeit fährt."],"rn":1155},{"n":"2.7.06-115","t":"In welcher Situation ist die Nutzung einer Adaptiven Geschwindigkeitsregelanlage (AGR) zweckmäßig?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["- kurvenreichen Straßen","- Autobahnen","- Kraftfahrstraßen"],"co":[1,2],"ex":["Ist die Straße sehr kurvig, solltest du die Adaptive Geschwindigkeitsregelanlage nicht nutzen, weil auf sehr kurvigen Straßen die Erkennung des vorausfahrenden Fahrzeugs fehlerhaft sein kann und so wird die Regelanlage auch keine sinnvolle Hilfe sein.","Beim Fahren auf Autobahnen bietet sich die Nutzung einer Adaptiven Geschwindigkeitsregelanlage an.","Beim Fahren auf Kraftfahrstraßen bietet sich die Nutzung einer Adaptiven Geschwindigkeitsregelanlage an."],"rn":1156},{"n":"2.7.06-116","t":"Wie können Sie eine aktivierte Geschwindigkeitsregelanlage (einen Tempomaten) manuell übersteuern?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Durch Lenken","Durch Beschleunigen","Durch Bremsen"],"co":[1,2],"ex":["Durch Lenken wird die aktivierte Geschwindigkeitsregelanlage nicht beeinflusst, da sich Lenken nicht auf die Geschwindigkeit auswirkt.","Durch Beschleunigen wird die aktivierte Geschwindigkeitsregelanlage übersteuert.","Durch Bremsen wird die aktivierte Geschwindigkeitsregelanlage übersteuert."],"rn":1157},{"n":"2.7.06-117","t":"Welche Funktion übernimmt eine Adaptive Geschwindigkeitsregelanlage (AGR) bei Kraftfahrzeugen?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["- beschleunigt selbstständig bis zu einer vorher eingestellten Geschwindigkeit","- bremst selbstständig, wenn es ein vorausfahrendes Fahrzeug mit geringerer Geschwindigkeit erkannt hat","- hält immer den vorgeschriebenen Sicherheitsabstand zum vorausfahrenden Fahrzeug ein"],"co":[0,1],"ex":["Die AGR regelt das Fahrzeug auf die von dir eingestellte Geschwindigkeit ein, wie ein gewöhnlicher Tempomat.","Die AGR bremst ab, wenn es vorausfahrende Fahrzeuge erkennt. Es bremst nicht ab, wenn es diese nicht erkennen kann, wie z. B. nachts, bei starkem Regen, Nebel usw. Je nachdem, wann das System das vorausfahrende Fahrzeug erkennt, kann es den Sicherheitsabstand einhalten oder nicht.","Kann die AGR das vorausfahrende Fahrzeug z. B. aufgrund der Witterungsverhältnisse nicht rechtzeitig erkennen, kann der Sicherheitsabstand nicht eingehalten werden."],"rn":1158},{"n":"2.7.06-119","t":"Welche Funktion erfüllt der Notbremsassistent?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["- kann bei einer unvermeidbaren Kollision das Verletzungsrisiko reduzieren","- warnt vor der unmittelbaren Gefahr eines Auffahrunfalls","- bremst mein Fahrzeug beim versehentlichen Überfahren der Fahrbahnbegrenzung ab"],"co":[0,1],"ex":["Wenn der Notbremsassistent eine Kollision erkennt, verstärkt er den Bremsdruck bei einer Notbremsung und kann so das Verletzungsrisiko reduzieren.","Der Notbremsassistent überwacht mit Sensoren deine unmittelbare Umgebung und warnt dich vor der Gefahr einer Kollision.","Nein, das kann der Notbremsassistent nicht. Dafür brauchst du einen Spurhalteassistenten."],"rn":1159},{"n":"2.7.06-405","t":"Sie möchten mit einem Fahrzeug mit auflaufgebremstem Anhänger fahren. Was müssen Sie vor Fahrtantritt überprüfen?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["- Verriegelung der Verbindungseinrichtung","- Funktion der Beleuchtungsanlage","- Anbringung des Abreiß-Bremsseils"],"co":[0,1,2],"ex":["Überprüfe die Verriegelung der Verbindungseinrichtung, um zu kontrollieren, dass der Anhänger sicher an das Zugfahrzeug angeschlossen ist.","Kontrolliere die Beleuchtungsanlage um sicherzugehen, dass die Leuchtsignale vom nachfolgenden Verkehr wahrgenommen werden können.","Das Abreiß-Seil ist ein Sicherungsseil für den Anhänger, das reißt, falls man den Anhänger verliert und diesen zum Abbremsen bringt. Du musst vor Fahrtantritt überprüfen, dass dieses angebracht ist."],"rn":1160},{"n":"2.7.06-118-M","t":"Sie nutzen während der Fahrt die Adaptive Geschwindigkeitsregelanlage (AGR). Die Geschwindigkeit ist auf 100 km/h eingestellt. Worauf müssen Sie sich vor der Kurve einstellen?","p":3,"c":"2.7.06","ch":"Bremsanlagen Und Geschwindigkeitsregler","th":"Technik","o":["Durch die AGR kann mein Fahrzeug nun beschleunigt werden","Die AGR fordert mich zur Verringerung der Geschwindigkeit auf","Ich muss die Geschwindigkeit an die Situation anpassen"],"co":[0,2],"ex":["Deine AGR hat das vorausfahrende Fahrzeug erkannt und abgebremst. Da das Fahrzeug nun in der Kurve außer Sichtweite ist, könnte die AGR wieder auf die vorher eingestellten 100 km/h beschleunigen.","Die AGR kann zwar vorausfahrende Fahrzeuge erkennen und ausreichend Abstand zu ihnen halten. Straßenbedingungen wie Kurven oder Straßenschäden kann sie jedoch nicht erkennen. Du musst selbstständig die Geschwindigkeit verringern.","Du hast die Geschwindigkeit der AGR auf 100 km/h eingestellt. Weil das vorausfahrende Fahrzeug jetzt außer Sicht ist, wird die AGR beschleunigen. Stelle eine niedrigere Geschwindigkeit ein, um die Kurve sicher zu befahren."],"v":["https://video4.kalaiwa.de/assets/2706118mv1440.mp4"],"rn":1161},{"n":"2.7.08-001","t":"Warum müssen Sie die Bremsflüssigkeit regelmäßig nach Vorgaben des Fahrzeugherstellers austauschen lassen?","p":3,"c":"2.7.08","ch":"Wartung Von Kraftfahrzeugen Und Rechtzeitige Veranlassung Von Reparaturen","th":"Technik","o":["Damit die Bremsanlage auch bei hoher Belastung funktionstüchtig bleibt","Damit der Wasseranteil in der Bremsflüssigkeit nicht unzulässig hoch wird","Damit die Bauteile der Bremsanlage nicht beschädigt werden"],"co":[0,1,2],"ex":["Durch einen erhöhten Wasseranteil wird die Funktionstüchtigkeit der Bremse eingeschränkt.","Ein Überschreiten des erlaubten Wasseranteils kann man nur durch Austauschen der Bremsflüssigkeit verhindern.","Sobald freie Wassertropfen in der Bremsflüssigkeit sind, können metallische Teile rosten. Auch das Gefrieren von freien Wassertropfen kann zu Beschädigungen führen."],"rn":1162},{"n":"2.8.01-001","t":"Wie lange dauert normalerweise die Probezeit?","p":2,"c":"2.8.01","ch":"Eignung Und Befaehigung Von Kraftfahrern","th":"Eignung Und Befaehigung Von Kraftfahrern","o":["2 Jahre","1 Jahr","3 Jahre"],"co":[0],"ex":["Die Probezeit dauert für jeden, der erstmals den Führerschein macht, 2 Jahre, wenn in dieser Zeit keine schweren Verkehrsverstöße begangen werden.","Die Probezeit dauert 2 Jahre.","Die Probezeit dauert 2 Jahre."],"rn":1163},{"n":"2.8.01-009","t":"Sie befinden sich in der Probezeit und sind bisher nicht auffällig geworden. Welche Folgen können eintreten, wenn Sie an dem Verkehrszeichen „Halt. Vorfahrt gewähren.“ nicht anhalten und dadurch andere Verkehrsteilnehmer gefährden?","p":2,"c":"2.8.01","ch":"Eignung Und Befaehigung Von Kraftfahrern","th":"Eignung Und Befaehigung Von Kraftfahrern","o":["Eintrag in das Fahreignungsregister","Anordnung zur Teilnahme an einem Aufbauseminar für Fahranfänger","Anordnung zum erneuten Ablegen einer theoretischen Fahrerlaubnisprüfung"],"co":[0,1],"ex":["Hält man sich nicht an Verkehrszeichen, dann ist mit einem Eintrag in das Fahreignungsregister zu rechnen.","Jegliche Verstöße können während der Probezeit zu einer Anordnung zur Teilnahme an einem Aufbauseminar führen. So auch das Überfahren des Verkehrszeichens \"Halt. Vorfahrt gewähren.\"","Dies wird nicht angeordnet, wenn man sich nicht an Verkehrszeichen hält."],"rn":1164},{"n":"2.8.01-010","t":"Was soll mit der Teilnahme an einem Aufbauseminar innerhalb der Probezeit erreicht werden?","p":2,"c":"2.8.01","ch":"Eignung Und Befaehigung Von Kraftfahrern","th":"Eignung Und Befaehigung Von Kraftfahrern","o":["Eine Verbesserung der Gefahrenerkennung","Ein Abbau der Punkte im Fahreignungsregister","Eine rücksichtsvollere und risikobewusstere Einstellung zum Straßenverkehr"],"co":[0,2],"ex":["Mithilfe des Aufbauseminars soll eine bessere Gefahrenerkennung erreicht werden.","Ein Abbau der Punkte im Fahrzeugregister ist durch ein Aufbauseminar innerhalb der Probezeit nicht möglich.","Das Aufbauseminar dient unter anderem dem Ziel, ein rücksichtsvolleres und risikobewussteres Verhalten im Straßenverkehr zu erlangen."],"rn":1165},{"n":"2.8.01-013","t":"Ein Fahranfänger hat innerhalb der Probezeit mehrere Verstöße begangen. Die Behörde hat die Teilnahme an einem Aufbauseminar angeordnet. Der Fahranfänger kommt dieser Anordnung nicht nach. Womit muss er jetzt rechnen?","p":2,"c":"2.8.01","ch":"Eignung Und Befaehigung Von Kraftfahrern","th":"Eignung Und Befaehigung Von Kraftfahrern","o":["Mit einem Entzug der Fahrerlaubnis","Mit einer Verlängerung der Probezeit um weitere 3 Jahre","Mit einer Anordnung für ein Fahreignungsseminar"],"co":[0],"ex":["Kommt der Fahranfänger seiner Pflicht, das Aufbauseminar zu besuchen, nicht nach, kann ihm daraufhin die Fahrerlaubnis entzogen werden.","Durch einen A-Verstoß (schwere Zuwiderhandlung) oder zwei B-Verstöße (leichte Zuwiderhandlung) kann die Probezeit um 2 Jahre verlängert werden.","Die Teilnahme an einem Fahreignungsseminar ist freiwillig, hiermit können Fahrer Punkte abbauen."],"rn":1166},{"n":"2.8.01-014","t":"Ein Fahrerlaubnisbewerber übt das praktische Fahren ohne Fahrlehrer im öffentlichen Verkehrsraum. Womit muss er rechnen, wenn er von der Polizei kontrolliert wird?","p":3,"c":"2.8.01","ch":"Eignung Und Befaehigung Von Kraftfahrern","th":"Eignung Und Befaehigung Von Kraftfahrern","o":["Mit einem Strafverfahren","Mit keinen Auswirkungen, wenn ein Inhaber einer Fahrerlaubnis im Fahrzeug mitfährt","Mit einer Überprüfung der Eignung zum Führen von Kraftfahrzeugen"],"co":[0,2],"ex":["Das Fahren ohne Fahrerlaubnis ist strafbar und kann mit einer Geld- oder Freiheitsstrafe bestraft werden.","Das Fahren ohne Fahrerlaubnis hat auch dann Konsequenzen, wenn ein Inhaber einer Fahrerlaubnis im Fahrzeug mitfährt.","Die Polizei kann eine Überprüfung der Fahreignung anordnen. So riskiert der Fahrerlaubnisbewerber, jemals einen Führerschein zu bekommen."],"rn":1167}];
